P.entries["quest:95144"] = {n="Overseas Delivery",s="Fizzgrimble vous demande de transporter une caisse scellée par-delà la mer jusqu’à Friz Frazzlespark, dans les Rives Claires. Son contenu doit rester secret jusqu’à son arrivée au Port de Poudremèche.",h="Fizzgrimble vous demande de transporter une caisse scellée par-delà la mer jusqu’à Friz Frazzlespark, dans...",kw={"fizzgrimble","friz frazzlespark","caisse mystérieuse","livraison outre-mer","port de poudremèche","rives claires","port gentepression"},sec={{t="Une traversée prudente",b="Fizzgrimble vous envoie vers l’est, au Port Gentepression, où un navire assure généralement la traversée. La caisse est destinée à Friz Frazzlespark, au Port de Poudremèche, dans les Rives Claires. Manipulez-la avec précaution ; Fizzgrimble vous déconseille de l’ouvrir ou de la secouer."}},faq={{q="À qui est destiné le colis ?",a="Friz Frazzlespark attend la caisse au Port de Poudremèche, dans les Rives Claires.",al={"qui reçoit la caisse","colis de friz frazzlespark"}},{q="Où dois-je apporter la caisse ?",a="Apportez-la à Friz Frazzlespark, au Port de Poudremèche, dans les Rives Claires.",al={"destination de la caisse","où se trouve le port de poudremèche"}},{q="Où trouver un navire pour traverser la mer ?",a="Fizzgrimble vous conseille de partir vers l’est, au Port Gentepression, où un navire assure généralement une traversée sans danger.",al={"comment traverser","navire du port gentepression"}},{q="Que dois-je faire de la caisse en chemin ?",a="Gardez la caisse fermée et évitez de l’incliner, de la secouer ou de la déplacer brusquement.",al={"comment transporter la caisse","puis-je ouvrir le colis"}},{q="Que contient la caisse ?",a="Friz Frazzlespark vous demande de vous retourner pendant qu’on regarde à l’intérieur, afin de garder le contenu secret.",al={"contenu de la caisse","quelle est la surprise"}}},fp="17,178,18.262.0,23.81.0,30.67.0,40.101.0,43.85.0,25.98.0"}
P.entries["quest:95161"] = {n="Remember That I Love You",s="À Hurlevent, une lettre tachée de sang est destinée à Jeremy Heartweaver, qui vit désormais avec sa mère adoptive, Avette Fellwood, dans le Bois de la Pénombre.",h="À Hurlevent, une lettre tachée de sang est destinée à Jeremy Heartweaver, qui vit désormais avec sa mère...",kw={"avette fellwood","lettre tachée de sang","bois de la pénombre","jeremy heartweaver","remember that i love you","hurlevent","orphelinat de hurlevent"},ang={["faction:Alliance"]="Pour l’Alliance, les souvenirs d’un parent disparu ou tombé au combat, transmis à des orphelins adoptés, témoignent du coût humain des troubles qui agitent le royaume.",["race:Human"]="En tant qu’humain de Hurlevent, vous quittez le cœur relativement sûr du royaume pour rejoindre les hameaux hantés et oubliés du Bois de la Pénombre."},sec={{t="Un message pour un orphelin",b="La guerre, les épreuves et les troubles du royaume ont laissé de nombreux enfants sans famille à l’orphelinat de Hurlevent. Jeremy Heartweaver en faisait partie, jusqu’à ce qu’Avette Fellwood l’adopte et l’emmène vivre dans le Bois de la Pénombre. Là-bas, les bois lugubres sont dangereux et le travail pénible. Les gardiennes pensaient qu’une famille pourrait lui offrir mieux que la vie à l’orphelinat de la ville."},{t="Un sinistre indice",b="La Lettre tachée de sang est destinée à Jeremy Heartweaver, qui est sous la garde d’Avette Fellwood. Sa piste mène au sud, au-delà de la Forêt d’Elwynn et jusque dans le Bois de la Pénombre. Quelle tragédie a suivi Jeremy au-delà des portes de Hurlevent, et pourquoi la lettre porte-t-elle une marque aussi sinistre ?"}},faq={{q="Qui est Jeremy Heartweaver ?",a="Jeremy Heartweaver est un jeune garçon élevé à l’orphelinat de Hurlevent. Avette Fellwood l’a récemment adopté, et il vit et travaille désormais dans le Bois de la Pénombre.",al={"jeremy","qui est jeremy","jeremy l’orphelin"}},{q="Qui est Avette Fellwood ?",a="Avette Fellwood est la mère adoptive de Jeremy et vit dans le Bois de la Pénombre. Les matrons de Hurlevent la considèrent comme une femme douce qui a probablement accueilli Jeremy pour disposer d’une paire de bras supplémentaire pour les tâches quotidiennes.",al={"avette","qui est avette","mère adoptive"}},{q="Qu’est-ce que la Lettre tachée de sang ?",a="La Lettre tachée de sang est destinée à Jeremy Heartweaver et doit être remise à sa tutrice, Avette Fellwood. Elle évoque la violence ou une tragédie.",al={"lettre tachée de sang","la lettre","qu’est-ce que la lettre"}},{q="Où trouver Avette Fellwood ?",a="Avette Fellwood vit dans le Bois de la Pénombre, la forêt sombre située juste au sud de la Forêt d’Elwynn, de l’autre côté de la rivière.",al={"emplacement d’avette fellwood","où se trouve avette","trouver avette"}},{q="Pourquoi Jeremy a-t-il été envoyé dans le Bois de la Pénombre ?",a="Jeremy a été adopté à l’orphelinat de Hurlevent. Ses gardiennes pensaient qu’une famille et un travail honnête dans le dangereux Bois de la Pénombre valaient mieux que la vie d’orphelin à l’orphelinat.",al={"pourquoi le bois de la pénombre","pourquoi jeremy a quitté hurlevent","orphelinat du bois de la pénombre"}},{q="Quelle faction peut accepter cette quête ?",a="Seule l’Alliance peut accepter cette mission. Elle commence à Hurlevent, la capitale des humains, et mène dans le Bois de la Pénombre, territoire de l’Alliance.",al={"est-ce une quête de l’alliance","alliance uniquement","quête de la horde"}}},fp="24,136,23.349.0,12.253.1,26.146.0,23.196.0,33.150.0,32.101.0,32.173.0,34.125.0"}
P.entries["quest:95162"] = {n="Paletusk Harvesting",s="Na'zok vous demande de récolter de la viande de paletusk près de Bolder'ok. Le ranch nourrit les ogres des environs et approvisionne Rog’mar à mesure que la guerre avance.",h="Na'zok vous demande de récolter de la viande de paletusk près de Bolder'ok.",kw={"viande de sanglier","bolder'ok","na'zok","ogres","paletusk","récolte de paletusk","ranch","rog’mar"},sec={{t="De la viande pour le ranch",b="Na'zok a besoin de plus de viande au ranch près de Bolder'ok, où les ogres l'hébergent tant que la viande continue d'arriver. À mesure que la guerre avance, le besoin de nourriture grandit, et les ogres commencent à considérer Na'zok comme leur prochain repas. On vous demande de récolter des morceaux de viande de sanglier pour les ogres affamés et Rog’mar."}},faq={{q="Qui demande de la viande ?",a="Na'zok vous demande de récolter de la viande de sanglier près de Bolder'ok pour les ogres et Rog’mar.",al={"qui a besoin de viande","demande de na'zok","qui est na'zok"}},{q="Pourquoi Na'zok a-t-il besoin de viande ?",a="Le ranch est l'une des rares sources de nourriture de Na'zok, et les ogres l'hébergent tant que la viande continue d'arriver.",al={"pourquoi de la viande","pourquoi récolter du sanglier","ogres affamés"}},{q="Qui est Rog’mar ?",a="Rog’mar est un établissement, pas une personne. Na'zok veut qu'il reste assez de viande pour l'approvisionner.",al={"viande de rog’mar","viande pour rog’mar"}},{q="Où se trouve Na'zok ?",a="Na'zok se trouve près de Bolder'ok.",al={"emplacement de na'zok","où se trouve le ranch"}},{q="Quelle viande faut-il ?",a="Na'zok demande des morceaux de viande de sanglier paletusk.",al={"viande de sanglier","viande de paletusk","morceaux de viande"}}},fp="19,126,18.294.0,23.77.0,30.106.0,15.87.0,16.25.0,20.50.0"}
P.entries["quest:95163"] = {n="Drive Them Back",s="Na'zok vous demande de ramener les jeunes Young Paletusks échappés à sa ferme près de Bolder'ok. Les porcelets ont traversé la rivière et doivent retrouver leurs enclos.",h="Na'zok vous demande de ramener les jeunes Young Paletusks échappés à sa ferme près de Bolder'ok.",kw={"bolder'ok","porcelets échappés","ferme","gorgegut","na'zok","paletusk","porcs","jeunes young paletusks"},sec={{t="Les porcelets échappés",b="À la ferme de Na'zok près de Bolder'ok, il y a plus de porcs en liberté dans la vallée que dans les enclos. Gorgegut n'a pas été un aide idéal, même s'il tient les humains à distance. Certains jeunes Young Paletusks ont traversé la rivière, et ils sont trop petits pour être récoltés dans les champs. Na'zok vous donne un bâton pour les renvoyer dans leurs enclos."}},faq={{q="Pourquoi les porcelets sont-ils sortis de leurs enclos ?",a="Des jeunes Young Paletusks se sont échappés de la ferme de Na'zok en traversant la rivière.",al={"porcelets échappés","porcs en liberté","pourquoi les porcs sont dehors"}},{q="Qui est Gorgegut ?",a="Gorgegut est l'aide de Na'zok à la ferme, mais Na'zok dit qu'il n'est pas vraiment idéal.",al={"gorgegut aide à la ferme","qui est gorgegut","homme de la ferme aux porcs"}},{q="Pourquoi ramener les jeunes Young Paletusks ?",a="Les jeunes Young Paletusks sont trop petits pour être récoltés dans les champs, alors Na'zok veut qu'ils retournent à la ferme.",al={"ramener les porcelets","pourquoi ramener les porcs","jeune young paletusk"}},{q="Où se trouve la ferme de Na'zok ?",a="La ferme de Na'zok se trouve près de Bolder'ok.",al={"emplacement de la ferme de na'zok","ferme près de bolder'ok","où se trouve la ferme aux porcs"}}},fp="15,148,19.313.0,38.70.0,16.78.0,35.106.0,23.32.0"}
P.entries["quest:95183"] = {n="Step One: Rock",s="Hamur, à Bolder'ok, cherche de belles pierres dans la rivière voisine. Apportez-les-lui pour qu'il forge une minuscule arme pour une minuscule créature.",h="Hamur, à Bolder'ok, cherche de belles pierres dans la rivière voisine.",kw={"bolder'ok","belles pierres","hamur","arme d'ogre","rivière","minuscule arme"},sec={{t="La demande de Hamur",b="Hamur, à Bolder'ok, dit que vous êtes trop petit pour manier une bonne arme d'ogre. Il propose de vous en fabriquer une minuscule si vous lui apportez de belles pierres. Il veut des pierres de la rivière qui coule à l'extérieur de Bolder'ok, et seules les meilleures feront l'affaire."}},faq={{q="Qui est Hamur ?",a="Hamur se trouve à Bolder'ok et propose de vous fabriquer une minuscule arme si vous lui apportez de belles pierres.",al={"qui est hamur","qui veut des pierres"}},{q="Où trouver les pierres ?",a="Hamur demande de belles pierres de la rivière qui coule à l'extérieur de Bolder'ok.",al={"emplacement des pierres","où trouver les pierres"}},{q="Pourquoi Hamur veut-il des pierres ?",a="Hamur dit qu'il utilisera les belles pierres pour fabriquer une minuscule arme pour une minuscule créature.",al={"pourquoi des pierres","à quoi servent les pierres"}},{q="Quel genre de pierres Hamur veut-il ?",a="Hamur veut de belles pierres de la rivière qui coule à l'extérieur de Bolder'ok. Il précise que toutes les pierres ne conviennent pas.",al={"belles pierres","quelles pierres"}}},fp="14,119,15.217.0,13.87.0,26.59.0,26.80.0,35.92.0"}
P.entries["quest:95189"] = {n="Écu de Lordaeron",s="Dans les ruines de Capital City, un Écu de Lordaeron usé par le temps témoigne du royaume déchu du Nord. Les reliques de ce genre sont rares, et Dame Dena Kennedy, à Hurlevent, tient à en obtenir une.",h="Dans les ruines de Capital City, un Écu de Lordaeron usé par le temps témoigne du royaume déchu du Nord.",kw={"écu de lordaeron","héraldique","dame dena kennedy","lordaeron","relique","ruines de lordaeron","hurlevent","clairières de tirisfal"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez voir dans l’emblème de Lordaeron une marque de la fondation de l’Alliance. Le récupérer empêche le Fléau et les Réprouvés d’effacer ce symbole.",["race:Human"]="En tant qu’humain, surtout si votre famille est originaire du nord, cet écu évoque le grand royaume qui a jadis dirigé l’Alliance."},sec={{t="Un héritage brisé",b="Le Fléau a laissé les palais et les archives de Lordaeron en ruines, dans l’ombre de Fossoyeuse. Ses fières armoiries ont été détruites ou abandonnées à la décrépitude, si bien qu’il reste peu de reliques portant le blason royal. Un écu usé provenant des ruines du nord préserve une part de l’histoire humaine."},{t="Un refuge dans le sud",b="Après la Troisième guerre, des milliers de réfugiés ont fui Lordaeron vers le sud, en direction du royaume de Hurlevent. Ils emportaient avec eux les souvenirs de leur foyer. À Hurlevent, Dame Dena Kennedy recherche des vestiges de leur patrie. Pour ceux qui ont quitté le nord, un écu comme celui-ci est un lien précieux avec Lordaeron."}},faq={{q="Qu’est-ce que l’Écu de Lordaeron ?",a="L’Écu de Lordaeron est un emblème usé par le temps qui porte la marque officielle du royaume. Il a survécu à la chute de Lordaeron face au Fléau et demeure une relique historique pour les survivants humains.",al={"écu de lordaeron","qu’est-ce que l’écu de lordaeron","objet écu de lordaeron"}},{q="Qui veut l’Écu de Lordaeron ?",a="Dame Dena Kennedy, à Hurlevent, veut l’écu. Elle collectionne et préserve de rares artefacts de Lordaeron.",al={"qui prend l’écu","où remettre l’écu de lordaeron","remise de l’écu"}},{q="Où l’écu a-t-il été trouvé ?",a="L’écu a été récupéré dans les Ruines de Lordaeron, dans les Clairières de Tirisfal. La capitale en ruines se trouve au-dessus de Fossoyeuse, le bastion des Réprouvés.",al={"emplacement de l’écu","écu dans les ruines","où trouver l’écu"}},{q="Pourquoi les artefacts de Lordaeron sont-ils si rares ?",a="Peu d’artefacts de Lordaeron ont survécu à la chute rapide du royaume pendant la Troisième guerre. Le Fléau a massacré ses habitants et ravagé ses domaines, tandis que les Réprouvés se sont établis dans le nord.",al={"pourquoi les reliques de lordaeron sont rares","rareté des artefacts de lordaeron"}},{q="Pourquoi Hurlevent s’intéresse-t-elle aux reliques de Lordaeron ?",a="Hurlevent a accueilli les réfugiés, les chevaliers et les nobles qui fuyaient la dévastation de Lordaeron. Préserver ses reliques rend hommage au royaume déchu du nord et maintient vivant son héritage humain.",al={"pourquoi hurlevent s’y intéresse","reliques de lordaeron à hurlevent"}},{q="Qui est Dame Dena Kennedy ?",a="Dame Dena Kennedy est une noble de Hurlevent qui cherche à sauver des objets de famille et d’autres vestiges historiques de Lordaeron.",al={"dame dena kennedy","qui est dena kennedy"}}},fp="18,193,20.268.0,19.292.0,31.177.0,33.110.0,26.141.0,41.176.0,50.174.0,25.126.0"}
P.entries["quest:95195"] = {n="Insigne ensanglanté",s="Dans les ruines ravagées de Lordaeron, les Insignes ensanglantés portent les anciens emblèmes de l’Alliance des défenseurs tombés au combat. Pendant la Troisième guerre, de nombreuses familles de soldats ont fui vers le sud, jusqu’à Hurlevent.",h="Dans les ruines ravagées de Lordaeron, les Insignes ensanglantés portent les anciens emblèmes de l’Alliance...",kw={"alliance","insigne ensanglanté","lordaeron","marcus jonathan","réfugiés","ruines de lordaeron","hurlevent","troisième guerre"},ang={["class:Paladin"]="En tant que paladin, vous rendez hommage aux frères et sœurs perdus de l’Ordre de la Main d’argent en récupérant les médailles de ceux qui combattirent aux côtés de l’ordre dans la capitale.",["faction:Alliance"]="Pour l’Alliance, rendre ces médailles au Général Marcus Jonathan honore les soldats morts en défendant leur peuple.",["race:Human"]="Pour les humains de l’Alliance, ces insignes rappellent la chute du plus grand royaume humain et rapprochent les réfugiés de Hurlevent de leurs proches tombés au nord."},sec={{t="Médailles des défunts",b="Le prince Arthas revint avec le Fléau et dévasta Lordaeron. Sa grande armée fut submergée, et d’innombrables soldats moururent en défendant la capitale et les terres alentour. Il ne reste de beaucoup de ceux qui combattirent que des armures rouillées et du laiton taché de sang.\n\nLes anciens insignes de l’Alliance appartenaient à ceux qui tinrent tête aux morts-vivants. Piétinées dans la terre et les décombres, ces médailles rappellent la dernière défense de Lordaeron."},{t="Un messager pour les exilés",b="De nombreux survivants fuirent vers le sud, par-delà la mer, et s’installèrent dans la Cité de Hurlevent. L’Alliance et les liens de parenté unissent les deux royaumes humains, et les familles du sud cherchent toujours des nouvelles de leurs proches disparus dans le nord.\n\nLe Général Marcus Jonathan commande la garde de la ville de Hurlevent et recueille les insignes ensanglantés. Il préserve la mémoire des défenseurs et aide leurs familles survivantes à connaître leur sort."}},faq={{q="Que sont les Insignes ensanglantés ?",a="Ce sont des médailles militaires portées par les soldats de Lordaeron qui ont combattu et péri sous la bannière de l’Alliance pendant la Troisième guerre.",al={"objet insigne ensanglanté","que signifie cet insigne","histoire des insignes"}},{q="Où trouve-t-on ces insignes ?",a="On les trouve partout dans les Ruines de Lordaeron, dans les Clairières de Tirisfal, où les défenseurs du royaume livrèrent leur dernier combat contre le Fléau.",al={"où obtenir des insignes","emplacement des insignes","insignes des ruines de lordaeron"}},{q="Pourquoi le Général Marcus Jonathan les veut-il ?",a="Le Général Marcus Jonathan commande la garde de Hurlevent, où vivent désormais de nombreux réfugiés du nord. Il rassemble ces médailles pour honorer les morts de Lordaeron et aider leurs proches encore en vie à tourner la page.",al={"qui est marcus jonathan","pourquoi les remettre à hurlevent","insigne marcus jonathan"}},{q="Pourquoi les soldats de Lordaeron portaient-ils des insignes de l’Alliance ?",a="L’Alliance originelle fut fondée à Lordaeron sous le règne du roi Terenas Menethil II pour vaincre l’ancienne Horde. Lordaeron dirigea l’Alliance de Lordaeron pendant les deuxième et troisième guerres.",al={"emblème de l’alliance de lordaeron","insigne de l’alliance de lordaeron"}},{q="Qu’est-il arrivé aux soldats qui portaient ces médailles ?",a="Ils furent tués pendant la Troisième guerre, lorsque le prince Arthas Menethil trahit le royaume, tua son père et déchaîna le Fléau sur la capitale.",al={"qu’est-ce qui a tué les soldats","sort des soldats de lordaeron"}},{q="Ces soldats ont-ils encore des proches en vie ?",a="Oui. Des milliers de citoyens et de soldats fuirent Lordaeron pendant les invasions de la peste et du Fléau, et trouvèrent refuge dans le royaume de Hurlevent.",al={"réfugiés de lordaeron à hurlevent","qui pleure ces soldats"}}},fp="17,169,20.402.0,26.384.0,32.119.0,32.141.0,43.191.0,55.176.0,52.147.0,51.144.0"}
P.entries["quest:952"] = {n="Bosquet des Anciens",s="Une dépêche urgente vous mène de Darnassus à Sombrivage, où Onu vous attend au Bosquet des Anciens. L’Archidruide Fandral Forteramure vous envoie par-delà la mer porter un message à l’Ancien du savoir, qui vit au sud d’Auberdine.",h="Une dépêche urgente vous mène de Darnassus à Sombrivage, où Onu vous attend au Bosquet des Anciens.",kw={"ancien du savoir","auberdine","cercle cénarien","sombrivage","darnassus","fandral forteramure","bosquet des anciens","onu","la clairière de l'oracle"},ang={["class:Druid"]="En tant que druide, vous transmettez un message entre l’Archidruide de Darnassus et Onu. Leurs tempéraments opposés confrontent l’ardeur de Forteramure à la patience paisible d’un Ancien du savoir.",["faction:Alliance"]="En tant que champion de l’Alliance, vous quittez vos affaires à Darnassus avec une raison de sécuriser les routes des hippogriffes et d’explorer la côte de Sombrivage.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous quittez le berceau protégé de Teldrassil pour les vastes étendues sauvages du continent de Kalimdor. Votre voyage révèle le contraste entre les enseignements de Fandral Forteramure et de Malfurion Hurlorage."},sec={{t="Quitter les frondaisons",b="Après votre aide à la Clairière de l’Oracle, au sommet de Teldrassil, l’Archidruide Fandral Forteramure vous confie une autre tâche. Il vous envoie à Sombrivage avec une dépêche urgente pour Onu. Depuis Darnassus, vous pouvez prendre un vol à dos d’hippogriffe."},{t="La patience à l’épreuve",b="Au sud d’Auberdine, vous atteignez le Bosquet des Anciens et remettez le message à Onu. L’imposant Ancien du savoir l’accepte en silence et fait remarquer l’impatience de Forteramure. Onu et les anciens gardiens de la forêt croient que toute chose arrive en son temps. Shan'do Malfurion Hurlorage incarnait cette sagesse patiente, qui fait défaut à Forteramure."}},faq={{q="Qui donne la quête Bosquet des Anciens ?",a="L’Archidruide Fandral Forteramure vous envoie depuis l’Enclave cénarienne, à Darnassus, après que vous avez accompli sa tâche précédente à la Clairière de l’Oracle.",al={"donneur de quête bosquet des anciens","qui donne bosquet des anciens","quête fandral forteramure"}},{q="Où se trouve le Bosquet des Anciens ?",a="Le Bosquet des Anciens se trouve sur le continent, à Sombrivage, juste au sud du port côtier d’Auberdine.",al={"emplacement bosquet des anciens","où se trouve bosquet des anciens","emplacement onu"}},{q="Qui est Onu ?",a="Onu est un Ancien du savoir sage et vénérable de Sombrivage. Il veille sur la sagesse de la nature et la consigne, et reçoit la correspondance des dirigeants druidiques de Darnassus.",al={"qui est onu","onu sombrivage","onu ancien du savoir"}},{q="Comment rejoindre Sombrivage depuis Teldrassil ?",a="Depuis Darnassus, rendez-vous au village de Rut'theran et prenez un hippogriffe au-dessus de l’eau jusqu’à Auberdine, le port de Sombrivage.",al={"comment aller à sombrivage","voyage vers auberdine","hippogriffe vers sombrivage"}},{q="Pourquoi Onu mentionne-t-il Shan'do Hurlorage ?",a="Après avoir reçu le message, Onu remarque l’impatience fébrile de l’Archidruide Forteramure. Il dit que la forêt suit son propre rythme, avec une patience que Shan'do Malfurion Hurlorage comprenait et respectait.",al={"commentaire onu malfurion","référence à shan'do stormrage","pourquoi mentionner shan'do"}},{q="Quelles quêtes précèdent celle-ci ?",a="Cette quête conclut une courte suite de trois quêtes. Celle-ci commence avec Enchanted Glade, se poursuit avec Teldrassil, puis vous mène à Sombrivage.",al={"prérequis bosquet des anciens","suite de quêtes bosquet des anciens","quêtes avant onu"}}},fx={["00893f03"]={q="Pourquoi l'archidruide Fandral Forteramure veut-il que ce message soit transmis à Onu ?",a="Fandral Forteramure est impatient de maintenir une communication étroite avec les anciens protecteurs à travers la mer, à Kalimdor. Onu, un Ancien du Savoir enraciné à Sombrivage, attendait des nouvelles de l'archidruide concernant les affaires sur Teldrassil. Maintenant que Fandral a reçu les derniers rapports de la Clairière de l'Oracle, il est impatient de transmettre ses conclusions et ses instructions sans délai, faisant avancer ses plans pour les elfes de la nuit.",al={"pourquoi envoyer un message à onu","motivation de fandral le bosquet des anciens","pourquoi fandral a-t-il besoin que cela soit livré"}},["658e120a"]={q="Pourquoi Fandral Forteramure vous choisit-il pour transmettre son message ?",a="Vous ayant vu porter des nouvelles de la Clairière de l'Oracle jusqu'à Darnassus, Fandral considère que vous êtes déjà capable d'effectuer des courses sensibles sur de longues distances. Plutôt que de détourner des émissaires cénariens ou des sentinelles expérimentés de leurs devoirs, il engage simplement un messager éprouvé pour transporter sa missive jusqu'à Sombrivage.",al={"pourquoi moi message de fandral","pourquoi envoyer le joueur vers onu","pourquoi ne pas envoyer une sentinelle"}}},fp="21,226,18.230.0,22.341.0,43.135.0,43.109.0,11.160.0,43.126.0,39.192.0,33.143.0"}
P.entries["quest:95204"] = {n="Écu de Lordaeron",s="Les Réprouvés préservent ce qu’il reste de Lordaeron à Fossoyeuse. Un Crest of Lordaeron patiné porte l’emblème du royaume déchu, rare lien avec son passé.",h="Les Réprouvés préservent ce qu’il reste de Lordaeron à Fossoyeuse.",kw={"crest of lordaeron","réprouvés","lordaeron","oran snakewrithe","relique","fossoyeuse"},ang={["faction:Horde"]="Vous aidez les archivistes réprouvés de Fossoyeuse à préserver l’héritage de Lordaeron au milieu des ruines laissées par le Fléau.",["race:Undead"]="En tant qu’ancien citoyen de Lordaeron, vous chérissez les reliques du royaume déchu, rares vestiges de votre passé et de votre héritage."},sec={{t="Un symbole rescapé du royaume déchu",b="La Troisième guerre a brisé Lordaeron. Les cendres, les ruines et la désolation du Fléau ont englouti une grande partie du royaume, laissant peu d’emblèmes derrière elles. Pour les Réprouvés sous les ruines de Capital City, ceux qui ont survécu sont de précieux liens avec la civilisation à laquelle ils appartenaient autrefois."},{t="Préserver l’héritage des Réprouvés",b="Le Crest of Lordaeron patiné est rapporté du vaste monde à Oran Snakewrithe, à Fossoyeuse. Oran teste le métal en le mordant, puis confirme qu’il est authentique et en grande partie intact. Pour Oran et les archivistes réprouvés, chaque pièce retrouvée aide à reconstituer une histoire que le Fléau a cherché à effacer."}},faq={{q="Qu’est-ce que le Crest of Lordaeron ?",a="Le Crest of Lordaeron est un emblème patiné de l’ancien royaume humain. Peu de reliques matérielles ont survécu à la destruction du Fléau ; il préserve donc une rare part du passé de Lordaeron.",al={"qu’est-ce que le crest of lordaeron","quête du crest of lordaeron","objet crest"}},{q="Qui veut le blason à Fossoyeuse ?",a="Oran Snakewrithe, à Fossoyeuse, reçoit le blason. Oran inspecte et protège les artefacts liés à l’ancien royaume.",al={"qui reçoit le crest","où remettre le crest","remettre le crest à fossoyeuse"}},{q="Pourquoi Oran Snakewrithe mord-il le blason ?",a="Oran Snakewrithe mord le blason pour tester son métal et vérifier son authenticité. Oran confirme qu’il s’agit d’une relique de Lordaeron en grande partie intacte.",al={"pourquoi mordre le crest","oran mord le crest"}},{q="Pourquoi les Réprouvés tiennent-ils aux reliques de Lordaeron ?",a="Les Réprouvés sont les restes mort-vivants de l’ancien peuple de Lordaeron. Les reliques de leur patrie ravagée restent des liens tangibles avec leur histoire et leur identité.",al={"pourquoi les réprouvés tiennent à lordaeron","reliques des réprouvés"}},{q="Qu’adviendra-t-il du blason une fois remis ?",a="Oran Snakewrithe prend le blason sous sa garde et le met en lieu sûr. Il aide les Réprouvés à préserver et à se rappeler l’héritage de leur royaume.",al={"que devient le crest","préserver le crest"}},{q="Les reliques de Lordaeron encore présentes sont-elles rares ?",a="Les emblèmes et les reliques ayant survécu à la Troisième guerre sont extrêmement rares. L’invasion du Fléau a laissé peu de traces matérielles de Lordaeron.",al={"le crest est-il rare","combien reste-t-il de crests"}}},fp="18,148,40.264.0,28.278.0,31.183.0,33.113.0,41.137.0,46.153.0,52.134.0,45.150.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="À la Ferme des Distillambre, les soigneurs préparent des béliers pour l’expédition de l’Alliance en Alterac. Il leur faut des peaux intactes de léopard des montagnes pour confectionner des selles chaudes, afin que montures et cavaliers puissent affronter le gel mordant des montagnes du nord.",h="À la Ferme des Distillambre, les soigneurs préparent des béliers pour l’expédition de l’Alliance en Alterac.",kw={"alterac","expédition d’alterac","ferme des distillambre","dun morogh","peaux de léopard","never saddle on quality","peaux intactes de léopard","béliers","selles"},ang={["class:Hunter"]="Il faut des pisteurs et des chasseurs expérimentés pour traquer les plus féroces léopards des montagnes de Dun Morogh et obtenir des peaux intactes.",["faction:Alliance"]="La Ferme des Distillambre élève des béliers pour renforcer les forces de l’Alliance dans les hauteurs glaciales d’Alterac.",["race:Dwarf"]="Les robustes béliers des montagnes de Dun Morogh sont des montures naines emblématiques. Leurs éleveurs de la Ferme des Distillambre refusent de les équiper avec du matériel de qualité inférieure."},sec={{t="Préparer l’expédition",b="Les soigneurs de la Ferme des Distillambre, à Dun Morogh, préparent de robustes béliers des montagnes pour Alterac. Mais le travail est au point mort : ils manquent du matériau nécessaire pour confectionner des selles résistantes au froid pour les béliers."},{t="De la chaleur pour les hauts cols",b="Les montures de l’expédition ont besoin d’une épaisse isolation pour résister au gel des montagnes d’Alterac. Des chasseurs sont envoyés vers les escarpements orientaux pour traquer les plus grands et les plus féroces léopards des montagnes de Dun Morogh et rapporter des peaux intactes. Les forces de l’Alliance ont besoin d’un équipement capable de résister aux hauts cols."}},faq={{q="Qu’est-ce que Never Saddle on Quality ?",a="À la Ferme des Distillambre, à Dun Morogh, un éleveur a besoin de peaux de léopard de grande qualité pour confectionner des selles chaudes et robustes. Elles sont destinées à une harde de béliers que l’on prépare pour renforcer l’expédition d’Alterac.",al={"quelle est cette quête","quête never saddle on quality","qu’est-ce que never saddle on quality"}},{q="Pourquoi faut-il des peaux de léopard ?",a="Les peaux de léopard fournissent la fourrure épaisse nécessaire à la confection de selles durables et chaudes pour les montures de l’expédition. Cette isolation protège cavaliers et bêtes du froid mordant des montagnes d’Alterac.",al={"pourquoi des peaux de léopard","à quoi servent les peaux","pourquoi des peaux intactes"}},{q="Où les béliers sont-ils envoyés ?",a="Les montures sont destinées aux forces de l’Alliance engagées dans l’expédition d’Alterac. Des béliers bien équipés sont un soutien essentiel face aux intempéries et aux opérations qui se poursuivent dans les hauts cols.",al={"où vont les béliers","qui reçoit les béliers","renforts pour alterac"}},{q="Quel est le rôle de la Ferme des Distillambre ?",a="La Ferme des Distillambre se trouve à Dun Morogh, à l’est de Kharanos. C’est le principal lieu d’élevage et de dressage des béliers des montagnes nains.",al={"où se trouve la ferme des distillambre","emplacement de la ferme des distillambre"}},{q="Où les léopards vivent-ils ?",a="Les léopards parcourent les crêtes enneigées et les escarpements orientaux de Dun Morogh, à l’est de la Ferme des Distillambre. Les chasseurs y recherchent les plus grandes bêtes pour obtenir leurs peaux intactes.",al={"où trouver des léopards","où sont les léopards à dun morogh"}},{q="Pourquoi est-il si important de se protéger du froid pendant l’expédition ?",a="Le royaume d’Alterac et ses sommets sont glacials et balayés par les vents. Sans des matériaux épais et de grande qualité pour les selles, montures et cavaliers risquent les engelures et l’épuisement dans les montagnes.",al={"fait-il froid à alterac","pourquoi des selles chaudes"}}},fp="23,229,23.201.0,26.290.0,32.198.0,29.181.0,30.175.0,37.125.0,27.157.0,63.166.0"}
P.entries["quest:95213"] = {n="Poudre explosive volée",s="Près de la Carrière de Gol'Bolar, un tonnelet vide de poudre explosive dangereuse a été découvert parmi des troggs. Le rapporter au maître de la carrière Thesten révèle une faille dans la sécurité de la carrière et de ses réserves d'explosifs.",h="Près de la Carrière de Gol'Bolar, un tonnelet vide de poudre explosive dangereuse a été découvert parmi des...",kw={"poudre explosive","dun morogh","tonnelet de poudre vide","carrière de gol'bolar","tonnelet de poudre","maître de la carrière thesten","poudre explosive dérobée","thesten","troggs"},ang={["faction:Alliance"]="Pour l'Alliance, protéger les lignes d'approvisionnement et les avant-postes miniers de Dun Morogh contre les incursions des troggs est essentiel aux opérations dans tout Khaz Modan.",["profession:Engineering"]="La poudre explosive est instable et dangereuse. En tant qu'ingénieur, vous savez quels ravages les troggs pourraient causer avec des explosifs utilisés sans autorisation.",["profession:Mining"]="Les activités de la carrière reposent sur des démolitions contrôlées pour extraire la pierre. Des tonnelets de poudre manquants signalent un grave danger dans les fosses d'extraction.",["race:Dwarf"]="La Carrière de Gol'Bolar fournit à Forgefer de la pierre et des ressources essentielles. Pour un nain, la sécurité de ses explosifs miniers est une préoccupation urgente."},sec={{t="Une découverte dangereuse",b="À la Carrière de Gol'Bolar, un avertissement gravé sur un tonnelet vide révèle que de la poudre explosive dangereuse a échappé aux mains autorisées. Ces explosifs sont réservés aux travaux d'extraction contrôlés, avec l'approbation directe du maître de la carrière. Le tonnelet a été découvert parmi des troggs hostiles, signe d'une menace qui dépasse les problèmes habituels des mineurs."},{t="L'alarme du maître de la carrière",b="Quand le tonnelet vide parvient au maître de la carrière Thesten, les pires craintes des surveillants nains se confirment. Thesten pâlit : la poudre explosive a disparu, et les troggs souterrains qui pullulent dans la région l'ont manipulée. Les dirigeants de la carrière doivent maintenant découvrir ce que ces créatures comptent faire sauter ensuite."}},faq={{q="Que raconte Poudre explosive dérobée ?",a="Poudre explosive dérobée concerne un tonnelet vide portant des avertissements de danger, découvert parmi des troggs près de la Carrière de Gol'Bolar. Il alerte le maître de la carrière Thesten du vol de fournitures minières explosives.",al={"que raconte poudre explosive dérobée","quête du tonnelet de poudre","histoire du tonnelet de poudre vide"}},{q="À qui remettre le tonnelet vide ?",a="Apportez le tonnelet vide directement au maître de la carrière Thesten, qui supervise les opérations à la Carrière de Gol'Bolar, dans Dun Morogh.",al={"où apporter le tonnelet","qui est thesten","emplacement du maître de la carrière"}},{q="Pourquoi la poudre explosive dérobée est-elle dangereuse ?",a="Le tonnelet porte des avertissements exigeant l'autorisation du maître de la carrière et contenait de la poudre explosive dangereuse. Des troggs munis d'explosifs puissants menacent la carrière et les villages voisins.",al={"pourquoi la poudre est-elle dangereuse","troggs avec des explosifs","pourquoi les troggs ont-ils de la poudre"}},{q="Qu'est-ce que la Carrière de Gol'Bolar ?",a="La Carrière de Gol'Bolar est un site d'extraction nain de Dun Morogh, où l'on extrait la pierre et les minerais destinés à Forgefer.",al={"où se trouve gol'bolar","emplacement de la carrière","gol'bolar dun morogh"}},{q="Pourquoi le maître de la carrière Thesten pâlit-il ?",a="À la vue du tonnelet vide, le maître de la carrière Thesten pâlit et demande où il a été trouvé. Il sait que son dangereux contenu est déjà tombé entre les mains des troggs hostiles.",al={"pourquoi thesten pâlit","réaction de thesten","que dit thesten"}},{q="Que font les troggs près de la Carrière de Gol'Bolar ?",a="Les troggs ont envahi les profondeurs et les abords de la Carrière de Gol'Bolar. Ils perturbent le travail des mineurs nains et récupèrent du matériel ainsi que de la poudre explosive sur le site d'extraction.",al={"y a-t-il des troggs dans la carrière","invasion de troggs à dun morogh","pourquoi les troggs prennent-ils la poudre"}}},fp="22,191,21.331.0,24.279.1,31.192.0,40.119.0,44.169.0,25.107.0,40.168.0,44.164.0"}
P.entries["quest:95214"] = {n="Poudre explosive volée",s="À la Carrière de Gol'Bolar, Stolen Blasting Powder a pris la direction de l'est avec les troggs. Le maître de carrière Thesten a besoin d'aide pour récupérer les munitions disparues avant que ces brutes ne les fassent exploser par accident.",h="À la Carrière de Gol'Bolar, Stolen Blasting Powder a pris la direction de l'est avec les troggs.",kw={"poudre explosive","dun morogh","explosifs","carrière de gol'bolar","forgefer","roi magni","maître de carrière thesten","thesten","troggs"},ang={["faction:Alliance"]="Les lignes d'approvisionnement et les carrières de Dun Morogh comptent pour la place forte montagneuse de l'Alliance. Garder les munitions dangereuses protège le Haut Siège, tout proche, à Forgefer.",["profession:Mining"]="La poudre explosive dégage la roche et ouvre des filons dans les excavations profondes, mais sa manipulation exige de la discipline. Perdre des barils entiers aux mains de troggs sauvages est le cauchemar de tout maître de carrière.",["race:Dwarf"]="La Carrière de Gol'Bolar fournit Forgefer en pierre et soutient ses travaux d'excavation. Laisser les troggs transformer des explosifs miniers en armes si près du Roi Magni est un échec humiliant pour un superviseur nain."},sec={{t="Un stock manquant",b="À la Carrière de Gol'Bolar, dans Dun Morogh, les nains utilisent de lourdes charges explosives pour briser la pierre et ouvrir de profonds filons. Mais des troggs primitifs des escarpements voisins ont volé une importante cargaison de poudre de haute qualité. Le maître de carrière Thesten a besoin de bras compétents avant que la bande ne provoque une détonation accidentelle."},{t="Un baril de poudre dans les escarpements",b="Le baril manquant contient assez de puissance pour transformer la grande salle du trône du Roi Magni Barbe-de-Bronze en une cour à ciel ouvert. Les troggs ont emporté la poudre vers l'est, dans leurs campements rudimentaires au pied des collines. Livrées à elles-mêmes, ces brutes pourraient bientôt découvrir le feu ou frapper la pierre contre une étincelle."},{t="Une résolution discrète",b="Une fois les charges volées récupérées auprès des troggs et ramenées au dépôt de la carrière, le maître de carrière Thesten peut souffler. Il vous récompense, puis vous demande discrètement de ne parler de l'incident à personne."}},faq={{q="Qui est le maître de carrière Thesten ?",a="Le maître de carrière Thesten supervise les excavations à la Carrière de Gol'Bolar, dans Dun Morogh. Après la disparition, sous sa garde, d'un important stock de poudre explosive industrielle, il a besoin d'aide pour le récupérer.",al={"qui est thesten","maître de carrière thesten","qui donne cette quête"}},{q="Où trouver la poudre explosive volée ?",a="Les troggs ont emporté la poudre dans les escarpements et les tanières juste à l'est de la Carrière de Gol'Bolar. Vous devez récupérer les barils et les sacs instables avant qu'un désastre ne survienne.",al={"où trouver la poudre explosive volée","emplacement des troggs","emplacement de la poudre"}},{q="Pourquoi les troggs ont-ils volé la poudre explosive ?",a="L'entrée ne donne aucune raison au vol des troggs. Ils ont récupéré les barils de poudre auprès des ouvriers de la carrière, et le maître de carrière Thesten craint qu'ils ne mettent le feu aux explosifs en faisant des expériences maladroites.",al={"pourquoi les troggs volent de la poudre","que veulent les troggs avec la poudre"}},{q="Quelle est la puissance de la poudre explosive volée ?",a="Le maître de carrière Thesten affirme que le baril manquant pourrait transformer la salle du trône du Roi Magni en une cour à ciel ouvert. S'il explose dans la carrière fermée ou dans les cavernes, ses effets seraient dévastateurs.",al={"puissance de la poudre","poudre et salle du trône de magni","la poudre est-elle dangereuse"}},{q="Pourquoi le maître de carrière Thesten veut-il garder l'incident secret ?",a="Quand vous lui rapportez la poudre, le maître de carrière Thesten vous paie et vous demande de garder l'incident secret. Il ne donne aucune raison, mais il préférerait dissimuler la perte d'une si grande quantité d'explosifs aux mains des troggs.",al={"pourquoi garder le secret","secret de thesten","ne pas parler de l'incident"}},{q="Qu'est-ce que la Carrière de Gol'Bolar ?",a="La Carrière de Gol'Bolar est un site d'extraction nain dans l'est de Dun Morogh. On y extrait la pierre destinée à la construction et à l'ingénierie dans tout le royaume, tandis que des troggs sortent des rochers jusque dans ses profondes excavations.",al={"qu'est-ce que gol'bolar","carrière de gol'bolar","où se trouve gol'bolar"}}},fp="22,183,19.282.0,25.250.0,16.202.1,28.188.0,46.166.0,45.194.0,44.189.0,59.199.0,25.191.0"}
P.entries["quest:95216"] = {n="The New Plague",s="À Fossoyeuse, Theodore Griffs étudie les rapports sur une créature mortelle dans les ruines au-dessus de la ville. Son venin consume même la chair des morts-vivants, et il cherche à comprendre le fonctionnement de ses toxines.",h="À Fossoyeuse, Theodore Griffs étudie les rapports sur une créature mortelle dans les ruines au-dessus de la...",kw={"l'apothicarium","ichor","ruines de lordaeron","the new plague","theodore griffs","souche toxique","fossoyeuse","witherfang"},ang={["faction:Horde"]="La Horde accepte les Réprouvés comme alliés dans les Royaumes de l’est, mais les sinistres expériences de l’Apothicarium inquiètent souvent ses membres les plus honorables.",["race:Undead"]="La Société royale des apothicaires recherche des toxines capables de nuire aux vivants comme aux morts. Elle poursuit la suprématie des Réprouvés et la protection de leur jeune nation."},sec={{t="L’ambition de l’apothicaire",b="La Société royale des apothicaires rassemble des substances dangereuses venues de tout Azeroth. Theodore Griffs est l’un de ses chercheurs. Il traque des bêtes étranges et des contaminants mortels pour faire progresser l’alchimie des Réprouvés. À présent, des rumeurs évoquent une créature venimeuse dans les pierres brisées au-dessus de la ville. Griffs vous envoie en rapporter un échantillon avant que l’occasion ne soit perdue."},{t="Une toxine qui dissout la chair",b="Witherfang est un arthropode venimeux qui rôde dans les ruines de Lordaeron, à la surface. Son venin décompose aussi bien les tissus vivants que la chair morte et préservée. Griffs veut comprendre comment il contourne la résistance de la chair morte. Ce savoir pourrait aider à perfectionner les armes biologiques et à protéger le royaume des Réprouvés."},{t="Rétroconcevoir l’ichor",b="Theodore Griffs est frustré que Witherfang ait été tué au lieu d’être capturé vivant. L’ichor recueilli lui fournit tout de même assez de matière pour l’étudier. En décomposant les fluides corporels de la créature, il espère comprendre le fonctionnement de son venin et enrichir les connaissances chimiques grandissantes de Fossoyeuse."}},faq={{q="Qui est Theodore Griffs ?",a="Theodore Griffs est un chercheur de la Société royale des apothicaires, à l’Apothicarium de Fossoyeuse. Il étudie des toxines puissantes et d’étranges spécimens pour créer des composés destinés aux Réprouvés. Il tolère difficilement ceux qui ne savent pas apprécier un travail alchimique minutieux.",al={"qui fournit the new plague","theodore griffs","qui est theodore griffs"}},{q="Qu’est-ce que Witherfang ?",a="Witherfang est un arthropode venimeux qui vit dans les Ruines de Lordaeron, au-dessus de Fossoyeuse. Sa toxine peut dissoudre même la chair résistante des morts-vivants.",al={"qu’est-ce que witherfang","où se trouve witherfang","arthropode des ruines de lordaeron"}},{q="Pourquoi Theodore Griffs veut-il le venin de Witherfang ?",a="Theodore Griffs veut comprendre comment le venin de Witherfang ronge la chair des morts-vivants. Il espère en reproduire les effets pour l’arsenal alchimique des Réprouvés.",al={"que veut theodore avec witherfang","pourquoi recueillir la souche hautement toxique"}},{q="Pourquoi Theodore Griffs est-il contrarié à votre retour ?",a="Theodore Griffs espérait que vous garderiez Witherfang intact ou que vous recueilleriez son venin avec soin. Il est contrarié qu’il ait été tué, mais il a récupéré assez d’ichor dans ses restes pour l’étudier.",al={"pourquoi theodore était-il en colère","ai-je gâché l’échantillon"}},{q="Quel est le rôle de l’Apothicarium ?",a="L’Apothicarium est le centre de recherche de la Société royale des apothicaires, sous Lordaeron. Ses membres y testent des souches dangereuses, fabriquent des armes alchimiques et expérimentent sur d’étranges créatures. C’est le quartier le plus vital de Fossoyeuse.",al={"rôle de l’apothicarium","pourquoi l’apothicarium est-il important"}},{q="Comment Theodore pense-t-il que les souches virulentes se transmettent le mieux ?",a="Theodore Griffs pense que le moyen le plus sûr de propager une souche puissante est de l’injecter directement dans le sang.",al={"comment le venin se transmet-il","mode de transmission"}}},fp="14,171,25.338.0,24.301.0,29.280.1,23.260.0,19.139.0,49.156.0,45.172.0,40.236.0,64.109.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="À la carrière, The Quarry's Smith, Frast Dokner, a besoin de métal et de cuir pour réparer le camp. Une livraison de ravitaillement ayant pris du retard, il demande aux voyageurs d'apporter ces matériaux. En échange, Dokner propose de transmettre des techniques pratiques de forge.",h="À la carrière, The Quarry's Smith, Frast Dokner, a besoin de métal et de cuir pour réparer le camp.",kw={"forge","barres de cuivre","dun morogh","nain","frast dokner","carrière de gol'bolar","forgefer","the quarry's smith","peaux de sanglier tannées"},ang={["faction:Alliance"]="En tant que membre de l'Alliance, vous pouvez aider à maintenir en activité cette carrière naine isolée et à garder son équipement prêt dans les hautes terres enneigées.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez apprendre auprès de Frast Dokner, un mentor de terrain pour les apprentis forgerons. Il transmet les techniques de forge qu'il a acquises à la dure à quiconque lui fournit le métal brut et le cuir nécessaires pour garder son enclume ardente.",["profession:Mining"]="En tant que mineur travaillant dans les gisements environnants, vous trouverez un acheteur tout près pour vos barres de cuivre fondues. Elles serviront à la formation pratique et aux réparations du camp.",["race:Dwarf"]="En tant que nain, vous pouvez découvrir l'industrie du clan Bronzebeard à la Carrière de Gol'Bolar, où la détermination des nains maintient les forges allumées malgré le retard des caravanes de ravitaillement."},sec={{t="Pénurie à la carrière",b="Un site d'excavation exige un entretien régulier. Il faut aiguiser les pioches, remplacer les ferrures usées et renforcer l'équipement du camp. Quand une livraison essentielle n'arrive pas à temps, le travail commence à ralentir. Faute de nouveaux stocks acheminés par les grandes routes commerciales, les artisans doivent improviser et demander de l'aide aux voyageurs de passage.\n\nFrast Dokner travaille à la forge malgré ces retards. Il demande à ceux qui le veulent bien de rassembler des métaux de base et des peaux pour maintenir le camp en activité, plutôt que d'attendre des chariots de transport qui pourraient avoir beaucoup de retard."},{t="Le marché d'un apprenti",b="Les guildes de forge naines prisent la discipline et gardent leurs méthodes, partageant rarement leurs secrets de métier avec les vagabonds de passage. Dokner met cette coutume en balance avec les besoins immédiats du camp. Il lui manque du cuivre malléable et du cuir résistant pour réparer les outils et l'équipement du camp.\n\nApportez les matières premières à son enclume, et il vous enseignera ses techniques personnelles de forge. Ce marché échange un savoir-faire utile contre les matériaux dont le camp a besoin pour tenir bon et entretenir son équipement."}},faq={{q="Qui est Frast Dokner ?",a="Frast Dokner est un forgeron expérimenté dans un campement de carrière. Il entretient les outils, les ferrures et l'équipement des ouvriers. Quand des retards coupent sa ligne d'approvisionnement habituelle, il demande aux voyageurs de passage de rassembler les matières premières dont il a besoin.",al={"histoire de frast dokner","qui est le forgeron de la carrière","forgeron de carrière"}},{q="Pourquoi la carrière a-t-elle besoin de barres de cuivre et de peaux de sanglier ?",a="L'exploitation de la carrière et l'entretien du camp nécessitent de grandes quantités de matériaux solides. Le cuivre est un métal facile à obtenir et à travailler, utile pour fabriquer des ferrures de remplacement, des clous, des attaches et des bandes qui renforcent les outils cassés. Les peaux de sanglier fournissent du cuir résistant pour les soufflets, les enveloppes d'outils, les sangles et les tabliers de protection contre les étincelles et les travaux pénibles.",al={"pourquoi des barres de cuivre et des peaux de sanglier","matériaux nécessaires au forgeron de la carrière","matériaux de réparation de la carrière"}},{q="Pourquoi la livraison de ravitaillement est-elle en retard ?",a="Frast Dokner n'explique pas pourquoi la livraison est en retard. Les routes terrestres qui traversent les crêtes enneigées et les cols de montagne sont souvent exposées aux blizzards, à la faune errante et aux embuscades de troggs ou de bandits hostiles. Les camps miniers et les carrières isolés sont les premiers touchés lorsque les chariots de transport prennent du retard.",al={"livraison de ravitaillement en retard","qu'est-il arrivé au ravitaillement","pourquoi le ravitaillement est-il retardé"}},{q="Que propose Frast Dokner en échange des matériaux ?",a="Frast Dokner propose plus que des pièces : il promet de transmettre ses techniques personnelles de forge à quiconque rassemble le ravitaillement nécessaire. Un artisan en herbe peut apprendre auprès d'un forgeron de terrain chevronné des techniques pratiques de travail du métal et d'entretien de l'équipement, des leçons que les guildes des villes enseignent rarement aux novices.",al={"récompense du forgeron de la carrière","qu'enseigne frast","techniques de forge de frast"}},{q="Où se trouve cette carrière ?",a="Frast Dokner travaille à la Carrière de Gol'Bolar, à Dun Morogh, au sud de Kharanos. Cette excavation naine se trouve dans des contreforts enneigés, exposés aux rigueurs de l'hiver et aux troggs souterrains agressifs, qui harcèlent les mineurs et perturbent les convois commerciaux en provenance de Forgefer.",al={"de quelle carrière s'agit-il","où se trouve frast dokner","emplacement du forgeron de la carrière"}},{q="Frast Dokner est-il affilié à Forgefer ?",a="Frast Dokner et le camp de la carrière dépendent du clan Bronzebeard et du royaume de Forgefer. L'extraction de pierre et de minerai à Dun Morogh contribue aux projets de construction et aux défenses du royaume. Les forgerons comme Dokner soutiennent l'industrie de Forgefer.",al={"frast dokner et forgefer","la carrière fait-elle partie de forgefer","allégeance des nains de la carrière"}}},fp="18,217,23.504.0,23.468.0,20.252.0,52.315.0,32.278.0,59.287.0,29.246.0,42.258.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="Dans la capitale déchue de Lordaeron, Captain Truman attend avec anxiété des renforts et des nouvelles de son commandant disparu. Il croit que le vénéré Grand Marshal combat toujours dans les ruines voisines et demande à un voyageur capable de le retrouver. Les recherches révèlent le sombre sort des défenseurs et la profonde hostilité des loyalistes.",h="Dans la capitale déchue de Lordaeron, Captain Truman attend avec anxiété des renforts et des nouvelles de son...",kw={"abominable creatures","captain truman","grand marshal","tête du baron","lordaeron","ruines de lordaeron","le baron","véritables fils de lordaeron"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous découvrez à quel point les vestiges loyalistes sont isolés et en péril dans les ruines souillées du nord de Lordaeron. Leurs détachements luttent contre le désespoir grandissant et les conséquences de leur combat contre des monstruosités écrasantes.",["race:Human"]="En tant qu’humain, vous découvrez le sombre sort des dirigeants déchus de Lordaeron : même un Grand Marshal estimé est devenu une horrible créature morte-vivante. Le chagrin de Captain Truman et son zèle nationaliste reflètent le traumatisme des survivants humains qui cherchent désespérément à reconquérir leur patrie ancestrale.",["race:Undead"]="En tant que Réprouvé, vous voyez dans la transformation grotesque du Baron un rappel de la façon dont le Fléau a mutilé les meilleurs défenseurs de Lordaeron pour en faire de monstrueuses abominations. Les paroles de Captain Truman révèlent l’hostilité des loyalistes encore en vie envers le peuple de Fossoyeuse."},sec={{t="Une veille désespérée",b="Captain Truman monte la garde aux abords de Lordaeron, dans l’attente anxieuse de renforts qui tardent depuis longtemps. Il décrit son supérieur comme un Grand Marshal renommé, grand et sculptural, et le croit redoutable au combat. Chargé de tenir la ligne pendant que son commandant se lançait dans la bataille, Truman reste lié par le devoir.\n\nIl se méfie des étrangers et méprise ceux qu’il appelle des races inférieures, refusant de compter sur les irréguliers locaux. À l’arrivée d’un voyageur capable, il vous demande d’entrer dans les ruines, de vérifier que son maître va bien et de découvrir comment tourne la bataille."},{t="Les Ruines de Lordaeron",b="Les recherches vous conduisent dans les Ruines de Lordaeron, la capitale brisée tombée aux mains du Fléau durant la Troisième guerre. Captain Truman s’attend à ce que son glorieux chef se tienne triomphant au-dessus des morts, mais la cité souillée raconte une histoire plus sombre.\n\nDes horreurs, des vestiges morts-vivants et des abominations errent sur ses places pavées en ruines. Les rues dévastées témoignent du sort des défenseurs entrés dans la ville. Aucun chevalier immaculé ne tient la ligne : le commandant a connu une fin tragique et dénaturée parmi les monstres des cours."},{t="Une découverte terrifiante",b="Le commandant disparu, que Captain Truman appelle le Baron, est devenu une monstrueuse abomination morte-vivante. Vous tuez la créature et rapportez la Tête du Baron à Captain Truman. La tête tranchée de son ancien seigneur laisse Truman stupéfait et horrifié, submergé par le dégoût.\n\nIncapable d’accepter le sort de son commandant, il se retourne contre vous, furieux, et vous accuse de vous être rangé du côté des monstres. Il déclare que les véritables fils de Lordaeron reconquerront leurs terres et purgeront toutes les bêtes."}},faq={{q="Qui donne la quête Abominable Creatures ?",a="Captain Truman, un loyaliste humain, vous confie cette tâche depuis son poste aux abords du royaume déchu. Il attend avec anxiété des renforts et des nouvelles de son commandant, un Grand Marshal vénéré parti combattre dans les Ruines de Lordaeron voisines.",al={"qui donne abominable creatures","personnage qui donne la quête abominable creatures","où commencer abominable creatures"}},{q="Où se déroule la quête Abominable Creatures ?",a="Les recherches vous conduisent dans les Ruines de Lordaeron, la capitale brisée envahie d’horreurs du Fléau et de vestiges morts-vivants. Captain Truman monte la garde aux abords de la cité souillée et demande aux voyageurs d’y retrouver son supérieur disparu.",al={"lieu d’abominable creatures","où terminer abominable creatures","zone d’abominable creatures"}},{q="Qui est le maître de Captain Truman ?",a="Captain Truman appelle son maître le Grand Marshal et le décrit comme un héros militaire grand et sculptural. Cet homme disparu est aussi appelé le Baron : c’est un aristocrate de haut rang et un commandant militaire qui dirige la défense du royaume.",al={"qui est le commandant de truman","identité du grand marshal de truman","qui est le baron"}},{q="Qu’est-il arrivé au Grand Marshal dans les Ruines de Lordaeron ?",a="Le Grand Marshal a été tué puis transformé en une monstrueuse créature morte-vivante dans les Ruines de Lordaeron. Vous trouvez une abomination appelée le Baron, la tuez et emportez sa tête tranchée.",al={"qu’est-il arrivé au baron","sort du grand marshal","le grand marshal est-il mort"}},{q="Pourquoi Captain Truman se met-il en colère quand vous rendez la quête ?",a="Captain Truman s’attend à ce que son commandant sculptural soit vivant et victorieux. La tête grotesque et mutée du Baron le remplit d’horreur et de dégoût. Fou de rage, il vous accuse de lui jouer une mauvaise plaisanterie et de frayer avec de viles bêtes.",al={"pourquoi truman est-il en colère","réaction de truman à abominable creatures","pourquoi truman vous crie-t-il dessus"}},{q="Que veut dire Captain Truman par « véritables fils de Lordaeron » ?",a="Par « véritables fils de Lordaeron », Captain Truman désigne les survivants humains légitimes qui cherchent à reconquérir leur patrie brisée et à la purger de toutes les bêtes. Cette expression révèle sa conviction que ces survivants humains sont les seuls à qui appartient cette terre.",al={"sens de véritables fils de lordaeron","qui sont les véritables fils de lordaeron","véritables fils selon truman"}},{q="Pourquoi Captain Truman refuse-t-il de faire confiance aux « sang-mêlé » ?",a="Captain Truman se méfie des races non humaines et des alliés irréguliers, qu’il traite de sang-mêlé indignes de confiance et de vermine. Son mépris l’empêche de se confier à quiconque ne représente pas, selon lui, dignement le royaume.",al={"sang-mêlé selon truman","pourquoi captain truman est-il raciste","xénophobie de truman"}}},fp="20,312,17.524.0,22.516.0,23.483.1,41.230.0,53.227.0,31.222.0,61.182.0,61.234.0,62.233.0,54.218.0"}
P.entries["quest:95254"] = {n="WANTED: Trapclaw",s="Fimbo Greasemitz veut la pince de Trapclaw, un énorme crabe qui vole des appâts et coupe les lignes de pêche sous les quais. Apportez-la-lui, et il vous promet un repas préparé avec son mélange d’épices secret.",h="Fimbo Greasemitz veut la pince de Trapclaw, un énorme crabe qui vole des appâts et coupe les lignes de pêche...",kw={"appât","crabe","chair de crabe","quais","fimbo greasemitz","lignes de pêche","pince","trapclaw"},sec={{t="Sous les quais",b="Fimbo Greasemitz veut de la chair de crabe, et Trapclaw rôde sous les quais. Ce grand crabe vole des appâts et coupe les lignes de pêche. Fimbo vous demande de lui apporter la pince de Trapclaw, qu’il compte utiliser pour préparer un repas."}},faq={{q="Qui réclame la pince de Trapclaw ?",a="Fimbo Greasemitz veut la pince de Trapclaw pour sa chair de crabe.",al={"qui veut la pince","requête de fimbo greasemitz"}},{q="Que fait Trapclaw ?",a="Trapclaw rôde sous les quais, vole des appâts et coupe les lignes de pêche.",al={"pourquoi trapclaw","crabe sous les quais"}},{q="Pourquoi Fimbo veut-il la pince ?",a="Fimbo veut de la chair de crabe et vous demande la pince de Trapclaw.",al={"à quoi sert la pince","demande de chair de crabe"}},{q="Que promet Fimbo de préparer ?",a="Fimbo dit qu’il préparera un plat avec du beurre et son mélange d’épices secret.",al={"quel repas","plat de fimbo"}}},fp="16,188,15.218.0,36.59.0,23.75.0,31.54.0,32.68.0"}
P.entries["quest:953"] = {n="La chute d'Ameth'Aran",s="À Ameth'Aran, à Sombrivage, vous explorez les ruines et lisez leurs anciennes tablettes de pierre pour la Sentinelle Tysha Lamelune. Leurs inscriptions racontent la chute de la cité des Bien-nés lors de la Fracture et préservent une histoire en grande partie perdue pendant la guerre des Anciens, pour le Cercle des anciens à Auberdine.",h="À Ameth'Aran, à Sombrivage, vous explorez les ruines et lisez leurs anciennes tablettes de pierre pour la...",kw={"ameth'aran","auberdine","azshara","cercle des anciens","sombrivage","bien-nés","fracture","tablettes","tysha lamelune"},ang={["class:Mage"]="En tant que mage, vous pouvez lire les tablettes comme un aperçu de l'art des sorts des elfes avant la Fracture, à son apogée. Elles racontent aussi les ruines qui suivirent lorsque cette puissance échappa à tout contrôle.",["faction:Alliance"]="En tant que membre de l'Alliance, vous aidez les Sentinelles à préserver l'histoire de Sombrivage pour les dirigeants elfes de la nuit qui guident l'Alliance sur Kalimdor.",["race:NightElf"]="En tant qu'elfe de la nuit, vous voyez les ruines d'Ameth'Aran comme un sinistre rappel de l'orgueil de vos ancêtres sous la reine Azshara. Une sorcellerie des arcanes sans limites a entraîné des conséquences catastrophiques."},sec={{t="Échos des Bien-nés",b="Ameth'Aran abritait les sorciers d'élite de la reine Azshara, qui maniaient une puissante magie des arcanes. Lorsque le Puits d'éternité fut détruit il y a dix mille ans, la cité s'effondra, laissant du marbre brisé et des piliers fissurés. Les Bien-nés qui y périrent hantent encore les ruines, esprits tourmentés et sans repos."},{t="Chroniques oubliées",b="Peu de récits écrits ont survécu intacts à la Grande Fracture. La guerre des Anciens força les elfes de la nuit à lutter pour leur survie, et une grande partie de leur histoire fut perdue. La Sentinelle Tysha Lamelune arpenta Ameth'Aran et découvrit deux grandes tablettes gravées, le Lai d'Ameth'Aran et La chute d'Ameth'Aran.\n\nDes spectres des Bien-nés chassèrent Tysha des ruines. Leurs inscriptions peuvent transmettre l'histoire du désastre aux érudits du Cercle des anciens à Auberdine."}},faq={{q="Qu'est-ce qu'Ameth'Aran ?",a="Ameth'Aran est une ancienne ruine des elfes de la nuit, au centre de Sombrivage. Il y a dix mille ans, c'était une cité où la noblesse des Bien-nés de la reine Azshara maniait et étudiait une puissante magie des arcanes. La Grande Fracture entraîna sa chute.",al={"histoire d'ameth'aran","qu'était ameth'aran","qui vivait à ameth'aran"}},{q="Pourquoi y a-t-il des fantômes à Ameth'Aran ?",a="Les fantômes d'Ameth'Aran sont les esprits des Bien-nés qui y ont vécu et péri. La catastrophe soudaine brisa le Puits d'éternité et fragmenta Kalimdor, les condamnant à un tourment éternel dans les ruines.",al={"pourquoi y a-t-il des esprits à ameth'aran","fantômes d'ameth'aran","bien-nés sans repos"}},{q="Qui est la Sentinelle Tysha Lamelune ?",a="La Sentinelle Tysha Lamelune est une sentinelle elfe de la nuit postée le long de la route à Sombrivage. Elle explore les sites anciens et retrouve des archives historiques perdues pour le Cercle des anciens à Auberdine.",al={"tysha lamelune","qui donne la quête la chute d'ameth'aran"}},{q="Pourquoi le Cercle des anciens veut-il faire lire ces tablettes ?",a="Le Cercle des anciens veut faire lire les tablettes, car la destruction du Puits d'éternité plongea Kalimdor dans un immense bouleversement. D'innombrables bibliothèques et monuments furent anéantis, et peu de récits écrits survécurent à la guerre des Anciens. Les tablettes préservent de rares témoignages directs des Bien-nés sur la Fracture.",al={"pourquoi lire les tablettes","tablettes du cercle des anciens","signification du lai d'ameth'aran"}},{q="Où se trouvent les tablettes ?",a="Le Lai d'Ameth'Aran et La chute d'Ameth'Aran sont gravés sur deux grands monuments de pierre dressés parmi les cours en ruine d'Ameth'Aran. Les fantômes errants des anciens habitants de la cité les entourent.",al={"où sont les tablettes d'ameth'aran","emplacement des tablettes","comment lire ameth'aran"}},{q="Qu'est-il arrivé aux Bien-nés d'Ameth'Aran pendant la Fracture ?",a="Lorsque le Puits d'éternité implosa au point culminant de la guerre des Anciens, de puissants tremblements de terre et un contrecoup des arcanes déchirèrent Kalimdor. Ameth'Aran s'effondra, ensevelissant ses habitants et laissant leurs fantômes dans les décombres.",al={"comment ameth'aran est-elle tombée","destruction d'ameth'aran"}}},fx={["4f4506ec"]={q="Pourquoi la sentinelle Tysha Lamelune veut-elle que cela soit fait ?",a="La sentinelle Tysha Lamelune a été envoyée au nom du Cercle des Anciens pour inspecter les ruines antiques. Les archives de l'époque de la Guerre des Anciens et de la Fracture sont extrêmement rares en raison des cataclysmes de cette ère. Recueillir l'histoire gravée sur les tablettes lui permet de fournir un compte-rendu complet aux druides et aux anciens d'Auberdine.",al={"motivation de tysha lamelune","pourquoi tysha a-t-elle besoin de cela","pourquoi étudier les tablettes d'ameth'aran"}},["2329a43d"]={q="Pourquoi la sentinelle Tysha Lamelune a-t-elle besoin de votre aide ?",a="Tysha s'est aventurée précédemment dans Ameth'Aran pour examiner les tablettes elle-même, mais elle a été prise en embuscade et chassée par les esprits vengeurs des Bien-nés qui hantent les ruines. Incapable de transcrire les inscriptions en toute sécurité seule tout en subissant une attaque spectrale constante, elle a besoin d'un aventurier capable de pénétrer dans les ruines et de déchiffrer le texte à sa place.",al={"pourquoi tysha ne peut-elle pas lire les tablettes","pourquoi tysha a-t-elle besoin de moi","pourquoi tysha n'y va-t-elle pas elle-même"}}},fp="22,278,23.289.0,26.458.0,19.221.0,35.199.0,32.190.0,56.311.0,30.204.0,66.216.0"}
P.entries["quest:95314"] = {n="That Shadowvale Green Elixir",s="À Brill, That Shadowvale Green Elixir attire des acheteurs malgré l’ancienne interdiction. Les habitants d’Ombreval, reclus, préparaient autrefois l’Élixir des murmures avec des herbes locales, et le Fléau a laissé le village en ruines.",h="À Brill, That Shadowvale Green Elixir attire des acheteurs malgré l’ancienne interdiction.",kw={"apothicaire","brill","carolai anise","poison","ombreval","tirisfal","élixir des murmures","forêt des murmures"},ang={["class:Rogue"]="En tant que voleur, vous savez que les empoisonneurs et les scélérats appréciaient l’Élixir des murmures lorsqu’ils agissaient à l’insu des anciens magistrats de Lordaeron.",["profession:Herbalism"]="En tant qu’herboriste, vous savez que l’élixir tire sa puissance de rares herbes qui ne poussent que sous la canopée sinistre de la Forêt des Murmures.",["race:Undead"]="En tant que Réprouvé, vous pouvez tirer profit des anciens breuvages oubliés de Lordaeron et les utiliser pour alimenter les expériences des apothicaires dans la jeune Fossoyeuse."},sec={{t="Un breuvage interdit",b="Avant l’arrivée du Fléau, les habitants d’Ombreval préparaient l’Élixir des murmures avec de rares herbes que l’on ne trouve que dans les Clairières de Tirisfal. Le breuvage se fit connaître dans tout le nord de Lordaeron. La Capital City l’interdit, mais les mystiques, les empoisonneurs et les apothicaires continuaient de rechercher ses propriétés inhabituelles, au mépris des décrets royaux."},{t="Ruines de la Forêt des Murmures",b="Ombreval se trouve au cœur de la Forêt des Murmures, dans l’ouest de Tirisfal. Ses habitants étaient reclus et méfiants, et accueillaient rarement les étrangers. L’invasion du Fléau a laissé le village en ruines, mais des réserves oubliées d’élixir vert vieilli subsistent parmi les décombres.\n\nCarolai Anise travaille depuis Brill. Le milieu interlope convoite toujours le breuvage, alors elle paie les aventuriers prêts à braver le silence inquiétant de la forêt."},{t="La malédiction des murmures",b="Carolai Anise balaie les rumeurs d’un revers de main, les prenant pour de la superstition, mais la Forêt des Murmures a mauvaise réputation. Selon les légendes locales, une ancienne malédiction souille son sol et ses racines, puis s’insinue dans les plantes récoltées par les brasseurs d’Ombreval. Quelle que soit la malveillance qui rôde autour du hameau abandonné, les acheteurs lointains convoitent toujours les vestiges embouteillés."}},faq={{q="Qu’est-ce qu’Ombreval ?",a="Ombreval était un village isolé, au cœur de la Forêt des Murmures, dans l’ouest des Clairières de Tirisfal. Avant que le Fléau ne submerge la région, ses habitants secrets distillaient de rares breuvages à partir d’herbes locales.",al={"où se trouve ombreval","qui vivait à ombreval","village d’ombreval"}},{q="Qu’est-ce que l’Élixir des murmures ?",a="L’Élixir des murmures est un puissant breuvage vert préparé avec des herbes que l’on ne trouve qu’à Tirisfal. Les mystiques, les empoisonneurs et les apothicaires le convoitaient, bien que la Capital City l’ait interdit avant la chute de Lordaeron.",al={"que fait l’élixir","histoire de l’élixir vert d’ombreval","élixir des murmures"}},{q="Qui est Carolai Anise ?",a="Carolai Anise est une Réprouvée qui vit à Brill. Elle sert d’intermédiaire pour des curiosités interdites de grande valeur, dont l’élixir d’Ombreval, auprès d’acheteurs de tout le royaume.",al={"carolai anise","qui donne la quête de that shadowvale green elixir","donneur de quête à brill"}},{q="Pourquoi l’élixir a-t-il été interdit dans la Capital City ?",a="La raison de cette interdiction n’est pas précisée. Carolai dit seulement que la Capital City a interdit l’élixir, bien que les apothicaires, les mystiques et les empoisonneurs le convoitent. Certains accusent une malédiction dans la Forêt des Murmures et ses racines, mais Carolai balaie ces propos d’un revers de main, les prenant pour de la superstition, et ne les relie jamais à l’interdiction.",al={"pourquoi l’élixir des murmures était-il illégal","l’élixir est-il un poison"}},{q="Pourquoi la Forêt des Murmures est-elle considérée comme dangereuse ?",a="La Forêt des Murmures, à l’ouest du Glas, est considérée comme sinistre et maudite. Ceux qui s’y aventurent parlent d’une profonde malveillance et d’étranges phénomènes forestiers. Les rumeurs disent que le sol de la forêt a contaminé ses herbes.",al={"la forêt des murmures est-elle maudite","histoire de la forêt des murmures"}},{q="Qui sont les acheteurs qui convoitent cet élixir ?",a="Carolai Anise dit que plusieurs acheteurs recherchent les bouteilles qui ont survécu à la guerre, mais elle ne les nomme pas.",al={"qui achète l’élixir","acheteurs de carolai anise"}}},fx={["4d019fa8"]={q="Pourquoi Carolai Anise veut-elle que l'élixir chuchotant soit récupéré ?",a="Carolai Anise opère en tant que receleuse de biens rares à Brill, et la demande pour ce breuvage illicite n'a jamais vraiment faibli. Avec de nombreux acheteurs impatients de recevoir des cargaisons, il y a un profit considérable à réaliser avec les bouteilles qui sont restées intactes parmi les ruines.",al={"pourquoi carolai veut-elle l'élixir","motivation de carolai anise","pourquoi collecter l'élixir chuchotant"}}},fp="28,195,13.300.0,30.405.0,20.331.1,19.190.0,26.192.0,21.142.0,46.280.0,50.204.0,39.105.0"}
P.entries["quest:95315"] = {n="The Riverglades Report",s="Le capitaine Nials vous envoie vers le sud avec une lettre pour Demar Brant, au Donjon de Fort-Lointain. Un éclaireur signale une force ennemie au-delà des Paluns, près de Farholde.",h="Le capitaine Nials vous envoie vers le sud avec une lettre pour Demar Brant, au Donjon de Fort-Lointain.",kw={"capitaine nials","correspondance","demar brant","farholde","donjon de fort-lointain","rapport des rives claires","éclaireur","les paluns"},sec={{t="Parole d’éclaireur",b="Le capitaine Nials a appris qu’une importante force ennemie se rassemble loin au sud des Paluns. Une colonie appelée Farholde se trouve peut-être là-bas, mais ce nom ne lui est que vaguement familier. Il vous confie une lettre pour Demar Brant, qui dirige le détachement du Donjon de Fort-Lointain, sur la côte sud-est des Rives Claires."}},faq={{q="Qu’a rapporté l’éclaireur ?",a="L’éclaireur a signalé une importante force ennemie qui se rassemble loin au sud, au-delà des Paluns.",al={"rapport de l’éclaireur","événements au sud"}},{q="À qui le capitaine Nials m’envoie-t-il ?",a="Vous devez remettre la lettre du capitaine Nials à Demar Brant, au Donjon de Fort-Lointain.",al={"destinataire de la lettre","demar brant"}},{q="Où se trouve le Donjon de Fort-Lointain ?",a="Le Donjon de Fort-Lointain se trouve sur la côte sud-est des Rives Claires.",al={"où se trouve farholde","emplacement du donjon"}},{q="Qu’est-ce que Farholde ?",a="Le capitaine Nials a entendu parler d’une colonie appelée Farholde, près de la force qui se rassemble.",al={"colonie farholde","qu’est-ce que farholde"}}},fp="22,180,16.302.0,26.80.0,35.83.0,23.67.0,17.81.0"}
P.entries["quest:95328"] = {n="Résidu d’horreur murmurante",s="Sous la Forêt des Murmures, Whispering Horror Residue est transporté à Fossoyeuse pour y être étudié. Father Lankester l’attend dans le War Quarter.",h="Sous la Forêt des Murmures, Whispering Horror Residue est transporté à Fossoyeuse pour y être étudié.",kw={"father lankester","ombre","tirisfal","fossoyeuse","vide","war quarter","forêt des murmures","whispering horror residue"},ang={["class:Priest"]="En tant que prêtre parmi les Réprouvés, vous partagez peut-être l’intérêt érudit et religieux de Father Lankester pour les spécimens touchés par le Vide. Les restes étranges peuvent être des sujets d’étude plutôt que de simples abominations.",["faction:Horde"]="En tant qu’aventurier de la Horde, vous récupérez des spécimens troublants dans des lieux cachés des Clairières de Tirisfal, afin qu’ils soient étudiés sous les ruines de la capitale.",["race:Undead"]="En tant que Réprouvé, vous savez que les habitants de Fossoyeuse étudient la magie interdite et la corruption contre nature dans tout Lordaeron. Ils cherchent des moyens d’utiliser les forces obscures pour renforcer leur emprise sur le royaume."},sec={{t="Une récolte troublante",b="Sous la Forêt des Murmures, vous récupérez les restes frémissants d’une étrange bête. Cette matière troublante est transportée à Fossoyeuse, où des chercheurs pourront l’étudier."},{t="Études dans l’ombre",b="Dans le War Quarter de Fossoyeuse, Father Lankester reçoit les restes. Il affirme que la Forêt des Murmures est depuis longtemps touchée par le Vide. Ces traces physiques pourraient l’aider à étudier les mystères de l’ombre."}},faq={{q="Qu’est-ce que Whispering Horror Residue ?",a="Il s’agit des restes frémissants d’une étrange bête vaincue sous la Forêt des Murmures. Les érudits de l’ombre les apprécient pour leurs études ésotériques et occultes.",al={"qu’est-ce que ces restes","qu’est-ce que whispering horror residue","objet de résidus"}},{q="Qui veut Whispering Horror Residue ?",a="Father Lankester, un Réprouvé du War Quarter de Fossoyeuse, veut récupérer ces restes. Il se réjouit de pouvoir étudier l’ombre et les phénomènes touchés par le Vide.",al={"qui récupère ces restes","qui est father lankester","où remettre les restes"}},{q="D’où vient ce spécimen ?",a="Le spécimen vient de sous la Forêt des Murmures, à l’ouest du Glas, dans les Clairières de Tirisfal. Father Lankester affirme que la zone est touchée par le Vide.",al={"d’où vient l’horreur","histoire de la forêt des murmures","sous la forêt des murmures"}},{q="Pourquoi Father Lankester veut-il ces restes ?",a="Father Lankester veut étudier l’ombre et le Vide. Les restes physiques de créatures touchées par le Vide fournissent aux adeptes des arts interdits une matière à étudier.",al={"pourquoi lankester veut ces restes","recherches sur l’ombre à fossoyeuse","pourquoi étudier ces restes"}},{q="Où trouver Father Lankester ?",a="Vous trouverez Father Lankester dans le War Quarter de Fossoyeuse, sous les ruines de la capitale de Lordaeron. Les guerriers, les érudits et les stratèges militaires réprouvés s’y rassemblent.",al={"où se trouve le war quarter","où se trouve lankester","emplacement de lankester à fossoyeuse"}},{q="La Forêt des Murmures est-elle touchée par le Vide ?",a="Father Lankester affirme que la Forêt des Murmures est depuis longtemps touchée par le Vide. Ces bois et les espaces qui s’étendent sous eux sont connus pour cette corruption.",al={"la forêt des murmures est-elle maudite","corruption du vide dans la forêt des murmures","qu’est-ce qui touche la forêt des murmures"}}},fp="25,138,21.162.0,17.197.0,38.149.0,40.151.0,34.147.0,43.154.0,36.168.0,45.147.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="Depuis Zephras, les Sculpte-vents du Cercle terrestre gagnent Azeroth comme avant-garde. Retardés par l’activité d’une secte à Valanaar, ils embarquent à bord d’un skycutter près du pavillon et débarquent en Mulgore pour rencontrer Alaana Stormwalker et s’adapter à un monde vaste et dangereux.",h="Depuis Zephras, les Sculpte-vents du Cercle terrestre gagnent Azeroth comme avant-garde.",kw={"alaana stormwalker","banu-alah","secte","mulgore","skycutter","cercle terrestre","valanaar","sculpte-vents","zephras"},ang={["class:Shaman"]="En tant que Chaman, vous partagez le respect des éléments des Sculpte-vents et leur confiance dans les vents qui guident leur traversée. Votre arrivée au sein du Cercle terrestre vous relie aux traditions élémentaires qui prennent racine en Mulgore.",["race:Skyborne"]="En tant qu’aventurier Skyborne quittant Valanaar, vous entreprenez le voyage historique vers Azeroth au sein de son avant-garde. Vous laissez derrière vous les troubles causés par la secte et posez le pied dans les plaines de Mulgore.",["race:Tauren"]="En tant que Tauren natif de Mulgore, vous voyez des voyageurs de Zephras descendre sur les plaines ancestrales de votre peuple. Accueillir ces visiteurs vous permet de nouer un premier lien avec des alliés qui cherchent à s’établir sur vos terres."},sec={{t="Départ de Valanaar",b="L’activité d’une secte à Valanaar a perturbé les plans des Sculpte-vents, qui devaient se rendre en Azeroth. Leurs hauts dirigeants restent au pavillon pour régler des affaires urgentes et mettre fin à la menace, tandis qu’une petite avant-garde part en avance. Aux quais, juste à l’extérieur du pavillon, les pionniers embarquent à bord d’un skycutter qui les mènera à travers les cieux.\n\nLeurs commandants promettent de les rejoindre bientôt. D’ici là, le groupe d’avant-garde doit établir une présence avant que les autres puissent suivre."},{t="Arrivée en Mulgore",b="En Mulgore, Alaana Stormwalker accueille les aventuriers arrivés de Zephras. Établir une présence en Azeroth prendra du temps. Les nouveaux venus sont donc invités à explorer le territoire alentour et à s’y accoutumer.\n\nLes vents favorisent l’expédition, mais Azeroth leur est étrangère et périlleuse. Les voyageurs doivent apprendre à connaître le terrain, la faune et les habitants des environs avant l’arrivée de ceux qui sont restés à Valanaar."}},faq={{q="Pourquoi les Sculpte-vents se rendent-ils en Azeroth ?",a="Les Sculpte-vents envoient une avant-garde établir une présence en Azeroth tandis que leurs dirigeants restent à Valanaar. L’activité d’une secte y a perturbé les plans initiaux et retardé le reste du groupe. L’avant-garde voyage donc seule, en attendant les renforts.",al={"pourquoi aller en azeroth","mission des sculpte-vents","pourquoi les sculpte-vents sont-ils en mulgore"}},{q="Qui est Alaana Stormwalker ?",a="Alaana Stormwalker accueille en Mulgore les Sculpte-vents arrivés de Zephras. Elle explique qu’il faudra du temps pour établir une présence sûre dans ces terres nouvelles et conseille aux arrivants d’explorer la région et de se préparer aux dangers d’Azeroth.",al={"qui est alaana","rôle d’alaana stormwalker","où se trouve alaana stormwalker"}},{q="Pourquoi le départ principal a-t-il été retardé ?",a="L’activité d’une secte à Valanaar a retardé le départ principal. Les chefs de l’expédition restent au pavillon pour régler le problème, tandis qu’une petite avant-garde embarque à bord d’un skycutter et prend de l’avance vers Azeroth.",al={"raison du retard","quelle secte a retardé le voyage","pourquoi rester à valanaar"}},{q="Comment les voyageurs se rendent-ils de Valanaar à Mulgore ?",a="À Valanaar, les voyageurs embarquent à bord d’un skycutter aux quais situés juste à l’extérieur du pavillon. Il transporte l’avant-garde à travers les cieux jusqu’en Mulgore, reliant Zephras à Azeroth lors de cette première expédition.",al={"comment rejoindre mulgore","où se trouve le navire","comment se rendre en azeroth"}},{q="Qu’est-ce que Zephras ?",a="Zephras est le foyer des aventuriers qui arrivent à bord du skycutter. En Mulgore, Alaana Stormwalker accueille les nouveaux venus de Zephras et explique que des vents favorables les ont guidés jusqu’à Azeroth, un monde inconnu et dangereux.",al={"où se trouve zephras","qu’est-ce que zephras","histoire de zephras"}},{q="Que doivent faire les aventuriers à leur arrivée en Mulgore ?",a="Les nouveaux arrivants sont invités à explorer les terres environnantes de Mulgore. Apprendre à connaître le terrain, les créatures et les menaces locales les aidera à établir une présence dans ce monde inconnu et dangereux.",al={"que faire en mulgore","que faire après l’arrivée","que faire ensuite"}}},fp="16,272,23.440.0,18.424.0,45.264.0,26.240.0,35.192.0,50.190.0,16.215.0,52.209.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="Sur Kalimdor, les Sculpte-vents quittent leur foyer isolé pour chercher des alliés. Guidé par ses liens avec le Cercle terrestre, un émissaire part des Pitons-du-Tonnerre rencontrer le chef de guerre Thrall à Orgrimmar.",h="Sur Kalimdor, les Sculpte-vents quittent leur foyer isolé pour chercher des alliés.",kw={"cercle terrestre","horde","orgrimmar","thrall","pitons-du-tonnerre","valley of wisdom","welcome to azeroth","sculpte-vents"},ang={["class:Shaman"]="Guidé par le Cercle terrestre et béni par les vents, vous reliez vos proches spirituels aux chefs chamaniques de la Valley of Wisdom.",["faction:Horde"]="Ce voyage diplomatique officialise les liens avec la Horde et présente les nouveaux venus au chef de guerre Thrall comme des alliés dans la lutte pour la survie sur Kalimdor.",["race:Skyborne"]="Quittant les hauteurs pour le monde de la surface, vous partez des Sculpte-vents célestes vers les Pitons-du-Tonnerre et Orgrimmar, en quête d’une place auprès de nouveaux alliés."},sec={{t="Des alliés dans un monde plus vaste",b="Les Sculpte-vents regardent au-delà de leurs origines isolées vers les peuples de Kalimdor. Ils savent que l’isolement ne peut les protéger des menaces d’Azeroth et cherchent donc des compagnons pour affronter ensemble les terres sauvages. Leur quête les mène jusqu’à la cité tauren voisine des Pitons-du-Tonnerre et aux bastions orcs de l’est."},{t="Une audience avec le chef de guerre",b="Les émissaires se rendent d’abord aux hautes tours des Pitons-du-Tonnerre, puis traversent les Tarides jusqu’à Orgrimmar, la capitale de la Horde. Le chef de guerre Thrall les attend dans la paisible Valley of Wisdom. Cette audience intègre les Sculpte-vents à la vie politique et spirituelle de Kalimdor, et les unit à la Horde par un objectif commun et le respect des éléments."}},faq={{q="Quel est l’objectif de la quête Welcome to Azeroth ?",a="Un émissaire voyage au nom des Sculpte-vents pour rencontrer le chef de guerre Thrall à Orgrimmar. Cette rencontre leur fait découvrir la Horde dans son ensemble et le monde de la surface de Kalimdor.",al={"quel est l’objectif de cette quête","quête welcome to azeroth","objectif de welcome to azeroth"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents tendent la main depuis les hauteurs à des alliés de la surface, et cherchent à survivre grâce à leurs liens avec le Cercle terrestre et la Horde. Ils envoient des voyageurs rencontrer directement les dirigeants de la Horde à Durotar.",al={"qui sont les sculpte-vents","que sont les sculpte-vents"}},{q="Pourquoi vous envoie-t-on parler à Thrall ?",a="Thrall est le chef de guerre de la Horde et un chef chamanique vénéré qui supervise les principales alliances de la coalition depuis la Valley of Wisdom. Le rencontrer officialise les relations entre les Sculpte-vents et la Horde.",al={"pourquoi rencontrer thrall","parler à thrall à orgrimmar","pourquoi aller à orgrimmar"}},{q="Comment vous rendre des Pitons-du-Tonnerre à Orgrimmar ?",a="Les voyageurs décollent du perchoir central des Pitons-du-Tonnerre avec le maître de vol et traversent les plaines de Kalimdor vers l’est, jusqu’à la forteresse d’Orgrimmar, bâtie dans un canyon.",al={"comment rejoindre orgrimmar","maître de vol des pitons-du-tonnerre","rejoindre orgrimmar depuis les pitons-du-tonnerre"}},{q="Quel rôle le Cercle terrestre joue-t-il dans cette mission ?",a="Le Cercle terrestre est allié à la coalition de peuples de la Horde qui partagent ses idéaux. Il contribue à unir les factions chamaniques aux nations de Kalimdor.",al={"rôle du cercle terrestre dans la horde","le cercle terrestre est-il dans la horde"}},{q="Où se trouve Thrall à Orgrimmar ?",a="Le chef de guerre Thrall réside dans la Valley of Wisdom, un sanctuaire spirituel paisible à l’ouest d’Orgrimmar où se réunissent chamans et conseillers tribaux.",al={"où se trouve thrall","emplacement de thrall dans la valley of wisdom"}}},fp="18,196,25.303.0,29.350.0,52.156.0,24.200.0,38.208.0,50.154.0,48.142.0,37.139.0"}
P.entries["quest:95384"] = {n="Partial Mystical Notes",s="Un étrange parchemin magique porte des symboles que vous ne pouvez pas lire, mais ne renferme aucune force qui vous semble instable. Vous l’apportez à Dudd Fizzlescroll, à Baie-du-Butin, où il voit du potentiel dans sa magie.",h="Un étrange parchemin magique porte des symboles que vous ne pouvez pas lire, mais ne renferme aucune force...",kw={"baie-du-butin","dudd fizzlescroll","parchemin magique","magie mystique","notes mystiques partielles","parchemin partiel","étranges symboles"},sec={{t="Symboles indéchiffrables",b="Vous trouvez un parchemin magique couvert d’étranges symboles, mais vous ne comprenez pas cette langue. Sa magie vous semble assez inoffensive, alors vous apportez le parchemin partiel à Dudd Fizzlescroll, à Baie-du-Butin. Il reconnaît une magie puissante et compte la traduire pour ses archives."}},faq={{q="Que contient le parchemin ?",a="Le parchemin magique porte d’étranges symboles dans une langue que vous ne parlez pas.",al={"quels symboles","écriture du parchemin","notes mystiques"}},{q="Le parchemin semble-t-il dangereux ?",a="Vous ne sentez aucune force particulièrement instable dans le parchemin.",al={"est-ce instable","parchemin dangereux","magie inoffensive"}},{q="Qui veut le parchemin ?",a="Dudd Fizzlescroll, à Baie-du-Butin, reconnaît la magie du parchemin et compte la traduire pour ses archives.",al={"qui le prend","dudd fizzlescroll","collectionneur de parchemins"}},{q="Où apporter le parchemin partiel ?",a="Vous apportez le parchemin partiel à Dudd Fizzlescroll, à Baie-du-Butin.",al={"où apporter le parchemin","parchemin à baie-du-butin","destination du parchemin"}}},fp="22,180,14.261.0,22.72.0,31.60.0,21.105.0,36.63.0"}
P.entries["quest:95385"] = {n="Torn Mystical Scroll",s="Un parchemin déchiré porte une faible magie et des runes inconnues. Vous l’apportez à Dudd Fizzlescroll, à Baie-du-Butin, où il voit du potentiel dans son écriture.",h="Un parchemin déchiré porte une faible magie et des runes inconnues.",kw={"baie-du-butin","dudd fizzlescroll","ingénierie","faible magie","parchemin incomplet","runes","parchemin mystique déchiré"},ang={["profession:Engineering"]="Dudd Fizzlescroll prévoit de copier les runes dans son ouvrage et parle de devenir un ingénieur légendaire."},sec={{t="Un fragment curieux",b="Une faible magie imprègne le parchemin déchiré, dont les runes vous sont inconnues. Vous n’y sentez aucun danger, même si la plupart jugeraient ce parchemin inutile. Dudd Fizzlescroll, à Baie-du-Butin, pourrait trouver un usage à ce fragment."},{t="Le travail de Dudd",b="Dudd Fizzlescroll s’empresse de copier les runes dans son ouvrage. Il parle de devenir un ingénieur légendaire, puis vous avertit de vous tenir à l’écart pour ne pas être blessé."}},faq={{q="Qu’est-ce que ce parchemin déchiré ?",a="C’est un fragment de parchemin portant une faible magie et des runes inconnues. Vous sentez qu’il n’est pas dangereux.",al={"parchemin déchiré","parchemin mystique","qu’est-ce que ce parchemin"}},{q="Qui veut le parchemin ?",a="Dudd Fizzlescroll, à Baie-du-Butin, s’intéresse au parchemin incomplet.",al={"qui le veut","collectionneur de parchemins","dudd scroll"}},{q="Pourquoi l’apporter à Dudd ?",a="Dudd pourrait trouver un usage aux runes inconnues inscrites sur le parchemin.",al={"pourquoi dudd","où va le parchemin","utilité du parchemin"}},{q="Le parchemin est-il dangereux ?",a="Le parchemin dégage une faible magie, mais vous sentez intuitivement qu’il n’est pas dangereux.",al={"parchemin sans danger","parchemin dangereux","est-ce magique"}}},fp="20,139,15.208.0,11.157.1,24.104.0,21.67.0,21.62.0,24.74.0"}
P.entries["quest:954"] = {n="Bashal'Aran",s="Une aura bleue inquiétante brille au-dessus d’un sanctuaire de Bashal'Aran, où les satyres et les grells refusent d’aller. Thundris Windweaver, l’aîné d’Auberdine, vous demande d’en trouver la source.",h="Une aura bleue inquiétante brille au-dessus d’un sanctuaire de Bashal'Aran, où les satyres et les grells...",kw={"asterion","bashal'aran","aura bleue","sombrivage","grell","ruines kaldorei","satyre","thundris windweaver"},ang={["faction:Alliance"]="En tant que vagabond de l’Alliance, vous aidez les éclaireurs d’Auberdine à s’enfoncer dans les ruines disputées de Sombrivage et à empêcher les menaces démoniaques d’atteindre la côte.",["race:NightElf"]="En tant qu’elfe de la nuit, Bashal'Aran vous rappelle ce que vos ancêtres ont perdu lors du Sundering. Leurs ombres persistantes montent une veille solitaire tandis que la corruption démoniaque gagne du terrain."},sec={{t="Un phare dans les ruines",b="Bashal'Aran prospérait autrefois sous l’ancien Empire kaldorei. À présent, une souillure démoniaque emplit ses salles de marbre brisées et ses arches envahies par la végétation. Les satyres déformés et les grells corrompus se nourrissent de la magie persistante des ruines et deviennent chaque jour plus malveillants. Pourtant, Thundris Windweaver, à Auberdine, a remarqué un mystère : au sommet d’un promontoire à l’ouest, une aura bleue brille au-dessus d’un sanctuaire qu’aucun démon n’approche."},{t="L’ombre blessée",b="Au sanctuaire surélevé, vous trouvez Asterion, un ancien esprit, au cœur de la lumière bleue. L’ombre monte une veille solitaire depuis des siècles. Au milieu des bêtes hurlantes et des vils démons, même un étranger de passage apporte un répit après des décennies d’isolement."}},faq={{q="Où se trouve l’aura bleue ?",a="L’aura bleue brille au-dessus d’un sanctuaire situé au sommet d’un petit promontoire, à l’extrémité ouest de Bashal'Aran, juste à l’est d’Auberdine, à Sombrivage. Le sanctuaire s’élève légèrement au-dessus des murs en ruine qui l’entourent.",al={"trouver l’aura bleue","où se trouve asterion","emplacement du sanctuaire de bashal'aran"}},{q="Pourquoi les satyres évitent-ils le sanctuaire ?",a="Personne ne sait pourquoi les satyres et les grells évitent le sanctuaire. Une étrange aura bleue emplit les lieux, et Thundris Windweaver vous envoie en trouver la source.",al={"pourquoi les démons ont peur","pourquoi les satyres restent à l’écart"}},{q="Qui vous envoie en quête ?",a="Thundris Windweaver, un druide elfe de la nuit et l’aîné d’Auberdine, vous envoie sur place après avoir remarqué des mouvements démoniaques anormaux dans les ruines orientales.",al={"qui donne la quête","donneur de quête","emplacement de thundris windweaver"}},{q="Qu’est-ce que Bashal'Aran ?",a="Bashal'Aran est une ancienne ruine kaldorei dans les forêts de Sombrivage, mise à sac lors du Sundering. Les grells et les satyres l’infestent désormais, attirés par ses pouvoirs telluriques dormants.",al={"qu’est-il arrivé à bashal'aran","histoire de bashal'aran"}}},fx={["2cba9e48"]={q="Pourquoi Thundris Windweaver veut-il que j'enquête sur Bashal'Aran ?",a="Thundris Windweaver surveille les ruines antiques de Bashal'Aran avec une crainte grandissante. Des sprites et des satyres corrompus pullulent sur les lieux, puisant dans les énergies arcaniques persistantes pour amplifier leur puissance démoniaque. Pourtant, parmi cette infestation, un sanctuaire enveloppé d'une curieuse aura bleue reste totalement épargné par les démons. Thundris a besoin de comprendre quelle puissance les tient à distance, et si cela pourrait être la clé pour repousser la corruption qui empiète sur Sombrivage.",al={"pourquoi enquêter sur bashal'aran","motivation de thundris","pourquoi m'envoyer à bashal'aran"}}},fp="11,161,21.382.0,17.245.1,31.192.0,35.147.0,28.136.0,20.171.0"}
P.entries["quest:95417"] = {n="The Purple Ones",s="Clubtoe vous demande de chercher les ogres disparus dans les grottes sous Clairsoleil. Certains reviennent changés, et il veut comprendre pourquoi.",h="Clubtoe vous demande de chercher les ogres disparus dans les grottes sous Clairsoleil.",kw={"grottes","clubtoe","runes sombres","ogres disparus","ogres","violets","clairsoleil","les violets","twilight hammer"},sec={{t="L’inquiétude de Clubtoe",b="Clubtoe a vu ses amis entrer dans les grottes sous Clairsoleil sans en revenir. Certains reviennent violets et ne se comportent plus comme ses amis. Il vous demande de chercher les ogres disparus dans les grottes, même s’il craint que vous n’en reveniez changé à votre tour."},{t="Dans les grottes",b="Sous Clairsoleil, vous trouvez un ogre mort au milieu de runes sombres. Les pouvoirs du rituel du Twilight Hammer l’ont submergé."}},faq={{q="Qui est Clubtoe ?",a="Clubtoe est un ogre dont les amis ont disparu dans les grottes sous Clairsoleil.",al={"clubtoe","qui est clubtoe"}},{q="Pourquoi Clubtoe me demande-t-il de chercher dans les grottes ?",a="Certains amis de Clubtoe ne reviennent pas des grottes, et certains de ceux qui reviennent sont violets et se comportent différemment.",al={"ogres disparus","retrouver les amis de clubtoe","ogres des grottes"}},{q="Où sont les ogres disparus ?",a="Clubtoe vous demande de chercher les ogres disparus dans les grottes sous Clairsoleil.",al={"où vont les ogres","grotte de clairsoleil","ogres disparus"}},{q="Qu’y a-t-il d’étrange chez les ogres qui reviennent ?",a="Certains reviennent violets et ne se comportent plus comme les amis de Clubtoe.",al={"ogres violets","pourquoi violets","ogres au comportement étrange"}}},fp="15,138,17.245.0,12.124.1,15.83.0,44.110.0,28.79.0,43.60.0"}
P.entries["quest:95418"] = {n="Spread the Word",s="Clubtoe vous demande d'apporter la tête de Chogg'Zac à Tran'gul, à Rog’mar, après son départ du Marteau du crépuscule. La nouvelle de sa défection pourrait inciter d'autres ogres du culte à se libérer.",h="Clubtoe vous demande d'apporter la tête de Chogg'Zac à Tran'gul, à Rog’mar, après son départ du Marteau du...",kw={"chogg'zac","clubtoe","clugfist","défection d'un ogre","rog’mar","répandre la nouvelle","tran'gul","marteau du crépuscule"},sec={{t="Un message pour Tran'gul",b="La tête de Chogg'Zac doit être rapportée à vos amis, et c'est Tran'gul, à Rog’mar, qui doit la recevoir. Clubtoe affirme en avoir fini avec le Marteau du crépuscule et prévoit de rejoindre Clugfist, le plus grand ogre qu'il connaisse, avec beaucoup d'autres. Clubtoe compte rester là où il est jusqu'à ce que tout danger soit écarté. À présent, Tran'gul doit savoir ce que Clubtoe a choisi."},{t="Des nouvelles de la grotte",b="Tran'gul apprend que la grotte réservait une autre surprise. Vous avez convaincu un ogre du Marteau du crépuscule de faire défection, et il a parlé d’autres ogres de son espèce. Tran'gul dit qu’ils doivent agir immédiatement à la lumière de cette nouvelle."}},faq={{q="Qui est Clubtoe ?",a="Clubtoe est un ogre qui dit en avoir fini avec le Marteau du crépuscule et compte rejoindre les ogres libres.",al={"clubtoe","ogre clubtoe","qui est clubtoe"}},{q="Qui est Clugfist ?",a="Clugfist est le plus gros ogre que Clubtoe connaisse. Selon Clubtoe, il a quitté le Marteau du crépuscule avec de nombreux amis.",al={"clugfist","ogre clugfist","plus gros ogre"}},{q="Que me demande Clubtoe d’apporter ?",a="Clubtoe vous demande de rapporter la tête de Chogg'Zac à ses amis.",al={"tête de chogg","tête de chogg'zac","quoi apporter"}},{q="Où dois-je apporter la tête de Chogg'Zac ?",a="Vous devez remettre la tête de Chogg'Zac à Tran'gul, à Rog’mar.",al={"où apporter la tête","tran'gul","rog’mar"}},{q="Pourquoi Tran'gul est-il inquiet ?",a="Tran'gul apprend qu’un ogre du Marteau du crépuscule a fait défection et a parlé d’autres ogres de son espèce.",al={"réaction de tran'gul","grotte du crépuscule","pourquoi agir maintenant"}}},fp="15,178,22.329.0,18.202.1,15.99.0,16.109.0,34.62.0,33.59.0,26.94.0"}
P.entries["quest:95420"] = {n="Land of Giants",s="Un orc vous demande de porter la tête de Chogg dans une cité ogre des collines du nord. Cette offrande pourrait renouer un ancien lien avec les ogres.",h="Un orc vous demande de porter la tête de Chogg dans une cité ogre des collines du nord.",kw={"chogg","chogg’zac","clugfist","terre des géants","collines du nord","cité ogre","ogres","alliance orque"},ang={["race:Orc"]="En tant qu’orc, vous portez une offre ancrée dans l’histoire honorée des orcs combattant aux côtés des ogres."},sec={{t="Un ancien lien",b="Les orcs voient une occasion de renouer leur ancienne alliance avec les ogres. Selon les rapports, le clan vit dans un bastion des collines du nord, et la tête de Chogg doit parler en votre nom. Portez-la jusqu’à la cité ogre et offrez-la en gage d’amitié. Le clan pourrait entendre votre proposition, s’il ne vous piétine pas d’abord."},{t="À la porte de Clugfist",b="Dans la cité ogre, vous présentez la tête de Chogg à Clugfist. Il reconnaît que vous avez vaincu Chogg’Zac et vous demande ce que vous lui voulez. Votre offre d’amitié vous donne l’occasion de parler au chef du clan."}},faq={{q="Pourquoi est-ce que j’apporte la tête de Chogg aux ogres ?",a="Les orcs espèrent que la tête de Chogg servira de gage d’amitié et aidera à renouer leur ancienne alliance avec les ogres.",al={"tête de chogg","pourquoi prendre la tête de chogg","offrande d’une tête d’ogre"}},{q="Où se trouve le foyer du clan ogre ?",a="Selon les rapports, le bastion du clan se trouve dans les collines, très au nord.",al={"emplacement de la cité ogre","où sont les ogres","ogres des collines du nord"}},{q="Qui est Clugfist ?",a="Clugfist est l’immense ogre que vous rencontrez dans la cité ogre. Il vous demande ce que vous lui voulez.",al={"qui est clugfist","chef ogre","clug fist"}},{q="Qui est Chogg’Zac ?",a="Chogg’Zac est l’ogre que Clugfist dit que vous avez vaincu.",al={"chogg zac","histoire de chogg","qui est chogg"}},{q="Que veulent les orcs aux ogres ?",a="Les orcs espèrent faire appel à leur ancienne alliance avec les ogres et présenter une proposition au clan.",al={"alliance entre orcs et ogres","que veulent les orcs","amitié avec les ogres"}}},fp="14,143,11.313.0,20.218.1,46.114.0,32.68.0,16.87.0,19.56.0,37.92.0"}
P.entries["quest:95424"] = {n="Might Makes Right",s="Clugfist vous défie de prouver votre force à Bolder'ok. Les ogres du Marteau du crépuscule sont l'épreuve.",h="Clugfist vous défie de prouver votre force à Bolder'ok.",kw={"bolder'ok","clugfist","la force fait loi","ogres","skyborne","twilight firecallers","twilight maulers","marteau du crépuscule"},sec={{t="L'épreuve de Clugfist",b="Clugfist juge la force au sang et vous envoie affronter les Twilight Maulers et les Twilight Firecallers à Bolder'ok. Il doute de votre carrure, mais vous donne l'occasion de montrer ce que vous valez. Le défi oppose votre force à celle des ogres du crépuscule."}},faq={{q="Qui est Clugfist ?",a="Clugfist est l'ogre de Bolder'ok qui vous défie de prouver votre force.",al={"clugfist","qui est clugfist","ogre"}},{q="Que veut Clugfist ?",a="Clugfist vous demande de tuer des Twilight Maulers et des Twilight Firecallers à Bolder'ok.",al={"que veut clugfist","tâche de clugfist","que tuer"}},{q="Pourquoi Clugfist doute-t-il de moi ?",a="Clugfist vous traite de gringalet et doute de votre force.",al={"pourquoi douter de moi","trop petit","clugfist me croit faible"}},{q="À quoi ressemble Bolder'ok ?",a="Bolder'ok est l'endroit où Clugfist affirme que les ogres valorisent la force et le sang.",al={"bolderok","ogres de bolder'ok","que se passe-t-il ici"}}},fp="17,98,15.248.0,16.76.0,33.81.0,27.61.0,23.64.0"}
P.entries["quest:95427"] = {n="Twilight No More!",s="Clubtoe vous demande d’affronter Chogg'Zac dans la grotte de Clairsoleil. Il les accuse de la mort de ses amis et d’avoir promis de rendre les ogres forts.",h="Clubtoe vous demande d’affronter Chogg'Zac dans la grotte de Clairsoleil.",kw={"grotte","chogg'zac","clubtoe","amis","ogres","clairsoleil","crépuscule"},sec={{t="La supplique de Clubtoe",b="Clubtoe dit que ses amis sont morts et accuse Chogg'Zac. Ils avaient promis de rendre les ogres forts, mais il affirme qu’ils ont menti. Il vous demande donc de l’aider à se retourner contre eux dans la grotte de Clairsoleil. Il veut leurs têtes et ne brisera plus de rochers pour eux."},{t="Un nouveau nom",b="Après la mort de Chogg'Zac, Clubtoe crie victoire. Il dit qu’il en a fini de briser des rochers pour les petits et de perdre ses amis. Il déclare qu’il n’est plus du Crépuscule."}},faq={{q="Qui est Clubtoe ?",a="Clubtoe est un ogre qui affirme que Chogg'Zac avait promis de rendre les ogres forts. Il les accuse de la mort de ses amis.",al={"clubtoe","qui est clubtoe","histoire de clubtoe"}},{q="Pourquoi Clubtoe veut-il la mort de Chogg'Zac ?",a="Clubtoe affirme que Chogg'Zac a menti en promettant de rendre les ogres forts et les accuse de la mort de ses amis.",al={"pourquoi tuer chogg'zac","raison de chogg zac","quête de chogg'zac"}},{q="Où se trouve Chogg'Zac ?",a="Chogg'Zac se trouve dans la grotte de Clairsoleil.",al={"emplacement de chogg'zac","où se trouve chogg zac","grotte de clairsoleil"}},{q="Qu’attend Clubtoe de vous ?",a="Clubtoe vous demande de tuer Chogg'Zac et de rapporter leurs têtes.",al={"que veut clubtoe","quoi rapporter à clubtoe","têtes pour clubtoe"}}},fp="17,141,14.247.0,10.155.1,15.108.0,37.94.0,20.37.0,32.59.0"}
P.entries["quest:95428"] = {n="Clugfist's Decree",s="Après la défaite du Marteau du crépuscule par les Skyborne, Clugfist vous autorise à rester à Bolder'ok pour le moment. Il vous demande d'annoncer aux autres que le clan combattra de nouveau bientôt.",h="Après la défaite du Marteau du crépuscule par les Skyborne, Clugfist vous autorise à rester à Bolder'ok pour...",kw={"bolder'ok","clugfist","décret","horde","krom'rosh","rog’mar","skyborne","marteau du crépuscule"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pourriez voir les Bolder'ok devenir de puissants alliés si votre peuple continue de gagner leur confiance."},sec={{t="Message pour Rog’mar",b="Krom'rosh, à Rog’mar, attend de vos nouvelles. Clugfist vous laisse rester à Bolder'ok pour le moment et vous demande de transmettre un message aux autres Skyborne. Le clan s'attend à de nouveaux combats bientôt."},{t="Confiance et alliances",b="Krom'rosh voit le clan Bolder'ok comme un allié possible de la Horde. Leur récent combat pour se libérer du Marteau du crépuscule rappelle la propre histoire sanglante de la Horde. Votre rapport pourrait aider la Horde à continuer de gagner leur confiance."}},faq={{q="Que veut Clugfist que je fasse ?",a="Clugfist vous demande d'annoncer aux autres Skyborne que le clan Bolder'ok s'attend à combattre de nouveau bientôt.",al={"décret de clugfist","ce que je dois rapporter","ordres de clugfist"}},{q="À qui dois-je faire mon rapport ?",a="Clugfist vous demande de faire votre rapport à Krom'rosh, à Rog’mar.",al={"faire son rapport à krom'rosh","où se trouve krom'rosh","rapport à rog’mar"}},{q="Puis-je rester à Bolder'ok ?",a="Clugfist vous autorise à rester à Bolder'ok pour le moment.",al={"rester à bolder'ok","clugfist me laisse rester","autorisation pour bolder'ok"}},{q="Qui sont les Bolder'ok ?",a="Les Bolder'ok sont un clan qui a récemment combattu pour se libérer du Marteau du crépuscule.",al={"clan bolder'ok","qui est clugfist","peuple de clugfist"}},{q="Pourquoi la Horde s'intéresse-t-elle aux Bolder'ok ?",a="Krom'rosh pense que les Bolder'ok pourraient devenir de puissants alliés si la Horde continue de gagner leur confiance.",al={"horde et bolder'ok","alliés bolder'ok","pourquoi krom'rosh s'y intéresse"}}},fp="17,168,16.182.0,19.225.1,33.97.0,18.55.0,24.52.0,22.85.0,44.105.0"}
P.entries["quest:95433"] = {n="Death to the Executioner",s="Clugfist vous demande d’affronter Morg, l’ogre qui garde la sortie du Crépuscule. Il veut que vous rapportiez la masse de Morg à Bolder’ok.",h="Clugfist vous demande d’affronter Morg, l’ogre qui garde la sortie du Crépuscule.",kw={"bolder’ok","clugfist","crag’rog","morg le bourreau","masse de bourreau","morg","voile du crépuscule","marteau du crépuscule"},ang={["race:Tauren"]="En tant que taurène, vous êtes une petite taurène pleine de ruses, dit Clugfist après la mort de Morg."},sec={{t="Une issue",b="À Bolder’ok, Clugfist vous demande de vous mesurer à Morg, dans le Voile du Crépuscule. Le bourreau est un ogre presque aussi grand que Clugfist, qui dit compter sur de plus petits alliés pour le protéger. Rapportez-lui la masse, et le Marteau du Crépuscule saura que les ogres ne le défieront plus."},{t="La réponse de Bolder’ok",b="Crag’rog dit que vous vous êtes joint à lui dans le combat, et Clugfist vous demande ce que vous rapportez. Morg est mort, et Clugfist loue vos ruses. Il dit que le Marteau du Crépuscule s’est effondré devant la puissance de Bolder’ok, et que les ogres sont libres."}},faq={{q="Qui est Morg ?",a="Morg est un bourreau dans le Voile du Crépuscule, un ogre presque aussi grand que Clugfist.",al={"qui est morg","morg le bourreau","ogre du crépuscule"}},{q="Pourquoi Clugfist veut-il la mort de Morg ?",a="Clugfist dit que Morg lui barre la route alors qu’il quitte le Crépuscule, et que Morg compte sur de plus petits alliés pour le protéger.",al={"pourquoi tuer morg","clugfist veut morg","problème de morg"}},{q="Que veut Clugfist que vous rapportiez ?",a="Clugfist veut que vous lui rapportiez la masse de bourreau de Morg à Bolder’ok.",al={"masse de morg","que rapporter","masse de bourreau"}},{q="Où se trouve Morg ?",a="Morg se trouve dans le Voile du Crépuscule.",al={"emplacement de morg","où est le bourreau","voile du crépuscule"}}},fp="24,122,9.288.0,22.227.1,12.83.0,33.114.0,42.76.0,14.31.0"}
P.entries["quest:95494"] = {n="Bruised Pride and Lion Hides",s="Une blessure empêche un chasseur ou un artisan de récolter des peaux de lion pour un tanneur local. Il fait appel à vous pour respecter son accord commercial et préserver sa réputation professionnelle.",h="Une blessure empêche un chasseur ou un artisan de récolter des peaux de lion pour un tanneur local.",kw={"bruised pride and lion hides","chasse","articles en cuir","peaux de lion","tanneur","commerce"},sec={{t="Le dilemme d’un Chasseur",b="Un chasseur ou un artisan est blessé et ne peut plus traquer les bêtes sauvages sans danger. Son accord avec un artisan du voisinage arrive à échéance ; il vous engage donc pour chasser des lions sauvages et récolter leurs peaux."},{t="Honorer l’accord",b="Les peaux brutes sont remises à un tanneur local, qui les échange contre des articles en cuir finis dont le donneur de quête a besoin pour vivre. Le donneur est blessé dans son orgueil de devoir demander de l’aide, mais respecter l’accord lui permet de préserver sa réputation professionnelle."}},faq={{q="De quoi parle cette quête ?",a="Un chasseur ou un commerçant blessé a besoin de peaux de lion pour approvisionner un tanneur local. En échange, le donneur de quête reçoit des articles en cuir finis, essentiels à ses moyens de subsistance.",al={"sens de bruised pride and lion hides","objectif de la quête","à quoi servent les peaux de lion"}},{q="Pourquoi le donneur de quête a-t-il besoin d’aide pour récolter les peaux ?",a="Une blessure empêche le donneur de quête de chasser les lions lui-même. Il compte sur vous pour respecter un accord de longue date avec un tanneur local.",al={"pourquoi a-t-il besoin d’aide","pourquoi ne peut-il pas chasser"}},{q="Qui reçoit les peaux de lion ?",a="Un tanneur local reçoit les peaux brutes et les transforme en articles en cuir finis dont le donneur de quête a besoin pour son commerce et son travail habituels.",al={"qui reçoit les peaux de lion","où vont les peaux"}},{q="Que signifie le nom « Bruised Pride and Lion Hides » ?",a="Le nom fait référence à la fois à une troupe de lions à chasser et à la fierté du chasseur blessé. Le chasseur n’a jamais manqué à un contrat, mais sa blessure le limite désormais.",al={"signification de bruised pride","pourquoi bruised pride"}},{q="L’accord avec le tanneur était-il menacé ?",a="Oui. La blessure compromet la prochaine livraison du donneur de quête. Récolter les peaux de lion lui permet de respecter son engagement sans être en défaut.",al={"accord avec le tanneur maintenu","accord commercial rompu"}},{q="Comment le donneur de quête a-t-il été blessé ?",a="Le donneur de quête a subi une blessure qui l’empêche de chasser les lions dans la nature. Sa cause exacte n’est pas précisée, et livrer les peaux lui permet de préserver sa réputation.",al={"blessure du donneur de quête","qu’est-il arrivé au chasseur"}}},fp="28,174,18.195.0,24.236.0,25.157.0,51.130.0,28.128.0,55.170.0,44.136.0,32.171.0"}
P.entries["quest:95495"] = {n="The Hermit Tanner",s="Vous portez des peaux brutes à The Hermit Tanner, qui vit au-dessus des Collines arides, dans les Tarides. Vrang ne peut pas gravir la pente et vous envoie chez son partenaire commercial reclus.",h="Vous portez des peaux brutes à The Hermit Tanner, qui vit au-dessus des Collines arides, dans les Tarides.",kw={"les tarides","tas de peaux","les collines arides","the hermit tanner","crête","tanneur","vrang"},ang={["faction:Horde"]="Dans les Tarides, vous pouvez aider des commerçants comme Vrang à transporter des marchandises à travers la savane accidentée."},sec={{t="Une crête dans les Tarides",b="Dans les Tarides, Vrang fait affaire avec un tanneur qui vit sur une crête au-dessus des Collines arides. La montée raide et rocailleuse est trop difficile pour Vrang. Il demande donc aux voyageurs de passage de porter des peaux brutes jusqu'à la propriété de son partenaire."},{t="Un artisan peu ordinaire",b="Vrang vous prévient que l'apparence inhabituelle du tanneur solitaire pourrait vous surprendre, mais qu'il ne présente aucun danger pour les visiteurs. Quand vous apportez les peaux sur la crête, l'ermite vous accueille chaleureusement. Il regrette que Vrang n'ait pas pu venir lui-même, car il espérait discuter de quelque chose avec le commerçant."}},faq={{q="Qui vous confie cette livraison ?",a="Vrang vous confie un tas de peaux brutes à porter à son partenaire commercial, sur la crête au-dessus des Collines arides.",al={"qui envoie chez le tanneur ermite","où commencer la quête","livraison de vrang"}},{q="Où vit le tanneur ermite ?",a="Le tanneur ermite vit seul dans une propriété isolée, au sommet d'une crête qui surplombe les Collines arides, dans les Tarides.",al={"emplacement du tanneur ermite","où se trouve le tanneur ermite","ermite de la crête"}},{q="Pourquoi Vrang vous prévient-il au sujet de l'apparence du tanneur ?",a="Vrang vous prévient que l'apparence inhabituelle du tanneur pourrait vous surprendre, mais vous assure qu'il ne présente aucun danger pour les visiteurs.",al={"apparence de l'ermite","pourquoi l'ermite fait peur"}},{q="Pourquoi Vrang n'a-t-il pas pu gravir la pente lui-même ?",a="La montée raide et rocailleuse est trop éprouvante pour Vrang. Il demande donc à un voyageur de passage de porter les peaux.",al={"pourquoi faire cette livraison","pourquoi vrang ne peut pas y aller"}},{q="Quels objets sont apportés sur la crête ?",a="Vous portez un tas de peaux brutes pour le commerce de tannage de l'ermite, qu'il partage avec Vrang.",al={"qu'est-ce que le tas de peaux","objets à livrer pour la quête"}},{q="De quoi le tanneur ermite souhaite-t-il parler avec Vrang ?",a="L'ermite regrette que Vrang n'ait pas pu venir en personne et dit qu'il a quelque chose à discuter avec lui.",al={"que veut discuter le tanneur avec vrang","affaires du tanneur avec vrang"}}},fp="17,169,22.210.0,27.293.0,31.100.0,34.108.0,54.122.0,42.107.0,44.89.0,55.101.0"}
P.entries["quest:955"] = {n="Bashal'Aran",s="La magie retient toujours Asterion sous les pierres brisées de Bashal'Aran. Cet ancien Elfe de la nuit cherche à quitter sa forme fantomatique et soupçonne les grells d'avoir touché le sceau qui le retient. Il demande aux voyageurs de ramasser leurs boucles d'oreilles pour en suivre la magie persistante.",h="La magie retient toujours Asterion sous les pierres brisées de Bashal'Aran.",kw={"asterion","bashal'aran","lien","sombrivage","fantôme","grell","boucle d'oreille de grell","sceau"},ang={["class:Mage"]="Si vous êtes mage, vous reconnaîtrez peut-être dans l'usage que fait Asterion de breloques enchantées pour suivre une magie persistante une ancienne pratique de divination des Highborne.",["faction:Alliance"]="En tant que voyageur de l'Alliance, vous contribuez à pacifier les dangereux confins nord de Sombrivage en éliminant les grells chaotiques autour de Bashal'Aran.",["race:NightElf"]="En tant que Kaldorei, vous verrez peut-être en Asterion un rappel de l'ancienne civilisation perdue lors du Sundering et des âmes liées aux ruines depuis des millénaires."},sec={{t="Un tourment séculaire",b="Depuis des siècles, Asterion attend parmi les marbres brisés de Bashal'Aran. L'esprit de cet ancien Elfe de la nuit reste prisonnier entre la vie et la véritable mort, sous la canopée de Sombrivage. Des arcanes le lient à la colonie en ruine, et il ne peut se libérer seul. La solitude et le désespoir ont usé son esprit."},{t="Des traces dans la nature",b="Asterion pense qu'un ancien sceau dissimulé dans les ruines pourrait le libérer. Il ne peut fouiller lui-même les broussailles et les pierres effondrées. Les grells sauvages de Bashal'Aran y cherchent leur nourriture et dérobent de petits bibelots. Il demande donc aux voyageurs de ramasser leurs boucles d'oreilles. Il espère que la magie persistante de ces breloques le mènera au sceau qui tourmente son âme."}},faq={{q="Qui est Asterion ?",a="Asterion est un ancien fantôme Elfe de la nuit lié aux ruines de Bashal'Aran, à Sombrivage. Un sceau mystique le tourmente depuis des siècles, et il aspire à être libéré de sa forme spectrale.",al={"histoire d'asterion","qui est le fantôme de bashal'aran","asterion donneur de quête"}},{q="Pourquoi Asterion veut-il des boucles d'oreilles de grell ?",a="Asterion pense que les grells ont touché le sceau qui le retient. Leurs boucles d'oreilles pourraient porter des traces de sa magie et l'aider à le retrouver.",al={"pourquoi les boucles d'oreilles de grell","utilité des boucles d'oreilles de grell","quête des boucles d'oreilles à sombrivage"}},{q="Qu'est-ce que Bashal'Aran ?",a="Bashal'Aran se trouve sur la côte boisée de Sombrivage. Ces ruines elfiques de la nuit remontent à l'époque précédant le Sundering. Des grells sauvages, des satyrs et les spectres des habitants tombés au combat y rôdent.",al={"qu'est-ce que bashal'aran","histoire de bashal'aran","ruines de bashal'aran"}},{q="Que se passe-t-il après avoir ramassé les boucles d'oreilles ?",a="Une fois les boucles d'oreilles ramassées, Asterion les examine. Il sent que les grells ont frôlé le sceau à une époque qu'il juge récente, même s'ils ne le portent pas. Cela lui permet de mieux cerner son emplacement dans les ruines.",al={"que révèlent les boucles d'oreilles","les grells avaient-ils le sceau","résultat des boucles d'oreilles de grell"}},{q="Pourquoi Asterion est-il piégé ici ?",a="Un ancien sceau magique a lié Asterion à Bashal'Aran il y a des siècles. Il ancre son esprit aux ruines et l'empêche de trouver le repos éternel.",al={"qui a lié asterion","comment asterion est-il lié","sceau d'asterion"}},{q="Que sont les grells ?",a="Les grells sont de petites créatures malveillantes des forêts de Kalimdor. Ils ont des griffes acérées, convoitent les bibelots et infestent souvent les vieilles ruines, où ils attaquent les voyageurs.",al={"qu'est-ce qu'un grell","histoire des grells","grells de sombrivage"}}},fx={["99bf1a9e"]={q="Pourquoi Asterion veut-il que cela soit fait ?",a="Asterion est piégé dans une forme spectrale agonisante, ancrée aux ruines de Bashal'Aran par un sceau magique ancien. Un confinement séculaire a lentement érodé sa santé mentale, et il aspire à être libéré de ce tourment. En examinant les boucles d'oreilles portées par les créatures locales, il espère scruter magiquement l'emplacement précis de la protection qui l'enchaîne afin qu'elle puisse finalement être détruite.",al={"motivation d'asterion","pourquoi aider asterion","pourquoi asterion veut-il des boucles d'oreilles"}},a8a71265={q="Pourquoi Asterion a-t-il besoin de votre aide plutôt que d'agir lui-même ?",a="Asterion est un fantôme insubstantiel lié directement aux ruines par une puissante sorcellerie. Incapable de s'aventurer bien au-delà de son lieu de repos immédiat ou de combattre physiquement les grells et les sprites lui-même, il compte entièrement sur les mortels de passage pour traquer les créatures et rassembler leurs bibelots pour ses divinations.",al={"pourquoi asterion a-t-il besoin de moi","pourquoi asterion ne peut-il pas obtenir les boucles d'oreilles","pourquoi asterion ne peut-il pas partir"}}},fp="11,257,23.299.0,18.346.0,16.183.0,38.133.0,20.187.0,43.223.1,29.145.0,16.164.0"}
P.entries["quest:95507"] = {n="Vrang's Game",s="Vrang vous envoie vérifier ses pièges dans une vallée des Tarides. Le petit gibier capturé peut l’aider, mais la faune rend les lieux dangereux.",h="Vrang vous envoie vérifier ses pièges dans une vallée des Tarides.",kw={"tarides","petit gibier","gibier piégé","pièges","vallée","vrang","faune"},sec={{t="Les pièges de Vrang",b="Vrang a placé des pièges dans toute la vallée et vous demande de rapporter le petit gibier qu’ils ont capturé. Restez attentif à la faune, qui peut aussi rendre les lieux dangereux."}},faq={{q="Que veut Vrang ?",a="Vrang veut que vous vérifiiez ses pièges et rapportiez le petit gibier qu’ils ont capturé.",al={"pièges de vrang","gibier de vrang","de quoi vrang a-t-il besoin"}},{q="Où se trouvent les pièges de Vrang ?",a="Les pièges de Vrang sont dispersés dans une vallée des Tarides.",al={"où sont les pièges","emplacement des pièges","pièges des tarides"}},{q="Qu’est-ce qui est dangereux près des pièges ?",a="La faune près des pièges peut être dangereuse si vous n’y prêtez pas attention.",al={"danger à proximité","autres animaux","danger de la faune"}}},fp="12,154,13.185.0,21.82.0,24.59.0,35.81.0"}
P.entries["quest:95508"] = {n="Unwelcome Guests",s="Vous avez aidé quelqu’un à survivre à une rencontre avec des invités indésirables. Cette personne vous en est reconnaissante, mais ce qui vous a réunis reste flou.",h="Vous avez aidé quelqu’un à survivre à une rencontre avec des invités indésirables.",kw={"dette","aide","survivre","remerciements","unwelcome guests"},faq={{q="Que s’est-il passé ici ?",a="Vous avez aidé la personne qui vous parle à survivre à une rencontre, mais elle n’en dit rien de plus.",al={"ce qui s’est passé","unwelcome guests","problèmes avec des invités"}},{q="Qui me remercie ?",a="La personne qui vous remercie n’est pas nommée.",al={"qui est cette personne","qui m’a remercié","donneur de quête"}},{q="Pourquoi vous suis-je redevable ?",a="La personne qui vous parle dit que vous l’avez aidée à survivre, mais n’explique pas ce qui s’est passé.",al={"pourquoi remercier","pourquoi cette dette","l’aider"}}},fp="16,128,19.82.0,19.40.0,24.77.0"}
P.entries["quest:95534"] = {n="Strahnbrad Mystery",s="Une note roussie vous demande d’enquêter sur d’étranges phénomènes autour du vieux soufflet de Strahnbrande. Faites votre rapport à Hautebrande.",h="Une note roussie vous demande d’enquêter sur d’étranges phénomènes autour du vieux soufflet de Strahnbrande.",kw={"élémentaire de feu","magie du feu","hautebrande","vieux soufflet","note roussie","strahnbrande","mystère de strahnbrande"},sec={{t="La note roussie",b="Une note trouvée à Strahnbrande avertit que le vieux soufflet semble bouger quand personne ne le regarde. Son auteur n’y voit qu’une histoire de fantômes, mais insiste pour que vous découvriez la vérité avant son retour. Selon cette personne, une grande puissance réside à Strahnbrande, et la magie du feu a consumé le reste du message."},{t="Vos découvertes",b="À Hautebrande, les habitants écoutent votre rapport sur le vieux soufflet de Strahnbrande. Un élémentaire de feu y vivait, mais la façon dont il s’y est retrouvé reste un mystère."}},faq={{q="Qu’a donc d’étrange le vieux soufflet ?",a="Une note roussie affirme que le vieux soufflet de Strahnbrande s’anime quand personne ne le regarde.",al={"mystère du vieux soufflet","soufflet qui bouge","soufflet de strahnbrande"}},{q="Qui a laissé la note ?",a="La note ne donne pas le nom de son auteur ; elle indique que cette personne reviendra.",al={"qui a écrit la note","auteur de la note roussie","note mystérieuse"}},{q="Que dit la note au sujet de Strahnbrande ?",a="Son auteur pense qu’une grande puissance réside à Strahnbrande.",al={"puissance de strahnbrande","grande puissance sur place","que trouve-t-on à strahnbrande"}},{q="Où dois-je faire mon rapport ?",a="On vous demande de faire votre rapport en ville, à Hautebrande.",al={"où faire son rapport","rapport à hautebrande","rapport en ville"}}},fp="18,128,15.291.0,13.167.1,38.90.0,18.60.0,40.51.0,30.59.0"}
P.entries["quest:956"] = {n="Bashal'Aran",s="Parmi les piliers en ruine de Bashal'Aran, Asterion cherche à se libérer de sa prison. Il a retracé la magie qui le lie jusqu'aux satyres qui commandent les grells. Il demande maintenant aux voyageurs de récupérer l'Ancien sceau de pierre de lune.",h="Parmi les piliers en ruine de Bashal'Aran, Asterion cherche à se libérer de sa prison.",kw={"ancien sceau de pierre de lune","asterion","bashal'aran","sombrivage","grell","kaldorei","fantôme elfe de la nuit","satyre"},ang={["class:Druid"]="En tant que druide, vous savez que l'influence des satyres continue de corrompre la faune de Sombrivage. Elle trouble aussi les esprits anciens qui devraient reposer en paix dans le cycle de la nature.",["faction:Alliance"]="En tant que membre de l'Alliance, vous contribuez à sécuriser la côte nord de Kalimdor en purifiant les ruines de Sombrivage de la corruption des satyres. Ce travail aide aussi les Kaldorei à faire le deuil de leur passé tragique.",["race:NightElf"]="En tant qu'elfe de la nuit, Bashal'Aran vous rappelle le passé ancien de votre peuple. Des ancêtres persistants restent enchaînés à la terre par les satyres, dont la nature incarne la trahison démoniaque du Fracture."},sec={{t="Une prison de pierre ancienne",b="Depuis plus de mille ans, Asterion est retenu dans les ruines de Bashal'Aran. Les piliers de marbre délimitent sa prison. Ni sa force ni son ancienne magie ne peuvent l'en faire sortir. Une relique maudite le retient là.\n\nAu fil des siècles, Asterion a contemplé la canopée de Sombrivage. Il se demande si la pierre usée qui l'entoure pourra un jour le libérer."},{t="Les satyres et le sceau de pierre de lune",b="Les grells des environs portaient des traces de la magie qui lie Asterion. Il en a déduit que l'Ancien sceau de pierre de lune était à l'origine de l'enchantement. Les satyres qui commandent les grells détiennent maintenant le sceau. Ces elfes de la nuit démoniaques rôdent dans les bosquets anciens et veillent sur la relique. Asterion a besoin que des voyageurs récupèrent le sceau pour briser le pouvoir qui le retient."}},faq={{q="Qui est Asterion ?",a="Asterion est un ancien esprit elfe de la nuit, piégé parmi les piliers en ruine de Bashal'Aran. Une magie ancienne le retient depuis plus de mille ans, l'empêchant de quitter sa prison de pierre ou de passer dans l'au-delà.",al={"qui est asterion","histoire d'asterion","fantôme de bashal'aran"}},{q="Pourquoi les satyres ont-ils l'Ancien sceau de pierre de lune ?",a="Les satyres commandent les grells sauvages du nord de Sombrivage. Asterion a senti des traces de la magie qui le lie chez les grells, puis en a déduit que les satyres détenaient l'Ancien sceau de pierre de lune, à l'origine de sa captivité.",al={"pourquoi les satyres ont le sceau","sceau de pierre de lune des satyres","ancien sceau de pierre de lune"}},{q="Que se passe-t-il une fois le sceau récupéré ?",a="Quand Asterion prend l'Ancien sceau de pierre de lune récupéré, la relique qui l'a retenu pendant des siècles, celle-ci peut être brisée. Il pourra alors parcourir de nouveau les forêts en toute liberté.",al={"à quoi sert le sceau","récupérer le sceau"}},{q="Qu'est-ce que Bashal'Aran ?",a="Bashal'Aran est une ancienne ruine elfe de la nuit sur les rives brumeuses du nord de Sombrivage. Autrefois magnifique cité ou enclave sacrée, elle gît désormais en ruines, infestée de grells et de satyres, et hantée par des esprits prisonniers d'une époque révolue.",al={"histoire de bashal'aran","qu'est-ce que bashal'aran"}},{q="Depuis combien de temps Asterion est-il prisonnier ici ?",a="Asterion est prisonnier depuis plus de mille ans. Ni sa force ni sa magie ne peuvent franchir la limite, et au fil des siècles, il s'est demandé s'il serait un jour libre.",al={"quel âge a asterion","depuis combien de temps prisonnier"}},{q="Asterion peut-il simplement quitter le sanctuaire ?",a="Non. L'Ancien sceau de pierre de lune maintient une barrière autour du sanctuaire, et les piliers de pierre empêchent l'esprit d'Asterion de les franchir.",al={"asterion peut-il partir","pourquoi le fantôme est-il prisonnier"}}},fx={["31aed888"]={q="Pourquoi Asterion veut-il que le sceau soit récupéré ?",a="Asterion est désespéré d'obtenir sa liberté. La relique antique sert d'ancre de liaison à sa prison éternelle, maintenant son esprit piégé dans le sanctuaire en ruine. Pendant plus de mille ans, il a regardé au-delà des piliers de pierre, incapable de briser leur emprise par la force ou la sorcellerie. Récupérer l'artefact est le seul moyen de le détruire et de lui permettre enfin de marcher librement dans les forêts une fois de plus.",al={"pourquoi asterion veut-il que cela soit fait","motivation d'asterion","pourquoi aider asterion"}},["5f1ff286"]={q="Qu'est-ce que l'Ancien sceau de pierre de lune ?",a="L'Ancien sceau de pierre de lune est une relique magique qui sert de clé à la captivité d'Asterion. Il crée une barrière intangible entre les piliers de Bashal'Aran, fonctionnant comme une cellule éternelle qu'aucun sortilège ni aucune force physique ne peut briser. Tant que le sceau demeure entre les mains des forces corrompues des environs, Asterion reste lié au sanctuaire.",al={"qu'est-ce que l'ancien sceau de pierre de lune","que fait l'ancien sceau de pierre de lune","but de l'ancien sceau de pierre de lune"}},c7650517={q="Pourquoi êtes-vous envoyé contre les satyres locaux ?",a="Les satyres commandent les vils grells qui infestent les ruines de Bashal'Aran. Comme les moindres grells portaient des traces de l'enchantement du sceau, Asterion en a déduit que leurs maîtres devaient avoir récupéré l'artefact lui-même. Corrompus et attirés par les reliques magiques antiques, les satyres détiennent le sceau dans leur campement, ce qui en fait votre cible.",al={"qui sont les satyres à bashal'aran","pourquoi combattre les satyres","qui a le sceau"}},["341831b6"]={q="Pourquoi Asterion ne peut-il pas récupérer le sceau lui-même ?",a="Asterion ne peut pas quitter l'enceinte du sanctuaire. La magie du sceau le maintient totalement lié dans son périmètre, traitant les piliers de pierre comme des barreaux infranchissables. Il ne possède ni la force ni la sorcellerie pour briser son confinement, ce qui le laisse totalement dépendant d'un étranger pour s'aventurer dans les camps de satyres en son nom.",al={"pourquoi asterion a-t-il besoin de moi","pourquoi asterion ne peut-il pas obtenir le sceau","pourquoi moi asterion"}}},fp="11,211,25.361.0,29.356.0,16.200.0,50.207.0,40.163.1,20.218.0,40.178.0,46.141.0"}
P.entries["quest:95601"] = {n="The Purple Ones",s="Clubtoe vous demande d’interrompre les rites du Marteau du crépuscule à Clairsoleil. Ils renforcent certains ogres et en tuent d’autres.",h="Clubtoe vous demande d’interrompre les rites du Marteau du crépuscule à Clairsoleil.",kw={"clubtoe","empowered brutes","ogre","clairsoleil","purple ones","twilight ritualists","marteau du crépuscule"},sec={{t="Les rites de Clairsoleil",b="À Clairsoleil, Clubtoe vous envoie affronter les Twilight Ritualists et les Empowered Brutes. Un ogre mort semble être l’un des amis que Clubtoe recherchait. Les rites renforcent certains membres et en tuent davantage, alors Clubtoe veut arrêter les ritualistes et leurs créations avant qu’ils ne se répandent."}},faq={{q="Qui est Clubtoe ?",a="Clubtoe vous demande d’arrêter les Twilight Ritualists à Clairsoleil.",al={"clubtoe","qui est clubtoe"}},{q="Que font les Purple Ones ?",a="Les Twilight Ritualists accomplissent des rites sur leurs membres. Certains sont renforcés, tandis que davantage sont tués.",al={"purple ones","que font les purple ones"}},{q="Pourquoi Clubtoe veut-il arrêter les rites ?",a="Clubtoe craint que les ritualistes et leurs monstruosités ne se répandent.",al={"pourquoi arrêter les rites","pourquoi tuer les ritualistes"}},{q="Qu’est-il arrivé aux amis de Clubtoe ?",a="Un ogre mort semble être l’un des amis que Clubtoe recherchait.",al={"amis de clubtoe","où sont les amis"}},{q="Où se trouve Clubtoe ?",a="Clubtoe se trouve à Clairsoleil.",al={"emplacement de clubtoe","clubtoe à clairsoleil"}}},fp="15,111,19.274.0,15.76.0,31.98.0,42.65.0,35.71.0,17.25.0"}
P.entries["quest:95602"] = {n="Sickening Lights",s="Clubtoe vous demande de briser les cercles rituels lumineux sous Clairsoleil. Leur lumière le rend malade, et il craint la colère de Chogg'Zac s'il agit seul.",h="Clubtoe vous demande de briser les cercles rituels lumineux sous Clairsoleil.",kw={"grottes","chogg'zac","clubtoe","lumière","dessins brillants","lumières écœurantes","clairsoleil","cercles rituels du crépuscule"},sec={{t="Une lueur écœurante",b="Clubtoe travaille dans les grottes sous Clairsoleil, où il casse des rochers pour Chogg'Zac. Il découvre des lumières brillantes dans la pierre, et les autres dessinent avec elles. Leur lueur rend Clubtoe malade, mais il craint que Chogg'Zac le punisse s'il détruit les dessins. On vous demande de détruire les Cercles rituels du Crépuscule, et Clubtoe espère que la lumière ne le tourmentera plus."}},faq={{q="Qui me demande de briser les cercles ?",a="Clubtoe vous demande de détruire les Cercles rituels du Crépuscule sous Clairsoleil.",al={"qui est clubtoe","quête de clubtoe","qui veut détruire les lumières"}},{q="Pourquoi Clubtoe veut-il que les lumières soient détruites ?",a="La lumière rend Clubtoe malade, et il veut briser les dessins lumineux.",al={"pourquoi détruire les lumières","les lumières rendent clubtoe malade","clubtoe déteste la lumière"}},{q="Qui est Chogg'Zac ?",a="Chogg'Zac est le patron de Clubtoe, et Clubtoe craint qu'il se mette en colère si les cercles sont brisés.",al={"chogg'zac","patron de clubtoe","grand patron"}},{q="Que sont ces dessins brillants ?",a="Ce sont des Cercles rituels du Crépuscule que l'on trouve dans les grottes sous Clairsoleil. Clubtoe les appelle des dessins lumineux.",al={"dessins brillants","cercles du crépuscule","que sont les lumières"}},{q="Que fait Clubtoe dans les grottes ?",a="Clubtoe casse des rochers pour Chogg'Zac et a découvert une lumière brillante dans la pierre.",al={"travail de clubtoe","casser des rochers","que fait clubtoe"}},{q="Clubtoe se sent-il mieux une fois les cercles brisés ?",a="Après que vous avez brisé les cercles, Clubtoe dit qu'il se sent déjà mieux.",al={"fin de la quête de clubtoe","est-ce que les briser a aidé","la lumière le fait se sentir mieux"}}},fp="16,147,16.364.0,38.75.0,41.78.0,17.90.0,28.116.0,34.76.0,55.66.0"}
P.entries["quest:95621"] = {n="Trouble in the Valley",s="Une escouade de soldats kultirassiens fouille la vallée, pour des raisons inconnues. Ils ont établi leur camp près d’une caravane détruite au sud, attirant l’attention des éclaireurs locaux.",h="Une escouade de soldats kultirassiens fouille la vallée, pour des raisons inconnues.",kw={"caravane","kul tiras","soldats","trouble in the valley","vallée","caravane détruite"},ang={["race:Human"]="En tant qu’humain, vous reconnaîtrez peut-être les couleurs vert marin et celles de l’ancre de Kul Tiras. Les soldats de cette nation maritime isolationniste sont un spectacle rare et inattendu dans la vallée."},sec={{t="Activité suspecte dans la vallée",b="Un fusilier qui surveillait les basses terres a repéré des soldats humains qui fouillaient le fond de la vallée. Dans sa lunette, il a reconnu les armoiries et la livrée de Kul Tiras. Les étrangers armés opèrent rarement aussi ouvertement ici, et leur présence a donné l’alerte."},{t="La caravane détruite",b="Les soldats ont établi leur camp près d’une caravane en ruine au sud. Ce qu’ils cherchent parmi les débris reste inconnu. Les observateurs locaux jugent leur présence armée préoccupante et immédiate. Des enquêteurs sont donc envoyés pour les éliminer et découvrir le but de leurs recherches."}},faq={{q="Que font des soldats kultirassiens dans la vallée ?",a="Un tireur d’élite a repéré des soldats kultirassiens qui fouillaient la vallée en contrebas. Ils ont établi leur camp près d’une caravane détruite au sud, et des éclaireurs locaux sont envoyés pour découvrir leurs intentions.",al={"pourquoi des kultirassiens ici","soldats de kul tiras dans la vallée","que font les kultirassiens"}},{q="Où se trouve le camp kultirassien ?",a="Les soldats kultirassiens ont établi leur camp près d’une caravane en ruine, au sud du point d’observation qui surplombe la vallée.",al={"emplacement de la caravane détruite","où se trouve le camp de kul tiras","site de la caravane"}},{q="Comment la présence des Kultirassiens a-t-elle été découverte ?",a="Un éclaireur qui surveillait la vallée a observé le groupe d’humains à travers la lunette d’un fusil et a reconnu Kul Tiras à ses uniformes et à ses insignes.",al={"comment les identifier","livrée de kul tiras"}},{q="Quel est l’objectif de l’enquête sur le camp ?",a="Vous êtes envoyé au sud, près de la caravane détruite, pour affronter les soldats kultirassiens et découvrir ce qui les a poussés à fouiller la région.",al={"quel est l’objectif","objectifs de trouble dans la vallée"}},{q="Pourquoi les soldats kultirassiens sont-ils considérés comme des ennemis ?",a="Ces soldats sont des étrangers armés qui fouillent les environs d’une caravane détruite sans donner d’explication. Les éclaireurs les considèrent comme une menace à neutraliser afin de découvrir leurs intentions.",al={"pourquoi combattre kul tiras","les kultirassiens sont-ils hostiles"}},{q="Qui a repéré les soldats dans la vallée ?",a="Walton, l’ermite tanneur qui surveillait la vallée, a repéré les soldats à travers la lunette de son fusil. Il a engagé un aventurier pour les éliminer et découvrir ce qu’ils faisaient là.",al={"qui a repéré les soldats","qui a donné la quête"}}},fp="21,177,33.236.0,19.264.0,48.174.0,36.100.0,42.130.0,48.127.0,50.180.0,40.164.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="Rethiel le Gouverneur vert sent une corruption s'écouler par un ravin de montagne jusque dans l'eau douce des Paluns. Il vous envoie chercher le noyau de racine d'une Horreur des hautes-terres sur les sites de fouilles, puis vous avertit que creuser réveille une énergie ancienne et met toute la région en danger.",h="Rethiel le Gouverneur vert sent une corruption s'écouler par un ravin de montagne jusque dans l'eau douce des...",kw={"corruption","sites de fouilles","horreur des hautes-terres","horrors in the highland","rethiel","rethiel le gouverneur vert","noyau de racine","les paluns"},ang={["class:Druid"]="En tant que druide, vous sentez l'équilibre naturel changer à travers les racines et les cours d'eau. Vous pouvez reconnaître la menace soudaine que la corruption ancienne fait peser sur la vie en eau douce.",["faction:Alliance"]="En tant qu'explorateur de l'Alliance, vous savez que les prospecteurs des sites de fouilles en montagne risquent de réveiller des forces anciennes enfouies sous terre.",["race:Dwarf"]="En tant que nain, vous savez que creuser dans les hautes-terres a dérangé bien plus que de vieilles reliques. Rethiel exhorte les excavateurs à s'arrêter avant que de pires fléaux ne s'éveillent."},sec={{t="Souillure dans le ravin",b="Rethiel le Gouverneur vert sent la terre changer au cœur des Paluns. Une souillure infecte les hautes-terres et leurs créatures d'eau douce en passant par un ravin de montagne. La vie des basses-terres s'est adaptée à l'eau saumâtre, mais ces créatures n'ont jamais connu le sel protecteur de la mer. Rethiel craint qu'elles ne puissent résister au mal qui se propage. Il vous demande de grimper jusqu'aux sites de fouilles, de tuer une Horreur des hautes-terres et de rapporter son noyau de racine."},{t="Un ancien réveil",b="Quand vous rapportez à Rethiel le noyau de racine de l'Horreur des hautes-terres, il confirme ses craintes : une énergie ancienne commence à s'agiter. Les créatures des hautes-terres ne souffrent pas d'une maladie ordinaire. Les fouilles récentes ont déclenché leur mal. Rethiel avertit les excavateurs de cesser immédiatement. Leur curiosité pourrait libérer quelque chose de bien pire dans les Paluns et mettre toute la région en danger."}},faq={{q="Qui propose la quête Horrors in the Highland ?",a="Rethiel le Gouverneur vert, ancien protecteur des Paluns, vous confie cette tâche après avoir senti une corruption s'infiltrer par un ravin de montagne voisin.",al={"qui donne horrors in the highland","donneur de quête horrors in the highland","quête de rethiel"}},{q="Où trouver les Horreurs des hautes-terres ?",a="Les Horreurs des hautes-terres vivent sur les sites de fouilles, en altitude au-dessus des basses-terres, près du ravin de montagne où s'infiltre la corruption.",al={"où trouver les horreurs des hautes-terres","emplacement de l'horreur des hautes-terres","où trouver une horreur des hautes-terres"}},{q="Pourquoi les créatures des hautes-terres sont-elles si vulnérables à la corruption ?",a="Les créatures d'eau douce des hautes-terres n'ont jamais connu le sel protecteur de la mer, ce qui les laisse sans défense face à la corruption qui se propage.",al={"pourquoi les créatures sont souillées","pourquoi les créatures des hautes-terres sont corrompues","corruption de l'eau sans sel"}},{q="Qu'est-ce que le noyau de racine d'une Horreur des hautes-terres ?",a="Le noyau de racine d'une Horreur des hautes-terres est le cœur de la créature corrompue. Rethiel en a besoin pour examiner le pouvoir surnaturel qui se répand dans les cours d'eau et découvrir la nature de la corruption.",al={"qu'est-ce que le noyau de racine","noyau de l'horreur des hautes-terres","pourquoi rapporter le noyau de racine"}},{q="Que découvre Rethiel quand vous lui rapportez le noyau de racine ?",a="Quand vous lui rapportez le noyau de racine, Rethiel découvre qu'une énergie ancienne commence à s'agiter au plus profond de la terre, probablement réveillée par les fouilles.",al={"que découvre rethiel","énergie ancienne des paluns","danger des fouilles"}},{q="Pourquoi Rethiel veut-il que les excavateurs cessent de creuser ?",a="Rethiel avertit les excavateurs de cesser immédiatement de creuser pour leur propre sécurité. Leurs travaux risquent de libérer de dangereuses forces anciennes.",al={"rethiel veut arrêter les fouilles","que doivent faire les excavateurs","avertissement sur le site de fouilles nain"}}},fp="23,266,18.437.0,19.372.1,45.144.0,36.131.0,60.132.0,43.189.0,57.170.0,53.127.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="Ardin Grassman a disparu près d'un site de fouilles après avoir entendu parler d'herbes imposantes. Son épouse alchimiste demande aux voyageurs de le retrouver, car une faune dangereuse a attaqué l'équipe.",h="Ardin Grassman a disparu près d'un site de fouilles après avoir entendu parler d'herbes imposantes.",kw={"alchimie","ardin","ardin grassman","sites de fouilles","herboristerie","lost in the thicket things","araignées","herbes imposantes"},ang={["class:Druid"]="En tant que druide, vous reconnaîtrez peut-être le don d'Ardin pour sentir la présence des plantes. La faune près des sites de fouilles s'est agitée, troublant l'équilibre de la nature.",["profession:Herbalism"]="En tant qu'herboriste, vous reconnaîtrez peut-être le don d'Ardin Grassman pour sentir la présence des plantes et des herbes. Il escalade souvent des terrains difficiles pour cueillir des plantes rares destinées à l'alchimie."},sec={{t="L'appel d'un cueilleur",b="L'épouse alchimiste d'Ardin Grassman vous demande de retrouver son mari disparu. Il a un instinct sûr pour la nature et brave souvent falaises et contrées sauvages lointaines pour cueillir des herbes et des plantes utiles à son travail. Quand une équipe de fouilles a parlé d'herbes imposantes, sans pareilles à leur connaissance, la curiosité d'Ardin l'a attiré vers le site."},{t="Embuscade sur le site de fouilles",b="Ardin est arrivé au site de fouilles et a trouvé l'équipe en danger. Les terres environnantes avaient agité la faune locale, et des araignées hostiles ont envahi le site. Ardin et l'équipe étaient piégés par les bêtes qui les attaquaient jusqu'à ce que des voyageurs viennent à leur secours."}},faq={{q="Qui est Ardin Grassman ?",a="Ardin Grassman cueille des herbes et possède un instinct rare pour sentir la présence des plantes. Il cherche souvent des plantes sauvages sur les falaises et les sommets afin d'approvisionner l'alchimie de son épouse. Des rumeurs d'herbes imposantes l'ont attiré vers un site de fouilles.",al={"qui est ardin","histoire d'ardin grassman","qui est ardin grassman"}},{q="Pourquoi Ardin s'est-il aventuré dans la nature ?",a="Ardin a entendu une équipe de fouilles parler d'herbes imposantes, sans pareilles à leur connaissance. Son instinct pour les plantes inhabituelles l'a poussé à aller les voir, et il n'est pas rentré chez lui.",al={"pourquoi ardin est-il parti","pourquoi ardin a-t-il disparu","que cherchait ardin"}},{q="Où Ardin est-il allé ?",a="Ardin s'est dirigé vers les Excavation Sites après avoir entendu le récit d'une équipe de passage. Cherchez-le sur les sites de fouilles où l'équipe a établi son camp.",al={"où est ardin","emplacement d'ardin","où trouver ardin grassman"}},{q="Qu'est-il arrivé à Ardin sur le site de fouilles ?",a="Ardin est arrivé au camp de fouilles alors que la faune locale devenait agressive. Des araignées géantes et d'autres bêtes ont tendu une embuscade à l'équipe, piégeant Ardin avec elle jusqu'à l'arrivée de voyageurs venus les aider.",al={"qu'est-il arrivé à ardin","ardin est-il mort","qu'est-ce qui a attaqué ardin"}},{q="Qui recherche Ardin ?",a="L'épouse d'Ardin, une alchimiste, le recherche. Il cueillait des herbes pour ses réserves, mais n'est pas rentré après avoir enquêté sur des rumeurs d'herbes étranges. Elle a donc demandé aux voyageurs de le retrouver.",al={"qui donne lost in the thicket things","qui a lancé cette quête","épouse d'ardin"}},{q="Pourquoi la faune a-t-elle attaqué l'équipe de fouilles ?",a="La cause de l'agitation soudaine de la faune près des sites de fouilles est inconnue. Des créatures agressives, surtout des araignées, ont envahi le site et submergé l'équipe.",al={"pourquoi les araignées attaquent-elles","qu'est-ce qui a agité les animaux","pourquoi les bêtes sont-elles agressives"}}},fp="26,183,19.303.0,22.250.1,22.215.0,39.168.0,19.133.0,46.178.0,25.183.0,48.162.0"}
P.entries["quest:95663"] = {n="Dragonmaw Rumors",s="Les Deathstalkers cherchent des précisions sur la magie que les Dragonmaw pratiqueraient dans les Paluns. Vous devez rencontrer leur agente dans les collines surplombant le camp du clan.",h="Les Deathstalkers cherchent des précisions sur la magie que les Dragonmaw pratiqueraient dans les Paluns.",kw={"symboles brisés","agente des deathstalkers","deathstalkers","asservissement des dragons","dragonmaw","camp des dragonmaw","rumeurs sur les dragonmaw","les paluns"},sec={{t="Murmures dans les Paluns",b="Un Deathstalker dans les Paluns a besoin de votre aide alors que les rumeurs se multiplient autour du clan Dragonmaw. On raconte qu’ils maîtrisent une magie capable d’asservir les dragons, et certains murmurent qu’ils préparent une démonstration de ce pouvoir. Les symboles brisés n’ont fourni aucune preuve solide, alors vous devez rencontrer une agente dans les collines surplombant leur camp."}},faq={{q="Que feraient les Dragonmaw selon les rumeurs ?",a="Selon la rumeur, les Dragonmaw préparent une démonstration de magie assez puissante pour asservir les dragons.",al={"rumeurs sur les dragonmaw","que préparent les dragonmaw","magie des dragonmaw"}},{q="Pourquoi les Deathstalkers ont-ils besoin d’aide ?",a="Les Deathstalkers n’ont que des symboles brisés et de vagues rumeurs sur les Dragonmaw, alors une agente a besoin d’aide dans les collines surplombant le camp du clan.",al={"deathstalker a besoin d’aide","pourquoi aider les deathstalkers","de quoi ont-ils besoin"}},{q="Où se trouve l’agente des Deathstalkers ?",a="L’agente se trouve dans les collines surplombant le camp des Dragonmaw, dans les Paluns.",al={"emplacement de l’agente","où rencontrer l’agente","agente des deathstalkers dans les collines"}},{q="Qu’ont révélé les symboles brisés ?",a="Les symboles brisés ne livraient que de vagues rumeurs sur une supposée démonstration de magie des Dragonmaw.",al={"symboles brisés","ce que les symboles ont révélé","symboles des dragonmaw"}},{q="Que se passe-t-il lors de la rencontre avec l’agente ?",a="L’agente des Deathstalkers vous révélera la suite lorsque vous la rencontrerez dans les collines surplombant le camp des Dragonmaw.",al={"rencontrer l’agente","prochaines étapes","que dit l’agente"}}},fp="16,151,24.300.0,43.98.0,35.151.0,32.67.0,35.94.0,37.106.0"}
P.entries["quest:95664"] = {n="Elder Knowledge",s="Une étrange Relique des Titans disperse la lumière tel un prisme vivant, mais sa nature demeure incertaine. Vous l’apportez à la Cime des Anciens, aux Pitons-du-Tonnerre, pour trouver quelqu’un capable d’expliquer son pouvoir ancestral.",h="Une étrange Relique des Titans disperse la lumière tel un prisme vivant, mais sa nature demeure incertaine.",kw={"pouvoir ancestral","fragment composite","elder knowledge","cime des anciens","prisme vivant","pitons-du-tonnerre","relique des titans"},sec={{t="Un fragment de lumière",b="L’étrange fragment composite en votre possession disperse la lumière tel un prisme vivant. Sa nature est incertaine, mais son pouvoir semble ancestral. Vous apportez la Relique des Titans à la Cime des Anciens, aux Pitons-du-Tonnerre, et cherchez quelqu’un qui pourra vous en dire davantage."}},faq={{q="Qu’est-ce que la Relique des Titans ?",a="C’est un étrange fragment composite qui disperse la lumière tel un prisme vivant. Sa nature est incertaine, mais son pouvoir semble ancestral.",al={"relique des titans","quelle est cette relique","fragment de prisme"}},{q="Où apporter la Relique des Titans ?",a="Apportez la Relique des Titans à la Cime des Anciens, aux Pitons-du-Tonnerre, et cherchez quelqu’un capable d’expliquer sa nature.",al={"où apporter la relique","relique cime des anciens","fragment pitons-du-tonnerre"}},{q="Pourquoi transporter ce fragment ?",a="Vous cherchez quelqu’un à la Cime des Anciens qui pourra vous en dire davantage sur la Relique des Titans.",al={"pourquoi cette relique","que faire du fragment","quête elder knowledge"}}},fp="15,186,16.232.0,24.127.0,32.92.0,28.82.0"}
P.entries["quest:95682"] = {n="Open the Maw",s="Un Deathstalker Agent vous demande de chasser les Dragonmaw des Excavation Sites et de rapporter tout objet digne d’intérêt. Le clan cherche peut-être un moyen de retrouver sa puissance.",h="Un Deathstalker Agent vous demande de chasser les Dragonmaw des Excavation Sites et de rapporter tout objet...",kw={"dark lady","deathstalker agent","dragonmaw","excavation site","réprouvés","griffonnage orc","rend"},sec={{t="Une approche discrète",b="Un Deathstalker Agent à l’extérieur de l’Excavation Site veut que les forces Dragonmaw soient chassées. Les survivants de ce clan de dompteurs de dragons pensent avoir trouvé quelque chose qui pourrait leur rendre leur puissance d’antan. Il faut déloger ces troupes disparates pour que les Deathstalkers puissent entrer sans être vus. Rapportez tout objet notable que vous récupérerez, et gardez cette affaire entre l’agent et le commandement royal."},{t="Le griffonnage récupéré",b="Le Deathstalker Agent reconnaît l’écriture orque parmi les objets récupérés. Elle révèle que les Dragonmaw espèrent apaiser Rend, leur faux chef de guerre. L’agent juge cette tentative vaine, mais ces renseignements sont précieux pour la Dark Lady. L’agent vous laisse les objets récupérés et vous avertit de ne rien dire de cette mission."}},faq={{q="Qui m’a envoyé à l’Excavation Site ?",a="Un Deathstalker Agent à l’extérieur de l’Excavation Site vous demande de chasser les Dragonmaw et de rapporter tout objet digne d’intérêt.",al={"qui veut chasser les dragonmaw","mission du deathstalker agent","qui m’a envoyé"}},{q="Que cherchent à faire les Dragonmaw ?",a="Les survivants Dragonmaw pensent avoir trouvé quelque chose qui pourrait leur rendre leur puissance d’antan.",al={"plan des dragonmaw","pourquoi les dragonmaw sont ici","retour au pouvoir des dragonmaw"}},{q="Pourquoi les Deathstalkers veulent-ils faire évacuer le site ?",a="Ils veulent entrer dans l’Excavation Site sans être repérés.",al={"pourquoi évacuer l’excavation site","arrivée des deathstalkers","de quoi ont-ils besoin"}},{q="Que dois-je rapporter ?",a="Rapportez au Deathstalker Agent tout objet digne d’intérêt que vous récupérerez auprès des Dragonmaw.",al={"quoi récupérer","objets des dragonmaw","que veut l’agent"}},{q="Qui est la Dark Lady ?",a="L’agent emploie ce titre pour désigner Sylvanas, qui dirige les Réprouvés.",al={"signification de dark lady","qui est la dark lady","titre de sylvanas"}}},fp="12,153,16.379.0,20.323.1,35.117.0,36.95.0,47.50.0,25.77.0,21.63.0"}
P.entries["quest:95697"] = {n="Changing Tastes",s="Chez Borstan's Firepit, un nouveau plat pourrait attirer des voyageurs à Orgrimmar. Les conseils de Zamja et les récits de serres de raptors géants poussent Borstan à chercher de la viande de raptor des fourrés dans les Paluns, de l'autre côté de la mer.",h="Chez Borstan's Firepit, un nouveau plat pourrait attirer des voyageurs à Orgrimmar.",kw={"borstan","borstan's firepit","changing tastes","sites de fouilles","orgrimmar","raptor des fourrés","viande de raptor des fourrés","les paluns","zamja"},ang={["faction:Horde"]="Pour approvisionner Borstan's Firepit, il faut traverser la mer et rejoindre les Paluns disputés afin de rapporter de la viande exotique à Orgrimmar.",["profession:Cooking"]="Borstan espère donner plus d'ampleur aux plats rustiques de la capitale de la Horde, tandis que les goûts et les menus des tavernes évoluent au-delà des mets traditionnels des villages."},sec={{t="Rehausser la cuisine de la capitale",b="Borstan's Firepit, à Orgrimmar, souhaite étoffer son menu. Zamja suggère de préparer le raptor comme au pays, pour les voyageurs qui regrettent les plats familiers de leur village natal. Borstan aime l'idée d'attirer de nouveaux clients avec du raptor, mais trouve ces plats rustiques trop modestes pour la grande capitale de la Horde. Il veut donner plus d'audace à ce mets traditionnel."},{t="La chasse dans les Paluns",b="Un chasseur revient à Orgrimmar avec une serre massive, prélevée sur un raptor des fourrés des sites de fouilles des Paluns. La taille et la qualité de la bête éveillent l'intérêt de Borstan. Il organise une expédition pour traverser la mer jusqu'aux Royaumes de l'est, braver les sites de fouilles et rapporter de la viande de premier choix pour ses feux."}},faq={{q="Qu'est-ce que la quête Changing Tastes ?",a="Changing Tastes est une tâche culinaire à Orgrimmar. Borstan, propriétaire de Borstan's Firepit, cherche de la viande de raptor des fourrés dans les lointains Paluns pour rehausser son menu au-delà des plats rustiques.",al={"qu'est-ce que changing tastes","quête changing tastes"}},{q="Qui est Zamja ?",a="Zamja est une associée et une cuisinière qui suggère des plats de raptor préparés comme au pays pour Borstan's Firepit. Elle espère ainsi attirer des clients qui ne fréquentent pas souvent l'établissement.",al={"qui est zamja","cuisine de zamja"}},{q="Qu'est-ce que Borstan's Firepit ?",a="Borstan's Firepit est un restaurant à Orgrimmar, la capitale de la Horde. Il sert des viandes nourrissantes aux habitants comme aux voyageurs.",al={"borstan's firepit","où est borstan"}},{q="Pourquoi Borstan veut-il de la viande de raptor des fourrés ?",a="Borstan veut donner plus d'ampleur aux saveurs familières que Zamja propose dans ses plats de raptor préparés comme au pays. Le récit d'un chasseur évoquant des serres géantes lui donne l'idée de chercher de la viande de raptor des fourrés dans les Paluns.",al={"pourquoi de la viande de raptor","pourquoi un raptor des fourrés"}},{q="Où se trouvent les raptors des fourrés ?",a="Les raptors des fourrés vivent sur des sites de fouilles dans les Paluns, une région acquise à l'Alliance, de l'autre côté de la Grande mer, dans les Royaumes de l'est.",al={"où trouver des raptors des fourrés","raptors des sites de fouilles des paluns"}},{q="Qui donne la quête Changing Tastes ?",a="Borstan, propriétaire de Borstan's Firepit à Orgrimmar, propose Changing Tastes. Les conseils de Zamja et le trophée rapporté par un chasseur aventurier lui en donnent l'idée.",al={"qui donne changing tastes","borstan donneur de quête"}}},fp="15,189,25.341.0,24.317.0,34.184.0,13.162.0,26.124.0,42.179.0,38.130.0,36.162.0"}
P.entries["quest:957"] = {n="Bashal'Aran",s="À Bashal'Aran, l'esprit d'Asterion reste lié par un sceau ancien. Vous portez le sceau vers le sud, jusqu'à Ameth'Aran, où une vieille flamme pourrait briser ses chaînes.",h="À Bashal'Aran, l'esprit d'Asterion reste lié par un sceau ancien.",kw={"ameth'aran","asterion","athrikus","azshara","bashal'aran","sombrivage","bien-nés","sceau de pierre de lune"},ang={["class:Mage"]="En tant que mage, vous percevez la puissance arcanique brute des anciens sorciers Bien-nés dans les enchantements qui retiennent Asterion et les flammes qui brûlent encore à Ameth'Aran.",["faction:Alliance"]="En tant que membre de l'Alliance, vous contribuez à dissiper les anciennes malédictions de Sombrivage et à protéger les frontières des nouvelles colonies d'Elfes de la nuit qui s'étendent depuis Auberdine.",["race:NightElf"]="En tant qu'Elfe de la nuit de Kalimdor à l'époque actuelle, vous découvrez le passé de votre peuple avant la Fracture et la corruption persistante de la noblesse Bien-née de la reine Azshara lors de la libération d'Asterion."},sec={{t="Une prison de sorcellerie ancienne",b="L'Ancien sceau de pierre de lune fut forgé par des sorciers Bien-nés avant la Grande Fracture, et aucune force ordinaire ne peut briser son pouvoir."},{t="Les ruines jumelles de Sombrivage",b="Bashal'Aran et Ameth'Aran étaient des cités sœurs kaldorei sous le règne de la reine Azshara, lorsque le Puits d'éternité ancrant leur empire existait encore. Aujourd'hui, les deux sites sont des ruines envahies par la végétation et hantées, où les fantômes s'attardent et la puissance arcanique reste instable. À Ameth'Aran, un brasero mystique brûle d'un feu cyan dans un kiosque de pierre ; c'est la seule flamme capable de consumer l'Ancien sceau de pierre de lune."},{t="La vengeance s'éveille",b="Asterion est libéré une fois le sceau détruit et découvre un Kalimdor brisé, bien différent de l'âge d'or dont il se souvient. Pourtant, la liberté ne lui apporte aucune paix. Il sent qu'Athrikus, son ancien maître et geôlier Bien-né, existe toujours. Le désespoir fait place à une soif froide de vengeance."}},faq={{q="Qui est Asterion ?",a="Asterion est l'esprit d'un Elfe de la nuit prisonnier des ruines de Bashal'Aran. Il remonte à dix mille ans, au règne de la reine Azshara, et un sceau forgé par l'un des Bien-nés les plus puissants le retient là-bas.",al={"asterion","qui est le fantôme","pnj asterion"}},{q="Où détruire l'Ancien sceau de pierre de lune ?",a="Portez l'Ancien sceau de pierre de lune vers le sud, jusqu'à Ameth'Aran, la ruine jumelle de Bashal'Aran. Dans un kiosque de pierre brûle un grand brasero cubique, alimenté par un feu ancien bleu verdâtre qui peut le détruire.",al={"où se trouve la flamme","lieu de la flamme ancienne","détruire le sceau"}},{q="Quel est le lien entre Bashal'Aran et Ameth'Aran ?",a="Bashal'Aran et Ameth'Aran étaient des cités sœurs de l'ancien empire des Elfes de la nuit, avant la Fracture. Toutes deux furent dévastées il y a dix mille ans, laissant des piliers de pierre hantés, une puissance arcanique persistante et des esprits agités.",al={"ruines jumelles","lien avec ameth'aran","bashal'aran ameth'aran"}},{q="Qui a emprisonné Asterion ?",a="Asterion raconte que l'un des Bien-nés les plus puissants a forgé le sceau qui le retient. Son ancien maître est révélé au fil de l'histoire.",al={"qui a emprisonné asterion","qui est athrikus","maître d'asterion"}},{q="De quelle époque Asterion se souvient-il ?",a="Asterion se souvient de l'époque où le Puits d'éternité originel existait encore, où la reine Azshara régnait sur l'empire et où les nobles Bien-nés tenaient leurs cours majestueuses avant la Fracture.",al={"passé d'asterion","époque du puits d'éternité","quel âge a asterion"}},{q="Libérer Asterion permet-il à son esprit de trouver le repos ?",a="La destruction du sceau doit briser la prison d'Asterion. Vous découvrirez ce que la liberté signifie pour lui à votre retour.",al={"asterion trouve-t-il le repos","qu'arrive-t-il à asterion","asterion après sa libération"}}},fx={["8275c861"]={q="Pourquoi Asterion veut-il que l'Ancien sceau de pierre de lune soit détruit ?",a="L'Ancien sceau de pierre de lune est l'ancre qui lie l'esprit d'Asterion dans le tourment au sein des ruines de Bashal'Aran. Créé il y a des millénaires par une puissante sorcellerie Bien-née, il le maintient emprisonné et aveugle au monde extérieur. Le détruire dans la flamme antique mystique d'Ameth'Aran est le seul moyen de briser ses chaînes éthérées, lui accordant la liberté et la clarté nécessaires pour constater ce qu'est devenu Kalimdor.",al={"pourquoi détruire l'ancien sceau de pierre de lune","motivation d'asterion","pourquoi asterion veut-il briser le sceau"}},["51df5ddd"]={q="Pourquoi Asterion a-t-il besoin que vous apportiez le sceau à Ameth'Aran ?",a="Lié par l'ancienne magie des Bien-nés qui l'ancre à Bashal'Aran, Asterion ne peut pas quitter les ruines immédiates, et encore moins voyager vers le sud jusqu'à Ameth'Aran. Il a besoin d'un voyageur pour porter le sceau dans la flamme antique.",al={"pourquoi asterion ne peut-il pas détruire le sceau","pourquoi asterion a-t-il besoin de moi","pourquoi envoyer un aventurier pour détruire le sceau"}}},fp="11,147,27.134.0,23.371.0,17.273.1,16.195.0,46.180.0,60.221.0,24.132.1,32.178.0,45.113.1"}
P.entries["quest:95737"] = {n="Seeking Caitlin",s="Une alchimiste attend des nouvelles au sujet d’une herbe rare. Elle vous demande de retrouver Caitlin Grassman au Port de Menethil, dont le mari n’a pas donné de nouvelles depuis une fouille.",h="Une alchimiste attend des nouvelles au sujet d’une herbe rare.",kw={"alchimiste","caitlin grassman","fouilles","graines d’herbe","port de menethil","herbe primordiale","seeking caitlin","les paluns"},ang={["profession:Herbalism"]="En tant qu’herboriste, vous devez prendre des nouvelles de Caitlin après que l’équipe de son mari a trouvé des traces d’une herbe primordiale rare."},sec={{t="Un rapport manquant",b="Caitlin a appris à l’alchimiste que l’équipe de fouilles de son mari avait trouvé des traces d’une herbe primordiale. Elle ignore quelle quantité ils ont trouvée et s’il est possible d’y accéder.\n\nL’alchimiste vous demande maintenant de parler à Caitlin au Port de Menethil. Toutes deux attendent de savoir ce qu’il est advenu des graines promises."}},faq={{q="Qui est Caitlin Grassman ?",a="Caitlin Grassman est une alchimiste du Port de Menethil. Son mari a rejoint une équipe de fouilles qui a trouvé des traces d’une herbe primordiale.",al={"caitlin","qui est caitlin","caitlin grassman"}},{q="Que veut l’alchimiste que je fasse ?",a="L’alchimiste vous demande de parler à Caitlin Grassman au Port de Menethil.",al={"trouver caitlin","parler à caitlin","quête de caitlin"}},{q="Qu’a trouvé l’équipe de fouilles ?",a="L’équipe a trouvé des traces d’une herbe primordiale disparue depuis longtemps. On ignore quelle quantité il y en a et s’il est possible d’y accéder.",al={"herbe primordiale","herbe rare","découverte des fouilles"}},{q="Pourquoi sont-elles inquiètes ?",a="Caitlin a promis à l’alchimiste que son mari rapporterait des graines d’herbe, mais aucune n’est arrivée. Toutes deux soupçonnent qu’un problème est survenu sur le site de fouilles.",al={"où sont les graines","graines d’herbe manquantes","pourquoi s’inquiéter"}}},fp="15,161,16.313.0,24.130.0,38.73.0,34.117.0,23.151.0"}
P.entries["quest:95748"] = {n="The Gurubashi Legends of Old",s="Un érudit troll cherche un estampage d’une tablette ancienne au nord du Récif infâme. Sa légende pourrait préciser l’étendue d’I'lalai, la cité perdue.",h="Un érudit troll cherche un estampage d’une tablette ancienne au nord du Récif infâme.",kw={"ruines anciennes","gurubashi","i'lalai","légende","estampage","tablette","troll","le récif infâme"},ang={["race:Troll"]="En tant que Troll, on vous demande d’aider un érudit à étudier les légendes d’une cité trolle perdue."},sec={{t="Une tablette près de la côte",b="L’érudit compare un fragment de tablette que vous avez rapporté aux ruines au large du Récif infâme. Ces ruines semblent trop petites pour correspondre à la vaste civilisation décrite dans le texte. L’érudit vous demande donc de réaliser l’estampage d’une tablette dans d’anciennes ruines trolles, sur les collines côtières au nord."},{t="Un lointain souvenir",b="L’érudit accueille l’estampage avec plaisir et dit connaître cette tablette depuis sa jeunesse. Bien des lunes se sont écoulées depuis sa dernière lecture, et ses souvenirs se sont estompés."}},faq={{q="Que veut l’érudit ?",a="L’érudit veut un estampage d’une tablette contenant des légendes sur la cité trolle perdue d’I'lalai.",al={"estampage de tablette","de quoi a-t-il besoin","demande d’estampage"}},{q="Où se trouve la tablette ?",a="Elle se trouve dans d’anciennes ruines trolles, sur les collines côtières au nord du Récif infâme.",al={"emplacement de la tablette","où est la tablette","au nord du récif"}},{q="Pourquoi l’érudit veut-il un estampage ?",a="Un fragment de tablette que vous avez rapporté décrit I'lalai comme une vaste civilisation, mais les ruines au large du Récif infâme semblent trop petites pour y correspondre.",al={"pourquoi un estampage","tablette d’i'lalai","légende de la cité perdue"}},{q="Qu’est-ce qu’I'lalai ?",a="Le fragment de tablette décrit I'lalai comme une cité trolle perdue et une vaste civilisation.",al={"cité d’i'lalai","cité trolle perdue","ilalai"}},{q="Que dit l’érudit au sujet de la tablette ?",a="L’érudit a déjà lu la tablette dans sa jeunesse, mais dit que bien des lunes se sont écoulées et que ses souvenirs se sont estompés.",al={"souvenirs de l’érudit","tablette déjà lue","ancienne légende trolle"}}},fp="28,122,21.278.0,13.159.0,27.93.0,20.71.0,36.128.0,16.91.0,43.105.0"}
P.entries["quest:95770"] = {n="Locating the Lost City",s="Kin'weelay vous demande de chercher au Récif infâme une caverne liée à la cité perdue. Les nagas qui s'y rassemblent ont peut-être trouvé quelque chose qui mérite une enquête.",h="Kin'weelay vous demande de chercher au Récif infâme une caverne liée à la cité perdue.",kw={"caverne","i'lalai","kin'weelay","locating the lost city","lost city","murlocs","nagas","le récif infâme"},sec={{t="Une caverne dans le récif",b="Kin'weelay se souvient avoir plongé parmi les ruines du Récif infâme avant que les murlocs ne s'y installent. Il se rappelle une caverne et vous demande d'explorer le récif pour en trouver l'entrée. Des nagas se rassemblent désormais dans la région, et il veut savoir ce qui les y a attirés."},{t="Une possible découverte",b="À votre retour, Kin'weelay écoute le récit de ce que vous avez vu. Les nagas vont et viennent dans les ruines de la caverne, mais leur but reste obscur. Il se demande si elle est liée à I'lalai et à Lost City, que les trolls ont longtemps considérée comme un mythe. Il veut maintenant enquêter."}},faq={{q="Qui me demande de fouiller le Récif infâme ?",a="Kin'weelay vous demande d'explorer le Récif infâme et de chercher l'entrée d'une caverne.",al={"qui m'a envoyé","demande de kin weelay","qui veut cela"}},{q="Pourquoi dois-je chercher une caverne ?",a="Kin'weelay se souvient d'une caverne parmi les ruines du Récif infâme et pense qu'elle pourrait aider à localiser Lost City.",al={"pourquoi la caverne","indice sur lost city","que dois-je chercher"}},{q="Pourquoi les nagas s'y rassemblent-ils ?",a="Kin'weelay a entendu dire que des nagas se rassemblent dans la région, mais leur raison reste inconnue.",al={"nagas au récif","pourquoi les nagas","raison des nagas"}},{q="Que sont devenues les ruines du Récif infâme ?",a="Des murlocs se sont installés parmi les ruines du Récif infâme après la jeunesse de Kin'weelay, à l'époque où il y plongeait.",al={"ruines du récif infâme","murlocs sur place","qui s'est installé au récif"}},{q="Où se trouve l'entrée de la caverne ?",a="L'entrée de la caverne se trouve au Récif infâme. Kin'weelay vous demande d'explorer le récif pour la trouver.",al={"emplacement de la caverne","trouver l'entrée","où est la caverne"}}},fp="22,146,20.228.0,20.259.1,41.76.0,30.102.0,33.88.0,37.103.0,29.88.0"}
P.entries["quest:95772"] = {n="Songblade Search",s="Dorin Songblade attend des nouvelles de son frère Daewyn, parti dans les Paluns. Daewyn s’est joint à une équipe archéologique de Loch Modan pour fouiller des collines inexplorées, mais son silence ne lui ressemble pas.",h="Dorin Songblade attend des nouvelles de son frère Daewyn, parti dans les Paluns.",kw={"daewyn songblade","dls","dorin songblade","loch modan","songblade search","les paluns","excavations de whelgar"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez passer près de sites de fouilles en chemin entre Loch Modan et le Port de Menethil. Vous pouvez alors aider des prospecteurs et des artisans nains en difficulté.",["race:Dwarf"]="En tant que nain, vous savez que les expéditions et les fouilles archéologiques sont courantes dans Khaz Modan. Les Paluns, au-delà de Loch Modan, sont dangereux, et s’y rendre met les proches en péril."},sec={{t="L’inquiétude d’un frère",b="Dorin Songblade s’occupe de son atelier, enseveli sous les commandes de réparation de ceintures. Son frère Daewyn est parti vers le nord avec une équipe de fouilleurs nains de Loch Modan. Les collines qu’ils cherchent à explorer dans les Paluns n’ont jamais senti le coup d’une pioche naine. Daewyn écrit généralement dès son arrivée, mais Dorin n’a reçu aucune nouvelle et ce silence le trouble."},{t="Les fouilles des Paluns",b="Daewyn Songblade fouille le site des Excavations de Whelgar, dans les Paluns. Il ressemble beaucoup à son frère Dorin et porte un fusil dont la crosse en bois est gravée des initiales DLS. Ces initiales désignent Daewyn dans ce camp de fouilles isolé des marécages."}},faq={{q="Qui donne la quête Songblade Search ?",a="Dorin Songblade demande aux voyageurs de prendre des nouvelles de son frère. Le travail de réparation des ceintures occupe les mains de l’artisan, qui n’a donc pas pu se joindre aux fouilles archéologiques de Daewyn.",al={"qui donne songblade search","donneur de quête songblade search","dorin songblade"}},{q="Qui est Daewyn Songblade ?",a="Daewyn Songblade est le frère de Dorin Songblade. Il est parti avec une équipe de fouilleurs de Loch Modan pour explorer les collines des Paluns, mais n’a pas donné de nouvelles comme il le fait habituellement.",al={"qui est le frère de dorin","nain songblade disparu","daewyn songblade"}},{q="Où trouver Daewyn ?",a="Daewyn se trouve aux Excavations de Whelgar, dans les Paluns. Sa ressemblance avec Dorin et les initiales DLS gravées sur la crosse en bois de son fusil permettent de le reconnaître.",al={"où est daewyn","où trouver daewyn songblade","lieu de songblade search"}},{q="Pourquoi Daewyn est-il parti dans les Paluns ?",a="Daewyn est parti dans les Paluns avec une expédition naine de fouilles venue de Loch Modan, pour explorer des collines inexplorées.",al={"pourquoi daewyn est-il parti dans les paluns","but des excavations de whelgar","pourquoi les nains sont-ils partis dans les paluns"}},{q="Que signifient les initiales gravées sur le fusil ?",a="Les initiales DLS gravées sur la crosse du fusil sont celles de Daewyn Songblade. Elles identifient le nain du site de fouilles comme le frère disparu de Dorin.",al={"que signifie dls","gravure dls sur le fusil","initiales dls"}},{q="Pourquoi Dorin s’inquiétait-il pour son frère ?",a="Dorin s’inquiète, car Daewyn écrit habituellement peu après son départ. Aucune lettre n’est arrivée depuis que Daewyn est parti dans les Paluns, et Dorin craint qu’il lui soit arrivé quelque chose.",al={"pourquoi dorin est-il inquiet","pourquoi chercher daewyn","raison de songblade search"}}},fp="16,183,18.330.0,23.239.1,37.155.0,24.160.0,26.152.0,38.111.0,44.147.0,40.170.0"}
P.entries["quest:95773"] = {n="Enemies in the Water",s="Des nagas se rassemblent près d’anciennes ruines trolles au large, alors que la Horde subit déjà des attaques contre ses caravanes. On vous demande de faire face à cette menace et de montrer que vous faites vos preuves.",h="Des nagas se rassemblent près d’anciennes ruines trolles au large, alors que la Horde subit déjà des attaques...",kw={"bloodscalp","brinescale","ennemis dans l’eau","grom'gol","horde","nagas","ogres","tridents","ruines trolles"},ang={["faction:Horde"]="La Horde cherche à protéger ses caravanes tout en guettant une éventuelle attaque venue de la mer."},sec={{t="Rapports de la côte",b="La Horde a reçu des rapports signalant un rassemblement de nagas près d’anciennes ruines trolles sous la mer. Les attaques des Bloodscalp et des ogres mettent déjà ses défenses à rude épreuve, si bien qu’une menace venue des eaux laisse peu de répit. On vous demande d’affronter les tirailleurs Brinescale et de rapporter leurs tridents comme preuve."},{t="Un message à Grom’gol",b="À Grom’gol, les tridents que vous rapportez doivent être plantés devant les portes. Ainsi exposés, ils avertiront que l’on ne défie pas la Horde à la légère, et votre travail vous vaut les éloges du commandant."}},faq={{q="Pourquoi les nagas sont-ils près de la côte ?",a="Selon les rapports, les nagas se rassemblent autour d’anciennes ruines trolles sous la mer.",al={"nagas côte","nagas dans l’eau","pourquoi les nagas sont ici"}},{q="Qui sont les ennemis ici ?",a="La menace vient des tirailleurs Brinescale, un groupe de nagas signalé près de la côte.",al={"ennemis dans l’eau","qui sont les nagas","brinescale"}},{q="Pourquoi la Horde veut-elle éliminer les nagas ?",a="La Horde peine déjà à défendre ses caravanes contre les attaques des Bloodscalp et des ogres, et craint un assaut surprise venu de la mer.",al={"pourquoi tuer les nagas","problème nagas horde","attaque maritime"}},{q="Quelle preuve est demandée ?",a="On vous demande de rapporter des tridents Brinescale comme preuve de votre réussite.",al={"tridents comme preuve","que rapporter","tridents brinescale"}},{q="Que deviendront les tridents ?",a="Ils seront plantés devant les portes de Grom’gol pour avertir que l’on ne défie pas la Horde à la légère.",al={"message des tridents","planter les tridents","tridents gromgol"}},{q="En quoi cela prouve-t-il ma valeur ?",a="Le commandant salue votre travail et affirme que vous faites rapidement vos preuves auprès de la Horde.",al={"faire ses preuves","approbation de la horde","pourquoi suis-je ici"}}},fp="20,188,22.299.0,23.197.1,32.74.0,25.86.0,44.135.0,24.73.0,33.104.0,29.89.0"}
P.entries["quest:95774"] = {n="Her Name Is Olgra",s="Mankrik pleure Olgra et prépare un monument pour que son nom perdure. Il vous demande de chercher ses ornements en os manquants auprès des pillards Razormane des environs.",h="Mankrik pleure Olgra et prépare un monument pour que son nom perdure.",kw={"ornements","mankrik","mémorial","olgra","os poli","quilboar","pillards razormane"},sec={{t="Honorer les défunts",b="Un guérisseur a sauvé Mankrik, mais Olgra a succombé à ses blessures sur le champ de bataille. En deuil, Mankrik prépare un hommage durable pour que son nom et son sacrifice restent dans les mémoires."},{t="Souvenirs perdus",b="Olgra portait de précieux ornements en os poli, mais ils ont disparu de son lieu de repos. Mankrik vous demande de les récupérer auprès des pillards Razormane des environs, afin qu’ils reposent près du monument qu’il érige pour elle."}},faq={{q="Qui est Olgra ?",a="Olgra est tombée au combat contre les quilboar. Le guérisseur qui a sauvé Mankrik n’a pas pu la sauver, et il compte honorer sa mémoire pour toujours.",al={"qui est olgra","épouse de mankrik","qui est morte"}},{q="Que sont les ornements d’Olgra ?",a="Les ornements d’Olgra sont de précieux bijoux en os poli. Elle les portait avant d’être tuée.",al={"que sont les ornements d’olgra","bijoux d’olgra","en quoi sont faits les ornements"}},{q="Pourquoi traque-t-on les pillards Razormane ?",a="Les pillards Razormane ont les ornements d’Olgra. Mankrik vous envoie les récupérer auprès des pillards, près du lieu où elle est morte.",al={"pourquoi tuer les pillards razormane","qui a volé les ornements d’olgra","où sont les ornements"}},{q="Que fera Mankrik des ornements récupérés ?",a="Mankrik compte placer les bijoux en os récupérés près du monument qu’il bâtit pour Olgra, afin que sa mémoire perdure.",al={"mémorial de mankrik","que fera mankrik des ornements","pourquoi mankrik veut les ornements"}}},fp="17,152,19.165.0,14.226.0,13.135.0,28.111.0,43.127.0,51.122.0"}
P.entries["quest:95775"] = {n="The Drowned City",s="Un érudit vous demande d’inspecter des ruines gardées par des nagas et de recopier leurs gravures sur des tablettes. Il pourrait s’agir d’I’lalai, riche en histoire oubliée.",h="Un érudit vous demande d’inspecter des ruines gardées par des nagas et de recopier leurs gravures sur des...",kw={"charbon de bois","cité engloutie","peau","i’lalai","histoire oubliée","nagas","frottages","ruines","tablettes"},sec={{t="De l’autre côté de la caverne",b="L’érudit est trop âgé pour entrer dans les ruines et vous demande d’y aller à sa place. Au-delà de la caverne gardée par des nagas, il pense que ces ruines pourraient être celles d’I’lalai. Cette cité perdue pourrait renfermer une grande richesse de connaissances historiques. Vous devez réaliser des frottages de toutes les tablettes que vous trouverez et les rapporter."}},faq={{q="Qu’est-ce que la cité engloutie ?",a="Selon l’érudit qui vous a envoyé, ces ruines pourraient être celles de la cité perdue d’I’lalai.",al={"cité engloutie","de quelle cité s’agit-il","ruines d’i’lalai"}},{q="Qui veut que j’explore les ruines ?",a="Un érudit vous demande d’explorer les ruines, car il est trop âgé pour s’y rendre lui-même.",al={"qui m’a envoyé","qui veut des frottages","demande de l’érudit"}},{q="Pourquoi m’envoie-t-on là-bas ?",a="L’érudit espère que les ruines renferment une grande richesse de connaissances historiques oubliées.",al={"pourquoi explorer","pourquoi les tablettes","histoire oubliée"}},{q="Que dois-je rapporter ?",a="Réalisez des frottages de toutes les tablettes que vous trouverez à l’aide de peau et de charbon de bois, puis rapportez-les à l’érudit.",al={"que rapporter","frottages de tablettes","mission de frottage"}},{q="Où se trouvent les ruines ?",a="Les ruines se trouvent de l’autre côté de la caverne gardée par des nagas.",al={"où se trouve la cité engloutie","caverne des nagas","emplacement des ruines"}}},fp="16,132,17.294.0,25.83.0,34.82.0,26.77.0,33.95.0,20.62.0"}
P.entries["quest:95776"] = {n="The Only Good Brinescale...",s="Les nagas qui rôdent dans les eaux côtières font craindre une menace plus grande. Vous devez trouver leur chef dans la Cité engloutie.",h="Les nagas qui rôdent dans les eaux côtières font craindre une menace plus grande.",kw={"brinescale","côte","cité engloutie","infiltration","kin'weelay","nagas","var'taka"},sec={{t="Une menace au large",b="Les nagas près de la côte ont été tués, mais leur nombre laisse présager un danger plus grand. Kin'weelay pense que les nagas Brinescale pénètrent dans les ruines de la Cité engloutie. Leur présence laisse penser qu'ils cherchent quelque chose qui pourrait menacer la côte. Vous devez tuer leur chef, Var'Taka."},{t="Le retour",b="À votre retour, votre employeur comprend votre arrivée comme un signe que Var'Taka est mort. Avec la disparition du chef des nagas, la côte a une inquiétude de moins."}},faq={{q="Pourquoi les nagas sont-ils dans la Cité engloutie ?",a="Kin'weelay pense que les nagas Brinescale cherchent quelque chose dans la Cité engloutie, mais on ignore quoi.",al={"pourquoi les nagas sont-ils là","objectif des brinescale","que cherchent les nagas"}},{q="Qui est Kin'weelay ?",a="Kin'weelay est celui qui pense que les nagas Brinescale infiltrent la Cité engloutie.",al={"kin weelay","qui est kin'weelay","kin"}},{q="Qui est Var'Taka ?",a="Var'Taka est le chef des nagas Brinescale dans la Cité engloutie.",al={"var taka","chef des nagas","chef des brinescale"}},{q="Que dois-je faire ?",a="Vous devez tuer Var'Taka dans la Cité engloutie.",al={"que faire","quelle est la tâche","qui tuer"}}},fp="27,126,17.299.0,10.143.1,48.121.0,18.89.0,16.66.0,22.51.0"}
P.entries["quest:95787"] = {n="Take Two With Water",s="Maître des traditions Dibbs vous demande de recueillir des légendes de la Drowned City, où il pense que la cité troll perdue d’I’lalai a refait surface. Il parle peut-être de la découverte archéologique du siècle.",h="Maître des traditions Dibbs vous demande de recueillir des légendes de la Drowned City, où il pense que la...",kw={"cité engloutie","i’lalai","loa","maître des traditions dibbs","relevés de tablettes","marées","légendes trolls","zandali"},sec={{t="La découverte de Dibbs",b="Le maître des traditions Dibbs a lu un rapport d’éclaireurs et des légendes trolls qui suggèrent qu’I’lalai, une cité troll perdue, a refait surface au large de la Vallée de Strangleronce. Il vous demande de rapporter des légendes de la Cité engloutie. Cette découverte pourrait changer ce que l’on sait des ruines antiques."},{t="Les tablettes",b="Dibbs vous accueille à votre retour des ruines trolls et brûle d’entendre ce que vous avez trouvé. Quatre tablettes livrent de nouvelles légendes, mais son ancien zandali est rouillé. Il pense que leurs mots pourraient nommer un loa inconnu lié aux marées."}},faq={{q="Qui demande ces légendes ?",a="Le maître des traditions Dibbs vous demande de recueillir des légendes de la Cité engloutie.",al={"qui est dibbs","maître des traditions dibbs","demande de dibbs"}},{q="Qu’est-ce que la Cité engloutie ?",a="Dibbs pense qu’il pourrait s’agir de la cité troll perdue d’I’lalai, qui a refait surface au large de la Vallée de Strangleronce.",al={"cité engloutie","quelle cité","cité troll sous-marine"}},{q="Que veut que je rapporte Dibbs ?",a="Il vous demande de faire des relevés au fusain des tablettes trouvées dans la Cité engloutie et de rapporter les légendes.",al={"que dois-je recueillir","relevés de tablettes","demande de la cité engloutie"}},{q="Pourquoi Dibbs veut-il ces légendes ?",a="Il pense que le rapport d’éclaireurs et les légendes trolls pourraient mener à la cité perdue d’I’lalai.",al={"pourquoi ces légendes","recherches de dibbs","qu’étudie-t-il"}},{q="Où pourrait se trouver I’lalai ?",a="Dibbs pense qu’I’lalai a refait surface juste au large de la Vallée de Strangleronce.",al={"où se trouve i’lalai","emplacement d’i’lalai","cité troll perdue"}}},fp="19,194,19.263.0,11.226.1,32.67.0,25.93.0,38.102.0,32.90.0,25.71.0"}
P.entries["quest:95788"] = {n="Magics of the Drowned City",s="Un érudit vous demande de rapporter des fétiches trolls d’I'lalai pour les étudier.",h="Un érudit vous demande de rapporter des fétiches trolls d’I'lalai pour les étudier.",kw={"frère nimetz","magie noire","cité engloutie","fétiches","i'lalai","naga","pirates","serpent de mer","troll","mort-vivant"},sec={{t="Des fétiches à étudier",b="L’érudit qui examine les fétiches des Tranche-tête de Frère Nimetz vous demande d’en rassembler d’autres à I'lalai. Selon les rumeurs, la cité troll perdue aurait émergé des eaux, peut-être grâce à une magie noire. L’érudit veut comparer ses fétiches à ceux déjà examinés."},{t="De nombreuses magies",b="À votre retour, l’érudit remarque que les fétiches d’I'lalai sont différents, avec une conception complexe mais simple et un grand serpent de mer. Votre récit décrit des morts-vivants, des pirates, des rituels de sang et des forces naga qui convergent dans les ruines. La cité rassemble désormais de nombreuses formes de magie, et l’érudit estime qu’elle mérite d’être étudiée davantage."}},faq={{q="Qui demande les fétiches ?",a="L’érudit qui a examiné les fétiches des Tranche-tête de Frère Nimetz vous demande de rapporter des fétiches trolls d’I'lalai.",al={"qui veut des fétiches","érudit fétiches"}},{q="Pourquoi rassembler les fétiches ?",a="L’érudit veut étudier si les fétiches d’I'lalai sont liés à la magie noire qui, selon les rumeurs, aurait fait émerger la cité.",al={"pourquoi rassembler des fétiches","étude des fétiches"}},{q="Qu’est-ce qu’I'lalai ?",a="I'lalai est une cité troll perdue qui, selon les rumeurs, aurait émergé des eaux.",al={"cité engloutie","cité troll"}},{q="Qu’est-ce qui distingue les fétiches d’I'lalai ?",a="Ils représentent un grand serpent de mer. Leur conception est plus complexe à certains égards et plus simple à d’autres que celle des fétiches examinés auparavant.",al={"conception des fétiches","fétiche serpent de mer"}},{q="Quelles forces convergent vers I'lalai ?",a="Votre récit décrit des morts-vivants errants, des pirates envahisseurs, des rituels de sang et des forces naga parmi les ruines.",al={"qui se trouve à i'lalai","morts-vivants pirates naga"}}},fp="26,142,18.273.0,11.331.1,26.111.0,36.115.0,16.74.0,43.148.0,38.104.0"}
P.entries["quest:95789"] = {n="Shady Saltseers",s="Un contact du Baron Revilgaz vous envoie à Drowned City sur la piste des Saltseers, des pirates qui collectionnent les artefacts magiques. Leur butin attire l’attention depuis que les ruines trolles englouties ont refait surface.",h="Un contact du Baron Revilgaz vous envoie à Drowned City sur la piste des Saltseers, des pirates qui...",kw={"baron revilgaz","drowned city","artefacts magiques","pirates","saltseers","shady saltseers","ruines trolles","voodoo infused artifacts"},sec={{t="La requête d’un baron",b="Un contact du Baron Revilgaz vous demande de récupérer des artefacts auprès des Saltseers à Drowned City. Ces pirates collectionnent les objets magiques, et la réapparition des ruines y a laissé des biens à prendre. Ce sont leurs artefacts volés que recherche le contact de Revilgaz."}},faq={{q="Qui veut les artefacts des Saltseers ?",a="Un contact du Baron Revilgaz vous demande de récupérer les artefacts.",al={"qui m’a envoyé","contact du baron revilgaz","qui veut les artefacts"}},{q="Qui sont les Saltseers ?",a="Les Saltseers sont des pirates qui collectionnent les artefacts magiques.",al={"pirates saltseers","qui sont les saltseers","saltseers"}},{q="Où sont les Saltseers ?",a="Ils se trouvent à Drowned City, des ruines trolles englouties qui ont refait surface.",al={"où se trouve drowned city","emplacement des saltseers","drowned city"}},{q="Quels artefacts dois-je chercher ?",a="On vous demande de récupérer les Voodoo Infused Artifacts volés par les Saltseers.",al={"quoi récupérer","artefacts vaudous","biens volés"}}},fp="15,205,19.255.0,37.62.0,22.56.0,24.71.0,32.74.0"}
P.entries["quest:95791"] = {n="The Saltseer Captain",s="Un chasseur rival veut éliminer Captain Dreadrise et ses Saltseer Coroners de Drowned City. Leur équipage ne cesse de rassembler les artéfacts magiques qu’il recherche.",h="Un chasseur rival veut éliminer Captain Dreadrise et ses Saltseer Coroners de Drowned City.",kw={"captain dreadrise","drowned city","artéfacts magiques","pirates","saltseer","saltseer coroners"},sec={{t="Un rival dans la cité",b="Un chasseur rival sollicite votre aide à Drowned City, où les pirates Saltseer sont devenus une épine dans son pied. Captain Dreadrise et ses Saltseer Coroners rassemblent les artéfacts magiques qu’il convoite. Il vous demande de mettre le capitaine et trois membres de son équipage hors jeu."}},faq={{q="Qui est Captain Dreadrise ?",a="Captain Dreadrise dirige les pirates Saltseer à Drowned City.",al={"dreadrise","capitaine saltseer","le capitaine"}},{q="Qui sont les Saltseer Coroners ?",a="Les Saltseer Coroners sont des membres d’équipage avec lesquels Captain Dreadrise rassemble des artéfacts magiques.",al={"équipage saltseer","coroners","équipage de dreadrise"}},{q="Pourquoi le donneur de quête veut-il se débarrasser de Dreadrise ?",a="Captain Dreadrise et son équipage ne cessent de rassembler les artéfacts magiques que recherche le donneur de quête, qui en a assez de cette concurrence.",al={"pourquoi tuer dreadrise","pourquoi éliminer le capitaine","rival de dreadrise"}},{q="Où se trouvent Captain Dreadrise et les Saltseers ?",a="Captain Dreadrise et les pirates Saltseer se trouvent à Drowned City.",al={"où est dreadrise","emplacement des saltseer","pirates de drowned city"}},{q="Que me demande le donneur de quête ?",a="Le donneur de quête vous demande de tuer Captain Dreadrise et trois Saltseer Coroners à Drowned City.",al={"que faire","quête de dreadrise","tâche saltseer"}}},fp="20,154,19.268.0,25.65.0,30.99.0,39.127.0,46.67.0,33.93.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="Sur le site de fouilles, un nain tombé au combat laisse de sombres nouvelles à son frère, à Comté-du-Lac. Dorin Songblade apprend le sort des siens et découvre les présents qu'il n'a pas pu achever à temps.",h="Sur le site de fouilles, un nain tombé au combat laisse de sombres nouvelles à son frère, à Comté-du-Lac.",kw={"forgeron","dorin","dorin songblade","nain","site de fouilles","sites de fouilles","fallen in the fen","comté-du-lac","songblade"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous pouvez réconforter un artisan éploré aux Carmines. Un habitant cherche l'apaisement en ces temps troublés pour le royaume.",["profession:Blacksmithing"]="En tant que forgeron, vous comprenez le soin que Dorin a mis dans les armes destinées à surprendre les siens. À présent, cet équipement lui rappelle la mort prématurée de son frère.",["race:Dwarf"]="En tant que nain, vous connaissez le chagrin de perdre un frère dans d'anciens sites de fouilles et une nature sauvage. Vous savez que le métal travaillé peut survivre à la main qui devait le tenir."},sec={{t="Une tragédie sur le site",b="Sur les sites de fouilles, un nain aventureux gît sans vie. Vous recouvrez sa dépouille de sa propre cape, puis portez la sinistre nouvelle à Comté-du-Lac pour retrouver les siens."},{t="Le chagrin d'un frère",b="Dorin Songblade est un artisan nain de Comté-du-Lac. Quand il apprend le sort de son frère, le chagrin le submerge. Pendant des semaines, il a travaillé à sa forge à un ensemble d'équipement surprise, mais celui-ci n'était pas prêt avant le départ de son frère en expédition. Il regrette de ne pas l'avoir accompagné.\n\nDorin ne peut se résoudre à reforger, vendre ou garder ce qu'il a fabriqué de ses propres mains. Il offre donc les pièces terminées à la personne qui lui a apporté l'apaisement."}},faq={{q="Qu'est-ce que Fallen in the Fen ?",a="Sur les sites de fouilles, vous trouvez un nain tombé au combat et recouvrez son corps de sa propre cape. Puis vous annoncez son sort à son frère éploré, Dorin Songblade, à Comté-du-Lac.",al={"qu'est-ce que fallen in the fen","quête fallen in the fen"}},{q="Qui est Dorin Songblade ?",a="Dorin Songblade est un forgeron nain de Comté-du-Lac. Il forgeait un ensemble d'équipement surprise pour son frère quand il a appris sa mort sur les sites de fouilles.",al={"qui est dorin songblade","dorin à comté-du-lac","rôle de dorin songblade"}},{q="Qui est le nain tombé au combat que l'on trouve sur le site de fouilles ?",a="Le nain tombé au combat était le frère de Dorin Songblade. Avant son expédition, il est passé par Comté-du-Lac pour rassembler des provisions, puis a trouvé la mort sur le terrain.",al={"qui est mort dans le marais","nain mort sur le site de fouilles","à qui appartient le corps sur le site de fouilles"}},{q="Où trouver Dorin Songblade ?",a="Dorin Songblade vit à Comté-du-Lac, le principal établissement des Carmines. Il y travaille à la forge.",al={"où est dorin songblade","emplacement de dorin songblade"}},{q="Que forgeait Dorin pour son frère ?",a="Dorin forgeait de l'équipement pour l'offrir par surprise à son frère. Il n'avait pas terminé son ouvrage quand celui-ci est parti en expédition. Dorin ne peut se résoudre à garder, reforger ou vendre l'équipement.",al={"que forgeait dorin","cadeau surprise de dorin"}},{q="Pourquoi Dorin donne-t-il les objets qu'il a fabriqués ?",a="Dorin regrette de ne pas avoir accompagné son frère et ne peut se résoudre à garder, reforger ou vendre les armes qu'il a fabriquées. Il offre les pièces terminées au voyageur qui lui a annoncé le sort des siens.",al={"pourquoi dorin a-t-il donné l'équipement","pourquoi dorin vous donne-t-il de l'équipement"}}},fp="17,175,18.158.0,17.401.1,26.175.0,23.161.0,48.153.0,35.114.0,39.182.0,46.176.0"}
P.entries["quest:95798"] = {n="The Web of Magic",s="Un ami vous demande d’apporter l’I'lalai Fetish à Abra Cadabra, à Dalaran. Elle s’intéresse à la magie des trolls et veut l’examiner.",h="Un ami vous demande d’apporter l’I'lalai Fetish à Abra Cadabra, à Dalaran.",kw={"abra cadabra","magies contradictoires","dalaran","i'lalai fetish","kirin tor","maître des traditions dibbs","magie des trolls"},sec={{t="Un fétiche pour Abra",b="L’I'lalai Fetish est destiné à Abra Cadabra, à Dalaran, où elle pourra l’examiner. On vous demande de le lui apporter, même si le Kirin Tor se montre parfois pointilleux envers les visiteurs de sa cité."},{t="Les découvertes d’Abra",b="Abra Cadabra découvre plusieurs magies différentes qui agissent sur le fétiche, dont certaines s’opposent. Elle vous avertit qu’il pourrait être dangereux entre des mains imprudentes et dit qu’elle transmettra ses découvertes à Maître des traditions Dibbs."}},faq={{q="Qui est Abra Cadabra ?",a="Abra Cadabra est une amie de la personne qui vous demande de lui apporter l’I'lalai Fetish. Elle s’intéresse aux pratiques et à la magie des trolls.",al={"qui est abra","abra cadabra","abra"}},{q="Qu’est-ce que l’I'lalai Fetish ?",a="L’I'lalai Fetish est un objet qu’Abra Cadabra examine pour en étudier les magies diverses et contradictoires.",al={"qu’est-ce que le fétiche","objet i'lalai","fétiche"}},{q="Pourquoi Abra veut-elle l’examiner ?",a="Abra s’intéresse particulièrement aux pratiques et à la magie des trolls, et le fétiche est une découverte qu’elle peut étudier.",al={"pourquoi abra le veut","abra intéressée","magie des trolls"}},{q="Où faut-il apporter le fétiche ?",a="On vous demande d’apporter l’I'lalai Fetish à Abra Cadabra, à Dalaran.",al={"où apporter le fétiche","livraison à dalaran","lieu où se trouve abra"}},{q="Pourquoi pourrait-il être difficile d’entrer à Dalaran ?",a="Le Kirin Tor peut se montrer pointilleux sur les personnes qu’il laisse entrer à Dalaran, et vous devrez peut-être gagner ses faveurs.",al={"entrer à dalaran","entrée du kirin tor","accès à dalaran"}}},fp="16,131,17.184.0,15.204.1,20.132.0,27.95.0,33.108.0,33.69.0,38.110.0"}
P.entries["quest:95799"] = {n="Findings for the Explorer's League",s="Maître des traditions Dibbs vous demande de porter ses traductions des tablettes I'lalai à l’Historien Karnik, à Forgefer. Karnik voit dans cette découverte une raison d’envoyer une équipe vers la ville perdue.",h="Maître des traditions Dibbs vous demande de porter ses traductions des tablettes I'lalai à l’Historien...",kw={"ligue des explorateurs","découvertes de la ligue des explorateurs","historien karnik","i'lalai","forgefer","maître des traditions dibbs","tablettes","traductions","trolls"},sec={{t="Une lettre pour Forgefer",b="L’Historien Karnik est le collègue de Maître des traditions Dibbs à l’Explorer’s League, à Forgefer. Dibbs a fait une découverte qu’il juge importante pour l’histoire et vous demande de remettre à Karnik sa lettre ainsi qu’une copie de ses traductions des tablettes I’lalai."},{t="La réponse de Karnik",b="Karnik accueille favorablement les traductions de Dibbs et annonce qu’il réunira une équipe pour rechercher la ville perdue d’I'lalai. Ses propres études portent sur d’autres sujets, mais il respecte l’intérêt de Dibbs pour les trolls."}},faq={{q="Qui me demande de porter la lettre ?",a="Maître des traditions Dibbs vous demande de porter sa lettre et un exemplaire de ses traductions des tablettes I'lalai à l’Historien Karnik, à Forgefer.",al={"qui m’a donné ceci","lettre de dibbs","qui est maître des traditions dibbs"}},{q="Qui est l’Historien Karnik ?",a="L’Historien Karnik est le collègue de la Ligue des explorateurs à Forgefer qui reçoit la lettre et les traductions de Maître des traditions Dibbs.",al={"qui est karnik","karnik forgefer","historien"}},{q="Que sont les traductions d’I'lalai ?",a="Ce sont les traductions par Maître des traditions Dibbs de tablettes liées à I'lalai.",al={"traductions d’ilalai","traductions des tablettes","tablettes de dibbs"}},{q="Pourquoi Dibbs veut-il que je porte la lettre ?",a="Dibbs dit que cette découverte revêt une grande importance historique et veut en informer rapidement son collègue à Forgefer.",al={"pourquoi porter la lettre","pourquoi forgefer","que veut dibbs"}}},fp="34,175,21.244.0,17.183.1,37.124.0,24.120.0,34.72.0,42.114.0"}
P.entries["quest:95803"] = {n="A Token of Good Faith",s="Danitha vous charge de porter la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse. Cette livraison doit montrer aux Réprouvés que votre peuple se dévoue à leur prospérité.",h="Danitha vous charge de porter la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse.",kw={"a token of good faith","danitha","dame noire","réprouvés","lumière","rudolph gelhardt","sylvanas coursevent","fossoyeuse"},sec={{t="Une preuve de loyauté",b="Danitha affirme que Sylvanas se méfie de votre peuple et le dénigre ouvertement. Elle vous demande d’apporter la tête de Rudolph Gelhardt pour prouver que vous vous occupez de vos affaires et soutenez les Réprouvés."},{t="La réponse de la Dame noire",b="Sylvanas doute que l’ordre de Danitha puisse empêcher d’autres de ses membres de tourner la Lumière contre leur propre peuple. Elle avertit qu’elle pourrait ne plus tolérer l’ordre s’il cesse de servir les intérêts des Réprouvés. L’ordre sera surveillé."}},faq={{q="Qui me demande d’apporter la tête de Rudolph Gelhardt à Sylvanas ?",a="Danitha vous demande de porter la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse.",al={"qui m’envoie auprès de sylvanas","livraison de la tête par danitha","tête pour la dame noire"}},{q="Pourquoi Danitha veut-elle que j’apporte la tête à Sylvanas ?",a="Danitha veut que cette livraison montre à Sylvanas que votre peuple s’occupe de ses affaires et se dévoue à la prospérité des Réprouvés.",al={"pourquoi apporter la tête de rudolph","à quoi sert cette livraison","prouver sa loyauté"}},{q="Pourquoi Sylvanas se méfie-t-elle du peuple de Danitha ?",a="Danitha affirme que Sylvanas se méfie énormément de votre peuple et le dénigre presque ouvertement.",al={"pourquoi sylvanas se méfie de nous","méfiance de la dame noire","pourquoi nous dénigre-t-elle"}},{q="Où dois-je apporter la tête de Rudolph Gelhardt ?",a="On vous demande d’apporter la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse.",al={"où se trouve sylvanas","lieu de livraison de la tête","l’apporter à fossoyeuse"}}},fp="21,186,17.189.0,24.238.1,59.92.0,55.135.0,46.86.0,42.89.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Sur la Mesa de Nuage rouge, An'she et Mu'sha sont honorés comme les yeux de la Terre-Mère. Vous portez un encens fumant jusqu'à un sanctuaire dans les collines du sud-est, où sa fumée s'élève vers le soleil et la lune, qui apportent chaleur, vie et orientation aux plaines.",h="Sur la Mesa de Nuage rouge, An'she et Mu'sha sont honorés comme les yeux de la Terre-Mère.",kw={"an'she","terre-mère","lune","mu'sha","mulgore","mesa de nuage rouge","sanctuaire","encens fumant","soleil","tauren"},ang={["class:Druid"]="En tant que druide tauren, vous voyez dans l'éternelle danse du soleil et de la lune l'équilibre primordial de la nature, qui guide votre compréhension de ses rythmes cosmiques.",["class:Shaman"]="En tant que chaman tauren, vous communiez avec les esprits de la terre, du feu, de l'eau et de l'air, et rendez un hommage égal aux jumeaux célestes dont la lumière nourrit l'énergie vitale.",["faction:Horde"]="En tant que membre de la Horde, vous découvrez les rites sacrés de la Mesa de Nuage rouge et les traditions des Tauren nomades, qui révèrent la nature et les partagent avec leurs alliés.",["race:Tauren"]="En tant que Tauren, vous apprenez que la vie vous appelle à honorer An'she et Mu'sha aussi fidèlement que la Terre-Mère. Leur vénération est au cœur de l'identité spirituelle des Tauren et rappelle leur devoir aux jeunes braves."},sec={{t="Les yeux de la Terre-Mère",b="Les Tauren honorent An'she et Mu'sha comme le soleil et la lune, les yeux jumeaux de la Terre-Mère. Des esprits élémentaires habitent les pierres, les vents et les eaux d'Azeroth, tandis que les jumeaux célestes veillent depuis les hauteurs des cieux. En traversant le ciel, ils marquent le jour et la nuit et apportent chaleur, guidance et espoir aux créatures vivantes. Pour les Tauren, les honorer est un devoir spirituel. L'équilibre exige de révérer la terre sous vos pieds et la lumière au-dessus de vous."},{t="Une offrande sur les hauteurs",b="Portez l'encens fumant dans les collines du sud-est qui surplombent la Mesa de Nuage rouge, juste au sud des terres épineuses des quilboars. Faites le trajet avec célérité et prudence. Gardez les braises au sec et atteignez le sanctuaire avant qu'elles ne se réduisent en cendres froides. Au sanctuaire perché, jetez-les dans le Sacred Fire. Leur fumée parfumée porte votre respect vers le ciel, en direction du soleil et de la lune."}},faq={{q="Qui sont An'she et Mu'sha ?",a="Dans les croyances des Tauren, An'she et Mu'sha sont le soleil et la lune, honorés comme les yeux jumeaux de la Terre-Mère. Ils brillent depuis les cieux, contrairement aux esprits qui habitent la terre, l'air, le feu et l'eau d'Azeroth. An'she apporte chaleur et vie, tandis que Mu'sha offre guidance et réconfort pendant la nuit.",al={"qui sont an'she et mu'sha","histoire d'an'she et mu'sha","dieux taurens du soleil et de la lune"}},{q="Pourquoi les Tauren offrent-ils des présents au soleil et à la lune ?",a="Selon les enseignements des Tauren, l'équilibre est essentiel à l'existence. An'she et Mu'sha donnent aux créatures vivantes énergie, vision et espoir. En offrant de l'encens en hauteur, les Tauren témoignent leur respect aux deux lumières célestes, dont la bienveillance constante est indispensable à la vie des mortels.",al={"pourquoi révérer le soleil et la lune","culte céleste des tauren","pourquoi honorer an'she et mu'sha"}},{q="Où se trouve le sanctuaire d'An'she et de Mu'sha ?",a="Le sanctuaire se trouve dans les hautes collines au sud-est de la Mesa de Nuage rouge. Il surplombe les plaines, juste au sud des territoires épineux des quilboars. Sa hauteur offre une vue dégagée sur le ciel ouvert, où la fumée peut s'élever vers les cieux.",al={"où se trouve le sanctuaire d'an'she","emplacement du sanctuaire à mulgore","comment trouver le sanctuaire de l'encens"}},{q="Quelle est la signification de l'encens fumant ?",a="L'encens fumant porte la prière et le respect du voyageur vers le soleil et la lune. Sa fumée parfumée s'élève des braises ardentes. Jetez-les dans le feu du sanctuaire pour achever le rite et procurer au pèlerin un paisible sentiment d'accomplissement spirituel.",al={"à quoi sert l'encens","signification de l'offrande d'encens","pourquoi brûler de l'encens fumant"}},{q="Pourquoi faut-il livrer l'encens rapidement et le garder au sec ?",a="L'encens doit encore fumer lorsqu'il atteint le feu du sanctuaire. Le trajet exige donc vigilance, célérité et prudence. Achevez-le avant que les braises ne se réduisent en cendres froides et protégez-les de l'eau, qui les éteindrait et gâcherait l'offrande.",al={"pourquoi l'encens doit-il être livré à temps","ne pas le mouiller","l'encens qui se consume"}},{q="Les quilboars menacent-ils le pèlerinage au sanctuaire ?",a="Des tribus de quilboars occupent des repaires épineux défendus dans les collines, juste au nord du sanctuaire. Celui-ci se trouve sur un belvédère paisible au sud de leurs terres, mais les voyageurs doivent éviter les fourrés des quilboars, où une attaque pourrait retarder ou interrompre le trajet.",al={"quilboars près du sanctuaire","les quilboars menacent-ils les pèlerins","quilboars au sud de la mesa"}},{q="En quoi Mu'sha diffère-t-elle des conceptions de la lune d'autres cultures ?",a="Les Tauren appellent la lune Mu'sha, l'œil gauche aimant de la Terre-Mère, qui veille sur la vie des mortels. Les Elfes de la nuit révèrent la même lune blanche et lumineuse sous le nom d'Elune, tandis que la tradition des Tauren lie Mu'sha à son jumeau solaire, An'she.",al={"mu'sha est-elle elune","mu'sha et elune chez les tauren","mu'sha et les elfes de la nuit"}}},fp="26,245,27.439.0,26.365.0,26.278.0,53.262.0,49.238.0,51.250.0,55.237.0,54.242.0,61.217.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Dans les Paluns, Ardin Grassman survit aux dangers du marais et envoie un message au Port de Menethil. Un voyageur porte un cœur de roseaux à Caitlin Grassman.",h="Dans les Paluns, Ardin Grassman survit aux dangers du marais et envoie un message au Port de Menethil.",kw={"caitlin grassman","grassman","heartwoven","port de menethil","cœur de roseaux","roseaux","les paluns"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous pouvez contribuer à sécuriser les routes périlleuses des marais autour du Port de Menethil, dont dépendent les civils.",["profession:Cooking"]="En apprenant que son époux a survécu, Caitlin se met à préparer un repas chaud et copieux pour l'accueillir chez lui."},sec={{t="Un signal des marais",b="Ardin Grassman est allé observer les étranges herbes des sites de fouilles des Paluns, mais s'est retrouvé bloqué au milieu des dangers du marais. Vous ouvrez un passage dans les terres sauvages, lui permettant de se reposer et de rassembler sa récolte. Épuisé mais déterminé, Ardin se prépare à repartir vers la sécurité du port."},{t="Gages de Menethil",b="Avant de prendre le chemin du retour, Ardin sort des roseaux des marais de son sac et les tresse en forme de cœur. Il vous confie ce gage pour que vous le portiez à Caitlin Grassman, au Port de Menethil. Elle attend, rongée par l'inquiétude. Apprendre qu'Ardin a survécu et reviendra bientôt la soulage, tout comme le cœur de roseaux et la promesse d'un repas chaud."}},faq={{q="En quoi consiste la quête Heartwoven ?",a="Un voyageur aide Ardin Grassman après qu'il s'est retrouvé bloqué sur les sites de fouilles des Paluns. Ardin fabrique un cœur de roseaux pour annoncer qu'il a survécu et témoigner son affection à Caitlin Grassman, qui l'attend au Port de Menethil.",al={"quête heartwoven","qu'est-ce que heartwoven","heartwoven dans les paluns"}},{q="Qui est Caitlin Grassman ?",a="Caitlin Grassman attend anxieusement son mari Ardin au Port de Menethil. Elle craint pour sa vie depuis son départ pour les sites de fouilles des Paluns et est soulagée lorsque vous lui apprenez qu'il a survécu.",al={"qui est caitlin grassman","caitlin port de menethil","caitlin grassman"}},{q="Qu'est-ce que le cœur tressé en roseaux ?",a="Le cœur tressé en roseaux est un gage qu'Ardin fabrique avec les roseaux des marais dans son sac. Il vous le confie pour rassurer Caitlin : il est vivant et rentrera bientôt chez lui.",al={"qu'est-ce que le cœur de roseaux","cœur tressé en roseaux"}},{q="Où rendre la quête Heartwoven ?",a="Vous apportez le cœur de roseaux à Caitlin Grassman, au Port de Menethil, une ville portuaire de l'Alliance sur la côte ouest des Paluns.",al={"où rendre heartwoven","lieu de remise de heartwoven","où se trouve caitlin grassman"}},{q="Qui vous confie la quête Heartwoven ?",a="Ardin Grassman vous donne le cœur à porter à Caitlin, son épouse. Après que vous avez dégagé un passage sûr dans les Paluns, il se repose, rassemble ses bottes et vous envoie en avant avec le gage.",al={"qui donne heartwoven","qui fabrique le cœur","le survivant heartwoven"}},{q="Qu'est-il arrivé au cueilleur bloqué ?",a="Ardin s'est rendu aux sites de fouilles pour voir d'étranges herbes géantes, mais la faune agitée a submergé l'équipe de fouilles, surtout les araignées. Vous ouvrez un passage à travers les menaces alentour, permettant à Ardin de survivre, de rassembler ses bottes et de rentrer au Port de Menethil.",al={"qu'est-il arrivé au cueilleur","est-il vivant","survivant de heartwoven"}}},fp="10,154,25.296.0,18.318.0,29.211.0,24.201.0,29.156.0,32.125.0,35.182.0,39.273.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="Vous transportez une relique brisée de méca-roche à travers les Paluns jusqu'au Prospecteur Whelgar. Son étrange matériau attire le regard des chercheurs nains.",h="Vous transportez une relique brisée de méca-roche à travers les Paluns jusqu'au Prospecteur Whelgar.",kw={"automate","site de fouilles","ligue des explorateurs","lost relic carry","prospecteur whelgar","méca-roche","relique des titans","les paluns"},ang={["profession:Engineering"]="En tant qu'ingénieur, vous voyez que le matériau composite et la conception complexe du méca-roche reposent sur des principes mécaniques qui dépassent l'ingénierie mortelle ordinaire.",["race:Dwarf"]="En tant que nain, vous partagez l'ardeur de votre peuple à exhumer les anciennes reliques de leurs créateurs. Ce fragment est une découverte précieuse pour l'héritage nain."},sec={{t="Un fragment d'art ancien",b="Un méca-roche a laissé derrière lui un fragment brisé de son art ancien. Son alliage inhabituel révèle qu'il faisait partie d'un mécanisme sophistiqué lié aux Titans."},{t="Livraison au site de fouilles",b="Le Prospecteur Whelgar étudie des vestiges anciens sur le site de fouilles des Paluns. Apportez-lui la relique sans l'endommager et les érudits nains disposeront d'une preuve matérielle pour étudier leur héritage ancien."}},faq={{q="Qu'est-ce que la Relique des Titans ?",a="La Relique des Titans est un fragment brisé d'un ancien automate méca-roche. Son alliage inconnu faisait partie d'un dispositif mécanique complexe.",al={"qu'est-ce que la relique","quel est cet objet","fragment de méca-roche"}},{q="Qui est le Prospecteur Whelgar ?",a="Le Prospecteur Whelgar est un chercheur nain qui supervise le site de fouilles des Paluns. Il étudie les anciens vestiges terrestres et les reliques découvertes dans la région.",al={"qui est whelgar","l'histoire de whelgar","responsable des fouilles"}},{q="Où faut-il livrer la relique ?",a="Apportez la relique au Prospecteur Whelgar, sur son site de fouilles des Paluns. Là-bas, des fouilleurs nains étudient d'anciennes ruines.",al={"où l'apporter","où le remettre","emplacement de whelgar"}},{q="Qui a créé l'automate méca-roche ?",a="Le fragment est identifié comme une relique des Titans. Les traditions naines associent les anciennes constructions mécaniques et les automates de pierre aux énigmatiques Titans, qui ont façonné le monde.",al={"qui a créé le méca-roche","origines de l'automate","lien avec les titans"}},{q="Pourquoi le Prospecteur Whelgar traite-t-il la relique avec déférence ?",a="Whelgar respecte les dangers qu'il faut affronter pour atteindre les profondeurs où reposent ces automates. Selon lui, survivre à cette expédition et en revenir avec un fragment intact force le respect.",al={"pourquoi whelgar est impressionné","expédition périlleuse"}},{q="Qu'a de particulier le matériau de l'automate ?",a="Le matériau de l'automate est un alliage inhabituel, différent de la pierre ordinaire ou du métal forgé. Il témoigne du savoir-faire sophistiqué des anciennes constructions des Titans.",al={"quel est ce matériau","alliage étrange"}}},fp="16,141,27.158.0,26.198.0,24.140.0,26.167.0,42.130.0,37.159.0,59.164.0,47.153.0"}
P.entries["quest:95882"] = {n="WANTED: Scoutmaster Vargas",s="Neza Bloodsnout veut faire éliminer Scoutmaster Vargas, dont les reconnaissances ont entravé la Horde. Elle exige son œil comme preuve de sa mort.",h="Neza Bloodsnout veut faire éliminer Scoutmaster Vargas, dont les reconnaissances ont entravé la Horde.",kw={"éclaireur de l’alliance","neza bloodsnout","rives claires","rog’mar","équipe d’éclaireurs","scoutmaster vargas","œil du maître-éclaireur"},ang={["faction:Horde"]="En tant que membre de la Horde, vous aidez Neza à éliminer un maître-éclaireur de l’Alliance dont les repérages entravent les déplacements de la Horde."},sec={{t="La traque de Neza",b="Neza Bloodsnout a déjà pris un œil à Scoutmaster Vargas, mais l’humain s’est échappé. Ses reconnaissances compliquent la tâche de la Horde pour suivre les mouvements de l’Alliance. Neza vous demande maintenant de lui rapporter l’autre œil de Vargas, preuve que le maître-éclaireur n’est plus."},{t="Le rapport",b="Neza apprend que Vargas est mort et affirme que les Rives Claires sont plus sûres pour la Horde. Elle regrette qu’il n’ait pas vécu aveugle après tout ce qu’il avait vu."}},faq={{q="Qui est Scoutmaster Vargas ?",a="Scoutmaster Vargas est un humain qui dirige une équipe d’éclaireurs de l’Alliance sur une petite île au nord-est de Rog’mar.",al={"vargas","qui est vargas"}},{q="Pourquoi Neza veut-elle la mort de Vargas ?",a="Les reconnaissances de Vargas compliquent la tâche de la Horde pour suivre les mouvements ennemis, et Neza affirme qu’il sait qu’elle le traque.",al={"pourquoi tuer vargas","neza vargas"}},{q="Où a-t-on aperçu Vargas ?",a="Une équipe d’éclaireurs de l’Alliance dirigée par Vargas a été aperçue sur une petite île au nord-est de Rog’mar.",al={"île de vargas","où est le maître-éclaireur"}},{q="Que me demande Neza de rapporter ?",a="Neza vous demande de lui rapporter l’autre œil de Scoutmaster Vargas, preuve de sa mort.",al={"œil de vargas","quelle preuve"}},{q="Qui est Neza Bloodsnout ?",a="Neza Bloodsnout se trouve à Rog’mar et veut une preuve que Scoutmaster Vargas n’est plus.",al={"neza","qui veut vargas"}},{q="Que dit Neza après la mort de Vargas ?",a="Neza accepte la mort de Vargas et affirme que les Rives Claires sont plus sûres pour la Horde.",al={"fin de vargas","que se passe-t-il ensuite"}}},fp="26,137,14.255.0,10.142.1,26.104.0,31.119.0,22.89.0,36.83.0,23.81.0,37.82.0"}
P.entries["quest:95883"] = {n="The Tortured Soul",s="Au Péril de Beren, dans la Forêt des Pins-Argentés, un rite obscur attend d’être achevé. Une note abandonnée indique les dernières offrandes requises : du sang et une âme marquée par la souffrance.",h="Au Péril de Beren, dans la Forêt des Pins-Argentés, un rite obscur attend d’être achevé.",kw={"péril de beren","énergie impie","offrande de sang","pierre d’offrande","rituel","forêt des pins-argentés","l’âme torturée"},ang={["class:Priest"]="Le rite tire une énergie impie des esprits souffrants, en opposition directe avec les principes réparateurs de la Lumière sacrée.",["class:Warlock"]="Canaliser des âmes tourmentées et préparer des rites obscurs auprès d’anciennes pierres d’offrande reflètent la nature sinistre et manipulatrice de la magie démoniaque et de Shadow Magic.",["race:Undead"]="La Forêt des Pins-Argentés est un territoire des Réprouvés, où la magie noire et les souffrances persistantes menacent les frontières de Lordaeron."},sec={{t="Un rite précipité",b="Au Péril de Beren, dans la Forêt des Pins-Argentés, un autel porte les vestiges d’un rite obscur assemblé à la hâte. Une note griffonnée repose parmi les matériaux éparpillés. La plupart des ingrédients sont déjà réunis, mais le rite réclame encore du sang et une Âme torturée."},{t="Des énergies impies libérées",b="Les créatures qui vivent dans les escarpements du Péril de Beren endurent de grandes souffrances, ce qui en fait des sources convenables pour l’essence requise par le rite. Apportez cette âme à la sinistre The Offering Stone, et une énergie magique impie en jaillit. Le rite se rapproche de son accomplissement."}},faq={{q="Qu’est-ce que L’Âme torturée ?",a="L’Âme torturée raconte un rite obscur inachevé au Péril de Beren, dans la Forêt des Pins-Argentés. Une pierre d’offrande attend du sang et l’âme d’une créature tourmentée.",al={"quête de l’âme torturée","âme torturée pins-argentés","quête péril de beren"}},{q="Où se déroule ce rituel ?",a="L’autel rituel et sa pierre d’offrande se trouvent au Péril de Beren, une enclave montagneuse périlleuse de la Forêt des Pins-Argentés.",al={"où se trouve le rituel","où se trouve le péril de beren","emplacement de la pierre d’offrande"}},{q="Quels éléments faut-il pour le rituel ?",a="Un morceau de note posé près de l’autel indique que presque tous les matériaux ont été réunis. Il manque encore deux éléments : du sang et une Âme torturée.",al={"éléments requis pour le rituel","composants du rituel au péril de beren"}},{q="Où trouver l’Âme torturée ?",a="Les créatures qui vivent dans les escarpements voisins du Péril de Beren sont assez tourmentées pour fournir l’essence dont la pierre d’offrande a besoin.",al={"où trouver l’âme torturée","qui détient l’âme"}},{q="Que se passe-t-il quand on apporte l’Âme torturée à l’autel ?",a="Apporter l’âme tourmentée à la pierre d’offrande libère une énergie impie et rapproche le rite obscur de son achèvement.",al={"que se passe-t-il quand on apporte l’âme","rendre l’âme torturée"}},{q="Qui a créé le rituel au Péril de Beren ?",a="Aucun créateur n’est mentionné. La note et les matériaux rassemblés à la hâte laissent penser que quelqu’un a assemblé l’autel parmi les habitants hostiles du Péril de Beren.",al={"qui a créé le rituel","qui a écrit la note"}}},fp="17,163,12.253.0,23.250.1,26.158.0,34.114.0,44.129.0,36.120.0,60.116.0,40.147.0"}
P.entries["quest:95884"] = {n="The Offering Stone",s="Au Péril de Beren, une offrande rituelle se prépare sur The Offering Stone. Des fragments d’une note usée par les intempéries indiquent aux voyageurs où trouver l’autel, dans la Forêt des Pins-Argentés.",h="Au Péril de Beren, une offrande rituelle se prépare sur The Offering Stone.",kw={"péril de beren","ustensiles","the offering stone","rituel","morceau de note","forêt des pins-argentés"},ang={["class:Warlock"]="En tant que démoniste, vous pouvez voir dans les sinistres ustensiles de The Offering Stone des signes de pratiques rituelles qui méritent un examen attentif.",["faction:Horde"]="En tant qu’aventurier de la Horde dans la Forêt des Pins-Argentés, surveillez les rituels suspects et les activités des cultistes dans les crêtes ombragées du Péril de Beren."},sec={{t="Une Note en lambeaux",b="Un morceau de papier usé par les intempéries, trouvé dans la Forêt des Pins-Argentés, conserve des fragments sur un rituel et une pierre d’offrande toute proche. Le temps et l’humidité en ont effacé la plupart des mots. Suivez les indices jusqu’au Péril de Beren pour trouver le grossier autel en pleine nature."},{t="Le lieu du rituel",b="Au Péril de Beren, d’étranges ustensiles et des objets bizarres sont éparpillés sur la pierre brute. Quelqu’un se sert du lieu pour préparer une offrande ou un sombre rite, loin des regards indiscrets."}},faq={{q="Qu’est-ce que The Offering Stone ?",a="The Offering Stone est un autel brut au Péril de Beren, dans la Forêt des Pins-Argentés. Les ustensiles et objets étranges éparpillés dessus témoignent de préparatifs en vue d’une offrande ou d’un sombre rite.",al={"qu’est-ce que the offering stone","the offering stone forêt des pins-argentés","qu’est-ce que cette pierre"}},{q="Où se trouve The Offering Stone ?",a="Vous trouverez The Offering Stone au Péril de Beren, dans le sud de la Forêt des Pins-Argentés.",al={"où se trouve the offering stone","emplacement de the offering stone","trouver the offering stone"}},{q="Qui a créé The Offering Stone ou s’en sert ?",a="La note abîmée ne nomme pas les ritualistes. Les outils et objets laissés sur la pierre montrent que quelqu’un préparait une offrande ou un sombre rite à proximité.",al={"qui a créé the offering stone","qui se sert de the offering stone","qui accomplit le rituel"}},{q="Que dit la mystérieuse note ?",a="La majeure partie de la note est usée et illisible. Les fragments encore lisibles mentionnent des préparatifs pour un rituel et indiquent la présence d’une pierre d’offrande à proximité.",al={"quelle note","morceau de note forêt des pins-argentés","que dit la note"}},{q="Que trouve-t-on sur The Offering Stone ?",a="D’étranges outils, des ustensiles rituels et d’autres objets sont éparpillés sur la pierre brute, destinés à une offrande.",al={"quels objets se trouvent sur la pierre","quels ustensiles sur la pierre","objets sur the offering stone"}},{q="Quel genre de rituel se déroule ici ?",a="La note ne décrit pas entièrement le rite. La pierre sert d’autel où des objets ou des sacrifices sont disposés pour un rituel.",al={"quel rituel sur the offering stone","pourquoi une pierre d’offrande","quelle offrande dans la forêt des pins-argentés"}}},fp="18,157,15.246.0,15.183.0,27.173.0,38.80.0,39.145.0,34.141.0,36.110.0,44.129.0"}
P.entries["quest:95885"] = {n="The Offering of Blood",s="À Péril de Beren, le fragment de note réclame du sang à The Offering Stone. Vous y apportez une Âme torturée.",h="À Péril de Beren, le fragment de note réclame du sang à The Offering Stone.",kw={"péril de beren","rituel de sang","the offering of blood","the offering stone","sacrifice","forêt des pins-argentés","âme torturée"},ang={["class:Priest"]="En tant que prêtre, vous pourriez être troublé par l’usage d’une âme torturée dans un sinistre rite de sang, quel que soit son destin.",["class:Warlock"]="En tant que démoniste, vous connaissez les rites sombres et les pactes conclus avec les âmes. Même un adepte chevronné de la magie gangrenée peut frissonner à l’idée d’offrir du sang à une pierre ancienne et inconnue."},sec={{t="Le rite final",b="Au cœur de Péril de Beren, The Offering Stone attend une ultime offrande. Des fragments de note réclament un sacrifice volontaire et vous conduisent à apporter du sang à l’autel. À mesure que vous approchez avec cette essence agitée, l’effroi vous gagne."},{t="La pierre se fissure",b="L’Âme torturée absorbe le pouvoir persistant de la pierre. Le rite épuise l’ancien monument au lieu d’éveiller une terreur plus grande. Sa surface rugueuse se fissure, puis s’effondre en décombres. Quelque chose de brillant gît parmi les fragments brisés."}},faq={{q="Où se déroule ce rituel ?",a="Le rite a lieu à The Offering Stone, à Péril de Beren, dans la Forêt des Pins-Argentés. Le danger et une magie ténébreuse hantent la région.",al={"où se trouve cette quête","où trouver the offering of blood","quête de péril de beren"}},{q="Qu’est-ce que The Offering Stone ?",a="The Offering Stone est un ancien monument de Péril de Beren. Il réclame le sang d’un sacrifice volontaire pour libérer ou drainer le pouvoir qu’il renferme.",al={"qu’est-ce que the offering stone","the offering stone à péril de beren","autel à péril de beren"}},{q="À quoi sert l’Âme torturée ?",a="Une Âme torturée est offerte à The Offering Stone pour répondre à l’appel au sacrifice volontaire du fragment de note.",al={"qui est l’âme torturée","qu’est-ce qu’une âme torturée","quel sacrifice faut-il faire"}},{q="Que se passe-t-il une fois l’offrande accomplie ?",a="Le rite draine le pouvoir qui anime The Offering Stone. La pierre rugueuse se fissure et s’effrite, laissant quelque chose de brillant parmi ses débris.",al={"que devient la pierre","la pierre se brise-t-elle","que se passe-t-il après le rituel"}},{q="Qui a créé la pierre et pourquoi ?",a="Nul ne sait qui a créé The Offering Stone, ni pourquoi. Le rite draine son pouvoir et la détruit, mais le dessein de son créateur reste inconnu.",al={"qui a bâti the offering stone","but de the offering of blood","pourquoi la pierre a-t-elle été créée"}},{q="Qu’est-ce que Péril de Beren ?",a="Péril de Beren est un repère rocheux de la Forêt des Pins-Argentés, où rôdent des bêtes sauvages et des dangers cachés. Des rites sombres et des âmes agitées y ont aussi laissé leur empreinte.",al={"qu’est-ce que péril de beren","lore de péril de beren","pourquoi ce nom, péril de beren"}}},fp="21,114,14.216.0,18.241.1,34.127.0,27.140.0,35.106.0,44.144.0,30.132.0,22.161.0"}
P.entries["quest:959"] = {n="Fuite de porto aux docks",s="À Cabestan, une bouteille volée met l’emploi de Bigglefuzz en péril. Mad Magglish s’est enfui dans les terres avec un Porto vieux de 99 ans, cadeau du Baron Revilgaz à Gazlowe, et se cache maintenant dans les Cavernes des lamentations.",h="À Cabestan, une bouteille volée met l’emploi de Bigglefuzz en péril.",kw={"bigglefuzz","baie-du-butin","gazlowe","magglish","porto","cabestan","revilgaz","cavernes des lamentations"},ang={["class:Rogue"]="En tant que voleur, vous pouvez repérer la cachette négligente de Mad Magglish dans les recoins des cavernes, où il tente d’échapper aux regards grâce à une discrétion rudimentaire.",["faction:Alliance"]="En tant que membre de l’Alliance, vous voyagez au cœur des Tarides, dominées par la Horde. Entretenir de bonnes relations avec les exploitants des ports Gentepression aide à garantir un passage sûr dans les eaux neutres.",["faction:Horde"]="En tant que membre de la Horde, vous aidez les dockers de Cabestan à faire tourner le principal port neutre entre Kalimdor et les Royaumes de l'est."},sec={{t="Une maladresse coûteuse",b="Les quais de Cabestan assurent le commerce maritime avec Baie-du-Butin, de l’autre côté de la Grande mer. Un matin, une cargaison énorme est arrivée, et le Grutier Bigglefuzz a surchargé sa grue pour la décharger plus vite. La grue a déversé toute la cargaison sur les quais. Dans la confusion, Mad Magglish, un fauteur de troubles du coin, a chapardé une bouteille d’alcool de grande valeur et s’est enfui dans les terres."},{t="Un porto diplomatique",b="La bouteille est un Porto vieux de 99 ans, un cadeau diplomatique personnel du Baron Revilgaz, dirigeant de Baie-du-Butin, à Gazlowe, chef ingénieur et superviseur de Cabestan. Sa perte pourrait humilier Bigglefuzz et provoquer la colère des deux chefs du commerce. Craignant pour son emploi, ou pire, Bigglefuzz a suivi le voleur jusqu’à l’entrée des Cavernes des lamentations. Mais la peur l’a empêché d’y pénétrer."},{t="La cachette des cavernes",b="Mad Magglish se cache dans des tunnels naturels humides, à l’extérieur de l’entrée intérieure des Cavernes des lamentations, et non au cœur du paysage onirique corrompu. Le voleur compte sur sa discrétion maladroite et les alcôves sombres, en espérant que ses poursuivants renonceront. Retrouvez Magglish dans les cavernes extérieures avant que le porto ne soit débouché ou détruit."}},faq={{q="Pourquoi cette bouteille de porto est-elle si importante ?",a="Le Porto vieux de 99 ans est un somptueux cadeau personnel du Baron Revilgaz de Baie-du-Butin à Gazlowe, le chef de Cabestan. Le perdre pourrait provoquer la colère des dirigeants de Cabestan et coûter son gagne-pain au Grutier Bigglefuzz.",al={"pourquoi bigglefuzz s’en soucie","qu’est-ce que le porto vieux de 99 ans","pourquoi ce vin est important"}},{q="Qui est Mad Magglish ?",a="Mad Magglish est un voleur et un fauteur de troubles qui traîne dans les environs de Cabestan. Quand Bigglefuzz a déversé une énorme cargaison sur les quais, Magglish s’est emparé du porto rare et s’est enfui pour se cacher dans les Cavernes des lamentations, non loin de là.",al={"qui est magglish","qui a volé le porto","histoire de mad magglish"}},{q="Dois-je entrer dans le donjon des Cavernes des lamentations pour trouver le voleur ?",a="Non. Mad Magglish se cache dans les passages sinueux à l’extérieur du portail de l’instance. Il se dissimule mal dans les tunnels latéraux supérieurs ou près des salles inondées, à côté de l’entrée principale.",al={"magglish est-il dans l’instance","où trouver mad magglish","trouver magglish"}},{q="Comment la cargaison s’est-elle renversée ?",a="Une énorme cargaison est arrivée de Baie-du-Butin, et le Grutier Bigglefuzz a tenté de décharger plus de caisses à la fois que son équipement ne pouvait en supporter. La grue surchargée a déversé la cargaison sur les quais de Cabestan.",al={"pourquoi les caisses sont-elles tombées","qu’a fait bigglefuzz","accident de grue à cabestan"}},{q="Quels liens unissent Cabestan et Baie-du-Butin ?",a="Cabestan et Baie-du-Butin sont des villes portuaires du Cartel Gentepression, unies par le commerce et leurs flottes de corsaires. Des cargaisons régulières et des marques de courtoisie officielles circulent entre le Baron Revilgaz, au sud, et Gazlowe, dans les Tarides, et font prospérer leur empire commercial commun.",al={"lien entre cabestan et baie-du-butin","ports gentepression","revilgaz et gazlowe"}},{q="Pourquoi Bigglefuzz n’a-t-il pas récupéré la bouteille lui-même ?",a="Bigglefuzz a suivi le voleur jusqu’à l’entrée des Cavernes des lamentations, mais la sinistre réputation du labyrinthe souterrain et ses habitants monstrueux l’ont effrayé. Il s’est arrêté au seuil.",al={"pourquoi le gobelin ne l’a-t-il pas récupéré","pourquoi bigglefuzz a-t-il cessé la poursuite"}}},fx={b908c2b9={q="Pourquoi le Grutier Bigglefuzz a-t-il besoin de récupérer ce porto ?",a="L'emploi de Bigglefuzz est en jeu. Lorsqu'il a tenté de décharger plus de caisses que ce que sa grue pouvait supporter, l'intégralité de la cargaison matinale en provenance de Baie-du-Butin s'est effondrée. Dans la confusion, la bouteille de porto vieux de quatre-vingt-dix-neuf ans, pièce de choix, a disparu, et le maître du port ne le lâche plus d'une semelle. Comme ce cru était un cadeau personnel destiné à l'ingénieur en chef de Cabestan, Gazlowe, le fait de ne pas le récupérer signifie pour Bigglefuzz un licenciement immédiat.",al={"pourquoi bigglefuzz veut le porto","mobile de bigglefuzz","pourquoi aider bigglefuzz"}}},fp="20,185,15.333.0,18.354.0,18.284.0,40.201.0,20.201.0,65.176.0,31.206.0,55.245.0,50.185.0"}
P.entries["quest:95912"] = {n="WANTED: Blademaster Kaijo",s="Ember Bladewhisper cherche Blademaster Kaijo dans un camp d’entraînement au nord de l’avant-poste de la Horde. Sa bannière doit affaiblir le moral des orcs et renforcer la détermination des recrues d’Ember.",h="Ember Bladewhisper cherche Blademaster Kaijo dans un camp d’entraînement au nord de l’avant-poste de la Horde.",kw={"maître-lame kaijo","blademaster’s banner","ember bladewhisper","donjon de fort-lointain","avant-poste de la horde","kaijo","recrues orcs","camp d’entraînement"},sec={{t="Un combat qui s’essouffle",b="Ember Bladewhisper craint que chaque orc tombé soit remplacé par un soldat plus aguerri. Elle pense qu’un maître-lame les entraîne et que Kaijo se trouve probablement au camp d’entraînement au nord de l’avant-poste de la Horde. Vous devez rapporter sa bannière au Donjon de Fort-Lointain."},{t="Le rôle d’une bannière",b="Ember dit que la menace des orcs semble sans fin et que la détermination de ses soldats faiblit. Elle espère que la bannière de Kaijo montrera à ses recrues que la Horde n’a rien d’effrayant."}},faq={{q="Qui est Blademaster Kaijo ?",a="Ember Bladewhisper présente Kaijo comme un maître-lame qui entraîne probablement des orcs dans un camp d’entraînement au nord de l’avant-poste de la Horde.",al={"qui est kaijo","histoire de kaijo"}},{q="Pourquoi Ember veut-elle retrouver Kaijo ?",a="Ember pense que Kaijo forme une nouvelle génération de soldats orcs aguerris et craint que leurs effectifs ne se reconstituent.",al={"pourquoi retrouver kaijo","raison de la prime sur kaijo"}},{q="Où Ember pense-t-elle que se trouve Kaijo ?",a="Ember dit que Kaijo se trouve probablement au camp d’entraînement au nord de l’avant-poste de la Horde.",al={"où se trouve kaijo","lieu où se trouve kaijo"}},{q="Que veut Ember que vous rapportiez au Donjon de Fort-Lointain ?",a="Ember vous demande de lui rapporter la Blademaster’s Banner au Donjon de Fort-Lointain.",al={"bannière de kaijo","que rapporter au donjon de fort-lointain"}},{q="Pourquoi Ember veut-elle la bannière ?",a="Ember espère que la bannière affaiblira le moral des orcs et rassurera ses recrues : la Horde n’a rien d’effrayant.",al={"rôle de la bannière","pourquoi prendre la bannière de kaijo"}},{q="Qu’est-ce qui inquiète Ember dans ce combat ?",a="Ember craint que la menace des orcs ne prenne jamais fin et que la détermination de ses soldats ne faiblisse.",al={"ember inquiète","menace des orcs"}}},fp="25,187,17.254.0,18.164.0,25.126.0,32.111.0,32.74.0,46.75.0,31.106.0,35.84.0"}
P.entries["quest:95951"] = {n="Fetch 'n' Fletch",s="Tan’jani vous propose de vous apprendre à fabriquer des lances pour les chasseurs de têtes de la Horde. Vous êtes envoyé à Turner's Logging Camp chercher du bois pour en façonner des lances.",h="Tan’jani vous propose de vous apprendre à fabriquer des lances pour les chasseurs de têtes de la Horde.",kw={"chercher et empennage","chasseurs de têtes","horde","lances de fortune","tan’jani","turner's logging camp","fagots de bois"},sec={{t="Du bois pour des lances",b="Tan’jani, un chasseur de têtes, vous demande de ramasser du bois à Turner's Logging Camp, le camp humain à l’ouest. Avec un couteau, vous pouvez tailler les rondins en lances pour transpercer les humains avant qu’ils ne vous voient venir. Tan’jani veut que vous lui rapportiez les lances."}},faq={{q="Qui est Tan’jani ?",a="Tan’jani est un chasseur de têtes qui propose de vous apprendre à fabriquer des lances.",al={"qui est tan’jani","qui est tanjani"}},{q="Que veut que je ramasse Tan’jani ?",a="Tan’jani vous demande de ramasser du bois dans les tas de bois des paysans à Turner's Logging Camp et d’en façonner des lances de fortune.",al={"quel bois","obtenir des lances"}},{q="Où se trouve le bois ?",a="Le bois se trouve dans les tas de bois des paysans à Turner's Logging Camp, le camp humain à l’ouest.",al={"emplacement du bois","où trouver le bois"}},{q="Pourquoi Tan’jani veut-il des lances ?",a="Tan’jani dit que les chasseurs de têtes utilisent des lances pour frapper les humains avant qu’ils ne les voient venir.",al={"pourquoi des lances","lances des chasseurs de têtes"}}},fp="16,149,15.251.0,18.66.0,36.118.0,18.86.0,32.84.0"}
P.entries["quest:95955"] = {n="Stick 'Em",s="Tan'jani, à Rog’mar, vous apprend à lancer des lances dans les Rives Claires. Les Freshwater Crocolisks lui servent de cibles, et il espère que cette leçon fera de vous un chasseur de têtes.",h="Tan'jani, à Rog’mar, vous apprend à lancer des lances dans les Rives Claires.",kw={"crocolisque d’eau douce","chasseur de têtes","rives claires","rog’mar","lancer de lance","lances","fichez-les","tan'jani","tran'jani"},sec={{t="Une cible crocolisque",b="Tan'jani, à Rog’mar, vous fournit des lances et veut vous apprendre à les lancer. Les Rives Claires regorgent de Freshwater Crocolisks, qu'il dit dangereux. Il les place comme cibles pour votre entraînement."},{t="La promesse d’un chasseur de têtes",b="Après votre entraînement, Tan'jani salue votre travail et dit que vous avez l'étoffe d'un vrai chasseur de têtes. Il vous demande de ne pas l'oublier si vous devenez célèbre."}},faq={{q="Qui est Tan'jani ?",a="Tan'jani vous fournit des lances et vous apprend à les lancer à Rog’mar.",al={"tran'jani","qui est tran'jani","vieux troll"}},{q="Pourquoi Tan'jani m'envoie-t-il chasser des crocolisques ?",a="Tan'jani se sert des Freshwater Crocolisks des Rives Claires comme cibles pour vous entraîner au lancer de lance.",al={"pourquoi les crocolisques","entraînement contre les crocolisques","empaler les crocos"}},{q="Que veut Tan'jani que je fasse ?",a="Tan'jani veut que vous vous entraîniez à lancer des lances sur les Freshwater Crocolisks des Rives Claires.",al={"que faire","fichez-les","cibles pour les lances"}},{q="Où cela se passe-t-il ?",a="Tan'jani vous fournit les lances à Rog’mar et vous envoie vous entraîner dans les Rives Claires.",al={"où est tran'jani","quête des rives claires","rog’mar"}},{q="Que dit Tan'jani au sujet des crocolisques ?",a="Tan'jani vous prévient que les Freshwater Crocolisks sont dangereux et peuvent vous happer si vous n'êtes pas assez rapide.",al={"les crocos sont-ils dangereux","danger des crocolisques","vous happer"}}},fp="9,179,18.199.0,22.153.1,16.82.0,43.98.0,33.91.0,24.92.0,44.101.0"}
P.entries["quest:95981"] = {n="Watching the Roads",s="Le Prêtre des ombres Allister envoie les Réprouvés contre les patrouilles du Kirin Tor près de Moulin-de-l'Ambre. Depuis la chute de la barrière de Dalaran, leurs sorciers et leurs vigiles gardent les routes menant à la Forêt des Pins-Argentés et acheminent des objets magiques vers les terres réprouvées.",h="Le Prêtre des ombres Allister envoie les Réprouvés contre les patrouilles du Kirin Tor près de...",kw={"moulin-de-l'ambre","vigile de dalaran","sorcier de dalaran","kirin tor","pendentifs","reliques","le sépulcre","prêtre des ombres allister","forêt des pins-argentés","watching the roads"},ang={["class:Mage"]="En tant que Mage, vous affrontez les sorciers et les vigiles de Dalaran, qui utilisent des reliques magiques et des patrouilles pour garder les passages. Leur mission fait d'eux des cibles pour les lanceurs de sorts rivaux.",["class:Priest"]="En tant que Prêtre, vous voyez le Prêtre des ombres Allister diriger l'offensive depuis Le Sépulcre, où le clergé réprouvé prend une part active à la défense des frontières.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à perturber les lignes de ravitaillement de Dalaran près de Moulin-de-l'Ambre et à tenir la région face aux enclaves humaines hostiles.",["race:Undead"]="En tant que Mort-vivant, vous contribuez à sécuriser les routes de la Forêt des Pins-Argentés et à défendre les frontières réprouvées contre les incursions magiques de Dalaran."},sec={{t="Tensions sur la route de Moulin-de-l'Ambre",b="Près de Moulin-de-l'Ambre, les sorciers et les sentinelles du Kirin Tor surveillent les routes menant à la Forêt des Pins-Argentés. Depuis la chute de la barrière autour de Dalaran, ils ont renforcé leur contrôle sur les déplacements à travers la frontière. Depuis Le Sépulcre, les Réprouvés voient les mages humains emprunter ces routes pour transporter de dangereuses reliques et des pendentifs enchantés dans des terres disputées."},{t="Couper la ligne de ravitaillement",b="Le Prêtre des ombres Allister veut interrompre à la source le flux d'objets magiques de Dalaran. Il envoie des agents s'en prendre aux escortes du Kirin Tor sur les routes près de Moulin-de-l'Ambre. En attaquant les sorciers de Dalaran et les vigiles de Dalaran, les Réprouvés cherchent à briser l'emprise du Kirin Tor sur les déplacements dans la région et à protéger leur frontière orientale contre les ingérences arcaniques extérieures."}},faq={{q="Qui confie la quête Watching the Roads ?",a="Le Prêtre des ombres Allister donne ses ordres depuis Le Sépulcre, dans la Forêt des Pins-Argentés. Il envoie des champions contre les patrouilles du Kirin Tor sur les routes locales.",al={"qui confie watching the roads","donneur de quête watching the roads","où rendre watching the roads"}},{q="Pourquoi les Réprouvés attaquent-ils les patrouilles de Dalaran près de Moulin-de-l'Ambre ?",a="Le Prêtre des ombres Allister veut empêcher les reliques et les pendentifs magiques de Dalaran d'atteindre la Forêt des Pins-Argentés. En frappant les sorciers et les vigiles près de Moulin-de-l'Ambre, ils leur coupent le passage à travers les frontières réprouvées.",al={"pourquoi tuer les sorciers de dalaran","pourquoi attaquer les routes de moulin-de-l'ambre","objectif du kirin tor dans la forêt des pins-argentés"}},{q="Quelle est la situation de la barrière autour de Dalaran ?",a="La barrière autour de Dalaran est tombée. Le Kirin Tor a renforcé sa surveillance des routes voisines et patrouille dans la région de Moulin-de-l'Ambre avec méfiance.",al={"qu'est-il arrivé à la barrière de dalaran","dôme de dalaran tombé","barrière de dalaran tombée"}},{q="Où trouver les sorciers et les vigiles de Dalaran ?",a="Les sorciers de Dalaran et les vigiles de Dalaran patrouillent sur les routes autour de Moulin-de-l'Ambre, dans la Forêt des Pins-Argentés. Ils surveillent les déplacements et protègent le personnel du Kirin Tor ainsi que ses objets enchantés.",al={"où sont les vigiles de dalaran","emplacements des patrouilles de moulin-de-l'ambre","où trouver les sorciers de dalaran"}},{q="Quels objets Dalaran expédie-t-elle sur ces routes ?",a="Le Kirin Tor transporte des pendentifs enchantés et d'autres reliques magiques de Dalaran vers la Forêt des Pins-Argentés. Allister veut les arrêter avant que les artefacts ne se répandent davantage dans le territoire.",al={"quelles reliques dalaran expédie","que sont les pendentifs","pendentifs de moulin-de-l'ambre"}},{q="Pourquoi le Kirin Tor est-il si vigilant sur les routes de Moulin-de-l'Ambre ?",a="Le Kirin Tor surveille de près les routes menant à la Forêt des Pins-Argentés depuis la chute de la barrière magique de Dalaran. Allister remarque sa méfiance et sa vigilance, mais les Réprouvés du Sépulcre ignorent ses véritables motivations.",al={"pourquoi le kirin tor est-il paranoïaque","pourquoi les gardes de dalaran patrouillent-ils","contrôle des routes par le kirin tor"}}},fp="18,228,33.326.0,24.339.0,39.144.0,62.207.0,54.143.0,52.161.0,57.187.0,60.210.0"}
P.entries["quest:95982"] = {n="Not My Circus",s="Jasper Geartoggle vous demande d’aider à nourrir les animaux abandonnés au Port de Poudremèche. Il lui faut du Briny Seafood Stew avant que les bêtes affamées ne causent des problèmes.",h="Jasper Geartoggle vous demande d’aider à nourrir les animaux abandonnés au Port de Poudremèche.",kw={"briny seafood stew","chevaux","animaux affamés","jasper geartoggle","pas mon cirque","port de poudremèche","loups"},sec={{t="Bêtes affamées",b="Au Port de Poudremèche, Jasper Geartoggle vous demande de l’aider avec les animaux laissés sous sa garde. Leurs propriétaires le blâment quand un cheval, un loup ou une autre bête meurt ou s’enfuit. Il lui faut du Briny Seafood Stew pour les contenir, avant que la faim ne les pousse à charger en troupeau."}},faq={{q="Qui demande de l’aide ?",a="Jasper Geartoggle vous demande d’aider à nourrir les animaux laissés sous sa garde.",al={"qui a besoin d’aide","qui est jasper","jasper geartoggle"}},{q="De quoi Jasper a-t-il besoin ?",a="Jasper a besoin de Briny Seafood Stew pour les animaux dont il a la garde.",al={"quelle nourriture veut-il","quel ragoût","briny stew"}},{q="Pourquoi Jasper a-t-il besoin de ragoût ?",a="Jasper dit que les animaux ont faim et qu’il lui faut de la nourriture pour les contenir.",al={"pourquoi du ragoût","animaux affamés","animaux en difficulté"}},{q="Où dois-je apporter le ragoût ?",a="Apportez le Briny Seafood Stew à Jasper Geartoggle, au Port de Poudremèche.",al={"où est jasper","où apporter le ragoût","port de poudremèche"}},{q="Pourquoi laisse-t-on des animaux à Jasper ?",a="Les gens continuent de laisser leurs chevaux, leurs loups et leurs autres animaux à Jasper.",al={"animaux abandonnés","qui a laissé les animaux","pourquoi ces animaux sont ici"}}},fp="13,149,13.261.0,23.69.0,22.60.0,26.75.0,30.69.0,39.72.0"}
P.entries["quest:95991"] = {n="WANTED: Ghostmaw",s="Wheatley craint qu’un crocilisque fantôme nommé Ghostmaw n’emporte ses poneys les plus précieux le long des rivières. Il attend au Donjon de Fort-Lointain qu’on lui apporte le croc de la bête.",h="Wheatley craint qu’un crocilisque fantôme nommé Ghostmaw n’emporte ses poneys les plus précieux le long des...",kw={"crocilisque","croc","donjon de fort-lointain","ghostmaw","clairières","poneys","rivières","wheatley"},sec={{t="Les inquiétudes de Wheatley",b="Wheatley a cessé de déplacer ses chevaux dans les clairières après des signalements de Ghostmaw le long des rivières. On dit que ce crocilisque fait trois fois la taille d’un spécimen ordinaire et qu’il est deux fois plus féroce. Apportez à Wheatley le croc de Ghostmaw pour qu’il sache qu’il peut de nouveau voyager sans danger."}},faq={{q="Qui est Ghostmaw ?",a="Ghostmaw est un mystérieux crocilisque fantôme signalé le long des rivières. On dit qu’il est bien plus grand et féroce qu’un crocilisque ordinaire.",al={"ghostmaw","crocilisque ghostmaw","crocilisque fantôme"}},{q="Pourquoi Wheatley a-t-il cessé de déplacer ses chevaux ?",a="Wheatley craint que Ghostmaw ne s’empare de ses poneys les plus précieux. Il reste donc sur place jusqu’à ce qu’on se débarrasse de la bête.",al={"pourquoi wheatley a cessé","chevaux immobiles","wheatley a peur"}},{q="Qu’est-ce que Wheatley veut qu’on lui apporte ?",a="Wheatley demande le croc de Ghostmaw comme preuve que le crocilisque ne représente plus un danger pour les voyageurs.",al={"croc de ghostmaw","quoi apporter à wheatley","croc"}},{q="Où dois-je apporter le croc de Ghostmaw ?",a="Apportez le croc de Ghostmaw à Wheatley, au Donjon de Fort-Lointain.",al={"où se trouve wheatley","donjon de fort-lointain","emplacement du croc"}}},fp="16,167,20.269.0,16.130.0,43.106.0,39.96.0,39.53.0"}
P.entries["quest:95992"] = {n="WANTED: Ghostmaw",s="Tan'jani propose un concours pour capturer Ghostmaw, un crocilisque blanc qui rôde dans les rivières. Rapportez son croc à Rog’mar pour remporter la cagnotte.",h="Tan'jani propose un concours pour capturer Ghostmaw, un crocilisque blanc qui rôde dans les rivières.",kw={"crocilisque","croc","ghostmaw","chasseur de têtes","rivières","rog’mar","tan'jani"},sec={{t="Concours au bord de la rivière",b="Tan'jani, à Rog’mar, organise un concours pour vous. Un crocilisque blanc nommé Ghostmaw rôde dans les rivières, et même les chasseurs de têtes ne l’ont pas capturé. Rapportez Ghostmaw's Fang à Tan'jani ; le gagnant remporte la cagnotte."}},faq={{q="Qui est Ghostmaw ?",a="Ghostmaw est un crocilisque blanc qui rôde dans les rivières.",al={"ghostmaw","crocilisque blanc","crocilisque ghostmaw"}},{q="Qui veut le croc de Ghostmaw ?",a="Tan'jani, à Rog’mar, vous demande de rapporter Ghostmaw's Fang.",al={"croc tan'jani","qui veut le croc","pour qui le croc"}},{q="Que veut que je rapporte Tan'jani ?",a="Tan'jani veut Ghostmaw's Fang.",al={"croc de ghostmaw","que dois-je rapporter","croc"}},{q="Quel est l’objet du concours ?",a="Tan'jani dit que le gagnant du concours pour capturer Ghostmaw remporte la cagnotte.",al={"concours tan'jani","la cagnotte","pourquoi capturer ghostmaw"}}},fp="16,136,17.206.0,16.53.0,26.54.0,36.31.0,30.77.0"}
P.entries["quest:95998"] = {n="The Great Outdoors",s="Au feu de Sam, les voyageurs apprennent à se reposer et à tenir la distance. Ils peuvent ensuite s’adonner aux métiers et travailler en pleine nature.",h="Au feu de Sam, les voyageurs apprennent à se reposer et à tenir la distance.",kw={"feu de camp de base","repos amélioré","installation de camp","campement","homme des bois","sam","the great outdoors","métier"},ang={["class:Hunter"]="En tant que chasseur, vivre des ressources de la terre et se reposer près d’un feu à ciel ouvert vous est peut-être familier. Même les éclaireurs chevronnés peuvent profiter de leçons sur le campement.",["profession:Cooking"]="En tant que cuisinier, apprendre à monter un camp vous donne les bases pour préparer des repas en plein air."},sec={{t="Leçons au coin du feu",b="Sam accueille les voyageurs avides d’aventure qui parcourent Azeroth en quête de fortune, de danger et de renommée. La seule ambition ne peut ni réchauffer un débutant ni alléger les kilomètres. À son feu, vous apprenez quand vous reposer, comment allumer un feu et comment reprendre des forces avant de reprendre la route."},{t="Vie sauvage et métiers",b="Un feu de camp réchauffe lors des nuits froides et permet de bénéficier d’un repos amélioré. Ceux qui connaissent la nature savent que l’endurance s’acquiert en se reposant entre les voyages. Une fois ces bases apprises, vous pouvez vous consacrer aux métiers. Artisans et récolteurs peuvent apprendre à fabriquer des installations de camp adaptées à leur travail sur le terrain."}},faq={{q="Qui est Sam ?",a="Sam est un voyageur expérimenté qui connaît bien la nature et enseigne aux débutants comment y tenir bon. Il les invite à partager son feu et à apprendre des façons pratiques d’affronter la route.",al={"qui est sam","quête du feu de camp de sam","donneur de quête"}},{q="À quoi sert de s’asseoir près du feu de camp ?",a="Le repos amélioré est le regain d’énergie que procure le repos près d’un feu de camp adapté, en pleine nature. Sa chaleur et son confort aident les voyageurs épuisés à récupérer et à poursuivre leur voyage.",al={"qu’est-ce que le repos amélioré","bonus de repos amélioré","se reposer près du feu"}},{q="Pourquoi les aventuriers ont-ils besoin de compétences de survie ?",a="Les compétences de survie aident les voyageurs à tenir face aux dangers et aux longues distances au-delà des murs des villes. La vie en pleine nature leur permet de subvenir à leurs besoins sans succomber à la fatigue.",al={"pourquoi apprendre la survie en pleine nature","pourquoi survivre en pleine nature","compétences de survie"}},{q="Quel est le lien entre les métiers et le camping en pleine nature ?",a="Après avoir appris à monter un camp de base, vous pouvez demander aux maîtres de métier de vous apprendre à fabriquer des installations de camp adaptées à votre travail sur le terrain.",al={"métiers et camping","installations de camp","métiers après cette quête"}},{q="Que doit faire un aventurier après cette leçon ?",a="Après vous être reposé au feu de Sam et avoir appris les rudiments du campement, vous pouvez chercher des maîtres de métier. Un métier pratique vous permet de construire des postes de travail adaptés à votre activité sur le terrain.",al={"étapes suivantes","que faire après the great outdoors","après la quête du feu de camp"}},{q="Qui peut entreprendre The Great Outdoors ?",a="Tout voyageur qui s’aventure dans le vaste monde peut apprendre ces leçons, quels que soient ses origines ou son allégeance.",al={"tout le monde peut-il faire cette quête","qui peut entreprendre the great outdoors","cette quête est-elle générale"}}},fp="18,117,19.257.0,20.322.0,11.166.0,47.169.0,52.162.0,48.128.0,58.167.0,37.111.0"}
P.entries["quest:95999"] = {n="WANTED: Incinerator Gar'im",s="À Comté-du-Lac, le Magistrat Salomon offre une prime pour l’incinérateur Gar’im, dont les forces menacent la ville. Ce commandant orc hostile tient la Vallée des Etripeurs avec ses lanceurs d’ombre, et travaillerait avec le clan Rochenoire au Donjon de Guet-de-pierre.",h="À Comté-du-Lac, le Magistrat Salomon offre une prime pour l’incinérateur Gar’im, dont les forces menacent la...",kw={"rochenoire","prime","gar’im","incinérateur","comté-du-lac","vallée des etripeurs","lanceur d’ombre","salomon"},ang={["class:Mage"]="En tant que mage, vous affrontez Gar’im et ses lanceurs d’ombre, qui manient une forme corrompue de magie arcanique offensive et de Shadow Magic. Répliquez sans tarder avec des contresorts.",["faction:Alliance"]="En tant que combattant de l’Alliance, vous protégez les habitants vulnérables de Comté-du-Lac contre le chef d’une incursion orc et ses dangereux lanceurs d’ombre en vainquant l’incinérateur Gar’im."},sec={{t="Un brasier dans la Vallée des Etripeurs",b="Les orcs Rochenoire sortent de leurs bastions montagneux et rendent les Carmines plus dangereuses. Dans la Vallée des Etripeurs, Gar’im mène une incursion avec ses fidèles lanceurs d’ombre et sa sombre sorcellerie. La garde de Comté-du-Lac est débordée, et les armées de la couronne sont largement absentes. Le Magistrat Salomon fait donc appel à des combattants indépendants pour éliminer Gar’im, qui travaillerait avec les Rochenoire au Donjon de Guet-de-pierre."},{t="Preuve de décès",b="Gar’im est réputé pour sa magie destructrice et son autorité sur des lanceurs d’ombre. Pour toucher la récompense de la ville, les chasseurs pénètrent en territoire ennemi et le vainquent. Ils doivent rapporter son bâton brisé à la mairie de Comté-du-Lac, preuve que la menace a pris fin."}},faq={{q="Qui est l’incinérateur Gar’im ?",a="L’incinérateur Gar’im est un chef de guerre orc et un lanceur de sorts qui mène une incursion dans la Vallée des Etripeurs. Il travaillerait avec les orcs Rochenoire du Donjon de Guet-de-pierre et commande de dangereux lanceurs d’ombre.",al={"qui est gar’im","gar’im","incinérateur gar’im"}},{q="Où trouver l’incinérateur Gar’im ?",a="Gar’im campe parmi des forces orcs hostiles dans la Vallée des Etripeurs, au sud-est des Carmines.",al={"emplacement de gar’im","où se trouve gar’im","emplacement de la vallée des etripeurs"}},{q="Qui a offert une prime pour Gar’im ?",a="Le Magistrat Salomon offre cette prime au nom de Comté-du-Lac, dans l’espoir de freiner les incursions orcs qui menacent la ville assiégée.",al={"qui a offert la prime","prime salomon"}},{q="Quelle preuve faut-il fournir pour toucher la prime ?",a="Le Magistrat Salomon exige le Bâton brisé de l’incinérateur Gar’im comme preuve de la mort du lanceur de sorts avant de verser la récompense.",al={"preuve pour gar’im","objet de quête bâton brisé"}},{q="Quelle menace Gar’im et ses suivants représentent-ils ?",a="Gar’im manie une magie destructrice meurtrière et est flanqué de lanceurs d’ombre. Ensemble, ils renforcent l’emprise du clan Rochenoire sur les Carmines et menacent de submerger Comté-du-Lac si on ne les arrête pas.",al={"capacités de gar’im","lanceurs d’ombre des carmines"}},{q="Pourquoi Comté-du-Lac compte-t-il sur les primes plutôt que sur l’armée de Hurlevent ?",a="Hurlevent a largement laissé les Carmines se défendre seules, en raison des conflits politiques et du manque de troupes. Le Magistrat Salomon a dû engager des combattants volontaires pour tuer les chefs ennemis.",al={"pourquoi des primes à comté-du-lac","où est l’armée de hurlevent"}}},fp="26,235,25.404.0,15.259.0,26.193.0,38.97.0,33.128.0,43.128.0,45.190.0,68.170.0"}
P.entries["quest:96"] = {n="L'appel de l'eau",s="Vous rapportez l'Eclat d'eau à Islen Oeil-des-rivières, sur la côte des Tarides. Ce retour témoigne de votre harmonie avec les énergies réparatrices et vous vaut un Totem d'eau.",h="Vous rapportez l'Eclat d'eau à Islen Oeil-des-rivières, sur la côte des Tarides.",kw={"l'appel de l'eau","islen oeil-des-rivières","manifestation d'eau mineure","eclat d'eau","forêt des pins-argentés","les tarides","totem d'eau"},ang={["class:Shaman"]="En tant que chaman, vous recevez votre Totem d'eau et accédez aux sources réparatrices et aux fontaines purificatrices qui sont au cœur de votre rôle de guérisseur spirituel.",["faction:Horde"]="En tant que membre de la Horde, vous partagez la responsabilité des esprits de la terre. Les jeunes chamans sont appelés à purifier les terres corrompues de Kalimdor et des Royaumes de l'est."},sec={{t="Un long retour",b="Vous rapportez par-delà la mer un don de la Manifestation d'eau mineure. Pour le mériter, vous avez traversé des continents jusqu'aux rivages souillés de la Forêt des Pins-Argentés et affronté la corruption qui y sévit. L'eau donne la vie, s'adapte et guérit, mais sa nature malléable la rend vulnérable au fléau et à la magie noire.\n\nDevant la Manifestation d'eau mineure, vous avez été témoin de la volonté élémentaire pure et reçu l'Eclat d'eau. Vous retournez maintenant dans les Tarides brûlées par le soleil, où l'éclat vous rappelle que l'eau relie les coins les plus éloignés du monde."},{t="Le Totem d'eau",b="Quand vous remettez l'éclat à Islen Oeil-des-rivières, elle y voit plus qu'une preuve de votre voyage. Elle vérifie si vous avez appris l'équilibre entre préservation et renouveau. La pourriture qui se répand dans Lordaeron peut masquer de petites victoires, mais purifier une seule source compte pour les esprits. Islen accepte votre offrande et vous donne un Totem d'eau. Grâce à lui, vous pouvez canaliser dans le royaume des mortels des flots purificateurs, curatifs et régénérateurs de mana, qui vous lient à la marée."}},faq={{q="Qu'est-ce que l'Eclat d'eau ?",a="L'Eclat d'eau est un vestige élémentaire donné par la Manifestation d'eau mineure. Il montre que vous comprenez le pouvoir vital de l'eau et que vous avez combattu la corruption qui menace les courants élémentaires.",al={"eclat d'eau","éclat d'eau","qu'est-ce que l'éclat"}},{q="Où remettre l'Eclat d'eau ?",a="Apportez l'Eclat d'eau à Islen Oeil-des-rivières, dans son camp isolé sur la côte est des Tarides, au sud de Cabestan.",al={"où remettre l'éclat","à qui donner l'éclat","lieu de remise"}},{q="Que reçoit-on en achevant cette épreuve ?",a="Vous recevez un Totem d'eau, un conduit dont les chamans ont besoin pour invoquer des totems élémentaires liés à l'eau, qui servent aux soins et à la magie réparatrice.",al={"récompense de quête","récompense totem","que reçoit-on"}},{q="Pourquoi l'épreuve a-t-elle lieu dans la Forêt des Pins-Argentés ?",a="Les eaux de la Forêt des Pins-Argentés sont gravement corrompues par le fléau et la Shadow Magic. Vous y avez vu la fragilité de l'eau et défendu sa pureté naturelle contre le déclin.",al={"pourquoi la forêt des pins-argentés","pourquoi les royaumes de l'est","eaux de la forêt des pins-argentés"}},{q="Qui est Islen Oeil-des-rivières ?",a="Islen Oeil-des-rivières est une chamane taurène de la côte est des Tarides. Elle supervise les épreuves chamaniques de l'eau et apprend aux novices à communier avec les esprits fluides et à maîtriser les arts réparateurs.",al={"islen","qui est islen oeil-des-rivières"}}},fx={["352084e3"]={q="Pourquoi la Manifestation d'eau mineure vous renvoie-t-elle auprès d'Islen ?",a="La manifestation élémentaire sert de voix vivante à l'eau pure, testée et invoquée par vos rituels. En vous accordant l'Eclat d'eau, elle vous confie la vérité fondamentale de sa nature : l'eau apporte la vie, tandis que la corruption l'éteint. Elle vous renvoie auprès d'Islen Oeil-des-rivières afin que la chamane puisse confirmer votre communion avec les esprits, reconnaître votre succès face à la corruption et vous confier le totem d'eau que vous avez prouvé être digne de manier.",al={"motif de la manifestation mineure","pourquoi apporter l'éclat à islen","pourquoi la manifestation d'eau veut cela"}}},fp="13,155,19.504.0,15.455.0,27.198.0,35.113.0,44.121.0,43.166.0,23.188.0"}
P.entries["quest:960"] = {n="Onu réfléchit",s="Au Glaive du Maître, dans le sud de Sombrivage, Onu entre en transe profonde tandis que la menace grandit. L'ancien du savoir évalue l'alliance et les motivations du culte du Marteau du crépuscule et des nagas serpentins. Si vous perdez votre flasque de divination, parlez-lui pour en obtenir une autre.",h="Au Glaive du Maître, dans le sud de Sombrivage, Onu entre en transe profonde tandis que la menace grandit.",kw={"sombrivage","bosquet des anciens","le glaive du maître","méditation","onu","flasque de divination","bassin de divination","marteau du crépuscule"},ang={["class:Druid"]="En tant que druide, vous partagez un lien profond avec la nature et les anciens du savoir. Les rituels de divination reflètent la manière dont le Cercle cénarien surveille à distance les terres corrompues.",["faction:Alliance"]="En tant que voyageur de l'Alliance, protéger Sombrivage des cultistes et des envahisseurs aquatiques compte lorsque vous voyagez entre Teldrassil et Orneval.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous vénérez les anciens du savoir comme Onu, gardiens de l'équilibre de Kalimdor. Leur sagesse immémoriale vous aide à comprendre les perturbations dans les étendues sauvages de Sombrivage."},sec={{t="Un esprit en profonde contemplation",b="Au Bosquet des Anciens, Onu conserve l'histoire de Kalimdor dans sa mémoire ancestrale. Des rapports inquiétants sur de sombres fouilles au Glaive du Maître tournent son immense conscience vers l'intérieur. Il se demande ce qui attire les fanatiques du culte du Marteau du crépuscule et les nagas serpentins vers les restes pétrifiés d'un ancien colosse. Pendant votre reconnaissance, Onu reste accessible et peut remplacer une flasque de divination égarée dans la nature."},{t="Scruter les profondeurs",b="Onu recourt à la divination en harmonie avec la nature pour observer les ruines sans risquer sa présence physique. Il vous confie une flasque de divination, qui fait apparaître un bassin de divination sur le site des fouilles et lui permet de communier à distance. Le voyage vers le sud à travers Sombrivage est périlleux, entre faune hostile et patrouilles de cultistes, et des mésaventures peuvent survenir.\n\nLa transe d'Onu est une vigie attentive, pas un sommeil ininterrompu. Il vous offre volontiers une autre fiole d'eaux sacrées pour poursuivre l'enquête sur le Glaive du Maître."}},faq={{q="Pourquoi Onu médite-t-il ?",a="Onu médite sur la présence inquiétante du culte du Marteau du crépuscule et des nagas au Glaive du Maître. Il cherche à percevoir leurs motivations et à vous guider pendant votre enquête sur le site.",al={"pourquoi onu médite","transe d' onu","que fait onu"}},{q="À quoi sert cette interaction ?",a="Cette interaction est une mesure de sécurité pour les aventuriers au Glaive du Maître. Si vous perdez votre flasque de divination, parlez à Onu pour en recevoir une autre et accomplir le rituel.",al={"flasque de divination perdue","obtenir une autre flasque","quête de remplacement d' onu"}},{q="Où se trouve Onu ?",a="Onu est enraciné au Bosquet des Anciens, dans le centre-sud de Sombrivage, juste à l'écart de la route principale.",al={"emplacement d' onu","où trouver onu"}},{q="Que faire de la flasque de divination ?",a="Emportez la flasque jusqu'au Glaive du Maître et utilisez-la pour créer un bassin de divination. Onu pourra alors communiquer avec vous par son intermédiaire.",al={"comment utiliser la flasque de divination","bassin de divination à sombrivage","utilité de la flasque de divination"}},{q="Qu'est-ce que le Glaive du Maître ?",a="Le Glaive du Maître est un ancien site de fouilles dans le sud de Sombrivage. Le crâne pétrifié d'une entité oubliée, colossal, y est transpercé par une lame gigantesque. Des cultistes et des nagas s'y sont rassemblés pour des raisons inconnues et malveillantes.",al={"qu'est-ce que le glaive du maître","monument dans le sud de sombrivage"}},{q="Les joueurs de la Horde peuvent-ils interagir avec Onu ici ?",a="Onu est exclusivement allié aux Elfes de la nuit et à l'Alliance. Les aventuriers de la Horde près du Bosquet des Anciens le trouveront, lui et ses protecteurs, hostiles ou peu coopératifs.",al={"onu est-il réservé à l'alliance","onu médite horde"}}},fx={["72a6a09e"]={q="Pourquoi Onu a-t-il besoin de votre aide plutôt que d'enquêter lui-même ?",a="Onu reste dans le Bosquet des Anciens pour méditer sur le Marteau du crépuscule et les nagas. Il compte sur les voyageurs pour enquêter sur le Glaive du Maître et le contacter via un bassin de scrying.",al={"pourquoi m'envoyer","pourquoi onu n'y va pas","pourquoi onu a besoin de vous"}}},fp="17,243,28.421.0,18.499.0,22.187.0,40.184.0,21.97.0,39.127.0,28.238.0,41.169.0"}
P.entries["quest:96010"] = {n="Fragments of the Pylons",s="Mordent Evenshade vous demande de récupérer des fragments de pylône dans les villages Magram et Gelkis, à Shen’dralas. Ces morceaux sont nécessaires à ses travaux sur les pylônes endommagés.",h="Mordent Evenshade vous demande de récupérer des fragments de pylône dans les villages Magram et Gelkis, à...",kw={"centaure","cristaux","fragments des pylônes","gelkis","magram","mana","mordent evenshade","pylône","éclats","shen’dralas"},sec={{t="Pylônes brisés",b="Mordent Evenshade pense que les saccages des centaures ont endommagé les deux pylônes de Shen’dralas. Il soupçonne les Magram et les Gelkis d’avoir rapporté les éclats dispersés dans leurs villages comme trophées. Vous devez récupérer les fragments qu’ils y gardent et les lui rapporter."},{t="Les cristaux",b="Mordent reçoit les fragments et dit que les cristaux sont plus brisés qu’il ne le pensait. Il va les garder pour le moment. Sa prochaine étape consiste à rassembler du mana malléable, capable de lier les morceaux et de laisser la puissance des lignes telluriques les traverser."}},faq={{q="Qui demande les fragments des pylônes ?",a="Mordent Evenshade vous demande de récupérer des éclats et des fragments dans les villages Magram et Gelkis, puis de les lui rapporter.",al={"qui est mordent","mordent evenshade","qui veut les cristaux"}},{q="Où se trouvent les fragments des pylônes ?",a="Mordent pense que les Magram et les Gelkis ont emporté les fragments des pylônes dans leurs villages de Shen’dralas.",al={"où trouver les éclats","emplacement des morceaux de pylône","trouver les fragments"}},{q="Pourquoi les pylônes sont-ils endommagés ?",a="Mordent pense que les activités imprudentes des centaures ont endommagé les deux pylônes.",al={"qu’est-ce qui a brisé les pylônes","dégâts causés par les centaures","pourquoi le pylône est brisé"}},{q="Que compte faire Mordent des fragments ?",a="Mordent compte lier les morceaux brisés avec du mana malléable et utiliser ce mana comme conduit pour les lignes telluriques.",al={"à quoi servent les cristaux","comment réparer les pylônes","plan de mordent"}}},fp="23,163,13.254.0,12.221.1,33.118.0,30.97.0,27.63.0,48.106.0"}
P.entries["quest:96018"] = {n="Powering the Pylons",s="Mordent Evenshade vous demande de réparer les pylônes endommagés de Shen’dralas. Des particules de mana y flottent, et il faut les recueillir pour les rendre aux pylônes.",h="Mordent Evenshade vous demande de réparer les pylônes endommagés de Shen’dralas.",kw={"ancient mana crystals","mana flottant","mana sieve","mordent evenshade","pylônes","shen’dralas"},sec={{t="Rassembler le mana",b="Dans le temple de Shen’dralas, vous cherchez le Mana Sieve, un artefact que ses habitants pourraient vous reprocher d’emprunter. Mordent Evenshade a besoin que vous rassembliez le mana dispersé sous forme semi-cristallisée. Avec suffisamment d’Ancient Mana Crystals, vous pourrez alimenter les pylônes endommagés et lui rapporter le fruit du travail du tamis."},{t="Les pylônes",b="Mordent Evenshade constate que les pylônes sont réparés et désigne le ciel. Il remarque votre réaction peu enthousiaste et se tourne de nouveau vers vous."}},faq={{q="Pourquoi Mordent a-t-il besoin de mana ?",a="Mordent a besoin que vous rassembliez du mana sous forme d’Ancient Mana Crystals pour alimenter les pylônes endommagés de Shen’dralas.",al={"pourquoi le mana","mana de mordent"}},{q="Où trouver le Mana Sieve ?",a="Le Mana Sieve se trouve dans le temple de Shen’dralas.",al={"emplacement du mana sieve","où trouver le tamis"}},{q="Que se passe-t-il avec le mana à Shen’dralas ?",a="Des étincelles de mana flottent autour de Shen’dralas, probablement à cause des dégâts subis par les pylônes.",al={"mana flottant","orbes de mana"}},{q="À quoi sert le Mana Sieve ?",a="Vous utilisez le Mana Sieve pour recueillir le mana flottant sous forme d’Ancient Mana Crystals.",al={"utilité du tamis","rassembler le mana"}},{q="Qui demande à ce que les pylônes soient alimentés ?",a="Mordent Evenshade vous demande de rassembler du mana et d’alimenter les pylônes.",al={"qui est mordent","mordent evenshade"}}},fp="19,159,14.294.0,10.129.1,27.98.0,31.51.0,45.105.0,28.72.0,45.65.0"}
P.entries["quest:96031"] = {n="Camping 101: Leatherworking",s="Dans un camp en pleine nature, les travailleurs du cuir utilisent des peaux tannées pour se fabriquer un abri. Un bon campement comprend une tente dressée et un feu, dont les maîtres de cuisine enseignent l'allumage.",h="Dans un camp en pleine nature, les travailleurs du cuir utilisent des peaux tannées pour se fabriquer un abri.",kw={"tente de campement","feu de camp","camping","cuisine","travail du cuir","abri","tente","nature sauvage"},ang={["profession:Cooking"]="Un feu de camp est le cœur d'un campement en pleine nature. Les bases de la cuisine vous apprennent à allumer un feu et à entretenir un camp dans la nature sauvage."},sec={{t="Dresser un abri en pleine nature",b="Pour les artisans qui travaillent les peaux et le cuir, se fabriquer un abri est une étape essentielle. Une solide tente en cuir protège les voyageurs des intempéries, du vent et du froid nocturne en terrain découvert. Les citadins voient d'un mauvais œil les tentes dressées dans les rues bondées ou sur les places du marché. Vous devez donc franchir les portes de la ville et gagner la nature sauvage pour établir votre camp."},{t="La chaleur d'un feu de camp",b="Une tente dressée ne constitue que la moitié d'un campement. Un feu digne de ce nom repousse l'obscurité et les vents froids, et vous offre un foyer dans les contrées dangereuses. Comme la cuisine sur le terrain commence par allumer et entretenir un feu, demandez conseil aux maîtres cuisiniers et aux maîtres des métiers de cuisine. Ils vous apprendront à allumer un feu de camp avant que vous établissiez votre campement."}},faq={{q="Où pouvez-vous dresser une tente de campement ?",a="Les citadins voient d'un mauvais œil les tentes dressées dans les rues ou sur les places de la ville. Emportez donc votre tente au-delà des portes de la ville, jusque dans la nature sauvage.",al={"usage d'une tente de campement","où dresser une tente","peut-on camper en ville"}},{q="Que faut-il en plus d'une tente pour établir un camp ?",a="Une tente ne suffit pas à former un campement. Il vous faut aussi un feu de camp allumé à côté.",al={"faut-il un feu pour camper","conditions pour camper","comment camper"}},{q="Où les aventuriers apprennent-ils à allumer un feu de camp ?",a="Les maîtres cuisiniers et les maîtres des métiers de cuisine vous apprennent à allumer un feu de camp pour préparer vos repas. Adressez-vous à un maître de cuisine pour en apprendre les rudiments.",al={"apprendre à allumer un feu de camp","qui apprend à allumer un feu de camp","feu de cuisine"}},{q="Quel est le lien entre le travail du cuir et la confection des tentes de campement ?",a="Les travailleurs du cuir utilisent des peaux et des fourrures tannées, assemblées par de solides coutures, pour fabriquer des toiles de tente capables de résister aux rigueurs de la nature sauvage. Cet artisanat procure aux voyageurs un abri fiable fait de peaux animales.",al={"camping 101 travail du cuir","tente de campement en cuir","confection de tente et travail du cuir"}},{q="Pourquoi les aventuriers établissent-ils des camps dans la nature sauvage ?",a="Les camps en pleine nature offrent aux voyageurs un refuge sûr où se reposer et reprendre des forces, loin des avant-postes habités, des auberges et des villages. Un abri portatif et un feu chaleureux aident à affronter les éléments et les terrains périlleux.",al={"pourquoi camper en pleine nature","but du camping","camp de survie en pleine nature"}},{q="Pourquoi les citadins s'opposent-ils à l'installation de tentes en ville ?",a="Les citadins s'y opposent, car les tentes dressées dans les rues encombrent les voies publiques et provoquent des nuisances. Les villes disposent d'auberges et de logements privés pour les voyageurs. Les habitants s'attendent donc à ce que les campements restent dans la nature sauvage.",al={"règles du camping en ville","pas de tente en ville","pourquoi ne puis-je pas dresser une tente en ville"}}},fp="27,193,28.361.0,24.324.0,32.125.0,53.76.0,47.139.0,54.205.0,53.213.0,56.202.0"}
P.entries["quest:96044"] = {n="Camping 101: Blacksmithing",s="Les forgerons qui partent dans la nature sont envoyés à Kharanos pour apprendre auprès de Tognus Flintfire. Il leur enseigne à fabriquer une meule à aiguiser portable pour garder leurs armes affûtées au camp.",h="Les forgerons qui partent dans la nature sont envoyés à Kharanos pour apprendre auprès de Tognus Flintfire.",kw={"forge","lames","camp","campement 101","dun morogh","kharanos","meule à aiguiser","tognus flintfire","armes"},ang={["class:Rogue"]="Une dague bien affûtée est essentielle à votre métier ; une meule à aiguiser au camp est donc la bienvenue entre deux contrats sur le terrain.",["class:Warrior"]="Des armes bien affûtées comptent au combat, et une meule à aiguiser au camp vous aide à garder le tranchant lors d'une expédition.",["profession:Blacksmithing"]="Vous pouvez apprendre à fabriquer des outils de terrain comme la meule à aiguiser, pour exercer votre métier au-delà des forges des villes et aider vos alliés dans la nature.",["race:Dwarf"]="En tant que nain, vous trouverez Kharanos dans les contreforts enneigés de Dun Morogh. Ses forgerons gardent l'acier froid bien affûté pour la route."},sec={{t="Entretenir son équipement sur la route",b="Vous êtes envoyé à Kharanos pour apprendre comment un forgeron peut être utile loin d'une forge de ville. Là-bas, des mains expertes transforment le métal brut en outils de campement. Une lame bien affûtée est prête pour la longue route."},{t="Le maître de Kharanos",b="À Kharanos, Tognus Flintfire apprend aux forgerons talentueux à fabriquer une meule à aiguiser. Installez-en une près de votre campement : guerriers et voleurs pourront éliminer les entailles de leurs armes et en affûter le tranchant avant la prochaine marche."}},faq={{q="Qui est Tognus Flintfire ?",a="Tognus Flintfire enseigne la forge à Kharanos, dans Dun Morogh. Il forme les forgerons qui ont fait leurs preuves dans leur métier et leur apprend à fabriquer de l'équipement pour les campements.",al={"qui est tognus flintfire","où se trouve tognus","emplacement de tognus flintfire"}},{q="Qu'est-ce qu'une meule à aiguiser ?",a="Une meule à aiguiser est un outil portable fabriqué par les forgerons. Au camp, elle permet aux guerriers, aux voleurs et aux autres porteurs d'armes d'affûter leurs lames sur le terrain.",al={"utilité de la meule à aiguiser","meule à aiguiser au camp","but de la meule à aiguiser"}},{q="Pourquoi les guerriers et les voleurs ont-ils besoin d'une meule à aiguiser ?",a="Les guerriers et les voleurs comptent sur des armes affûtées au combat. Une meule à aiguiser leur permet d'entretenir leurs lames, leurs haches et leurs dagues lorsqu'ils voyagent loin des forges de ville.",al={"qui a besoin d'une meule à aiguiser","meule à aiguiser pour guerriers","meule à aiguiser pour voleurs"}},{q="Où se trouve Kharanos ?",a="Kharanos se trouve au sud-ouest de Forgefer, dans les sommets enneigés de Dun Morogh. Voyageurs, mineurs et artisans font halte dans cette colonie en traversant les cols de montagne.",al={"où se trouve kharanos","emplacement de kharanos","trouver kharanos"}},{q="Que faut-il pour apprendre à fabriquer cet objet de campement ?",a="Montrez que vous maîtrisez les bases du travail à l'enclume, et Tognus Flintfire vous apprendra à fabriquer de l'équipement de campement. Vous pourrez ensuite apprendre à forger la meule portable.",al={"condition pour apprendre la forge de campement","quand apprendre à fabriquer une meule à aiguiser","formation de forge pour le campement"}},{q="Pourquoi les forgerons fabriquent-ils des objets de campement ?",a="Les forgerons fabriquent des outils de campement pour aider les groupes d'aventuriers loin des villes habitées. Une meule à aiguiser portable permet à vos compagnons d'entretenir leurs armes à la belle étoile, sans retourner à la forge d'une cité.",al={"pourquoi fabriquer des objets de campement","objets de campement en forge","utilité de la forge dans la nature"}}},fp="26,170,35.181.0,22.211.0,24.162.0,27.161.0,59.157.0,18.177.0,44.137.0,39.202.0"}
P.entries["quest:96045"] = {n="Camping 101: Alchemy",s="À Forgefer, Vosur Brakthel montre aux alchimistes comment se préparer à la route. Avec un Puits de mana, ils peuvent offrir aux lanceurs de sorts et aux soigneurs un lieu où se reposer pendant le voyage.",h="À Forgefer, Vosur Brakthel montre aux alchimistes comment se préparer à la route.",kw={"alchimie","feu de camp","camping","camping 101: alchemy","forgefer","puits de mana","vosur brakthel"},ang={["faction:Alliance"]="À Forgefer, les alchimistes peuvent demander conseil à Vosur Brakthel pour préparer des concoctions fortifiantes en vue de leurs voyages.",["profession:Cooking"]="Un campement a besoin d’un feu de camp, un savoir-faire pratique enseigné par les maîtres cuisiniers des différents royaumes."},sec={{t="Préparer la route",b="Vosur Brakthel forme les alchimistes à Forgefer pour qu’ils exercent leur art au-delà de la ville. Préparer des fioles dans un laboratoire tranquille ne représente qu’une partie du travail. Dans les contrées sauvages d’Azeroth, les alchimistes peuvent mettre leur savoir à profit pour créer un Puits de mana dans un campement et aider leurs compagnons à poursuivre leur voyage."},{t="Campements en pleine nature",b="Un Puits de mana peut revigorer les soigneurs et les lanceurs de sorts, mais il a sa place dans un campement en pleine nature, pas dans une rue de Forgefer. Les citadins voient d’un mauvais œil les tentes dressées dans leurs murs. Un véritable campement a aussi besoin d’un feu, alors demandez conseil à un maître cuisinier avant de partir dans la nature."}},faq={{q="Qui est Vosur Brakthel ?",a="Vosur Brakthel est un maître en alchimie à Forgefer. Il enseigne aux alchimistes à mettre leur art à profit pour créer un Puits de mana destiné à leurs compagnons sur le terrain.",al={"qui enseigne les bases du camping en alchimie","rôle de vosur brakthel","qui est vosur brakthel"}},{q="Qu’est-ce qu’un Puits de mana ?",a="Un Puits de mana est une installation alchimique pour un campement en pleine nature. Il aide les lanceurs de sorts et les soigneurs à récupérer pendant leurs voyages.",al={"à quoi sert un puits de mana","utilité du puits de mana","pourquoi créer un puits de mana"}},{q="Peut-on installer un campement à Forgefer ?",a="Non. Les citadins voient d’un mauvais œil les campements dressés dans les rues de Forgefer, alors emmenez votre Puits de mana au-delà de la ville, dans la nature.",al={"peut-on camper à forgefer","camper en ville","où placer le puits de mana"}},{q="De quoi d’autre a-t-on besoin pour installer un campement ?",a="Un campement a aussi besoin d’un feu de camp. Si vous ne savez pas en allumer un, demandez conseil à un maître cuisinier avant de partir.",al={"nécessité d’un feu de camp","faut-il connaître la cuisine pour camper","comment installer un campement"}},{q="Quand un alchimiste peut-il apprendre à créer un Puits de mana ?",a="Vosur Brakthel enseigne aux alchimistes qui ont choisi cette profession et acquis un peu d’expérience. Grâce à cette expérience, ils peuvent apprendre à créer un Puits de mana.",al={"quand apprendre à créer un puits de mana","conditions pour créer un puits de mana","conditions pour camper"}},{q="Qui profite le plus d’un Puits de mana au campement ?",a="Les lanceurs de sorts et les soigneurs profitent le plus d’un Puits de mana. Celui-ci les aide à renouveler leur mana lorsqu’ils voyagent loin des tavernes et des pierres de foyer.",al={"qui profite du puits de mana","classes pour le puits de mana","qui utilise le puits de mana"}}},fp="20,167,20.280.0,20.267.0,22.140.0,20.117.0,39.118.0,37.108.0,48.152.0,43.146.0"}
P.entries["quest:96046"] = {n="Camping 101: Mining",s="Au-delà des routes gardées, les mineurs apprennent à façonner une pierre d’aimant pour un campement en pleine nature. Ce travail associe la connaissance de la pierre à l’art du feu, nécessaire pour vivre au grand air.",h="Au-delà des routes gardées, les mineurs apprennent à façonner une pierre d’aimant pour un campement en pleine...",kw={"feu de camp","camping","camping 101: mining","campement","cuisine","pierre d'aimant","minage","nature sauvage"},ang={["profession:Cooking"]="En tant que cuisinier, vous apprenez auprès des maîtres de cuisine l’art du feu nécessaire à un campement.",["profession:Mining"]="En tant que mineur, vous apprenez à façonner la terre et le minerai pour en faire une pierre d’aimant qui ancre un campement en pleine nature."},sec={{t="Techniques de terrain pour mineurs",b="Au-delà des routes gardées, le mineur doit compter sur son savoir-faire de plein air. La connaissance des minéraux vous permet de façonner une pierre d’aimant, qui ancre un campement en pleine nature."},{t="Règles de la nature sauvage",b="Un campement doit se trouver au-delà des limites de la ville, où les voyageurs peuvent dresser leurs abris sans gêner les habitants. Choisissez un endroit en pleine nature. Un camp a aussi besoin d’un feu pour chasser le froid de la nuit. Apprendre à en allumer un fait partie du même savoir-faire de plein air que le travail de la pierre."}},faq={{q="À quoi sert une pierre d'aimant ?",a="Une pierre d’aimant ancre un campement en pleine nature.",al={"utilité de la pierre d'aimant","à quoi sert la pierre d'aimant","pourquoi fabriquer une pierre d'aimant"}},{q="Puis-je installer un campement dans une ville ou une cité ?",a="Les habitants et les autorités locales voient d’un mauvais œil les tentes sur les places publiques et dans les rues. Installez votre camp au-delà des limites de la ville.",al={"peut-on camper en ville","camper en ville","camper dans une colonie"}},{q="Qu'est-ce qui est requis avant d'installer un campement ?",a="Un camp a besoin d’un feu bien chaud à proximité.",al={"faut-il un feu de camp","comment monter un campement","conditions requises pour camper"}},{q="Où puis-je apprendre à faire un feu de camp ?",a="Les instructeurs de cuisine et les chefs d’Azeroth enseignent les rudiments nécessaires pour allumer un feu de cuisson.",al={"où apprendre le feu de camp","qui enseigne le feu de camp","maître de feu de camp"}},{q="Quel est le lien entre le minage et la fabrication d'une pierre d'aimant ?",a="Le minage vous apprend à travailler les minéraux et la pierre nécessaires pour façonner une pierre d’aimant.",al={"pourquoi les mineurs campent","lien entre minage et pierre d'aimant","artisanat de pierre d'aimant"}},{q="Où devrais-je aller pour tester mon nouveau campement ?",a="Franchissez les portes de la ville et gagnez la pleine nature, où vous trouverez de la place pour camper à l’écart des habitants.",al={"où tester le campement","tester la pierre d'aimant","camper en plein air"}}},fp="19,163,21.153.0,17.270.0,29.49.0,40.120.0,42.40.0,41.98.0,48.77.0,38.103.0"}
P.entries["quest:96047"] = {n="Camping 101: First Aid",s="À Kharanos, Thamner Pol vous apprend à préparer des Trousses de premiers soins pour les campements de Dun Morogh. Ces fournitures aident les voyageurs à survivre sur le terrain.",h="À Kharanos, Thamner Pol vous apprend à préparer des Trousses de premiers soins pour les campements de Dun...",kw={"bandages","introduction au camping","dun morogh","premiers soins","trousse de premiers soins","kharanos","survie","thamner pol"},ang={["faction:Alliance"]="En tant que recrue de l'Alliance en formation au cœur glacé de Khaz Modan, vous apprenez que l'autonomie et la médecine de terrain comptent pour les groupes militaires et les équipes d'exploration.",["race:Dwarf"]="En tant que nain, vous comptez sur un équipement robuste et pratique pour patrouiller dans les hauts cols enneigés de Dun Morogh. Une Trousse de premiers soins est utile dans vos provisions.",["race:Gnome"]="En tant que réfugié ou voyageur gnome à Kharanos, vous pouvez compter sur la médecine de terrain pour survivre loin des salles perdues de Gnomeregan."},sec={{t="Soigner les blessures dans la nature",b="Vous pouvez développer vos bases en bandage en apprenant à préparer des fournitures pour un lieu de repos. Thamner Pol vous montre comment transformer des fournitures médicales brutes en trousses complètes, prêtes à servir au camp lorsque des voyageurs ont besoin de soins loin de tout abri."},{t="Les leçons de Kharanos",b="Thamner Pol vous enseigne des méthodes pratiques pour équiper les sites d'expédition en fournitures d'urgence. Une bonne trousse de terrain permet à un groupe de panser ses blessures et de reprendre des forces ensemble près du foyer avant de repartir dans le froid."}},faq={{q="À quoi sert cette tâche ?",a="Les soigneurs fraîchement formés se rendent auprès de Thamner Pol, à Kharanos, pour apprendre à confectionner des Trousses de premiers soins destinées aux campements d'aventuriers.",al={"pourquoi apprendre les premiers soins en camping","à quoi sert cette quête","objectif d'introduction au camping"}},{q="Qui est Thamner Pol ?",a="Thamner Pol forme les habitants de Kharanos, à Dun Morogh, à fabriquer du matériel pour les campements en pleine nature.",al={"qui est thamner pol","où trouver thamner pol","où est thamner pol"}},{q="Où cette formation a-t-elle lieu ?",a="La formation a lieu à Kharanos, le principal établissement du centre de Dun Morogh, au sud de Forgefer.",al={"où aller","lieu de l'introduction au camping","premiers soins à kharanos"}},{q="Pourquoi une trousse de premiers soins est-elle importante au camp ?",a="Une Trousse de premiers soins permet aux voyageurs blessés de panser leurs blessures et de récupérer en sécurité entre deux batailles.",al={"à quoi sert une trousse de premiers soins","pourquoi fabriquer une trousse de premiers soins","utilité des premiers soins au camp"}},{q="Faut-il avoir suivi une formation médicale avant de solliciter Thamner Pol ?",a="Oui. Les aventuriers doivent connaître les bases des premiers soins et avoir un peu de pratique avant que Thamner Pol leur enseigne des recettes avancées pour le camping.",al={"conditions pour l'introduction au camping","compétence en premiers soins requise","faut-il d'abord connaître les premiers soins"}},{q="Cette activité est-elle ouverte à tous les aventuriers ?",a="Tout aventurier peut apprendre les premiers soins, quelle que soit sa vocation. C'est une compétence utile aux voyageurs de Dun Morogh.",al={"tout le monde peut-il le faire","conditions de classe","qui peut apprendre les premiers soins au camp"}}},fp="22,147,26.230.0,23.212.0,33.112.0,19.85.0,36.100.0,38.110.0,62.130.0,39.113.0"}
P.entries["quest:96050"] = {n="Camping 101: Fishing",s="Préparez-vous à pêcher en pleine nature avec un Bocal à poisson et un feu de camp. Apprenez où vous installer et comment vous reposer confortablement.",h="Préparez-vous à pêcher en pleine nature avec un Bocal à poisson et un feu de camp.",kw={"campement","feu de camp","camping","cuisine","bocal à poisson","pêche","nature sauvage"},ang={["profession:Cooking"]="Apprenez les bases de la cuisine avant de monter votre campement. Les maîtres cuisiniers apprennent aux voyageurs à allumer le feu nécessaire à tout campement."},sec={{t="Savoir-vivre en pleine nature",b="Voyager en Azeroth exige quelques connaissances sur la nature sauvage. Pour vous reposer, installez votre tente et votre équipement hors des limites des villes. Les habitants et les gardes n’apprécient pas que les voyageurs dispersent leurs affaires dans les agglomérations. Emportez plutôt vos provisions dans les étendues sauvages."},{t="Le confort du campement",b="Un bon campement a besoin de quelques commodités. Commencez par allumer un feu de camp ; un maître cuisinier peut vous apprendre comment faire. Une fois le feu prêt, installez un Bocal à poisson artisanal. Votre halte sera alors digne d’un pêcheur."}},faq={{q="Qu’apprenez-vous avec Camping 101: Fishing ?",a="Vous apprenez à fabriquer un Bocal à poisson et à préparer un lieu de repos en pleine nature pour pêcher. Installez-vous loin des agglomérations.",al={"que vous apprend cette quête","fabriquer un bocal à poisson","récompense camping pêche"}},{q="Où pouvez-vous installer un campement ?",a="Installez-vous dans la nature, hors des limites des villes. Les habitants s’opposent à ce que les voyageurs dispersent leur équipement dans les rues publiques.",al={"où installer son campement","peut-on camper en ville","règles sur les lieux de camping"}},{q="De quoi avez-vous besoin avant de monter un campement ?",a="Prévoyez un feu de camp pour vous réchauffer. Un campement n’est complet qu’avec un feu.",al={"comment monter un campement","faut-il un feu de camp","conditions pour camper"}},{q="Comment apprendre à allumer un feu de camp ?",a="Les maîtres cuisiniers vous apprennent à allumer un feu de camp. Si vous ne connaissez pas encore les bases de la cuisine, demandez conseil à un cuisinier.",al={"comment allumer un feu de camp","où apprendre à allumer un feu de camp","qui apprend à allumer un feu"}},{q="À quoi sert le Bocal à poisson ?",a="Le Bocal à poisson décore un campement en plein air et convient à un pêcheur qui se repose près de l’eau.",al={"à quoi sert le bocal à poisson","utilité du bocal à poisson au campement","histoire du bocal à poisson"}},{q="Pourquoi les aventuriers reçoivent-ils des leçons de camping ?",a="Les mentors de la nature sauvage enseignent des compétences pratiques, comme allumer un feu et respecter les limites des agglomérations avant de partir dans la nature.",al={"qui propose camping 101: fishing","pourquoi des leçons de camping","guide de survie en camping"}}},fp="20,140,20.280.0,20.210.0,44.111.0,28.126.0,40.70.0,37.126.0,37.85.0,46.142.0"}
P.entries["quest:96055"] = {n="Camping 101: Herbalism",s="À Forgefer, les herboristes peuvent apprendre à fabriquer des Bougies d’encens pour la vie au camp. Reyna Stonebranch enseigne cet art aux cueilleurs prêts à tirer parti des plantes sauvages.",h="À Forgefer, les herboristes peuvent apprendre à fabriquer des Bougies d’encens pour la vie au camp.",kw={"camp","camping 101","herboristerie","herbes","bougie d’encens","forgefer","reyna stonebranch"},ang={["faction:Alliance"]="En tant qu’herboriste de l’Alliance, vous pouvez demander à Reyna Stonebranch de vous enseigner les techniques de survie à Forgefer.",["profession:Herbalism"]="En tant qu’herboriste, vous pouvez fabriquer des Bougies d’encens à partir de plantes sauvages cueillies pour aider les lanceurs de sorts au camp.",["race:Dwarf"]="En tant que Nain, vous pouvez trouver Reyna Stonebranch, maîtresse des herboristes, à Forgefer. Elle y enseigne la fabrication des Bougies d’encens."},sec={{t="Botanique de terrain pratique",b="La cueillette de plantes sauvages peut être utile au camp comme à un groupe en voyage. Avec de l’expérience, les herboristes transforment leur récolte en outils précieux pour la vie en plein air."},{t="Arômes pour le foyer",b="À Forgefer, les herboristes expérimentés peuvent demander conseil à Reyna Stonebranch. Après avoir fait leurs preuves, elle leur apprend à fabriquer une Bougie d’encens. Son arôme apaisant remonte le moral au camp et calme les lanceurs de sorts et les soigneurs lors de longues expéditions."}},faq={{q="Qu'est-ce que Camping 101: Herbalism ?",a="Les herboristes apprennent à tirer parti des plantes sauvages au camp. Reyna Stonebranch enseigne cet art à Forgefer.",al={"qu'est-ce que camping 101: herbalism","quête de camping d'herboristerie","guide de camping pour l'herboristerie"}},{q="Qui est Reyna Stonebranch ?",a="À Forgefer, Reyna Stonebranch apprend aux herboristes expérimentés à fabriquer des Bougies d’encens pour le camp.",al={"qui enseigne la bougie d’encens","où se trouve reyna stonebranch","emplacement de reyna stonebranch"}},{q="Que fait une Bougie d’encens ?",a="Une Bougie d’encens embaume le camp d’un arôme apaisant et remonte le moral des voyageurs.",al={"à quoi sert la bougie d’encens","bougie d’encens camping","utilité de la bougie d’encens"}},{q="Pourquoi les Bougies d’encens sont-elles utiles aux lanceurs de sorts ?",a="Son arôme apaisant aide les lanceurs de sorts et les soigneurs à trouver le calme pendant les longues expéditions.",al={"à qui profite la bougie d’encens","la bougie d’encens est-elle pour les lanceurs de sorts"}},{q="Où les herboristes doivent-ils se rendre pour cette formation ?",a="Après avoir fait leurs preuves dans la cueillette de plantes, les herboristes se rendent à Forgefer pour rencontrer Reyna Stonebranch.",al={"où aller pour camping herbalism","quelle ville pour camping 101: herbalism"}},{q="Que faut-il avant de pouvoir apprendre à fabriquer la bougie ?",a="Les herboristes doivent faire leurs preuves dans la cueillette de plantes avant que Reyna Stonebranch leur apprenne à fabriquer des Bougies d’encens.",al={"quand peut-on apprendre la bougie d’encens","prérequis de camping en herboristerie"}}},fp="22,167,22.148.0,24.263.0,31.111.0,25.98.0,31.85.0,47.94.0,50.102.0,53.115.0"}
P.entries["quest:96056"] = {n="Camping 101: Skinning",s="À Forgefer, les dépeceurs chevronnés apprennent à fabriquer une Chaise du camp avec des peaux de bêtes. Balthus Stoneflayer leur enseigne ce savoir-faire après qu’ils ont prouvé leur compétence.",h="À Forgefer, les dépeceurs chevronnés apprennent à fabriquer une Chaise du camp avec des peaux de bêtes.",kw={"balthus stoneflayer","chaise du camp","camping","camping 101: skinning","peaux","forgefer","dépeçage"},ang={["class:Hunter"]="En tant que chasseur, vous pouvez dépecer vos proies dans la nature et fabriquer une Chaise du camp pour vous reposer entre de longues traques.",["faction:Alliance"]="Pour apprendre à fabriquer une Chaise du camp, votre chemin mène à Forgefer, la cité naine des montagnes et capitale de l’Alliance.",["race:Dwarf"]="En tant que nain, vous pouvez trouver Balthus Stoneflayer à Forgefer et apprendre comment les dépeceurs chevronnés transforment des peaux pour améliorer le confort du camp."},sec={{t="Récolter les ressources de la nature",b="Dépecer les bêtes abattues fournit du cuir aux armuriers et aux artisans. Les peaux de félins, d’ours et d’autres bêtes servent aussi sur le terrain. On vous envoie transformer ces matériaux en quelque chose d’utile au camp au lieu de les vendre."},{t="L'artisan de Forgefer",b="Balthus Stoneflayer enseigne aux dépeceurs de Forgefer comment fabriquer une Chaise du camp avec des peaux préparées. Vous devez d’abord lui montrer que vous savez dépecer les bêtes. Alors seulement, il vous transmettra ses méthodes de fabrication."},{t="Repos et préparation",b="Une Chaise du camp vous permet de vous asseoir près du feu et de vous détendre au cours de vos voyages. Reposez-vous là, et vous pourrez affronter le prochain danger avec les sens aiguisés et vos forces retrouvées."}},faq={{q="Qu'est-ce que Camping 101: Skinning ?",a="Les dépeceurs chevronnés se rendent à Forgefer pour apprendre à fabriquer une Chaise du camp avec des peaux de bêtes.",al={"qu'est-ce que camping 101: skinning","but de la quête","quête camping 101: skinning"}},{q="Qui vous apprend à fabriquer l'objet de campement ?",a="Balthus Stoneflayer vous apprend à fabriquer une Chaise du camp à Forgefer. Montrez-lui d’abord que vous savez dépecer les bêtes.",al={"à qui parler","qui enseigne la chaise du camp","qui est balthus stoneflayer"}},{q="Où devez-vous vous rendre pour accomplir cette quête ?",a="Rendez-vous à Forgefer, la capitale naine située dans les sommets enneigés de Dun Morogh. Balthus Stoneflayer y enseigne aux dépeceurs qui prouvent leur compétence.",al={"où aller","emplacement de balthus","maître de forgefer"}},{q="Quel objet les dépeceurs apprennent-ils à fabriquer pour leur campement ?",a="Vous apprenez à fabriquer une Chaise du camp avec des peaux de bêtes, pour vous reposer sur le terrain entre deux dangers.",al={"que fabrique-t-on","utilité de la chaise du camp","artisanat de camp de dépeçage"}},{q="Pourquoi la fabrication d'une chaise de camp est-elle utile pour un aventurier ?",a="Une Chaise du camp vous permet de vous reposer lors de longues expéditions en pleine nature et de retrouver votre concentration avant que le danger vous trouve.",al={"pourquoi fabriquer une chaise","à quoi sert la chaise du camp","avantage de la chaise du camp"}},{q="Quelle compétence est requise avant que Balthus n'accepte de vous enseigner ?",a="Balthus Stoneflayer vous enseigne son savoir-faire après que vous avez prouvé votre compétence à dépecer les bêtes.",al={"prérequis","quand peut-on apprendre","compétence requise"}}},fp="21,144,20.234.0,24.194.0,18.173.0,30.85.0,42.103.0,47.136.0,52.106.0,54.111.0,59.78.0"}
P.entries["quest:96057"] = {n="Camping 101: Tailoring",s="Un couturier peut apprendre auprès d’Uthrar Threx à Forgefer à confectionner une Rallying Banner pour un camp. Cette bannière est destinée à soutenir le moral, et un feu de camp est nécessaire pour établir un camp.",h="Un couturier peut apprendre auprès d’Uthrar Threx à Forgefer à confectionner une Rallying Banner pour un camp.",kw={"camp","feu de camp","bases du camping","forgefer","moral","rallying banner","couture","uthrar threx"},ang={["profession:Cooking"]="Un cuisinier peut vous apprendre à allumer le feu de camp nécessaire avant d’installer votre camp.",["profession:Tailoring"]="En tant que couturier, vous pouvez apprendre à confectionner une Rallying Banner pour votre camp une fois votre maîtrise du métier démontrée."},sec={{t="Une bannière pour le camp",b="Un maître à Forgefer peut vous montrer comment confectionner une bannière pour votre camp une fois vos compétences en couture démontrées. Cette bannière s’appelle une Rallying Banner. Elle peut vous aider à garder votre énergie, et il vous faudra un feu de camp avant d’installer votre camp."}},faq={{q="Qui enseigne la couture pour le camping ?",a="Uthrar Threx, à Forgefer, peut vous apprendre à confectionner un objet de camping une fois votre maîtrise de la couture démontrée.",al={"qui enseigne cela","maître des couturiers","uthrar threx"}},{q="Que puis-je confectionner grâce à la couture ?",a="Vous pouvez apprendre à confectionner une Rallying Banner pour votre camp.",al={"objet de camping en couture","quelle bannière","confectionner une bannière"}},{q="À quoi sert la Rallying Banner ?",a="Une bannière inspirante peut vous aider à garder votre énergie, et le moral est important pour remporter la victoire sur un champ de bataille.",al={"utilité de la bannière","pourquoi une bannière","bannière de ralliement"}},{q="De quoi ai-je besoin avant d’établir un camp ?",a="Il vous faut un feu de camp avant d’installer votre camp. Un cuisinier peut vous apprendre à en allumer un.",al={"feu de camp nécessaire","comment établir un camp","conditions pour établir un camp"}}},fp="22,172,17.238.0,34.109.0,31.55.0,33.105.0,38.77.0"}
P.entries["quest:96058"] = {n="Camping 101: Engineering",s="À Kharanos, un ingénieur peut apprendre à fabriquer un Robot vendeur de composants pour son camp.",h="À Kharanos, un ingénieur peut apprendre à fabriquer un Robot vendeur de composants pour son camp.",kw={"bronk guzzlegear","camp","feu de camp","camping 101","ingénierie","kharanos","robot vendeur de composants","composants de sorts"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre aux autres à faire le feu de camp nécessaire à un camp.",["profession:Engineering"]="En tant qu’ingénieur, vous pouvez apprendre auprès de Bronk Guzzlegear à fabriquer un Robot vendeur de composants pour votre camp."},sec={{t="Les provisions du camp",b="À Kharanos, Bronk Guzzlegear peut apprendre à un ingénieur à fabriquer un Robot vendeur de composants. Vous devez faire preuve de maîtrise en ingénierie avant qu’il ne vous l’enseigne. Ce robot aide à fournir les composants nécessaires aux sorts que vous et vos alliés lancez."},{t="Prêts pour la nature",b="Vous pouvez maintenant fabriquer un Robot vendeur de composants. Pour le tester, quittez la ville et partez en pleine nature, où vous pourrez établir un camp. Prévoyez aussi un feu de camp ; les cuisiniers peuvent vous apprendre à en faire un."}},faq={{q="Qui peut m’apprendre à fabriquer un Robot vendeur de composants ?",a="Bronk Guzzlegear, à Kharanos, peut vous apprendre à fabriquer un Robot vendeur de composants si vous faites preuve de maîtrise en ingénierie.",al={"leçon de robot de bronk","qui est bronk guzzlegear","formateur en robot vendeur de composants"}},{q="À quoi sert un Robot vendeur de composants ?",a="Un Robot vendeur de composants aide à fournir à vous et à vos alliés les composants nécessaires aux sorts.",al={"à quoi sert le robot vendeur de composants","robot composants de sorts","robot de camp"}},{q="Que me faut-il avant de pouvoir apprendre cela ?",a="Vous devez faire preuve de maîtrise en ingénierie avant que Bronk Guzzlegear vous apprenne à fabriquer un Robot vendeur de composants.",al={"maîtrise en ingénierie","apprendre à fabriquer un robot vendeur de composants","camping 101 ingénierie"}},{q="Où puis-je essayer le Robot vendeur de composants ?",a="Vous pouvez tester le Robot vendeur de composants en pleine nature, car la plupart des gens ne souhaitent pas que des camps soient installés au centre de la ville.",al={"où tester le robot","emplacement du camp","robot vendeur de composants en pleine nature"}},{q="Ai-je besoin d’un feu de camp ?",a="Oui. Un camp a besoin d’un feu de camp, et la plupart des cuisiniers peuvent vous apprendre à en faire un.",al={"feu de camp nécessaire","comment faire un feu de camp","cuisine au camp"}}},fp="24,127,17.233.0,19.175.1,37.107.0,27.87.0,39.114.0,36.111.0,21.71.0"}
P.entries["quest:96059"] = {n="Camping 101: Enchanting",s="Un enchanteur de Forgefer peut apprendre à fabriquer un Luth enchanté pour le camp après avoir fait ses preuves. Sa magie permet de se divertir lors des haltes en chemin.",h="Un enchanteur de Forgefer peut apprendre à fabriquer un Luth enchanté pour le camp après avoir fait ses...",kw={"objet de camping","initiation au camping","luth enchanté","enchantement","forgefer","thonys pillarstone"},ang={["profession:Engineering"]="En tant qu’enchanteur, vous pouvez apprendre auprès de Thonys Pillarstone à fabriquer un Luth enchanté pour le camp une fois votre maîtrise démontrée."},sec={{t="Un luth pour le camp",b="Votre prochaine leçon porte sur un air à jouer en chemin. À Forgefer, Thonys Pillarstone peut vous apprendre à fabriquer un Luth enchanté une fois que vous avez démontré votre maîtrise de l’enchantement. Sa magie vous permet de vous divertir pendant les moments de repos avant de reprendre la route."}},faq={{q="Qui peut m’apprendre à fabriquer un Luth enchanté ?",a="Thonys Pillarstone, à Forgefer, peut vous apprendre à fabriquer un Luth enchanté après que vous avez démontré votre maîtrise de l’enchantement.",al={"thonys pillarstone","qui enseigne la fabrication d’un objet de camping d’enchantement"}},{q="À quoi sert le Luth enchanté ?",a="Le Luth enchanté est un objet de camping destiné à vous divertir pendant les moments de repos.",al={"utilité du luth","luth enchanté au camp"}},{q="Pourquoi dois-je maîtriser l’enchantement ?",a="Vous pouvez apprendre à fabriquer cet objet de camping une fois que vous avez démontré votre maîtrise de l’enchantement.",al={"maîtrise de l’enchantement","comment apprendre à fabriquer un luth"}}},fp="23,149,15.267.0,43.114.0,31.84.0,31.86.0"}
P.entries["quest:96063"] = {n="Gaseous Gold",s="Sleebo Fizzlespout veut du gaz des marais provenant des mares au sud-ouest d’ici. Il espère s’en servir pour alimenter un nouveau moteur.",h="Sleebo Fizzlespout veut du gaz des marais provenant des mares au sud-ouest d’ici.",kw={"moteur","fioles de gaz","or gazeux","industrie","gaz des marais","sciences","sleebo fizzlespout","cheminées"},sec={{t="Un nouveau carburant",b="Sleebo Fizzlespout voit du gaz s’échapper de cheminées près de l’eau, dans les mares marécageuses au sud-ouest. Il met au point un moteur qui fonctionne au gaz et vous demande de lui rapporter des fioles de gaz des marais. Ces travaux pourraient permettre d’utiliser ce carburant dans les domaines des sciences et de l’industrie."}},faq={{q="Qui demande du gaz des marais ?",a="Sleebo Fizzlespout vous demande de lui rapporter des fioles de gaz des marais.",al={"qui veut du gaz","sleebo fizzlespout"}},{q="Pourquoi Sleebo veut-il ce gaz ?",a="Sleebo met au point un nouveau type de moteur qui fonctionne au gaz des marais.",al={"à quoi sert le gaz","moteur à gaz"}},{q="D’où vient le gaz des marais ?",a="Le gaz s’échappe de cheminées près de l’eau, dans des mares marécageuses au sud-ouest de Sleebo.",al={"où se trouve le gaz","cheminées de gaz"}},{q="À quoi sert le gaz des marais ?",a="Sleebo espère utiliser le gaz des marais comme carburant pour son nouveau moteur.",al={"utilité du gaz des marais","carburant gazeux"}}},fp="12,109,10.260.0,28.62.0,29.65.0,35.76.0,27.57.0"}
P.entries["quest:96067"] = {n="Rock 'em and Sock 'em",s="Sleebo vous demande de tester G45-B4G, son prototype de moteur à gaz. L’essai lui fournira des notes pour les réparations et les modifications.",h="Sleebo vous demande de tester G45-B4G, son prototype de moteur à gaz.",kw={"g45-b4g","gaz","moteur à gaz","compagnon mécanique","prototype","sleebo","test de résistance"},sec={{t="Un essai mécanique",b="Sleebo possède un prototype fonctionnel de son moteur à gaz, logé dans le coffre en toile de jute de G45-B4G. Il peut alimenter son compagnon mécanique avec le gaz que vous avez récupéré. Il vous demande de tester la machine au combat afin de voir comment elle se comporte."},{t="Les notes de Sleebo",b="Après l’essai, Sleebo est satisfait du spectacle et des notes recueillies. Il prévoit de réparer G45-B4G et de régler le moteur avant le prochain test."}},faq={{q="Qui est G45-B4G ?",a="G45-B4G est le compagnon mécanique de Sleebo. Le coffre en toile de jute qu’il porte contient le prototype fonctionnel de son moteur à gaz.",al={"g45-b4g","qui est g45","compagnon mécanique"}},{q="Que veut faire tester Sleebo ?",a="Sleebo veut que vous testiez au combat G45-B4G, le prototype fonctionnel de son moteur à gaz.",al={"test de sleebo","tester le moteur","que dois-je tester"}},{q="Qu’est-ce qui alimente G45-B4G ?",a="Sleebo peut alimenter G45-B4G avec le gaz que vous avez récupéré.",al={"robot à gaz","carburant du moteur","qu’est-ce qui alimente g45"}},{q="G45-B4G peut-il ressentir la douleur ?",a="Non. Sleebo affirme que G45-B4G ne peut rien ressentir.",al={"g45 ressent-il quelque chose","faire mal à la machine","douleur du robot"}},{q="Pourquoi Sleebo teste-t-il son invention ?",a="Sleebo veut soumettre le prototype de son moteur à gaz à un test de résistance et noter ses performances.",al={"pourquoi tester g45","test de résistance du moteur","invention de sleebo"}}},fp="21,121,18.240.0,14.150.1,15.118.0,29.94.0,20.53.0,22.45.0,36.97.0"}
P.entries["quest:96101"] = {n="The Great Outdoors",s="Raan accueille les nouveaux voyageurs et leur apprend à survivre dans la nature. Reposez-vous près de son feu de camp basique pour obtenir Boosted Rest, puis rendez-vous auprès des maîtres de profession des environs pour apprendre des métiers pratiques.",h="Raan accueille les nouveaux voyageurs et leur apprend à survivre dans la nature.",kw={"feu de camp basique","boosted rest","installation de campement","feu de camp","raan","the great outdoors","métier","survie en pleine nature"},ang={["class:Hunter"]="En tant que chasseur, vous savez que l’art du campement est essentiel aux pisteurs et aux rôdeurs qui vivent sous le ciel ouvert.",["profession:Cooking"]="En tant que cuisinier, vous savez qu’un feu de camp basique aide un groupe en voyage à se reposer et à récupérer dans la nature."},sec={{t="Leçons de survie en pleine nature",b="Raan a parcouru les terres sauvages et apprend aux autres à survivre au-delà des remparts des colonies. L’ambition et l’acier ne suffisent pas face aux intempéries ; savoir camper est essentiel. Il accueille ceux qui cherchent fortune et gloire, et conseille tous ceux qui veulent apprendre."},{t="La chaleur du foyer",b="Raan vous invite à vous asseoir près de son feu de camp basique et à vous reposer jusqu’à obtenir Boosted Rest. Dans les contrées sauvages d’Azeroth, savoir quand faire une pause, établir un campement et récupérer peut faire la différence entre la vie et la mort.\n\nAprès la leçon, Raan vous oriente vers les maîtres des villages voisins. Vous pourrez y apprendre un métier et fabriquer des installations spécialisées pour votre campement."}},faq={{q="Qui donne la quête The Great Outdoors ?",a="Raan, un voyageur chevronné, apprend aux aventuriers itinérants à survivre en pleine nature.",al={"qui propose the great outdoors","donneur de quête the great outdoors","quête du feu de camp de raan"}},{q="Quel est le but de The Great Outdoors ?",a="Cette leçon enseigne la survie en pleine nature. Reposez-vous près d’un feu de camp basique pour obtenir Boosted Rest avant de vous lancer dans des voyages périlleux.",al={"que vous apprend the great outdoors","but de the great outdoors","que m’apprend raan"}},{q="Comment terminer la quête ?",a="Asseyez-vous près du feu de camp basique de Raan et reposez-vous jusqu’à obtenir Boosted Rest.",al={"comment terminer the great outdoors","objectif du feu de camp de raan","objectif de boosted rest"}},{q="Que conseille Raan de faire après avoir terminé la quête ?",a="Après la leçon près du feu de camp, Raan vous encourage à rendre visite aux maîtres des villages voisins pour apprendre un métier pratique. Les artisans peuvent fabriquer des installations de campement adaptées à leur métier.",al={"que conseille raan ensuite","où aller après the great outdoors","après avoir terminé the great outdoors"}},{q="Qu’est-ce que Boosted Rest ?",a="Boosted Rest est un effet réparateur obtenu en se reposant près d’un feu de camp établi. Il aide les voyageurs à récupérer tout en affrontant les éléments.",al={"qu’est-ce que boosted rest","bonus boosted rest du feu de camp"}},{q="Les métiers permettent-ils aux aventuriers de fabriquer des installations de campement ?",a="Oui. Les maîtres de profession locaux peuvent vous apprendre à fabriquer des installations de campement utiles, adaptées à votre métier, afin d’aménager un camp spécialisé en pleine nature.",al={"les métiers permettent-ils de fabriquer des feux de camp","installations de campement de métier","objets de campement fabriqués"}}},fp="18,180,19.275.0,24.350.0,39.99.0,42.116.0,27.70.0,56.166.0,21.141.0,60.144.0"}
P.entries["quest:96102"] = {n="Camping 101: Tailoring",s="La formation de couture vous apprend à confectionner une bannière de ralliement. Son épreuve se déroule en pleine nature, où un campement a besoin d’un feu de camp.",h="La formation de couture vous apprend à confectionner une bannière de ralliement.",kw={"feu de camp","campement","cuisine","bannière de ralliement","couture","pleine nature"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre aux autres à faire un feu de camp.",["profession:Tailoring"]="En tant que couturier, vous pouvez confectionner une bannière de ralliement pour un campement."},sec={{t="D’abord, un feu de camp",b="Vous pouvez maintenant confectionner une bannière de ralliement, et sa note d’achèvement demande de la tester en pleine nature. Un campement a besoin d’un feu de camp avant que vous l’installiez. La plupart des cuisiniers peuvent vous apprendre à en faire un. Demandez les bases à un maître cuisinier si vous ne les avez pas apprises."}},faq={{q="Que puis-je confectionner ensuite ?",a="La formation de couture vous apprend à confectionner votre propre bannière de ralliement.",al={"que confectionner","recette de bannière","bannière de couture"}},{q="Où dois-je tester la bannière ?",a="Testez votre bannière de ralliement en pleine nature. La note d’achèvement indique que les habitants des villes n’apprécient généralement pas les campements en plein centre-ville.",al={"où la tester","où camper","tester la bannière"}},{q="De quoi un campement a-t-il besoin ?",a="Avant d’installer un campement, il vous faut un feu de camp.",al={"besoins d’un campement","feu de camp nécessaire","bases du camping"}},{q="Qui peut m’apprendre à faire un feu de camp ?",a="La plupart des cuisiniers peuvent vous apprendre à faire du feu. Un maître cuisinier peut vous en enseigner les bases.",al={"maître cuisinier feu de camp","qui apprend à faire du feu","feu de camp et cuisine"}}},fp="22,124,16.243.0,27.65.0,31.134.0,22.46.0,36.84.0"}
P.entries["quest:96103"] = {n="A Feast for Buzzards",s="Un squelette meurtri dans les plaines porte des marques qui pourraient révéler à un chasseur ce qui s’est passé. Vous apportez son crâne à Neza Bloodsnout, à Rog’mar, pour qu’elle l’examine.",h="Un squelette meurtri dans les plaines porte des marques qui pourraient révéler à un chasseur ce qui s’est...",kw={"un festin pour les vautours","marques de griffes","crâne rongé","neza bloodsnout","rog’mar","squelette","marques de dents"},sec={{t="Un crâne dans les plaines",b="Les os reposent, meurtris, sous le soleil, leur surface pâle marquée de formes semblables à des dents et des griffes. Les dégâts ne permettent pas d’identifier la victime. Vous portez le crâne à Neza Bloodsnout, à Rog’mar, où une chasseuse pourra interpréter les marques."}},faq={{q="Qu’est-il arrivé au squelette ?",a="Ses membres portent des marques semblables à des dents et des griffes, mais l’assaillant reste inconnu.",al={"squelette dans les plaines","cause de sa mort"}},{q="Pourquoi apporter le crâne à Neza ?",a="Neza est une chasseuse de Rog’mar qui pourrait reconnaître la signification des marques.",al={"pourquoi apporter le crâne à neza","neza bloodsnout"}},{q="Qui était la victime ?",a="Le squelette est très abîmé et son identité reste inconnue avant que Neza examine le crâne.",al={"à qui est ce squelette","qui est la personne morte"}},{q="Où se trouve Neza Bloodsnout ?",a="Neza Bloodsnout se trouve à Rog’mar.",al={"emplacement de neza","où se trouve rog’mar"}}},fp="20,151,21.235.0,30.82.0,28.69.0,19.90.0,25.30.0"}
P.entries["quest:96104"] = {n="Song of the Strider",s="Neza Bloodsnout repère les traces d’un grand lion près de Rog’mar et propose de vous aider à le faire sortir. Vous lui apportez un bec de tallstrider pour qu’elle façonne un sifflet de chasse.",h="Neza Bloodsnout repère les traces d’un grand lion près de Rog’mar et propose de vous aider à le faire sortir.",kw={"bec","lion","neza bloodsnout","rog’mar","chant du tallstrider","tallstrider","sifflet"},sec={{t="Un sifflet de chasseur",b="À Rog’mar, Neza Bloodsnout reconnaît les traces d’un lion, probablement le chef d’une harde voisine. Elle vous propose la première prise sur cette chasse et vous aidera à faire sortir la bête. Pour cela, il lui faut un bec de tallstrider afin de façonner un sifflet qui imite le cri d’un tallstrider blessé."}},faq={{q="Qui est Neza Bloodsnout ?",a="Neza Bloodsnout est une chasseuse de Rog’mar qui sait fabriquer des sifflets et imiter les cris des animaux.",al={"neza","qui est neza","neza bloodsnout"}},{q="D’après Neza, qu’est-ce qui a laissé ces traces ?",a="Neza pense qu’elles ont été laissées par un lion, probablement le chef d’une harde voisine.",al={"qu’est-ce qui a laissé ces traces","traces de lion","traces à rog’mar"}},{q="Pourquoi Neza a-t-elle besoin d’un bec de tallstrider ?",a="Neza a besoin d’un bec de tallstrider pour façonner un sifflet qui imite le cri d’un tallstrider blessé.",al={"pourquoi un bec","à quoi sert le bec de tallstrider","bec pour le sifflet"}},{q="À quoi sert le sifflet ?",a="Le sifflet doit attirer le lion en imitant le cri d’un tallstrider blessé.",al={"à quoi sert le sifflet","attirer le lion","sifflet pour attirer le lion"}},{q="Où Neza vous demande-t-elle d’apporter le bec ?",a="Apportez le bec de tallstrider intact à Neza Bloodsnout, à Rog’mar.",al={"où apporter le bec","emplacement de neza","rapporter le bec"}}},fp="19,157,18.271.0,23.78.0,39.79.0,38.90.0,24.81.0,42.64.0"}
P.entries["quest:96105"] = {n="King of the Wild Plains",s="Neza Bloodsnout, à Rog’mar, vous envoie affronter le chef d’une troupe de lions. Un Tallstrider Call fera venir la bête sur la colline au sud, où vivent les lions.",h="Neza Bloodsnout, à Rog’mar, vous envoie affronter le chef d’une troupe de lions.",kw={"peau","colline","roi des plaines sauvages","chef","troupe de lions","neza bloodsnout","rog’mar","tallstrider call"},sec={{t="L’Appel",b="Neza Bloodsnout, à Rog’mar, a un Tallstrider Call pour vous. Portez-le au sommet de la colline au sud, où vivent les lions, puis utilisez-le quand vous serez prêt à affronter le chef de la troupe. Neza vous demande de rapporter la peau de la bête, et cette chasse mettra votre force à l’épreuve dans ces plaines."}},faq={{q="Qui veut la peau du lion ?",a="Neza Bloodsnout, à Rog’mar, vous demande de rapporter la peau du chef de la troupe de lions.",al={"qui m’a envoyé","neza bloodsnout","peau pour neza"}},{q="À quoi sert le Tallstrider Call ?",a="Utilisé, le Tallstrider Call fait apparaître le chef de la troupe de lions.",al={"à quoi sert le sifflet","sifflet d’appel","faire apparaître le lion"}},{q="Où dois-je utiliser le Tallstrider Call ?",a="Utilisez le Tallstrider Call au sommet de la colline au sud, où vivent les lions.",al={"où se trouve la colline","colline des lions","où l’appeler"}},{q="Quelle bête dois-je traquer ?",a="Vous traquez le chef de la troupe de lions.",al={"quelle bête","roi des plaines sauvages","chef des lions"}}},fp="23,159,8.293.0,26.86.0,34.68.0,40.83.0,18.45.0"}
P.entries["quest:96107"] = {n="Feathers for Fletching",s="Neza Bloodsnout, à Rog’mar, fabrique ses flèches et demande des Plains Buzzard Feathers. Leur texture grossière les rend utiles pour l’empennage.",h="Neza Bloodsnout, à Rog’mar, fabrique ses flèches et demande des Plains Buzzard Feathers.",kw={"flèches","plumes","empennage","chasseur","neza bloodsnout","plains buzzard","rog’mar"},ang={["class:Hunter"]="En tant que chasseur, vous savez que les flèches sont un besoin régulier ; Neza fabrique les siennes et fait confiance à son travail manuel."},sec={{t="Les flèches de Neza",b="À Rog’mar, Neza Bloodsnout vous demande de ramasser des plumes de buses dans les environs. Elle fabrique ses flèches à la main et fait confiance à son propre travail. Les plumes grossières conviennent à l’empennage, les ailettes qui aident une flèche à voler droit."}},faq={{q="Pourquoi Neza veut-elle des plumes de buse ?",a="Neza utilise les Plains Buzzard Feathers grossières pour empennage des flèches qu’elle fabrique à la main.",al={"raison des plumes de buse","pourquoi des plumes","plumes de neza"}},{q="Qui est Neza Bloodsnout ?",a="Neza Bloodsnout est une fabricante de flèches à Rog’mar qui préfère les fabriquer à la main.",al={"qui est neza","neza bloodsnout","neza à rog’mar"}},{q="Où trouver Neza ?",a="Neza Bloodsnout se trouve à Rog’mar.",al={"où est neza","emplacement de neza","rog’mar neza"}}},fp="22,139,13.215.0,36.91.0,23.84.0,22.30.0"}
P.entries["quest:96108"] = {n="Poison Tips",s="Neza Bloodsnout veut du venin de Glade Viper provenant des mares au sud de Rog’mar. Elle compte en enduire des flèches, même si le poison gâche la viande.",h="Neza Bloodsnout veut du venin de Glade Viper provenant des mares au sud de Rog’mar.",kw={"glade viper","neza bloodsnout","flèches empoisonnées","pointes empoisonnées","rog’mar","venin de vipère"},sec={{t="Un enduit mortel",b="Le poison peut rendre une flèche plus puissante, mais il gâche la viande. Neza Bloodsnout, à Rog’mar, pense que vous pouvez récolter le venin des vipères près des mares au sud. Leur venin est dangereux à manipuler, alors soyez prudent pendant la récolte."}},faq={{q="Qui veut le venin des vipères ?",a="Neza Bloodsnout, à Rog’mar, veut du venin de Glade Viper.",al={"qui a demandé du venin","venin de neza bloodsnout","qui est neza"}},{q="À quoi servira le venin ?",a="Neza compte utiliser le venin pour enduire des flèches de poison.",al={"pourquoi du venin","flèches empoisonnées","à quoi sert-il"}},{q="D’où vient le venin ?",a="Les Glade Vipers près des mares au sud produisent ce venin.",al={"où sont les vipères","emplacement du venin de vipère","vipères des mares"}},{q="Pourquoi enduire les flèches de poison ?",a="Le poison rend les flèches plus puissantes contre les proies, mais gâche la viande.",al={"pourquoi empoisonner les flèches","pourquoi des pointes empoisonnées","renforcer les flèches"}},{q="Est-il dangereux de récolter le venin de Glade Viper ?",a="Oui. Neza prévient que vous pourriez succomber au venin des vipères pendant la récolte.",al={"le venin peut-il me blesser","danger du poison de vipère","avertissement sur le venin"}}},fp="11,140,16.235.0,26.51.0,22.59.0,31.61.0,28.72.0,41.79.0"}
P.entries["quest:96109"] = {n="A Hunter's Quiver",s="Neza Bloodsnout, à Rog’mar, a besoin de peaux de lion pour un carquois de chasseur. Vous récupérez des peaux sur les lions de la colline du sud.",h="Neza Bloodsnout, à Rog’mar, a besoin de peaux de lion pour un carquois de chasseur.",kw={"flèches","chasseur","carquois de chasseur","peaux de lion","lions","neza bloodsnout","peaux de lion de qualité","rog’mar"},ang={["class:Hunter"]="En tant que chasseur, vous avez besoin d’un carquois pouvant contenir de nombreuses flèches sans vous ralentir."},sec={{t="L’équipement d’un chasseur",b="Les armes d’un chasseur nécessitent un carquois pouvant contenir de nombreuses flèches sans gêner son porteur. Neza Bloodsnout, à Rog’mar, vous demande de récupérer des peaux de lion de qualité pour en fabriquer un. Les lions chassent en meute ; Neza vous recommande donc de veiller à ne pas vous laisser encercler."}},faq={{q="Qui a besoin des peaux de lion ?",a="Neza Bloodsnout, à Rog’mar, a besoin de peaux de lion de qualité pour un carquois de chasseur.",al={"qui veut des peaux","peaux neza bloodsnout"}},{q="À quoi servent les peaux ?",a="Les peaux de lion serviront à fabriquer un carquois solide, bien ajusté et pouvant contenir de nombreuses flèches sans gêner son porteur.",al={"utilité des peaux de lion","peaux pour carquois"}},{q="Où se trouvent les lions ?",a="Les lions se rassemblent sur une colline au sud, visible depuis Rog’mar.",al={"colline des lions","où sont les lions"}},{q="Pourquoi Neza veut-elle des peaux de lion ?",a="Neza dit que les peaux de lion conviennent bien à la vie de chasseur dans les plaines.",al={"pourquoi des peaux de lion","lions pour carquois"}},{q="Quel avertissement Neza donne-t-elle ?",a="Neza vous avertit que les lions chassent en meute et risquent de vous encercler.",al={"avertissement sur les lions","meutes"}}},fp="17,120,15.230.0,25.73.0,23.118.0,20.62.0,30.71.0,28.61.0"}
P.entries["quest:96130"] = {n="Chakuyak",s="Près des bosquets à l’ouest du Lac Taureau-de-pierre, Chakuyak menace les voyageurs qui traversent Mulgore. Les membres des tribus locales ont désigné cette louve féroce pour la chasse, et sa peau sera honorée.",h="Près des bosquets à l’ouest du Lac Taureau-de-pierre, Chakuyak menace les voyageurs qui traversent Mulgore.",kw={"chakuyak","mulgore","louve des prairies","lac taureau-de-pierre","chasse tauren","voyageurs","peau de loup"},ang={["class:Hunter"]="En tant que chasseur, vous devez faire preuve de patience et d’un sens aigu de l’observation pour traquer une louve alpha féroce et solitaire dans les collines boisées. Traitez ce prédateur avec respect.",["race:Tauren"]="En tant que tauren, vous connaissez l’équilibre entre le respect de la nature et le devoir de protéger votre tribu. Utiliser la peau d’une bête abattue lui rend hommage."},sec={{t="L’ombre du Lac Taureau-de-pierre",b="Chakuyak rôde dans les bosquets à l’ouest du Lac Taureau-de-pierre, où les loups des prairies parcourent les plateaux herbeux et les collines ondulantes de Mulgore. Cette femelle alpha féroce est devenue un danger pour les voyageurs venus de loin. Les chasseurs locaux l’ont donc désignée pour être éliminée avant que d’autres vagabonds ne soient blessés."},{t="Révérence et nécessité",b="Pour les tribus locales, tuer Chakuyak appelle un respect solennel, pas des vantardises. Elles estiment que c’est nécessaire pour protéger les voyageurs et les villageois. Sa peau épaisse est tannée et utilisée, en hommage à la louve et pour que son sacrifice ne soit pas vain."}},faq={{q="Qui est Chakuyak, ou qu’est-ce que c’est ?",a="Chakuyak est une grande louve des prairies, exceptionnellement agressive, qui menace les voyageurs en Mulgore.",al={"qu’est-ce que chakuyak","qui est chakuyak","chakuyak est-elle une louve"}},{q="Où se trouve Chakuyak ?",a="Chakuyak rôde dans les bosquets à l’ouest du Lac Taureau-de-pierre, parmi les collines boisées.",al={"où trouver chakuyak","emplacement de chakuyak","où rôde chakuyak"}},{q="Pourquoi faut-il traquer Chakuyak ?",a="Chakuyak est devenue audacieuse et agressive, et représente un danger pour les voyageurs venus de loin.",al={"pourquoi tuer chakuyak","menace de chakuyak"}},{q="Que devient la peau de Chakuyak après la chasse ?",a="Sa peau est préservée et utilisée, afin que rien ne soit gaspillé.",al={"que devient la peau de chakuyak","fourrure de chakuyak"}},{q="Faut-il un groupe pour chasser Chakuyak ?",a="Chakuyak est exceptionnellement féroce. Les voyageurs se joignent souvent à de petits groupes de chasse pour la traquer et l’abattre sans danger.",al={"faut-il un groupe pour chakuyak","chakuyak est-elle difficile à vaincre en solo"}},{q="Qui reconnaît votre victoire sur Chakuyak ?",a="Le chasseur qui a organisé la chasse promet de vanter votre exploit auprès du chef de la tribu à votre retour avec la peau de Chakuyak.",al={"qui récompense la chasse à chakuyak","chakuyak et le chef"}}},fp="8,179,28.287.0,23.239.0,24.90.0,26.79.0,33.94.0,47.59.0,35.112.0,44.119.0"}
P.entries["quest:96137"] = {n="Dague d’Ira",s="Sirra Von'Indi vous demande d'enquêter sur la dague d'Ira et les worgs qui s'en prennent encore aux voyageurs. L'esprit d'Ira a peut-être une tâche inachevée dans la forêt.",h="Sirra Von'Indi vous demande d'enquêter sur la dague d'Ira et les worgs qui s'en prennent encore aux voyageurs.",kw={"black ravager","sombre-comté","ira","dague d'ira","forestière","sirra von'indi","esprit","worg","young black ravager"},sec={{t="Une dague de forestière",b="Sirra Von'Indi, à Sombre-Comté, vous demande de vous occuper des worgs qui continuent de faire des victimes dans la forêt. Ira s'était proclamée forestière et protégeait les bois en empêchant les bêtes d'attaquer les voyageurs. Son esprit y erre encore, et la dague lui appartenait. Sirra cherche à en savoir plus sur cette lame."}},faq={{q="Qui était Ira ?",a="Ira s'était proclamée forestière et protégeait la forêt en empêchant les bêtes d'attaquer les voyageurs.",al={"histoire d'ira","qui est ira"}},{q="Pourquoi l'esprit d'Ira erre-t-il dans la forêt ?",a="L'esprit d'Ira erre encore dans les bois, où elle a peut-être une tâche inachevée.",al={"pourquoi le fantôme d'ira","pourquoi ira est un fantôme"}},{q="Qu'est-ce que la dague d'Ira ?",a="C'est une petite dague qui appartenait à Ira.",al={"dague d'ira","histoire de la dague"}},{q="Pourquoi vous occupez-vous des worgs ?",a="Les worgs continuent de faire des victimes dans toute la forêt, et la tâche inachevée d'Ira consiste peut-être à les éliminer.",al={"worgs dans la forêt","quête des worgs d'ira"}},{q="Qui s'intéresse à la dague ?",a="Sirra Von'Indi, à Sombre-Comté, vous demande de lui rapporter la dague pour en savoir plus.",al={"dague de sirra","qui veut la dague d'ira"}}},fp="12,145,17.316.0,12.103.0,40.81.0,21.42.0,31.114.0,26.91.0"}
P.entries["quest:96138"] = {n="Merrick's Bow",s="Sirra Von'Indi vous demande d'enquêter sur les ogres qui tourmentent l'esprit de Merrick Valor près de la Colline-aux-Corbeaux. L'arc de Merrick pourrait éclairer l'histoire des lieux.",h="Sirra Von'Indi vous demande d'enquêter sur les ogres qui tourmentent l'esprit de Merrick Valor près de la...",kw={"sombre-comté","merrick valor","arc de merrick","ogres","colline-aux-corbeaux","sirra von'indi","splinter fist","watcher"},sec={{t="L'inquiétude d'un esprit",b="Près de la Colline-aux-Corbeaux, l'esprit de Merrick Valor erre encore sur les routes. Vous possédez un arc qu'il a laissé derrière lui, et ses affaires inachevées pourraient concerner les ogres au sud de la ville. Sirra Von'Indi, à Sombre-Comté, peut vous en apprendre davantage sur l'arc et le passé de Merrick."},{t="Le passé de Merrick",b="Sirra Von'Indi dit que Merrick a toujours voulu faire ses preuves, et qu'il lui est arrivé quelque chose, à lui et à sa famille. Elle vous remercie d'avoir apporté l'arc et espère qu'il permettra de mieux éclairer l'histoire de la Colline-aux-Corbeaux."}},faq={{q="Qui était Merrick Valor ?",a="Merrick Valor était un Watcher renommé qui mettait un point d'honneur à protéger les routes des ennemis qui gagnaient du terrain.",al={"merrick","merrick valor"}},{q="Pourquoi l'esprit de Merrick erre-t-il ?",a="L'esprit de Merrick erre encore sur les routes. Ses affaires inachevées pourraient être liées aux ogres au sud de la Colline-aux-Corbeaux.",al={"fantôme de merrick","pourquoi l'esprit erre"}},{q="Quel rapport y a-t-il entre l'arc de Merrick et la Colline-aux-Corbeaux ?",a="Sirra Von'Indi espère que l'arc de Merrick permettra de mieux éclairer l'histoire de la Colline-aux-Corbeaux.",al={"arc de merrick","arc colline-aux-corbeaux"}},{q="Qui est Sirra Von'Indi ?",a="Sirra Von'Indi se trouve à Sombre-Comté et peut vous en apprendre davantage sur l'arc de Merrick.",al={"sirra","sirra von indi"}},{q="Qu'est-il arrivé à Merrick et à sa famille ?",a="Sirra Von'Indi dit qu'il est arrivé quelque chose à Merrick et à sa famille, sans donner plus de détails.",al={"famille de merrick","qu'est-il arrivé à merrick"}}},fp="13,154,18.240.0,14.205.1,22.96.0,34.111.0,51.79.0,22.73.0,40.95.0"}
P.entries["quest:96139"] = {n="The Valor Family",s="À Sombre-Comté, Sirra Von'Indi cherche des archives sur les habitants disparus de Colline-aux-Corbeaux. Le village se souvient de leur courage, mais sa bibliothèque conserve peu de traces de l'histoire de Colline-aux-Corbeaux.",h="À Sombre-Comté, Sirra Von'Indi cherche des archives sur les habitants disparus de Colline-aux-Corbeaux.",kw={"sombre-comté","bois de la pénombre","histoire","dame althea","colline-aux-corbeaux","sirra von'indi","tome","famille valor"},sec={{t="Une histoire oubliée",b="Sirra Von'Indi dit que des gens courageux ont aidé Sombre-Comté à tenir bon. Dame Althea comptait parmi eux, tout comme ceux qui sont morts à Colline-aux-Corbeaux. On vous demande de chercher tout document susceptible de préserver leur mémoire."},{t="Le tome",b="Le livre que vous rapportez raconte l'histoire de la famille Valor. Sirra propose de le recopier et accueille tout autre document à leur sujet."}},faq={{q="Qui me demande de chercher à Colline-aux-Corbeaux ?",a="Sirra Von'Indi, dont la bibliothèque se trouve à Sombre-Comté, vous demande de chercher à Colline-aux-Corbeaux des documents sur ses habitants.",al={"qui veut le livre","sirra colline-aux-corbeaux","qui est sirra"}},{q="Pourquoi Sirra veut-elle des archives de Colline-aux-Corbeaux ?",a="Sirra veut que l'histoire de Colline-aux-Corbeaux reste dans les mémoires. Elle a disparu avec les habitants qui y vivaient.",al={"pourquoi chercher à colline-aux-corbeaux","histoire de colline-aux-corbeaux","se souvenir de colline-aux-corbeaux"}},{q="Qui, selon Sirra, a aidé Sombre-Comté à tenir bon ?",a="Sirra cite dame Althea et ceux qui ont perdu la vie à Colline-aux-Corbeaux parmi les gens courageux dont les actes ont aidé Sombre-Comté à tenir bon.",al={"héros de sombre-comté","dame althea","qui a sauvé sombre-comté"}},{q="Quelle est l'histoire de Colline-aux-Corbeaux ?",a="Sirra dit que l'histoire de Colline-aux-Corbeaux a disparu avec ses habitants. Sa bibliothèque en conserve peu de traces.",al={"que s'est-il passé à colline-aux-corbeaux","passé de colline-aux-corbeaux","colline-aux-corbeaux disparue"}}},fp="16,162,14.194.0,8.118.1,38.107.0,44.95.0,50.123.0,34.98.0"}
P.entries["quest:962"] = {n="Fleur de serpent",s="Au fond des Cavernes des lamentations, la Fleur de serpent attire l’attention de l’Apothecary Zamah. Elle cherche d’autres spécimens pour les recherches de la Société royale des apothicaires et des Réprouvés.",h="Au fond des Cavernes des lamentations, la Fleur de serpent attire l’attention de l’Apothecary Zamah.",kw={"apothicaire","tarides","société royale des apothicaires","fleur de serpent","cime des esprits","pitons-du-tonnerre","fossoyeuse","cavernes des lamentations","zamah"},ang={["faction:Horde"]="Ce travail renforce la première alliance entre Fossoyeuse et les tribus de Kalimdor. Elles partagent des ressources et des composants rares par-delà l’océan.",["profession:Herbalism"]="Les Cavernes des lamentations tortueuses abritent une flore qu’on ne trouve nulle part ailleurs à la surface brûlée par le soleil des Tarides.",["race:Tauren"]="En tant que Tauren, vous voyez l’hospitalité de la Horde dans l’accueil réservé aux apothicaires réprouvés sous la Cime des Esprits. Leurs concoctions mortelles contrastent avec les soins traditionnels de la terre.",["race:Undead"]="La récolte de Fleur de serpent soutient les travaux alchimiques de la Société royale des apothicaires en Lordaeron, sous le mandat de la Dame noire."},sec={{t="Le regard de l’apothicaire",b="L’Apothecary Zamah veille sur les Bassins de la Vision, sous la Cime des Esprits des Pitons-du-Tonnerre. Elle est venue de Fossoyeuse comme envoyée de la Société royale des apothicaires. Ses hôtes taurens veillent à l’équilibre spirituel et à la terre blessée, tandis que Zamah étudie des substances rares et virulentes. Elle a isolé un échantillon de Fleur de serpent et en cherche d’autres pour les recherches de Dame Sylvanas Coursevent et des Réprouvés."},{t="Les profondeurs des cavernes",b="La Fleur de serpent pousse dans les grottes humides et tortueuses des Cavernes des lamentations, loin du soleil des Tarides. Les druides corrompus du Croc ont dénaturé ces profondeurs moites, où des créatures serpentines gardent la plante. Nombre d’éclaireurs envoyés par Zamah ne sont pas revenus. Elle cherche maintenant des aventuriers robustes pour en récolter davantage."}},faq={{q="Qui est l’Apothecary Zamah ?",a="L’Apothecary Zamah est une chercheuse venue de Fossoyeuse et une envoyée de la Société royale des apothicaires. Elle veille sur les Bassins de la Vision, sous la Cime des Esprits des Pitons-du-Tonnerre, et relie les alchimistes réprouvés au reste du continent de Kalimdor.",al={"zamah","lore de l’apothecary zamah","qui donne la fleur de serpent"}},{q="Pourquoi la Société royale des apothicaires veut-elle de la Fleur de serpent ?",a="Zamah pense que la Fleur de serpent possède un potentiel chimique lorsqu’elle est raffinée en grande quantité. La Société recherche des plantes rares et puissantes dans tout Kalimdor pour soutenir les expériences alchimiques des Réprouvés.",al={"pourquoi la fleur de serpent","recherches de plantes des réprouvés","utilité de la fleur de serpent"}},{q="Où pousse la Fleur de serpent ?",a="La Fleur de serpent pousse dans des cavernes humides sous le nord des Tarides, dans les couloirs et les passages rocheux des Cavernes des lamentations.",al={"où trouver la fleur de serpent","emplacement de la fleur de serpent"}},{q="Pourquoi les éclaireurs précédents ne sont-ils pas revenus ?",a="Les Cavernes des lamentations grouillent de bêtes dégénérées, de raptors et de druides corrompus du Croc. Des cueilleurs inexpérimentés ont vite succombé aux prédateurs et aux gardiens venimeux des tunnels sinueux.",al={"éclaireurs disparus","éclaireurs de zamah","les cavernes des lamentations sont-elles dangereuses"}},{q="Les Tauren approuvent-ils les recherches de Zamah ?",a="Les Tauren des Pitons-du-Tonnerre ont accordé l’asile aux Réprouvés par compassion et par désir de les guérir. L’alchimie de la Société royale des apothicaires peut se rapprocher d’expériences contre nature, ce qui inquiète les chamans et les druides traditionnels.",al={"réaction des taurens","apothicaires à la cime des esprits"}},{q="Faut-il maîtriser l’herboristerie pour récolter la Fleur de serpent ?",a="Non. Tout aventurier prêt à braver les Cavernes des lamentations peut cueillir la Fleur de serpent sur le sol de la caverne, sans formation en herboristerie.",al={"faut-il l’herboristerie","récolter la fleur de serpent et métier"}}},fx={["962715c8"]={q="Pourquoi Apothecary Zamah souhaite-t-elle que la Fleur de serpent soit récoltée ?",a="Apothecary Zamah a été envoyée aux Pitons-du-Tonnerre par la Société royale des apothicaires pour une mission spécifique visant à faire avancer les intérêts des Réprouvés et de la Dame noire, Dame Sylvanas Coursevent. Après avoir analysé un échantillon rare de Fleur de serpent, Zamah voit un immense potentiel dans ses propriétés si elle est obtenue en quantités importantes. Obtenir suffisamment de spécimens permet à ses recherches de faire progresser les ambitions scientifiques et alchimiques de Fossoyeuse.",al={"motif d'apothecary zamah","pourquoi zamah a besoin de fleur de serpent","pourquoi récolter la fleur de serpent"}},["92b49307"]={q="Pourquoi Apothecary Zamah envoie-t-elle un aventurier plutôt que de récolter elle-même la Fleur de serpent ?",a="Zamah ne peut pas facilement abandonner son poste aux Pitons-du-Tonnerre, et la récolte de l'herbe nécessite de s'aventurer dans les profondeurs traîtresses et corrompues des Cavernes des lamentations. Elle a déjà envoyé plusieurs éclaireurs et agents dans le système de grottes pour son compte, mais aucun d'entre eux n'en est revenu vivant. Elle a besoin d'aventuriers chevronnés et compétents, prêts à braver ces recoins sombres là où les éclaireurs ordinaires ont échoué.",al={"pourquoi m'envoyer pour la fleur de serpent","pourquoi zamah ne récolte-t-elle pas la fleur de serpent","pourquoi des aventuriers pour la fleur de serpent"}}},fp="12,168,22.387.0,25.307.0,24.232.0,56.188.0,29.123.0,37.206.0,42.221.0,54.126.0"}
P.entries["quest:96204"] = {n="The Windshaper's Wrath",s="Lumina Windsinger vous demande de l’aider à s’échapper du Donjon de Fenris. Votre aide lui donne une raison de faire confiance aux paladins.",h="Lumina Windsinger vous demande de l’aider à s’échapper du Donjon de Fenris.",kw={"évasion","donjon de fenris","lumina windsinger","paladin","trevan","sculpte-vent"},ang={["class:Paladin"]="Lumina a entendu des propos peu aimables sur les paladins comme vous, mais votre aide lui donne une raison de vous accueillir en ami."},sec={{t="Une issue",b="Lumina Windsinger est libre dans le Donjon de Fenris, mais elle veut partir avec vous. Elle compte faire regretter aux créatures qui la retenaient de s’être attaquées à une Sculpte-vent. Restez à ses côtés pendant sa fuite."},{t="Une nouvelle amie",b="Au Donjon de Fenris, Lumina vous dit avoir rencontré Trevan et appris qu’il vous avait envoyé la chercher. Elle a entendu des propos peu aimables sur les paladins, mais votre aide lui a fait changer d’avis. Les Sculpte-vents vous considèrent, vous et vos semblables, comme des amis."}},faq={{q="Qui est Lumina Windsinger ?",a="Lumina Windsinger est une Sculpte-vent qui était retenue au Donjon de Fenris et sollicite votre aide pour s’en échapper.",al={"lumina","qui est lumina","windsinger"}},{q="D’où Lumina essaie-t-elle de s’échapper ?",a="Lumina Windsinger essaie de s’échapper du Donjon de Fenris.",al={"fuite de lumina","donjon de fenris","faire sortir lumina"}},{q="Qui m’a envoyé chercher Lumina ?",a="Lumina dit que Trevan vous a envoyé sur sa piste.",al={"qui m’a envoyé","trevan","piste de lumina"}},{q="Pourquoi Lumina parle-t-elle des paladins ?",a="Lumina a entendu des propos peu aimables sur les paladins, mais elle dit que votre aide lui a prouvé qu’ils étaient infondés.",al={"histoire de paladins","lumina paladins","fait-elle confiance aux paladins"}},{q="Que pense Lumina de moi ?",a="Lumina dit que vous et vos semblables avez une amie parmi les Sculpte-vents.",al={"lumina m’apprécie","ami des sculpte-vents","que dit lumina"}}},fp="22,103,9.192.0,12.220.1,25.91.0,38.50.0,27.44.0,33.102.0,29.66.0"}
P.entries["quest:96241"] = {n="Talkin' bout Toxins, Mon",s="Mazu'kon veut que vous préleviez des échantillons de venin sur les Gnawed Corpses à la Cime du Chagrin. Ces étranges toxines ont éveillé sa curiosité.",h="Mazu'kon veut que vous préleviez des échantillons de venin sur les Gnawed Corpses à la Cime du Chagrin.",kw={"extracteur","cime du chagrin","échantillons de toxine de la cime du chagrin","gnawed corpses","mazu'kon","toxine","venin"},sec={{t="À la Cime du Chagrin",b="Mazu'kon a entendu parler d'étranges nouvelles créatures qui grouillent à la Cime du Chagrin. Leur venin pourrait avoir des propriétés inhabituelles, alors il vous demande de prélever des échantillons sur les Gnawed Corpses avec son extracteur. Il est curieux de découvrir ce qui rend cette toxine différente."},{t="Les échantillons",b="Mazu'kon vous remercie d'avoir rapporté les échantillons de toxine de la Cime du Chagrin. Il affirme que les propriétés inhabituelles du venin n'étaient pas une plaisanterie et remarque que vous semblez indemne."}},faq={{q="Qui demande les échantillons de toxine ?",a="Mazu'kon vous demande de prélever des échantillons de venin sur les Gnawed Corpses à la Cime du Chagrin.",al={"qui veut des toxines","toxine mazu'kon"}},{q="Pourquoi Mazu'kon veut-il ce venin ?",a="Il a entendu dire que le venin de ces créatures pourrait avoir des propriétés inhabituelles, ce qui a éveillé sa curiosité.",al={"pourquoi les toxines","objet de sa curiosité"}},{q="Où trouver les échantillons ?",a="Les échantillons proviennent des Gnawed Corpses à la Cime du Chagrin.",al={"où trouver les échantillons de toxine","cadavres de la cime du chagrin"}},{q="Que vous donne Mazu'kon ?",a="Mazu'kon vous donne un extracteur pour prélever le venin.",al={"extracteur","comment prélever la toxine"}},{q="De combien d'échantillons de toxine a-t-il besoin ?",a="Mazu'kon demande cinq Gloomrise Toxin Samples.",al={"nombre d'échantillons","combien de toxines"}}},fp="24,127,12.244.0,11.153.1,36.80.0,33.91.0,27.50.0,28.52.0,36.47.0"}
P.entries["quest:96243"] = {n="Call of Earth",s="Dans la Vallée des Frigères, Call of Earth envoie l’initié chercher Teo Hammerstorm à Courbenclume. Là commence la communion du chaman avec les esprits de la pierre.",h="Dans la Vallée des Frigères, Call of Earth envoie l’initié chercher Teo Hammerstorm à Courbenclume.",kw={"courbenclume","call of earth","vallée des frigères","dun morogh","totem de terre","éléments","chaman","teo hammerstorm"},ang={["class:Shaman"]="En tant que chaman, répondre à l’appel de la terre ouvre votre voie et vous lie à la pierre profonde ainsi qu’aux esprits inébranlables du pays.",["faction:Alliance"]="En tant que chaman de l’Alliance à Dun Morogh, vous commencez votre parcours élémentaire à Courbenclume, le bastion ancestral des nains.",["race:Dwarf"]="En tant que nain, votre lien avec la pierre et la terre peut rendre la communion avec ces esprits naturelle dans les profondes salles de Dun Morogh."},sec={{t="La voix de la pierre",b="La première communion de l’initié avec les éléments commence lorsque la terre l’appelle. D’autres énergies élémentaires peuvent déjà s’agiter, mais parler à la pierre apporte l’équilibre. La terre lui apprend à trouver une force qui ne cède pas. Le sol devient ferme sous ses bottes et dans son esprit."},{t="Le bastion de Courbenclume",b="Dans les étendues enneigées de Dun Morogh, les initiés trouvent refuge et enseignement à Courbenclume. Ce bastion se dresse dans la Vallée des Frigères, forgé par le marteau, le feu et la volonté. Teo Hammerstorm les y attend. Il apprend aux jeunes chamans à écouter les grondements de la terre et à commencer leurs devoirs élémentaires."}},faq={{q="Qu’est-ce que Call of Earth ?",a="Call of Earth appelle les futurs chamans à commencer leur communion avec les esprits de la terre. La convocation dirige l’initié vers un guide et l’invite à trouver son ancrage dans la puissance de la pierre vivante.",al={"qu’est-ce que call of earth","quête call of earth","quelle est cette quête"}},{q="Qui est Teo Hammerstorm ?",a="Teo Hammerstorm enseigne aux initiés à Courbenclume, le bastion nain de la Vallée des Frigères. Il les guide dans leur communion avec la terre et leur apprend à puiser dans sa force constante.",al={"qui est teo hammerstorm","où se trouve teo hammerstorm","emplacement de teo hammerstorm"}},{q="Qu’est-ce que Courbenclume ?",a="Courbenclume est un bastion nain de la Vallée des Frigères, dans les étendues enneigées de Dun Morogh. Forgé par le marteau, le feu et la volonté, c’est une redoute où s’entraînent les jeunes héros.",al={"où se trouve courbenclume","qu’est-ce que courbenclume","emplacement de courbenclume"}},{q="Pourquoi un chaman doit-il écouter l’appel de la terre ?",a="Un chaman écoute l’appel de la terre pour ancrer son esprit et trouver un sol ferme sous ses pieds. La communion avec la pierre lui donne accès à sa puissance constante.",al={"pourquoi parler à la terre","but de call of earth","lien du chaman avec la terre"}},{q="Qui reçoit cette convocation ?",a="Cette convocation s’adresse aux chamans qui commencent leur parcours à Dun Morogh. Elle les dirige vers des maîtres des éléments expérimentés, capables de guider leur lien avec les esprits.",al={"qui lance call of earth","qui reçoit call of earth","qui fait cette quête"}},{q="Où cette quête mène-t-elle ?",a="Le voyage mène à Courbenclume, dans la Vallée des Frigères, au cœur de Dun Morogh enneigé. Les initiés entrent dans le bastion pour trouver leur mentor.",al={"où se déroule call of earth","zone de call of earth","où aller"}}},fp="13,156,18.294.0,24.275.0,22.177.0,23.171.0,17.163.0,41.157.0,28.155.0,27.130.0"}
P.entries["quest:96259"] = {n="Defending the Dead",s="À la Cime du Chagrin, des araignées menacent Mulgore et un ancien cimetière tauren. On vous demande d’aider à contenir l’infestation.",h="À la Cime du Chagrin, des araignées menacent Mulgore et un ancien cimetière tauren.",kw={"defending the dead","cime du chagrin","nouveau-nés","mulgore","soldats","araignées","cimetière tauren"},ang={["race:Tauren"]="En tant que tauren, la Cime du Chagrin compte pour vous comme un ancien cimetière que beaucoup des vôtres tiennent pour sacré."},sec={{t="Le cimetière",b="Un camp vous demande de protéger la Cime du Chagrin, un ancien cimetière tauren situé au nord-ouest du camp. Des araignées féroces infestent les lieux, menaçant la population de Mulgore et dégradant un endroit que beaucoup de taurens tiennent pour sacré."},{t="Un point d’appui",b="Vos efforts aident la population de Mulgore à établir un point d’appui contre les araignées. Éradiquer complètement l’infestation pourrait prendre du temps, et le cimetière reste donc menacé."}},faq={{q="Qu’est-ce que la Cime du Chagrin ?",a="La Cime du Chagrin est un ancien cimetière tauren situé au nord-ouest du camp.",al={"cimetière de la cime du chagrin","où se trouve la cime du chagrin"}},{q="Pourquoi la Cime du Chagrin est-elle en danger ?",a="De féroces araignées infestent la Cime du Chagrin, menaçant la population de Mulgore et dégradant le cimetière sacré.",al={"araignées à la cime du chagrin","pourquoi défendre les morts"}},{q="Pourquoi le cimetière est-il sacré ?",a="Beaucoup de taurens considèrent la Cime du Chagrin comme sacrée.",al={"lieu sacré tauren","pourquoi un cimetière tauren"}},{q="Qui demande de l’aide ?",a="Un camp vous demande d’aider à protéger la Cime du Chagrin contre l’infestation d’araignées.",al={"qui a besoin d’aide","qui a donné ceci"}},{q="L’infestation a-t-elle été éradiquée ?",a="Non. Vos efforts permettent d’établir un point d’appui, mais éradiquer complètement l’infestation pourrait prendre du temps.",al={"les araignées ont-elles disparu","infestation à la cime du chagrin"}}},fp="18,133,17.202.0,10.170.1,18.67.0,27.103.0,32.38.0,18.70.0,33.90.0"}
P.entries["quest:96260"] = {n="Stronger than Steel",s="À la Cime du Chagrin, un chercheur veut de la soie cristalline des araignées géantes qui prolifèrent. Cette soie pourrait donner une étoffe légère offrant une solide protection.",h="À la Cime du Chagrin, un chercheur veut de la soie cristalline des araignées géantes qui prolifèrent.",kw={"cape","étoffe","soie cristalline","cime du chagrin","araignées","plus solide que l’acier","venin"},sec={{t="De la soie à étudier",b="Un chercheur vous demande davantage de soie cristalline après qu’un éclaireur est revenu de la Cime du Chagrin couvert de cette matière. Des araignées géantes ont envahi le cimetière, et leur venin aurait le pouvoir de réveiller les morts. La résistance de cette soie pourrait permettre d’en faire une étoffe protectrice."},{t="Un nouveau tissage",b="Les échantillons suffisent aux besoins du chercheur. Une cape tissée avec de la soie déjà disponible vous est offerte, dans l’espoir qu’elle vous aidera dans vos voyages."}},faq={{q="Que veut le chercheur ?",a="Le chercheur veut davantage de soie cristalline des araignées de la Cime du Chagrin pour l’étudier.",al={"échantillons de soie","soie cristalline","quelle soie"}},{q="Où trouve-t-on la soie ?",a="La soie cristalline provient des araignées géantes de la Cime du Chagrin.",al={"où trouver la soie","soie de la cime du chagrin","où trouver la soie d’araignée"}},{q="Pourquoi étudier la soie ?",a="La soie pourrait servir à fabriquer une étoffe légère et résistante aux propriétés protectrices.",al={"utilité de la soie","que peut-on faire avec la soie","pourquoi la soie"}},{q="Que dit-on du venin des araignées ?",a="Le venin des araignées serait assez puissant pour réveiller les morts.",al={"venin d’araignée","réveiller les morts","rumeur sur le venin"}},{q="Qu’a rapporté l’éclaireur ?",a="Un éclaireur est revenu d’une reconnaissance à la Cime du Chagrin couvert de soie d’araignée cristalline et résistante.",al={"rapport de l’éclaireur","soie de l’éclaireur","qu’est-il arrivé à l’éclaireur"}}},fp="19,138,14.273.0,11.152.1,30.80.0,24.59.0,19.79.0,41.67.0,30.94.0"}
P.entries["quest:96261"] = {n="The Broodmother",s="À la Cime du Chagrin, le Cercle terrestre vous demande d’endiguer l’infestation d’araignées en affrontant leur mère des couvées. Cette menace met en danger la population de Mulgore.",h="À la Cime du Chagrin, le Cercle terrestre vous demande d’endiguer l’infestation d’araignées en affrontant...",kw={"mère des couvées","cercle terrestre","cime du chagrin","infestation","mulgore","forme d’elfe de la nuit","araignées","valraxx"},sec={{t="Le nid de la Cime du Chagrin",b="Le Cercle terrestre pense qu’une puissante matriarche est à l’origine de l’infestation d’araignées à la Cime du Chagrin. On vous demande de trouver Broodmother Valraxx et de la détruire. Ces araignées semblent différentes des araignées ordinaires, aussi le Cercle vous recommande de vous préparer à toute éventualité."},{t="Des signes inquiétants",b="Par la suite, le Cercle terrestre fait état de morts réanimés et d’une mère des couvées ayant une forme d’elfe de la nuit. Ces découvertes inquiètent ses membres, même s’ils laissent de côté la question de leur signification. Ils vous remercient d’avoir aidé le Cercle et la population de Mulgore."}},faq={{q="Que se passe-t-il à la Cime du Chagrin ?",a="Une infestation d’araignées s’étend à la Cime du Chagrin, et le Cercle terrestre pense qu’une puissante matriarche la dirige.",al={"araignées de la cime du chagrin","infestation d’araignées","que trouve-t-on à la cime du chagrin"}},{q="Qui est Broodmother Valraxx ?",a="Broodmother Valraxx est la mère des couvées de la Cime du Chagrin que le Cercle terrestre vous demande de détruire.",al={"valraxx","mère des couvées","matriarche des araignées"}},{q="Pourquoi le Cercle terrestre veut-il éliminer la mère des couvées ?",a="Le Cercle pense que la mère des couvées pousse la population d’araignées hostiles à se propager.",al={"pourquoi tuer la mère des couvées","pourquoi valraxx","arrêter les araignées"}},{q="Où se trouve la mère des couvées ?",a="Broodmother Valraxx se trouve à la Cime du Chagrin.",al={"emplacement de valraxx","où est la mère des couvées","emplacement de la cime du chagrin"}},{q="Que dit le Cercle terrestre au sujet de ces araignées ?",a="Le Cercle terrestre affirme que ces araignées ne semblent pas ordinaires.",al={"araignées étranges","araignées ordinaires","araignées bizarres"}}},fp="15,149,18.247.0,15.238.1,31.113.0,27.94.0,52.85.0,25.36.0,51.59.0"}
P.entries["quest:96264"] = {n="Elemental Aid",s="Un chaman doit enquêter sur le rassemblement des hurans au Kraal de Tranchebauge. La terre annonce un rituel, et les éléments ont besoin d’aide contre ceux qui abusent de leur pouvoir.",h="Un chaman doit enquêter sur le rassemblement des hurans au Kraal de Tranchebauge.",kw={"charlga trancheflanc","terre","aide élémentaire","éléments","hurans","kraal de tranchebauge","rituel","chaman"},ang={["class:Shaman"]="En tant que chaman, vous maîtrisez les éléments, et cette demande vous invite à leur rendre l’aide qu’ils vous ont apportée."},sec={{t="L’avertissement de la terre",b="La terre transmet un avertissement à un chaman : les hurans se rassemblent dans le Kraal de Tranchebauge pour un rituel d’une puissance terrible. Votre tâche consiste à explorer leur repaire et à rapporter des informations sur leurs plans. Les éléments vous prêtent leur aide, et ils ont maintenant besoin de la vôtre."}},faq={{q="Quel avertissement la terre donne-t-elle ?",a="La terre avertit que les hurans se rassemblent pour un rituel d’une puissance terrible.",al={"avertissement de la terre","qu’est-ce qui gronde","rituel des hurans"}},{q="Où les hurans se rassemblent-ils ?",a="Les hurans se rassemblent au Kraal de Tranchebauge.",al={"où enquêter","emplacement des hurans","emplacement du kraal"}},{q="Pourquoi le chaman doit-il aider les éléments ?",a="Les éléments aident le chaman, et on lui demande de leur rendre la pareille en les aidant contre ceux qui abusent de leur pouvoir.",al={"aider les éléments","elemental aid raison","pourquoi aider les éléments"}},{q="Quelles informations faut-il obtenir ?",a="On vous demande d’enquêter au Kraal de Tranchebauge et de rapporter des informations sur les projets des hurans.",al={"que trouver","projets des hurans","informations nécessaires"}},{q="De qui vient la demande ?",a="La demande vient d’une personne qui vous appelle chaman et affirme que les éléments ont besoin d’aide.",al={"qui demande","donneur de quête","qui a besoin d’aide"}}},fp="13,166,21.259.0,31.79.0,33.45.0,46.124.0,27.95.0,22.88.0"}
P.entries["quest:96294"] = {n="A Darker Truth",s="Muln Earthfury vous demande de lui apporter une lettre récupérée à la Cime du Chagrin. Elle pourrait éclaircir le mystère des araignées qui s’y trouvent.",h="Muln Earthfury vous demande de lui apporter une lettre récupérée à la Cime du Chagrin.",kw={"a darker truth","broodmother valraxx","cercle cénarien","cime du chagrin","muln earthfury","druide elfe de la nuit","pact","plateau de guette-ciel","araignées","wild king"},sec={{t="Une lettre à la Cime du Chagrin",b="À la Cime du Chagrin, vous avez découvert que la Broodmother était une druidesse elfe de la nuit sous une forme animale difforme. Des questions demeurent sur les araignées et leur rôle. Un mot trouvé dans sa robe pourrait apporter des réponses, alors vous le portez à Muln Earthfury, au Plateau de Guette-ciel."},{t="L’inquiétude de Muln",b="Muln Earthfury trouve la lettre troublante. Elle évoque un « Wild King » et un « Pact », mais il ignore de qui ou de quoi il s’agit. Il compte consulter le Cercle cénarien, tout en se rassurant à l’idée que celle qui contrôlait les araignées n’est plus."}},faq={{q="Qui était la Broodmother ?",a="La Broodmother était une druidesse elfe de la nuit qui avait pris une forme animale difforme.",al={"identité de la broodmother","qui est valraxx","araignée elfe ?"}},{q="Que dois-je apporter à Muln Earthfury ?",a="Vous apportez à Muln Earthfury la lettre récupérée dans la robe de Broodmother Valraxx.",al={"quelle lettre","lettre de muln","apporter quoi ?"}},{q="Où dois-je porter la lettre ?",a="Vous portez la lettre à Muln Earthfury, au Plateau de Guette-ciel.",al={"où est muln","où est le plateau de guette-ciel","destination de la lettre"}},{q="Que pense Muln de la lettre ?",a="Muln la trouve troublante et s’interroge sur ses références à un « Wild King » et à un « Pact ».",al={"réaction de muln","pourquoi troublante","que dit la lettre"}},{q="Qui Muln va-t-il consulter ?",a="Muln compte parler aux druides du Cercle cénarien.",al={"lettre du cercle cénarien","qui va-t-il consulter","conseil de druides ?"}}},fp="14,109,21.247.0,14.246.1,24.74.0,34.78.0,27.60.0,34.96.0,22.59.0"}
P.entries["quest:963"] = {n="Un amour éternel",s="À Auberdine, Cerellean Blanchegriffe vous demande d’apaiser les tourments d’Anaya Dawnrunner à Ameth'Aran. Son chagrin dure depuis la chute de la cité.",h="À Auberdine, Cerellean Blanchegriffe vous demande d’apaiser les tourments d’Anaya Dawnrunner à Ameth'Aran.",kw={"ameth'aran","anaya dawnrunner","pendentif d'anaya","auberdine","cerellean blanchegriffe","sombrivage","un amour éternel","grande fracture"},ang={["class:Druid"]="En tant que druide, vous voyez le prix personnel payé par ceux qui ont dormi des milliers d’années aux côtés de Shan'do Stormrage. Cerellean s’est réveillé dans un monde encore marqué par les pertes anciennes.",["faction:Alliance"]="En tant que héros de l’Alliance, vous voyez le chagrin que vos alliés elfes de la nuit portent depuis des millénaires, tandis qu’ils s’adaptent au monde éveillé.",["race:NightElf"]="En tant qu’elfe de la nuit de Sombrivage, vous voyez dans l’histoire de Cerellean les cicatrices durables de la Grande Fracture et de la chute de vos anciennes cités."},sec={{t="Un sommeil plein de chagrin",b="Il y a dix mille ans, la guerre des Anciens déchira Kalimdor autour du Puits d’éternité. Ameth'Aran tomba, et Anaya Dawnrunner fut arrachée à Cerellean Blanchegriffe. Accablé de chagrin, Cerellean rejoignit Shan'do Malfurion Hurlorage dans la longue hibernation des druides. Il espérait que les âges passés à parcourir le Rêve d’émeraude apaiseraient son cœur, mais son chagrin perdura."},{t="Le fantôme d’Ameth'Aran",b="À son réveil, Cerellean erra dans Sombrivage, hébété. Il finit par atteindre les ruines mélancoliques d’Ameth'Aran, où il aperçut le fantôme torturé d’Anaya. Il ne peut pas lever son arme contre la femme qu’il aimait. Il demande donc aux voyageurs de passage de détruire sa forme tourmentée, de récupérer son pendentif et d’apaiser son âme troublée."},{t="Un adieu derrière le voile",b="Quand le pendentif d’Anaya arrive à Auberdine, son vestige spectral apparaît une dernière fois devant Cerellean. Libérée de l’angoisse qui la retenait dans les ruines, Anaya lui fait brièvement ses adieux, puis s’évanouit. Au bord de la mer, le druide éploré pleure, mais trouve un réconfort doux-amer."}},faq={{q="Qui est Cerellean Blanchegriffe ?",a="Cerellean Blanchegriffe est un druide elfe de la nuit qui se repose à Auberdine. Après avoir perdu Anaya lors de la Grande Fracture, il y a dix mille ans, il entra dans la longue hibernation des druides avec Shan'do Malfurion Hurlorage. Son chagrin perdura à travers les âges.",al={"cerellean blanchegriffe","qui donne la quête un amour éternel","histoire de cerellean"}},{q="Qui était Anaya Dawnrunner ?",a="Anaya Dawnrunner était une elfe de la nuit qui vivait à Ameth'Aran avant la Grande Fracture. Elle mourut lorsque la cité tomba après la guerre des Anciens. Son fantôme reste prisonnier de ses ruines.",al={"anaya dawnrunner","qui est anaya","anaya à sombrivage"}},{q="Où se trouve l’esprit d’Anaya ?",a="L’esprit d’Anaya erre dans les ruines antiques d’Ameth'Aran, infestées de fantômes, au sud de Sombrivage, à l’est de la route principale.",al={"emplacement d’anaya","où se trouve anaya dawnrunner","emplacement du pendentif d’anaya"}},{q="Pourquoi Cerellean n’a-t-il pas pu libérer Anaya lui-même ?",a="Cerellean ne peut se résoudre à lever la main ni à lancer un sort contre l’apparition d’Anaya. Dix mille ans ont passé, mais il ne peut pas la frapper alors qu’elle souffre.",al={"pourquoi cerellean ne tue-t-il pas anaya","pourquoi cerellean demande de l’aide"}},{q="Qu’est-il arrivé à Ameth'Aran ?",a="Ameth'Aran était une ancienne cité des elfes de la nuit, détruite lors de la Grande Fracture qui suivit la guerre des Anciens. Ses ruines de Sombrivage abritent toujours des fantômes persistants et des échos arcaniques.",al={"histoire d’ameth'aran","chute d’ameth'aran","qu’est-ce qu’ameth'aran"}},{q="Que se passe-t-il quand vous rapportez le pendentif d’Anaya ?",a="Vous rapportez le pendentif d’Anaya à Cerellean, à Auberdine, après avoir libéré son âme troublée. La suite se révèle à votre retour.",al={"rendre la quête d’anaya","fin de cerellean","fin d’un amour éternel"}}},fx={dc23d6a3={q="Pourquoi Cerellean Blanchegriffe veut-il que l'esprit d'Anaya soit libéré ?",a="Cerellean croyait que son amour, Anaya, avait péri il y a des millénaires lorsque Ameth'Aran fut détruit pendant la Fracture. Découvrir son fantôme agité et tourmenté errant dans les ruines lui a brisé le cœur. Sachant qu'elle souffre, liée à ce royaume, il ne peut supporter l'idée qu'elle reste dans l'angoisse, mais il ne peut se résoudre à lever la main sur elle.",al={"pourquoi cerellean veut que cela soit fait","motif de cerellean","pourquoi détruire l'esprit d'anaya"}},ed60ea9d={q="À quoi sert le Pendentif d'Anaya ?",a="Le Pendentif d'Anaya est le souvenir que Cerellean vous demande de rapporter après avoir libéré son esprit troublé à Ameth'Aran.",al={"usage du pendentif d'anaya","à quoi sert le pendentif d'anaya","but du pendentif d'anaya"}}},fp="16,134,23.358.0,23.321.0,23.274.1,27.233.0,25.183.0,32.116.0,42.162.0,28.184.0,45.128.1"}
P.entries["quest:96339"] = {n="Legacy Reward: Replica Ironforge Air Rifle",s="Un colis à votre nom attendait chez un gardien jusqu’à ce que vous veniez le réclamer. Il contenait une Réplique de carabine à air comprimé de Forgefer, laissée par un messager inconnu.",h="Un colis à votre nom attendait chez un gardien jusqu’à ce que vous veniez le réclamer.",kw={"carabine à air comprimé","forgefer","carabine à air comprimé de forgefer","récompense de vétéran","colis mystérieux","réplique de carabine à air comprimé de forgefer"},ang={["profession:Engineering"]="Les bricoleurs et les armuriers apprécieront peut-être ce modèle d’arme à feu minutieusement ouvragé. Un messager indifférent l’a apporté, et il a failli finir au fond de l’océan.",["race:Dwarf"]="Le colis contient une réplique de carabine à air comprimé de Forgefer, en hommage aux armes à feu réputées et au savoir-faire mécanique de Khaz Modan."},sec={{t="Un colis à récupérer",b="Le gardien ne conservait rien et ne souhaitait pas garder le colis. Le messager a insisté sur le fait que vous viendriez le chercher, puis s’est empressé de partir avant que le gardien puisse refuser. Vous êtes arrivé juste avant que la boîte ne soit jetée à la mer avec les déchets du soir."},{t="L’ingénierie naine en miniature",b="Le colis contient une Réplique de carabine à air comprimé de Forgefer, hommage à l’art des armes à feu de la capitale naine. Les montagnards et tireurs d’élite nains portent des armes meurtrières à travers Dun Morogh. Ces répliques rappellent le travail minutieux des canons et les mécanismes pneumatiques perfectionnés par les artisans de Forgefer."}},faq={{q="Qui a envoyé ce colis ?",a="Le messager et l’expéditeur d’origine n’ont donné ni nom ni explication. Le gardien raconte que quelqu’un a laissé un colis à votre nom, assuré que vous viendriez le réclamer, puis a disparu avant qu’on puisse lui poser des questions.",al={"qui a envoyé le colis","expéditeur de la carabine à air comprimé","qui a laissé la carabine"}},{q="Qu’allait-il advenir du colis ?",a="Le colis a failli finir à la mer avec les ordures de la nuit. Le gardien a dit qu’il ne conservait rien et jetait régulièrement les objets encombrants dont personne ne voulait dans l’océan.",al={"qu’allait-il advenir du colis","ordures dans la mer","colis jeté"}},{q="Que contient le colis ?",a="Le colis contient une Réplique de carabine à air comprimé de Forgefer, laissée pour vous en hommage à la conception des armes à feu naines.",al={"que contient le colis","contenu de la carabine réplique","récompense dans le colis"}},{q="Pourquoi le gardien détenait-il le colis ?",a="Le gardien ne conserve ni courrier ni colis. Le messager est parti en hâte avant qu’on ait eu le temps de refuser la livraison.",al={"pourquoi l’a-t-on gardé","garder le courrier","cet endroit garde-t-il les colis"}},{q="Pourquoi est-ce une récompense de vétéran ?",a="Un bienfaiteur mystérieux a laissé un colis spécial pour un aventurier chevronné dans un avant-poste. Le colis l’y attendait jusqu’à son arrivée.",al={"pourquoi l’appeler récompense de vétéran","histoire de la récompense de vétéran","que signifie vétéran ici"}},{q="La carabine à air comprimé est-elle une arme fonctionnelle ?",a="Cette carabine est une réplique d’une carabine à air comprimé de Forgefer, inspirée des armes à distance naines finement ouvragées plutôt que d’un fusil de combat de première ligne.",al={"la carabine est-elle une vraie arme","peut-on tirer avec","fonctionnement de la réplique"}}},fp="42,168,29.255.0,32.291.0,22.195.0,36.168.0,26.103.0,42.125.0,39.132.0,41.142.0"}
P.entries["quest:96390"] = {n="Nip 'Em in the Bud",s="Les espions sombrefers se déplacent dans Dun Morogh, et le voyant de la terre Farsen appelle à l’aide. Près de la Base de Baguefer, leur présence menace la patrie des Barbe-de-bronze.",h="Les espions sombrefers se déplacent dans Dun Morogh, et le voyant de la terre Farsen appelle à l’aide.",kw={"carte sombrefer","espion sombrefer","dun morogh","voyant de la terre farsen","la salle des thanes","base de baguefer","nip 'em in the bud","underground map"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, arrêter les éclaireurs ennemis à Dun Morogh contribue à protéger les lignes de ravitaillement de Forgefer et les avant-postes voisins contre le sabotage.",["race:Dwarf"]="En tant que nain Barbe-de-bronze, chasser les espions sombrefers de vos montagnes ancestrales revient à défendre votre foyer et à répondre aux vieilles rancunes entre clans."},sec={{t="Des yeux dans le froid",b="Les espions sombrefers ont franchi les hauts cols et les crêtes enneigées de Dun Morogh. Ils se cachent près des colonies et des excavations, où quelques guetteurs peuvent annoncer une attaque. Le voyant de la terre Farsen voit le danger et appelle les défenseurs de l’Alliance à les retrouver avant que leurs plans n’avancent."},{t="Menace près de la Base de Baguefer",b="Les espions se rassemblent près de la Base de Baguefer, dans l’est de Dun Morogh. Le voyant de la terre Farsen ignore d’abord leur objectif. Fouiller les éclaireurs permet de trouver un Underground Map, preuve qu’ils préparent autre chose que la surveillance des environs. Leurs plans mènent vers d’antiques secrets souterrains, notamment la salle des Thanes."}},faq={{q="Qui confie la mission Nip 'Em in the Bud ?",a="Après avoir terminé Farsen's Watch, le voyant de la terre Farsen appelle à l’aide contre les intrus de Dun Morogh.",al={"donneur de quête nip 'em in the bud","qui lance nip 'em in the bud","quête de farsen"}},{q="Pourquoi les espions sombrefers sont-ils à Dun Morogh ?",a="Le clan des Sombrefers complote contre ses cousins Barbe-de-bronze. Ses espions surveillent les colonies de l’est de Dun Morogh et pourraient fouiller ou repérer des passages enfouis près de la Base de Baguefer.",al={"pourquoi les espions sombrefers sont ici","que font les sombrefers à dun morogh","espions sombrefers à la base de baguefer"}},{q="Où se trouvent les espions sombrefers ?",a="Les espions se rassemblent près de la Base de Baguefer, dans l’est de Dun Morogh, et surveillent les environs enneigés.",al={"emplacement des espions","où sont les espions sombrefers","où trouver les espions"}},{q="Quelle mission mène à cette tâche ?",a="Vous arrivez ici après avoir fait votre rapport pour Farsen's Watch. Les défenses passent de la surveillance des intrus à leur traque.",al={"quête prérequise","quelle quête précède nip 'em in the bud","quête prérequise pour nip 'em in the bud"}},{q="Que découvre-t-on en traquant ces espions ?",a="Les espions tombés au combat portent une Carte sombrefer. Elle montre que leurs plans s’étendent sous terre, vers des secrets liés à la salle des Thanes.",al={"butin des espions","carte sombrefer butin","quête suivante après nip 'em in the bud"}},{q="Qui est le voyant de la terre Farsen ?",a="Le voyant de la terre Farsen est un nain de Dun Morogh qui surveille l’activité sismique inhabituelle et les mouvements hostiles des clans dans les montagnes.",al={"qui est farsen","histoire du voyant de la terre farsen"}}},fx={bdd12e65={q="Pourquoi le Voyant de terre Farsen veut-il que l'on s'occupe des espions sombrefer ?",a="Le Voyant de terre Farsen sait que toute tête de pont sombrefer à Dun Morogh signifie un danger pour Forgefer et les terres environnantes. Bien que leurs motifs précis restent flous pour lui, laisser des infiltrés agir sans entrave invite à un sabotage plus important ou à un assaut ouvert. Il veut écraser leur présence immédiatement avant que le complot qu'ils préparent ne prenne racine.",al={"pourquoi farsen veut les espions morts","motif du voyant de terre farsen","pourquoi l'opération dans l'œuf"}}},fp="18,154,16.267.0,31.310.1,40.98.0,38.177.0,38.99.0,26.113.0,44.122.1,24.127.0"}
P.entries["quest:96391"] = {n="Underground Map",s="Près de la Base de Baguefer, l’Underground Map indique des salles sous Forgefer. Récupérées sur des espions sombrefers, ses runes tracent un passage secret vers d’antiques salles sous la montagne. Vous l’apportez à Earthseer Farsen pour découvrir ce qui se cache en dessous.",h="Près de la Base de Baguefer, l’Underground Map indique des salles sous Forgefer.",kw={"carte sombrefer","dun morogh","earthseer farsen","la salle des thanes","base de baguefer","forgefer","underground map"},ang={["class:Shaman"]="En tant que chaman, vous pouvez entendre dans la rafale qui vous guide vers Earthseer Farsen un avertissement des esprits élémentaires. Ils sentent des travaux de creusement anormaux sous Dun Morogh.",["faction:Alliance"]="En tant que membre de l’Alliance, vous savez qu’il faut bloquer cette route souterraine pour protéger Forgefer et l’ancrage septentrional de l’Alliance.",["race:Dwarf"]="En tant que nain Barbe-de-Bronze, vous savez que des tunnels sombrefers qui s’approchent directement des fondations de Forgefer constituent une grave violation des frontières de la capitale."},sec={{t="Un plan d’infiltration",b="Vous trouvez le parchemin près de la Base de Baguefer après avoir affronté des espions sombrefers. Ses schémas révèlent un dédale complexe de routes sous la terre. Des runes rudes et dentelées marquent des passages qui s’enfoncent profondément sous terre et convergent sous Forgefer. Leur tracé suggère une menace possible sous la capitale des Barbe-de-Bronze, bien que les notes sombrefers restent incertaines."},{t="Des murmures dans le vent",b="Tandis que vous étudiez cette carte sommaire, une rafale surnaturelle porte le faible murmure d’une voix naine. Elle vous presse d’agir vite et vous indique Earthseer Farsen. Vous lui apportez cet avertissement, qui pourrait révéler les premiers mouvements vers d’antiques salles scellées au plus profond de la ville et menacer le sanctuaire du royaume de la montagne."}},faq={{q="D’où vient cette carte souterraine ?",a="Des espions sombrefers transportaient la carte tandis qu’ils surveillaient le périmètre de la Base de Baguefer, à Dun Morogh. Vous la trouvez parmi leurs éclaireurs dans les contreforts.",al={"butin de carte","où trouver la carte","comment obtenir l’underground map"}},{q="Que montre la carte ?",a="La carte montre un réseau complexe de routes et de tunnels souterrains qui serpentent sous la terre. Ils convergent sous Forgefer.",al={"que contient la carte","détails de la carte","utilité de la carte sombrefer"}},{q="Qui est Earthseer Farsen ?",a="Earthseer Farsen est un nain qui lit la terre et vient du Nid-de-l’Aigle. Il est en harmonie avec les roches profondes et les esprits de la montagne. Il perçoit les mouvements anormaux sous terre et a besoin de la carte pour évaluer la brèche sous Forgefer.",al={"où se trouve farsen","qui est farsen","lecteur de la terre"}},{q="Pourquoi les Sombrefers creusent-ils sous Forgefer ?",a="La carte suggère un passage possible sous Forgefer, mais ses notes sombrefers restent indéchiffrées. Earthseer Farsen doit l’examiner avant que leur plan puisse être établi.",al={"pourquoi les sombrefers creusent","complot sombrefer à dun morogh"}},{q="À quoi mène cette quête ?",a="Apporter la carte à Earthseer Farsen lance une enquête sur les profondeurs sous la ville. Elle mène à l’incursion dans le Vieux Forgefer et ouvre un passage vers la salle des Thanes.",al={"suite de l’underground map","quête suivante après underground map"}},{q="Dans quelle langue les runes de la carte sont-elles écrites ?",a="La carte porte l’écriture runique dentelée des nains sombrefers. Quiconque la trouve ne peut pas être certain du sens des notes.",al={"runes de la carte","langue sombrefer"}}},fx={["1c73103d"]={q="Pourquoi la Carte sombrefer doit-elle être apportée au Voyant de terre Farsen ?",a="La carte détaille un réseau alarmant de tunnels et de routes souterraines convergeant directement sous Forgefer. Ses runes sombrefer dentelées nécessitent une traduction, et l'étrange voix naine portée par le vent indique clairement que le Voyant de terre Farsen doit inspecter immédiatement la menace souterraine potentielle pour avertir le royaume de la montagne.",al={"pourquoi apporter la carte à farsen","motif de la carte sombrefer","pourquoi livrer la carte"}}},fp="15,270,27.360.0,20.309.1,41.148.0,23.127.0,24.205.0,49.168.0,29.182.1,45.115.0"}
P.entries["quest:96392"] = {n="Farsen's Watch",s="Près de la Carrière de Gol'Bolar, le prophète de la terre Farsen surveille les mouvements des Sombrefer près de Forgefer. Le chaman Wildhammer vous prête sa double-vue et révèle une menace qui appelle une action rapide.",h="Près de la Carrière de Gol'Bolar, le prophète de la terre Farsen surveille les mouvements des Sombrefer près...",kw={"nid-de-l’aigle","sombrefer","dun morogh","prophète de la terre","farsen","double-vue","gol'bolar","la salle des thanes","wildhammer"},ang={["class:Shaman"]="En tant que chaman, vous assistez à la vision tellurique et spirituelle de la tradition Wildhammer, enracinée dans les crêtes de Nid-de-l’Aigle.",["faction:Alliance"]="En tant que voyageur de l'Alliance, vous contribuez à découvrir les complots des Sombrefer à Dun Morogh et à protéger Forgefer ainsi que les cols environnants.",["race:Dwarf"]="En tant que défenseur Bronzebeard, vous recevez l'avertissement d'un cousin de Nid-de-l’Aigle. Il révèle à quel point les Sombrefer sont devenus audacieux dans votre patrie."},sec={{t="Des yeux sur la crête",b="Depuis son poste au-dessus de la Carrière de Gol'Bolar, Farsen surveille les basses terres de Dun Morogh. Il est venu du sud, des crêtes de Nid-de-l’Aigle, avec la sensibilité spirituelle des Wildhammer. Les arts anciens de son clan lui permettent de sentir les secousses souterraines et de guetter les mouvements soudains sur les flancs des collines."},{t="Une vision prêtée",b="Farsen vous prête sa double-vue, un don chamanique qui porte le regard au loin. Vous y découvrez un danger qui dépasse les troggs et les bêtes sauvages. Des nains Sombrefer se sont approchés du centre industriel de Forgefer et y creusent des positions. Il faut les déloger avant qu'ils ne s'enracinent."}},faq={{q="Qui est le prophète de la terre Farsen ?",a="Le prophète de la terre Farsen est un nain Wildhammer venu de Nid-de-l’Aigle, dans les Hinterlands, et de passage à Dun Morogh. Son don chamanique lui permet de sentir les perturbations du sol et de guetter les menaces au loin.",al={"prophète de la terre farsen","qui est farsen","farsen wildhammer"}},{q="Où se déroule cette veille ?",a="Farsen veille depuis les hauteurs de la Carrière de Gol'Bolar, une mine Bronzebeard à l'est de Dun Morogh.",al={"emplacement de farsen","où se trouve farsen","vue sur la carrière"}},{q="Quelle menace Farsen révèle-t-il ?",a="La double-vue de Farsen révèle un avant-poste proche de nains Sombrefer hostiles, qui représentent un danger immédiat pour la région.",al={"que révèle la double-vue","menace des sombrefer","vision de farsen"}},{q="Quel est le lien avec La salle des Thanes ?",a="Enquêter sur la présence des Sombrefer aperçue pendant la veille de Farsen lance la suite de tâches destinée à ceux qui cherchent à entrer dans La salle des Thanes.",al={"harmonisation de la salle des thanes","suite de quêtes de la salle des thanes"}},{q="Pourquoi un nain Wildhammer participe-t-il à la défense de Dun Morogh ?",a="Les Wildhammer ont élu domicile dans les Hinterlands, mais les liens de parenté et leur hostilité commune envers les Sombrefer amènent parfois des voyageurs comme Farsen dans les terres ancestrales des Bronzebeard, à Dun Morogh.",al={"pourquoi un wildhammer est ici","nain de nid-de-l’aigle à dun morogh"}},{q="Que se passe-t-il juste après avoir terminé Le guet de Farsen ?",a="Après vous avoir fait voir l'infiltration des Sombrefer grâce à sa vision, Farsen vous presse de repousser l'ennemi qui gagne du terrain avec « Nip 'Em in the Bud ».",al={"quête suivante","que faire après le guet de farsen","nip 'em in the bud"}}},fx={["73fc96dc"]={q="Pourquoi le Voyant de terre Farsen veut-il que cela soit fait ?",a="Alors qu'il traversait Dun Morogh depuis Nid-de-l’Aigle, le Voyant de terre Farsen a repéré des signes d'agression de nains sombrefer empiétant près de la Carrière de Gol'Bolar. Avant d'agir ou de donner l'alerte, le chaman souhaite que vous soyez témoin du danger qui couve grâce à sa magie de prescience, en vous assurant que les défenseurs de Forgefer saisissent la véritable ampleur de l'infiltration hostile avant qu'elle ne devienne incontrôlable.",al={"pourquoi le guet de farsen","motif de farsen","pourquoi farsen veut que je regarde"}}},fp="14,184,21.288.0,17.291.0,24.181.0,33.98.0,31.105.0,44.136.0,59.184.0,52.143.0"}
P.entries["quest:96393"] = {n="Old Ironforge Incursion",s="Sous Forgefer, Earthseer Farsen vous envoie dans la salle des Thanes pour la dernière partie de l’enquête. Là, vous affrontez la menace des Sombrefer et faites votre rapport au Roi Magni Barbe-de-Bronze.",h="Sous Forgefer, Earthseer Farsen vous envoie dans la salle des Thanes pour la dernière partie de l’enquête.",kw={"sombrefer","dirgehammer","farsen","incursion","forgefer","kharanos","magni","thanes"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous contribuez à arrêter une incursion qui menace votre faction d’une attaque surprise dévastatrice contre son principal bastion dans les Royaumes de l’est.",["race:Dwarf"]="En tant que nain, vous savez que des infiltrateurs sombrefer ont violé votre forteresse ancestrale, dans les caveaux oubliés sous le Haut Siège."},sec={{t="Forcer les caveaux",b="La carte souterraine révèle les mouvements des Sombrefer, et Earthseer Farsen identifie le cerveau de l’intrusion. L’entrée de la salle des Thanes se trouve au plus profond des antiques salles de pierre du Vieux Forgefer. Tandis que la ville haute s’occupe des affaires de la surface, les forces sombrefer se glissent dans les cavernes endormies sous le royaume."},{t="Le commandant Durgen Dirgehammer",b="Earthseer Farsen traduit les documents sombrefer saisis et nomme leur commandant : Durgen Dirgehammer. Au plus profond des caveaux inférieurs, Durgen menace le cœur du royaume montagnard des Bronzebeard. Rejoignez-le, abattez-le et apportez sa tête tranchée au Roi Magni Barbe-de-Bronze, dans la ville haute."},{t="Audience avec le roi",b="La tête de Durgen Dirgehammer confirme au Roi Magni Barbe-de-Bronze la menace des Sombrefer sous les antiques fondations de la cité. Vous apportez la preuve de votre victoire et les salutations personnelles de Farsen, un vieil ami de Magni. L’enquête s’achève, et Magni sait désormais ce qui rôde dans les profondeurs."}},faq={{q="Qu’est-ce que Old Ironforge Incursion ?",a="Earthseer Farsen vous envoie dans la salle des Thanes, sous le Vieux Forgefer, pour affronter le commandant sombrefer, Durgen Dirgehammer. C’est la dernière étape d’une enquête sur les activités des Sombrefer sous Dun Morogh.",al={"quête old ironforge incursion","quête durgen dirgehammer"}},{q="Où se déroule cette quête ?",a="Vous entrez dans la salle des Thanes, une antique chambre creusée profondément dans le socle rocheux, sous le Vieux Forgefer et la capitale montagnarde.",al={"où se trouve la salle des thanes","emplacement de la salle des thanes"}},{q="Qui est Durgen Dirgehammer ?",a="Durgen Dirgehammer commande l’incursion des Sombrefer dans la salle des Thanes, sous le Vieux Forgefer. Earthseer Farsen a appris son nom grâce aux documents sombrefer récupérés.",al={"qui est dirgehammer","durgen dirgehammer"}},{q="Qui donne la quête et à qui la rendre ?",a="Après avoir récupéré l’Underground Map, Earthseer Farsen vous envoie auprès du Roi Magni Barbe-de-Bronze, à Forgefer.",al={"qui donne old ironforge incursion","à qui rendre old ironforge incursion"}},{q="Comment commencer la suite de quêtes qui mène à celle-ci ?",a="Commencez par A Visitor to Dun Morogh, proposée par Beldin Grillacier à l’extérieur de Kharanos, dans Dun Morogh.",al={"comment commencer la quête de la salle des thanes","début de a visitor to dun morogh"}},{q="Quel est le lien entre Earthseer Farsen et le roi Magni ?",a="Earthseer Farsen considère le Roi Magni Barbe-de-Bronze comme un vieil ami. Il vous demande de lui transmettre ses salutations personnelles lorsque vous présenterez la tête de Durgen Dirgehammer dans la salle du trône.",al={"farsen et magni","histoire d’earthseer farsen"}}},fx={bdae81a8={q="Pourquoi le Voyant de terre Farsen veut-il que Durgen Dirgehammer soit tué ?",a="Farsen a découvert des mouvements ennemis sous la montagne et a déchiffré des ordres désignant Durgen Dirgehammer comme le commandant menant l'incursion dans le Vieux Forgefer. La présence sombrefer dans La salle des Thanes menace directement la capitale naine depuis les profondeurs. En vous envoyant abattre leur chef, Farsen vise à briser l'assaut avant que les sombrefer ne puissent s'y retrancher, tout en envoyant une preuve indéniable de la menace directement au Roi Magni Bronzebeard.",al={"motif de farsen","pourquoi tuer durgen dirgehammer","pourquoi farsen vous envoie"}},["664606f0"]={q="À quoi sert la Tête de Durgen Dirgehammer ?",a="Vous avez besoin de la Tête de Durgen Dirgehammer comme preuve absolue pour le Roi Magni Bronzebeard que le commandant de l'assaut souterrain a été mis hors d'état de nuire. Livrer ce macabre trophée directement dans la salle du trône confirme que la force d'intervention hostile sombrefer dans La salle des Thanes a perdu son chef et porte l'avertissement personnel du Voyant de terre Farsen au roi.",al={"usage de la tête de durgen dirgehammer","pourquoi prendre la tête de durgen","tête de durgen dirgehammer"}}},fp="23,182,20.333.0,18.279.1,22.260.1,32.210.0,33.116.0,26.168.0,41.105.0,50.96.0,63.179.0"}
P.entries["quest:96394"] = {n="The Restless Dead",s="Sous la salle des Thanes, des esprits agités troublent les cryptes où reposent des générations de nains défunts. Les gardiens craignent d’entrer dans les caveaux, et le trouble a atteint l’esprit de Courbenclume.",h="Sous la salle des Thanes, des esprits agités troublent les cryptes où reposent des générations de nains...",kw={"courbenclume","tombes naines","esprits nains","enraged apparitions","fantômes","la salle des thanes","esprit de courbenclume","the restless dead","tormented souls"},ang={["class:Priest"]="En tant que prêtre, vous êtes appelé à communier avec les âmes et à guider les morts tourmentés vers le repos lorsque des esprits s’attardent dans la souffrance ou la colère.",["faction:Alliance"]="En tant que membre de l’Alliance, vous aidez à sécuriser les cryptes ancestrales sous Forgefer afin que les gardiens puissent accomplir leurs devoirs sacrés sans craindre les apparitions vengeresses.",["race:Dwarf"]="En tant que nain, vous savez que la salle des Thanes abrite les ancêtres et les défunts honorés de votre peuple. Leur brusque agitation violente ébranle le cœur du patrimoine nain."},sec={{t="Trouble dans les caveaux profonds",b="Des générations de nains honorés reposent dans les cryptes ancestrales sous la salle des Thanes. Leurs esprits dorment généralement en paix, mais une présence invisible les a violemment agités. D’étranges bruits montent des caveaux inférieurs et effraient les gardiens. Ils refusent d’entrer dans ces salles ou d’accomplir leurs tâches tant que l’ordre n’est pas rétabli. Des aventuriers sont désormais appelés à apaiser les âmes agitées."},{t="Apaiser les ancêtres",b="Les esprits de la salle des Thanes ont le sommeil léger. Ce qui a troublé les tombes inférieures a réveillé des Enraged Apparitions et des Tormented Souls, transformant un lieu sacré en repaire périlleux. Le vénérable esprit de Courbenclume s’est également éveillé. Une main respectueuse mais ferme doit apaiser la fureur des ancêtres et ramener la paix dans les catacombes."}},faq={{q="En quoi consiste la quête The Restless Dead ?",a="Un trouble inconnu a agité les esprits dans les cryptes sous la salle des Thanes. Les gardiens craignent d’y entrer tant que les apparitions restent agitées.",al={"que sont les morts agités","en quoi consiste cette quête","résumé de la quête the restless dead"}},{q="Pourquoi les esprits se sont-ils réveillés ?",a="Un trouble inconnu dans les caveaux profonds a réveillé les morts ensevelis. Les esprits de la salle des Thanes ont le sommeil léger, et ce qui s’est passé dans les tombes les a plongés dans la rage et le tourment.",al={"pourquoi les fantômes sont-ils en colère","qui a troublé les tombes","pourquoi les apparitions sont-elles réveillées"}},{q="Où se produit ce trouble ?",a="Le trouble sévit dans les cryptes et les caveaux sous la salle des Thanes de Forgefer, un lieu de repos ancestral où sont ensevelis les anciens esprits nains.",al={"où se trouve la salle des thanes","où apparaissent les morts agités","emplacement de la salle des thanes"}},{q="Qui est l’esprit de Courbenclume ?",a="Courbenclume est un ancien esprit éminent qui repose dans les tombes profondes de la salle des Thanes. Ce grand esprit s’est éveillé avec des apparitions moins importantes et doit retrouver le repos paisible.",al={"qui est l’esprit de courbenclume","histoire de l’esprit de courbenclume","qui est le fantôme de courbenclume"}},{q="Pourquoi les gardiens ont-ils besoin de l’aide d’un aventurier ?",a="Les gardiens veillent sur les cryptes et accomplissent leurs tâches habituelles dans la salle des Thanes. Des esprits furieux parcourent les couloirs, alors les gardiens refusent d’entrer dans les caveaux inférieurs tant que le danger persiste.",al={"qui sont les gardiens","pourquoi les gardiens ont-ils besoin d’aide","gardiens de la salle des thanes"}},{q="Quels esprits hantent la salle des Thanes ?",a="Des Enraged Apparitions, des Tormented Souls et le grand esprit de Courbenclume hantent les caveaux troublés. Tous ont été tirés de leur torpeur et veillent désormais avec agressivité dans les salles funéraires.",al={"quels types de fantômes se trouvent là-bas","apparitions dans la salle des thanes","types de morts agités"}}},fp="17,207,30.381.0,22.328.1,38.153.0,30.187.0,39.152.0,30.182.0,45.190.0,38.169.0"}
P.entries["quest:96395"] = {n="An Ancient Grudge",s="Dans la salle des Thanes, l’esprit de Faldrim Anvilmar reste tourmenté par une vieille rancune. Son serviteur fantomatique demande aux voyageurs de lui apporter la paix.",h="Dans la salle des Thanes, l’esprit de Faldrim Anvilmar reste tourmenté par une vieille rancune.",kw={"rancune ancestrale","courbenclume","fantôme nain","faldrim anvilmar","serviteur fantomatique","la salle des thanes","esprit agité","thane"},ang={["class:Paladin"]="En tant que paladin, vous assumez le devoir solennel d’apporter la paix aux morts qui souffrent.",["class:Priest"]="En tant que prêtre, vous savez que les rancunes persistantes et les chagrins non apaisés peuvent lier un esprit au monde physique, longtemps après que le corps est réduit en poussière.",["race:Dwarf"]="En tant que nain, vous voyez là un rappel solennel qu’une rancune ancestrale peut survivre à la mort elle-même."},sec={{t="Une supplique venue de la tombe",b="Un serviteur fantomatique demeure dans la salle des Thanes, où Faldrim Anvilmar régnait autrefois. L’esprit peine à se faire entendre par-delà le voile qui sépare les vivants des morts. Il vous demande d’apaiser l’esprit agité de son maître. Il souhaite que celui-ci trouve la paix, pas être libéré lui-même."},{t="Le poids du passé",b="Faldrim Anvilmar reste lié au monde physique par une rancune ancestrale. Son fantôme est agité et hostile. Il ne peut trouver le repos tant que quelqu’un ne lui a pas accordé une délivrance par la force."}},faq={{q="Qui est Faldrim Anvilmar ?",a="Faldrim Anvilmar était un thane nain dont le fantôme agité hante la salle des Thanes. Son serviteur fantomatique dit qu’une rancune ancestrale le consume et l’empêche de trouver le repos.",al={"histoire de faldrim anvilmar","qui est faldrim","thane courbenclume"}},{q="Où se trouve la salle des Thanes ?",a="La salle des Thanes se trouve dans les cavernes sous le Vieux Forgefer, au cœur de la capitale naine de Forgefer.",al={"emplacement de la salle des thanes","où se trouve la salle des thanes","entrée de la salle des thanes"}},{q="Pourquoi le fantôme de Faldrim Anvilmar est-il hostile ?",a="Le fantôme de Faldrim Anvilmar est hostile, car une rancune ancestrale le consume. Son serviteur fantomatique dit que ce grief empêche l’ancien thane de trouver le repos.",al={"pourquoi faldrim est-il en colère","pourquoi le thane attaque-t-il","explication de la rancune ancestrale"}},{q="Qui donne la quête An Ancient Grudge ?",a="Un serviteur fantomatique, dans la salle des Thanes, vous demande d’apporter la paix à son ancien maître.",al={"qui lance rancune ancestrale","quête du serviteur fantomatique","donneur de quête"}},{q="Que devez-vous faire pour terminer la quête ?",a="Vous affrontez le fantôme de Faldrim Anvilmar dans la salle des Thanes et le vainquez au combat pour le délivrer de son tourment. Puis vous faites votre rapport au serviteur fantomatique.",al={"comment terminer rancune ancestrale","apaiser faldrim","objectif de rancune ancestrale"}},{q="Faldrim est-il lié à la ville de Courbenclume ?",a="Nul ne sait si Faldrim Anvilmar a un lien de parenté avec la ville de Courbenclume, dans la Vallée des Frigères. Ils portent le même nom, mais on ignore tout de sa famille et de ses liens éventuels avec la ville.",al={"faldrim vient-il de courbenclume","lien entre courbenclume et la vallée des frigères","famille courbenclume"}}},fp="17,147,21.261.0,22.169.1,24.167.0,36.98.0,45.151.0,38.91.0,39.160.0,43.164.0"}
P.entries["quest:96403"] = {n="Important Heirlooms",s="Dans la salle des Thanes, des nains Sombrefer s’introduisent dans les caveaux tandis que Thom se retrouve piégé à l’intérieur. Le gnome nerveux vous demande de rassembler les reliques naines éparpillées avant que les envahisseurs ne les atteignent.",h="Dans la salle des Thanes, des nains Sombrefer s’introduisent dans les caveaux tandis que Thom se retrouve...",kw={"sombrefer","héritages nains","gnome","la salle des thanes","important heirlooms","engin de forage souterrain","thom","caveaux"},ang={["class:Rogue"]="En tant que voleur, vous voyez clair dans les affirmations de Thom, qui prétendait patrouiller dans les caveaux. C’est un pilleur pris au dépourvu par une invasion souterraine.",["race:Dwarf"]="En tant que nain, vous pouvez douter de l’intérêt soudain de Thom pour les reliques ancestrales, puisqu’il revient sans cesse au butin et à son estimation.",["race:Gnome"]="En tant que gnome, vous voyez dans le piètre prétexte de Thom comment la curiosité peut se tourner vers de précieuses reliques."},sec={{t="Des ennuis dans les caveaux",b="Thom est un gnome pris au piège dans la salle des Thanes lorsque des nains Sombrefer creusent jusqu’à elle à bord d’engins de forage souterrains. Incapable de sécuriser seul les caveaux, il demande aux aventuriers de passage d’entrer dans le site de fouilles hostile. Les reliques naines sont éparpillées dans les salles. Les envahisseurs pourraient s’en emparer ou les détruire."},{t="Préserver la culture ou piller un trésor ?",b="Thom affirme qu’il patrouillait et veut cataloguer les reliques pour les préserver. Pourtant, il laisse échapper des propos sur un butin inestimable et sur l’estimation de sa prise. Il vous paie bien pour affronter le danger, mais on ignore si les trésors finiront dans un musée ou aux enchères."}},faq={{q="Qui est Thom ?",a="Thom est un gnome nerveux près des caveaux qui demande de l’aide pour récupérer des reliques. Ses écarts sur le butin et son estimation laissent penser que le pillage l’intéresse davantage que la sécurité des caveaux.",al={"qui donne la quête","qui est thom","donneur de quête"}},{q="Qu’est-ce que la salle des Thanes ?",a="La salle des Thanes est un caveau souterrain nain qui abrite d’anciennes reliques culturelles et des héritages. Les forces Sombrefer y ont fait irruption.",al={"qu’est-ce que la salle des thanes","où se trouve la salle des thanes"}},{q="Pourquoi des nains Sombrefer sont-ils dans les caveaux ?",a="Des nains Sombrefer ont creusé jusqu’aux caveaux depuis les profondeurs à bord d’engins de forage souterrains. Leur objectif est inconnu.",al={"pourquoi les sombrefer sont-ils là","engins de forage souterrains sombrefer"}},{q="Thom va-t-il vraiment rendre les héritages ?",a="Thom dit qu’il rendra les reliques à des lieux d’honneur, mais ses paroles éveillent les soupçons. Il parle de rôder et de cataloguer comme d’une estimation, et évoque un butin et une prise.",al={"thom ment-il","thom vole-t-il","peut-on faire confiance à thom"}},{q="Que sont les Dwarven Heirlooms ?",a="Les Dwarven Heirlooms sont d’anciennes reliques culturelles conservées dans la salle des Thanes. Les historiens les tiennent en grande estime, tandis que des opportunistes comme Thom y voient un précieux butin.",al={"que sont les héritages","histoire des héritages nains"}},{q="Pourquoi Thom ne peut-il pas récupérer les héritages lui-même ?",a="Les engins de forage souterrains Sombrefer ont pris Thom par surprise alors qu’il rôdait dans les caveaux. Il ne peut pas rassembler les reliques sans la protection d’un aventurier.",al={"pourquoi thom a-t-il besoin d’aide","pourquoi aider thom"}}},fp="19,189,21.287.0,43.264.1,12.166.0,27.132.0,40.97.0,39.165.0,31.151.0,46.152.0"}
P.entries["quest:96408"] = {n="A Visitor to Dun Morogh",s="Beldin Grillacier vous envoie découvrir qui a allumé un feu au-dessus de la Carrière de Gol'Bolar. Le camp surplombe l’excavation, et les nains craignent que son visiteur leur veuille du mal.",h="Beldin Grillacier vous envoie découvrir qui a allumé un feu au-dessus de la Carrière de Gol'Bolar.",kw={"beldin grillacier","dun morogh","voyant de la terre farsen","farsen's watch","carrière de gol'bolar","la salle des thanes","kharanos","visiteur"},ang={["class:Shaman"]="En tant que chaman, vous rencontrez le voyant de la terre Farsen, dont le lien avec les pierres de la montagne est rare dans les hautes terres enneigées de Dun Morogh.",["faction:Alliance"]="En tant que membre de l’Alliance, vous aidez les Montagnards près de Kharanos à protéger les voies d’approvisionnement et les ouvriers de la carrière contre les menaces imprévues.",["race:Dwarf"]="En tant que nain Barbe-de-bronze, vous savez pourquoi les Montagnards surveillent les inconnus au-dessus des grands sites miniers comme la Carrière de Gol'Bolar. Ils défendent les frontières de Khaz Modan."},sec={{t="Un panache de fumée sur les hauteurs",b="Sur les crêtes enneigées à l’est de Kharanos, le feu de camp d’un inconnu brûle au-dessus de la carrière. Ce feu inhabituel inquiète les habitants de Kharanos. Les Montagnards y surveillent les hauteurs pour repérer tout danger."},{t="À la rencontre du voyant de la terre",b="Le voyant de la terre Farsen a installé son camp sur les hauteurs au-dessus de la Carrière de Gol'Bolar. C’est un mystique profondément lié à la terre, et non un trogg maraudeur ni un espion hostile. Sa veille le conduit à s’intéresser aux troubles sous Khaz Modan et au mystère de la salle des Thanes."}},faq={{q="Qui vous envoie enquêter sur le visiteur ?",a="Beldin Grillacier, près de Kharanos, vous demande d’enquêter après que des Montagnards ont signalé un feu inhabituel dans les collines.",al={"qui donne cette quête","début de quête","quête de beldin grillacier"}},{q="Où se trouve le mystérieux campement ?",a="Le feu de camp brûle sur les crêtes enneigées à l’est de Kharanos, au-dessus de la Carrière de Gol'Bolar.",al={"emplacement du camp","où se trouve le visiteur","lieu du visiteur"}},{q="Qui est le visiteur qui surplombe la carrière ?",a="Le voyant de la terre Farsen est le visiteur qui campe sur les hauteurs au-dessus de la carrière et la surveille.",al={"qui est farsen","qui est le visiteur","voyant de la terre farsen"}},{q="Pourquoi les nains se méfiaient-ils du feu de camp ?",a="Les nains se méfient de ce camp inconnu, car il surplombe la Carrière de Gol'Bolar, un site essentiel déjà menacé par les troggs des environs. Ils craignent que des éclaireurs ou des forces hostiles n’observent leurs déplacements.",al={"pourquoi se méfier","pourquoi enquêter","pourquoi m’envoyer"}},{q="À quoi cette quête mène-t-elle ?",a="Parler au voyant de la terre Farsen vous mène à Farsen's Watch et lance la suite de quêtes d’harmonisation de la salle des Thanes.",al={"what comes next","quête suivante","introduction à la salle des thanes"}},{q="Faut-il combattre l’inconnu au camp ?",a="Non. Beldin Grillacier vous conseille de vous tenir prêt à la violence, mais le voyant de la terre Farsen est un observateur pacifique disposé à vous parler.",al={"le visiteur est-il hostile","dois-je tuer le visiteur","combat contre le visiteur"}}},fx={["3b0d76fb"]={q="Pourquoi Beldin Grillacier demande-t-il à un aventurier plutôt qu'aux Montagnards ?",a="Les Montagnards locaux ont repéré le feu de camp sur le flanc de la colline de loin, mais leurs rangs sont trop dispersés pour garder les routes, les colonies et les opérations de carrière contre les troggs et les bêtes sauvages. Comme le feu est probablement inoffensif, Beldin compte sur un voyageur capable passant par Kharanos pour inspecter rapidement la crête plutôt que de retirer des gardes de leur service actif.",al={"pourquoi m'envoyer","pourquoi ne pas envoyer de gardes","pourquoi beldin grillacier m'a choisi"}}},fp="23,167,28.196.0,21.242.1,41.119.0,41.85.0,42.89.1,48.207.0,31.102.1,46.135.1"}
P.entries["quest:965"] = {n="La Tour d'Althalaxx",s="Au nord d’Auberdine, la Sentinelle Elissa Brise-stellaire craint qu’un danger menace une ruine antique. Elle a envoyé Balthule Frappelombre surveiller la Tour d’Althalaxx, mais il n’a pas donné de nouvelles.",h="Au nord d’Auberdine, la Sentinelle Elissa Brise-stellaire craint qu’un danger menace une ruine antique.",kw={"althalaxx","auberdine","balthule frappelombre","sombrivage","elissa brise-stellaire","éclaireur","sentinelle","tour"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous comptez sur Auberdine, principale porte d’entrée de l’Alliance vers le nord de Kalimdor. Les routes et les frontières alentour doivent être protégées.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous savez que les ruines d’Althalaxx rappellent les Bien-nés déchus de l’antique Kalimdor. La corruption s’insinue dans leurs pierres, et les sentinelles ont le devoir essentiel de protéger Auberdine contre elle."},sec={{t="Un éclaireur introuvable",b="La Sentinelle Elissa Brise-stellaire veille aux dangers qui menacent Auberdine. Une activité suspecte près de la Tour d’Althalaxx, dans le nord de Sombrivage, a attiré son attention. Elle a donc envoyé Balthule Frappelombre surveiller cette ruine antique. Des jours ont passé sans nouvelles. Elissa vous demande d’aller vers le nord, de retrouver Balthule et de vérifier qu’il n’a pas connu une fin prématurée."},{t="Des yeux sur la ruine",b="La route au nord d’Auberdine passe devant d’antiques ruines kaldorei et traverse la Bondissante avant d’atteindre la tour. Balthule a survécu à sa première surveillance, mais n’a pas pu donner de nouvelles à Auberdine. Vous le trouvez dans les bois environnants. Il confirme alors les craintes d’Elissa : des événements sombres et inquiétants se déroulent dans la flèche de pierre croulante."}},faq={{q="Qui est la Sentinelle Elissa Brise-stellaire ?",a="La Sentinelle Elissa Brise-stellaire est une sentinelle elfe de la nuit en poste à Auberdine. Elle protège la colonie contre les dangers de Sombrivage et veille aux menaces telles que la Tour d’Althalaxx.",al={"elissa brise-stellaire","qui donne la quête","donneur de quête à auberdine"}},{q="Qui est Balthule Frappelombre ?",a="Balthule Frappelombre est l’éclaireur que la Sentinelle Elissa Brise-stellaire a envoyé surveiller l’activité étrange autour de la Tour d’Althalaxx. Il observe la ruine depuis l’extérieur afin de repérer les forces hostiles.",al={"balthule","qui est l’éclaireur","frappelombre"}},{q="Où se trouve la Tour d’Althalaxx ?",a="La Tour d’Althalaxx se dresse au nord-est de Sombrivage. Depuis Auberdine, allez vers l’est et suivez la route du nord au-delà de Bashal’Aran. Traversez ensuite le pont au-dessus de la Bondissante jusqu’à ce que la flèche apparaisse.",al={"emplacement de la tour d’althalaxx","où se trouve la tour","comment trouver althalaxx"}},{q="Pourquoi envoyer un éclaireur à la tour ?",a="Elissa a envoyé Balthule surveiller l’activité étrange autour de la Tour d’Althalaxx dans le cadre de son devoir de protection d’Auberdine.",al={"pourquoi surveiller la tour","que se passe-t-il à althalaxx","pourquoi avoir envoyé balthule"}},{q="Pourquoi Balthule n’est-il pas rentré à Auberdine ?",a="Elissa n’a pas reçu le rapport de Balthule et vous demande donc d’aller voir ce qu’il en est. Balthule pourra vous expliquer sa situation quand vous le trouverez.",al={"pourquoi balthule a disparu","balthule est-il piégé","pourquoi balthule est-il resté"}},{q="Cette suite de quêtes continue-t-elle ?",a="Oui. Retrouver Balthule Frappelombre lance une enquête en plusieurs parties sur les forces obscures qui occupent la Tour d’Althalaxx et leurs ambitions à Sombrivage.",al={"est-ce une suite de quêtes","quelle quête vient ensuite","suite d’althalaxx"}}},fx={["895f5562"]={q="Pourquoi la Sentinelle Elissa Brise-stellaire veut-elle que cela soit fait ?",a="En tant que Sentinelle chargée de la défense d'Auberdine, Elissa Brise-stellaire est responsable de la protection de Sombrivage contre les menaces imminentes. Elle a envoyé Balthule Frappelombre enquêter sur des événements suspects près de la tour d'Althalaxx, mais il a beaucoup de retard. Craignant qu'il ne soit tombé dans un péril inattendu, elle a besoin de quelqu'un pour le localiser et confirmer sa sécurité.",al={"pourquoi trouver balthule","motif d'elissa brise-stellaire","pourquoi m'envoyer à la tour d'althalaxx"}}},fp="22,173,23.345.0,18.352.1,34.188.0,29.184.0,40.211.0,53.118.0,42.129.0,31.156.0"}
P.entries["quest:966"] = {n="La Tour d'Althalaxx",s="Les démonistes se rassemblent à la Tour d'Althalaxx, dans le nord de Sombrivage, attirant l'attention vigilante de Balthule Frappelombre. Il demande aux voyageurs de récupérer des fragments de parchemin auprès des fanatiques campés devant les ruines, dans l'espoir de découvrir qui ils sont et ce qu'ils cherchent.",h="Les démonistes se rassemblent à la Tour d'Althalaxx, dans le nord de Sombrivage, attirant l'attention...",kw={"althalaxx","auberdine","balthule","brin noir","sombrivage","delgren","fanatiques","parchemin","purificateur","frappelombre","démonistes"},ang={["class:Paladin"]="En tant que paladin, vous pouvez aider Delgren le Purificateur dans sa croisade contre la corruption gangrenée et démoniaque en contribuant à démasquer un culte obscur dans le nord de Sombrivage.",["class:Warlock"]="En tant que démoniste, vous pouvez voir comment des covens échappant à l'autorité de l'Alliance et de la Horde s'emparent d'antiques ruines pour leurs invocations.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous voyez dans la profanation de la Tour d'Althalaxx par les sombres sectateurs une nouvelle souillure du patrimoine elfique antique sur les rivages de Kalimdor."},sec={{t="Des yeux dans les bas-fonds",b="Depuis le Rivage brumeux, dans le nord de Sombrivage, Balthule Frappelombre surveille la côte et garde l'antique Tour d'Althalaxx à l'œil. Auberdine l'a envoyé surveiller les ruines et prévenir Delgren le Purificateur si le danger s'intensifie. Mais quitter son poste pour faire rapport pourrait laisser les sombres lanceurs de sorts parmi les pierres disparaître de sa vue. Balthule demande donc aux voyageurs de passage d'explorer les camps autour de la tour."},{t="Déchiffrer le culte",b="Les fidèles de moindre importance qui rôdent dans les ruines transportent des fragments de parchemins et des notes. Plusieurs Parchemins déchirés révèlent à Balthule leur nom : le Culte du Brin noir. Il n'a jamais entendu parler de cette secte et sait désormais qu'une bande de démonistes renégats n'est pas seule à l'œuvre. Delgren doit être prévenu sans tarder."}},faq={{q="Qui est Balthule Frappelombre ?",a="Balthule Frappelombre est un éclaireur de l'Alliance posté sur la route, près de la Tour d'Althalaxx, dans le nord de Sombrivage. Les dirigeants d'Auberdine l'ont envoyé surveiller les rassemblements suspects et faire rapport à Delgren le Purificateur.",al={"histoire de balthule frappelombre","qui est balthule","balthule à sombrivage"}},{q="Qu'est-ce que la Tour d'Althalaxx ?",a="La Tour d'Althalaxx est une antique ruine elfique dans le nord de Sombrivage. Des démonistes sinistres et leurs séides sectateurs ont investi ses abords et son intérieur, où ils accomplissent de sombres rituels à l'insu d'Auberdine.",al={"tour d'althalaxx","qu'est-ce qu'althalaxx","tour en ruines de sombrivage"}},{q="Qui sont les sectateurs autour de la tour ?",a="Les sectateurs autour de la tour appartiennent au Culte du Brin noir, une bande secrète de démonistes et de fanatiques réunis dans les antiques ruines elfiques pour pratiquer de sombres rituels d'invocation.",al={"qui sont les démonistes","culte du brin noir","fanatiques du brin noir"}},{q="Pourquoi Balthule déconseille-t-il d'entrer dans la tour ?",a="Balthule prévient que les démonistes dans la partie supérieure de la tour sont bien plus puissants et dangereux que les fanatiques campés parmi les ruines. Il conseille de recueillir des renseignements aux abords avant de tenter de prendre la forteresse d'assaut.",al={"peut-on entrer dans la tour","démonistes dangereux dans la tour","à l'intérieur de la tour"}},{q="Que révèlent les parchemins déchirés ?",a="Les fragments transportés par les fanatiques du culte révèlent le nom du groupe : le Culte du Brin noir. Balthule apprend que les occupants forment une secte organisée dont la présence menace la région.",al={"que révèlent les parchemins","histoire du parchemin déchiré","notes du culte"}},{q="Qui est Delgren le Purificateur ?",a="Delgren le Purificateur est un paladin de l'Alliance posté au Poste de Maestra, en Orneval, qui lutte contre les influences démoniaques et corruptrices. Il soupçonne qu'une activité malveillante prend racine à la Tour d'Althalaxx et compte sur des éclaireurs comme Balthule pour obtenir des renseignements.",al={"delgren","qui est delgren","delgren le purificateur"}}},fx={bc625320={q="Pourquoi Balthule Frappelombre veut-il que cela soit fait ?",a="Balthule Frappelombre craint que des forces obscures ne se rassemblent secrètement aux frontières de Sombrivage. Alors que Delgren soupçonnait que des démonistes se rassemblaient aux anciennes ruines, aucun d'eux ne sait qui ils sont ou quel rituel ignoble ils ont l'intention d'accomplir. Balthule a besoin de suffisamment de preuves écrites pour reconstituer leur identité et leurs motifs avant de prendre des mesures décisives pour protéger la région.",al={"pourquoi balthule veut les parchemins","motif de balthule","pourquoi enquêter sur althalaxx"}},["151da73d"]={q="Pourquoi Balthule Frappelombre vous envoie-t-il plutôt que d'y aller lui-même ?",a="Balthule est en poste pour une surveillance de reconnaissance solitaire à l'extérieur des ruines. Il ne peut pas quitter son poste pour parcourir les camps de cultistes environnants ou retourner à Auberdine pour faire un rapport, terrifié à l'idée que toute absence ne lui fasse manquer des mouvements ennemis critiques. En vous faisant affronter les cultistes extérieurs et récupérer leurs écrits, il peut maintenir une surveillance continue sur la tour.",al={"pourquoi balthule a besoin d'aide","pourquoi pas balthule","pourquoi balthule vous demande"}}},fp="22,252,20.370.0,20.280.1,29.215.0,31.218.0,43.179.0,50.225.0,35.185.0,28.262.0"}
P.entries["quest:96604"] = {n="The Great Outdoors",s="Brakk accueille les voyageurs près de son Basic Campfire et leur apprend à se reposer dans la nature. Ils passent ensuite aux métiers pratiques.",h="Brakk accueille les voyageurs près de son Basic Campfire et leur apprend à se reposer dans la nature.",kw={"boosted rest","brakk","installation de campement","feu de camp","the great outdoors","métier","survie en pleine nature"},ang={["faction:Horde"]="Un traditionnel « Lok-tar » orc accueille les nouveaux aventuriers de la Horde, qui apprennent les rudiments de la survie avant de traverser des territoires périlleux."},sec={{t="Leçons en pleine nature",b="Brakk salue les aventuriers en herbe d’un chaleureux « Lok-tar » et accueille ceux qui cherchent fortune et gloire. Les routes sauvages d’Azeroth exigent plus que le maniement des armes ; les voyageurs doivent aussi endurer les éléments. Apprendre à établir un campement et à reprendre des forces est une première étape pour survivre dans la nature."},{t="Du foyer aux métiers",b="Se reposer près du Basic Campfire de Brakk offre une pause réparatrice en plein air et apprend aux voyageurs à récupérer. Une fois ces bases acquises, les aventuriers novices peuvent rendre visite aux artisans d’un village voisin. Ils pourront y étudier des métiers et apprendre à fabriquer des installations de campement adaptées à leur artisanat."}},faq={{q="Qu’est-ce que The Great Outdoors ?",a="La leçon de Brakk apprend aux nouveaux aventuriers à se reposer près d’un feu de camp avant de choisir un métier.",al={"qu’est-ce que the great outdoors","quête the great outdoors"}},{q="Qui est Brakk ?",a="Brakk accueille les voyageurs impatients en quête de fortune et de gloire. Il leur apprend des moyens pratiques de survivre dans la nature et de se reposer près d’un feu de camp.",al={"qui est brakk","donneur de quête"}},{q="Qu’est-ce que le bonus Boosted Rest ?",a="Se reposer près du Basic Campfire de Brakk confère le bonus Boosted Rest et montre comment un feu à ciel ouvert peut aider un aventurier à récupérer dans la nature.",al={"bonus boosted rest","bonus de feu de camp"}},{q="Que faire après avoir terminé la quête ?",a="Après avoir appris à se reposer dans la nature, rendez visite aux maîtres du village voisin pour étudier un métier et apprendre à fabriquer des installations de campement adaptées à cet artisanat.",al={"étape suivante après la quête","que faire après le feu de camp"}},{q="Que sont les installations de campement ?",a="Les installations de campement sont des aménagements de site que les maîtres de métier enseignent dans les villages voisins. Elles permettent aux voyageurs d’adapter leur campement à l’artisanat qu’ils ont choisi.",al={"installations de campement","que sont les installations de campement"}},{q="À qui s’adresse cette formation ?",a="Cette leçon s’adresse aux âmes impatientes en quête de fortune et de gloire dans la nature, en particulier à ceux qui commencent leur périple et se préparent à choisir un métier.",al={"à qui s’adresse cette quête","est-ce pour la horde"}}},fp="18,131,19.303.0,20.303.0,27.97.0,13.133.0,30.138.0,46.153.0,23.164.0,34.151.0"}
P.entries["quest:96605"] = {n="The Great Outdoors",s="Au camp sauvage de Kaga, les nouveaux venus apprennent à se reposer et à récupérer. Depuis le feu de camp, ils se rendent chez les artisans des environs pour apprendre des métiers et fabriquer des installations de campement.",h="Au camp sauvage de Kaga, les nouveaux venus apprennent à se reposer et à récupérer.",kw={"boosted rest","installation de campement","feu de camp","kaga","survie","the great outdoors","métier","nature sauvage"},ang={["profession:Cooking"]="Les feux de camp et la survie en milieu sauvage sont les fondements de la cuisine en plein air. Apprendre l’art du campement complète naturellement vos talents de cuisinier."},sec={{t="Leçons de la nature sauvage",b="Kaga montre aux nouveaux venus comment affronter la nature sauvage, loin de la civilisation. Le courage seul ne suffit pas à les protéger. Ils doivent aussi savoir établir un camp et résister aux éléments."},{t="Le foyer et l’artisanat",b="Le feu de camp de Kaga offre un lieu de repos aux voyageurs épuisés. Asseyez-vous auprès du feu pour obtenir l’amélioration Boosted Rest. Une fois que vous savez vous reposer dans la nature, Kaga vous encourage à rendre visite aux artisans d’un village voisin. Ils peuvent vous enseigner des métiers et vous apprendre à fabriquer des installations de campement."}},faq={{q="Qu’est-ce que The Great Outdoors ?",a="Kaga apprend aux nouveaux venus à survivre dans la nature sauvage. Elle leur montre comment se reposer auprès d’un feu de camp et se préparer à apprendre des métiers.",al={"qu’est-ce que the great outdoors","quête the great outdoors"}},{q="Qui propose cette quête ?",a="Kaga est une voyageuse qui enseigne aux nouveaux venus les bases de la survie en milieu sauvage. Auprès de son feu de camp, ils peuvent apprendre à se reposer et à récupérer.",al={"qui est kaga","kaga donneuse de quête"}},{q="Qu’est-ce que l’amélioration Boosted Rest ?",a="Boosted Rest est l’état obtenu en s’asseyant auprès du Basic Campfire de Kaga. Il représente l’effet réparateur d’un repos dans un camp sauvage.",al={"boosted rest","qu’est-ce que l’amélioration boosted rest"}},{q="Que sont les installations de campement ?",a="Après avoir appris les bases du repos en pleine nature, vous pouvez demander aux artisans des villages voisins de vous apprendre à fabriquer des installations de campement spécialisées.",al={"histoire des installations de campement","fabriquer des installations de campement liées aux métiers"}},{q="Pourquoi Kaga vous demande-t-elle de vous asseoir près du feu de camp ?",a="Apprendre à établir un camp et à récupérer de l’endurance vous aide à survivre loin des villes civilisées. En vous asseyant près du feu de camp de Kaga, vous récupérez en vous reposant entre vos voyages.",al={"pourquoi se reposer près d’un feu de camp","repos près du feu de camp"}},{q="Que faire après cette leçon ?",a="Après avoir appris à vous reposer en pleine nature, cherchez les maîtres de métier du village voisin. Ils peuvent vous enseigner un métier et vous apprendre des recettes d’installations de campement propres à ce métier.",al={"que faire après the great outdoors","après la quête de kaga"}}},fp="18,162,19.184.0,24.259.0,27.126.0,22.128.0,30.141.0,23.140.0,43.158.0,48.161.0"}
P.entries["quest:96606"] = {n="The Great Outdoors",s="Près du feu de camp de Lyreena, les chasseurs apprennent à se reposer avant de parcourir les terres sauvages. Ils peuvent y obtenir l’amélioration Boosted Rest.",h="Près du feu de camp de Lyreena, les chasseurs apprennent à se reposer avant de parcourir les terres sauvages.",kw={"aventurier","boosted rest","feu de camp","chasseur","lyreena","survie","the great outdoors","étendues sauvages"},ang={["class:Hunter"]="En tant que chasseur, vous découvrez l’importance de la survie en pleine nature et de l’art du campement lorsque vous pistez dans les terres sauvages."},sec={{t="Leçons de la nature",b="Lyreena est une éclaireuse expérimentée qui guide les chasseurs au-delà des frontières de la civilisation. Elle vous invite à vous reposer près de son feu de camp entre deux chasses. Dans les terres sauvages d’Azeroth, savoir établir un camp et reprendre des forces compte autant que savoir pister le gibier."},{t="Répit au feu de camp",b="Un feu de camp offre chaleur et repos paisible après la route. Asseyez-vous près des flammes pour obtenir Boosted Rest et reprendre des forces pour la suite du voyage. Le repos vous aide à survivre en pleine nature."}},faq={{q="Qui est Lyreena ?",a="Lyreena est une éclaireuse expérimentée qui guide les chasseurs à travers les terres sauvages. Elle prodigue des conseils pratiques près de son feu de camp.",al={"qui est lyreena","feu de camp de lyreena","donneur de quête"}},{q="Qu'est-ce que The Great Outdoors ?",a="Près du feu de camp de Lyreena, les chasseurs apprennent à se reposer avant de parcourir les terres sauvages.",al={"qu'est-ce que the great outdoors","quelle est cette quête","quête the great outdoors"}},{q="Qu'est-ce que Boosted Rest ?",a="Boosted Rest est un avantage obtenu en vous asseyant près d’un feu de camp. Il vous aide à vous remettre du voyage et à vous préparer pour la suite du chemin.",al={"amélioration boosted rest","feu de camp boosted rest","comment obtenir boosted rest"}},{q="Pourquoi devez-vous vous reposer près d'un feu de camp ?",a="Vous reposer près d’un feu de camp vous apporte de la chaleur et vous laisse le temps de récupérer. Cela vous aide à vous préparer aux voyages périlleux à travers les terres sauvages.",al={"utilité du feu de camp","pourquoi s'asseoir près du feu","se reposer au feu de camp"}},{q="Pourquoi la survie en extérieur est-elle cruciale pour les chasseurs ?",a="Les chasseurs parcourent des terres sauvages isolées où tavernes et villes sûres peuvent être bien loin. Les rudiments de l’art du campement vous aident à supporter des conditions difficiles sans vous épuiser.",al={"compétences de survie du chasseur","survie en plein air","pourquoi une quête de chasseur"}},{q="Que devez-vous faire pour accomplir la tâche ?",a="Asseyez-vous près du feu de camp de Lyreena et patientez un court instant pour obtenir l’amélioration Boosted Rest.",al={"objectif de la quête","comment terminer the great outdoors","objectifs de the great outdoors"}}},fp="18,127,19.247.0,16.179.0,15.123.0,27.80.0,21.130.0,38.127.0,44.153.0,38.75.0"}
P.entries["quest:96607"] = {n="The Great Outdoors",s="Au-delà des remparts, The Great Outdoors vous apprend à respecter la nature sauvage. Les voyageurs chevronnés commencent par un feu de camp et les habitudes qui rendent chaque voyage plus sûr.",h="Au-delà des remparts, The Great Outdoors vous apprend à respecter la nature sauvage.",kw={"aventurier","repos amélioré","feu de camp","camping","eleanor shackleton","forêt d’elwynn","sam sarsaparilla","survie","métier"},ang={["faction:Alliance"]="Dans la Forêt d’Elwynn, les voyageurs humains apprennent les bases de la survie auprès de routiers expérimentés avant d’affronter des menaces plus redoutables dans la Marche de l’Ouest et aux Carmines.",["faction:Horde"]="Dans les plaines arides de Durotar et sur les mesas balayées par le vent de Mulgore, les maîtres de survie de la Horde enseignent aux jeunes guerriers à maîtriser le feu et à faire preuve de discipline en plein air.",["profession:Cooking"]="Tout campement en pleine nature commence par un feu, alors la cuisine va de pair avec la survie en plein air. Après cette leçon, vos instructeurs vous orientent vers des leçons de cuisine le long de la route."},sec={{t="Leçons de la route",b="Une lame acérée ou une magie puissante ne vous sauvera pas si vous négligez les bases. Près des clairières en bord de route, des rôdeurs chevronnés apprennent aux voyageurs quittant leur vallée natale à se reposer près d’un feu de camp. Sa chaleur soulage les pieds endoloris, apaise l’esprit et vous prépare à affronter la route difficile. Le repos et la préparation augmentent vos chances de survivre assez longtemps pour trouver fortune et gloire."},{t="Un chez-soi loin de chez soi",b="Vos instructeurs vous envoient aussi auprès des artisans de la ville, car un campement a besoin de plus qu’une braise et d’un sac de couchage. Vous pouvez forger des rivets de rechange, cuisiner des rations de route ou recoudre votre équipement déchiré sous les étoiles. Chaque métier fournit des installations de campement qui aident à transformer un flanc de colline nu en avant-poste autosuffisant."}},faq={{q="Qui enseigne cette leçon aux nouveaux voyageurs ?",a="Des voyageurs chevronnés enseignent cette leçon, mais l’instructeur dépend de l’endroit où vous vous trouvez. Dans la Forêt d’Elwynn, Sam Sarsaparilla s’en charge ; ailleurs, vous trouverez notamment Eric Brighthammer, Lyreena Duskblade, Brakk, Eleanor Shackleton, Kaga Wildhoof et Raan Wildwind.",al={"qui donne the great outdoors","qui commence the great outdoors","donneur de quête the great outdoors"}},{q="À quoi sert le repos près du feu de camp ?",a="Vous reposer près d’un feu de camp vous permet de reprendre votre souffle et d’obtenir un effet de repos amélioré. Prendre le temps de vous reposer sur le terrain vous aide à garder vos forces lors de longs voyages dans la nature sauvage.",al={"pourquoi s’asseoir près du feu","à quoi sert le feu de camp","effet de repos amélioré"}},{q="Où cette formation vous mène-t-elle ensuite ?",a="Après votre repos près du feu, votre mentor vous envoie dans les villages voisins pour apprendre des métiers pratiques. Vous pourrez ensuite suivre Camping 101: Cooking et des leçons de camping adaptées au métier que vous avez choisi.",al={"que faire après the great outdoors","quête suivante après the great outdoors","quêtes de camping"}},{q="Les aventuriers de la Horde peuvent-ils aussi suivre cette leçon ?",a="Oui. La survie est importante pour les aventuriers des deux factions. Les instructeurs de l’Alliance et de la Horde, dont Brakk, Eleanor Shackleton et Kaga Wildhoof, enseignent les mêmes bases du campement à leurs novices.",al={"réservé à l’alliance","the great outdoors pour la horde","les orcs peuvent-ils faire cette quête"}},{q="Pourquoi les instructeurs vous demandent-ils de parler aux maîtres de métier ?",a="Pour survivre, il ne suffit pas de s’asseoir près du feu ; il faut aussi savoir se débrouiller seul. Les maîtres de métier vous apprennent à fabriquer des installations de campement liées à votre profession, que vous cuisiniez des rations de route, répariez une armure ou prépariez des remèdes à la belle étoile.",al={"pourquoi apprendre des métiers","installations de campement et maîtres de métier","lien entre métier et campement"}},{q="Quelle expérience faut-il avoir avant d’accepter cette quête ?",a="Vous recevez généralement cette leçon après « The Adventurer », une fois que vous avez montré un peu d’ambition et quitté votre enclave de départ pour explorer la région environnante.",al={"prérequis pour the great outdoors","comment débloquer the great outdoors","avant the great outdoors"}}},fp="18,163,20.367.0,21.304.0,40.260.0,47.178.0,35.203.0,52.194.0,61.225.0,59.144.0"}
P.entries["quest:96608"] = {n="The Great Outdoors",s="Eric attend près de son feu de camp pour apprendre aux voyageurs à se reposer en pleine nature.",h="Eric attend près de son feu de camp pour apprendre aux voyageurs à se reposer en pleine nature.",kw={"boosted rest","camp fixture","feu de camp","eric","survie","the great outdoors","métier","nature sauvage"},ang={["class:Priest"]="En tant que prêtre, vous trouverez peut-être votre vocation dans les sanctuaires sacrés et les chapelles. Pourtant, la vie sur les routes exige des compétences pratiques de survie en plus des prières et des bénédictions."},sec={{t="Leçons de la nature sauvage",b="Loin des lieux habités, l’ambition et une arme ou un symbole sacré ne suffisent pas. Il faut savoir se reposer face aux éléments. Eric a beaucoup voyagé et vous accueille près de son feu de camp. Là, il vous enseigne l’importance d’un bon repos avant d’affronter les contrées sauvages."},{t="Du feu de camp à l'artisanat",b="Un feu de camp est un premier pas pour établir un campement utile lors d’un long voyage. Une fois que vous aurez appris à récupérer en pleine nature, rendez visite aux maîtres de métier dans les localités voisines. Ils peuvent vous apprendre à fabriquer des installations de camp adaptées à votre métier. Votre savoir-faire pourra alors vous accompagner dans vos voyages, où que la route vous mène."}},faq={{q="Qui est Eric ?",a="Eric est un voyageur aguerri qui apprend aux novices à survivre en pleine nature. Il vous accueille près de son feu de camp et partage ses conseils pour vivre au-delà des remparts des villes.",al={"qui donne cette quête","qui est eric","qui enseigne la vie en plein air"}},{q="Qu'est-ce que l'amélioration Boosted Rest ?",a="Vous reposer près du feu de camp d’Eric vous confère l’effet Boosted Rest. Il vous aide à récupérer et à vous préparer aux épreuves à venir, à l’abri des éléments.",al={"qu'est-ce que boosted rest","comment le feu de camp aide-t-il","amélioration de repos au camp"}},{q="Que sont les camp fixtures ?",a="Les installations de camp sont des structures ou des outils pratiques propres à certains métiers, que vous pouvez installer en pleine nature. Les maîtres des localités voisines expliquent comment votre métier vous permet d’établir un campement fonctionnel.",al={"que sont les camp fixtures","installations de métier","objet de camp de métier"}},{q="Pourquoi devez-vous vous asseoir près du feu de camp d'Eric ?",a="Vous asseoir près du feu de camp d’Eric vous laisse le temps de faire une pause, de vous réchauffer et d’écouter ses conseils de survie en pleine nature. Vous y reposer vous permet de profiter pleinement des bienfaits d’un abri en plein air.",al={"pourquoi s'asseoir au feu","s'asseoir près du feu de camp","objectif de feu de camp"}},{q="Où un aventurier devrait-il se rendre après avoir terminé cette leçon ?",a="Après vous avoir appris à vous reposer au camp, Eric vous suggère de vous rendre au village voisin. Les maîtres locaux peuvent vous enseigner un métier, puis vous montrer comment fabriquer des installations de camp adaptées à votre savoir-faire.",al={"que faire ensuite","où aller ensuite","après the great outdoors"}},{q="À qui s'adresse cette leçon de survie ?",a="Eric accueille les aventuriers de passage animés d’un esprit vagabond et prêts à chercher fortune et gloire à travers le monde. Ses conseils de survie peuvent vous aider à quitter la sécurité pour vous aventurer en pleine nature sauvage.",al={"qui peut faire cette quête","prêtre uniquement","est-ce destiné aux aventuriers"}}},fp="18,70,19.256.0,22.277.0,12.165.0,30.144.0,23.199.0,44.176.0,59.179.0,41.199.0"}
P.entries["quest:96626"] = {n="Camping 101: Cooking",s="À Comté-de-l’Or, Cook Tomas montre aux nouveaux voyageurs comment la cuisine permet d’allumer un feu de camp. Grâce à ce feu, ils peuvent établir un camp rudimentaire dans la nature.",h="À Comté-de-l’Or, Cook Tomas montre aux nouveaux voyageurs comment la cuisine permet d’allumer un feu de camp.",kw={"feu de camp","camping","camping 101: cooking","campement","cuisine","aménagements","comté-de-l’or","tomas"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance faisant ses premiers pas dans la Forêt d’Elwynn, vous êtes envoyé auprès de Cook Tomas à l’Auberge de la Fierté du Lion, à Comté-de-l’Or, pour apprendre à cuisiner et à faire un feu de camp.",["profession:Cooking"]="La cuisine vous apprend à faire des feux de camp rudimentaires au cœur de vos campements dans la nature."},sec={{t="Le foyer dans la nature",b="Un feu de camp vous offre un endroit où préparer à manger et commencer à établir un camp dans les contrées sauvages d’Azeroth. Apprenez à cuisiner, et vous apprendrez à faire ce feu. Une étendue sauvage peut alors devenir un lieu où camper."},{t="Formation à Comté-de-l’Or",b="Dans la Forêt d’Elwynn, les nouveaux voyageurs trouvent Cook Tomas à Comté-de-l’Or et apprennent la cuisine. Son enseignement vous permet d’établir un camp rudimentaire dans la nature. Au début, votre camp ne compte que quelques meubles. Une meilleure maîtrise de la cuisine vous permet de faire de plus grands feux, tandis que d’autres métiers d’artisanat vous offrent davantage de possibilités pour meubler et aménager votre campement."}},faq={{q="Qu'est-ce que la quête Camping 101: Cooking ?",a="La cuisine vous apprend à faire un feu de camp rudimentaire pour un campement dans la nature.",al={"qu'est-ce que camping 101 cooking","qu'enseigne camping 101","but de camping 101"}},{q="Qui est Tomas et où le trouver ?",a="Tomas enseigne la cuisine à Comté-de-l’Or, dans la Forêt d’Elwynn. Retrouvez-le à l’Auberge de la Fierté du Lion, où il enseigne les bases de la cuisine et l’art d’allumer un feu de camp.",al={"qui est tomas","où se trouve tomas","tomas comté-de-l'or"}},{q="Pourquoi la cuisine est-elle requise pour installer un campement ?",a="La cuisine vous apprend à faire le feu de camp au cœur d’un campement dans la nature, où vous pouvez vous reposer et disposer des meubles.",al={"pourquoi avoir besoin de cuisine pour camper","la cuisine est-elle requise pour camper","relation cuisine feu de camp"}},{q="Peut-on faire de plus grands feux de camp à mesure que la compétence progresse ?",a="Une meilleure maîtrise de la cuisine vous permet de faire des feux plus grands et plus robustes pour votre camp dans la nature.",al={"comment améliorer un feu de camp","peut-on faire des feux de camp plus grands","cuisine feux plus grands"}},{q="Comment acquiert-on des aménagements pour son campement ?",a="D’autres maîtres de métiers vous apprennent à fabriquer des meubles de campement. Différents métiers d’artisanat vous permettent de créer des objets pour décorer et améliorer un camp dans la nature.",al={"comment ajouter des aménagements de camp","d'où viennent les aménagements de camp","fabriquer des objets de camp"}},{q="Où un aventurier peut-il monter un camp ?",a="Une fois que vous savez cuisiner et faire un feu de camp, vous pouvez camper en pleine nature. Vos premiers campements sont modestes et ne comptent que quelques meubles jusqu’à ce que vous développiez vos compétences.",al={"peut-on camper n'importe où","règles du camping sauvage","limites de placement du camp"}}},fp="20,133,22.193.0,24.328.0,39.73.0,39.151.0,48.120.0,53.86.0,49.161.0,36.183.0"}
P.entries["quest:96627"] = {n="The Adventurer",s="Depuis la Vallée de Comté-du-Nord, le Maréchal McBride vous envoie vers Comté-de-l’Or chercher Sam Sarsaparilla. Vous avez prouvé votre valeur en défendant l’abbaye, et il veut maintenant que vous enquêtiez sur un nouveau venu.",h="Depuis la Vallée de Comté-du-Nord, le Maréchal McBride vous envoie vers Comté-de-l’Or chercher Sam...",kw={"forêt d’elwynn","comté-de-l’or","maréchal mcbride","comté-du-nord","sam sarsaparilla","the adventurer"},ang={["faction:Alliance"]="Pour les nouvelles recrues de l’Alliance qui achèvent leur service à Comté-du-Nord, c’est le premier pas officiel vers les contrées plus vastes de la Forêt d’Elwynn.",["race:Human"]="En tant que défenseur humain quittant l’Abbaye de Comté-du-Nord, vous faites vos premiers pas vers Comté-de-l’Or, au cœur d’Elwynn."},sec={{t="Quitter la vallée",b="Alors que les menaces des Défias et de la vermine s’atténuent, McBride se tourne vers la route qui s’étend au-delà de la vallée. Sa garnison a besoin de combattants prometteurs pour surveiller les voyageurs et les vagabonds dans les bois alentour."},{t="Un nouveau venu intrigant",b="Le Maréchal McBride vous demande de retrouver Sam Sarsaparilla, aperçu près de Comté-de-l’Or. Il ne s’agit ni d’un ordre militaire ni d’une chasse à la prime. Ce nouveau venu vous entraîne hors de la vallée isolée de Comté-du-Nord, vers les étendues sauvages de la Forêt d’Elwynn."}},faq={{q="Qui m’envoie accomplir cette tâche ?",a="Le Maréchal McBride, commandant de la garnison de Hurlevent dans la Vallée de Comté-du-Nord, vous envoie après que vous avez prouvé votre valeur en défendant l’abbaye.",al={"donneur de quête","qui confie la tâche de l’aventurier","quête du maréchal mcbride"}},{q="Qui est Sam Sarsaparilla ?",a="Sam Sarsaparilla est un aventurier qui se trouve près de la route, aux abords de Comté-de-l’Or. Le Maréchal McBride apprend sa présence et vous demande de découvrir ce qu’il fait là.",al={"sam sarsaparilla","qui est sam","aventurier de comté-de-l’or"}},{q="Où trouver Sam Sarsaparilla ?",a="Sam Sarsaparilla se trouve le long de la route principale qui mène au sud, de Comté-du-Nord vers Comté-de-l’Or, dans la Forêt d’Elwynn.",al={"emplacement de sam sarsaparilla","où est sam","trouver sam sarsaparilla"}},{q="Pourquoi le Maréchal McBride s’intéresse-t-il à un aventurier quelconque ?",a="Comté-du-Nord reste en alerte face aux bandits et aux intrus. McBride surveille les mercenaires et les vagabonds inconnus de passage, et fait confiance aux habitants fiables pour établir le premier contact.",al={"pourquoi m’envoyer","motivations de mcbride","pourquoi chercher sam"}},{q="Dois-je quitter la Vallée de Comté-du-Nord pour terminer cette tâche ?",a="Oui. Quittez la Vallée de Comté-du-Nord par ses portes sud, puis suivez la route forestière vers Comté-de-l’Or.",al={"hors de comté-du-nord","cette tâche quitte-t-elle comté-du-nord","aller à comté-de-l’or"}},{q="Cette tâche fait-elle partie de la chaîne de commandement militaire habituelle de Hurlevent ?",a="Le Maréchal McBride est un officier de Hurlevent, mais il qualifie cette mission d’inhabituelle, et non de service de garde ordinaire. Il compte sur votre jugement de protecteur indépendant, en dehors du protocole militaire officiel.",al={"armée de hurlevent","est-ce une tâche habituelle","mission officielle"}}},fx={dd262048={q="Pourquoi le Maréchal McBride me choisit-il pour enquêter sur Sam ?",a="Le Maréchal McBride considère qu'il s'agit d'une tâche inhabituelle plutôt que d'une mission de garnison standard. Vous ayant vu gérer les menaces locales du Comté-du-Nord, il vous considère comme un protecteur capable qui peut opérer discrètement au-delà des portes de l'abbaye. Sa propre garnison étant trop occupée à gérer les problèmes locaux, envoyer une recrue de confiance enquêter sur des rumeurs en bas de la route est bien plus logique que d'envoyer des gardes réguliers.",al={"pourquoi moi maréchal mcbride","pourquoi mcbride m'envoie","pourquoi ne pas envoyer un garde vers sam"}}},fp="14,186,18.198.0,18.232.0,26.131.0,24.138.0,33.96.0,56.182.0,52.100.0,63.202.0"}
P.entries["quest:96628"] = {n="The Adventurer",s="À la porte sud de Dun Morogh, The Adventurer transporte des vivres vers Kharanos. Le Montagnard Thalos demande aux voyageurs d’en apporter à Eric Brighthammer, un nouveau venu installé juste à l’extérieur du village.",h="À la porte sud de Dun Morogh, The Adventurer transporte des vivres vers Kharanos.",kw={"passe des frigères","dun morogh","eric brighthammer","kharanos","montagnard thalos","paquet de fournitures","the adventurer"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous transportez des provisions sur les routes glacées jusqu’à des alliés campés aux abords de Kharanos.",["race:Dwarf"]="En tant que nain quittant la Vallée des Frigères, vous apportez des provisions à Eric Brighthammer et prêtez main-forte aux Montagnards de Dun Morogh."},sec={{t="Une faveur pour les montagnards",b="Le Montagnard Thalos monte la garde à la porte sud de Dun Morogh, là où le sentier quitte la Vallée des Frigères. La surveillance des hauts cols et des tunnels occupe les Montagnards. Thalos veille aussi aux dangers et aux voyageurs sur la route. Quand un aventurier solitaire arrive près de Kharanos, il demande à des passants de confiance de transporter des provisions. Le paquet doit aider les nouveaux venus qui s’aventurent dans les escarpements gelés."},{t="Des provisions pour Kharanos",b="La route du col sud serpente jusqu’à Kharanos, un centre de l’artisanat et des voyages nains au cœur de Dun Morogh. Eric Brighthammer a récemment établi son camp juste à l’extérieur du village. Lui apporter les provisions des Montagnards relie les sentinelles de la crête à ceux qui parcourent les étendues sauvages."}},faq={{q="Qui donne la quête The Adventurer ?",a="Le Montagnard Thalos demande de l’aide aux voyageurs depuis son poste à la porte du col, là où le sentier de la Vallée des Frigères entre dans Dun Morogh.",al={"donneur de quête","qui donne the adventurer","quête de thalos"}},{q="Qui est Eric Brighthammer ?",a="Eric Brighthammer est un aventurier récemment arrivé aux abords de Kharanos. Le Montagnard Thalos demande aux voyageurs de lui apporter un paquet de fournitures.",al={"où se trouve eric brighthammer","qui est the adventurer","brighthammer"}},{q="Où cette livraison a-t-elle lieu ?",a="La livraison est destinée au camp d’Eric Brighthammer, juste à l’extérieur de Kharanos, à Dun Morogh. Il se trouve au nord du tunnel du Passe des Frigères, où le Montagnard Thalos est posté.",al={"où livrer les provisions","emplacement d’eric brighthammer","butin du paquet de fournitures"}},{q="Pourquoi le Montagnard Thalos envoie-t-il des provisions ?",a="Les Montagnards veillent sur les voyageurs à travers Dun Morogh. Quand Thalos apprend qu’un aventurier a établi son camp près de Kharanos, il organise l’envoi de provisions pour l’aider à affronter le froid.",al={"pourquoi envoyer des provisions","rôle de thalos","raison du paquet"}},{q="Quel objet transportez-vous ?",a="Vous transportez un paquet de fournitures du Montagnard Thalos à Eric Brighthammer.",al={"quelles provisions","objet paquet de fournitures"}},{q="Cette quête est-elle accessible aux joueurs de la Horde ?",a="Non. Le Montagnard Thalos est un garde nain lié à l’Alliance. Cette tâche est donc réservée aux voyageurs de l’Alliance.",al={"la horde peut-elle faire cette quête","quête réservée à l’alliance","quête de l’aventurier de la horde"}}},fx={["95095969"]={q="Pourquoi le Montagnard Thalos vous demande-t-il de livrer les fournitures ?",a="Le Montagnard Thalos et sa patrouille sont stationnés au col, chargés de surveiller la route et de sécuriser le tunnel contre les dangers locaux. Comme vous voyagez déjà à travers le col en direction de Kharanos, il vous demande de prendre la livraison le long de votre itinéraire plutôt que de détourner ses montagnards de leurs postes de garde.",al={"pourquoi moi the adventurer","pourquoi thalos a besoin de moi","pourquoi envoyer le joueur vers eric brighthammer"}}},fp="14,201,28.398.0,21.296.0,36.135.0,25.142.0,36.164.0,43.175.0,27.71.0,41.107.0"}
P.entries["quest:96629"] = {n="Camping 101: Cooking",s="À Dun Morogh, les voyageurs apprennent à cuisiner et à allumer un feu dans la nature. Gremlock Pilsnor enseigne aux aventuriers novices à Kharanos. La cuisine permet d’avoir des provisions pour la route et aide les voyageurs à allumer des feux de camp dans la nature.",h="À Dun Morogh, les voyageurs apprennent à cuisiner et à allumer un feu dans la nature.",kw={"feu de camp","camping","cuisine","dun morogh","mobilier","gremlock pilsnor","kharanos","nature sauvage"},ang={["class:Priest"]="En tant que prêtre, vous avez besoin de compétences de survie élémentaires, comme allumer un feu, lorsque vous voyagez loin des temples et des campements.",["faction:Alliance"]="En tant qu’aventurier de l’Alliance près de Dun Morogh, vous apprenez la cuisine et les techniques de survie en pleine nature auprès des instructeurs nains de Kharanos.",["profession:Cooking"]="La cuisine vous apprend à allumer le feu de camp nécessaire à un campement dans la nature et à son mobilier."},sec={{t="Le foyer dans la nature",b="Votre premier campement à Dun Morogh commence par un feu. À Kharanos, Gremlock Pilsnor apprend aux aventuriers novices à cuisiner. Cette compétence permet d’avoir des provisions pour la route. Un feu de camp robuste est le cœur d’un campement en plein air."},{t="Agrandir le campement",b="Une fois que vous savez allumer un feu de camp, vous pouvez installer un modeste campement en pleine nature. Un feu simple ne permet d’accueillir que quelques meubles, mais une meilleure compétence en cuisine vous permet d’allumer de plus grands brasiers. Les artisans formés à d’autres métiers peuvent fabriquer du mobilier et transformer une simple halte en un campement tout équipé."}},faq={{q="En quoi consiste la quête Camping 101: Cooking ?",a="Vous apprenez à cuisiner et à allumer des feux de camp, premières étapes pour installer un campement dans la nature.",al={"en quoi consiste camping 101 cooking","but de la quête","bases du camping et de la cuisine"}},{q="Qui est Gremlock Pilsnor ?",a="Gremlock Pilsnor apprend aux aventuriers novices à cuisiner à Kharanos, à Dun Morogh.",al={"qui enseigne la cuisine à kharanos","emplacement de gremlock pilsnor","maître de cuisine à dun morogh"}},{q="Pourquoi la cuisine est-elle nécessaire au camping ?",a="La cuisine vous apprend à allumer un feu de camp, qui est la base d’un campement dans la nature et de son mobilier.",al={"pourquoi faut-il cuisiner pour camper","utilité du feu de camp","cuisine et campements"}},{q="Où peut-on installer un campement ?",a="Une fois que vous savez allumer un feu, vous pouvez installer un campement rudimentaire dans la nature et vous y reposer pendant vos voyages.",al={"où installer un campement","règles des campements","installer un campement"}},{q="Comment améliorer ou agrandir un campement ?",a="Une meilleure compétence en cuisine vous permet d’allumer de plus grands feux de camp, tandis que d’autres métiers d’artisanat vous permettent de fabriquer davantage de mobilier pour le campement.",al={"comment améliorer un campement","feux plus grands","plus de décorations pour le camp"}},{q="D’autres métiers peuvent-ils contribuer au camping ?",a="D’autres métiers d’artisanat peuvent fournir du mobilier pour votre campement, à condition que vous ayez appris les compétences nécessaires à sa fabrication.",al={"qui propose du mobilier de campement","objets de campement des métiers","autres instructeurs de campement"}}},fp="20,225,22.208.0,22.298.0,39.91.0,24.79.0,37.91.0,36.115.0,40.122.0,44.105.0"}
P.entries["quest:96630"] = {n="The Adventurer",s="À Teldrassil, vous trouvez près de Dolanaar un journal égaré destiné à Lyreena Duskblade. Ses pages racontent les paisibles voyages et les bivouacs d’un voyageur inconnu.",h="À Teldrassil, vous trouvez près de Dolanaar un journal égaré destiné à Lyreena Duskblade.",kw={"camping","dolanaar","journal","journal égaré","lyreena duskblade","teldrassil","the adventurer"},ang={["faction:Alliance"]="En tant que jeune membre de l’Alliance sous l’Arbre-monde, vous contribuez à préserver l’ordre dans les bosquets en rapportant aux autres voyageurs les objets égarés.",["race:NightElf"]="En tant que jeune elfe de la nuit patrouillant à Teldrassil, vous pouvez trouver des traces de voyageurs et rapporter des objets perdus à des vagabonds comme Lyreena Duskblade."},sec={{t="Le journal d’un voyageur",b="Parmi les branches et les racines de Teldrassil, vous trouvez un journal abandonné. Son auteur anonyme raconte ses modestes pérégrinations et le simple plaisir de camper sous la canopée crépusculaire."},{t="Remise à Dolanaar",b="Vous pouvez emporter le journal jusqu’à Dolanaar au lieu de le laisser dans la nature. Lyreena Duskblade attend près de la colonie des elfes de la nuit pour récupérer ses pages égarées."}},faq={{q="Quel est le journal mentionné dans la quête ?",a="Le journal est un simple carnet trouvé dans les terres sauvages de Teldrassil. Ses entrées racontent les paisibles voyages d’un voyageur inconnu et son goût pour le camping en plein air.",al={"journal égaré","quel est ce livre","journal de the adventurer"}},{q="Qui est Lyreena Duskblade ?",a="Lyreena Duskblade est une elfe de la nuit qui attend près de Dolanaar pour récupérer le journal égaré.",al={"lyreena","où se trouve lyreena duskblade","pnj à qui remettre la quête"}},{q="Où se déroule cette quête ?",a="L’histoire se déroule dans les terres sauvages de Teldrassil, autour de Dolanaar.",al={"où se trouve la quête the adventurer","zone de quête"}},{q="Le journal parle-t-il de monstres dangereux ou de batailles ?",a="Non. Le journal raconte les pérégrinations ordinaires et le plaisir du camping d’une personne inconnue, sans parler de monstres dangereux ni de batailles.",al={"histoire du journal","que contient le journal","que dit le journal"}},{q="Qui peut accomplir cette tâche ?",a="Les membres de l’Alliance qui explorent Teldrassil peuvent rapporter le journal, en particulier les jeunes elfes de la nuit près de Dolanaar.",al={"la horde peut-elle faire cette quête","quête de l’alliance"}},{q="Pourquoi rapporter le journal à Dolanaar ?",a="Dolanaar est un lieu de rassemblement central et un carrefour de cette partie de Teldrassil. Lyreena Duskblade attend à proximité pour récupérer le journal.",al={"pourquoi dolanaar","pourquoi lyreena"}}},fp="14,156,20.179.0,20.163.0,43.152.0,25.83.0,33.65.0,56.125.0,27.106.0,36.135.0"}
P.entries["quest:96634"] = {n="Camping 101: Cooking",s="En pleine nature, tout commence par la cuisine et un feu, et des maîtres comme Zarrin, à Dolanaar, peuvent vous enseigner ce métier. Un feu de camp ancre votre campement et ouvre la voie à la survie en extérieur.",h="En pleine nature, tout commence par la cuisine et un feu, et des maîtres comme Zarrin, à Dolanaar, peuvent...",kw={"feu de camp","camping 101","campement","cuisine","dolanaar","aménagements","survie en pleine nature","zarrin"},ang={["profession:Cooking"]="La cuisine vous permet d’allumer le feu qui ancre un campement en extérieur. À mesure que vos compétences en cuisine progressent, vous pouvez apprendre à allumer des feux plus grands et plus solides.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous pouvez apprendre les rudiments de la vie en pleine nature et à allumer un feu auprès de Zarrin, à Dolanaar, avant de vous aventurer plus profondément dans les étendues sauvages de Teldrassil."},sec={{t="Le foyer de la nature sauvage",b="Quand vous voyagez en pleine nature, un feu de camp vous offre un point de départ. Commencez par apprendre la cuisine. Elle vous permet de préparer des repas à partir du gibier sauvage et vous apprend à allumer un feu de camp rudimentaire. Ce feu ancre un campement en extérieur. Sans lui pour vous protéger du froid et tenir les ténèbres à distance, vous ne pouvez pas établir un campement fiable en pleine nature."},{t="Agrandir le campement",b="Un feu de camp rudimentaire vous permet d’établir un camp modeste en pleine nature. Il ne peut accueillir que quelques aménagements simples, mais vous pouvez agrandir votre camp à mesure que vos compétences progressent. Une formation plus poussée en cuisine vous apprend à allumer des feux plus grands et plus solides. Les maîtres d’autres métiers peuvent vous apprendre à fabriquer des aménagements et à améliorer votre camp."}},faq={{q="À quoi sert Camping 101: Cooking ?",a="La formation en cuisine vous initie à la survie en pleine nature. Un feu de camp ancre votre campement en pleine nature.",al={"à quoi sert cette quête","objectif de camping 101: cooking","pourquoi faire camping 101"}},{q="Qui est Zarrin ?",a="Zarrin enseigne la cuisine à Dolanaar, sur Teldrassil. Il enseigne aux débutants les bases de la cuisine et à construire un feu de camp rudimentaire.",al={"qui est zarrin","zarrin dolanaar","où trouver le maître de cuisine à dolanaar"}},{q="Comment établir un campement en pleine nature ?",a="Commencez par apprendre à construire un feu de camp rudimentaire grâce à une formation en cuisine. La formation de base vous permet d’établir un camp modeste en pleine nature, tandis qu’une formation plus poussée vous apprend à allumer de plus grands feux et à améliorer votre campement.",al={"comment construire un camp","comment fonctionne le camping","installer un campement"}},{q="Peut-on ajouter des aménagements à son campement ?",a="Oui. La cuisine donne à votre camp son feu d’ancrage, et les maîtres d’autres métiers apprennent aux artisans chevronnés à fabriquer des aménagements et des améliorations pour leur camp.",al={"aménager un campement","décorations de camp","aménagements de campement et autres métiers"}},{q="Pourquoi la cuisine est-elle nécessaire au camping ?",a="La cuisine vous apprend à construire et à entretenir un feu de camp en pleine nature. Comme le feu ancre un campement en extérieur, apprendre à cuisiner est la première étape du camping en pleine nature.",al={"pourquoi faut-il cuisiner pour camper","lien entre cuisine et camping"}},{q="Peut-on allumer de plus grands feux de camp ?",a="Oui. Une formation plus poussée en cuisine vous apprend à allumer de plus grands feux pour vos campements en pleine nature.",al={"peut-on allumer de plus grands feux de camp","comment améliorer un feu de camp"}}},fp="20,180,22.333.0,22.297.0,44.101.0,14.121.0,44.196.0,41.154.0,36.163.0,30.87.0"}
P.entries["quest:96638"] = {n="The Adventurer",s="Sur l’Île de Zéphras, The Adventurer quitte le Bosquet de Thendal pour prendre la route de Shen’dar. Aetheen of the Gales envoie les vagabonds nouvellement aguerris vers le sud-ouest rencontrer Raan Wildwind, un campeur chevronné qui connaît les terres sauvages.",h="Sur l’Île de Zéphras, The Adventurer quitte le Bosquet de Thendal pour prendre la route de Shen’dar.",kw={"aetheen of the gales","raan wildwind","shen’dar","the adventurer","bosquet de thendal","île de zéphras"},ang={["race:Skyborne"]="En tant que jeune Skyborne quittant la canopée protectrice du Bosquet de Thendal, vous rencontrez Raan Wildwind, premier pas vers les vastes terres sauvages de votre île natale."},sec={{t="Quitter le bosquet",b="Le Bosquet de Thendal offre un abri, mais l’Île de Zéphras reste sauvage et périlleuse au-delà. Aetheen of the Gales veille sur les initiés et sait quand un voyageur est prêt à quitter les terres familières. Ceux qui cherchent la gloire, la fortune ou un but ont dépassé les limites protégées du bosquet."},{t="Un guide sur la route",b="Raan Wildwind a établi son camp au sud-ouest du Bosquet de Thendal, le long de la route menant à Shen’dar. Il a passé du temps à affronter les dangers au-delà du havre de paix. Pour les vagabonds qui quittent le bosquet, Raan donne des conseils pratiques pour survivre sur les routes exposées."}},faq={{q="Qui vous envoie trouver Raan Wildwind ?",a="Aetheen of the Gales vous envoie depuis le Bosquet de Thendal trouver Raan Wildwind. Après que vous avez fait vos preuves dans les bois environnants, elle vous oriente vers quelqu’un qui connaît l’île dans son ensemble pour l’avoir parcourue.",al={"qui donne la quête the adventurer","qui lance la quête the adventurer","quête d’aetheen"}},{q="Où se trouve Raan Wildwind ?",a="Raan Wildwind a établi son camp au sud-ouest du Bosquet de Thendal, le long de la route principale menant à Shen’dar.",al={"emplacement de raan wildwind","où se trouve raan","comment trouver raan wildwind"}},{q="Quel est le but de cette tâche ?",a="Vous quittez le havre sûr du Bosquet de Thendal et rencontrez un guide qui vous aidera à affronter les défis plus loin sur l’Île de Zéphras.",al={"pourquoi faire the adventurer","but de la quête the adventurer","qu’enseigne raan"}},{q="Quel prérequis faut-il remplir avant de recevoir cette quête ?",a="Avant qu’Aetheen of the Gales vous envoie trouver Raan Wildwind, vous devez accomplir la tâche concernant Foul Matriarch.",al={"prérequis de the adventurer","conditions pour the adventurer"}},{q="Le village de Shen’dar est-il sûr pour les voyageurs ?",a="Shen’dar se trouve au-delà du camp de Raan, au bout de la route qui part au sud-ouest du Bosquet de Thendal. C’est un établissement important, mais restez prudent sur les routes et dans les terres sauvages alentour.",al={"shen’dar est-il sûr","qu’est-ce que le village de shen’dar"}},{q="Qui est Raan Wildwind ?",a="Raan Wildwind est un vagabond qui a voyagé au-delà du Bosquet de Thendal et établi son camp à l’extérieur de Shen’dar. Il donne des conseils pratiques et des tâches aux nouveaux venus qui prennent la route.",al={"histoire de raan","qui est raan wildwind"}}},fx={dc12ab9c={q="Pourquoi Aetheen of the Gales vous envoie-t-il trouver Raan Wildwind ?",a="Aetheen reconnaît que de plus en plus de vagabonds s'aventurent au-delà de la sécurité du Bosquet de Thendal à la recherche de gloire et de fortune. Sachant que la nature sauvage présente un grand danger pour les inexpérimentés, Aetheen veut que vous recherchiez Raan Wildwind — un compagnon de voyage campant près de Shen’dar — pour apprendre une sagesse pratique et des leçons de survie qui vous garderont en vie pendant vos voyages à travers l'île.",al={"pourquoi aetheen vous envoie","motif d'aetheen of the gales","pourquoi rencontrer raan wildwind"}}},fp="14,209,17.275.0,19.252.0,36.189.0,31.96.0,33.100.0,64.113.0,39.179.0,21.174.0"}
P.entries["quest:96646"] = {n="Camping 101: Cooking",s="À Shen’dar, Zerril Softbreeze vous montre comment allumer un feu de camp. Camping 101: Cooking vous apprend à faire du feu et à établir un campement en pleine nature.",h="À Shen’dar, Zerril Softbreeze vous montre comment allumer un feu de camp.",kw={"feu de camp","camping","campement","cuisine","aménagements","shen’dar","zerril softbreeze"},ang={["profession:Cooking"]="En tant que cuisinier, vous apprenez à allumer un feu de camp au cœur d’un campement en pleine nature."},sec={{t="L’âtre sauvage",b="Un feu de camp vous offre un endroit où vous reposer dans les terres sauvages. Apprendre à cuisiner commence par allumer ce feu. C’est la première étape pour établir un campement sûr."},{t="Les bases du campement",b="Parlez à Zerril Softbreeze à Shen’dar pour apprendre les bases de la cuisine. Une fois que vous savez allumer un feu de camp, vous pouvez établir un petit campement en pleine nature. Un campement rudimentaire ne comporte que quelques aménagements. À mesure que votre compétence en cuisine progresse, vous pouvez allumer de plus grands feux. D’autres métiers permettent d’aménager le site."}},faq={{q="Qu’est-ce que Camping 101: Cooking ?",a="Camping 101: Cooking vous apprend à allumer un feu de camp et à établir un campement en pleine nature.",al={"qu’est-ce que camping 101 cooking","quête camping cuisine"}},{q="Qui est Zerril Softbreeze ?",a="Zerril Softbreeze enseigne la cuisine et l’art d’allumer un feu de camp à Shen’dar.",al={"qui est zerril softbreeze","maître de cuisine à shen’dar"}},{q="Pourquoi faut-il cuisiner pour installer un camp ?",a="La cuisine vous apprend à allumer le feu de camp au cœur d’un campement en pleine nature.",al={"pourquoi apprendre la cuisine pour camper","pourquoi faut-il cuisiner pour camper"}},{q="Où se trouve Zerril Softbreeze ?",a="Zerril Softbreeze se trouve à Shen’dar.",al={"où se trouve zerril softbreeze","emplacement de shen’dar"}},{q="Comment aménager les campements ?",a="Un campement rudimentaire comporte peu d’aménagements. D’autres métiers vous permettent d’en fabriquer et d’en installer davantage.",al={"aménagements du campement","comment aménager un camp"}},{q="Peut-on améliorer les feux de camp ?",a="À mesure que votre compétence en cuisine progresse, vous pouvez allumer de plus grands feux de camp.",al={"feux de camp plus grands","améliorer le camp"}}},fp="20,166,22.159.0,27.323.0,29.97.0,25.74.0,41.81.0,35.41.0,31.82.0,26.64.0"}
P.entries["quest:96652"] = {n="The Adventurer",s="Dans les terres rouges de Durotar, The Adventurer trouve un journal perdu destiné à Brakk, près de Tranchecolline. Ses pages évoquent des voyages paisibles et des nuits sous les étoiles.",h="Dans les terres rouges de Durotar, The Adventurer trouve un journal perdu destiné à Brakk, près de...",kw={"aventurier","brakk","camping","durotar","journal","journal perdu","tranchecolline"},ang={["class:Hunter"]="En tant que chasseur, vous savez vivre des ressources de la nature. Les notes attendries du journal sur le camping en pleine nature vous sembleront peut-être familières.",["faction:Horde"]="De nombreuses nouvelles recrues parcourent les sentiers arides de Durotar. Rapporter leurs effets perdus à des voyageurs comme Brakk, près de Tranchecolline, aide à maintenir l’ordre sur la frontière centrale."},sec={{t="Notes d’un voyageur",b="Un journal perdu repose dans la terre rouge de Durotar, loin des batailles et des campagnes qui marquent la région. Un voyageur inconnu y consigne ses trajets quotidiens et le plaisir de camper sous le ciel ouvert. Le journal offre un aperçu paisible de la vie sur les routes d’une contrée hostile."},{t="À remettre à Brakk",b="Le journal est destiné à Brakk, un aventurier qui campe près de Tranchecolline. Ses pages relient un voyageur inconnu à quelqu’un qui veille sur les routes poussiéreuses. Le remettre à Brakk pourrait préserver le souvenir des voyages de son auteur."}},faq={{q="Que contient le journal perdu ?",a="Le journal rassemble les récits quotidiens des voyages d’un aventurier peu connu, avec des notes attendries sur ses campements en pleine nature.",al={"que raconte le journal","contenu du journal perdu","texte du journal"}},{q="Qui a écrit le journal ?",a="Les pages retrouvées ne nomment pas leur auteur. Elles décrivent la vie et les voyages d’un aventurier inconnu.",al={"qui est l’aventurier","auteur du journal perdu","qui a écrit ce livre"}},{q="Qui est Brakk ?",a="Brakk est un aventurier qui campe près de Tranchecolline, au centre de Durotar, et le journal lui est destiné.",al={"brakk tranchecolline","qui est brakk","où se trouve brakk"}},{q="Où trouve-t-on le journal ?",a="Le journal est abandonné dans la terre rouge de Durotar, où un voyageur de la Horde peut le trouver en passant.",al={"où trouver le journal","emplacement du journal perdu","début de la quête de l’aventurier"}},{q="Pourquoi ce journal intéresse-t-il Brakk ?",a="Le journal n’indique pas pourquoi il intéresserait Brakk. C’est un aventurier qui campe juste à l’extérieur de Tranchecolline et enseigne les bases du camping aux nouvelles recrues. Le journal parle de camping.",al={"pourquoi le remettre à brakk","rôle de brakk","journal de brakk"}},{q="L’aventurier qui l’a écrit est-il en danger ?",a="Les pages ne révèlent aucun signe de méfait et évoquent le camping avec tendresse. L’auteur a peut-être perdu le journal par inadvertance ou est parti à l’improviste.",al={"l’auteur est-il vivant","l’aventurier est-il mort","sort de l’aventurier perdu"}}},fp="14,158,18.287.0,17.206.0,32.121.0,22.106.0,13.99.0,27.95.0,39.185.0,41.136.0"}
P.entries["quest:96655"] = {n="Camping 101: Cooking",s="À Tranchecolline, le cuisinier Cook Torka apprend aux voyageurs à cuisiner et à allumer un feu de camp. Ces compétences leur permettent d'établir des campements dans la nature.",h="À Tranchecolline, le cuisinier Cook Torka apprend aux voyageurs à cuisiner et à allumer un feu de camp.",kw={"feu de camp","camping 101","camping 101: cooking","campement","cook torka","cuisine","durotar","aménagements","tranchecolline"},ang={["faction:Horde"]="En tant qu'aventurier de la Horde débutant en Durotar, vous pouvez rendre visite à Cook Torka à Tranchecolline pour apprendre les bases de la cuisine.",["profession:Cooking"]="La cuisine est nécessaire pour allumer un feu de camp élémentaire, base de la survie en pleine nature et de l'installation d'un campement."},sec={{t="Le foyer de la nature",b="Au-delà des portes d'une colonie, survivre dans la nature exige plus qu'une lame acérée et une armure robuste. À Tranchecolline, le cuisinier Cook Torka enseigne la cuisine aux aventuriers en herbe. Dans Durotar et au-delà, cuisiner ne consiste pas seulement à préparer un repas chaud. Cela apprend aussi aux voyageurs à allumer un feu de camp fiable, au cœur de tout campement."},{t="Aménager un campement",b="Une fois les bases acquises, les voyageurs peuvent installer un modeste campement presque partout aux confins de la civilisation. Un feu de camp de novice ne permet d'accueillir que quelques aménagements essentiels. Une meilleure maîtrise de la cuisine leur permet d'allumer de plus grands feux. D'autres métiers leur apprennent à fabriquer ce dont ils ont besoin pour aménager leur campement et en faire un abri fiable contre les dangers de la nature."}},faq={{q="Qu'apprend la quête Camping 101: Cooking ?",a="Camping 101: Cooking enseigne aux aventuriers les bases de la survie en plein air. Apprendre à cuisiner et à allumer un feu de camp leur permet d'établir des campements dans la nature.",al={"qu'est-ce que camping 101 cooking","quête camping 101 cooking","à quoi sert cette quête"}},{q="Qui est Cook Torka ?",a="Cook Torka est le maître de cuisine de la Horde à Tranchecolline, en Durotar. Il enseigne les bases de la cuisine et l'allumage d'un feu de camp aux aventuriers en herbe.",al={"qui enseigne la cuisine à tranchecolline","qui est cook torka","où se trouve cook torka"}},{q="Pourquoi faut-il savoir cuisiner pour camper ?",a="La cuisine apprend aux voyageurs à allumer le feu de camp qui est au cœur de tout campement. Sans feu, ils ne peuvent pas aménager un véritable campement dans la nature.",al={"pourquoi cuisiner pour camper","lien entre cuisine et feu de camp","faut-il cuisiner pour camper"}},{q="Où un aventurier peut-il installer un campement ?",a="Une fois que vous savez cuisiner et allumer un feu de camp, vous pouvez installer un petit campement presque partout en pleine nature. Au début, il ne peut accueillir que quelques aménagements.",al={"où camper","comment fonctionne le camping","emplacement du campement"}},{q="Comment améliorer son feu de camp ?",a="En améliorant vos compétences en cuisine, vous pouvez apprendre à allumer des feux de camp plus grands et plus durables, et à accueillir davantage d'aménagements dans votre campement.",al={"feux de camp plus grands","améliorer un feu de camp","comment améliorer son campement"}},{q="Comment obtenir des aménagements pour un campement ?",a="La cuisine fournit les bases du feu de camp, tandis que les maîtres d'autres métiers, partout dans le monde, apprennent aux aventuriers à fabriquer et à placer des aménagements pour leur campement.",al={"décorations de campement","aménager un campement","maîtres des métiers pour aménager un campement"}}},fp="20,131,22.315.0,30.329.0,39.148.0,18.139.0,36.149.0,42.177.0,33.133.0,45.155.0"}
P.entries["quest:96656"] = {n="The Adventurer",s="Près du Glas, The Adventurer enquête sur une inconnue en route vers Brill. La Croisade écarlate menace la région, mais l'inconnue est Eleanor Shackleton, une voyageuse réprouvée qui enseigne la survie en pleine nature.",h="Près du Glas, The Adventurer enquête sur une inconnue en route vers Brill.",kw={"brill","campement","le glas","eleanor shackleton","exécuteur arren","croisade écarlate","the adventurer","the great outdoors","clairières de tirisfal"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez apprendre des techniques pratiques de survie auprès de voyageurs errants, tandis que l'Exécuteur Arren garde les jeunes frontières du royaume réprouvé.",["race:Undead"]="En tant que nouveau Réprouvé près du Glas, votre rencontre avec Eleanor, une aventurière comme vous, montre qu'une inconnue près de Brill n'est pas forcément une espionne de la Croisade écarlate."},sec={{t="Une surveillance suspecte",b="L'Exécuteur Arren veille sur le Glas et les routes alentour. Des croisés écarlates espionnent la région et s'infiltrent dans le nord de Lordaeron, alors une silhouette inconnue près de Brill éveille ses soupçons. Vous avez prouvé votre dévouement en vous attaquant aux menaces de la Croisade le long de la frontière. À présent, Arren vous demande d'enquêter discrètement sur l'inconnue et de découvrir si elle menace les Réprouvés."},{t="Une voyageuse dans les bois",b="Au bord de la route près de Brill, vous trouvez Eleanor Shackleton. C'est une voyageuse réprouvée qui fait une pause avant de repartir à l'aventure dans les étendues sauvages. Elle ne prépare aucun complot de la Croisade et ne pratique pas la nécromancie du Fléau. Voyant en ceux qui viennent la vérifier des aventuriers comme elle, Eleanor vous propose de vous apprendre à survivre en pleine nature et à établir un campement."}},faq={{q="Pourquoi l'Exécuteur Arren veut-il qu'on enquête sur Eleanor ?",a="Les infiltrés de la Croisade écarlate et les espions ennemis menacent Le Glas et Brill. Arren se méfie de toute personne inconnue sur la grande route jusqu'à ce que ses intentions soient claires.",al={"pourquoi enquêter sur eleanor","qui m'a envoyé auprès d'eleanor","mission d'arren auprès d'eleanor"}},{q="Qui est Eleanor Shackleton ?",a="Eleanor Shackleton est une aventurière réprouvée qui campe près de la route, non loin de Brill. Elle explore les étendues sauvages et propose aux voyageurs des conseils pratiques pour survivre.",al={"qui est eleanor","histoire d'eleanor shackleton","qui est le pnj the adventurer"}},{q="Eleanor est-elle liée à la Croisade écarlate ?",a="Non. Eleanor n'a aucun lien avec la Croisade écarlate, dont les fanatiques menacent les Clairières de Tirisfal.",al={"eleanor est-elle de la croisade écarlate","eleanor est-elle une ennemie","eleanor est-elle une espionne"}},{q="Où mène cette quête ?",a="Parler à Eleanor mène à The Great Outdoors. Elle commence alors à vous enseigner la survie en pleine nature et l'art d'établir un campement.",al={"que faire après the adventurer","quête après the adventurer","suite de la quête d'eleanor shackleton"}},{q="Où trouver Eleanor Shackleton ?",a="Eleanor campe juste à l'écart de la route principale, à l'est en direction de Brill, dans les Clairières de Tirisfal.",al={"emplacement d'eleanor","où se trouve eleanor shackleton","camp d'eleanor dans les clairières de tirisfal"}},{q="Pourquoi l'Exécuteur Arren vous a-t-il choisi pour cette mission ?",a="Vous avez gagné la confiance d'Arren en débusquant des agents et des messagers de la Croisade écarlate près du Glas. Ce travail lui a montré que vous pouviez mener une mission de reconnaissance délicate.",al={"pourquoi m'avoir choisi","confiance d'arren","pourquoi l'exécuteur arren vous envoie"}}},fp="14,219,18.368.0,23.319.0,50.157.0,26.158.0,44.87.0,27.123.0,38.74.0,51.154.0"}
P.entries["quest:96658"] = {n="Camping 101: Cooking",s="En apprenant la cuisine, un feu de camp vous offre un foyer loin des remparts. Sur les terres de l’Alliance et de la Horde, les maîtres cuisiniers montrent aux nouveaux aventuriers comment en allumer un et se préparer à la vie dans la nature.",h="En apprenant la cuisine, un feu de camp vous offre un foyer loin des remparts.",kw={"feu de camp","camping 101","cuisine","comté-de-l’or","shackleton","tomas","terres sauvages","zarrin"},ang={["faction:Alliance"]="En quittant le Comté-du-Nord, Dun Morogh ou Teldrassil comme aventurier de l’Alliance, vous êtes dirigé vers des villes comme le Comté-de-l’Or, Kharanos et Dolanaar. Vous y apprenez à vous débrouiller avant d’affronter les terres sauvages.",["faction:Horde"]="Jeune combattant de la Horde, vous êtes dirigé vers les feux de camp de Tranchecolline, Sabot-de-Sang ou Brill, dans Durotar, Mulgore ou Tirisfal.",["profession:Cooking"]="La cuisine vous fournit de quoi reprendre des forces et un feu de camp pour établir le cœur de votre campement en plein air."},sec={{t="Le foyer des terres sauvages",b="Loin des remparts, un feu de camp permet de faire bouillir de l’eau et de rôtir de la viande. Ses flammes vous offrent un foyer lorsque vous traversez des contrées inconnues et dressez votre camp."},{t="Des braises aux campements",b="Les apprentis cuisiniers allument de petits feux avec peu d’aménagements. À mesure que vous progressez en cuisine, vous pouvez allumer de plus grands feux pour aménager des campements plus élaborés. D’autres métiers pratiques vous apprennent à fabriquer du mobilier utile."}},faq={{q="À quoi sert cette quête ?",a="Les nouveaux aventuriers se rendent auprès d’un maître cuisinier dans une localité voisine pour apprendre les bases de la cuisine et allumer un feu de camp pour leur campement en plein air.",al={"pourquoi faire camping 101","but de camping 101 cuisine","à quoi sert cette quête"}},{q="Qui propose cette quête aux voyageurs ?",a="Des guides expérimentés des terres sauvages et des aventuriers proposent cette formation aux deux factions. Parmi eux figurent Eleanor Shackleton, Eric Brighthammer, Lyreena Duskblade, Sam Sarsaparilla, Brakk, Kaga Wildhoof et Raan Wildwind.",al={"qui donne camping 101","donneur de quête de camping"}},{q="Où les joueurs de l’Alliance rendent-ils cette quête ?",a="Les aventuriers de l’Alliance se présentent auprès des maîtres cuisiniers de leur territoire natal, comme Tomas au Comté-de-l’Or, Gremlock Pilsnor à Kharanos ou Zarrin à Dolanaar.",al={"où rendre la quête alliance","maître cuisinier alliance"}},{q="Où les joueurs de la Horde rendent-ils cette quête ?",a="Les aventuriers de la Horde peuvent apprendre auprès du cuisinier Torka à Tranchecolline, de William Pickman à Brill ou de Pyall Silentstride à Sabot-de-Sang.",al={"maître cuisinier horde","où rendre la quête horde"}},{q="Peut-on agrandir le campement par la suite ?",a="Oui. Une meilleure maîtrise de la cuisine vous apprend à allumer de plus grands feux, qui permettent d’installer davantage d’aménagements dans votre campement en pleine nature.",al={"feu de camp plus grand","améliorer son campement"}},{q="D’autres métiers peuvent-ils contribuer au campement ?",a="Oui. La cuisine permet d’allumer le feu de camp de base, tandis que d’autres métiers vous apprennent à fabriquer des aménagements pratiques si vous les avez appris.",al={"métiers de camping","aménagements de campement"}}},fp="20,216,28.150.0,26.199.0,34.137.0,35.217.0,39.147.0,36.128.0,36.109.0,44.129.0"}
P.entries["quest:96659"] = {n="The Adventurer",s="Depuis la Mesa de Nuage rouge, le Chef Vent-du-faucon envoie de jeunes voyageurs porter des fournitures à Kaga Wildhoof, près du village de Sabot-de-Sang. Elle l'a aidé il y a longtemps, et il compte lui rendre sa bonté.",h="Depuis la Mesa de Nuage rouge, le Chef Vent-du-faucon envoie de jeunes voyageurs porter des fournitures à...",kw={"sabot-de-sang","camp narache","chef vent-du-faucon","kaga wildhoof","mulgore","mesa de nuage rouge","paquet de fournitures","the adventurer"},ang={["faction:Horde"]="En tant que voyageur de la Horde quittant la Mesa de Nuage rouge, vous portez des fournitures à Kaga Wildhoof, une aventurière expérimentée près du village de Sabot-de-Sang.",["race:Tauren"]="En tant que jeune tauren, vous portez les fournitures du Chef Vent-du-faucon à Kaga Wildhoof, au-delà du Camp Narache et jusque dans les plaines de Mulgore."},sec={{t="La dette d'un chef",b="Le Chef Vent-du-faucon vous demande de porter des provisions à Kaga Wildhoof, près du village de Sabot-de-Sang. Il y a longtemps, elle l'a aidé quand il en avait besoin, et il se souvient de sa bonté. Elle a maintenant établi son campement à l'extérieur du village. Hawkwind confie donc des fournitures à de jeunes voyageurs qui quittent la mesa, pour son ancienne bienfaitrice."},{t="Quitter la mesa",b="Le sentier part de la Mesa de Nuage rouge en direction du village de Sabot-de-Sang, à travers les plaines de Mulgore. Avec le paquet du Chef Vent-du-faucon, vous dépassez le Camp Narache, où les jeunes taurens se sont entraînés. Le chemin mène vers les vastes terres des Tribus taurens unies."}},faq={{q="Qui est Kaga Wildhoof ?",a="Kaga Wildhoof est une aventurière tauren expérimentée qui campe juste à l'extérieur du village de Sabot-de-Sang. Elle a aidé le Chef Vent-du-faucon par le passé.",al={"kaga wildhoof","qui est wildhoof","où est kaga"}},{q="Pourquoi le Chef Vent-du-faucon envoie-t-il ces fournitures ?",a="Le Chef Vent-du-faucon envoie ces fournitures pour rendre à Kaga Wildhoof l'aide qu'elle lui a apportée il y a longtemps.",al={"dette du chef vent-du-faucon","pourquoi envoyer des fournitures","utilité du paquet de fournitures"}},{q="Où se trouve le campement de Kaga Wildhoof ?",a="Le campement de Kaga Wildhoof se trouve juste à l'extérieur du village de Sabot-de-Sang, en descendant le sentier depuis la Mesa de Nuage rouge vers le centre de Mulgore.",al={"emplacement du camp de kaga","trouver kaga","camp près du village de sabot-de-sang"}},{q="Quand cette quête devient-elle disponible ?",a="Le Chef Vent-du-faucon vous confie cette tâche lorsque vous avez fait vos preuves sur la Mesa de Nuage rouge et que vous êtes prêt à voyager dans Mulgore.",al={"quand obtenir l'aventurière","moment de la quête du chef vent-du-faucon","quête de sortie de la mesa"}},{q="Cette quête vous éloigne-t-elle du Camp Narache ?",a="Oui. Vous transportez les fournitures depuis le Camp Narache en descendant le sentier vers le village de Sabot-de-Sang.",al={"quitter la mesa de nuage rouge","voyage vers sabot-de-sang"}},{q="Que contient le Paquet de fournitures ?",a="Le Paquet de fournitures contient le nécessaire pour un aventurier qui voyage au-delà des campements.",al={"quelles sont les fournitures","contenu du paquet de fournitures"}}},fx={["2c6e5885"]={q="Pourquoi le Chef Vent-du-faucon vous demande-t-il de livrer les fournitures ?",a="Vous avez terminé vos rites initiaux dans la Mesa de Nuage rouge et vous vous préparez à quitter le Camp Narache pour vous aventurer dans les plaines plus larges de Mulgore. Votre départ vous faisant déjà passer par le village de Sabot-de-Sang, le Chef Vent-du-faucon vous confie cette commission plutôt que d'envoyer des braves qui sont nécessaires pour garder la mesa et protéger les jeunes tauren qui s'y entraînent.",al={"pourquoi moi hawkwind","pourquoi m'envoyer avec les fournitures","pourquoi hawkwind me choisit"}}},fp="14,173,23.296.0,16.244.0,21.122.0,44.92.0,38.111.0,38.117.0,48.86.0,43.94.0"}
P.entries["quest:96661"] = {n="Camping 101: Cooking",s="À Sabot-de-Sang, Pyall Silentstride vous initie à la cuisine et aux feux de camp. À travers Kalimdor, ces compétences vous aident à établir un campement et à préparer des repas à partir du gibier chassé.",h="À Sabot-de-Sang, Pyall Silentstride vous initie à la cuisine et aux feux de camp.",kw={"sabot-de-sang","feu de camp","camping 101","campement","cuisine","meubles","pyall silentstride","nature sauvage"},ang={["faction:Horde"]="En tant que voyageur de la Horde en Mulgore, vous commencez votre formation à la survie à Sabot-de-Sang, où des artisans et des cuisiniers taurens peuvent vous guider.",["profession:Cooking"]="En tant que cuisinier, vous apprenez à allumer le feu au cœur d’un campement et à préparer de la nourriture pour vos séjours en pleine nature."},sec={{t="Le foyer de la nature sauvage",b="À la nuit tombée, un feu de camp vous offre un endroit où revenir. À travers Kalimdor, les bases de la cuisine vous apprennent à allumer un feu en pleine nature. Elles vous montrent aussi comment préparer des repas nourrissants à partir du gibier chassé, faisant de la cuisine un élément de la survie en plein air."},{t="Construire le camp",b="À Sabot-de-Sang, en Mulgore, Pyall Silentstride vous enseigne les bases de la cuisine. Grâce à cette formation, vous pouvez allumer un feu de camp et établir un campement sommaire en pleine nature. À mesure que votre compétence en cuisine progresse, vous apprenez à faire des feux plus grands. D’autres métiers peuvent fournir du mobilier pour votre avant-poste."}},faq={{q="Qu'est-ce que Camping 101: Cooking ?",a="La cuisine vous apprend à allumer un feu de camp et à établir un campement en pleine nature.",al={"qu'est-ce que camping 101 cooking","quête de cuisine camping","bases du camping cuisine"}},{q="Qui est Pyall Silentstride ?",a="Pyall Silentstride enseigne la cuisine à Sabot-de-Sang, en Mulgore. Il montre aux aventuriers novices comment cuisiner et allumer des feux de camp simples.",al={"qui est pyall silentstride","emplacement de pyall silentstride","maître des cuisiniers de sabot-de-sang"}},{q="Pourquoi la cuisine est-elle nécessaire pour apprendre à camper ?",a="La cuisine vous apprend à allumer un feu de camp, le cœur pratique d’un campement, et à préparer des repas.",al={"pourquoi avoir besoin de la cuisine pour camper","pourquoi apprendre la cuisine pour camper","lien feu de camp camping"}},{q="Peut-on faire de plus grands feux de camp à mesure que la compétence s'améliore ?",a="À mesure que votre compétence en cuisine s’améliore, vous apprenez à faire des feux plus grands pour des campements plus importants.",al={"puis-je améliorer les feux de camp","feux de camp plus grands","comment faire de plus grands feux"}},{q="Comment meubler un campement ?",a="D’autres métiers peuvent fournir du mobilier pour votre campement. Vous pouvez le fabriquer si vous avez appris ces métiers.",al={"comment fonctionnent les meubles de campement","décorations de campement","meubles de campement métiers"}},{q="Où peut-on installer un camp ?",a="Une fois que la cuisine vous a appris à allumer un feu de camp, vous pouvez établir un campement sommaire en pleine nature, où que vous alliez.",al={"où installer son camp","puis-je camper n'importe où","restrictions de campement"}}},fp="20,177,22.243.0,17.274.0,29.84.0,26.132.0,42.95.0,53.95.0,30.107.0,28.125.0"}
P.entries["quest:967"] = {n="La Tour d'Althalaxx",s="À la Tour d'Althalaxx, les sectateurs du Brin sombre se rassemblent et Balthule Frappelombre a besoin d'aide. Il envoie un avertissement par un coursier de l'Alliance au Poste de Maestra, en Orneval, pour son mentor, Delgren le Purificateur.",h="À la Tour d'Althalaxx, les sectateurs du Brin sombre se rassemblent et Balthule Frappelombre a besoin d'aide.",kw={"orneval","balthule frappelombre","brin sombre","sombrivage","delgren le purificateur","lumière sacrée","poste de maestra","tour d'althalaxx"},ang={["class:Paladin"]="En tant que paladin, vous pouvez prendre Delgren pour modèle dans votre vocation sacrée en terre inconnue. Ce croisé humain manie la Lumière et a gagné la confiance des Elfes de la nuit reclus de Kalimdor.",["faction:Alliance"]="En tant que membre de l'Alliance, vous pouvez voir comment Balthule, à Sombrivage, et Delgren, en Orneval, maintiennent le contact entre les garnisons dispersées de l'Alliance dans le nord de Kalimdor.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous pouvez voir vos Sentinelles bâtir un partenariat concret avec des alliés de l'est venus purger les derniers vestiges démoniaques de vos bois."},sec={{t="Un appel à des renforts",b="Balthule Frappelombre comprend qu'un seul éclaireur ne peut pas faire face à la menace du Brin sombre. Après un affrontement contre des sectateurs près de la Tour d'Althalaxx, il rédige un rapport pour son maître, Delgren le Purificateur, et le confie à un messager de l'Alliance. Les invocateurs de la secte gagnent en audace. Balthule a besoin de chefs aguerris pour diriger la riposte."},{t="La route vers Orneval",b="La dépêche de Balthule vous mène vers le sud, le long de la route côtière de Sombrivage, puis au-delà de la frontière boisée, en Orneval. Delgren le Purificateur est en poste au Poste de Maestra, près de la route occidentale. Ce paladin humain s'efforce de purifier les bois des démons et des morts-vivants. Les coutumes des Elfes de la nuit lui semblaient autrefois étranges, mais il a gagné le profond respect des Sentinelles en tant qu'allié indispensable."},{t="L'éveil d'un saint guerrier",b="Delgren le Purificateur reçoit la lettre urgente de Balthule et la lit avec une sombre détermination. Dévoué à la Lumière sacrée, il considère les sombres sectateurs, les âmes corrompues et les créatures démoniaques dans ces bois anciens comme un fléau intolérable. La lettre signale que le Brin sombre est solidement implanté dans la tour bien-née en ruine. Delgren se prépare à prendre les choses en main et à riposter."}},faq={{q="Qui est Delgren le Purificateur ?",a="Delgren le Purificateur est un paladin humain en poste au Poste de Maestra, en Orneval. Dévoué à la Lumière sacrée, il met ses talents martiaux et spirituels au service des Sentinelles elfes de la nuit dans leur lutte contre les démons et les morts-vivants de leurs forêts ancestrales.",al={"delgren le purificateur","qui est delgren","histoire de delgren"}},{q="Pourquoi Balthule Frappelombre envoie-t-il un messager en Orneval ?",a="Balthule Frappelombre est un éclaireur près de la Tour d'Althalaxx, où il surveille la secte du Brin sombre. Alors que ses rituels maléfiques se multiplient et que ses rangs grossissent, il transmet ses découvertes à son mentor Delgren pour qu'ils organisent une attaque.",al={"pourquoi envoyer une lettre à delgren","raison de la lettre de balthule"}},{q="Quel lien unit Balthule et Delgren ?",a="Delgren est le maître de Balthule. Le paladin humain a enseigné à l'Elfe de la nuit l'art du combat et les préceptes de la Lumière sacrée. Leur lien est étroit malgré leurs différences culturelles.",al={"balthule et delgren","comment balthule et delgren se connaissent-ils"}},{q="Où se trouve le Poste de Maestra ?",a="Le Poste de Maestra est un avant-poste de l'Alliance dans l'ouest d'Orneval, près de la route principale qui vient de Sombrivage et mène vers le sud. Les voyageurs y passent en se rendant dans la forêt.",al={"emplacement du poste de maestra","où se trouve le poste de maestra"}},{q="Que fait la secte du Brin sombre à la Tour d'Althalaxx ?",a="La secte du Brin sombre opère depuis la Tour d'Althalaxx, une tour bien-née en ruine dans le nord de Sombrivage. Ses membres pratiquent les arts obscurs et s'allient à des puissances démoniaques. Ils menacent de répandre la corruption le long du rivage.",al={"secte du brin sombre althalaxx","sectateurs de la tour d'althalaxx"}},{q="Que pense Delgren de son alliance avec les Elfes de la nuit ?",a="À son arrivée en Kalimdor, Delgren trouvait les manières et les coutumes des Elfes de la nuit peu familières. En combattant à leurs côtés les mêmes ennemis, il a gagné le profond respect des Sentinelles.",al={"delgren et les elfes de la nuit","paladin humain et elfes de la nuit"}}},fx={["4ad41352"]={q="Pourquoi Balthule vous choisit-il comme messager au lieu d'y aller lui-même ?",a="Balthule doit rester en poste près de la tour d'Althalaxx pour garder un oeil vigilant sur les cultistes du Culte du Rivage sombre et surveiller leur menace croissante. Comme le voyage s'étend sur toute la longueur de Sombrivage jusqu'en Orneval, il a besoin d'un voyageur compétent et bien armé capable de survivre aux routes dangereuses et de garantir que l'avertissement urgent parvienne en toute sécurité entre les mains de Delgren le Purificateur.",al={"pourquoi m'envoyer vers delgren","pourquoi le messager de balthule","pourquoi balthule ne peut-il pas livrer la lettre"}}},fp="22,206,25.325.0,21.382.0,23.356.1,28.234.0,62.216.0,54.179.0,24.149.0,61.217.0,56.159.0"}
P.entries["quest:96770"] = {n="The Witch Doctor's Head",s="L'archimage Lan'dalock vous demande de tuer le docteur sorcier Sandfury Zum'rah dans Zul'Farrak et de rapporter sa tête intacte. Sa requête repose sur une vieille histoire entre Lan'dalock et le troll.",h="L'archimage Lan'dalock vous demande de tuer le docteur sorcier Sandfury Zum'rah dans Zul'Farrak et de...",kw={"dalaran","lan'dalock","sandfury","tanaris","troll","docteur sorcier","zul'farrak","zum'rah","zumrah"},sec={{t="La requête de Lan'dalock",b="L'archimage Lan'dalock, à Dalaran, veut la mort de Zum'rah. Le docteur sorcier se trouve dans Zul'Farrak, un bastion Sandfury au cœur de Tanaris. Lan'dalock dit avoir un passé avec Zum'rah et vous demande de revenir avec la tête intacte du troll. Sa requête découle de ce vieux grief."}},faq={{q="Qui est Zum'rah ?",a="Zum'rah est un docteur sorcier troll qui se trouve dans Zul'Farrak, le bastion Sandfury de Tanaris.",al={"zumrah","docteur sorcier zum'rah","docteur sorcier sandfury"}},{q="Qui veut la mort de Zum'rah ?",a="L'archimage Lan'dalock, à Dalaran, vous demande de tuer Zum'rah. Il dit avoir un passé avec le troll.",al={"qui a donné ça","lan'dalock","pourquoi tuer zumrah"}},{q="Où se trouve Zum'rah ?",a="Zum'rah se trouve dans Zul'Farrak, au cœur des déserts de Tanaris.",al={"où trouver zumrah","zul'farrak","troll de tanaris"}},{q="Pourquoi Lan'dalock veut-il le tuer ?",a="Lan'dalock dit avoir un passé avec Zum'rah, sans donner plus de détails.",al={"rancune de lan'dalock","pourquoi l'archimage veut-il la mort de zumrah","passé avec zumrah"}},{q="Que vous demande Lan'dalock de rapporter ?",a="Lan'dalock vous demande de lui rapporter la tête de Zum'rah intacte.",al={"que rapporter","tête de zumrah","tête intacte"}}},fp="23,181,20.267.0,15.86.0,23.95.0,17.61.0,36.73.0,43.55.0"}
P.entries["quest:96771"] = {n="Vengeance of the Highborne",s="Un commanditaire vous demande de retrouver Zalfan Moonshadow au Bastion Krol’dok, dans les Rives Claires. Il condamne les liens de Zalfan avec le Marteau du crépuscule et son usage de connaissances arcaniques volées.",h="Un commanditaire vous demande de retrouver Zalfan Moonshadow au Bastion Krol’dok, dans les Rives Claires.",kw={"highborne","bastion krol’dok","rives claires","connaissances arcaniques volées","marteau du crépuscule","vengeance des highborne","zalfan moonshadow"},sec={{t="Un Highborne dans les Glades",b="Un commanditaire vous indique le sud-est, vers le Bastion Krol’dok, dans les Rives Claires, où Zalfan Moonshadow aurait été aperçu avec le Marteau du crépuscule. Il traite Zalfan de honte pour les Highborne et l’accuse de servir des fanatiques avec des connaissances arcaniques volées. Le commanditaire offre une généreuse récompense pour la mort de Zalfan."}},faq={{q="Qui est Zalfan Moonshadow ?",a="Zalfan Moonshadow est un Highborne aperçu au Bastion Krol’dok avec le Marteau du crépuscule.",al={"zalfan","qui est zalfan"}},{q="Où se trouve Zalfan ?",a="Zalfan aurait été aperçu au Bastion Krol’dok, dans les Rives Claires, au sud-est d’ici.",al={"où est zalfan","emplacement du bastion krol’dok"}},{q="Pourquoi le commanditaire veut-il la mort de Zalfan ?",a="Le commanditaire dit que Zalfan fait honte aux Highborne en fréquentant le Marteau du crépuscule et en utilisant à leur service des connaissances arcaniques volées.",al={"pourquoi tuer zalfan","problème de zalfan"}},{q="Que propose le commanditaire ?",a="Le commanditaire offre une généreuse récompense à quiconque tuera Zalfan Moonshadow.",al={"récompense pour zalfan","prime sur zalfan"}}},fp="26,173,25.297.0,25.88.0,16.82.0,37.145.0,27.69.0"}
P.entries["quest:96773"] = {n="The Coldbringer's Eye",s="Le Kirin Tor recherche le Coldbringer’s Eye, un orbe de divination utilisé par un serviteur du Lich King dans les Souilles de Tranchebauge. On vous demande de le récupérer pour que l’artefact puisse être étudié.",h="Le Kirin Tor recherche le Coldbringer’s Eye, un orbe de divination utilisé par un serviteur du Lich King dans...",kw={"coldbringer","coldbringer's eye","kirin tor","lich king","huran","souilles de tranchebauge","orbe de divination","serviteur"},sec={{t="Une requête du Kirin Tor",b="Un serviteur du Lich King demeure dans les Souilles de Tranchebauge, où le repaire des hurans lui sert de refuge. Le Kirin Tor affirme qu’il utilise le Coldbringer’s Eye pour diriger des serviteurs inférieurs en d’autres lieux. On vous demande de récupérer l’orbe pour que le Kirin Tor puisse l’étudier."}},faq={{q="Qu’est-ce que le Coldbringer’s Eye ?",a="Le Coldbringer’s Eye est un orbe de divination utilisé par un serviteur du Lich King dans les Souilles de Tranchebauge.",al={"coldbringer eye","qu’est-ce que l’œil","orbe de divination"}},{q="Qui veut le Coldbringer’s Eye ?",a="Le Kirin Tor veut le Coldbringer’s Eye pour étudier l’artefact et comprendre son fonctionnement.",al={"qui veut l’orbe","œil kirin tor","qui l’a demandé"}},{q="Où se trouve le Coldbringer’s Eye ?",a="Le Coldbringer’s Eye se trouve dans les Souilles de Tranchebauge.",al={"où est l’œil","orbe des souilles de tranchebauge","emplacement de l’œil"}},{q="Qui utilise l’orbe ?",a="Un serviteur du Lich King dans les Souilles de Tranchebauge utilise l’orbe pour diriger des serviteurs inférieurs en d’autres lieux.",al={"qui possède l’œil","serviteur du lich king","utilisateur de coldbringer"}}},fp="21,172,19.228.0,32.94.0,34.101.0,33.45.0,17.93.0"}
P.entries["quest:96775"] = {n="Zum'rah's Head",s="Mazu'kon vous demande de chasser Zum'rah à Zul'Farrak, où le sorcier-docteur pratique le vaudou. Il veut que vous rapportiez la tête de Zum'rah à Mulgore.",h="Mazu'kon vous demande de chasser Zum'rah à Zul'Farrak, où le sorcier-docteur pratique le vaudou.",kw={"tête","mazu'kon","mulgore","sandfury","tanaris","sorcier-docteur","zul'farrak","zum'rah"},sec={{t="Une chasse à Tanaris",b="Mazu'kon, à Mulgore, vous envoie au sud, à Zul'Farrak, une cité Sandfury de Tanaris. Zum'rah est un sorcier-docteur qui y pratique le vaudou, et Mazu'kon veut que vous le tuiez. Vous devez rapporter la tête du sorcier-docteur à Mulgore."}},faq={{q="Qui est Zum'rah ?",a="Zum'rah est un sorcier-docteur qui pratique le vaudou dans la cité Sandfury de Zul'Farrak.",al={"qui est zum'rah","sorcier-docteur zum'rah"}},{q="Où trouver Zum'rah ?",a="Zum'rah se trouve à Zul'Farrak, une cité Sandfury de Tanaris.",al={"emplacement de zum'rah","où se trouve zum'rah"}},{q="Qui me demande de chasser Zum'rah ?",a="Mazu'kon, à Mulgore, vous demande de tuer Zum'rah et de rapporter sa tête.",al={"quête de mazu'kon","qui veut la mort de zum'rah"}},{q="Que veut Mazu'kon que je rapporte ?",a="Mazu'kon veut que vous lui rapportiez la tête de Zum'rah à Mulgore.",al={"tête de zum'rah","rapporter sa tête"}}},fp="14,142,17.220.0,15.82.0,25.53.0,28.69.0,41.58.0"}
P.entries["quest:96781"] = {n="What's the Big Idea?",s="Myrokos Silentform, au Manoir de Ravenholdt, vous demande de découvrir ce que le Syndicat cherche dans les Ruines d’Alterac. Barton détient les rapports d’éclaireur qui pourraient révéler leurs intentions.",h="Myrokos Silentform, au Manoir de Ravenholdt, vous demande de découvrir ce que le Syndicat cherche dans les...",kw={"barton","myrokos silentform","manoir de ravenholdt","ruines d'alterac","rapport d’éclaireur","strahnbrande","syndicat"},ang={["class:Rogue"]="En tant que voleur, vous devez dérober le rapport de Barton sans le tuer."},sec={{t="Rapport de Barton",b="Au Manoir de Ravenholdt, Myrokos Silentform a besoin du rapport d’éclaireur de Barton. Une troupe du Syndicat menée par Barton rôde dans les Ruines d’Alterac à la recherche de quelque chose. On vous demande de lui dérober le rapport sans le tuer, afin que le Syndicat ignore que ses plans ont éveillé l’attention."}},faq={{q="Qui est Barton ?",a="Barton dirige une troupe d’éclaireurs du Syndicat qui rôde dans les Ruines d’Alterac.",al={"barton","qui est barton","éclaireur du syndicat"}},{q="Que cherche le Syndicat ?",a="La troupe du Syndicat cherche quelque chose dans les Ruines d’Alterac, mais Myrokos a besoin du rapport d’éclaireur de Barton pour savoir quoi.",al={"que cherche le syndicat","que cherchent-ils","recherche du syndicat"}},{q="Pourquoi Myrokos veut-il le rapport ?",a="Myrokos Silentform veut le rapport pour découvrir ce que cherche le Syndicat.",al={"pourquoi prendre le rapport","rapport de barton","grande idée"}},{q="Pourquoi ne pas tuer Barton ?",a="Si Barton meurt, le Syndicat comprendra qu’on le surveille et pourrait prendre des mesures pour brouiller les pistes.",al={"ne pas tuer barton","détrousser barton","pourquoi voler le rapport"}},{q="Où trouver Barton ?",a="Barton se trouve probablement parmi les membres du Syndicat à Strahnbrande.",al={"où trouver barton","trouver barton","éclaireur de strahnbrande"}},{q="À qui remettre le rapport ?",a="Le rapport d’éclaireur de Barton est destiné à Myrokos Silentform, au Manoir de Ravenholdt.",al={"qui reçoit le rapport","où apporter le rapport","myrokos"}}},fp="20,173,17.280.0,14.77.0,36.129.0,33.81.0,20.107.0,26.56.0,25.77.0"}
P.entries["quest:96783"] = {n="A Way In",s="Une transaction du Syndicat vous mène au Donjon de Stromgarde, dans les Hautes-terres Arathies. Il vous faut un déguisement du Manoir de Nordclos pour entrer sans éveiller les soupçons.",h="Une transaction du Syndicat vous mène au Donjon de Stromgarde, dans les Hautes-terres Arathies.",kw={"un moyen d’entrer","hautes-terres arathies","manoir de nordclos","donjon de stromgarde","syndicat","transaction","uniforme"},sec={{t="Une transaction secrète",b="Un contact vous envoie au Donjon de Stromgarde, dans les Hautes-terres Arathies, où le Syndicat mène d’importantes tractations à l’abri de ses murs. Votre contact a eu vent d’une transaction entre des membres du Syndicat, et ses détails pourraient se trouver dans le donjon. Pour entrer sans éveiller les soupçons, il vous faut un uniforme du Syndicat provenant du Manoir de Nordclos."}},faq={{q="Que se passe-t-il au Donjon de Stromgarde ?",a="Le Syndicat fait du Donjon de Stromgarde l’un de ses principaux bastions, et une transaction entre ses membres a lieu quelque part dans les Hautes-terres Arathies.",al={"transaction à stromgarde","que se passe-t-il à stromgarde","donjon du syndicat"}},{q="Pourquoi dois-je aller au Manoir de Nordclos ?",a="Vous cherchez un uniforme du Syndicat au Manoir de Nordclos pour vous déguiser avant d’entrer dans le Donjon de Stromgarde.",al={"manoir de nordclos","pourquoi northfold","obtenir un déguisement"}},{q="De quoi ai-je besoin pour entrer dans le donjon ?",a="Il vous faut un uniforme du Syndicat provenant du Manoir de Nordclos pour entrer dans le Donjon de Stromgarde sans éveiller les soupçons.",al={"uniforme","déguisement du syndicat","entrer dans stromgarde"}},{q="Sur quoi porte la transaction du Syndicat ?",a="La transaction se déroule entre des membres du Syndicat, quelque part dans les Hautes-terres Arathies. Ses détails pourraient se trouver dans le Donjon de Stromgarde.",al={"transaction du syndicat","quelle transaction","détails de la transaction"}}},fp="8,144,14.314.0,37.152.0,34.112.0,33.102.0,34.122.0"}
P.entries["quest:968"] = {n="Les outils des Bien-nés",s="Thundris Windweaver vous envoie d’Auberdine à Ameth'Aran. Des esprits des Bien-nés hantent toujours les ruines, leurs reliques enchantées à la main, et il veut les récupérer.",h="Thundris Windweaver vous envoie d’Auberdine à Ameth'Aran.",kw={"ameth'aran","auberdine","sombrivage","bien-nés","reliques","sundering","thundris windweaver"},ang={["class:Druid"]="En tant que druide, vous aidez à éliminer les vestiges arcaniques corrompus d’Ameth'Aran et à apaiser les blessures spirituelles qui troublent la tranquillité naturelle de Sombrivage.",["class:Mage"]="En tant que mage, vous reconnaîtrez peut-être dans ces reliques de rares exemples intacts du savoir-faire des Bien-nés, datant d’avant le Sundering. Pourtant, les kaldorei cherchent à les détruire.",["faction:Alliance"]="En tant que membre de l’Alliance, vous aidez les elfes de la nuit à sécuriser leurs terres hantées et à renforcer la présence et la solidarité de l’Alliance dans les anciennes forêts du nord de Kalimdor.",["race:NightElf"]="En tant que kaldorei, les fantômes d’Ameth'Aran vous rappellent l’hubris de vos ancêtres et le Sundering qui a brisé leur empire."},sec={{t="Échos dans les ruines",b="Ameth'Aran se trouve au sud d’Auberdine et à l’est de la route côtière. Ses fondations de pierre sont envahies par la végétation. Il y a dix mille ans, c’était un bastion des Bien-nés, l’aristocratie privilégiée de l’ancien empire des elfes de la nuit.\n\nLeur magie des arcanes débridée a contribué au Sundering, qui a détruit la colonie. Pourtant, ses habitants ne sont jamais vraiment partis. Les Sentinels qui patrouillent à Sombrivage signalent la présence de fantômes des Bien-nés sur les places englouties, serrant toujours les outils et les babioles enchantés qu’ils possédaient de leur vivant."},{t="Purifier le passé arcanique",b="Pour les kaldorei, la magie des arcanes rappelle un danger qui a failli détruire toute vie sur Azeroth. Thundris Windweaver craint que les outils des Bien-nés n’attirent la corruption s’ils restent entre les mains des fantômes. Il vous envoie donc arracher les reliques aux esprits agités. Il compte les détruire avant que leur magie corrompue ne provoque une nouvelle catastrophe."}},faq={{q="Où trouver les reliques des Bien-nés ?",a="Les reliques se trouvent à Ameth'Aran, au sud d’Auberdine et à l’est du chemin principal de Sombrivage. Des esprits errants les transportent dans les cours en ruines.",al={"où trouver les reliques","emplacement d’ameth'aran"}},{q="Qui est Thundris Windweaver ?",a="Thundris Windweaver est un érudit et ancien elfe de la nuit qui vit à Auberdine. Il travaille avec les Sentinels locaux pour protéger Sombrivage des résidus magiques persistants et des anciennes malédictions laissées par le Sundering.",al={"thundris windweaver","qui donne les outils des bien-nés"}},{q="Pourquoi Thundris veut-il détruire ces reliques ?",a="Thundris craint que le pouvoir arcanique des reliques ne réveille des maux endormis. La société des elfes de la nuit rejette la magie des arcanes, car la sorcellerie inconsidérée des Bien-nés a provoqué le Grand Sundering.",al={"pourquoi détruire les reliques","but des outils des bien-nés"}},{q="Quels esprits hantent Ameth'Aran ?",a="Ce sont des aristocrates des Bien-nés morts pendant la guerre des Anciens. Ils s’accrochent encore à leur orgueil, à leur pouvoir et à leurs objets magiques, rejouant leur ancienne vie parmi les ruines.",al={"fantômes à ameth'aran","que sont les esprits"}},{q="Pourquoi les Bien-nés sont-ils toujours liés aux ruines ?",a="Thundris ignore pourquoi les Bien-nés restent liés à Ameth'Aran. Les Sentinels lui ont seulement dit que les esprits persistent parmi les ruines et manient toujours leurs anciens outils magiques.",al={"pourquoi sont-ils des fantômes","malédiction des bien-nés"}},{q="Que deviennent les reliques après leur remise ?",a="Thundris Windweaver prend les reliques sous sa garde et prévoit de les démanteler et de les détruire. Il veut s’assurer que leur corruption arcanique latente ne puisse plus jamais être exploitée ni libérée.",al={"que fait thundris des reliques","sort des reliques"}}},fx={df86da6d={q="Que sont les Relique de bien-Né ?",a="Ces reliques sont d'anciens outils magiques préservés depuis avant la Grande Fracture, autrefois maniés par les sorciers d'élite de la cour de la reine Azshara. Même après dix mille ans, elles conservent la trace de la souillure des manipulations arcaniques imprudentes qui ont déchiré l'ancien Kalimdor. Laissées entre les mains de fantômes persistants, elles demeurent des vecteurs d'une puissance latente et dangereuse.",al={"que sont les reliques de bien-né","qu'est-ce qu'une relique de bien-né","lore des reliques de bien-né"}}},fp="22,167,19.507.0,23.350.0,37.149.0,27.204.0,46.169.0,38.187.0,47.192.0,50.176.0"}
P.entries["quest:96800"] = {n="Past Due",s="Un érudit a besoin d’un tome manquant au Monastère écarlate pour étudier les anciens maîtres des runes Wildhammer de Grim Batol.",h="Un érudit a besoin d’un tome manquant au Monastère écarlate pour étudier les anciens maîtres des runes...",kw={"arcaniste doan","bibliothèque de dalaran","grim batol","past due","monastère écarlate","la magie perdue des maîtres des runes","maîtres des runes wildhammer"},sec={{t="Un livre en retard",b="Les registres de l’ancienne bibliothèque de Dalaran indiquent que l’Arcaniste Doan a emprunté le tome avant la troisième guerre et ne l’a jamais rendu."}},faq={{q="Qui a besoin du livre ?",a="Un érudit rédige une thèse sur les anciens maîtres des runes Wildhammer de Grim Batol et a besoin du livre pour ses recherches.",al={"qui veut le tome","recherches de l’érudit"}},{q="Quel livre a été emprunté ?",a="Le livre emprunté s’intitule La Magie perdue des maîtres des runes.",al={"quel tome","livre perdu des maîtres des runes"}},{q="Qui a emprunté le livre ?",a="Les registres de l’ancienne bibliothèque de Dalaran indiquent qu’un mage nommé Doan a emprunté le livre avant la troisième guerre.",al={"qui l’a emprunté","livre de doan"}},{q="Où se trouve le livre ?",a="Le livre se trouve au Monastère écarlate, dans les Clairières de Tirisfal, où se trouve désormais l’Arcaniste Doan.",al={"où est le tome","lieu où se trouve le livre"}},{q="Quel est le sujet des recherches ?",a="L’érudit étudie les anciens maîtres des runes Wildhammer de Grim Batol.",al={"maîtres des runes wildhammer","thèse sur grim batol"}}},fp="8,113,15.121.0,19.112.0,23.62.0,22.97.0,18.84.0,27.76.0"}
P.entries["quest:96821"] = {n="Legging It",s="Les péons ont interrompu leur voyage vers le sud, car des dangers bordent la route. Leur travail attendra que la voie soit de nouveau sûre.",h="Les péons ont interrompu leur voyage vers le sud, car des dangers bordent la route.",kw={"chemin dégagé","main-d'œuvre de la horde","legging it","surveillant","travail des péons","péons","chemin du sud"},ang={["faction:Horde"]="La construction et la récolte de ressources de la Horde reposent largement sur les péons, dont les itinéraires doivent donc rester sûrs.",["race:Orc"]="Les péons accomplissent une grande partie du travail dans les implantations orques. Les contremaîtres comptent sur les guerriers pour éliminer les menaces sur leurs chemins afin que le travail puisse continuer."},sec={{t="Sécuriser la voie",b="Les péons ont laissé leurs tâches inachevées et cessé de voyager vers le sud. Les périls qui jalonnent la route ont rendu le voyage trop dangereux. Une fois les menaces repoussées, les contremaîtres pourront renvoyer leurs équipes au travail."},{t="Main-d'œuvre et sécurité de l'itinéraire",b="Les péons accomplissent une grande partie des travaux pénibles de la Horde, de l’abattage du bois à l’extraction de pierre et à la construction d’avant-postes. Ils sont peu doués au combat, si bien que des prédateurs ou des éclaireurs hostiles en bord de route peuvent interrompre l’acheminement des provisions. Des voies dégagées assurent le ravitaillement des implantations et permettent au travail de continuer."}},faq={{q="Qu'est-ce que Legging It ?",a="Les dangers qui jalonnent la route ont dissuadé les péons de voyager vers le sud. Leurs tâches attendront que la voie soit sûre.",al={"qu'est-ce que legging it","informations sur la quête legging it","quête legging it"}},{q="Pourquoi les péons avaient-ils peur de voyager vers le sud ?",a="Les péons craignent les dangers qui jalonnent la route du sud. Sans protection ni chemin dégagé, ils refusent de rejoindre leur lieu de travail, paralysant ainsi les activités locales.",al={"pourquoi les péons avaient-ils peur","peur des péons","pourquoi les péons ont cessé de travailler"}},{q="Qu'accomplit-on en terminant la tâche ?",a="Lorsque la route du sud sera dégagée et les dangers immédiats repoussés, les contremaîtres pourront envoyer les péons récolter des ressources et travailler sur le terrain.",al={"que se passe-t-il après legging it","dénouement de legging it","résultat du dégagement du chemin"}},{q="Qui sont les péons mentionnés dans la tâche ?",a="Les péons constituent la main-d’œuvre de la Horde. Ils coupent du bois, extraient du minerai et bâtissent des fortifications. Ils sont essentiels aux implantations, mais peu aptes au combat, et battent facilement en retraite devant le danger.",al={"qui sont les péons","rôle des péons","que font les péons"}},{q="Où se rendaient les péons ?",a="Les péons voyageaient vers le sud, sur un chemin menant à des chantiers éloignés et à des gisements de ressources nécessitant un entretien régulier. Le voyage était devenu assez dangereux pour interrompre toute circulation.",al={"où mène le chemin","chemin du sud","direction le sud"}},{q="Pourquoi les péons ont-ils besoin d'aventuriers pour dégager leurs itinéraires ?",a="Les péons n’ont ni formation militaire ni équipement de combat, ce qui les rend vulnérables aux prédateurs sauvages et aux forces hostiles. Les contremaîtres comptent sur des aventuriers expérimentés pour éliminer les menaces et sécuriser les voies d’accès aux chantiers.",al={"pourquoi les péons ont besoin de protection","sécurité des péons","protéger les péons"}}},fp="10,121,17.210.0,24.276.0,19.112.0,42.162.0,44.139.0,40.185.0,31.177.0,55.199.0"}
P.entries["quest:96822"] = {n="For Honor",s="Les guerriers tombés vivent dans les mémoires grâce à For Honor. Leurs sacrifices perdurent dans l’esprit de ceux qui se souviennent d’eux.",h="Les guerriers tombés vivent dans les mémoires grâce à For Honor.",kw={"guerriers tombés","for honor","honneur","mémorial","quête","souvenir","guerrier"},ang={["class:Warrior"]="En tant que guerrier, vous connaissez le poids des sacrifices sur le champ de bataille. Se souvenir des combattants tombés garde leurs actes vivants."},sec={{t="Un devoir de mémoire",b="Ceux qui survivent aux guerriers tombés perpétuent leur mémoire. Se souvenir de ceux qui ont tout donné est un devoir."},{t="Préserver l’héritage",b="Vos efforts gardent le souvenir des combattants tombés vivant. Ceux qui se souviennent d’eux continuent d’honorer leurs sacrifices."}},faq={{q="De quoi parle la quête For Honor ?",a="For Honor vous demande de vous souvenir des combattants tombés. Vos efforts empêchent leurs sacrifices de tomber dans l’oubli.",al={"que signifie for honor","résumé de la quête for honor"}},{q="Qui sont les guerriers mentionnés à la fin de la quête ?",a="Ce sont des combattants tombés au combat, honorés pour leurs actes. Vos actions préservent leur mémoire et le service qu’ils ont rendu.",al={"qui sont les guerriers","qui est commémoré"}},{q="Pourquoi est-il important d’honorer ces guerriers ?",a="Se souvenir des guerriers tombés donne de la dignité à leur sacrifice. Leur courage reste ainsi reconnu.",al={"pourquoi faire cette quête","signification de for honor"}},{q="Qui demande que cette tâche soit accomplie ?",a="Une personne qui souhaite se souvenir de ses compagnons tombés vous confie cette tâche. À votre retour, elle confirme qu’elle est accomplie et rend hommage à leur mémoire.",al={"qui confie for honor","donneur de quête de for honor"}},{q="Cette quête mène-t-elle à d’autres tâches ?",a="Rien n’indique qu’il y ait d’autres tâches à accomplir. For Honor rend hommage aux combattants tombés et à leurs sacrifices.",al={"for honor fait-elle partie d’une suite de quêtes","que faire après for honor"}},{q="Que signifie le titre For Honor ?",a="For Honor désigne le devoir de se souvenir des soldats tombés. Pour tout combattant, garder leur sacrifice et leur mémoire du champ de bataille vivants est un devoir solennel.",al={"qu’est-ce qui rend cela honorable","signification de for honor"}}},fp="9,117,21.110.0,21.114.0,34.95.0,47.119.0,41.95.0,34.140.0,36.86.0,38.143.0"}
P.entries["quest:96825"] = {n="This Fruit Could Bite Back",s="À Durotar, les figues de barbarie nourrissent Orgrimmar et promettent davantage de nourriture à l’avenir. Récoltés avec soin, ces fruits résistants peuvent nourrir la capitale de la Horde et fournir des graines pour les cultures futures.",h="À Durotar, les figues de barbarie nourrissent Orgrimmar et promettent davantage de nourriture à l’avenir.",kw={"fruit de cactus","durotar","fruit","orgrimmar","figue de barbarie","figues de barbarie","graines","this fruit could bite back"},ang={["faction:Horde"]="En tant que membre de la Horde, vous savez que des sources de nourriture durables, comme les fruits nourrissants du désert, peuvent aider à nourrir Orgrimmar et la population grandissante de la Horde.",["profession:Cooking"]="En tant que cuisinier, vous pouvez préparer des plats à base de figues de barbarie, et ces fruits peuvent aussi nourrir les habitants de la ville.",["profession:Herbalism"]="En tant qu’herboriste, vous savez à quel point les plantes du désert peuvent être résistantes et combien d’efforts demande la récolte de fruits sauvages épineux destinés à la culture."},sec={{t="Récolter dans les terres arides",b="Durotar est une terre rude et écrasée de soleil, où l’agriculture traditionnelle est presque impossible. Ses figues de barbarie résistantes prospèrent dans le sol aride, alors les habitants les récoltent pour contribuer à nourrir Orgrimmar. Leurs épines protectrices imposent de prendre des précautions, et leurs fruits apportent une nourriture indispensable."},{t="Culture et subsistance",b="Les figues de barbarie nourrissent les habitants dès aujourd’hui et peuvent contribuer à l’approvisionnement alimentaire des années à venir. Leur chair sert à préparer des plats, tandis que leurs graines sont soigneusement conservées pour être plantées. L’objectif est de faire pousser cette culture résistante autour d’Orgrimmar, afin de créer une source durable de nourriture juste à l’extérieur des murs de la forteresse."}},faq={{q="Qu’est-ce que This Fruit Could Bite Back ?",a="Vous récoltez des figues de barbarie sauvages à Durotar pour les cuisiner et en conservez les graines afin de les planter dans les terres arides autour d’Orgrimmar.",al={"qu’est-ce que this fruit could bite back","quête this fruit could bite back","quête du fruit qui mord"}},{q="Pourquoi récolter des figues de barbarie ?",a="Les figues de barbarie fournissent de quoi préparer des repas locaux, et leurs graines sont conservées pour les plantations. L’objectif est de les faire pousser dans les terres arides autour d’Orgrimmar.",al={"pourquoi récolter des figues de barbarie","utilité des figues de barbarie","à quoi servent les figues de barbarie"}},{q="Où les graines seront-elles plantées ?",a="Les graines doivent être plantées dans les environs et les terres autour d’Orgrimmar, où elles contribueront à établir une source de nourriture résistante dans le sol désertique hostile.",al={"où faire pousser des figues de barbarie","plantation de figues de barbarie à orgrimmar"}},{q="Qui veut que ces fruits soient récoltés ?",a="Un habitant local souhaite que la récolte améliore les réserves de nourriture locales, nourrisse les voyageurs et permette de cultiver des plantes adaptées au climat désertique rigoureux de Durotar.",al={"qui veut les figues de barbarie","donneur de quête du fruit qui mord"}},{q="Pourquoi le fruit « mord-il » ?",a="Les figues de barbarie portent des épines acérées et des aiguillons, comme les autres cactus résistants du désert. Les cueilleurs doivent donc prendre des précautions.",al={"pourquoi mordre en retour","pourquoi le fruit mord-il"}},{q="Pourquoi est-il important de planter des fruits autour d’Orgrimmar ?",a="Durotar est surtout aride et rocheux, ce qui rend l’agriculture traditionnelle difficile. Les figues de barbarie résistantes à la sécheresse pourraient contribuer à assurer un approvisionnement durable en nourriture pour Orgrimmar.",al={"orgrimmar manque-t-elle de nourriture","agriculture à orgrimmar","agriculture à durotar"}}},fp="26,174,26.262.0,26.288.0,35.120.0,37.146.0,32.166.0,32.137.0,31.103.0,49.159.0"}
P.entries["quest:96873"] = {n="A Pain in the Neck",s="Pa'zula vous demande de dissiper la magie des liens des pendentifs dont Zalazane se sert pour contrôler les trolls des Îles de l'Écho. Le résidu pourrait libérer leurs esprits de l'emprise du docteur sorcier.",h="Pa'zula vous demande de dissiper la magie des liens des pendentifs dont Zalazane se sert pour contrôler les...",kw={"un vrai casse-tête","sorts de lien","îles de l'écho","hexed pendants","résidu lumineux","pa'zula","village de sen'jin","zalazane"},ang={["profession:Tailoring"]="En tant qu'enchanteur, vous exercez votre art en dissipant les sorts de lien des Hexed Pendants pour Pa'zula."},sec={{t="La demande de Pa'zula",b="Pa'zula, au Village de Sen'jin, a besoin du résidu des Hexed Pendants. Zalazane utilise des sorts de lien sur ces pendentifs pour garder ses prisonniers sous son contrôle. Vous devez dissiper cette magie et rapporter à Pa'zula ce qu'il en reste. La liberté des trolls est en jeu."},{t="Les pendentifs",b="Pa'zula explique que les sorts de lien retiennent l'esprit des trolls et vous met en garde contre le port d'un pendentif. À votre retour avec le résidu, Pa'zula affirme que les sorts ont été dissipés et que les esprits des trolls tués peuvent reposer en paix."}},faq={{q="Qui demande le résidu ?",a="Pa'zula, au Village de Sen'jin, vous demande de rapporter le résidu des Hexed Pendants.",al={"qui veut le résidu","demande de pa'zula"}},{q="Que fait Zalazane avec les pendentifs ?",a="Zalazane utilise des sorts de lien sur les pendentifs pour garder l'esprit de ses prisonniers sous son contrôle.",al={"pendentifs de zalazane","hexed pendants"}},{q="Où trouve-t-on les Hexed Pendants ?",a="Les trolls des Îles de l'Écho portent les Hexed Pendants.",al={"emplacement des pendentifs","où trouver les pendentifs"}},{q="Qu'est-ce que le Résidu lumineux ?",a="Le Résidu lumineux s'obtient en dissipant la magie des Hexed Pendants.",al={"résidu des pendentifs","substance lumineuse"}},{q="Pourquoi Pa'zula veut-elle que la magie des pendentifs soit dissipée ?",a="Pa'zula affirme que dissiper les sorts de lien permet aux esprits des trolls tués de reposer en paix.",al={"pourquoi dissiper les pendentifs","libérer les esprits des trolls"}}},fp="18,175,17.241.0,12.215.1,30.77.0,40.88.0,35.59.0,25.72.0,48.77.0"}
P.entries["quest:96874"] = {n="This Is Spinal Axe",s="À Orgrimmar, Ug’thok vous demande de récolter des épines sur les bêtes géantes des Falaises du Tonnerre. Il espère en façonner une tête de hache pour vos leçons de forge.",h="À Orgrimmar, Ug’thok vous demande de récolter des épines sur les bêtes géantes des Falaises du Tonnerre.",kw={"tête de hache","orgrimmar","pierres à aiguiser grossières","saru","forge","falaises du tonnerre","ug’thok","épines usées"},ang={["profession:Blacksmithing"]="En tant qu’apprenti forgeron, vous aidez Ug’thok à réunir les matériaux pour une tête de hache qu’il espère fabriquer."},sec={{t="Une idée de forgeron",b="Ug’thok vous demande cinq épines usées et cinq pierres à aiguiser grossières. Il pense que les épines pourraient faire une belle tête de hache, même si Saru s’est moqué de cette idée."},{t="Un matériau résistant",b="Les épines sont plus résistantes que Ug’thok ne le pensait, ce qui pourrait les rendre difficiles à travailler. Il compte poursuivre la mise au point de son modèle."}},faq={{q="Qui demande les épines ?",a="Ug’thok, à Orgrimmar, vous demande de récolter des épines usées et des pierres à aiguiser grossières.",al={"qui veut des épines","hache d’ug’thok","leçon de forge"}},{q="Que veut fabriquer Ug’thok ?",a="Ug’thok espère fabriquer une tête de hache avec les épines des bêtes.",al={"hache en épines","que fabrique-t-il","idée de tête de hache"}},{q="D’où viennent les épines ?",a="Les épines usées proviennent des bêtes géantes des Falaises du Tonnerre.",al={"où trouver les épines","bêtes des falaises du tonnerre","emplacement des épines"}},{q="De quoi Ug’thok a-t-il besoin d’autre ?",a="Ug’thok demande aussi des pierres à aiguiser grossières, en plus des épines.",al={"pierres à aiguiser nécessaires","quels matériaux","pierres grossières"}},{q="Pourquoi Ug’thok veut-il ces matériaux ?",a="Ug’thok veut essayer de fabriquer une tête de hache avec les épines, dans le cadre de vos leçons de forge.",al={"pourquoi des épines","à quoi servent-elles","matériaux d’ug’thok"}}},fp="18,154,16.165.0,14.123.1,29.85.0,33.62.0,30.64.0,30.63.0,38.91.0"}
P.entries["quest:96875"] = {n="Beasts of Thunder Ridge",s="Dans tout Durotar, les bâtisseurs d’Orgrimmar ont besoin de peaux pour consolider la capitale en pleine expansion. Kamari vous envoie aux Falaises du Tonnerre chercher des peaux de lézard et des cured light hides.",h="Dans tout Durotar, les bâtisseurs d’Orgrimmar ont besoin de peaux pour consolider la capitale en pleine...",kw={"beasts of thunder ridge","cured light hide","durotar","kamari","travail du cuir","orgrimmar","péons","peau de lézard grossière","falaises du tonnerre"},ang={["faction:Horde"]="Alors que la Horde s’installe à Durotar, les ressources sauvages contribuent à fortifier et à agrandir Orgrimmar.",["race:Orc"]="En tant qu’orc, vous savez que les éléments de Durotar exigent des matériaux robustes, récoltés par les chasseurs et les ouvriers."},sec={{t="Une capitale en pleine croissance",b="Orgrimmar ne cesse de s’étendre tandis que la Horde s’installe à Durotar. Les nouvelles habitations, les ateliers et les défenses nécessitent du bois, de la pierre et des peaux d’animaux. Le bois vient de contrées plus lointaines, mais les bêtes de Durotar fournissent des peaux solides aux péons et aux bâtisseurs."},{t="Les bêtes du canyon",b="Les lézards des Falaises du Tonnerre ont eux aussi la peau dure, trop épaisse et rigide pour en faire des armures. Correctement prélevées, leurs peaux tapissent les murs et les plafonds des bâtiments de bois et de pierre d’Orgrimmar. Elles protègent ainsi l’intérieur du soleil ardent et des vents soudains du canyon."}},faq={{q="Pourquoi Orgrimmar a-t-elle besoin de peaux de lézard des Falaises du Tonnerre ?",a="Les peaux des lézards des Falaises du Tonnerre sont trop épaisses et grossières pour en faire des armures, mais leur robustesse convient aux constructions. Les péons d’Orgrimmar en tapissent les murs et les toits pour les protéger des éléments.",al={"à quoi servent les peaux","pourquoi des peaux de lézard grossières","utilisation des peaux des falaises du tonnerre"}},{q="Qui est Kamari ?",a="Kamari est un travailleur du cuir à Orgrimmar. Il fournit aux bâtisseurs et aux péons de la ville des peaux et des fourrures solides, nécessaires aux travaux de construction en cours.",al={"qui est kamari","kamari à orgrimmar","qui donne bêtes des falaises du tonnerre"}},{q="Où se trouvent les Falaises du Tonnerre ?",a="Les Falaises du Tonnerre sont un canyon accidenté de Durotar, où vivent des lézards à la peau épaisse que Kamari veut pour les nouveaux bâtiments d’Orgrimmar.",al={"où se trouvent les falaises du tonnerre","emplacement des falaises du tonnerre","falaises du tonnerre durotar"}},{q="Pourquoi demande-t-on aussi des cured light hides ?",a="Kamari demande des cured light hides en plus des lourdes peaux de lézard pour compléter ces matériaux. Cette requête met aussi à l’épreuve votre connaissance et votre savoir-faire dans le travail du cuir.",al={"pourquoi des cured light hides","à quoi servent les peaux traitées"}},{q="Pourquoi Orgrimmar s’agrandit-elle si rapidement ?",a="Orgrimmar est la capitale récemment fondée de la Horde, et les travaux en cours doivent loger un nombre croissant d’orcs et de leurs alliés. Cette croissance entraîne un besoin constant en matières premières.",al={"pourquoi orgrimmar se construit-elle","expansion d’orgrimmar"}},{q="Peut-on fabriquer des armures avec les peaux des lézards des Falaises du Tonnerre ?",a="Les peaux des lézards des Falaises du Tonnerre sont généralement trop épaisses et rigides pour des armures souples. Elles servent surtout aux constructions.",al={"peut-on porter des peaux de lézard","armure en peau de lézard grossière"}}},fp="23,157,17.236.0,20.266.0,56.205.0,14.155.0,31.119.0,60.180.0,38.186.0,59.126.0"}
P.entries["quest:96876"] = {n="Sac perdu d’Ukor",s="Dans le sud de Durotar, le sac perdu d'Ukor gît, abandonné dans les contrées sauvages. Son propriétaire a fui une araignée gigantesque et laissé ses provisions derrière lui.",h="Dans le sud de Durotar, le sac perdu d'Ukor gît, abandonné dans les contrées sauvages.",kw={"durotar","horde","sac perdu","sud de durotar","araignée","ukor","sac perdu d'ukor"},ang={["faction:Horde"]="Les jeunes aventuriers de la Horde qui s'aventurent dans le sud de Durotar aident fréquemment les habitants comme Ukor, prouvant leur valeur et leur fiabilité en récupérant des effets personnels perdus face à une faune dangereuse."},sec={{t="Un bien égaré",b="En traversant les étendues sauvages et arides du sud de Durotar, un aventurier tombe sur un sac de voyage abandonné avec le nom « Ukor » grossièrement cousu sur son rabat. Survivre dans les terres rudes de Durotar laisse peu de place aux promenades imprudentes, et trouver de l'équipement abandonné indique généralement une fâcheuse rencontre à proximité."},{t="Fuir les étendues sauvages",b="En rapportant le sac à Ukor dans le sud de Durotar, l'histoire de son abandon est mise au jour. Ukor a laissé tomber le sac de panique lorsqu'il a été pris en embuscade par une immense araignée originaire de la région, convaincu qu'il ne reverrait jamais ses provisions. Retrouver son sac intact lui vaut la sincère gratitude et les éloges du voyageur."}},faq={{q="Qui est Ukor ?",a="Ukor est un habitant résidant dans le sud de Durotar. Confronté à une immense araignée dans les étendues arides, il a été forcé d'abandonner ses affaires dans une tentative désespérée de s'échapper sain et sauf.",al={"qui est ukor","ukor durotar"}},{q="Pourquoi Ukor a-t-il perdu son sac ?",a="Ukor a lâché son sac en fuyant pour sauver sa vie devant une araignée géante qui rôdait en Durotar. Il pensait que ses affaires étaient perdues à jamais jusqu'à ce qu'un aventurier retrouve la trace du sac.",al={"pourquoi le sac a été perdu","où ukor a perdu son sac"}},{q="Où le sac doit-il être apporté ?",a="Le sac récupéré appartient à Ukor, qui attend dans le sud de Durotar, prêt à accueillir les voyageurs qui reviennent.",al={"où rendre le sac","rendre la quête à ukor"}},{q="Comment le sac est-il identifié ?",a="Le sac est facilement identifié par le nom d'Ukor, qui est grossièrement cousu sur le rabat du sac.",al={"comment identifier le sac","couture du sac"}},{q="Quel genre de créature a poursuivi Ukor ?",a="Ukor a été pris en embuscade par une araignée géante qui parcourait le relief du sud de Durotar, ce qui l'a suffisamment terrifié pour qu'il abandonne tous ses biens et coure se mettre à l'abri.",al={"araignée à durotar","quelle araignée a attaqué ukor"}},{q="Que se passe-t-il lorsque vous rendez le sac à Ukor ?",a="Ukor est étonné et profondément reconnaissant de revoir ses biens perdus, qualifiant de véritable héros l'aventurier qui a récupéré son sac.",al={"récompense d'ukor","comment réagit ukor"}}},fp="16,125,16.162.0,17.222.0,12.118.0,27.131.0,37.97.0,27.54.0,34.106.0,46.116.0"}
P.entries["quest:96877"] = {n="Sabot d’Halikor",s="Dans les terres sauvages, le sabot d’Halikor est apporté à Orgrimmar comme preuve du triomphe d’un chasseur. Cet énorme sabot tranché honore la victoire du chasseur sur le redoutable lézard.",h="Dans les terres sauvages, le sabot d’Halikor est apporté à Orgrimmar comme preuve du triomphe d’un chasseur.",kw={"halikor","sabot d’halikor","horde","chasse","lézard","orgrimmar","trophée"},ang={["class:Hunter"]="En tant que chasseur, terrasser l’immense Halikor révèle votre talent de pisteur et vous fait goûter au frisson de la chasse.",["faction:Horde"]="Apporter à Orgrimmar la preuve de la défaite d’une puissante bête honore les traditions de la Horde, fondées sur la force et le talent de chasseur."},sec={{t="Trophée d’une bête puissante",b="La taille immense d’Halikor se voit au sabot prélevé sur sa dépouille. Depuis longtemps, les chasseurs et les guerriers des terres sauvages réclament une partie d’une bête redoutable pour prouver qu’ils l’ont tuée. Le sabot ne laisse aucun doute sur la taille et la force impressionnantes du lézard."},{t="Preuve destinée à la capitale",b="Le lourd sabot est apporté à Orgrimmar pour annoncer la défaite de la bête à la Horde. Dans cette société guerrière, la force et la survie face aux prédateurs féroces de ces terres comptent beaucoup. Présenter le trophée honore le chasseur et assure la capitale qu’une créature dangereuse a été tuée."}},faq={{q="Qu’est-ce qu’Halikor ?",a="Halikor est un redoutable lézard de taille immense. Les chasseurs réclament son sabot tranché pour prouver que la bête a été tuée.",al={"qu’est-ce qu’halikor","qui est halikor","lézard halikor"}},{q="Pourquoi faut-il apporter le sabot à Orgrimmar ?",a="Le sabot est apporté à Orgrimmar comme preuve de la défaite de la bête et du triomphe du chasseur.",al={"pourquoi apporter le sabot à orgrimmar","livrer le sabot d’halikor","où va le sabot"}},{q="Comment obtenir le sabot d’Halikor ?",a="Vous récupérez le sabot d’Halikor sur le corps du lézard après l’avoir traqué et tué au combat.",al={"comment obtenir le sabot d’halikor","butin d’halikor"}},{q="Pourquoi un lézard a-t-il un sabot ?",a="Halikor est une puissante bête des terres sauvages, et son énorme sabot prouve que vous l’avez terrassée. Personne n’a expliqué pourquoi elle a un sabot.",al={"halikor a-t-il des sabots","pourquoi un lézard a-t-il des sabots"}},{q="Qui veut le sabot d’Halikor à Orgrimmar ?",a="Vous apportez le sabot à Orgrimmar comme preuve de votre victoire. Aucun chasseur ni responsable en particulier n’est désigné pour le recevoir.",al={"qui reçoit le sabot d’halikor à orgrimmar","rendre le sabot d’halikor à orgrimmar"}},{q="Quelle est l’histoire de la quête Halikor's Hoof ?",a="Le puissant lézard Halikor est tué, et son énorme sabot tranché est apporté à Orgrimmar. Le trophée témoigne du talent du chasseur et annonce à la Horde la mort de la bête.",al={"quelle est la quête du sabot d’halikor","histoire du sabot d’halikor"}}},fp="14,166,24.231.0,21.278.0,16.113.0,44.89.0,31.93.0,30.126.0,38.114.0,50.176.0"}
P.entries["quest:96895"] = {n="The Argent Emissary",s="Dans les Clairières de Tirisfal, deux émissaires de l’Aube d’argent traquent des cultistes du Fléau près de Fossoyeuse. Tous deux sont Réprouvés, mais les autorités locales se méfient d’un ordre neutre et armé sur leur territoire.",h="Dans les Clairières de Tirisfal, deux émissaires de l’Aube d’argent traquent des cultistes du Fléau près de...",kw={"aube d'argent","émissaire de l’aube d’argent","cultistes","réprouvés","cultistes du fléau","clairières de tirisfal","fossoyeuse"},ang={["faction:Horde"]="L’Aube d’argent est neutre, mais les autorités de la Horde surveillent attentivement ses opérations indépendantes près de Fossoyeuse.",["race:Undead"]="En tant que Réprouvé, vous voyez des morts-vivants comme vous choisir l’Aube d’argent plutôt que Fossoyeuse. Leur choix révèle les loyautés divisées des morts-vivants libres."},sec={{t="Un accueil méfiant",b="Deux émissaires réprouvés de l’Aube d’argent sont récemment arrivés dans les Clairières de Tirisfal. Leur arrivée inquiète les autorités locales. L’Aube d’argent combat le Fléau, mais les Réprouvés se méfient d’un ordre neutre et armé qui agit sans surveillance sur leur territoire. Même leurs origines communes apaisent peu cette méfiance."},{t="Cultistes aux portes",b="Les émissaires traquent des cultistes du Fléau au sud-est de Fossoyeuse, près de ses abords. Ils veulent débusquer les agents du Roi-liche avant que les cultistes ne s’implantent. L’un des émissaires surveille leurs mouvements près des portes de la ville."}},faq={{q="Qui sont les émissaires de l’Aube d’argent ?",a="Deux émissaires de l’Aube d’argent sont récemment venus dans les Clairières de Tirisfal. Tous deux sont des Réprouvés qui ont rejoint l’ordre sacré et neutre au lieu de servir uniquement Fossoyeuse.",al={"qui sont les émissaires","visiteurs de l’aube d’argent","qui est venu à tirisfal"}},{q="Pourquoi l’Aube d’argent agit-elle près de Fossoyeuse ?",a="Les émissaires suivent la trace de cultistes du Fléau aperçus près des abords de Fossoyeuse, au sud-est. L’Aube d’argent traque les vestiges du Fléau partout où ils apparaissent, même près des grandes villes de la Horde.",al={"pourquoi sont-ils près de fossoyeuse","mission de l’aube d’argent à tirisfal","que font les émissaires"}},{q="Pourquoi les Réprouvés locaux se méfient-ils des émissaires ?",a="Les Réprouvés locaux se méfient d’un ordre neutre et armé qui opère sans supervision dans les Clairières de Tirisfal. Cette méfiance persiste même si ses émissaires partagent leur condition de morts-vivants.",al={"pourquoi se méfier de l’aube d’argent","peut-on faire confiance à l’aube d’argent","avis des réprouvés sur l’aube d’argent"}},{q="Quelle menace les cultistes représentent-ils ?",a="Une cellule de cultistes du Fléau a été aperçue rôdant au sud-est, près des abords de la ville. Le Roi-liche reste une menace pour les morts-vivants libres, aussi les éclaireurs locaux et l’Aube d’argent y prêtent attention.",al={"cultistes aux abords de fossoyeuse","fléau à tirisfal","qui sont les cultistes"}},{q="Où l’émissaire est-il allé ?",a="Un émissaire s’est approché de l’entrée de Fossoyeuse pour surveiller les cultistes du Fléau qui opèrent juste à l’extérieur des murs de la ville.",al={"où trouver l’émissaire","emplacement de l’émissaire","trouver un membre de l’aube d’argent"}},{q="Les Réprouvés servent-ils dans l’Aube d’argent ?",a="Oui. L’Aube d’argent accueille tous ceux qui veulent combattre le Fléau, y compris les morts-vivants libres qui se consacrent à cette cause. Ce n’est pas le cas de la Croisade écarlate.",al={"les réprouvés peuvent-ils rejoindre l’aube d’argent","morts-vivants de l’aube d’argent","les morts-vivants peuvent-ils rejoindre l’aube d’argent"}}},fp="19,181,12.319.0,21.231.0,30.157.0,52.185.0,46.173.0,41.187.0,26.111.0,41.161.0"}
P.entries["quest:96896"] = {n="A Righteous Cause",s="Leonid Barthalomew the Revered et Danitha Morr se retrouvent pour évoquer la défense de Fossoyeuse contre Naxxramas. Ils parlent de Garek Bandarion, un héros mort-vivant tombé au combat qui a retrouvé la Lumière sacrée en devenant paladin, et des Réprouvés qui poursuivent son œuvre.",h="Leonid Barthalomew the Revered et Danitha Morr se retrouvent pour évoquer la défense de Fossoyeuse contre...",kw={"danitha morr","réprouvés","garek bandarion","leonid barthalomew","chapelle de l’espoir de lumière","naxxramas","paladin","noble cause","fléau","fossoyeuse"},ang={["class:Paladin"]="Garek Bandarion et la cohorte de Danitha incarnent une voie rare : des Réprouvés redécouvrent comment manier la Lumière sacrée en paladins malgré leur état de mort-vivant.",["faction:Horde"]="Leonid Barthalomew relie les défenseurs de Fossoyeuse à l’Aube d’argent, à la Chapelle de l’Espoir de Lumière, dans les Maleterres.",["race:Undead"]="Leonid et Danitha cherchent une voie vers la Lumière, tandis que la plupart des Réprouvés restent éloignés de la sainteté ou lui sont hostiles dans leur non-mort."},sec={{t="Retrouvailles de vétérans",b="Leonid Barthalomew the Revered et Danitha Morr se retrouvent après avoir défendu Lordaeron ensemble. Ils ont survécu à l’assaut de Naxxramas contre Fossoyeuse, mais nombre de leurs compagnons sont tombés. Ils se souviennent des morts et du chemin difficile des Réprouvés qui honorent encore la Lumière sacrée."},{t="L’héritage de Garek Bandarion",b="Leonid et Danitha se souviennent de Garek Bandarion, le héros tombé au combat dont le donjon porte le nom. Leonid pense que Garek a peut-être été le premier Réprouvé à manier de nouveau la Lumière sacrée en véritable paladin. La plupart des Réprouvés se sont détournés de la Lumière. Danitha et sa cohorte perpétuent l’héritage de Garek et explorent les possibilités d’une non-mort sacrée."},{t="Retour dans les Maleterres",b="Après avoir parlé avec Danitha, Leonid se prépare à quitter le donjon et à reprendre le combat contre le Fléau dans l’est dévasté. Il est en poste à la Chapelle de l’Espoir de Lumière, dans les Maleterres de l’Est. Il y accueille les aventuriers valides prêts à prendre les armes."}},faq={{q="Qui est Leonid Barthalomew the Revered ?",a="Leonid Barthalomew the Revered est un mort-vivant membre de l’Aube d’argent. Il opère depuis la Chapelle de l’Espoir de Lumière, dans les Maleterres de l’Est, et garde le contact avec ses anciens compagnons de Lordaeron qui ont combattu le Fléau à ses côtés.",al={"qui est leonid barthalomew","leonid the revered","histoire de leonid barthalomew"}},{q="Qui est Danitha Morr ?",a="Danitha Morr est une dirigeante réprouvée qui a combattu aux côtés de Leonid Barthalomew durant l’attaque du Fléau contre Fossoyeuse. Elle dirige une cohorte qui perpétue les enseignements et l’héritage sacré de Garek Bandarion.",al={"qui est danitha morr","danitha","histoire de danitha morr"}},{q="Qui était Garek Bandarion ?",a="Garek Bandarion était un combattant réprouvé tombé en défendant Fossoyeuse lors de l’attaque de Naxxramas. Leonid pense qu’il a peut-être été le premier Réprouvé à manier de nouveau la Lumière sacrée en paladin.",al={"qui est garek bandarion","histoire de garek bandarion","donjon nommé d’après"}},{q="Que s’est-il passé durant l’attaque de Fossoyeuse ?",a="Quand Naxxramas, une nécropole, a attaqué Fossoyeuse, des champions réprouvés, dont Danitha Morr, Leonid Barthalomew et Garek Bandarion, ont participé à la défense de la ville contre le Fléau. Ils ont subi de lourdes pertes.",al={"attaque de naxxramas contre fossoyeuse","défense de fossoyeuse","attaque du fléau contre fossoyeuse"}},{q="Les Réprouvés peuvent-ils manier la Lumière en paladins ?",a="La plupart des Réprouvés rejettent la Lumière, qui inflige une douleur atroce à la chair morte-vivante. Garek Bandarion a montré qu’un guerrier mort-vivant pouvait manier la Lumière sacrée en paladin. La cohorte de Danitha continue d’étudier cette pratique.",al={"les réprouvés peuvent-ils être paladins","histoire des paladins morts-vivants","réprouvés maniant la lumière"}},{q="Où va Leonid Barthalomew ensuite ?",a="Après avoir rendu visite à ses amis et parlé avec Danitha Morr, Leonid prévoit de retourner à la Chapelle de l’Espoir de Lumière, dans les Maleterres de l’Est. L’Aube d’argent y coordonne son combat contre le Fléau.",al={"où va leonid","retrouver leonid plus tard","chapelle de l’espoir de lumière leonid"}}},fp="17,257,19.268.0,29.329.0,25.260.0,38.223.0,20.194.0,24.192.0,49.211.0,45.214.0,44.197.0"}
P.entries["quest:96897"] = {n="The Cult of the Damned",s="Dans les Clairières de Tirisfal, des serviteurs vivants du Fléau menacent de nouveau la population. En éliminant les néophytes sombres et les exécuteurs sombres, vous empêchez les agents du roi-liche de répéter les trahisons qui ont brisé Lordaeron.",h="Dans les Clairières de Tirisfal, des serviteurs vivants du Fléau menacent de nouveau la population.",kw={"culte des damnés","exécuteurs sombres","néophytes sombres","serviteurs vivants","lordaeron","nécromancie","fléau","clairières de tirisfal"},ang={["class:Paladin"]="En tant que paladin, vous avez juré d’éradiquer l’ombre qui a brisé Lordaeron. Les cultistes vivants dévoués au Fléau sont des ennemis jurés de la Lumière.",["class:Priest"]="En tant que prêtre, vous savez comment le Culte des damnés dévoie la foi. Ses membres troquent leur dévotion sacrée contre la sombre nécromancie.",["race:Undead"]="En tant que Réprouvé, vous savez comment les cultistes vivants ont ravagé Lordaeron et provoqué votre non-mort. Mettre fin aux nouvelles cellules du Culte en Tirisfal contribue à protéger votre nouveau royaume."},sec={{t="Agents mortels du Fléau",b="Le Fléau compte des serviteurs vivants qui jurent fidélité au roi-liche. Ils agissent là où les morts sans esprit ne le peuvent pas. Dans les Clairières de Tirisfal, la population doit déjà affronter des morts-vivants errants et les zélotes implacables de la Croisade écarlate. La découverte récente de cellules de néophytes sombres et d’exécuteurs sombres révèle que le Fléau cherche de nouveau à s’implanter."},{t="Les leçons de la chute",b="Les morts en marche ne furent pas les seuls responsables de la chute de Lordaeron. Des voisins trahirent leurs voisins tandis que le Culte des damnés s’infiltrait dans les villages et empoisonnait les greniers. Depuis l’ombre, ses membres contribuèrent à faire tomber le royaume. Les nouvelles activités du Culte en Tirisfal menacent de répéter cette histoire dans les terres meurtries du nord."}},faq={{q="Qu’est-ce que le Culte des damnés ?",a="Le Culte des damnés est composé de mortels qui servent volontairement le roi-liche et le Fléau. Ces acolytes vivants répandent la peste, sabotent les défenses et pratiquent la nécromancie de leur plein gré, au lieu d’être relevés comme morts-vivants sans esprit.",al={"qu’est-ce que le culte des damnés","qui sont les cultistes","qui sont les néophytes sombres"}},{q="Pourquoi des membres du Culte agissent-ils dans les Clairières de Tirisfal ?",a="Les Clairières de Tirisfal restent disputées et hantées par des morts-vivants sans esprit, des zélotes de la Croisade écarlate et des vestiges de l’influence du Fléau. Le Culte agit en secret pour saper la résistance locale et faire avancer les sombres desseins du Fléau.",al={"pourquoi des cultistes en tirisfal","culte dans les clairières de tirisfal"}},{q="Qui sont les néophytes sombres et les exécuteurs sombres ?",a="Les néophytes sombres sont de nouvelles recrues qui apprennent les arts sombres et leurs rituels. Les exécuteurs sombres protègent les opérations du Culte et y font régner la discipline. Ensemble, ils forment des cellules actives dans la région.",al={"qui sont les exécuteurs sombres","rôle des néophytes sombres"}},{q="Pourquoi les serviteurs vivants sont-ils considérés comme pires que les morts-vivants sans esprit ?",a="Les morts-vivants sans esprit agissent par instinct ou sur ordre direct, tandis que les cultistes vivants choisissent sciemment la trahison. Ils peuvent se mêler aux sociétés mortelles et infiltrer les établissements, ce qui les rend plus insidieux que les goules ou les squelettes errants.",al={"pourquoi les cultistes vivants sont pires","serviteurs vivants du fléau"}},{q="Que signifie la quête lorsqu’elle dit qu’il ne faut pas laisser l’histoire de Lordaeron se répéter ?",a="Lordaeron ne tomba pas seulement sous les coups de l’invasion. Le Culte des damnés empoisonna aussi les céréales et trahit ses concitoyens de l’intérieur. Si les cultistes s’implantent, la même catastrophe pourrait se produire.",al={"répétition de l’histoire de lordaeron","chute de lordaeron et culte"}},{q="Quel est le lien entre le Culte et la Croisade écarlate en Tirisfal ?",a="La Croisade écarlate traque avec fanatisme tout ce qui est souillé par la non-mort. Le Fléau et le Culte sont donc ses cibles. Leur conflit laisse les habitants pris entre des horreurs sans esprit, des croisés fanatiques et des cultistes clandestins.",al={"lien avec la croisade écarlate","culte contre croisade écarlate"}}},fp="22,219,28.323.0,19.316.0,31.229.0,57.215.0,46.182.0,62.226.0,74.194.0,60.224.0"}
P.entries["quest:96898"] = {n="Remnants of War",s="Dans les Clairières de Tirisfal, des vestiges de la guerre reposent éparpillés sous la terre. Naxxramas a été chassée de Fossoyeuse au prix de lourdes pertes pour les Réprouvés et l’Aube d’argent. Son cristal de focalisation nécrotique brisé reste dangereux, et les sectateurs du Fléau recherchent ses fragments pour la magie noire qu’ils renferment.",h="Dans les Clairières de Tirisfal, des vestiges de la guerre reposent éparpillés sous la terre.",kw={"aube d'argent","sectateurs","réprouvés","naxxramas","fragments de cristal nécrotique","remnants of war","fléau","clairières de tirisfal","fossoyeuse"},ang={["class:Mage"]="En tant que Mage, manipulez avec précaution les cristaux nécrotiques brisés de Naxxramas. Ils renferment encore une énergie magique instable.",["class:Priest"]="En tant que Prêtre, vous êtes confronté à la corruption impie qui persiste dans les éclats. Elle menace de souiller davantage la terre.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à protéger les Clairières de Tirisfal contre la magie persistante du Fléau. Vous protégez Fossoyeuse et la position de la Horde dans le nord de Lordaeron.",["race:Undead"]="En tant que Mort-vivant, vous savez que Naxxramas menaçait Fossoyeuse elle-même. Récupérer les fragments aide à protéger votre peuple contre la puissance du Fléau, à ses portes."},sec={{t="L’ombre sur la ville",b="Naxxramas dominait autrefois les Clairières de Tirisfal, avec l’intention de détruire Fossoyeuse et les Réprouvés. Les Réprouvés et l’Aube d’argent ont repoussé la forteresse flottante au cours d’une défense désespérée. Les deux camps ont subi de lourdes pertes. Pendant la bataille, l’immense cristal de focalisation nécrotique au sommet de Naxxramas a été détruit, dispersant ses fragments dans les clairières."},{t="Nécromancie dispersée",b="Naxxramas a été repoussée, mais des morceaux de son cristal reposent encore dans la terre. Les sectateurs du Fléau recherchent les fragments, dans l’espoir d’utiliser la magie noire qu’ils renferment toujours. Rassembler les éclats empêche le Fléau de s’emparer de cette puissance. Pourtant, il faudra des années pour retrouver chaque fragment dans les Clairières de Tirisfal."}},faq={{q="Que sont les fragments de cristal nécrotique ?",a="Les fragments de cristal nécrotique sont des morceaux du grand cristal de focalisation autrefois fixé au sommet de Naxxramas. Le cristal a été détruit pendant l’assaut contre Fossoyeuse, et ses éclats sont tombés dans les Clairières de Tirisfal.",al={"que sont les fragments de cristal nécrotique","que sont les cristaux","cristaux nécrotiques"}},{q="Pourquoi Naxxramas a-t-elle attaqué Fossoyeuse ?",a="Naxxramas est venue dans les Clairières de Tirisfal pour détruire Fossoyeuse et anéantir les Réprouvés. Les Réprouvés et l’Aube d’argent l’ont repoussée, bien que les deux camps aient subi de lourdes pertes.",al={"pourquoi naxxramas a attaqué","attaque de naxxramas contre fossoyeuse","qu’a fait naxxramas ici"}},{q="Pourquoi les sectateurs du Fléau ramassent-ils les fragments de cristal ?",a="Les sectateurs du Fléau fouillent les Clairières de Tirisfal à la recherche des fragments brisés, car ils renferment encore de la magie nécrotique. Ils espèrent reconquérir cette puissance pour le Fléau.",al={"pourquoi les sectateurs veulent les cristaux","que veulent les sectateurs avec les éclats","cristaux des sectateurs du fléau"}},{q="Est-il dangereux de manipuler les cristaux nécrotiques ?",a="Oui. Bien qu’ils soient brisés et que leur charge d’origine se soit largement dissipée, les fragments renferment encore une énergie nécrotique instable. Tout contact direct est dangereux.",al={"les cristaux sont-ils dangereux au toucher","contact physique avec le cristal","les cristaux nécrotiques peuvent-ils vous blesser"}},{q="Qui a aidé les Réprouvés à repousser Naxxramas ?",a="Les Réprouvés ont combattu aux côtés de l’Aube d’argent pour défendre Fossoyeuse contre Naxxramas. Les deux camps ont subi de lourdes pertes pendant la bataille.",al={"qui a combattu à naxxramas","qui a défendu fossoyeuse","défense de fossoyeuse par l’aube d’argent"}},{q="Tous les cristaux nécrotiques finiront-ils par être retirés des Clairières de Tirisfal ?",a="Il faudra des années pour retirer chaque fragment de cristal des Clairières de Tirisfal. Le cristal s’est brisé au-dessus des clairières et ses éclats se sont dispersés au loin. Les habitants continueront d’en trouver dans la terre.",al={"les clairières de tirisfal seront-elles débarrassées des cristaux","peut-on retirer tous les fragments","cristaux restants dans les clairières de tirisfal"}}},fp="15,287,24.346.0,20.278.0,40.203.0,39.168.0,58.160.0,44.144.0,44.124.0,61.182.0"}
P.entries["quest:96899"] = {n="Forteresse de Bandarion",s="À la Forteresse de Bandarion, le commandant Leonid Barthalomew attend les voyageurs dans l’ouest des Clairières de Tirisfal. L’Aube d’argent défendit jadis cette forteresse isolée contre le Fléau. Danitha et ses paladins en gardent désormais les murs.",h="À la Forteresse de Bandarion, le commandant Leonid Barthalomew attend les voyageurs dans l’ouest des...",kw={"aube d'argent","forteresse de bandarion","culte des damnés","danitha","leonid barthalomew","paladin","fléau","clairières de tirisfal"},ang={["class:Paladin"]="En tant que paladin, vous trouvez la Forteresse de Bandarion sous la garde de Danitha. Ses compagnons paladins tiennent ses murs, bastion sacré contre les forces obscures des Clairières de Tirisfal."},sec={{t="Un appel à la forteresse",b="Après avoir aidé l’Aube d’argent à lutter contre les agissements du Culte des damnés, vous partez vers le nord-ouest, à travers les Clairières de Tirisfal. Le commandant Leonid Barthalomew vous attend à la forteresse pour vous parler de la croisade que mène toujours l’ordre contre les ténèbres."},{t="Histoire et intendance",b="L’Aube d’argent utilisait jadis cette place forte comme base avancée contre les incursions du Fléau dans les Clairières de Tirisfal. Puis l’ordre reporta son attention sur les Maleterres de l’Est et de l’Ouest. Le fort fut abandonné et commença à tomber en ruine, jusqu’à ce que la paladin Danitha et ses compagnons prennent soin de ses murs."},{t="Le souvenir d’un ami commun",b="Leonid Barthalomew se souvient des batailles livrées depuis les remparts de la forteresse. Il est soulagé que la place forte n’ait pas été laissée à l’abandon. Danitha lui a donné le nom d’un ami commun."}},faq={{q="Qui est Leonid Barthalomew ?",a="Leonid Barthalomew commande l’Aube d’argent. Il utilisait autrefois la Forteresse de Bandarion comme base lors des incursions du Fléau dans les Clairières de Tirisfal. Il est revenu rencontrer Danitha et ses paladins.",al={"qui est leonid barthalomew","où se trouve leonid barthalomew","leonid forteresse de bandarion"}},{q="Qu’est-ce que la Forteresse de Bandarion ?",a="Dans l’ouest des Clairières de Tirisfal, la Forteresse de Bandarion est une place forte que l’Aube d’argent défendit jadis contre les assauts du Fléau. L’ordre se replia dans les Maleterres et laissa le fort se dégrader. Les paladins de Danitha l’ont restauré et le tiennent désormais.",al={"qu’est-ce que la forteresse de bandarion","histoire de la forteresse de bandarion","qui tient la forteresse de bandarion"}},{q="Qui est Danitha ?",a="Danitha est une paladin qui a pris soin de la Forteresse de Bandarion avec son ordre après le repli de l’Aube d’argent vers l’est, dans les Maleterres. Elle a donné son nom à la forteresse en hommage à un ami commun avec Leonid Barthalomew.",al={"qui est danitha","danitha paladin","qui dirige la forteresse de bandarion"}},{q="Pourquoi ce nom, Forteresse de Bandarion ?",a="Danitha a donné à la forteresse le nom d’un ami commun à elle et au commandant Leonid Barthalomew.",al={"pourquoi ce nom, forteresse de bandarion","qui est bandarion","signification du nom bandarion"}},{q="Pourquoi l’Aube d’argent s’intéresse-t-elle à la Forteresse de Bandarion ?",a="L’Aube d’argent se rend à la Forteresse de Bandarion pour se coordonner avec les paladins de Danitha. Ensemble, ils protègent les Clairières de Tirisfal contre les forces du Fléau et les agissements du Culte des damnés.",al={"pourquoi aller à la forteresse de bandarion","aube d’argent clairières de tirisfal","forteresse de bandarion aube d’argent"}},{q="Pourquoi l’Aube d’argent a-t-elle autrefois abandonné la forteresse ?",a="L’Aube d’argent a quitté la Forteresse de Bandarion lorsqu’elle a déplacé ses principales forces vers l’est, dans les Maleterres, pour combattre le Fléau. Le fort est resté vide jusqu’à ce que Danitha et ses paladins en prennent soin.",al={"qu’est-il arrivé à la forteresse après la guerre","pourquoi l’aube d’argent a-t-elle quitté la forteresse de bandarion"}}},fp="14,214,21.234.0,23.298.0,27.172.1,26.184.0,23.226.0,15.205.0,32.93.0,52.180.0,52.183.0"}
P.entries["quest:96984"] = {n="Heart of Disruption",s="Magus Wordeen Voidglare vous laisse franchir ses protections pour chercher un Granule arcanique à Dalaran. Il craint que la chute de la cité ne provoque aussi une catastrophe à Fossoyeuse.",h="Magus Wordeen Voidglare vous laisse franchir ses protections pour chercher un Granule arcanique à Dalaran.",kw={"granule arcanique","dalaran","heart of disruption","magus wordeen voidglare","moulin-de-tarren","fossoyeuse","violet citadel","protections"},sec={{t="Une clé pour franchir les protections",b="Magus Wordeen Voidglare, à Moulin-de-Tarren, vous envoie à Dalaran avec une clé qu’il a imprégnée de magie pour franchir ses protections. Il craint que si la cité tombe, Fossoyeuse soit également menacée. Trouvez le Granule arcanique et retrouvez-le à la Violet Citadel, où tout a commencé ; empêcher une catastrophe passe avant tout."}},faq={{q="Qui m’envoie à Dalaran ?",a="Magus Wordeen Voidglare, à Moulin-de-Tarren, vous envoie à Dalaran pour trouver un Granule arcanique.",al={"qui a donné ceci","wordeen voidglare","qui est le magus"}},{q="Pourquoi dois-je aller à Dalaran ?",a="Vous êtes envoyé à la recherche d’un Granule arcanique. Wordeen craint que la chute de Dalaran n’entraîne celle de Fossoyeuse.",al={"pourquoi dalaran","objet recherché","mission à dalaran"}},{q="Comment franchir les protections de Wordeen ?",a="Wordeen imprègne votre clé de magie pour qu’elle permette de franchir ses protections et d’entrer dans la cité.",al={"la clé","clé de dalaran","franchir les protections"}},{q="Où dois-je retrouver Wordeen ?",a="Wordeen vous demande de le retrouver à la Violet Citadel, à Dalaran, où tout a commencé.",al={"retrouver le magus","violet citadel","où est wordeen"}},{q="Quelle est la priorité absolue de Wordeen ?",a="Wordeen dit qu’empêcher une catastrophe passe avant tout.",al={"empêcher une catastrophe","ce qui compte le plus","priorité absolue"}}},fp="19,161,23.287.0,24.85.0,26.107.0,34.76.0,28.80.0,33.50.0"}
P.entries["quest:96986"] = {n="The Grave Knight",s="Au Moulin-de-Tarren, Melisara vous envoie chercher Atrexis, qui relève les morts sous Dalaran. Elle voit ses actes comme une offense aux Réprouvés.",h="Au Moulin-de-Tarren, Melisara vous envoie chercher Atrexis, qui relève les morts sous Dalaran.",kw={"atrexis","dalaran","réprouvés","grave knight","melisara","nécromancien","moulin-de-tarren","armée de morts-vivants"},ang={["faction:Alliance"]="En vous envoyant chercher Atrexis, Melisara se soucie peu du sort de Dalaran.",["race:Undead"]="En tant que mort-vivant, vous savez que Melisara traite Atrexis de traître aux Réprouvés. Elle dit que son armée de morts-vivants défie les principes des Réprouvés."},sec={{t="La mission de Melisara",b="Melisara traite Atrexis de traître aux Réprouvés. Sous Dalaran, il lève une armée de morts-vivants. Elle vous demande de le vaincre, bien que le sort de la cité des mages lui importe peu. Nul n'échappe à la portée de la Dame noire."}},faq={{q="Qui est le Grave Knight ?",a="Atrexis est un nécromancien à Dalaran, que Melisara appelle le Grave Knight.",al={"atrexis","atrexis grave knight","qui est le grave knight"}},{q="Qui m'a envoyé affronter Atrexis ?",a="Melisara, au Moulin-de-Tarren, vous demande de vaincre Atrexis.",al={"qui a donné la quête du grave knight","melisara atrexis","qui veut la mort d'atrexis"}},{q="Pourquoi Melisara veut-elle vaincre Atrexis ?",a="Melisara traite Atrexis de traître aux Réprouvés, car il lève une armée de morts-vivants sous Dalaran.",al={"pourquoi tuer atrexis","pourquoi grave knight","raison des réprouvés contre atrexis"}},{q="Où se trouve Atrexis ?",a="Atrexis se trouve dans la Cité de Dalaran.",al={"emplacement d'atrexis","emplacement du grave knight","où se trouve le grave knight"}}},fp="16,135,17.210.0,24.74.0,26.51.0,40.98.0,17.34.0"}
P.entries["quest:96987"] = {n="Opportunistic Education",s="Rexxie Copperclutch vous demande d’aller chercher un ouvrage à la bibliothèque de Dalaran pendant que ses mages sont occupés. Elle espère vendre le livre et partager les bénéfices avec vous.",h="Rexxie Copperclutch vous demande d’aller chercher un ouvrage à la bibliothèque de Dalaran pendant que ses...",kw={"dalaran","founding of dalaran","library","mages","opportunistic education","rexxie copperclutch","ouvrage","mort-vivant"},ang={["race:Undead"]="Rexxie vous considère, en tant que mort-vivant, comme un esprit proche du sien et vous accueille dans sa combine."},sec={{t="Un livre pour Rexxie",b="Rexxie Copperclutch, près de l’entrée des égouts, voit une occasion de tirer profit de la bibliothèque de Dalaran. Pendant que ses mages sont occupés, elle vous demande de lui apporter l’ouvrage intitulé Founding of Dalaran. Elle propose de partager la somme qu’elle en tirera."},{t="La valeur du livre",b="Rexxie estime que le livre que vous rapportez ne vaut pas grand-chose. Elle envisage de le maquiller avec de la peinture dorée et de prétendre qu’il appartenait à un archimage."}},faq={{q="Qui demande le livre ?",a="Rexxie Copperclutch, près de l’entrée des égouts de Dalaran, vous demande de lui apporter un ouvrage de la bibliothèque de la ville.",al={"qui veut l’ouvrage","rexxie copperclutch","qui est rexxie"}},{q="Quel livre Rexxie veut-elle ?",a="Rexxie demande Founding of Dalaran.",al={"quel livre","founding of dalaran","nom de l’ouvrage"}},{q="Pourquoi Rexxie veut-elle cet ouvrage ?",a="Rexxie espère vendre l’ouvrage et partager les bénéfices avec vous.",al={"pourquoi voler le livre","à quoi sert le livre"}},{q="D’où le livre est-il censé provenir ?",a="Rexxie vous demande de trouver Founding of Dalaran dans la Cité de Dalaran.",al={"où trouver l’ouvrage","bibliothèque de dalaran","emplacement du livre"}},{q="Que se passe-t-il avec les mages de Dalaran ?",a="Rexxie dit que les mages sont occupés lorsqu’elle vous demande de chercher un livre.",al={"mages occupés","pourquoi opportuniste","mages de dalaran"}},{q="Que pense Rexxie du livre que vous rapportez ?",a="Rexxie estime que le livre ne vaut pas grand-chose et envisage de le vaporiser de peinture dorée pour lui donner de la valeur.",al={"le livre a-t-il de la valeur","que devient l’ouvrage","réaction de rexxie"}}},fp="23,157,17.231.0,18.142.1,27.109.0,28.36.0,30.60.0,40.67.0,41.73.0,45.103.0"}
P.entries["quest:96988"] = {n="Source of Power",s="À Dalaran, des assemblages rebelles se sont retournés contre leurs créateurs. Le docteur Martin Felben y voit une chance pour les Réprouvés. Il veut récupérer leurs noyaux arcaniques pour ses travaux à Fossoyeuse et espère attirer l’attention de la Dame noire.",h="À Dalaran, des assemblages rebelles se sont retournés contre leurs créateurs.",kw={"abominations","assemblages arcaniques","noyau fêlé de sentinelle","dalaran","docteur martin felben","société royale des apothicaires","source of power","sylvanas coursevent","fossoyeuse"},ang={["class:Mage"]="Les mages trouveront peut-être une sombre ironie dans le fait que les assemblages de Dalaran se retournent contre leurs maîtres, tandis que leurs sources de pouvoir arcanique sont pillées pour alimenter de sinistres expériences à Fossoyeuse.",["faction:Horde"]="Les aventuriers de la Horde à Lordaeron soutiennent les efforts des Réprouvés pour s’emparer d’équipements militaires avancés contre leurs rivaux, tandis que Dalaran est affaiblie par ses créations rebelles.",["profession:Engineering"]="Les ingénieurs peuvent apprécier le savoir-faire derrière les sentinelles autonomes de Dalaran, même si leurs délicats noyaux arcaniques sont arrachés pour alimenter d’horribles abominations façonnées dans la chair.",["race:Undead"]="Les Réprouvés comptent sur les innovations impitoyables de la Société royale des apothicaires pour survivre à Lordaeron. Aider le docteur Felben fait avancer les recherches de la faction sur le façonnage de la chair par les arcanes, sous le regard de la Dame noire."},sec={{t="Une récolte opportuniste",b="Les assemblages arcaniques rebelles de Dalaran assiègent les mages, et les Réprouvés sont impatients de tirer parti du chaos qui règne dans la cité. Apothicaire à Fossoyeuse, le docteur Martin Felben veut récupérer les noyaux qui alimentent les sentinelles plutôt que secourir les sorciers assiégés. Dalaran protège depuis longtemps ses recherches magiques, mais ses sentinelles vulnérables offrent désormais une occasion aux chercheurs opportunistes."},{t="L’ambition d’un apothicaire",b="Le docteur Felben veut améliorer sa position au sein de la Société royale des apothicaires grâce aux noyaux fêlés de sentinelle. Il espère imprégner les abominations des Réprouvés de la magie volatile des assemblages de Dalaran et lever une armée dévastatrice de bêtes de chair alimentées aux arcanes. Selon lui, une telle avancée attirerait toute l’attention de Dame Sylvanas Coursevent et démontrerait son génie alchimique. Il espère gravir les échelons de la Société, où la ruse impitoyable et les résultats puissants dictent la survie et le rang."}},faq={{q="Qui donne la quête Source of Power ?",a="C’est le docteur Martin Felben. Apothicaire résidant à Fossoyeuse, la capitale des Réprouvés, il cherche à prouver ses talents d’alchimiste à la Société royale des apothicaires et à Dame Sylvanas Coursevent en créant de nouvelles monstruosités militaires.",al={"qui donne source of power","donneur de quête source of power","quête martin felben"}},{q="Que se passe-t-il à Dalaran pendant cette quête ?",a="Dalaran est assiégée par ses propres assemblages arcaniques, qui se sont retournés contre leurs créateurs. Les combats permettent à des étrangers d’entrer dans la cité et de récupérer les composants magiques qui alimentent les sentinelles rebelles.",al={"que s’est-il passé à dalaran","dalaran assiégée","pourquoi les assemblages attaquent dalaran"}},{q="Pourquoi le docteur Felben veut-il les noyaux des assemblages ?",a="Le docteur Felben veut utiliser l’énergie arcanique des noyaux des sentinelles de Dalaran pour renforcer les abominations des Réprouvés. En associant machines arcaniques et façonnage de la chair, il espère créer une armée d’abominations alimentées aux arcanes et prouver sa maîtrise alchimique à Dame Sylvanas Coursevent.",al={"pourquoi récupérer les noyaux de sentinelle","à quoi servent les noyaux pour felben","projet de felben avec les noyaux de sentinelle"}},{q="Quels sont les objectifs de Source of Power ?",a="Vous êtes envoyé à Dalaran pour affronter les assemblages rebelles et récupérer six noyaux fêlés de sentinelle. Vous les rapportez ensuite au docteur Martin Felben, à Fossoyeuse, pour ses expériences en cours.",al={"objectifs de source of power","combien de noyaux faut-il","que récupérer pour source of power"}},{q="Quel est l’objectif du docteur Felben au sein de la Société royale des apothicaires ?",a="Le docteur Martin Felben cherche à se faire reconnaître et à gravir rapidement les échelons chez les Réprouvés. Il espère qu’une force redoutable d’abominations imprégnées d’énergie arcanique impressionnera assez Dame Sylvanas Coursevent pour qu’elle le nomme à la tête de la Société royale des apothicaires.",al={"objectif de felben chez les apothicaires","qui dirige la société royale des apothicaires","felben veut être reconnu par la dame noire"}},{q="Pourquoi les Réprouvés récupèrent-ils la technologie de Dalaran ?",a="La Société royale des apothicaires et les Réprouvés cherchent des armes et des sources de pouvoir inhabituelles pour assurer leur survie à Lordaeron. Alors que les défenses de Dalaran s’effondrent de l’intérieur, les apothicaires réprouvés peuvent s’emparer de ses composants arcaniques sophistiqués sans affronter officiellement les mages en guerre ouverte.",al={"pourquoi les réprouvés veulent la magie de dalaran","assemblages de dalaran à fossoyeuse","intérêt des réprouvés pour dalaran"}},{q="Où trouver les noyaux fêlés de sentinelle ?",a="Les noyaux fêlés de sentinelle proviennent des assemblages rebelles qui assiègent Dalaran. Vous les récupérez sur les gardiens enchantés hostiles disséminés dans la cité, pour les recherches du docteur Felben à Fossoyeuse.",al={"où trouver les noyaux fêlés de sentinelle","emplacement des noyaux fêlés de sentinelle","butin des sentinelles de dalaran"}}},fp="15,210,24.393.0,34.472.0,36.238.0,47.222.0,48.276.0,44.181.0,65.242.0,53.298.0,41.186.0"}
P.entries["quest:97"] = {n="La légende de Stalvan",s="À Sombre-Comté, le Greffier Daltry associe l’écriture retrouvée à Stalvan Mantebrume. Son rapport confirme les soupçons de The Night Watch.",h="À Sombre-Comté, le Greffier Daltry associe l’écriture retrouvée à Stalvan Mantebrume.",kw={"althea bouclenoire","greffier daltry","sombre-comté","bois de la pénombre","écriture","mantebrume","the night watch","stalvan"},ang={["faction:Alliance"]="Pour les enquêteurs de l’Alliance, la piste de Stalvan montre que les dirigeants éprouvés de Sombre-Comté et les aventuriers de passage doivent unir leurs efforts pour protéger les territoires du sud.",["race:Human"]="En tant qu’humain, vous voyez votre société se dégrader : des précepteurs respectés et des villages ruraux sombrent, quittant la civilisation pour la folie et l’isolement."},sec={{t="Une correspondance dans les registres",b="De retour à l’hôtel de ville de Sombre-Comté, le Greffier Daltry compare la page du Journal maculé de sang aux signatures du registre municipal. L’écriture correspond exactement à celle de Stalvan Mantebrume. Après une piste qui l’a mené dans des manoirs, des auberges et des archives municipales des royaumes humains, The Night Watch détient désormais la preuve que le danger est tout proche."},{t="Les soupçons de The Night Watch",b="Le Commandant Althea Bouclenoire craint Stalvan depuis le début. Le Bois de la Pénombre fait déjà face aux worgens sauvages, aux morts-vivants squelettiques et aux nécromanciens tapis dans l’ombre. Elle ne peut ignorer un autre danger : un meurtrier introuvable dans les bois. La confirmation de Daltry met The Night Watch sur la piste de Stalvan pour l’arrêter une bonne fois pour toutes."}},faq={{q="Qu’a découvert le Greffier Daltry ?",a="Le Greffier Daltry a comparé la page du Journal maculé de sang aux signatures du registre municipal de Sombre-Comté. L’écriture correspondait exactement à celle de Stalvan Mantebrume, comme le soupçonnait le Commandant Althea Bouclenoire.",al={"qu’a trouvé daltry","correspondance de l’écriture de daltry","preuve écrite contre stalvan"}},{q="Pourquoi le Commandant Althea Bouclenoire se soucie-t-elle tant de Stalvan ?",a="Le Commandant Althea Bouclenoire dirige The Night Watch, la milice éprouvée de Sombre-Comté. Alors que des terreurs menacent déjà la région, elle ne peut laisser un individu violent et mystérieux, au passé trouble, rôder sans être inquiété dans le Bois de la Pénombre.",al={"pourquoi althea s’en soucie","enquête de bouclenoire","the night watch et stalvan"}},{q="Où se déroule cette étape ?",a="Cette étape se déroule entièrement à Sombre-Comté. Le Greffier Daltry se trouve à l’hôtel de ville, tandis que le Commandant Althea Bouclenoire patrouille sur les routes centrales de la ville, non loin de là.",al={"où se trouve cette quête","lieu de la quête","rendre la quête de stalvan à sombre-comté"}},{q="Que se passe-t-il après le signalement de la correspondance ?",a="Après que le Greffier Daltry a confirmé la correspondance, l’enquête se tourne vers la recherche de Stalvan dans les étendues sauvages hantées du Bois de la Pénombre.",al={"que faire ensuite avec stalvan","après la correspondance trouvée par daltry","étape suivante de la suite de quêtes de stalvan"}},{q="Qui était Stalvan Mantebrume à l’origine ?",a="Stalvan Mantebrume a autrefois enseigné à l’École de Ruisselune, puis a été le précepteur privé des enfants de la famille Flintridge. Ses lettres et les pages de son journal mènent de Ruisselune et de Comté-de-l’Or au Bois de la Pénombre, où il vit comme un reclus dangereux dans les bois.",al={"qui est stalvan","histoire de stalvan","histoire de stalvan mantebrume"}},{q="Pourquoi fallait-il analyser l’écriture ?",a="Les événements et les accusations concernant Stalvan s’étendent à Ruisselune et à Comté-de-l’Or, et les documents officiels sont donc dispersés. Le registre municipal de Sombre-Comté contient des échantillons locaux vérifiés, qui permettent de relier avec certitude ces indices venus d’ailleurs à cet homme précis.",al={"pourquoi comparer les écritures","pourquoi daltry a vérifié l’écriture","prouver l’identité de stalvan"}}},fx={cc1b58e5={q="Pourquoi le greffier Daltry est-il si impatient que vous fassiez votre rapport au commandant Bouclenoire ?",a="Le greffier Daltry est un archiviste municipal, pas un officier de The Night Watch, et confirmer que l'écriture appartient à Stalvan Mantebrume valide les graves soupçons du commandant Bouclenoire. Daltry reconnaît qu'une enquête officielle sur un meurtre nécessite une autorité armée immédiate, rendant urgent qu'Althea reçoive une preuve définitive sans délai.",al={"pourquoi daltry veut-il que cela soit fait","mobile de daltry","pourquoi faire un rapport à althea"}}},fp="21,137,22.323.0,28.315.1,31.183.0,63.224.0,32.159.0,51.128.0,38.255.0,39.225.0"}
P.entries["quest:970"] = {n="La Tour d'Althalaxx",s="Au Poste de Maestra, Delgren le Purificateur vous envoie vers le sud pour arrêter le Culte du Dark Strand. Depuis la Tour d'Althalaxx, sa menace s'étend jusqu'en Orneval. Vous devez récupérer une Gemme d'âme luminescente dans les Ruines d'Ordil'Aran.",h="Au Poste de Maestra, Delgren le Purificateur vous envoie vers le sud pour arrêter le Culte du Dark Strand.",kw={"althalaxx","orneval","dark strand","sombrivage","delgren","delgren le purificateur","gemme d'âme luminescente","poste de maestra","ordil'aran"},ang={["class:Paladin"]="En tant que paladin, vous purifiez la corruption impie en détruisant les sombres réceptacles d'âme et en combattant les sectateurs qui les pervertissent.",["class:Priest"]="En tant que prêtre, vous examinez un sombre réceptacle d'âme pour contrer la corruption et apaiser les âmes tourmentées.",["faction:Alliance"]="En tant que membre de l'Alliance, vous aidez les avant-postes de Sombrivage et d'Orneval à protéger la frontière nord contre les adeptes des arts sombres qui menacent les voyageurs de l'Alliance.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous voyez le Culte du Dark Strand profaner d'anciennes ruines comme celles d'Ordil'Aran et corrompre les forêts du nord. Il faut les éliminer sans tarder."},sec={{t="Un appel au-delà de la frontière",b="Des rapports sur la Tour d'Althalaxx, au nord de Sombrivage, vous ont mené vers le sud, auprès de Delgren le Purificateur au Poste de Maestra. Il combat le Culte du Dark Strand depuis longtemps, mais le culte s'étend désormais dans les antiques forêts elfiques d'Orneval. Sa menace franchit les frontières des deux territoires, et Delgren veut frapper à la source de sa sorcellerie."},{t="Les secrets d'Ordil'Aran",b="Au nord-est du Poste de Maestra, les Ruines d'Ordil'Aran sont envahies par les sectateurs du Dark Strand. Delgren affirme que leurs agents portent des gemmes d'âme luminescentes, des réceptacles enchantés par une magie qui entretient le pouvoir du culte. Fouillez les ruines et récupérez une gemme. Delgren pourra briser son enchantement et découvrir l'origine du rite du culte."},{t="Un esprit prisonnier",b="Un esprit tourmenté est lié à la Gemme d'âme luminescente. Quand ses protections cèdent, Sargath apparaît. C'est l'un des elfes d'Ameth'Aran qu'Athrikus Narassin a emprisonnés dans des gemmes d'âme pendant la Fracture, et dont il draine peu à peu l'énergie depuis. Sargath nomme le lieutenant d'Athrikus, Ilkrud Magthrull. Son grimoire pourrait révéler où se trouvent les autres gemmes d'âme."}},faq={{q="Où trouver la Gemme d'âme luminescente ?",a="Les membres du Culte du Dark Strand dans les Ruines d'Ordil'Aran, au nord-est du Poste de Maestra, portent des Gemmes d'âme luminescentes. Les ruines se trouvent en Orneval. Vous devrez peut-être fouiller plusieurs sectateurs pour en récupérer une.",al={"emplacement de la gemme d'âme","où trouver la gemme d'âme","gemme d'âme du dark strand"}},{q="Qui est Delgren le Purificateur ?",a="Delgren le Purificateur est un champion de l'Alliance en poste au Poste de Maestra, dans le nord d'Orneval. Il combat les forces qui envahissent la forêt, en particulier le Culte du Dark Strand.",al={"delgren","qui est delgren"}},{q="Qu'est-ce que le Culte du Dark Strand ?",a="Le Culte du Dark Strand est une secte établie dans la Tour d'Althalaxx, à Sombrivage, et dans d'anciennes ruines elfiques comme celles d'Ordil'Aran, en Orneval. Ses membres pratiquent la sorcellerie noire, la liaison des âmes et des rites de nécromancie.",al={"culte du dark strand","qui sont les membres du dark strand"}},{q="Pourquoi une quête de Sombrivage m'envoie-t-elle en Orneval ?",a="Le Culte du Dark Strand étend son influence depuis la Tour d'Althalaxx, à Sombrivage, jusqu'en Orneval. Delgren le Purificateur, au Poste de Maestra, sait comment contrer la magie du culte qui lie les âmes.",al={"pourquoi le poste de maestra","pourquoi aller en orneval"}},{q="Que se passe-t-il quand la gemme d'âme est déchiffrée ?",a="Delgren prévoit de déchiffrer le sombre enchantement de la Gemme d'âme luminescente. Vous découvrirez ce qu'il trouve après la lui avoir apportée.",al={"que contient la gemme d'âme","fantôme de la gemme d'âme"}},{q="Où se trouve Ordil'Aran ?",a="Ordil'Aran est une ancienne ruine elfique au nord-est du Poste de Maestra, dans le nord d'Orneval. Le Culte du Dark Strand l'a envahie.",al={"emplacement d'ordil'aran","où se trouve ordil'aran"}}},fx={a63b3648={q="Pourquoi Delgren le Purificateur veut-il que cela soit fait ?",a="Delgren est engagé dans un combat contre le Culte du Rivage sombre, qui s'est retranché au nord-est du Poste de Maestra. Pour lui, ils sont une épine dangereuse qui doit être arrachée complètement. Les avertissements terribles contenus dans la lettre de Balthule Frappelombre confirment que leur influence corrompue s'intensifie, et Delgren pense que percer les secrets piégés dans leur gemme d'âme enchantée est le seul moyen d'exposer et de démanteler leur pouvoir.",al={"mobile de delgren","pourquoi delgren veut-il la gemme d'âme","pourquoi combattre le culte du rivage sombre"}},c112c454={q="À quoi sert la Gemme d'âme luminescente ?",a="La Gemme d'âme luminescente est un sombre artefact enchanté transporté par le Culte du Rivage sombre aux Ruines d'Ordil'Aran. Delgren pense qu'elle détient le secret de la vile magie du culte et du pouvoir qu'ils exercent. En lui apportant la gemme, vous permettez à Delgren de déchiffrer les sombres enchantements tissés dans la pierre et de découvrir quelle essence ou entité y est piégée.",al={"qu'est-ce que la gemme d'âme luminescente","but de la gemme d'âme luminescente","gemme d'âme du rivage sombre"}},d0742ede={q="Contre qui êtes-vous envoyé aux Ruines d'Ordil'Aran ?",a="Vous êtes envoyé affronter le Culte du Rivage sombre qui occupe les ruines des Ruines d'Ordil'Aran, au nord-est du Poste de Maestra. Cultistes, fanatiques, acolytes et adeptes lanceurs de sorts se sont rassemblés parmi les ruines elfiques pour mener des rites interdits. L'un de leurs membres porte une gemme d'âme enchantée dont Delgren a besoin pour percer les secrets du culte, ce qui vous oblige à vous frayer un chemin à travers leurs rangs jusqu'à ce que la relique soit récupérée.",al={"qui est aux ruines d'ordil'aran","le culte du rivage sombre aux ruines d'ordil'aran","qui détient la gemme d'âme"}}},fp="22,227,24.334.0,25.322.0,16.347.1,37.199.0,28.173.0,36.214.0,49.182.0,45.126.1,28.130.0"}
P.entries["quest:97003"] = {n="Chol'aruk the Ravener",s="Dans les Tarides, Gur'ak envoie des voyageurs traquer un colossal quilboar nommé Chol'aruk the Ravener. Il croit ces récits et leur demande de revenir avec sa tête.",h="Dans les Tarides, Gur'ak envoie des voyageurs traquer un colossal quilboar nommé Chol'aruk the Ravener.",kw={"les tarides","chol'aruk","cholaruk","gur'ak","gurak","quilboar","dos-hirsute","the ravener","colline des épines"},ang={["class:Hunter"]="En tant que Chasseur, traquer une bête qui serait cinq fois plus grande qu'un quilboar ordinaire exige un instinct affûté et de se préparer à affronter une proie redoutable.",["class:Warrior"]="En tant que Guerrier, vous affrontez une créature brutale, animée d'une soif de sang inextinguible. Préparez-vous à résister à sa fureur physique écrasante.",["faction:Horde"]="Gur'ak, un orc, appelle les voyageurs de la Horde à traquer une menace dangereuse dans les Tarides au cri de guerre « Sang et tonnerre »."},sec={{t="La légende du Ravener",b="Les quilboars Dos-hirsutes murmurent le nom de Chol'aruk, une terreur immense qu'ils appellent The Ravener. Ils disent qu'il niche au fond d'une caverne de la Colline des épines, au nord-est des sentiers locaux. Selon eux, il fait environ cinq fois la taille d'un quilboar ordinaire et sa soif de sang est inextinguible. Beaucoup rejettent ces récits, les prenant pour des exagérations de veillée. Gur'ak sait qu'il en est autrement, car il a déjà combattu des bêtes semblables."},{t="L'avertissement de Gur'ak",b="Gur'ak sait qu'une bête de cette taille représente un véritable danger. Il charge les voyageurs capables de traquer Chol'aruk jusqu'à son repaire de la Colline des épines, de mettre fin à la menace et de rapporter sa tête en guise de preuve. Le Ravener serait féroce et colossal. Gur'ak avertit que seuls des groupes bien préparés devraient pénétrer dans la caverne pour l'affronter."}},faq={{q="Qui est Chol'aruk the Ravener ?",a="Les Dos-hirsutes appellent Chol'aruk un quilboar immense connu sous le nom de The Ravener. Ils disent qu'il fait environ cinq fois la taille d'un quilboar ordinaire, qu'il a une soif de sang inextinguible et qu'il niche dans une profonde caverne des Tarides.",al={"qui est cholaruk","qu'est-ce que cholaruk","the ravener"}},{q="Où trouver Chol'aruk ?",a="Chol'aruk niche au fond d'une caverne de la Colline des épines, au nord-est du campement de Gur'ak dans les Tarides. Les voyageurs doivent pénétrer dans les cavernes de la Colline des épines pour l'atteindre.",al={"où se trouve cholaruk","emplacement de cholaruk","où se trouve la caverne de la colline des épines"}},{q="Qui propose de traquer Chol'aruk ?",a="Gur'ak, un orc des Tarides, envoie des voyageurs traquer Chol'aruk. Il croit les rumeurs, car il a déjà affronté des bêtes semblables.",al={"qui donne la quête de cholaruk","qui est gurak","gurak dans les tarides"}},{q="Pourquoi Gur'ak traque-t-il Chol'aruk ?",a="Gur'ak veut éliminer Chol'aruk, car il terrorise la région. Il demande la tête tranchée de la bête comme preuve que le Ravener est tombé.",al={"pourquoi tuer cholaruk","raison de la prime sur cholaruk"}},{q="Puis-je affronter Chol'aruk seul ?",a="Gur'ak avertit les voyageurs de ne pas affronter Chol'aruk seuls. Sa taille et sa soif de sang rapportées en font un adversaire redoutable ; il demande donc un groupe de chasse bien préparé.",al={"peut-on affronter cholaruk seul","cholaruk est-il difficile","groupe pour cholaruk"}},{q="Quel lien unit Chol'aruk aux quilboars Dos-hirsutes ?",a="Les quilboars Dos-hirsutes parlent de Chol'aruk avec effroi et l'appellent The Ravener. Les Dos-hirsutes sont une tribu de quilboars qui vit dans certaines parties des Tarides, et les quilboars sont des humanoïdes à l'allure de sanglier originaires du centre de Kalimdor.",al={"que sont les quilboars","cholaruk et les dos-hirsutes","pourquoi les dos-hirsutes le craignent-ils"}}},fp="21,155,25.395.0,16.307.0,29.209.0,29.149.0,34.130.0,32.141.0,31.151.0,68.209.0"}
P.entries["quest:97005"] = {n="Chol'aruk the Ravener",s="Sur la Colline des épines, dans les Tarides, Chol'aruk the Ravener hante une grotte. Bainham veut sa tête tranchée pour venger ses compagnons tués par des bêtes semblables.",h="Sur la Colline des épines, dans les Tarides, Chol'aruk the Ravener hante une grotte.",kw={"abomination","bainham","tarides","chol'aruk","razormane","le vorace","colline des épines"},ang={["class:Hunter"]="En tant que chasseur, traquer un prédateur réputé capable d'avaler tout rond des guerriers en armure mettra à l'épreuve votre adresse et votre sang-froid.",["class:Warrior"]="En tant que guerrier, vous pouvez répondre à l'appel de Bainham en affrontant une horreur gigantesque dans son repaire souterrain et en vengeant vos compagnons tombés.",["faction:Horde"]="Des monstres incontrôlés sur les hauts plateaux menacent les voyageurs et les caravanes qui traversent les Tarides. Tuer cette bête contribuerait à protéger la région."},sec={{t="Terreur de la Colline des épines",b="Au nord-ouest du camp de Bainham, la Colline des épines s'élève au-dessus de la savane des Tarides. Les tribus Razormane se disputent son plateau depuis longtemps. On raconte maintenant qu'une abomination monstrueuse rôde dans l'une de ses grottes. Les Razormane l'appellent Chol'aruk ou le Vorace. Certains voyageurs doutent qu'elle puisse avaler un orc en armure tout entier. Ceux qui ont vu le carnage savent que le danger est bien réel."},{t="Une rancune assouvie",b="Bainham sait que Chol'aruk n'est pas une histoire à raconter au coin du feu. Il a combattu des horreurs semblables et porte les cicatrices de ces affrontements. Ses compagnons ont péri sous les coups de telles bêtes, et il les pleure encore. Il craint que l'abomination ne menace tous ceux qui traversent la savane. Bainham demande à des champions aguerris de gravir la Colline des épines, de pénétrer dans son repaire souterrain, de tuer Chol'aruk et de rapporter son énorme tête."}},faq={{q="Quelle créature est Chol'aruk ?",a="Chol'aruk est une abomination monstrueuse qui vit dans une grotte de la Colline des épines. Selon les rumeurs, elle peut avaler un orc adulte tout entier, et les Razormane l'appellent le Vorace.",al={"qui est chol'aruk","type de monstre chol'aruk","qui est le vorace"}},{q="Où se trouve le repaire de Chol'aruk ?",a="Chol'aruk vit dans une grotte du haut plateau de la Colline des épines, au nord-ouest des Tarides.",al={"où se trouve chol'aruk","emplacement de chol'aruk","grotte de la colline des épines"}},{q="Qui est Bainham et pourquoi veut-il la mort de Chol'aruk ?",a="Bainham vit dans les Tarides et a combattu des bêtes semblables à Chol'aruk. Il veut la tuer pour venger les alliés qu'il a perdus face à de telles abominations.",al={"qui donne la quête de chol'aruk","pourquoi tuer chol'aruk","histoire de bainham"}},{q="Que signifie « le Vorace » ?",a="Les quilboars Razormane appellent Chol'aruk le Vorace, un nom lié à son appétit insatiable. Selon les rumeurs, la créature dévore des guerriers adultes tout entiers.",al={"signification de chol'aruk","pourquoi l'appeler le vorace","chol'aruk razormane"}},{q="Les quilboars Razormane vénèrent-ils Chol'aruk ou le craignent-ils ?",a="Personne ne sait si les quilboars Razormane craignent ou vénèrent Chol'aruk. Ils l'appellent Chol'aruk ou le Vorace, mais on n'en sait pas davantage sur leurs sentiments envers l'abomination de la grotte de la Colline des épines.",al={"les quilboars aiment-ils chol'aruk","razormane et chol'aruk"}},{q="Quelle preuve faut-il apporter pour confirmer la mort de Chol'aruk ?",a="Bainham vous demande de rapporter la tête tranchée de Chol'aruk pour prouver sa mort.",al={"rendre la quête de chol'aruk","que rapporter à bainham"}}},fp="21,141,20.371.0,15.372.0,35.145.0,34.81.0,51.134.0,29.135.0,52.198.0,52.78.0"}
P.entries["quest:97048"] = {n="Returning to Port",s="Un cuisinier sauvé vous demande de parler à la capitaine Aransas, à Baie-du-Butin. Son retour compte pour elle, qui a perdu un membre de son équipage.",h="Un cuisinier sauvé vous demande de parler à la capitaine Aransas, à Baie-du-Butin.",kw={"baie-du-butin","capitaine aransas","cuisinier","équipage","base de kurzen","mathers","retour au port"},sec={{t="De retour auprès de la capitaine",b="La capitaine Aransas vous attend à Baie-du-Butin, où vous ramenez le cuisinier à son navire. Il promet de dire du bien de vous à son retour et assure que la capitaine sera ravie de le retrouver. Elle vous accueille et entend le récit de Mathers sur votre évasion de la Base de Kurzen."},{t="Les remerciements de la capitaine",b="La capitaine Aransas sait que le récit de Mathers sur ses prouesses à l’épée est un mensonge. Elle dit que le cuisinier ne sait manier qu’un couteau de cuisine. Elle vous remercie tout de même d’avoir sauvé un membre de son équipage. Un bon cuisinier est précieux à bord de son navire."}},faq={{q="Qui est la capitaine Aransas ?",a="La capitaine Aransas commande le navire dont vous ramenez le cuisinier à Baie-du-Butin.",al={"capitaine aransas","aransas"}},{q="Qui est Mathers ?",a="Mathers est le cuisinier de la capitaine Aransas et un membre de son équipage.",al={"mathers","cuisinier mathers"}},{q="Où trouver la capitaine Aransas ?",a="La capitaine Aransas se trouve à Baie-du-Butin.",al={"emplacement d’aransas","capitaine à baie-du-butin"}},{q="Pourquoi la capitaine me remercie-t-elle ?",a="Elle vous remercie d’avoir sauvé un membre de son équipage.",al={"raison des remerciements","cuisinier sauvé"}},{q="Qu’a raconté Mathers au sujet de l’évasion ?",a="Mathers a dit à la capitaine Aransas que vous vous étiez échappés ensemble de la Base de Kurzen.",al={"récit de mathers","qu’a-t-il raconté à aransas"}}},fp="17,137,19.272.0,20.212.1,23.76.0,15.58.0,32.32.0,30.47.0,38.85.0"}
P.entries["quest:971"] = {n="La connaissance des profondeurs",s="À Forgefer, Gerrig Poigne-d'os vous envoie outre-mer chercher un manuscrit ancien. Il veut le Manuscrit de Lorgalis, dans les ruines englouties des Profondeurs de Brassenoire, en Orneval.",h="À Forgefer, Gerrig Poigne-d'os vous envoie outre-mer chercher un manuscrit ancien.",kw={"orneval","profondeurs de brassenoire","forlorn cavern","gerrig poigne-d'os","forgefer","la connaissance des profondeurs","manuscrit de lorgalis"},ang={["class:Warlock"]="Dans la Forlorn Cavern de Forgefer, Poigne-d'os travaille aux côtés des démonistes qui s'y cachent. Il partage leur soif de textes interdits capables de plier les plans.",["faction:Alliance"]="Aider un érudit de l'Alliance semble sans danger, mais les motivations de Poigne-d'os et ses alliés obscurs annoncent des projets plus sinistres dans les murs de Forgefer.",["race:NightElf"]="Le manuscrit se trouve dans les Profondeurs de Brassenoire, un sanctuaire elfe de la nuit englouti, désormais occupé par des sectateurs et d'autres intrus."},sec={{t="Un érudit dans l'ombre",b="Dans la Forlorn Cavern de Forgefer, Gerrig Poigne-d'os rassemble des textes anciens. Ses intérêts dépassent l'histoire ordinaire et les archives civiles. Il cherche un savoir oublié qui peut ouvrir des portes et éveiller « Ceux qui dorment ». \n\nPoigne-d'os parle de survivre « à la fin des temps ». Ces paroles le font passer pour un érudit excentrique ou un adepte de puissances assoupies dans l'ombre."},{t="Les ruines englouties de Lorgalis",b="Poigne-d'os vous envoie vers les rivages ombragés d'Orneval, où le sanctuaire elfe de la nuit des Profondeurs de Brassenoire repose sous les eaux. Avant que la Grande Fracture ne déchire Kalimdor, les érudits elfes de la nuit rassemblaient de vastes connaissances magiques dans les temples côtiers. \n\nÀ présent, nagas, satyres et sectateurs du Marteau du crépuscule rampent dans les salles inondées. Le Manuscrit de Lorgalis, un savoir interdit, se trouve parmi eux dans un Pitted Iron Chest."},{t="Frères et sœurs",b="Quand Gerrig Poigne-d'os reçoit le manuscrit détrempé, il ne le dépose pas au Hall of Explorers de Forgefer. Il se réjouit à l'idée que des copies seront faites et partagées avec ses mystérieux « frères et sœurs ». \n\nIl remercie l'aventurier de l'Alliance qui l'a récupéré, mais ses loyautés vont à une secte clandestine avide d'utiliser ce savoir dans des rites capables de changer le monde. Poigne-d'os est lié au Marteau du crépuscule, dont les adeptes recherchent le savoir interdit des Dieux très anciens."}},faq={{q="Qui donne la quête La connaissance des profondeurs ?",a="C'est Gerrig Poigne-d'os qui donne la quête. Ce nain cherche des connaissances et vit dans la Forlorn Cavern, à Forgefer.",al={"donneur de quête","où prendre la quête","qui lance la quête la connaissance des profondeurs"}},{q="Qu'est-ce que le Manuscrit de Lorgalis ?",a="Le Manuscrit de Lorgalis est un texte que Gerrig Poigne-d'os veut récupérer dans les Profondeurs de Brassenoire. Il se trouve dans un Pitted Iron Chest, parmi les ruines inondées.",al={"qu'est-ce que le manuscrit de lorgalis","histoire du manuscrit de lorgalis","quel livre trouver"}},{q="Où se trouve le Manuscrit de Lorgalis ?",a="Le Manuscrit de Lorgalis se trouve au fond des Profondeurs de Brassenoire, le long de la grève de Zoram, sur la côte nord-ouest d'Orneval, en Kalimdor.",al={"emplacement du manuscrit de lorgalis","où trouver le livre dans les profondeurs de brassenoire","emplacement du livre dans les profondeurs de brassenoire"}},{q="Qui sont « Ceux qui dorment », mentionnés par Gerrig Poigne-d'os ?",a="Poigne-d'os désigne par « Ceux qui dorment » les puissances assoupies décrites dans le savoir interdit qu'il rassemble.",al={"ceux qui dorment","de qui parle poigne-d'os","que vénère gerrig"}},{q="Qui sont les « frères et sœurs » avec qui Gerrig compte partager le manuscrit ?",a="Les associés de Poigne-d'os partagent son intérêt pour le savoir interdit. La récupération du manuscrit peut révéler davantage sur ceux qu'il sert.",al={"frères et sœurs de gerrig","pour qui travaille gerrig","faction de poigne-d'os"}},{q="Pourquoi une quête à Forgefer envoie-t-elle les joueurs jusqu'en Orneval ?",a="La Forlorn Cavern de Forgefer attire les utilisateurs de magie non autorisés, les démonistes et les voleurs en quête de secrets cachés à la lumière. Poigne-d'os rassemble un savoir ancien et puissant, et le Manuscrit de Lorgalis qu'il recherche se trouverait sous les Profondeurs de Brassenoire, en Orneval, l'ancien foyer d'elfes morts depuis longtemps qui détenaient de grandes connaissances.",al={"pourquoi aller en orneval","quête de forgefer aux profondeurs de brassenoire","aller aux profondeurs de brassenoire"}}},fx={["32faf93b"]={q="Pourquoi Gerrig Poigne-d'os veut-il le Manuscrit de Lorgalis ?",a="Gerrig Poigne-d'os collectionne des textes anciens et puissants capables d'ouvrir des portes oubliées et d'éveiller Ceux qui dorment. Il pense que le Manuscrit de Lorgalis détient des secrets perdus depuis longtemps des anciens elfes de la nuit des Profondeurs de Brassenoire, et il a l'intention de copier et de distribuer ses sombres connaissances parmi ses frères et soeurs secrets avant la venue des derniers jours.",al={"mobile de gerrig poigne-d'os","pourquoi gerrig veut-il le manuscrit","raison de la quête de gerrig poigne-d'os"}}},fp="22,175,24.364.0,27.407.0,20.458.1,43.110.0,32.145.0,41.129.0,55.102.0,77.123.1,68.305.0"}
P.entries["quest:97130"] = {n="Ancient Gurubashi Secrets",s="Lan'dalock et un compagnon vous demandent de récupérer une idole dans une ancienne ruine gurubashi, récemment émergée au large de la Vallée de Strangleronce. Le site pourrait receler de précieux indices sur la magie du sang gurubashi.",h="Lan'dalock et un compagnon vous demandent de récupérer une idole dans une ancienne ruine gurubashi, récemment...",kw={"idole gurubashi antique","secrets gurubashi antiques","magie du sang","cité engloutie","gurubashi","lan'dalock","mers du sud","vallée de strangleronce","médecins des ombres"},sec={{t="Une ruine émergée",b="Lan'dalock et un compagnon discutent d'un étrange changement dans les Mers du sud. Une ancienne ruine gurubashi est apparue au large des côtes de la Vallée de Strangleronce. Son retour soudain attire l'attention de ceux qui étudient le passé."},{t="Une idole des Gurubashi",b="La Cité engloutie regorge d'artefacts d'une grande valeur archéologique. Lan'dalock recherche une idole dont certains médecins des ombres gurubashi se servaient comme catalyseur pour la magie du sang. On vous demande d'en rapporter une pour l'étudier."}},faq={{q="Qui veut l'idole ?",a="Lan'dalock et un compagnon recherchent une Idole gurubashi antique dans la Cité engloutie.",al={"qui m'a envoyé","idole de lan'dalock","qui la veut"}},{q="Où la ruine gurubashi est-elle apparue ?",a="L'ancienne ruine gurubashi est apparue au large des côtes de la Vallée de Strangleronce, dans les Mers du sud.",al={"où se trouve la cité engloutie","emplacement de la ruine","cité gurubashi"}},{q="Pourquoi veulent-ils une idole ?",a="Certains anciens médecins des ombres gurubashi se servaient d'idoles comme catalyseurs pour la magie du sang, et Lan'dalock en veut une pour l'étudier.",al={"pourquoi une idole","utilité de l'idole","à quoi sert-elle"}},{q="Qu'est-ce que la Cité engloutie ?",a="C'est une ancienne ruine gurubashi apparue au large des côtes de la Vallée de Strangleronce.",al={"cité engloutie","ruines gurubashi englouties","ruines anciennes"}}},fp="25,179,12.220.0,24.204.0,19.80.0,36.90.0,25.114.0,25.81.0"}
P.entries["quest:97196"] = {n="The Coldbringer's Eye",s="Un serviteur du Lich King observe depuis les Souilles de Tranchebauge grâce à Coldbringer’s Eye. On vous demande de récupérer l’orbe afin de traquer les agents infiltrés du Fléau sur Kalimdor.",h="Un serviteur du Lich King observe depuis les Souilles de Tranchebauge grâce à Coldbringer’s Eye.",kw={"amnennar","coldbringer","coldbringer's eye","death's head quilboar","lich king","souilles de tranchebauge","fléau","orbe de divination"},sec={{t="Un orbe dans le repaire",b="Un orbe de divination permet à Amnennar the Coldbringer d’observer et de diriger ses serviteurs ailleurs. Il réside au cœur des Souilles de Tranchebauge, le repaire des quilboars Death's Head. On vous demande de récupérer Coldbringer's Eye, qui pourrait aider à traquer les agents infiltrés du Fléau sur Kalimdor."}},faq={{q="Qui est Amnennar the Coldbringer ?",a="Amnennar the Coldbringer est un serviteur du Lich King qui réside dans les Souilles de Tranchebauge.",al={"amnennar","qui est coldbringer"}},{q="Qu’est-ce que Coldbringer's Eye ?",a="Coldbringer's Eye est un orbe de divination dont Amnennar se sert pour observer et diriger ses serviteurs ailleurs.",al={"coldbringer's eye","l’orbe de l’œil"}},{q="Où se trouve Coldbringer's Eye ?",a="Coldbringer's Eye se trouve dans les Souilles de Tranchebauge, dans le repaire d’Amnennar the Coldbringer.",al={"où se trouve l’œil","orbe des souilles de tranchebauge"}},{q="Pourquoi veut-on l’orbe ?",a="L’orbe pourrait aider à traquer les agents infiltrés du Fléau sur Kalimdor et à mettre fin à la menace qu’ils représentent.",al={"pourquoi récupérer l’œil","agents du fléau"}}},fp="21,172,18.262.0,32.84.0,30.97.0,31.79.0,22.94.0"}
P.entries["quest:972"] = {n="Le sapta d'eau",s="Sur la rive d’Islen Oeil-des-rivières, un jeune chaman de la Horde reçoit le sapta d’eau pour traverser la Grande mer. L’épreuve le mène des Tarides à la Forêt des Pins-Argentés, où une source a été corrompue.",h="Sur la rive d’Islen Oeil-des-rivières, un jeune chaman de la Horde reçoit le sapta d’eau pour traverser la...",kw={"call of water","islen oeil-des-rivières","épreuve du chaman","forêt des pins-argentés","les tarides","quête du totem d’eau","le sapta d'eau"},ang={["class:Shaman"]="En tant que chaman, vous franchissez une étape décisive de vos épreuves élémentaires avec le sapta d’eau. Il vous ouvre les yeux sur le monde des esprits avant que vous ne maîtrisiez votre Totem d’eau guérisseur.",["faction:Horde"]="En tant que membre de la Horde, vous voyez cette épreuve envoyer les initiés des plaines brûlées par le soleil de Kalimdor aux bois hantés de Lordaeron."},sec={{t="Une vision de l’eau",b="Chez les chamans de la Horde, un sapta est une décoction qui ouvre les sens aux esprits du monde. Un ruisseau peut sembler calme et un étang immobile aux yeux ordinaires. Buvez un sapta, et le voile du monde physique se déchire. Les élémentaires qui vivent dans l’eau deviennent alors visibles."},{t="La route vers la Forêt des Pins-Argentés",b="Après que le chaman a prouvé son dévouement aux esprits, Islen Oeil-des-rivières lui donne la décoction. Elle vit seule sur la rive désolée au sud de Cabestan. Puis elle envoie l’initié traverser la Grande mer, des vallées arides de Kalimdor jusqu’à la Forêt des Pins-Argentés. Là, une corruption élémentaire empoisonne les cours d’eau de Lordaeron, et le chaman doit l’affronter."}},faq={{q="Qu’est-ce qu’un sapta d’eau ?",a="Un sapta est une décoction rituelle préparée par des mentors chamaniques. Il aiguise la vision spirituelle et permet aux chamans de voir et de parler avec des élémentaires invisibles aux yeux des mortels.",al={"qu’est-ce qu’un sapta","signification du sapta d’eau","effet du sapta"}},{q="Qui est Islen Oeil-des-rivières ?",a="Islen Oeil-des-rivières est une maîtresse chaman qui vit seule sur la côte est des Tarides, au sud de la Côte des marchands. Elle guide les jeunes chamans de la Horde sur la voie difficile qui mène à communier avec l’élément de l’eau et à le soumettre.",al={"histoire d’islen oeil-des-rivières","qui est islen"}},{q="Pourquoi le chaman doit-il se rendre dans la Forêt des Pins-Argentés ?",a="Les élémentaires de l’eau souffrent d’un mal qui s’étend dans la Forêt des Pins-Argentés. Pour achever leur initiation, les chamans transportent le sapta par-delà la mer et découvrent une source corrompue de leurs propres yeux, puis en purifient la souillure.",al={"pourquoi la forêt des pins-argentés","pourquoi aller dans les royaumes de l’est"}},{q="Que se passe-t-il après avoir bu le sapta ?",a="Après avoir bu le sapta, les chamans peuvent voir les élémentaires de l’eau corrompus dans les bassins souillés de la Forêt des Pins-Argentés. Cette vision leur permet d’affronter la source du fléau.",al={"boire le sapta","effet du sapta"}},{q="Cette épreuve est-elle obligatoire pour tous les chamans de la Horde ?",a="Oui. Les chamans orcs, taurens et trolls répondent tous à l’Appel de l’eau et reçoivent le sapta lors d’un rite de passage, avant de gagner leur Totem d’eau.",al={"qui fait cette quête","quête de classe chaman"}},{q="Où se trouve le bassin corrompu dans la Forêt des Pins-Argentés ?",a="La source corrompue se trouve sur la côte de la Forêt des Pins-Argentés, à l’ouest du Sépulcre.",al={"emplacement du bassin dans la forêt des pins-argentés","où se trouve le bassin d’eau"}}},fx={c8d11240={q="Pourquoi Islen Oeil-des-rivières vous envoie-t-elle dans la Forêt des Pins-Argentés ?",a="Islen Oeil-des-rivières cherche à vous guider à travers votre rite de passage spirituel, vous aidant à vous accorder aux forces élémentaires de l'eau. Pour gagner la communion avec les esprits de l'eau et terminer la Call of Water, vous devez faire face à la souillure qui afflige les voies navigables du monde et la purifier. Elle vous a confié une Water Sapta préparée afin que vous puissiez percevoir la corruption élémentaire cachée de première main et prouver votre dévotion en tant que chamane en herbe.",al={"pourquoi islen veut-elle que cela soit fait","mobile d'islen oeil-des-rivières","pourquoi nettoyer l'eau corrompue"}}},fp="11,195,17.259.0,22.331.0,22.160.0,23.207.0,48.216.0,38.157.0,44.138.0,50.78.0"}
P.entries["quest:97220"] = {n="Philmor's Favor",s="Une cargaison fragile doit être livrée au Gatehouse, à Hurlevent, dans le cadre de Philmor's Favor. Faute de dockers, des voyageurs la transportent jusqu'à l'entrée d'une réserve située au-dessus de Trias' Cheese, dans le Quartier commerçant.",h="Une cargaison fragile doit être livrée au Gatehouse, à Hurlevent, dans le cadre de Philmor's Favor.",kw={"elaine","gatehouse","cargaison du gatehouse","philmor","philmor's favor","hurlevent","quartier commerçant","trias' cheese"},ang={["faction:Alliance"]="En tant que membre de l'Alliance, vous contribuez à maintenir les livraisons dans le Quartier commerçant de Hurlevent malgré le manque de dockers."},sec={{t="La logistique sous tension à Hurlevent",b="Les transporteurs de marchandises de Hurlevent manquent de dockers, ce qui perturbe les horaires habituels des cargaisons. Ils comptent sur des voyageurs dignes de confiance pour acheminer des caisses sensibles dans le quartier commerçant de la ville et maintenir les livraisons."},{t="Livraisons discrètes chez Trias' Cheese",b="La cargaison destinée au Gatehouse doit être livrée à une destination inhabituelle. Portez la caisse au deuxième étage de Trias' Cheese, dans le Quartier commerçant, où une entrée dissimulée donne sur une réserve. Les fournitures et les cadeaux de cérémonie destinés aux officiers de la garde y transitent à l'abri des regards indiscrets."}},faq={{q="Qui a besoin d'aide pour cette livraison ?",a="Les transporteurs de marchandises de Hurlevent ont besoin d'aide pour respecter les horaires des cargaisons, car les dockers manquent à l'appel.",al={"qui donne philmor's favor","donneur de quête philmor"}},{q="Où se trouve la destination de la livraison ?",a="Apportez la cargaison à l'entrée de la réserve du Gatehouse, au deuxième étage de Trias' Cheese, dans le Quartier commerçant de Hurlevent.",al={"où apporter le colis","livraison trias' cheese","où se trouve l'entrée du gatehouse"}},{q="Qui reçoit la cargaison ?",a="Elaine, la gérante de Trias' Cheese, s'occupe des marchandises discrètes destinées à la réserve voisine du Gatehouse.",al={"qui est elaine","elaine trias' cheese"}},{q="Que contient la cargaison destinée au Gatehouse ?",a="La cargaison contient des marchandises fragiles destinées au Gatehouse. Les transporteurs locaux font preuve de discrétion pour les livraisons liées aux surprises de cérémonie destinées aux officiers de la garde.",al={"que contient le colis","contenu de la livraison du gatehouse"}},{q="Pourquoi accéder à une réserve militaire par une fromagerie ?",a="Trias' Cheese dispose d'un accès à l'étage supérieur vers la réserve du Gatehouse. Les marchandises peuvent ainsi y transiter discrètement sans passer par l'entrée principale militaire.",al={"pourquoi trias' cheese et le gatehouse","entrée secrète trias' cheese"}},{q="Pourquoi manque-t-il de dockers ?",a="Les effectifs du port et du transport de marchandises sont réduits toute la semaine. Les coordinateurs logistiques comptent donc sur les voyageurs pour respecter les horaires de livraison.",al={"pourquoi manque-t-il de dockers","pénurie de dockers à hurlevent"}}},fp="15,191,31.219.0,36.281.0,34.99.0,34.121.0,26.99.0,38.147.0,59.142.0,34.141.0"}
P.entries["quest:97222"] = {n="Gatehouse Goods",s="À Hurlevent, Gatehouse Goods relie Trias' Cheese au corps de garde voisin. La cargaison emprunte les escaliers de la boutique jusqu'à un palier du même étage, où les gardes peuvent la récupérer devant la réserve. Des locaux partagés relient les commerces et les défenses de la ville.",h="À Hurlevent, Gatehouse Goods relie Trias' Cheese au corps de garde voisin.",kw={"livraison","elling trias","gatehouse goods","cargaison pour le corps de garde","réserve","hurlevent","trias cheese"},ang={["class:Rogue"]="En tant que voleur, vous savez vous déplacer sans bruit dans Trias' Cheese et remarquer des détails comme les portes qui s'ouvrent vers l'intérieur.",["faction:Alliance"]="En tant que membre de l'Alliance, vous aidez à acheminer des marchandises entre les commerçants de Hurlevent et le corps de garde voisin, grâce à des livraisons discrètes à Trias' Cheese."},sec={{t="Des locaux et des étages partagés",b="Les coursiers montent une cargaison destinée au corps de garde par les escaliers de Trias' Cheese. La fromagerie est un commerce distinct avec son propre stock, mais son bâtiment partage un étage avec le corps de garde voisin. Depuis le palier supérieur, les coursiers peuvent acheminer des fournitures entre les deux locaux sans emprunter les grandes avenues."},{t="Un dépôt pratique",b="La caisse est laissée devant la porte de la réserve, sans être transportée à l'intérieur. Les gardes du corps de garde surveillent les livraisons et veillent à ce que quelqu'un récupère chaque colis en regagnant son poste. La porte s'ouvre vers l'intérieur : la caisse laissée dehors ne bloque donc pas l'entrée et ne gêne personne à l'intérieur."}},faq={{q="Qu'est-ce que Gatehouse Goods ?",a="Gatehouse Goods est une livraison à Hurlevent entre Trias' Cheese et le corps de garde voisin. Un coursier monte la cargaison et la laisse devant la porte de la réserve du corps de garde.",al={"qu'est-ce que gatehouse goods","quête gatehouse goods"}},{q="Où faut-il livrer la cargaison ?",a="La cargaison emprunte les escaliers de Trias' Cheese. Bien que la boutique soit un commerce distinct, son bâtiment partage un étage avec le corps de garde, et la caisse est laissée devant la réserve.",al={"trias cheese corps de garde","où va la livraison"}},{q="Pourquoi laisser la caisse devant la porte au lieu de la rentrer ?",a="Le coursier doit laisser la caisse devant la réserve. Les gardes du corps de garde surveillent les livraisons et veillent à ce que quelqu'un les rentre en regagnant son poste.",al={"pourquoi ne pas livrer à l'intérieur","qui récupère la caisse"}},{q="Pourquoi la porte de la réserve s'ouvre-t-elle vers l'intérieur ?",a="La porte de la réserve s'ouvre vers l'intérieur. Les marchandises laissées dehors ne bloquent donc pas l'entrée et ne gênent personne à l'intérieur.",al={"porte s'ouvrant vers l'intérieur trias","charnière de la porte de la réserve"}},{q="Trias' Cheese est-elle affiliée au corps de garde ?",a="Non. Trias' Cheese est un commerce distinct avec son propre stock, même s'il partage un étage avec le corps de garde.",al={"trias cheese fait-elle partie du corps de garde","stock de trias cheese"}},{q="Qui supervise la livraison des marchandises ?",a="Les responsables locaux organisent la livraison et attendent des coursiers qu'ils agissent avec professionnalisme et discrétion. Après un dépôt réussi qui laisse le seuil dégagé, ils remercient les coursiers fiables.",al={"qui confie gatehouse goods","qui réceptionne la livraison"}}},fp="15,269,33.307.0,20.281.0,24.184.0,47.186.0,65.171.0,40.106.0,47.109.0,39.181.0"}
P.entries["quest:97223"] = {n="Bloodtalon Matriarch",s="Près du Village de Sen'jin, les dresseurs affrontent la Bloodtalon Matriarch en cherchant ses petits. Sa meute est prisée pour sa vitesse et sa ruse, mais les adultes résistent au dressage. Les Sombrelances veulent mettre sa ponte à l'abri et élever des compagnons loyaux dès l'œuf.",h="Près du Village de Sen'jin, les dresseurs affrontent la Bloodtalon Matriarch en cherchant ses petits.",kw={"serres-de-sang","sombrelance","matriarche","raptor","œufs de raptor","raptors","village de sen'jin","sen'jin","montures trolls"},ang={["class:Hunter"]="En tant que chasseur, vous savez combien il est difficile de dompter une bête adulte aguerrie. Élever un prédateur dès sa naissance peut forger un véritable lien.",["faction:Horde"]="En tant que membre de la Horde, vous savez qu'élever les prédateurs locaux pour en faire des alliés loyaux aide à protéger le campement sombrelance et à renforcer la présence de la Horde sur la côte de Durotar.",["race:Troll"]="En tant que troll sombrelance, vous savez que les dresseurs du Village de Sen'jin apprécient les raptors comme compagnons agiles et montures de guerre. La lignée des Bloodtalon est estimée pour sa ruse et sa vitesse."},sec={{t="La lignée des Bloodtalon",b="Le long de la côte de Durotar, les raptors des Serres-de-sang sont prisés pour leur vitesse et leur ruse. Les dresseurs du Village de Sen'jin apprécient ces qualités chez les montures et compagnons fiables de la tribu Sombrelance. Pourtant, les raptors adultes ont des instincts tenaces et violents. Une fois adultes, les raptors sauvages sont presque impossibles à dompter."},{t="Préserver la lignée",b="Les tentatives répétées pour capturer et dresser la Matriarch n'ont fait qu'accroître son agressivité. Elle menace désormais le territoire alentour. Les trolls cherchent à protéger leur tribu et à préserver sa lignée. Ils doivent maîtriser cette mère dangereuse et sauver sa ponte, afin que la génération suivante puisse être élevée dès l'œuf comme alliée loyale."}},faq={{q="Qui est la Bloodtalon Matriarch ?",a="La Bloodtalon Matriarch est une raptor adulte féroce, dont la meute est connue pour sa vitesse et sa ruse. Les tentatives pour la capturer et la dresser ont échoué, car elle est devenue trop dangereuse à maîtriser. Les trolls sombrelances cherchent à mettre ses œufs à l'abri.",al={"qui est la bloodtalon matriarch","matriarche raptor des serres-de-sang","matriarche raptor"}},{q="Pourquoi faut-il s'occuper de la Bloodtalon Matriarch ?",a="La Matriarch est devenue une menace pour le territoire alentour, et les raptors adultes sont difficiles à dompter. En la maîtrisant et en mettant sa ponte à l'abri, les dresseurs du Village de Sen'jin peuvent protéger la tribu et préserver sa lignée.",al={"pourquoi tuer la matriarche","pourquoi capturer les œufs","pourquoi chasser la matriarche"}},{q="Pourquoi ne pas dompter la Matriarch ?",a="Les raptors adultes ont des instincts tenaces et violents et sont presque impossibles à dompter. Les dresseurs peuvent plutôt élever les petits dès l'œuf pour en faire des compagnons loyaux.",al={"peut-on dompter les raptors adultes","dresser un raptor adulte"}},{q="Que deviendront les petits de la Matriarch ?",a="La ponte capturée est amenée au Village de Sen'jin pour y être incubée et élevée. Les trolls comptent dresser les jeunes raptors dès leur naissance pour en faire des alliés fiables et des montures pour la tribu.",al={"que deviennent les œufs","petits de la matriarche","raptors à sen'jin"}},{q="Où cette quête se déroule-t-elle ?",a="Les opérations se déroulent près du Village de Sen'jin, sur la côte de Durotar. Les dresseurs y cherchent à élever des raptors loyaux pour la tribu Sombrelance.",al={"où rendre cette quête","quête des raptors de sen'jin"}},{q="Qu'est-ce qui distingue la meute des Bloodtalon ?",a="La meute des Serres-de-sang est prisée pour sa vitesse et sa ruse. Ces qualités rendent ses petits recherchés comme compagnons et montures, tandis que les raptors adultes résistent au dressage.",al={"caractéristiques des raptors des serres-de-sang","pourquoi les raptors des serres-de-sang"}}},fp="20,247,22.284.0,24.325.0,32.216.0,48.223.0,35.154.0,46.178.0,29.131.0,39.156.0"}
P.entries["quest:97225"] = {n="Forgotten Loa Idols",s="Les Sombrelances recherchent les Forgotten Loa Idols pour que leurs rites sacrés puissent se poursuivre. Ces reliques préservent le lien de la tribu avec ses esprits tutélaires.",h="Les Sombrelances recherchent les Forgotten Loa Idols pour que leurs rites sacrés puissent se poursuivre.",kw={"sombrelance","forgotten loa idols","idoles","loas","vénération","rituels","esprits","troll"},ang={["class:Priest"]="En tant que prêtre troll, vous comptez sur les rituels et les objets sacrés de vos ancêtres pour canaliser le pouvoir spirituel et honorer les loas.",["class:Shaman"]="En tant que chaman troll, vous invoquez les forces élémentaires tout en honorant les dieux sauvages et les loas ancestraux liés à la survie de votre tribu.",["faction:Horde"]="En tant que membre de la Horde, vous appartenez à une faction dont les Sombrelances sont l’un des membres fondateurs. Aider leurs anciens sacrés à préserver des artefacts religieux essentiels renforce l’unité tribale.",["race:Troll"]="En tant que troll sombrelance, la communion avec les loas est au cœur de votre vie spirituelle. Les idoles perdues permettent de poursuivre les rituels essentiels et contribuent à conserver la faveur des esprits pour la tribu."},sec={{t="Vestiges sacrés des loas",b="Les Sombrelances honorent les loas par des rites sacrés. Ces esprits animaux primordiaux et dieux sauvages font partie de l’héritage ancestral des trolls. Les idoles perdues sont nécessaires aux cérémonies qui leur rendent hommage. Sans elles, les guides spirituels ne peuvent accomplir les rites qui maintiennent la tribu en harmonie avec ses gardiens divins."},{t="Le lien des Sombrelances",b="Les Sombrelances approchent les loas avec respect et humble vénération. D’autres factions hostiles de trolls à travers Azeroth pratiquent des sacrifices de sang ou tentent de commander les esprits par la force. Perdre la faveur de leurs protecteurs serait une grave catastrophe pour les Sombrelances. Restaurer les idoles est donc essentiel à la préservation de la tribu."}},faq={{q="À quoi servent les Forgotten Loa Idols ?",a="Les Sombrelances ont besoin des idoles sacrées manquantes pour reprendre leurs rituels tribaux et honorer leurs esprits sauvages.",al={"forgotten loa idols","en quoi consiste cette quête","que sont les forgotten loa idols"}},{q="Que sont les loas ?",a="Les loas sont de puissants esprits primordiaux ancestraux et des divinités animales vénérées par les trolls. Les trolls les honorent par des offrandes, des prières et des cérémonies rituelles, en quête de protection, de faveur et de conseils spirituels.",al={"que sont les loas","dieux trolls","qui sont les loas"}},{q="Comment les Sombrelances considèrent-ils leurs loas par rapport aux autres tribus de trolls ?",a="Les Sombrelances approchent les loas avec une profonde vénération, un respect mutuel et le sens du devoir spirituel. Ils pensent que leur survie dépend de la faveur des esprits.",al={"lien entre les sombrelances et les loas","pourquoi vénérer les loas","les loas des autres tribus"}},{q="Pourquoi les idoles sont-elles nécessaires aux rituels tribaux ?",a="Les idoles sont des objets sacrés nécessaires aux rites tribaux. Sans elles, les anciens et les guides spirituels ne peuvent communier comme il se doit avec leurs esprits tutélaires ni les honorer.",al={"pourquoi avoir besoin des idoles","rôle des idoles des loas","pourquoi les idoles sont-elles importantes"}},{q="Pourquoi est-il si essentiel aux Sombrelances de conserver la faveur des loas ?",a="Les Sombrelances craignent de perdre la faveur et la protection des loas sans rites et offrandes appropriés, ce qui rendrait la tribu vulnérable dans un monde périlleux.",al={"que se passe-t-il si elles ne sont pas rendues","perdre la faveur","faveur des loas pour les sombrelances"}},{q="Qui souhaite le retour des Forgotten Loa Idols ?",a="Un guide spirituel des Sombrelances souhaite le retour des idoles. Il a hâte de reprendre les cérémonies communes et d’obtenir les bénédictions des protecteurs ancestraux de la tribu.",al={"qui donne les forgotten loa idols","donneur de quête","qui réclame les idoles"}}},fp="19,142,26.307.0,18.305.0,43.117.0,13.198.0,67.163.0,44.157.0,57.159.0,48.157.0"}
P.entries["quest:97234"] = {n="Reading Room",s="Au Roy's Book Club, les membres échangent des ouvrages anciens contre des œuvres récentes de la bibliothèque de Hurlevent. Des livres emballés assurent les échanges entre le club et la bibliothécaire.",h="Au Roy's Book Club, les membres échangent des ouvrages anciens contre des œuvres récentes de la bibliothèque...",kw={"livres","légendes","bibliothécaire","reading room","roy's book club","stormwind library","tomes"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous pouvez visiter la Royal Library dans le Donjon de Hurlevent. Les échanges civiques et savants contribuent à la vie intellectuelle de la cité."},sec={{t="Passions littéraires à Hurlevent",b="Le Roy's Book Club réunit des lecteurs à Hurlevent pour discuter de légendes classiques et d'écrits provocateurs. Pour renouveler ces échanges, les membres font tourner leurs lectures. Ils troquent des ouvrages anciens ou moins populaires contre des volumes plus récents de la bibliothèque de la ville."},{t="L’échange de livres",b="Le Roy's Book Club a conclu un accord de prêt durable avec la bibliothèque de Hurlevent. Roy emballe les livres rendus par le club d'une manière distinctive, et vous les apportez à la bibliothécaire. En échange, le club reçoit une nouvelle liste de tomes modernes."}},faq={{q="En quoi consiste la quête Reading Room ?",a="Le Roy's Book Club échange des livres anciens contre des tomes modernes de la bibliothèque de Hurlevent. Vous apportez à la bibliothèque un paquet emballé contenant des ouvrages moins populaires pour procéder à l'échange.",al={"quête reading room","qu'est-ce que reading room","histoire de reading room"}},{q="Qui est Roy ?",a="Roy dirige un club de lecture où les membres discutent de légendes et de littérature. Il s'est entendu avec la bibliothèque de Hurlevent pour renouveler les lectures et rend les livres empruntés en parfait état.",al={"qui est roy","club de lecture de roy","chef du club de lecture"}},{q="Où les livres sont-ils apportés ?",a="Les livres sont apportés à la bibliothèque de Hurlevent. La bibliothécaire reconnaît l'emballage distinctif du club de Roy et accepte les livres en échange d'écrits modernes.",al={"où vont les livres","dépôt à la bibliothèque de hurlevent","livraison de livres emballés"}},{q="Pourquoi échanger les livres ?",a="Grâce à son accord d'emprunt avec la bibliothèque de la ville, le club échange des livres moins populaires contre des ouvrages plus modernes et stimulants.",al={"pourquoi échanger des livres","pourquoi rendre les tomes","échange de livres"}},{q="Que pense la bibliothécaire de Hurlevent du club de lecture ?",a="La bibliothécaire de Hurlevent apprécie cet accord. Le club de Roy rend les livres empruntés en excellent état et prend soin de chaque texte, même lorsque son sujet est provocateur.",al={"avis de la bibliothécaire","le club de lecture est-il autorisé","accord avec la bibliothèque"}},{q="Quelles sont les boissons et collations mentionnées pour le club ?",a="Le club offre gratuitement des rafraîchissements aux clients et aux personnes qui l'aident à échanger des livres entre le lieu de réunion et les archives de la ville.",al={"rafraîchissements offerts au club","avantages du club","quels rafraîchissements"}}},fp="12,163,30.238.0,20.236.0,31.161.0,11.185.0,32.154.0,34.135.0,52.182.0,41.136.0"}
P.entries["quest:97236"] = {n="Crochet de Githyiss",s="Près d’Aldrassil, la chasse de Githyiss fournit un spécimen rare au sanctuaire. Les érudits peuvent étudier le croc de l’araignée géante et surveiller les prédateurs de Sombrevallon.",h="Près d’Aldrassil, la chasse de Githyiss fournit un spécimen rare au sanctuaire.",kw={"aldrassil","fang of githyiss","githyiss","sombrevallon","araignée","étude des araignées","teldrassil"},ang={["class:Druid"]="En tant que druide, vous veillez à l’équilibre naturel de Teldrassil en étudiant les prédateurs inhabituels et les araignées démesurées des terres sauvages environnantes.",["faction:Alliance"]="En tant qu’aventurier de l’Alliance, vous aidez les chercheurs et les jeunes recrues à en apprendre davantage sur la faune dangereuse près d’Aldrassil, à travers Teldrassil.",["race:NightElf"]="En tant que jeune aventurier elfe de la nuit à Sombrevallon, vous aidez à défendre Teldrassil en affrontant des créatures dangereuses et en prêtant main-forte aux chercheurs d’Aldrassil."},sec={{t="Un spécimen monstrueux",b="Githyiss menace les voyageurs dans les terres sauvages de Sombrevallon. Le croc de l’araignée géante représente à la fois un danger et un spécimen digne d’étude. Des éclaireurs le transportent à travers les sous-bois jusqu’au sanctuaire sous le grand arbre."},{t="Recherches à Aldrassil",b="À Aldrassil, les naturalistes et les érudits elfes de la nuit observent la faune qui parcourt le sol forestier. Un croc frais et intact provenant d’une araignée aussi grande que Githyiss peut leur en apprendre davantage sur les arachnides sous la canopée de Teldrassil. Les chercheurs accueillent cette découverte tandis qu’ils étudient les créatures agressives de la clairière."}},faq={{q="Qu’est-ce que le Fang of Githyiss ?",a="Ce croc est un spécimen frais provenant de la grande araignée Githyiss. Sa taille fournit aux chercheurs un rare sujet d’étude sur les prédateurs arachnides près d’Aldrassil.",al={"qu’est-ce que le fang of githyiss","quête du fang of githyiss","objet fang of githyiss"}},{q="Qui ou qu’est-ce que Githyiss ?",a="Githyiss est une araignée imposante et dangereuse qui rôde dans les forêts près d’Aldrassil, à Sombrevallon. Sa taille menace les voyageurs et suscite l’intérêt des naturalistes locaux.",al={"qui est githyiss","araignée githyiss","où se trouve githyiss"}},{q="Qui veut le Fang of Githyiss ?",a="Un érudit d’Aldrassil qui étudie les araignées veut le croc. Des spécimens frais aident les chercheurs à mieux connaître les arachnides locales.",al={"qui rend le fang of githyiss","où apporter le croc","chercheur en araignées aldrassil"}},{q="Où se trouve Aldrassil ?",a="Aldrassil est la grande ramure de Sombrevallon et son sanctuaire central, au sein de la cime de l’Arbre-monde Teldrassil. Les jeunes elfes de la nuit s’y entraînent et y trouvent refuge.",al={"où se trouve aldrassil","emplacement d’aldrassil"}},{q="Pourquoi les érudits d’Aldrassil étudient-ils les crocs d’araignée ?",a="Les érudits et les naturalistes d’Aldrassil étudient les araignées locales pour comprendre l’écologie de Sombrevallon et surveiller les bêtes agressives et démesurées sous la canopée de Teldrassil.",al={"pourquoi étudier les araignées à aldrassil","pourquoi étudier les crocs d’araignée"}},{q="Les joueurs de la Horde peuvent-ils rendre le Fang of Githyiss ?",a="Non. Sombrevallon, l’enclave de départ des elfes de la nuit au sommet de Teldrassil, est accessible aux aventuriers de l’Alliance qui commencent leur périple à Aldrassil.",al={"cette quête est-elle réservée à l’alliance","la horde peut-elle faire le fang of githyiss"}}},fp="16,158,20.218.0,21.285.0,29.145.0,24.165.0,31.125.0,19.157.0,52.169.0,47.133.0"}
P.entries["quest:97237"] = {n="Shelf Picked",s="À Hurlevent, Roy Lewells envoie un coursier chercher des livres pour un cercle de lecture dans le Park.",h="À Hurlevent, Roy Lewells envoie un coursier chercher des livres pour un cercle de lecture dans le Park.",kw={"club de lecture","coursier","library","le parc","roy lewells","shelf picked","hurlevent"},ang={["faction:Alliance"]="Les courses entre les bibliothèques de Hurlevent et les lieux de réunion locaux font partie du quotidien dans la capitale, même au milieu des tensions plus larges qui agitent le royaume."},sec={{t="Une course pour les rayonnages",b="Roy Lewells a envoyé un mot pour demander plusieurs livres à la bibliothèque de Hurlevent. La bibliothécaire vérifie la liste et confirme que tous les titres sont disponibles. Les livres sont là, à vous de les trouver et de les prendre sur les étagères. La bibliothécaire reste au comptoir pour tenir l’inventaire."},{t="Le club de lecture de la cave",b="Le mot de Roy Lewells fait de vous un coursier officiel, vous n’avez donc pas à rapporter les livres empruntés. Cette tâche revient à l’établissement de Lewells. Une fois les volumes apportés au Park, Roy les prépare pour des discussions animées après les heures d’ouverture, dans une cave. Les livres ont une odeur exotique."}},faq={{q="Qui donne la quête Shelf Picked ?",a="Une bibliothécaire qui supervise la bibliothèque de Hurlevent vous confie cette tâche après avoir reçu le mot de Roy Lewells. Elle confirme que les livres demandés sont disponibles et vous demande de les prendre sur les étagères.",al={"qui donne shelf picked","donneur de quête de shelf picked","où commence shelf picked"}},{q="Qui est Roy Lewells ?",a="Roy Lewells organise un cercle de lecture local dans le Park de Hurlevent. Il envoie des coursiers chercher des livres à la bibliothèque pour les discussions du groupe après les heures d’ouverture, dans une cave.",al={"qui est roy lewells","roy lewells park","qui est lewells"}},{q="Où la collecte des livres a-t-elle lieu ?",a="Les livres sont récupérés dans une bibliothèque de Hurlevent. La bibliothécaire tient l’inventaire pendant que vous cherchez sur les étagères les titres demandés par Roy Lewells.",al={"de quelle library s'agit-il","où les livres sont-ils récupérés","quelle library shelf picked"}},{q="Pourquoi Roy Lewells a-t-il besoin de ces livres ?",a="Roy Lewells a besoin des livres pour un club de lecture informel dont les membres se réunissent dans une cave pour des discussions animées après la fermeture.",al={"pourquoi récupérer des livres pour lewells","qu'est-ce que le club de lecture de lewells","club de lecture en cave en dehors des heures d'ouverture"}},{q="Êtes-vous responsable du retour des livres empruntés ?",a="Non. Grâce au mot de Roy Lewells, vous agissez comme un coursier officiel. Son établissement est chargé de rapporter les livres empruntés.",al={"suis-je responsable du retour des livres","qui rend les livres de shelf picked","responsabilité du book return de la library"}},{q="Où apportez-vous les livres une fois récupérés ?",a="Vous apportez les livres rassemblés à Roy Lewells dans le Park de Hurlevent.",al={"où rendre shelf picked","où trouver roy lewells","rendre shelf picked"}}},fp="12,89,24.274.0,23.294.0,33.201.0,19.175.0,42.154.0,38.122.0,53.127.0,44.65.0"}
P.entries["quest:97242"] = {n="Yelmak's Medley",s="Les tensions montent chez Yelmak's Alchemy and Potions, dans la Vallée de l’Honneur d'Orgrimmar. Le maître alchimiste Yelmak espère qu'un mélange apaisant à base de plantes aquatiques locales calmera la frustration maladroite et la fierté obstinée de son apprenti Whuut.",h="Les tensions montent chez Yelmak's Alchemy and Potions, dans la Vallée de l’Honneur d'Orgrimmar.",kw={"alchimie","quenouille","kor'geld","orgrimmar","herbe piquante","vallée de l’honneur","whuut","yelmak","yelmak's medley"},ang={["faction:Horde"]="En tant que membre de la Horde, vous contribuez à apaiser les tensions dans la Vallée de l’Honneur d'Orgrimmar et au sein de son commerce alchimique.",["profession:Herbalism"]="En tant qu'herboriste, vous cueillez des quenouilles fraîches et des herbes piquantes le long des cours d'eau d'Orgrimmar. Les plantes locales servent à préparer des concoctions et des infusions."},sec={{t="Des problèmes au laboratoire",b="Chez Yelmak's Alchemy and Potions, la fierté du jeune apprenti Whuut sème le trouble. Plutôt que de demander de l'aide quand il est dépassé, il casse le matériel de la boutique sous le coup de la frustration. Le maître alchimiste Yelmak cherche à apaiser le jeune homme sans froisser son ego fragile et prépare donc une concoction calmante."},{t="Les plantes locales apaisantes",b="La recette demande des quenouilles fraîches et des herbes piquantes cueillies le long des cours d'eau qui serpentent dans la Vallée de l’Honneur. Kor'geld ne peut pas quitter la boutique sans alerter l'apprenti méfiant : il faut donc que quelqu'un cueille discrètement les plantes. Ce mélange botanique doit tempérer l'attitude de Whuut et rétablir la paix dans la boutique d'alchimie."}},faq={{q="Qui propose la quête Yelmak's Medley ?",a="Kor'geld propose cette tâche au nom du maître alchimiste de la boutique. Vous le trouverez chez Yelmak's Alchemy and Potions, dans la Vallée de l’Honneur d'Orgrimmar.",al={"qui donne yelmak's medley","donneur de quête yelmak's medley"}},{q="Qui est Whuut ?",a="Whuut est un apprenti préparateur qui se forme auprès de Yelmak, dans la Vallée de l’Honneur. Sa fierté obstinée le pousse à casser du matériel plutôt qu'à admettre qu'il a besoin de conseils ou d'aide.",al={"qui est whuut","apprenti de yelmak","whuut orgrimmar"}},{q="À quoi sert le mélange maison ?",a="Ce mélange maison doit apaiser l'apprenti orgueilleux de Yelmak et calmer sa mauvaise humeur. Il contient des quenouilles fraîches et des pousses d'herbes piquantes.",al={"quelle est la recette de yelmak's medley","que veut préparer yelmak"}},{q="Où trouve-t-on les ingrédients ?",a="Des quenouilles sauvages et des herbes piquantes poussent le long des ruisseaux et des mares d'eau douce de la Vallée de l’Honneur, à Orgrimmar.",al={"où trouver des quenouilles et des herbes piquantes","pousses de la vallée de l’honneur"}},{q="Pourquoi Kor'geld ne cueille-t-il pas lui-même les pousses ?",a="Kor'geld ne peut pas quitter Yelmak's Alchemy and Potions sans que Whuut comprenne que le personnel de la boutique s'adapte à son tempérament difficile.",al={"pourquoi kor'geld a-t-il besoin d'aide","pourquoi kor'geld ne peut-il pas cueillir les plantes"}},{q="Où se trouve Yelmak's Alchemy and Potions ?",a="Yelmak's Alchemy and Potions se trouve dans la Vallée de l’Honneur, un quartier à l'est d'Orgrimmar. Ses cours d'eau serpentent entre des casernes de guerriers et des boutiques d'artisans.",al={"où se trouve yelmak's alchemy and potions","emplacement de la boutique de yelmak"}}},fp="15,228,25.302.0,20.325.0,37.142.0,13.167.0,46.140.0,35.117.0,52.131.0,46.149.0"}
P.entries["quest:97243"] = {n="Call of Fire",s="À Mur-Céleste, les initiés apportent la Torch of Dormant Flame à Olariaan Swiftburn pour recevoir son enseignement. Le sanctuaire se trouve dans les Plaines Aérelles.",h="À Mur-Céleste, les initiés apportent la Torch of Dormant Flame à Olariaan Swiftburn pour recevoir son...",kw={"call of fire","plan élémentaire","plaines aérelles","olariaan swiftburn","shen'dorei","shrine of flames","mur-céleste","torch of dormant flame","valanaar","sculpte-vents"},ang={["class:Shaman"]="Être à l’écoute des éléments est fondamental dans la formation des chamans. Même à Mur-Céleste, communier avec le feu exige un enseignement dédié et le respect des ancêtres.",["race:Skyborne"]="Bien que vous soyez natifs des vents de Mur-Céleste, vous et les Sculpte-vents savez que l’équilibre exige d’honorer les quatre éléments primordiaux."},sec={{t="Des voix venues du plan élémentaire",b="Mur-Céleste appartient aux élémentaires de l’air, bien que ses courants rejoignent le vaste plan élémentaire. Les esprits de la terre, de l’eau et du feu parlent encore à ceux qui peuvent les entendre. Certains Sculpte-vents sont particulièrement réceptifs à ces autres forces. Olariaan Swiftburn, un shen'dorei parmi eux, est profondément lié au feu."},{t="Le sanctuaire des flammes",b="Les initiés apportent la Torch of Dormant Flame dans les Plaines Aérelles. Au loin, le long du bord de l’île, à l’ouest de Valanaar, se dresse le Shrine of Flames, où vit Olariaan Swiftburn. Olariaan reçoit la flamme dormante et propose d’apprendre aux étudiants désireux d’écouter l’exigeant appel du feu au milieu des courants tumultueux du royaume de l’air."}},faq={{q="Qui est Olariaan Swiftburn ?",a="Olariaan Swiftburn est un Sculpte-vents shen'dorei, profondément lié au feu. Olariaan vit au Shrine of Flames, au bord des Plaines Aérelles, à l’ouest de Valanaar.",al={"qui donne l’appel du feu","à qui apporter la torche","olariaan swiftburn"}},{q="Où se trouve le Shrine of Flames ?",a="Le Shrine of Flames se trouve dans les Plaines Aérelles de Mur-Céleste. Il se dresse au bord de l’étendue d’îles flottantes, juste à l’ouest de Valanaar.",al={"où se trouve le shrine of flames","emplacement des plaines aérelles","comment trouver olariaan"}},{q="Pourquoi étudie-t-on le feu à Mur-Céleste ?",a="Mur-Céleste appartient à l’air, mais fait toujours partie du vaste plan élémentaire. Les esprits des quatre éléments parlent encore à ceux qui sont assez réceptifs pour les écouter.",al={"pourquoi le feu à mur-céleste","feu du plan élémentaire","mur-céleste n’est-il pas seulement lié à l’air"}},{q="Qu’est-ce que la Torch of Dormant Flame ?",a="La Torch of Dormant Flame est un catalyseur élémentaire que l’on apporte à Olariaan Swiftburn. Un initié la lui apporte pour apprendre à communier avec le feu.",al={"qu’est-ce que la flamme dormante","torch of dormant flame","quel objet apporter"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents s’exercent à naviguer parmi les forces élémentaires de Mur-Céleste et à les façonner. Leurs rangs rassemblent des individus d’origines diverses, comme les shen'dorei.",al={"qui sont les sculpte-vents","faction des sculpte-vents"}},{q="À quoi mène cette quête ?",a="Olariaan Swiftburn apprend à ses disciples à écouter l’appel du feu. Maîtriser les forces primordiales dans le domaine exigeant de Mur-Céleste demande une grande persévérance.",al={"qu’enseigne olariaan","formation au feu à mur-céleste"}}},fp="12,133,33.297.0,20.312.0,26.163.0,30.145.0,37.152.0,35.145.0,24.146.0,29.142.0"}
P.entries["quest:97244"] = {n="Call of Fire",s="Les Sculpte-vents vous envoient traquer un traître qui a choisi le pouvoir plutôt que son ordre. Le prêtre du ciel Faladiel a fui dans les Plaines Aérelles, et ils ont besoin de son cœur pour un rituel.",h="Les Sculpte-vents vous envoient traquer un traître qui a choisi le pouvoir plutôt que son ordre.",kw={"al’aketh","call of fire","faladiel","cœur de faladiel","plaines aérelles","sanctuaire d’akir","prêtre du ciel faladiel","valanaar","sculpte-vents"},ang={["class:Priest"]="En tant que prêtre, vous pouvez voir la chute de Faladiel dans son renoncement à invoquer la flamme, puis dans sa trahison et le meurtre de membres de son propre ordre.",["class:Shaman"]="En tant que chaman accordé au feu et aux rites élémentaires, vous pouvez reconnaître la nature primordiale du sacrifice de l’essence d’un traître aux flammes pour intensifier leur pouvoir sacré."},sec={{t="Un traître parmi les flammes",b="Les Sculpte-vents vous envoient retrouver le prêtre du ciel Faladiel, qui fut autrefois l’un des leurs. Il a quitté l’ordre pour rejoindre les Al’Aketh et troqué sa vocation d’invocateur de la flamme contre le pouvoir. Il a trahi ses anciens frères et sœurs, et leur sang lui souille les mains. À présent, les Sculpte-vents vous chargent d’appliquer leur jugement."},{t="Le châtiment dans les plaines",b="Faladiel se cache dans une ferme des Plaines Aérelles, au nord-est, au-delà de Valanaar et juste au sud du Sanctuaire d’Akir. Les Sculpte-vents cherchent plus que la vengeance. Ils ont besoin de son cœur pour un rituel à venir. Ils pensent que le cœur d’un traître donnera à leurs flammes sacrées une intensité sans pareille."},{t="Le sang appelle le sang",b="Les Sculpte-vents restent fidèles à leur credo : le sang doit répondre au sang. Le cœur de Faladiel n’est qu’un élément de ce qui doit nourrir leur feu cérémoniel avant que leurs rites puissent s’achever."}},faq={{q="Qui est le prêtre du ciel Faladiel ?",a="Le prêtre du ciel Faladiel fut autrefois un invocateur de la flamme dévoué et un membre des Sculpte-vents. Il a rejoint les Al’Aketh pour obtenir le pouvoir, trahissant ses anciens frères et sœurs et se souillant les mains de leur sang.",al={"qui est faladiel","histoire de faladiel","histoire du prêtre du ciel faladiel"}},{q="Pourquoi les Sculpte-vents veulent-ils tuer Faladiel ?",a="Faladiel a trahi les Sculpte-vents pour le pouvoir et assassiné ses anciens frères et sœurs. Leur credo exige que le sang réponde au sang ; ils réclament donc son exécution en guise de châtiment.",al={"pourquoi tuer faladiel","pourquoi les sculpte-vents veulent-ils la mort de faladiel","trahison de faladiel"}},{q="Pourquoi les Sculpte-vents ont-ils besoin du cœur de Faladiel ?",a="Les Sculpte-vents ont besoin du cœur de Faladiel pour un rituel. Ils pensent que le cœur d’un traître fera brûler leurs flammes avec plus de chaleur et d’intensité.",al={"pourquoi le cœur de faladiel","à quoi sert le cœur","cœur comme ingrédient de rituel"}},{q="Où trouver le prêtre du ciel Faladiel ?",a="Le prêtre du ciel Faladiel se cache dans une ferme des Plaines Aérelles, au nord-est, au-delà de Valanaar et juste au sud du Sanctuaire d’Akir.",al={"où est faladiel","emplacement du prêtre du ciel faladiel","trouver faladiel"}},{q="Quel est le credo des Sculpte-vents ?",a="Le credo des Sculpte-vents veut que le sang soit payé par le sang. Ils pratiquent l’invocation de la flamme et des rituels élémentaires sacrés.",al={"qui sont les sculpte-vents","credo des sculpte-vents","faction des sculpte-vents"}},{q="Quel est le lien entre les Al’Aketh et cette mission ?",a="Les Al’Aketh comptent parmi eux des membres qui ont troqué leurs anciennes allégeances et leur honneur contre le pouvoir personnel. Le prêtre du ciel Faladiel est l’un d’eux.",al={"que sont les al’aketh","faladiel et les al’aketh","traîtres al’aketh"}}},fp="12,165,25.301.0,25.282.0,21.176.1,26.207.0,44.181.0,45.145.0,38.123.0,37.122.0,50.127.0"}
P.entries["quest:97245"] = {n="Call of Fire",s="Dans les Hautes-terres de Shen’dar, Olariaan Swiftburn vous envoie affronter Kuramaa, un ancien esprit sylvestre. Les flammes peuvent percer ses défenses, et son masque de bois est nécessaire dans les Plaines Aérelles pour allumer une flamme éternelle et communier avec les esprits du feu.",h="Dans les Hautes-terres de Shen’dar, Olariaan Swiftburn vous envoie affronter Kuramaa, un ancien esprit...",kw={"anchor pylon","call of fire","esprit sylvestre","plaines aérelles","kuramaa","masque de kuramaa","olariaan swiftburn","hautes-terres de shen’dar"},ang={["class:Mage"]="En tant que mage, vous découvrez que Kuramaa résiste à la plupart des formes de magie. Seule la magie du feu peut vaincre l’esprit.",["class:Shaman"]="En tant que chaman, vous affrontez un esprit des hautes-terres avec les flammes et puisez la force nécessaire pour communier avec les esprits du feu."},sec={{t="L’esprit des hautes-terres",b="Les habitants des Hautes-terres de Shen’dar parlent de Kuramaa, un ancien esprit sylvestre qui vit dans une souche d’arbre tortueuse. Celle-ci se dresse au sommet d’une colline, près de l’Anchor Pylon régional. Frappez l’écorce à poing nu, et Kuramaa sortira pour vous affronter."},{t="Le feu et le bois",b="Les protections naturelles de Kuramaa repoussent la plupart des magies arcaniques et divines. Seules les flammes brûlantes peuvent percer son écorce ancestrale et l’abattre. Vainquez l’esprit, et son masque de bois sera à vous, un puissant artefact. Pourtant, Kuramaa est éternel. Lorsqu’on l’appelle de nouveau, il se reforme."},{t="La flamme éternelle",b="Dans les Plaines Aérelles, Olariaan Swiftburn attend le masque de Kuramaa. Cette relique enchantée est nécessaire pour allumer une flamme éternelle et communier avec les esprits du feu. Vaincre les esprits de la nature des hautes-terres ouvre la voie à un ancien rite de communion avec les éléments."}},faq={{q="Qui est Kuramaa ?",a="Kuramaa est un ancien esprit sylvestre qui vit dans les Hautes-terres de Shen’dar. Selon les habitants, il réside dans une souche d’arbre tortueuse, au sommet d’une colline près de l’Anchor Pylon des hautes-terres.",al={"qui est kuramaa","histoire de kuramaa","qu’est-ce que kuramaa"}},{q="Qui est Olariaan Swiftburn ?",a="Olariaan Swiftburn est un ritualiste des Plaines Aérelles qui vous envoie affronter Kuramaa. Olariaan a besoin du masque de bois de l’esprit pour accomplir un rite sacré du feu.",al={"qui donne l’appel du feu","qui est olariaan swiftburn","où rendre l’appel du feu"}},{q="Comment invoquer Kuramaa ?",a="Kuramaa vit dans une souche d’arbre tortueuse, au sommet d’une colline près de l’Anchor Pylon des Hautes-terres de Shen’dar. Frappez l’écorce de la souche du poing, et l’esprit sortira pour combattre.",al={"comment invoquer kuramaa","où se trouve la souche de kuramaa","invoquer un esprit sylvestre"}},{q="À quoi Kuramaa est-il vulnérable au combat ?",a="Kuramaa résiste à la plupart des formes de magie. Seules les flammes peuvent percer ses défenses et abattre l’ancien esprit sylvestre.",al={"faiblesses de kuramaa","comment vaincre kuramaa","kuramaa immunisé à la magie"}},{q="Pourquoi Olariaan Swiftburn a-t-il besoin du masque de Kuramaa ?",a="Olariaan Swiftburn a besoin du puissant masque de bois de Kuramaa pour allumer une flamme éternelle et communier avec les esprits du feu.",al={"pourquoi récupérer le masque de kuramaa","à quoi sert le masque","utilité du masque de kuramaa"}},{q="Kuramaa est-il définitivement détruit quand on le vainc ?",a="Non. Kuramaa est éternel. Son esprit perdure après la défaite de sa forme physique, puis se manifeste à nouveau lorsqu’on l’appelle.",al={"kuramaa est-il mort","ai-je tué kuramaa","histoire de la réapparition de kuramaa"}}},fp="12,243,27.254.0,13.259.0,17.259.1,15.169.0,26.161.0,26.171.0,40.113.0,48.113.0,47.113.0"}
P.entries["quest:97246"] = {n="Meal Appeal",s="À Orgrimmar, Thatog s’inquiète que son jeune fils Migi saute des repas pour jouer. Il vous demande d’aller chercher son déjeuner au Borstan's Firepit et de retrouver Migi derrière Grommash Hold.",h="À Orgrimmar, Thatog s’inquiète que son jeune fils Migi saute des repas pour jouer.",kw={"borstan","borstan's firepit","grommash hold","livraison du déjeuner","meal appeal","migi","orgrimmar","thatog"},ang={["faction:Horde"]="À Orgrimmar, la vie quotidienne comprend aussi des préoccupations autres que la guerre et la défense. Thatog s’inquiète de nourrir les enfants comme Migi, qui courent dans la Vallée de la Force.",["race:Orc"]="En tant qu’orc, vous savez que des parents comme Thatog s’inquiètent lorsque leurs enfants négligent leurs repas pour jouer dans les rues de la capitale de Durotar."},sec={{t="Le devoir d’un parent à Orgrimmar",b="Les tâches quotidiennes de Thatog le retiennent à son poste à Orgrimmar. Il a peu de temps pour veiller sur Migi, son jeune fils plein d’énergie. Du matin au crépuscule, Migi court partout dans la ville avec ses amis. Il ignore souvent sa faim jusqu’à rentrer chez lui affamé."},{t="Livraison derrière le fort",b="Thatog fait préparer un déjeuner chaud pour Migi au Borstan's Firepit et vous demande de le lui apporter. Migi préfère continuer à jouer plutôt que de s’arrêter pour manger. Vous portez donc le repas dans la cour derrière Grommash Hold, où Migi et les enfants du quartier jouent."}},faq={{q="Qui est Thatog ?",a="Thatog est un parent orc d’Orgrimmar que ses tâches quotidiennes empêchent de veiller sur Migi, son jeune fils. Craignant que Migi saute des repas pour jouer avec ses amis, il vous demande de récupérer et de lui apporter son déjeuner.",al={"qui est thatog","donneur de quête thatog","thatog orgrimmar"}},{q="Où trouver Migi ?",a="Migi passe ses journées à jouer avec ses amis à Orgrimmar. Thatog vous dit que vous trouverez les enfants derrière Grommash Hold.",al={"où est migi","emplacement de migi","trouver migi"}},{q="Qu’est-ce que le Borstan's Firepit ?",a="Le Borstan's Firepit est un endroit où se procurer de la nourriture à Orgrimmar. Thatog vous demande d’y récupérer le déjeuner préparé pour Migi et de le lui apporter.",al={"où se trouve le borstan's firepit","emplacement du borstan's firepit","déjeuner de borstan"}},{q="Pourquoi Migi oublie-t-il de manger ?",a="Migi est tellement pris par ses jeux avec ses amis derrière Grommash Hold qu’il en oublie de manger. Il rentre souvent affamé à la fin de la journée.",al={"pourquoi migi saute-t-il le déjeuner","migi affamé","pourquoi migi ne mange-t-il pas"}},{q="Qui est Migi ?",a="Migi est le jeune fils de Thatog. Il passe son temps à jouer avec ses amis à Orgrimmar au lieu de rentrer chez lui ou de récupérer les repas préparés pour lui.",al={"qui est migi","enfant orc migi","fils de thatog"}},{q="Quel est l’objectif de Meal Appeal ?",a="Vous récupérez le déjeuner de Migi au Borstan's Firepit et le lui apportez derrière Grommash Hold, afin qu’il puisse manger tout en jouant.",al={"objectif de la quête meal appeal","que faire dans meal appeal","tâche de meal appeal"}}},fp="11,160,28.244.0,24.234.0,14.203.0,24.115.0,26.132.0,28.130.0,12.137.0,37.121.0"}
P.entries["quest:97249"] = {n="Favorite Food",s="À Orgrimmar, les parents de Migi craignent que ses jeux l’empêchent de manger à sa faim. Borstan de Borstan's Meats prépare des déjeuners variés au goût que Migi adore, et ses amis et lui s’arrêtent pour manger.",h="À Orgrimmar, les parents de Migi craignent que ses jeux l’empêchent de manger à sa faim.",kw={"borstan","borstan's meats","favorite food","grommash hold","poitrine de porc","déjeuner","migi","orgrimmar","glaçage sucré"},ang={["faction:Horde"]="Cette histoire montre le quotidien à Orgrimmar, où artisans et familles prennent soin des enfants de la capitale et veillent à ce qu’ils soient nourris.",["profession:Cooking"]="À Orgrimmar, Borstan transforme les grattons croustillants de poitrine de porc fumée en un assaisonnement savoureux pour les repas quotidiens."},sec={{t="Le goût du jeu",b="Derrière Grommash Hold, le jeune Migi et ses amis passent leurs après-midi à jouer sur les chemins poussiéreux d’Orgrimmar. Ses parents craignent qu’il néglige souvent ses repas et ne mange pas assez. Ils demandent donc à Borstan's Meats de préparer des paniers-repas chaque jour. Ils insistent pour que Borstan varie les repas, dans l’espoir que Migi apprenne à apprécier autre chose que son plat préféré."},{t="Un compromis sucré",b="Migi adore les sandwichs à la poitrine de porc glacée au sucre et vient déjeuner quand le fumoir embaume leur doux arôme. Borstan trouve un moyen de satisfaire les parents tout en nourrissant Migi. Il émiette les grattons glacés croustillants restants pour en faire un assaisonnement savoureux, à saupoudrer sur n’importe quel plat. Derrière Grommash Hold, cette garniture convainc Migi et ses compagnons de faire une pause et de partager leur déjeuner."}},faq={{q="Qui est Migi ?",a="Migi est un jeune habitant d’Orgrimmar qui joue avec ses amis derrière Grommash Hold. Ses parents craignent qu’il soit si absorbé par ses jeux qu’il ne mange pas assez. Ils organisent donc des déjeuners quotidiens préparés par Borstan's Meats.",al={"migi orgrimmar","qui est l’enfant derrière grommash hold","déjeuner de migi"}},{q="Qui donne la quête Favorite Food ?",a="Borstan de Borstan's Meats la donne à Orgrimmar. Après avoir appris que les parents de Migi s’inquiètent de ses habitudes alimentaires, il lui prépare un repas varié.",al={"personnage qui donne la quête favorite food","qui lance favorite food","borstan favorite food"}},{q="Où trouver Migi ?",a="Migi se trouve derrière Grommash Hold, à Orgrimmar, où il joue avec d’autres enfants du coin. Ils passent souvent sur la route qui mène à la forteresse et reconnaissent à leur odeur les repas que Borstan prépare chaque jour.",al={"emplacement de migi","où se trouve migi","où livrer le déjeuner de migi","trouver migi à orgrimmar"}},{q="Quel est le plat préféré de Migi ?",a="Migi adore le sandwich à la poitrine de porc glacée au sucre, préparé dans le fumoir de Borstan's Meats. Quand le fumoir fonctionne, son arôme l’attire vers le déjeuner, derrière Grommash Hold.",al={"qu’est-ce que migi aime manger","repas préféré de migi","poitrine de porc glacée au sucre migi"}},{q="Pourquoi les parents de Migi demandent-ils des repas variés ?",a="Les parents de Migi demandent à Borstan de varier les repas de leur fils pour qu’il apprenne à apprécier plusieurs plats. Ils veulent qu’il mange assez sans dépendre uniquement du porc glacé au sucre.",al={"pourquoi varier le déjeuner de migi","demande des parents de migi","pourquoi ne pas servir des sandwichs glacés au sucre chaque jour"}},{q="Comment Borstan incite-t-il Migi à goûter différents plats ?",a="Borstan émiette les grattons glacés croustillants restants pour en faire une garniture destinée à différents plats. Leur goût familier de glaçage sucré aide Migi à apprécier les repas variés.",al={"astuce de borstan","comment borstan incite-t-il migi à manger","miettes de glaçage sucré"}},{q="Qu’est-ce que Borstan's Meats ?",a="Borstan's Meats est un fumoir et une boucherie à Orgrimmar. Borstan fume des sandwichs à la poitrine de porc et prépare des repas à emporter pour les habitants de la ville, notamment les jeunes du quartier.",al={"borstan's meats orgrimmar","où se trouve borstan's meats","qu’est-ce que borstan"}}},fp="13,185,20.349.0,25.403.0,12.215.0,34.147.0,24.188.0,29.167.0,46.167.0,49.153.0,24.171.0"}
P.entries["quest:97250"] = {n="Wrongly Blamed, Justly Corrected",s="Sur la côte orientale, Wrongly Blamed, Justly Corrected suit la montée des tensions entre la Horde et l’Alliance après la destruction d’une taverne au bord d’une route. L’incident met les forces de l’Alliance en garde, tandis que l’on ignore toujours qui a menacé une voie commerciale civile vitale.",h="Sur la côte orientale, Wrongly Blamed, Justly Corrected suit la montée des tensions entre la Horde et...",kw={"avertissement à l’alliance","voie civile","côte orientale","commerce de la horde","taverne","conflit territorial","wrongly blamed, justly corrected"},ang={["faction:Alliance"]="Cette issue met l’Alliance en garde contre toute nouvelle présence et provocation sur la côte orientale.",["faction:Horde"]="La Horde remporte la victoire et adresse un avertissement contre les incursions de l’Alliance. Cette issue soulève aussi des inquiétudes quant à la protection des routes commerciales et des voies civiles dont dépend la Horde."},sec={{t="Frictions sur la côte",b="Sur la côte orientale, les escarmouches entre la Horde et l’Alliance gagnent les territoires contestés. Puis une taverne située sur un axe majeur est détruite. Les voyageurs ordinaires sont désormais en danger, et la stabilité de la région est menacée."},{t="Doute et perturbations",b="Les dirigeants locaux doutent que les forces de la Horde aient détruit la taverne, bien que les premiers soupçons se soient portés sur la Horde. Les civils et les marchands empruntent cette route pour transporter des marchandises, et la Horde a donc intérêt à la maintenir ouverte. Ils demandent que l’on examine de plus près qui a détruit la taverne."},{t="Un avertissement à l’Alliance",b="L’affaire se conclut par une victoire des forces de la Horde dans la région, même si des questions subsistent au sujet de la taverne. Cette issue avertit l’Alliance que toute incursion en territoire de la Horde le long de la côte rencontrera une résistance immédiate."}},faq={{q="De quoi parle Wrongly Blamed, Justly Corrected ?",a="Wrongly Blamed, Justly Corrected suit la montée des tensions entre la Horde et l’Alliance sur la côte orientale, après la destruction d’une taverne au bord d’une route commerciale vitale.",al={"de quelle quête s’agit-il","lore de wrongly blamed, justly corrected","que s’est-il passé dans wrongly blamed"}},{q="La Horde a-t-elle détruit la taverne ?",a="Les dirigeants de la Horde doutent que leurs forces aient détruit la taverne. Les civils de la Horde dépendent de cette route pour le commerce et leurs déplacements quotidiens ; sa destruction va donc à l’encontre de leurs intérêts.",al={"la horde a-t-elle détruit la taverne","qui a incendié la taverne","qui a détruit la taverne"}},{q="Pourquoi la taverne détruite importe-t-elle à la Horde ?",a="La taverne se trouve le long d’une route majeure empruntée par les voyageurs civils et les marchands. Sa destruction perturbe le commerce et les déplacements, ce qui fait de cette route une préoccupation pour la Horde.",al={"pourquoi la route de la taverne est-elle importante","pourquoi la taverne est-elle importante"}},{q="Qu’est-ce qui a provoqué les tensions sur la côte orientale ?",a="La cause des tensions n’est pas claire. Les frictions entre la Horde et l’Alliance s’intensifient sur la côte orientale, et le conflit a gagné le territoire de la Horde.",al={"pourquoi se battre sur la côte orientale","conflit sur la côte orientale"}},{q="Quel message cette issue adresse-t-elle à l’Alliance ?",a="Cette issue avertit l’Alliance que toute incursion en territoire de la Horde le long de la côte rencontrera une résistance.",al={"qu’a accompli la horde","pourquoi avertir l’alliance"}},{q="La destruction de la taverne fera-t-elle l’objet d’une enquête plus approfondie ?",a="Les dirigeants de la Horde cherchent à découvrir qui a détruit la taverne. Ses ruines menacent le passage des civils, et les circonstances restent suspectes.",al={"que faut-il examiner","la taverne fera-t-elle l’objet d’une enquête"}}},fp="32,254,21.212.0,20.248.1,25.211.0,47.160.0,33.171.0,50.162.0,42.162.0,52.105.0,61.139.0"}
P.entries["quest:97253"] = {n="Parts and Pieces",s="À Cabestan, la machine de Wrenix gît en pièces après que les pirates l'ont démontée. Il l'avait envoyée affronter les pillards après que cinq ou six Mercenaries ne sont pas revenus vivants. Ses pièces éparpillées se trouvent maintenant dans le camp supérieur des pirates.",h="À Cabestan, la machine de Wrenix gît en pièces après que les pirates l'ont démontée.",kw={"pièces complexes","machine","parts and pieces","pirate","pirates","cabestan","cimeterres","camp supérieur des pirates","wrenix le misérable"},ang={["profession:Engineering"]="Les ingénieurs verront peut-être l'ironie dans le fait que des pirates démontent une machine sophistiquée. Les pièces éparpillées de Wrenix illustrent le danger d'envoyer un prototype automatisé dans un camp hostile sans protections physiques."},sec={{t="Une solution mécanique",b="Les pirates qui longent la côte au sud de Cabestan causent des problèmes aux habitants et aux commerçants de la ville. Wrenix le Misérable voulait les arrêter sans risquer davantage de pièces en embauchant des mercenaires. Cinq ou six Mercenaries étaient déjà partis affronter les pirates et n'étaient pas revenus vivants.\n\nWrenix a donc envoyé une machine automatisée s'occuper seule du campement. Il espérait que cet engin pourrait affronter les maraudeurs sans mettre une autre âme vivante en danger."},{t="Cimeterres et tournevis",b="Les pirates au sud de Cabestan se sont montrés débrouillards. Ils ont utilisé leurs cimeterres courbés comme des tournevis de fortune et démonté la machine de Wrenix avant qu'il puisse lui ordonner de battre en retraite vers la ville.\n\nSes composants délicats sont maintenant éparpillés dans leur camp supérieur. Wrenix a besoin de quelqu'un pour s'y faufiler et ramasser cinq poignées de ces pièces complexes dans la poussière."}},faq={{q="Qui est Wrenix le Misérable ?",a="Wrenix le Misérable est un bricoleur excentrique de la ville portuaire de Cabestan. Après que cinq ou six Mercenaries ne sont pas revenus vivants des affrontements avec les pirates au sud de la ville, il a envoyé une machine automatisée les affronter. Les pirates l'ont démontée, et ses pièces sont éparpillées dans leur camp supérieur.",al={"qui est wrenix","histoire de wrenix le misérable","wrenix cabestan"}},{q="Qu'est-il arrivé aux premiers mercenaires engagés par Wrenix ?",a="Wrenix a engagé cinq ou six Mercenaries pour s'occuper des pirates au sud de Cabestan. Aucun n'est revenu vivant, alors il s'est tourné vers une machine.",al={"anciens mercenaires de wrenix","qu'est-il arrivé aux autres aventuriers","qui wrenix a-t-il envoyé en premier"}},{q="Pourquoi Wrenix a-t-il envoyé une machine combattre les pirates ?",a="Wrenix a envoyé une machine parce que cinq ou six Mercenaries qu'il avait engagés ne sont pas revenus vivants. Il espérait qu'un engin automatisé pourrait affronter les pirates sans mettre une autre âme vivante en danger.",al={"pourquoi envoyer une machine","plan du robot de wrenix","pourquoi wrenix a-t-il utilisé un engin"}},{q="Comment les pirates ont-ils démonté la machine de Wrenix ?",a="Les pirates ont utilisé leurs cimeterres courbés comme des tournevis de fortune pour démonter la machine de Wrenix. Ils ont éparpillé ses composants dans leur camp et réduit l'engin à son châssis avant que Wrenix puisse lui ordonner de battre en retraite vers Cabestan.",al={"comment la machine a-t-elle été détruite","comment les pirates ont-ils démonté le robot","cimeterres des pirates utilisés comme tournevis"}},{q="Où se trouvent les pièces complexes ?",a="Les pièces complexes sont éparpillées au sol dans le camp supérieur des pirates, sur la côte au sud de Cabestan. Ils les ont laissées là après avoir démonté la machine de Wrenix. Il faut en ramasser cinq poignées.",al={"où se trouvent les pièces","emplacement du camp supérieur des pirates","emplacement des poignées de pièces complexes"}},{q="Pourquoi Wrenix pense-t-il que cette mission de récupération est plus sûre ?",a="Wrenix pense qu'il est plus sûr de ramasser des pièces éparpillées que d'envoyer des mercenaires éliminer les pirates. Les mercenaires précédents ne sont pas revenus vivants ; il faut se faufiler dans le camp supérieur et ramasser cinq poignées de composants dans la poussière.",al={"parts and pieces est-elle sans danger","pourquoi wrenix pense-t-il que vous survivrez","chances de survie selon wrenix"}},{q="À quoi servent les pièces complexes ?",a="Les pièces complexes sont des morceaux de la machine automatisée de Wrenix. Il veut les récupérer pour que son travail d'ingénierie et ses matériaux ne soient pas entièrement gâchés.",al={"que sont les pièces complexes","pourquoi wrenix a-t-il besoin des pièces","que fait wrenix avec les pièces"}}},fp="16,217,21.426.0,26.363.0,27.277.0,54.135.0,51.180.0,47.262.0,40.206.0,56.254.0,42.154.0"}
P.entries["quest:97257"] = {n="Call of Fire",s="À Mur-Céleste, les initiés affrontent l’épreuve des Sculpte-vents et cherchent un Totem de feu. Ils invoquent des esprits des flammes, portent la Flamme éternelle jusqu’à Valanaar et en rallument le brasero.",h="À Mur-Céleste, les initiés affrontent l’épreuve des Sculpte-vents et cherchent un Totem de feu.",kw={"call of fire","flamme éternelle","totem de feu","terres de feu","olariaan","mur-céleste","valanaar","sculpte-vents"},ang={["class:Shaman"]="En tant que chaman, vous accomplissez ce rite d’initiation et gagnez un Totem de feu à l’issue de l’épreuve. Le totem vous confère la maîtrise du feu.",["race:Skyborne"]="En tant que Skyborne, vous suivez une tradition chamanique où les Sculpte-vents de Mur-Céleste guident les initiés dans le respect des plans élémentaires."},sec={{t="Le rituel des flammes",b="Olariaan des Sculpte-vents guide les initiés lors d’une épreuve sacrée à Mur-Céleste. Ils se rassemblent au Brazier of Offering et appellent les esprits des flammes des Terres de Feu. Si leurs offrandes sont dignes, les esprits embrasent l’autel avec la Flamme éternelle. Un initié digne peut alors prendre cette flamme."},{t="Le voyage vers Valanaar",b="La Flamme éternelle doit être recueillie sur une torche et portée à travers Mur-Céleste jusqu’à Valanaar. Dans ce royaume élémentaire, son pouvoir venu des Terres de Feu s’évanouit dans l’air tourbillonnant. L’initié doit atteindre le Brazier of Eternal Flames avant que la torche ne s’éteigne."},{t="Le Totem de feu",b="Lorsqu’un initié rallume le brasero à Valanaar, les Sculpte-vents lui accordent un Totem de feu. Celui-ci honore sa discipline et son respect des éléments. Les anciens enseignent que la puissance élémentaire sert ceux qui la respectent, mais consume ceux qui ne le font pas."}},faq={{q="Qu’est-ce que Call of Fire ?",a="Call of Fire envoie un aspirant chaman invoquer des esprits des flammes et recueillir la Flamme éternelle. La porter jusqu’à Valanaar prouve le respect de l’initié envers le plan élémentaire et lui vaut un Totem de feu.",al={"qu’est-ce que call of fire","quête call of fire","de quoi parle cette quête"}},{q="Qui est Olariaan ?",a="Olariaan dirige la cérémonie au Brazier of Offering. Il dépose des matériaux sur l’autel et appelle les esprits des flammes pour qu’ils embrasent la Flamme éternelle.",al={"qui est olariaan","rôle d’olariaan","qui commence le rituel"}},{q="Qu’est-ce que la Flamme éternelle ?",a="La Flamme éternelle provient des esprits des flammes appelés des Terres de Feu pendant le rituel des Sculpte-vents. Les initiés la recueillent sur une torche et s’en servent pour embraser le Brazier of Eternal Flames à Valanaar.",al={"qu’est-ce que la flamme éternelle","flamme éternelle à mur-céleste"}},{q="Pourquoi faut-il porter rapidement la flamme jusqu’à Valanaar ?",a="La flamme vient des Terres de Feu, et sa chaleur s’évanouit rapidement dans l’air de Mur-Céleste. Les initiés se hâtent pour que la torche reste allumée jusqu’à leur arrivée à Valanaar.",al={"pourquoi la flamme éternelle se dissipe","pourquoi se hâter vers valanaar","flammes des terres de feu à mur-céleste"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents sont un ordre de Mur-Céleste qui guide les initiés lors d’épreuves élémentaires. Ils honorent l’équilibre et la puissance des plans élémentaires et supervisent l’attribution des totems.",al={"qui sont les sculpte-vents","faction des sculpte-vents"}},{q="Quelle est la récompense pour avoir réussi l’épreuve ?",a="Un initié qui accomplit le rituel et rallume le brasero à Valanaar gagne un Totem de feu, un catalyseur qui permet de canaliser la puissance élémentaire du feu.",al={"récompense de call of fire","récompense totem de feu","que rapporte call of fire"}}},fp="12,164,19.298.0,23.246.0,14.247.0,25.197.0,16.148.0,26.201.0,50.148.0,24.178.0,44.140.0"}
P.entries["quest:97263"] = {n="Your Package Has Arrived",s="Un colis de Nid-de-l’Aigle repose près d’une boîte aux lettres de la ville, à destination de Forgefer. Signalé comme urgent pour Eldrun Stormbreaker, il attend toujours d’être livré.",h="Un colis de Nid-de-l’Aigle repose près d’une boîte aux lettres de la ville, à destination de Forgefer.",kw={"nid-de-l’aigle","eldrun stormbreaker","forgefer","boîte aux lettres","colis égaré","livraison urgente","marteaux-hardis","your package has arrived"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous savez qu’une communication fiable entre les Hinterlands et Forgefer compte pour les intérêts de l’Alliance dans Khaz Modan et les territoires du nord.",["race:Dwarf"]="En tant que nain, vous connaissez les liens entre les Barbe-de-Bronze de Forgefer et leurs cousins Marteaux-hardis de Nid-de-l’Aigle. Remettre ce colis à son destinataire en toute sécurité honore ces liens."},sec={{t="Fret égaré",b="Plusieurs colis sont abandonnés près d’une boîte aux lettres de la ville. Ils ont été laissés là au lieu d’être acheminés à destination. L’un d’eux, signalé comme urgent, vient de Nid-de-l’Aigle, le bastion montagnard des nains Marteaux-hardis dans les Hinterlands. Les livraisons entre des avant-postes éloignés de Khaz Modan et de Lordaeron peuvent mal tourner. Un passant vigilant peut remettre un colis égaré sur la bonne voie."},{t="Un colis pour Eldrun Stormbreaker",b="Le colis est adressé à Eldrun Stormbreaker, à Forgefer. La mention « urgent » indique que l’envoi doit parvenir sans délai de la région des Hinterlands à la capitale naine. Il reste à remettre la caisse à Eldrun avant qu’elle ne soit volée ou oubliée."}},faq={{q="Qu’est-ce que ce colis trouvé près de la boîte aux lettres ?",a="C’est un colis urgent de Nid-de-l’Aigle, dans les Hinterlands, adressé à Eldrun Stormbreaker, à Forgefer. Il a été laissé près d’une boîte aux lettres avec plusieurs autres paquets au lieu d’arriver à destination.",al={"qu’est-ce que le colis","colis égaré","qu’est-ce qui a été laissé près de la boîte aux lettres","colis près de la boîte aux lettres"}},{q="Qui est Eldrun Stormbreaker ?",a="Eldrun Stormbreaker est le destinataire indiqué sur le colis égaré à Forgefer. L’étiquette donne son nom et signale que le colis est urgent, mais n’en dit guère plus avant qu’il ne parvienne à son destinataire.",al={"qui est eldrun stormbreaker","eldrun stormbreaker","qui reçoit le colis","destinataire du colis"}},{q="D’où le colis a-t-il été envoyé ?",a="Le colis vient de Nid-de-l’Aigle, la colonie et forteresse montagnarde du clan Marteaux-hardis dans les Hinterlands. Il était destiné à Forgefer avant de s’égarer près d’une boîte aux lettres en chemin.",al={"d’où vient le colis","origine du colis","d’où a-t-il été envoyé","livraison de nid-de-l’aigle"}},{q="Pourquoi le colis a-t-il été signalé comme urgent ?",a="L’expéditeur a signalé la caisse comme urgente, car son contenu ou son heure d’arrivée comptait. Un retard sur la longue route entre Nid-de-l’Aigle et Forgefer pourrait causer des problèmes à Eldrun Stormbreaker.",al={"pourquoi est-il urgent","livraison urgente","que contient le colis","pourquoi est-ce urgent"}},{q="Pourquoi le colis a-t-il été laissé près d’une boîte aux lettres ?",a="Plusieurs colis ont été abandonnés près d’une boîte aux lettres au lieu d’être triés et livrés. On ignore pourquoi, et les paquets sont toujours égarés.",al={"pourquoi a-t-il été abandonné","pourquoi le colis a-t-il été laissé","courrier perdu","colis égarés"}},{q="Où faut-il livrer ce colis ?",a="Le colis est destiné à Forgefer et adressé à Eldrun Stormbreaker. Il faut le remettre à Eldrun dans la cité fortifiée des nains.",al={"où dois-je le livrer","destination du colis","lieu de livraison","à qui dois-je remettre le colis"}},{q="Quel lien existe entre Nid-de-l’Aigle et Forgefer ?",a="Nid-de-l’Aigle est le foyer des nains Marteaux-hardis, et Forgefer est le siège du clan Barbe-de-Bronze. Ces clans ont des coutumes et des foyers distincts, mais la correspondance, le commerce et les liens de parenté relient les Hinterlands à la Grande Forge sous la montagne.",al={"nid-de-l’aigle et forgefer","commerce entre les marteaux-hardis et les barbe-de-bronze","lien entre forgefer et nid-de-l’aigle","pourquoi envoyer du courrier depuis nid-de-l’aigle"}}},fp="24,144,17.359.0,32.258.0,41.199.0,27.195.0,31.198.0,33.183.0,46.149.0,45.138.0,56.245.0"}
P.entries["quest:97265"] = {n="Hate the Hatefury",s="Aka'rai, à Proie-de-l'Ombre, vous demande de frapper les satyres Hatefury à Sargeron. Sa rancœur vient d'un marché qui l'a poussé à chercher vengeance.",h="Aka'rai, à Proie-de-l'Ombre, vous demande de frapper les satyres Hatefury à Sargeron.",kw={"aka'rai","désolace","hate the hatefury","hatefury","sargeron","satyre","proie-de-l'ombre","pierre d'âme"},sec={{t="La rancœur d'Aka'rai",b="Aka'rai évoque un marché conclu avec un satyre, qui lui promettait puissance et savoir. Il affirme que les Hatefury l'ont rejeté, le laissant avec moins qu'auparavant. Il vous demande maintenant d'attaquer leur camp au nord-est de Proie-de-l'Ombre, à Sargeron. Leur sang est le prix qu'il exige pour sa vengeance."},{t="Le pacte de sang",b="Après les combats, Aka'rai affirme qu'un Hatefury a échappé à votre assaut. Il désigne ce satyre comme celui qui a participé avec lui à un rituel marqué par le sang versé. Le satyre détient la pierre d'âme d'Aka'rai, qui craint donc de quitter Proie-de-l'Ombre tant qu'elle reste entre ses mains. Pour l'heure, il estime que votre tâche est terminée."}},faq={{q="Qui demande de l'aide ?",a="Aka'rai, à Proie-de-l'Ombre, vous demande d'attaquer les satyres Hatefury à Sargeron.",al={"qui est aka'rai","aka rai","donneur hatefury"}},{q="Pourquoi Aka'rai veut-il faire attaquer les Hatefury ?",a="Aka'rai affirme que les Hatefury l'ont rejeté après un marché qui lui promettait puissance et savoir.",al={"pourquoi hatefury","vengeance d'aka'rai","rancune envers les satyres"}},{q="Où sont les Hatefury ?",a="Le camp des Hatefury se trouve à Sargeron, en Désolace, au nord-est de Proie-de-l'Ombre.",al={"emplacement des hatefury","satyres de sargeron","où est le camp"}},{q="Qu'espérait obtenir Aka'rai en concluant ce marché ?",a="Aka'rai affirme que le marché lui promettait la puissance, un savoir dépassant celui des ouvrages ordinaires et un serviteur zélé.",al={"marché d'aka'rai","marché avec un satyre","marché pour la puissance"}}},fp="17,149,19.285.0,17.298.1,23.80.0,44.91.0,23.78.0,29.94.0"}
P.entries["quest:97275"] = {n="Whuut's the Rush",s="Yelmak vous envoie porter un tonique à Whuut, dont l’empressement a pris le pas sur la prudence. Son apprenti convoite les herbes rares avant même de découvrir les propriétés des plantes communes.",h="Yelmak vous envoie porter un tonique à Whuut, dont l’empressement a pris le pas sur la prudence.",kw={"alchimie","lotus noir","quenouille","herboristerie","sauge-argent des montagnes","potion","herbe piquante","whuut","yelmak"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez vous inspirer de la patience de Yelmak et de son ingéniosité avec les ingrédients locaux de Kalimdor.",["profession:Herbalism"]="En tant qu’herboriste, vous savez qu’apprendre les propriétés des plantes du quotidien, comme l’herbe piquante et la quenouille, compte autant que rechercher des fleurs rares."},sec={{t="Le prodige impatient",b="Whuut a un don pour l’alchimie, et manier le bâtonnet lui vient naturellement. Pourtant, son impatience le pousse à utiliser les réactifs les plus rares de l’échoppe avant d’en maîtriser les bases. Il se tourne vers les plantes légendaires avant d’apprendre à équilibrer les herbes communes, comme si l’alchimie était une course."},{t="Une leçon en fiole",b="Yelmak répond à la précipitation de son apprenti par une leçon dans une fiole. Il prépare un tonique raffiné à base d’herbe piquante et de quenouille ordinaires, selon une méthode rapide. Whuut rêvasse à propos de Lotus noir et de Sauge-argent des montagnes lorsque le tonique lui parvient. Ses ingrédients simples montrent combien le savoir-faire, la patience et le respect des plantes du quotidien peuvent compter."}},faq={{q="Qui est Whuut ?",a="Whuut est le jeune apprenti de Yelmak et un alchimiste doué. Impatient d’expérimenter avec des herbes rares, il brûle les étapes et néglige les bases du métier.",al={"qui est whuut","histoire de whuut","à propos de whuut"}},{q="Qui est Yelmak ?",a="Yelmak est un alchimiste chevronné qui forme Whuut dans son échoppe. Il craint que le jeune alchimiste ne gaspille de précieuses fournitures.",al={"qui donne cette quête","rôle de yelmak","qui est yelmak"}},{q="Pourquoi Yelmak vous envoie-t-il porter une potion à Whuut ?",a="Yelmak vous envoie porter un tonique afin d’enseigner à Whuut la patience et le respect des bases. Il l’a préparé avec de l’herbe piquante et de la quenouille, des plantes ordinaires que Whuut négligeait.",al={"quelle leçon yelmak donne-t-il","pourquoi yelmak envoie-t-il la potion","but de la quête"}},{q="Quels ingrédients Yelmak a-t-il utilisés dans sa potion ?",a="Yelmak a utilisé de l’herbe piquante et de la quenouille pour préparer le tonique. Sa méthode minutieuse permet de tirer parti de ces plantes communes.",al={"que contient la potion","réactifs de la potion de yelmak","ingrédients du tonique rapide"}},{q="Quels réactifs rares Whuut voulait-il utiliser ?",a="Whuut convoitait le Lotus noir et la Sauge-argent des montagnes. Il avait délaissé les ingrédients du quotidien au profit de ces plantes rares.",al={"que préparait whuut","herbes rares convoitées par whuut","quels réactifs whuut a-t-il utilisés"}},{q="Whuut retient-il la leçon ?",a="Après avoir goûté le tonique et entendu sa recette, Whuut s’étonne que des plantes communes puissent donner un tel breuvage. Il reconnaît que Yelmak a raison et décide de prêter davantage attention aux plantes du quotidien qu’il avait dédaignées.",al={"whuut change-t-il d’avis","réaction de whuut à la potion","issue de whuut's the rush"}}},fp="16,161,17.283.0,18.341.0,13.140.0,14.131.0,49.165.0,46.106.0,50.130.0,28.213.0"}
P.entries["quest:97277"] = {n="Grund and Gozwin",s="Dans leur camp des collines du nord-ouest, Grund and Gozwin subissent l’attaque d’un léopard des neiges. Grund le chasse avec son fusil, mais Gozwin perd son Journal de mécano de Gozwin dans la cohue.",h="Dans leur camp des collines du nord-ouest, Grund and Gozwin subissent l’attaque d’un léopard des neiges.",kw={"nain","ingénieur gnome","gozwin","grund","mecha-walker","journal de mécano","léopard des neiges rôdeur"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous comprenez pourquoi les schémas et les notes du Journal de mécano de Gozwin l’inquiètent.",["race:Dwarf"]="En tant que nain, vous reconnaîtrez peut-être la rapidité avec laquelle Grund défend son compagnon gnome.",["race:Gnome"]="En tant que gnome, vous comprendrez peut-être l’inquiétude de Gozwin au sujet des schémas perdus de son mecha-walker."},sec={{t="Une embuscade près du feu",b="Vous campez pour la soirée avec Grund and Gozwin dans les collines enneigées. Tandis que Grund se tourne pour préparer un sanglier au-dessus du feu, un léopard des neiges bondit des fourrés et saisit Gozwin entre ses mâchoires. Grund s’empare de son fusil et tire au-dessus de la tête de la bête. Surpris, le léopard relâche Gozwin et s’enfuit dans les rochers glacés."},{t="Le travail perdu d’un bricoleur",b="Gozwin s’en sort avec de profondes égratignures, mais l’attaque sème le désordre dans le camp. Dans la cohue, il perd son précieux Journal de mécano de Gozwin, qui contient les schémas de son mecha-walker. Le gnome meurtri craint que quelqu’un ne découvre ses secrets d’ingénierie. Il ne peut trouver le repos avant que vous ayez fouillé les collines au nord-ouest du camp à la recherche du journal et du léopard rôdeur."}},faq={{q="Qui sont Grund and Gozwin ?",a="Grund est un nain, et Gozwin est son compagnon gnome et un ingénieur. Un léopard des neiges les attaque alors qu’ils campent dans les collines enneigées, blessant Gozwin et dispersant leurs affaires.",al={"qui sont grund et gozwin","grund gozwin"}},{q="Qu’est-ce qui a attaqué Gozwin au camp ?",a="Un léopard des neiges bondit des fourrés et saisit Gozwin entre ses mâchoires tandis que Grund prépare un sanglier au-dessus du feu. Grund tire au-dessus de sa tête, effrayant la bête qui s’enfuit.",al={"qu’est-ce qui a attaqué gozwin","qui a attaqué gozwin"}},{q="Pourquoi le Journal de mécano de Gozwin est-il si important pour lui ?",a="Le Journal de mécano de Gozwin contient les schémas techniques de son mecha-walker. Il craint que quelqu’un ne découvre ses secrets d’ingénierie si le journal est retrouvé.",al={"pourquoi le journal est-il important","journal de mécano de gozwin"}},{q="À quel point Gozwin a-t-il été blessé lors de l’attaque ?",a="Gozwin s’en sort avec de profondes égratignures après que Grund a tiré avec son fusil et effrayé le léopard. Le gnome meurtri s’inquiète pour son journal perdu.",al={"gozwin va-t-il bien","gozwin a-t-il survécu"}},{q="Où se trouve le camp de Grund and Gozwin ?",a="Leur camp se trouve dans les collines enneigées au nord-ouest. On vous demande d’y chercher le journal perdu et le léopard rôdeur.",al={"où se trouve le camp","emplacement du camp de grund"}},{q="Qu’est-il arrivé au repas que Grund préparait ?",a="Le léopard s’enfuit après que Grund a tiré avec son fusil. Le léopard des neiges a dévoré le sanglier que Grund préparait.",al={"qu’est-il arrivé au rôti de sanglier","léopard qui dévore un sanglier"}}},fp="16,180,21.316.0,22.332.0,25.181.0,29.176.0,51.147.0,40.146.0,41.123.0,46.110.0"}
P.entries["quest:97279"] = {n="Wayward Weapons",s="Dans la Vallée des épreuves, Gornek envoie les nouveaux arrivants récupérer des armes pour le campement. De jeunes guerriers continuent d’affluer pour servir la Horde, et Kzan Trancheronce a besoin de vieilles armes remises en état.",h="Dans la Vallée des épreuves, Gornek envoie les nouveaux arrivants récupérer des armes pour le campement.",kw={"durotar","gornek","kzan trancheronce","recrues","récupération","l'antre","armes d’entraînement","vallée des épreuves"},ang={["class:Warrior"]="En tant que guerrier, vous apprenez à respecter vos armes. Récupérer celles qu’ont laissées des recrues ayant échoué exige discipline et autonomie avant même le début du combat.",["faction:Horde"]="En tant que membre de la Horde, vous survivez à Durotar grâce à votre ténacité et à votre ingéniosité, en sauvant des armes même lorsque ceux qui sont incapables de les porter les abandonnent.",["profession:Blacksmithing"]="À Durotar, chaque morceau de métal compte. En tant que forgeron, vous récupérez l’équipement abîmé et retravaillez les lames émoussées pour en faire des armes de guerre."},sec={{t="Armer les nouvelles recrues",b="Les jeunes recrues affrontent de rudes épreuves dans les étendues rouges de Durotar. Nombre d’entre elles arrivent prêtes à vouer leur lame au chef de guerre, laissant le campement à court d’armes. Le fabricant d’armes Kzan Trancheronce peine à répondre à la demande. Pour les novices mal préparés, les premières leçons peuvent être fatales ou humiliantes."},{t="Une épreuve d’ingéniosité",b="Le surveillant Gornek transforme la pénurie en épreuve pratique. Il envoie les nouveaux arrivants récupérer les lames abandonnées et les armes d’entraînement émoussées laissées par les recrues tombées au combat ou en fuite. Kzan peut réparer et tremper les armes récupérées pour la prochaine vague. Les recrues apprennent que survivre au sein de la Horde demande aussi de récupérer du matériel, pas seulement de manier l’acier."}},faq={{q="Pourquoi tant d’armes d’entraînement abandonnées traînent-elles ici ?",a="Certaines recrues manquent de force ou de détermination pour répondre aux exigences de la Horde. Des nouveaux venus imprudents ou effrayés abandonnent leur équipement, tandis que d’autres succombent aux sangliers et aux scorpides des environs, éparpillant leurs armes dans la poussière.",al={"pourquoi des armes sont au sol","armes abandonnées à durotar","armes des recrues ayant échoué"}},{q="Qui est Kzan Trancheronce ?",a="Kzan Trancheronce est le fabricant d’armes qui se trouve dans l’Antre, dans la Vallée des épreuves. Il équipe les nouvelles recrues, répare leur matériel d’entraînement abîmé et entretient les réserves d’armes de la Horde dans la vallée de départ.",al={"histoire de kzan trancheronce","qui est kzan","fabricant d’armes kzan"}},{q="Qui confie cette tâche ?",a="Gornek, le surveillant posté devant l’Antre, envoie les nouvelles recrues donner un coup de main. Il observe les aspirants qui arrivent, évalue leurs aptitudes de base et leur confie des tâches immédiates autour du terrain d’épreuve.",al={"qui confie wayward weapons","quête de gornek"}},{q="Que fera Kzan de ces armes récupérées ?",a="Kzan répare, aiguise et remet en état les armes d’entraînement abîmées. Les ressources étant rares à Durotar et les recrues arrivant sans cesse, il réutilise le fer et le bois récupérés pour entraîner la prochaine vague.",al={"que deviennent les armes d’entraînement","réparation des armes par kzan"}},{q="Où se déroule cette quête ?",a="Vous vous trouvez dans la Vallée des épreuves, un canyon isolé du sud de Durotar où les jeunes orcs et les Trolls sombrelances commencent leur parcours de guerriers au service de la Horde.",al={"emplacement de la vallée des épreuves","où se trouve wayward weapons"}},{q="Pourquoi la Horde ne forge-t-elle pas simplement des armes entièrement neuves ?",a="Durotar est une région aride et accidentée, où les gisements de fer faciles d’accès sont rares, et la jeune Horde ne peut se permettre le gaspillage. Réutiliser les lames d’entraînement des recrues qui échouent permet d’économiser le métal brut pour les soldats du front.",al={"pourquoi récupérer les armes","pénurie de métal à durotar"}}},fx={c966be67={q="Pourquoi Gornek veut-il que les armes abandonnées soient récupérées ?",a="Un nouvel afflux de recrues dans la Vallée des épreuves a mis l'armurerie du camp à rude épreuve. L'armurier, Kzan Trancheronce, manque d'équipement d'entraînement, et Gornek doit maintenir l'approvisionnement pour entraîner la prochaine vague. Vous demander de fouiller les lieux résout la pénurie tout en permettant à Gornek de tester votre diligence et vos compétences de survie dans la vallée.",al={"mobile de gornek","pourquoi gornek veut-il des armes","pourquoi récupérer les armes d'entraînement abandonnées"}},["42aac14b"]={q="À quoi sert l'Arme d'entraînement abandonnée ?",a="Ces lames et gourdins rudimentaires étaient portés par d'anciennes recrues qui se sont révélées indignes ou qui ont péri avant de terminer leurs épreuves. Laissés éparpillés dans la terre, ils sont encore assez robustes pour être restaurés. Une fois que vous les apportez à Kzan Trancheronce, il les répare et les aiguise afin que les futures recrues aient du matériel pour se battre.",al={"utilisation de l'arme d'entraînement abandonnée","à quoi servent les armes abandonnées","but de l'arme d'entraînement abandonnée"}},["056af0db"]={q="Pourquoi Gornek envoie-t-il une recrue au lieu de gardes ?",a="Les terrains d'épreuve existent pour séparer les guerriers capables des faibles. Envoyer des gardes chevronnés nettoyer après les recrues qui ont échoué gaspille la main-d'oeuvre vétérane, tandis que vous envoyer sert un double objectif : vous faites vos armes en chassant les sangliers dans la nature tout en prouvant que vous pouvez suivre les ordres et assurer les besoins du camp.",al={"pourquoi ne pas envoyer de gardes","pourquoi moi gornek","pourquoi envoyer des recrues pour les armes"}}},fp="15,190,20.275.0,25.331.0,62.212.0,23.198.0,21.185.0,46.191.0,33.153.0,54.192.0"}
P.entries["quest:97281"] = {n="A Simmering Storm",s="À Durotar, l’Orbe orageux terne a attiré l’attention de Rezlak. Le bricoleur gobelin voit une raison d’étudier la relique, récupérée auprès des harpies Dustwind du Ravin asséché.",h="À Durotar, l’Orbe orageux terne a attiré l’attention de Rezlak.",kw={"a simmering storm","ravin asséché","orbe orageux terne","durotar","dustwind","gazlowe","harpie","rezlak"},ang={["class:Shaman"]="En tant que chaman, vous reconnaissez dans cette tempête électrique miniature le reflet des forces élémentaires primordiales. Son enveloppe rudimentaire soulève des questions sur les méthodes des harpies.",["faction:Horde"]="En tant qu’aventurier de la Horde, vous aidez Rezlak à mettre à l’abri de mystérieux artefacts magiques récupérés auprès de harpies hostiles qui menacent les canyons de Durotar.",["profession:Engineering"]="En tant qu’ingénieur, vous partagez l’intérêt de Rezlak pour les curiosités insolites, parcourues de charges électriques irrégulières et de brumes tourbillonnantes."},sec={{t="Une étincelle dans la poussière",b="Les voyageurs qui affrontent les harpies Dustwind du Ravin asséché peuvent trouver l’Orbe orageux terne parmi leurs étranges bibelots. Sa surface usée émet une vibration électrique constante. Une brume sombre s’agite à l’intérieur, parfois traversée d’étincelles vives. La relique montre que les harpies ont manipulé la magie des tempêtes."},{t="Curiosité gobeline",b="Rezlak attend à l’entrée du Ravin asséché, où l’orbe a attiré son attention. Sa découverte lui rappelle les conseils de son employeur, l’ingénieur en chef Gazlowe de Cabestan. On ignore ce que les harpies comptaient faire de cette tempête miniature. À présent, l’orbe est entre des mains gobelines."}},faq={{q="Qu’est-ce que l’Orbe orageux terne ?",a="L’Orbe orageux terne est une curiosité magique récupérée auprès d’une harpie à Durotar. Sa surface terne dissimule un léger bourdonnement électrique, une brume sombre tourbillonnante et des étincelles occasionnelles.",al={"qu’est-ce que l’orbe orageux terne","orbe orageux","orbe des harpies"}},{q="Qui veut l’Orbe orageux terne ?",a="Rezlak veut l’Orbe orageux terne. C’est un éclaireur gobelin posté juste à l’extérieur du Ravin asséché, à Durotar, qui s’intéresse aux curiosités insolites et aux objets de récupération.",al={"qui prend l’orbe orageux terne","rendre l’orbe orageux","où apporter l’orbe"}},{q="Pourquoi les harpies avaient-elles cet orbe ?",a="On ignore ce que les harpies comptaient faire de l’orbe. Les harpies Dustwind du Ravin asséché s’en servaient pour canaliser ou contenir des forces élémentaires électriques et orageuses.",al={"que faisaient les harpies avec l’orbe","pourquoi les harpies ont un orbe orageux","but de l’orbe des harpies"}},{q="Qui est Rezlak ?",a="Rezlak est un agent gobelin près du Ravin asséché, dans le nord de Durotar. Il est affilié au Cartel Gentepression et à l’ingénieur en chef Gazlowe de Cabestan.",al={"qui est rezlak","rezlak durotar","gobelin près du ravin asséché"}},{q="Où se trouve le Ravin asséché ?",a="Le Ravin asséché est un réseau de canyons escarpés dans le nord de Durotar. Des harpies Dustwind hostiles l’infestent, s’en prenant aux voyageurs et perturbant le commerce local et les colonies.",al={"où se trouve le ravin asséché","emplacement du ravin asséché","canyon des harpies à durotar"}},{q="Que pense Rezlak de l’orbe ?",a="L’orbe rappelle à Rezlak les leçons et les remarques de son patron, l’ingénieur en chef Gazlowe, sur les curiosités insolites qui pourraient s’avérer rentables.",al={"que dit rezlak sur gazlowe","lien entre rezlak et gazlowe"}}},fp="17,168,19.298.0,16.275.0,28.168.0,30.155.0,34.160.0,14.155.0,25.162.0,34.143.0"}
P.entries["quest:97282"] = {n="Stormy Potential",s="Près du Ravin asséché, Rezlak cherche un moyen de protéger sa caravane des harpies. Il espère recharger un orbe déchargé grâce aux organes électriques des lézards-tonnerre de Durotar.",h="Près du Ravin asséché, Rezlak cherche un moyen de protéger sa caravane des harpies.",kw={"organes chargés","ravin asséché","durotar","gazlowe","harpies","orbe","rezlak","stormy potential","lézard-tonnerre"},ang={["faction:Horde"]="Le travail de Rezlak contribue à maintenir la Horde et ses voyageurs en Durotar, où les harpies maraudeuses du Ravin asséché menacent les voyageurs et les caravanes de ravitaillement.",["profession:Engineering"]="L’utilisation des organes de lézards-tonnerre pour alimenter des appareils inertes témoigne de l’ingéniosité des gobelins, même si les marges de sécurité sont presque inexistantes."},sec={{t="Saisir l’occasion",b="Près du Ravin asséché, en Durotar, les harpies menacent la caravane de Rezlak et un orbe magique intact a perdu son pouvoir. Gazlowe, l’ingénieur en chef de Cabestan, lui a autrefois conseillé de saisir l’occasion quand elle se présente. Le gobelin compte maintenant recharger l’orbe inerte et régler les deux problèmes à la fois."},{t="Canaliser la tempête",b="Rezlak a besoin d’une puissante source d’électricité pour restaurer son orbe déchargé. Des lézards-tonnerre vivent dans la gorge à l’ouest du Ravin asséché, et leurs organes produisent et conduisent des éclairs mortels. Il vous demande de lui rapporter ces organes chargés. Rezlak espère canaliser leur courant instable dans l’orbe et défendre ses chariots de ravitaillement contre les embuscades des harpies."}},faq={{q="Qui donne la quête Stormy Potential ?",a="Rezlak, un marchand et bricoleur gobelin près du Ravin asséché, en Durotar, vous demande de l’aide. Gazlowe, l’ingénieur en chef de Cabestan, lui a appris à saisir les occasions, et Rezlak espère restaurer un orbe déchargé grâce à l’énergie des organes électriques des créatures locales.",al={"qui donne stormy potential","où se trouve rezlak","donneur de quête rezlak"}},{q="Que cherche à recharger Rezlak avec les organes ?",a="Rezlak espère recharger un orbe intact qui a perdu toute son énergie. Il compte utiliser les organes de lézards-tonnerre pour défendre sa caravane contre les harpies qui rôdent dans la région.",al={"que recharge rezlak","pourquoi avoir besoin d’organes de lézard-tonnerre","à quoi sert l’orbe de rezlak"}},{q="Où trouve-t-on les lézards-tonnerre ?",a="Les lézards-tonnerre vivent dans une gorge à l’ouest de Rezlak, près du Ravin asséché en Durotar. Vous pouvez lui rapporter leurs organes électriques.",al={"où trouver des lézards-tonnerre","emplacement des lézards-tonnerre en durotar","où trouver les organes"}},{q="Pourquoi est-il dangereux de récolter les organes des lézards-tonnerre ?",a="Les lézards-tonnerre sont dangereux parce qu’ils projettent des éclairs. Leurs décharges électriques peuvent donner aux voyageurs une leçon douloureuse qu’ils ne recevront peut-être qu’une fois.",al={"pourquoi les lézards-tonnerre lancent des éclairs","les lézards-tonnerre utilisent-ils des éclairs"}},{q="Pourquoi Rezlak craint-il les harpies ?",a="Des harpies du Ravin asséché ont tendu une embuscade à la caravane de Rezlak. Il espère que l’orbe chargé les dissuadera ou lui servira d’arme contre de nouvelles attaques visant ses cargaisons.",al={"pourquoi rezlak a-t-il besoin de se défendre","qui a attaqué rezlak","attaque de harpies contre une caravane"}},{q="Quel lien Rezlak a-t-il avec Gazlowe ?",a="Rezlak considère Gazlowe, l’ingénieur en chef de Cabestan, comme un mentor et un modèle en affaires. Le conseil de Gazlowe, qui lui a dit de saisir l’occasion, guide le plan de Rezlak pour l’orbe.",al={"qui est gazlowe pour rezlak","conseil de gazlowe à rezlak"}}},fp="16,171,19.284.0,20.331.0,37.253.0,48.158.0,36.141.0,45.155.0,33.159.0,39.160.0"}
P.entries["quest:97284"] = {n="Vahlarriel's Vengeance",s="Vahlarriel vous demande de frapper les orcs de la Lame ardente à la Forteresse de Hache-Tonnerre. Il craint qu'ils soient prêts à se battre et veut leur faire payer la menace qu'ils font peser sur Malem.",h="Vahlarriel vous demande de frapper les orcs de la Lame ardente à la Forteresse de Hache-Tonnerre.",kw={"lame ardente","caravane","désolace","malem","combe de nijel","forteresse de hache-tonnerre","vahlarriel","vahlarriel demonslayer"},sec={{t="Un compte à régler",b="À la Combe de Nijel, Vahlarriel Demonslayer s'attend à ce que les orcs de la Lame ardente soient prêts à vous affronter. Il préférerait que vous les évitiez, mais il pense qu'ils chercheront la bagarre. Il vous demande donc d'en tuer autant que possible à la Forteresse de Hache-Tonnerre, puis de revenir le voir."},{t="Après l'attaque",b="À votre retour, Vahlarriel pense que votre attaque pourrait faire réfléchir la Lame ardente avant qu'elle ne pille une autre caravane. Il espère que les orcs resteront assez longtemps derrière leurs portes pour disparaître d'eux-mêmes."}},faq={{q="Qui me demande d'attaquer la Lame ardente ?",a="Vahlarriel Demonslayer, à la Combe de Nijel, vous demande d'attaquer la Lame ardente à la Forteresse de Hache-Tonnerre.",al={"qui est vahlarriel","vengeance de vahlarriel","qui veut la mort des orcs"}},{q="Pourquoi Vahlarriel veut-il que la Lame ardente soit attaquée ?",a="Vahlarriel pense que les orcs sont prêts à se battre au sujet de Malem et veut leur faire payer leur menace.",al={"pourquoi tuer la lame ardente","pourquoi vahlarriel est-il en colère","raison de la lame ardente"}},{q="Où se trouvent les orcs de la Lame ardente ?",a="Les orcs de la Lame ardente se trouvent à la Forteresse de Hache-Tonnerre, en Désolace.",al={"où se trouve hache-tonnerre","emplacement de la lame ardente","forteresse orque"}},{q="Que craint Vahlarriel de la part des orcs ?",a="Vahlarriel pense que les orcs s'attendent à ce que quelqu'un cherche Malem et qu'ils seront prêts à se battre.",al={"danger pour malem","les orcs vont-ils se battre","menace de la lame ardente"}},{q="Qu'espère accomplir Vahlarriel avec cette attaque ?",a="Vahlarriel espère que la Lame ardente réfléchira à deux fois avant de piller une autre caravane de passage.",al={"pourquoi attaquer hache-tonnerre","mettre fin aux raids contre les caravanes","que veut vahlarriel"}}},fp="22,162,17.258.0,16.202.0,45.101.0,52.98.0,33.63.0,43.94.0,53.94.0"}
P.entries["quest:97286"] = {n="Research Access",s="Vos actes vous ont valu une place à la Library. Ses portes vous sont ouvertes pour vos études.",h="Vos actes vous ont valu une place à la Library.",kw={"accès","savoir","library","research access","respect","étude"},sec={{t="Accès à la Library",b="Vous avez obtenu l’accès à la Library pour vos études. Ses portes vous sont ouvertes."}},faq={{q="Pourquoi puis-je entrer dans la Library ?",a="Vos actes ont témoigné de votre respect du savoir, alors la Library vous est ouverte pour vos études.",al={"accès à la bibliothèque","pourquoi la bibliothèque est ouverte","étudier à la bibliothèque"}},{q="Que m’offre la Library ?",a="La Library vous est ouverte pour vos études.",al={"à quoi sert la bibliothèque","accès aux études","que puis-je faire"}},{q="Qu’ont montré mes actes ?",a="Vos actes ont témoigné de votre respect du savoir.",al={"respect du savoir","pourquoi suis-je accepté","qu’ai-je prouvé"}}},fp="15,87,14.82.0,28.83.0,31.35.0,25.42.0"}
P.entries["quest:97287"] = {n="Shrewd Negotiations",s="Après votre infiltration de la cité des mages, Magus Wordeen Voidglare vous envoie à Dalaran. Apportez le Granule arcanique à l’Archmage Celindra. Wordeen pense que le Kirin Tor donnera n’importe quoi pour le récupérer.",h="Après votre infiltration de la cité des mages, Magus Wordeen Voidglare vous envoie à Dalaran.",kw={"montagnes d’alterac","granule arcanique","archmage celindra","dalaran","kirin tor","shrewd negotiations","wordeen voidglare"},sec={{t="Le temps de négocier",b="Magus Wordeen Voidglare affirme qu’aucun ordre sur Azeroth n’égale le Kirin Tor en savoir arcanique. Même ses travaux brillants pâlissent face à leur sagesse ancestrale. Il pense que la Horde devrait accéder à leur ordre exclusif. Il vous envoie donc auprès de l’Archmage Celindra, à Dalaran, avec le Granule arcanique que vous avez obtenu. Wordeen pense que le Kirin Tor donnera n’importe quoi pour le récupérer."}},faq={{q="Qui vous envoie négocier avec Dalaran ?",a="Magus Wordeen Voidglare vous envoie à Dalaran après votre infiltration de la cité.",al={"qui donne shrewd negotiations","wordeen voidglare","donneur de quête shrewd negotiations"}},{q="À qui devez-vous parler ?",a="Vous devez parler à l’Archmage Celindra, à Dalaran.",al={"à qui parler","emplacement de celindra","où est celindra"}},{q="Quel moyen de pression avez-vous ?",a="Vous avez le Granule arcanique que vous avez obtenu. Wordeen pense que le Kirin Tor donnera n’importe quoi pour le récupérer.",al={"qu’est-ce que le granule","monnaie d’échange","granule arcanique"}},{q="Pourquoi Wordeen Voidglare veut-il traiter avec Dalaran ?",a="Wordeen affirme qu’aucun lieu sur Azeroth ne rivalise avec le Kirin Tor en savoir arcanique. Il pense que la Horde devrait accéder à leur ordre exclusif.",al={"pourquoi négocier avec le kirin tor","motivation de wordeen","pourquoi dalaran"}}},fp="19,198,17.359.0,40.81.0,31.56.0,27.104.0,53.141.0"}
P.entries["quest:97288"] = {n="Unending Torment",s="La tête d’une abomination vaincue met Unending Torment en mouvement. Ses sutures répétées révèlent de sombres expériences délibérées dans la capitale des Réprouvés. Vous l’apportez au Maître apothicaire Faranell, à Fossoyeuse.",h="La tête d’une abomination vaincue met Unending Torment en mouvement.",kw={"tête abominable","abomination","l'apothicarium","dame noire","maître apothicaire faranell","société royale des apothicaires","sylvanas coursevent","fossoyeuse","unending torment"},ang={["faction:Horde"]="Les aventuriers de la Horde qui voient la tête découvrent les pratiques réprouvées de réanimation répétée et de sculpture de chair. Ces méthodes fonctionnent, mais elles peuvent troubler ceux qui sont plus attachés à l’honneur.",["race:Undead"]="Pour les Réprouvés, la tête montre comment les réparations répétées affaiblissent un assemblage de morts-vivants. Elle rappelle sinistrement l’autorité absolue de leur reine et l’ingéniosité macabre de la Société royale des apothicaires."},sec={{t="Une couture lâche",b="Quand l’imposante abomination tombe au combat, sa tête bascule de ses épaules. Son cou a été tranché, recousu, arraché et rattaché à de nombreuses reprises. Chaque réparation a fragilisé davantage la couture, jusqu’à ce que la tête ne tienne presque plus à ses épaules.\n\nUn rapiéçage aussi persistant est inhabituel, même pour des assemblages de morts-vivants. Les destructions et les reconstructions répétées suggèrent que cette abomination a été rebâtie encore et encore. De simples charognards ne sauraient expliquer un tel travail. Seuls les sculpteurs de chair chevronnés de Fossoyeuse pourraient identifier les origines de la créature."},{t="La plaisanterie de la Dame noire",b="À l’Apothicarium, le Maître apothicaire Faranell, dirigeant de la Société royale des apothicaires, reconnaît aussitôt la tête tranchée. Il voit dans ses reconstructions répétées une plaisanterie cruelle et délibérée conçue par Dame Sylvanas Coursevent, et non un accident de nécromancie.\n\nSeuls la Dame noire et son cercle intime savent quelle offense a valu à la créature ce châtiment dégradant. Faranell accepte avec joie la tête abîmée, convaincu que la Société royale des apothicaires saura l’utiliser dans ses travaux alchimiques et nécromantiques en cours."}},faq={{q="Qu’est-ce que la Tête abominable ?",a="La Tête abominable est la tête tranchée d’un assemblage unique, détachée lorsque la créature est vaincue. Son cou porte les marques de rattachements répétés, et chaque réparation a fragilisé la chair et les sutures. Vous l’apportez au Maître apothicaire Faranell, à Fossoyeuse, pour qu’il l’examine.",al={"histoire de la tête abominable","qu’est-ce que la tête abominable","objet de quête tête d’abomination"}},{q="Pourquoi la tête a-t-elle été rattachée autant de fois ?",a="Après chaque chute ou perte, la tête était recousue pour que l’assemblage puisse être reconstitué et continuer à servir ou à souffrir. Son cou, de plus en plus fragile, finissait par céder à nouveau.",al={"pourquoi rattacher la tête","pourquoi la tête a-t-elle été recousue","sutures de unending torment"}},{q="Qui est le Maître apothicaire Faranell ?",a="Le Maître apothicaire Faranell dirige la Société royale des apothicaires à l’Apothicarium de Fossoyeuse. Sous l’autorité de la reine Sylvanas Coursevent, il supervise les apothicaires réprouvés qui étudient les poisons, les pestes et les modifications anatomiques. Sa connaissance des projets de la Dame noire lui permet d’identifier aussitôt les origines de la tête cousue.",al={"qui est faranell","histoire du maître apothicaire faranell","faranell à fossoyeuse"}},{q="Pourquoi Sylvanas considère-t-elle cela comme une plaisanterie cruelle ?",a="La cruauté réside dans le cycle sans fin. Chaque fois que la créature tombe, on la recoud à la hâte pour qu’elle serve ou souffre encore, et chaque réparation l’affaiblit. Voilà comment la Dame noire punit ses ennemis. Faranell ne dit pas qui était la créature autrefois ni ce qu’elle a fait pour mériter cela.",al={"plaisanterie de sylvanas","pourquoi la plaisanterie de la dame noire","plaisanterie cruelle de la dame noire"}},{q="Que fera Faranell de la tête ?",a="Faranell réutilise régulièrement des restes nécromantiques, de la chair et des curiosités biologiques pour élaborer des concoctions, des pestes et des renforts pour les assemblages engagés dans les conflits des Réprouvés. Il accepte la tête pour les travaux alchimiques et nécromantiques de la Société.",al={"que devient la tête","utilisation de la tête par faranell","que feront les apothicaires de la tête"}},{q="Où rendre la quête Unending Torment ?",a="Apportez la Tête abominable au Maître apothicaire Faranell, à l’Apothicarium, dans le quartier sud de Fossoyeuse. Il est entouré de cuves bouillonnantes, d’assistants et de sujets d’expérience, tandis qu’il supervise les recherches de la Société.",al={"où rendre unending torment","rendre unending torment","qui prend la tête abominable"}},{q="Les joueurs de l’Alliance peuvent-ils rendre cette quête ?",a="La livraison vous mène auprès du Maître apothicaire Faranell, à l’Apothicarium de Fossoyeuse. Cette quête est donc destinée aux aventuriers de la Horde. Les aventuriers de l’Alliance qui s’approcheraient de lui affronteraient les gardes hostiles de Fossoyeuse et risqueraient de mourir aux mains des Réprouvés en entrant dans leur bastion.",al={"unending torment est-elle réservée à la horde","alliance et unending torment","l’alliance peut-elle faire unending torment"}}},fp="16,224,14.544.0,20.519.1,28.279.0,47.183.0,34.337.0,45.303.0,36.253.0,48.218.0,40.281.0"}
P.entries["quest:97289"] = {n="Unending Torment",s="À Fossoyeuse, les Réprouvés s'apprêtent à interroger un commandant de l'Alliance tombé au combat. Ils veulent donner un nouveau corps à Grand Marshal Othmar Garithos et découvrir ce qu'il a emporté dans sa tombe.",h="À Fossoyeuse, les Réprouvés s'apprêtent à interroger un commandant de l'Alliance tombé au combat.",kw={"abomination","réprouvés","garithos","grand marshal","tête du baron","othmar","sylvanas","fossoyeuse","unending torment"},ang={["faction:Alliance"]="Dans l'Alliance, vous assistez au sort atroce de Grand Marshal Garithos, un chef de l'Alliance qui s'est opposé à la reine banshee à Lordaeron.",["faction:Horde"]="Dans la Horde, vous voyez la Société royale des apothicaires mener des expériences de réanimation à Fossoyeuse. Ces travaux révèlent l'art sombre des Réprouvés et leur vengeance contre leurs anciens oppresseurs.",["race:Undead"]="Chez les Réprouvés, vous voyez les restes de Grand Marshal Garithos utilisés dans des expériences qui rappellent la conquête de Lordaeron par Dame Sylvanas."},sec={{t="Un trophée de conquête",b="Au plus profond de Fossoyeuse, des praticiens réprouvés cousent des abominations à partir de morceaux récupérés sur les morts. Parmi les crânes préservés, l'un porte une histoire amère : la tête tranchée de Grand Marshal Othmar Garithos. Il a mené les forces survivantes de l'Alliance à travers Lordaeron, jusqu'à ce que la Dame noire le tue."},{t="Les secrets de la tombe",b="Les Réprouvés comptent interroger Garithos, pas garder sa tête comme trophée. Leurs nécromanciens préparent un corps d'abomination assemblé de bric et de broc pour lui servir de nouvel hôte, dans l'espoir de découvrir les secrets de l'Alliance enfermés dans son crâne. Quand ils approchent la tête du pantin sans vie, l'abomination s'éveille dans l'agonie et revit ses derniers instants atroces."}},faq={{q="Qui était Othmar ?",a="Othmar était Grand Marshal Othmar Garithos, un commandant tristement célèbre qui a mené les forces restantes de l'Alliance à Lordaeron après la troisième guerre. Les non-humains le méprisaient. Maître apothicaire Faranell affirme que la Dame noire a eu le plaisir de l'éliminer elle-même.",al={"qui est othmar","identité d'othmar","qui était othmar"}},{q="Pourquoi les Réprouvés réaniment-ils les restes d'Othmar ?",a="Les Réprouvés espèrent arracher à Garithos les secrets qu'il a emportés dans sa tombe. Ils placent sa tête préservée près d'un corps d'abomination préparé afin d'obtenir des informations de ses restes réanimés.",al={"pourquoi réanimer othmar","but de la réanimation de la tête","quels secrets othmar"}},{q="Comment Othmar est-il mort ?",a="Maître apothicaire Faranell affirme que Dame Sylvanas Coursevent, la Dame noire, a eu le plaisir de tuer Grand Marshal Garithos elle-même.",al={"qui a tué othmar","comment othmar est-il mort","mort d'othmar"}},{q="Pourquoi l'objet de quête s'appelle-t-il Tête du Baron ?",a="Le Baron est le nom de l'imposante abomination des Ruines de Lordaeron. Faranell révèle que sa tête appartenait autrefois à Grand Marshal Garithos.",al={"tête du baron othmar","pourquoi tête du baron"}},{q="Où se trouve le nouveau corps d'Othmar ?",a="L'abomination sans tête destinée à recevoir la tête d'Othmar se trouve dans une chambre adjacente de Fossoyeuse. Des praticiens réprouvés attendent de la réanimer.",al={"où se trouve le corps d'othmar","emplacement de l'abomination à fossoyeuse"}},{q="Que se passe-t-il quand le pantin s'éveille ?",a="Quand on place la tête près du pantin assemblé, sa chair cousue tressaute violemment et prend vie. Les restes paniquent en revivant la terreur des derniers instants de Garithos.",al={"que se passe-t-il quand le corps s'éveille","réaction à la réanimation d'othmar"}}},fp="16,179,20.297.0,20.320.1,15.239.0,50.182.0,19.132.0,51.144.0,35.155.0,40.179.0"}
P.entries["quest:97290"] = {n="Unending Torment",s="À Fossoyeuse, un sujet rebelle rejette les exigences de la Société royale des apothicaires. Maître apothicaire Faranell se réjouit de la nouvelle, impatient de briser un captif difficile.",h="À Fossoyeuse, un sujet rebelle rejette les exigences de la Société royale des apothicaires.",kw={"abomination","l'apothicarium","faranell","réprouvés","maître apothicaire faranell","société royale des apothicaires","fossoyeuse","unending torment"},ang={["faction:Horde"]="En tant que champion de la Horde à Lordaeron, vous découvrez la cruauté de vos alliés réprouvés. Le plaisir de Faranell à briser les captifs obstinés révèle le pragmatisme sinistre de Fossoyeuse.",["race:Undead"]="En tant que Réprouvé, vous savez que les vivants peuvent vous traiter d’abomination. Aider Maître apothicaire Faranell soutient les sombres activités de la Société royale des apothicaires."},sec={{t="Défiance dans l’ombre",b="Un sujet placé sous la surveillance de la Société royale des apothicaires vous méprise. Le captif vous traite d’abomination et refuse d’aider. Cette haine est familière aux Réprouvés, car nombre d’êtres vivants et de captifs sont horrifiés par les morts-vivants de Lordaeron."},{t="L’ambition de Faranell",b="Vous rapportez le refus du sujet à Maître apothicaire Faranell, à Fossoyeuse. Le chef de la Société royale des apothicaires accueille la nouvelle avec un plaisir malveillant. À ses yeux, cette résistance fait du sujet un défi digne des cruelles expériences de l’Apothicarium."}},faq={{q="Qu’est-ce qu’Unending Torment ?",a="Unending Torment vous envoie affronter un sujet rebelle lié à la Société royale des apothicaires. Le prisonnier ou l’être hostile vous traite d’abomination et refuse d’aider, alors vous rapportez cet échec à Maître apothicaire Faranell, à Fossoyeuse.",al={"quête unending torment","qu’est-ce qu’unending torment","histoire d’unending torment"}},{q="Qui donne la quête Unending Torment ?",a="Un sujet rebelle rejette votre approche et vous traite d’abomination. Le captif reste anonyme au cours de cet échange et vous renvoie auprès des dirigeants de la Société royale des apothicaires avec vos conclusions.",al={"qui donne unending torment","donneur de quête unending torment","où obtenir unending torment"}},{q="Qui est Maître apothicaire Faranell ?",a="Maître apothicaire Faranell dirige la Société royale des apothicaires dans l’Apothicarium, sous les ruines de Lordaeron, à Fossoyeuse. Il supervise les alchimistes et chercheurs réprouvés qui élaborent des fléaux, des concoctions et des poisons pour défendre les Réprouvés et détruire leurs ennemis à travers Azeroth.",al={"qui est faranell","maître apothicaire faranell","rôle de l’apothicaire faranell"}},{q="Pourquoi le locuteur traite-t-il le joueur d’abomination ?",a="Le captif vous traite d’abomination par dégoût des morts-vivants et de leurs agents. Nombre d’êtres vivants et d’ennemis des Réprouvés partagent cette horreur des morts animés de Fossoyeuse.",al={"pourquoi abomination","qui vous traite d’abomination","pourquoi le prisonnier est-il en colère"}},{q="Où devez-vous faire votre rapport après avoir terminé la tâche ?",a="Rapportez directement le refus du sujet à Maître apothicaire Faranell, à Fossoyeuse. Au cœur de l’Apothicarium, d’autres chercheurs l’entourent tandis qu’ils préparent des concoctions mortelles pour Dame Sylvanas Coursevent et les Réprouvés.",al={"où rendre unending torment","rendre unending torment","à qui rapporter unending torment"}},{q="Comment Maître apothicaire Faranell réagit-il à la défiance du sujet ?",a="Maître apothicaire Faranell se réjouit de l’obstination du sujet. Il accueille cette impasse comme un défi divertissant et se délecte de mettre à l’épreuve les sujets difficiles avec les méthodes impitoyables de la Société royale des apothicaires.",al={"réaction de faranell","que dit faranell","faranell se met-il en colère"}}},fp="16,165,23.236.0,19.258.0,25.241.0,37.198.0,34.290.0,52.188.0,48.222.0,68.219.0"}
P.entries["quest:97291"] = {n="Unending Torment",s="À Fossoyeuse, le Maître apothicaire Faranell prépare un breuvage pour soumettre un captif à la Dame noire. Il lui faut des réactifs mortels provenant de toute la capitale des Réprouvés pour l'achever.",h="À Fossoyeuse, le Maître apothicaire Faranell prépare un breuvage pour soumettre un captif à la Dame noire.",kw={"l'apothicarium","blisterweed","essence d'agonie","faranell","maître apothicaire faranell","tawny grisette","toxic skullcap","fossoyeuse","unending torment"},ang={["class:Rogue"]="La tâche vous mène au Rogues' Quarter pour acheter de l'Essence d'agonie, un puissant réactif prisé des fabricants de poisons et des assassins.",["faction:Horde"]="La Société royale des apothicaires continue de préparer de sinistres concoctions sous les ruines de Lordaeron et de tester les limites de la soumission alchimique.",["profession:Herbalism"]="Récolter de la Blisterweed auprès des maîtres herboristes de l'Apothicarium montre comment l'étude botanique ordinaire côtoie les sombres travaux alchimiques de la Société.",["race:Undead"]="Pour les Réprouvés, tourmenter par l'alchimie des restes réanimés afin de les soumettre au service de la Dame noire fait partie du quotidien à l'Apothicarium."},sec={{t="Soumettre la volonté",b="Au plus profond de l'Apothicarium de Fossoyeuse, le Maître apothicaire Faranell mène des expériences pour renforcer les Réprouvés. Il a rattaché la tête tranchée d'un captif malmené. Il lui faut maintenant un mélange alchimique spécial pour briser les dernières résistances de la créature et soumettre sa volonté à Dame Sylvanas Coursevent."},{t="Réactifs d'apothicaire",b="Faranell envoie son agent à travers Fossoyeuse pour rassembler de puissants ingrédients pour son breuvage. Tawny Grisette, dans le Trade Quarter, fournit un Toxic Skullcap. Des maîtres herboristes tout proches détiennent de la Blisterweed et lui doivent une faveur, tandis qu'un vendeur de poison du Rogues' Quarter vend de l'Essence d'agonie."},{t="Le chef-d'œuvre",b="Les ingrédients en main, Faranell éprouve une sombre satisfaction devant le chef-d'œuvre qu'il s'apprête à créer. Il a hâte de tester sa concoction sur leur « invité d'honneur ». Il compte sur ce breuvage atroce pour ôter au captif ses derniers restes de bravoure et renvoyer docilement la créature égarée au service de la Dame noire."}},faq={{q="Qui propose la quête Unending Torment ?",a="C'est le Maître apothicaire Faranell qui la propose. Il dirige la Société royale des apothicaires et se trouve dans l'Apothicarium, à Fossoyeuse.",al={"qui donne unending torment","donneur de quête unending torment","début d'unending torment"}},{q="Quels réactifs faut-il pour la concoction de Faranell ?",a="Faranell a besoin de trois ingrédients : un Toxic Skullcap auprès de Tawny Grisette, dans le Trade Quarter, de la Blisterweed près des maîtres herboristes de l'Apothicarium et de l'Essence d'agonie auprès d'un vendeur de poison du Rogues' Quarter.",al={"quels sont les ingrédients","objets d'unending torment","réactifs nécessaires à faranell"}},{q="Sur qui le Maître apothicaire Faranell fait-il ses expériences ?",a="Faranell fait ses expériences sur un captif récalcitrant dont la tête tranchée vient d'être rattachée. Il le surnomme avec ironie « brebis égarée » et « invité d'honneur », et cherche à briser la bravoure insolente à laquelle il s'accroche après avoir été sévèrement battu.",al={"qui est la bête","qui est la brebis égarée mentionnée par faranell","qui est torturé"}},{q="Quel est le but de la potion de Faranell ?",a="La potion de Faranell doit briser mentalement le sujet et le soumettre à la volonté de Dame Sylvanas Coursevent. Elle est la Dame noire des Réprouvés.",al={"pourquoi préparer cette potion","but de la potion unending torment","que fait la concoction"}},{q="Où trouver Tawny Grisette ?",a="Tawny Grisette se trouve dans le Trade Quarter de Fossoyeuse, où elle vend des marchandises spécialisées, dont le Toxic Skullcap dont les apothicaires ont besoin.",al={"où se trouve tawny grisette","vendeur de toxic skullcap","trouver miss grisette"}},{q="Où se trouve la Blisterweed ?",a="La Blisterweed pousse près des maîtres herboristes Alliestars, dans l'Apothicarium de Fossoyeuse. Faranell dit qu'ils lui doivent une faveur, les aventuriers peuvent donc prendre ce qu'il leur faut.",al={"où trouver la blisterweed","herboristerie des alliestars","maître herboriste blisterweed à fossoyeuse"}}},fp="16,175,16.305.0,19.289.0,15.316.1,38.134.0,51.224.0,51.231.0,38.142.0,38.138.0,33.171.0"}
P.entries["quest:97292"] = {n="Unending Torment",s="Maître apothicaire Faranell met en œuvre un châtiment sous Fossoyeuse. À L'Apothicarium, la Société royale des apothicaires utilise Hissing Serum sur les restes d’Othmar, pour le punir durablement de ses crimes contre la Dame noire.",h="Maître apothicaire Faranell met en œuvre un châtiment sous Fossoyeuse.",kw={"l'apothicarium","dame noire","garithos","hissing serum","maître apothicaire faranell","othmar","fossoyeuse","unending torment"},ang={["faction:Horde"]="En aidant Faranell à Fossoyeuse, vous prenez part aux méthodes impitoyables que les Réprouvés emploient contre ceux qui les ont défiés, eux et la reine banshee.",["race:Undead"]="Maître apothicaire Faranell dirige la Société royale des apothicaires à Fossoyeuse. Pour les Réprouvés, punir les ennemis de la Dame noire comme Garithos est au cœur de leur vengeance."},sec={{t="Châtiment des apothicaires",b="Dans L'Apothicarium de Fossoyeuse, Maître apothicaire Faranell mène de rudes expériences sur les ennemis des Réprouvés. Il a préparé Hissing Serum, une substance caustique destinée à s’égoutter sans fin sur un captif sous un appareil alchimique."},{t="Le sort de Garithos",b="Grand Marshal Garithos repose sous l’appareil de Faranell, sous le nom d’Othmar, ses restes maintenus dans une structure suspendue. Faranell estime que le tourment chimique convient aux crimes commis contre la Dame noire. Le sérum coule sur le corps d’Othmar et fait mijoter sa chair, en guise de châtiment et pour l’étudier."}},faq={{q="Qui est Othmar ?",a="Othmar est Grand Marshal Othmar Garithos, l’ancien commandant humain qui a conclu une alliance précaire avec Sylvanas Coursevent lors de la reconquête de Lordaeron. Les Réprouvés l’ont trahi et tué. Maître apothicaire Faranell détient désormais ses restes pour poursuivre son supplice et ses expériences.",al={"qui est othmar","que sait-on d’othmar","othmar garithos"}},{q="Pourquoi Othmar est-il torturé ?",a="Othmar Garithos a aidé Sylvanas Coursevent à reprendre Capital City aux seigneurs de l’effroi. Pourtant, il méprisait les non-humains et voulait revendiquer tout Lordaeron au nom de l’humanité. Les Réprouvés le jugent coupable de crimes contre la Dame noire et estiment que son arrogance et ses actes méritent un tourment chimique.",al={"pourquoi torturer othmar","qu’a fait othmar","crimes contre sylvanas"}},{q="Qui est Maître apothicaire Faranell ?",a="Maître apothicaire Faranell dirige la Société royale des apothicaires dans L'Apothicarium de Fossoyeuse. Il supervise la création de sérums, de toxines et de peste, et dirige l’opération contre Othmar.",al={"rôle de faranell","qui inflige un tourment sans fin","apothicaire faranell"}},{q="Quel est l’effet de Hissing Serum ?",a="Hissing Serum est une préparation alchimique de Maître apothicaire Faranell. En s’écoulant d’un appareil au-dessus du corps suspendu d’Othmar, il fait mijoter la chair et provoque une douleur atroce.",al={"qu’est-ce que hissing serum","effets du sérum","sérum de faranell"}},{q="Othmar est-il vivant ou mort-vivant ?",a="Othmar est mort-vivant. La Dame noire a tué Garithos elle-même, et sa tête a été greffée sur le corps d’une abomination qui tressaille et s’anime. Faranell le qualifie de « nouvel invité » et compte le laisser souffrir sous le sérum qui s’égoutte.",al={"othmar mort ou vivant","garithos est-il vivant","état d’othmar"}},{q="Que compte faire Faranell d’Othmar ensuite ?",a="Maître apothicaire Faranell compte continuer à faire mijoter la chair d’Othmar sous l’appareil goutte-à-goutte et à le surveiller de près. Il dit avoir de grands projets pour l’avenir d’Othmar, entre nouvelles expériences et châtiments.",al={"projets de faranell pour l’avenir","que va-t-il arriver à othmar","avenir d’othmar"}}},fp="16,237,22.247.0,20.274.1,14.280.0,30.290.0,34.193.0,31.175.0,26.236.0,47.226.0"}
P.entries["quest:973"] = {n="La Tour d'Althalaxx",s="À la Tour d'Althalaxx, de sombres sectateurs mènent Delgren le Purificateur jusqu'à Ilkrud Magthrull. Il vous envoie vers le sud, à travers Sombrivage et jusqu'en Orneval, pour tuer le démoniste orc au Sanctuaire de Scarfeu et récupérer son tome.",h="À la Tour d'Althalaxx, de sombres sectateurs mènent Delgren le Purificateur jusqu'à Ilkrud Magthrull.",kw={"althalaxx","orneval","delgren","sanctuaire de scarfeu","ilkrud","maestra","magthrull","tome","démoniste"},ang={["class:Paladin"]="En tant que paladin, vous vous joignez à Delgren le Purificateur pour combattre les invocateurs gangrenés et récupérer leurs tomes corrompus. Vous répondez à l'appel de la Holy Light contre la corruption démoniaque.",["class:Warlock"]="En tant que démoniste, vous affrontez Ilkrud Magthrull, un adepte des arts sombres comme vous. Il protège ses textes impies à l'aide de succubes invoquées et de voidwalkers.",["faction:Alliance"]="En tant qu'aventurier de l'Alliance, vous voyagez de Sombrivage jusqu'aux terres d'Orneval souillées par les démons pour faire face à une menace grandissante.",["race:NightElf"]="En tant qu'elfe de la nuit, vous défendez les anciennes forêts d'Orneval contre la souillure du Sanctuaire de Scarfeu en abattant Ilkrud."},sec={{t="Une chasse en Orneval",b="Delgren le Purificateur remonte la piste des sombres sectateurs de la Tour d'Althalaxx jusqu'à Ilkrud Magthrull, un démoniste orc. Ilkrud opère depuis le Sanctuaire de Scarfeu, dans le sud-ouest d'Orneval. Delgren craint que sa magie ne se répande dans les forêts elfiques. Il vous envoie donc tuer le démoniste et prendre son tome. Il espère que son contenu révélera les desseins de son maître."},{t="Le repaire du démoniste",b="Au Sanctuaire de Scarfeu, Ilkrud est entouré d'une succube invoquée et de faucheurs gangrenés gardiens. Des piliers rouges marquent la montée rocheuse vers le sanctuaire. Une fois Ilkrud mort, Delgren pourra étudier son tome. Ses connaissances et ses ordres sont liés aux rituels d'Althalaxx."}},faq={{q="Qui est Delgren le Purificateur ?",a="Delgren le Purificateur est un champion de l'Alliance au Poste de Maestra, un avant-poste elfe de la nuit à la frontière entre Sombrivage et Orneval. Il dirige la lutte contre la corruption démoniaque et les sectateurs de la région.",al={"delgren","histoire de delgren","qui donne la quête"}},{q="Qui est Ilkrud Magthrull ?",a="Ilkrud Magthrull est un démoniste orc qui a établi son repaire au Sanctuaire de Scarfeu, dans le sud-ouest d'Orneval. Delgren le croyait d'abord insignifiant, mais ses liens avec les rites sombres de la Tour d'Althalaxx en font une cible cruciale.",al={"ilkrud","qui est ilkrud magthrull","démoniste orc orneval"}},{q="Où se trouve le Sanctuaire de Scarfeu ?",a="Le Sanctuaire de Scarfeu se trouve dans le sud-ouest d'Orneval, au sud du sanctuaire d'Aessina et à l'ouest d'Astranaar. Des démons infestent cette enclave corrompue, et deux piliers rouges encadrent le chemin menant à l'autel d'Ilkrud.",al={"emplacement du sanctuaire de scarfeu","où se trouve ilkrud","comment rejoindre ilkrud"}},{q="Pourquoi Delgren a-t-il besoin du tome d'Ilkrud Magthrull ?",a="Le tome d'Ilkrud contient ses rituels sombres et ses communications. Delgren espère les déchiffrer et découvrir le complot qui lie le démoniste aux sectateurs autour de la Tour d'Althalaxx.",al={"pourquoi le tome","que contient le tome d'ilkrud","but du tome"}},{q="Quel lien cette quête établit-elle entre Sombrivage et Orneval ?",a="L'enquête commence à la Tour d'Althalaxx, sur la côte nord de Sombrivage. À mesure que le mystère s'épaissit, le réseau des sectateurs mène vers le sud, à travers Sombrivage et jusqu'aux forêts disputées d'Orneval.",al={"quête de sombrivage à orneval","lien avec la série d'althalaxx"}},{q="Que se passe-t-il après la récupération du tome ?",a="Delgren étudie le tome pour découvrir les complots derrière les sectateurs de la Tour d'Althalaxx. Ses découvertes mènent aux affrontements finaux de la série de quêtes.",al={"quête suivante","que faire après althalaxx 5"}}},fx={b25de95c={q="Pourquoi Delgren le Purificateur veut-il que cela soit fait ?",a="Delgren le Purificateur se consacre à l'éradication de la corruption démoniaque dans la région. Bien qu'il ait auparavant considéré Ilkrud Magthrull comme guère plus qu'une nuisance mineure, les recherches sinistres du démoniste et sa présence active au Sanctuaire de Scarfeu corrompu font de lui une menace croissante que Delgren ne peut plus ignorer.",al={"mobile de delgren","pourquoi tuer ilkrud magthrull","objectif de delgren le purificateur"}}},fp="22,205,21.347.0,18.253.1,28.204.0,24.236.0,38.193.0,46.176.0,51.193.0,39.154.0"}
P.entries["quest:97326"] = {n="Rocks to Rests",s="Derrière Grommash Hold, Thra et ses amis aménagent un espace de jeu à Orgrimmar. Il leur faut des rochers lisses pour en faire des chaises et des tables.",h="Derrière Grommash Hold, Thra et ses amis aménagent un espace de jeu à Orgrimmar.",kw={"durotar","grommash hold","orcs","orgrimmar","rocks to rests","rochers lisses","jeu de plateau","thra"},ang={["faction:Horde"]="Aider de jeunes orcs derrière le bastion du chef de guerre montre l’importance de la communauté et de la vie quotidienne à Orgrimmar, même dans une société guerrière.",["race:Orc"]="Les jeux des jeunes orcs derrière Grommash Hold montrent comment la prochaine génération grandit au cœur de Durotar."},sec={{t="Un coin tranquille d'Orgrimmar",b="De jeunes orcs se rassemblent dans une clairière de terre derrière Grommash Hold, à Orgrimmar. Ils peuvent y jouer loin des gardes de la forteresse. Le terrain dégagé convient à leurs figurines, mais faute de mobilier, ils s’assoient dans la poussière."},{t="Mobilier de fortune",b="Thra vous aperçoit et vous demande d’apporter huit rochers lisses de taille moyenne dans la clairière. Leurs faces plates feront de solides chaises et de petites tables. Les jeunes pourront alors organiser leurs parties sans s’asseoir dans la terre."}},faq={{q="Qui donne la quête Rocks to Rests ?",a="Thra est un jeune orc qui joue avec ses amis dans la clairière derrière Grommash Hold, à Orgrimmar. Observateur et espiègle, Thra demande aux passants de l’aider à aménager l’aire de jeu.",al={"qui donne rocks to rests","thra orgrimmar","qui est thra"}},{q="Où se déroule cette quête ?",a="La clairière se trouve juste derrière Grommash Hold, le siège du chef de guerre Thrall dans la vallée de la Sagesse, à Orgrimmar. Les enfants se rassemblent dans cette parcelle de terre relativement dégagée, à l’écart du passage intense autour de la forteresse.",al={"où se trouve rocks to rests","emplacement de thra","où derrière grommash hold"}},{q="Pourquoi Thra a-t-il besoin de rochers lisses ?",a="Thra et les autres jeunes ont besoin de rochers lisses de taille moyenne pour en faire des chaises et des tables. Sans mobilier, ils s’assoient dans la terre pour installer leurs jeux de figurines et y jouer.",al={"pourquoi des rochers","à quoi servent les rochers lisses"}},{q="À quel jeu joue-t-on derrière Grommash Hold ?",a="Thra et les autres jeunes jouent à un jeu de plateau improvisé, avec de petites figurines disposées sur le sol. Les rochers lisses leur offriront des surfaces stables pour leurs figurines et des sièges confortables.",al={"à quel jeu jouent-ils","jeu de thra orgrimmar","figurines derrière grommash hold"}},{q="Rocks to Rests implique-t-elle des combats ?",a="Non. Il s’agit d’une tâche paisible, sans combat ni épreuve militaire. Vous mettez votre force à profit pour transporter de lourds rochers jusqu’à l’aire de jeu des enfants.",al={"rocks to rests est-elle dangereuse","combat dans rocks to rests"}},{q="Que font les enfants des rochers une fois livrés ?",a="Après que vous avez apporté les huit rochers lisses, Thra et les enfants les déplacent dans la clairière. Leurs faces plates leur servent de sièges et de tables pour leurs figurines.",al={"que se passe-t-il après rocks to rests","que fait thra des rochers"}}},fp="14,127,27.214.0,19.223.0,35.178.0,33.204.0,35.171.0,47.202.0,37.145.0,57.176.0"}
P.entries["quest:97328"] = {n="Anything of Value",s="Un zeppelin écrasé dans la Vallée de Strangleronce porte les traces du pillage d’une cargaison. Son étiquette déchirée indique encore la Baie-du-Butin.",h="Un zeppelin écrasé dans la Vallée de Strangleronce porte les traces du pillage d’une cargaison.",kw={"objets de valeur","baie-du-butin","écrasement","empreintes","cargaison","provisions volées","zeppelin","zul'kunda"},sec={{t="Une étiquette déchirée",b="Dans la Vallée de Strangleronce, les débris du zeppelin portent les traces du pillage d’une cargaison de provisions. Ses étiquettes sont en lambeaux, mais l’une porte encore les mots Baie-du-Butin. Des empreintes à deux orteils et des creux dans la terre mènent vers les Ruines de Zul'Kunda, au nord-ouest."}},faq={{q="Qu’est-il arrivé à la cargaison ?",a="Les provisions ont été pillées et les étiquettes d’expédition ont été déchirées.",al={"cargaison volée","cargaison du zeppelin","ce qui a été pillé"}},{q="Où menaient les empreintes ?",a="Les empreintes et les creux mènent vers les Ruines de Zul'Kunda, au nord-ouest.",al={"traces à deux orteils","où est la piste","empreintes"}},{q="Que dit l’étiquette qui subsiste ?",a="Une étiquette déchirée porte encore les mots Baie-du-Butin.",al={"étiquette de baie-du-butin","étiquette d’expédition déchirée","destination de la cargaison"}},{q="Qui a besoin des cargaisons récupérées ?",a="Les cargaisons doivent être rapportées à quelqu’un à la Baie-du-Butin.",al={"qui veut la cargaison","où rapporter la cargaison","retour de la cargaison"}}},fp="17,128,12.249.0,30.69.0,30.78.0,34.47.0,34.57.0"}
P.entries["quest:97329"] = {n="Where's the Key?",s="Zimmix Sputterspark est prisonnier d’une cage de trolls après que son zeppelin au départ de la Baie-du-Butin a été abattu. Il vous demande de lui apporter une clé détenue par les trolls de Zul’Kunda.",h="Zimmix Sputterspark est prisonnier d’une cage de trolls après que son zeppelin au départ de la Baie-du-Butin...",kw={"baie-du-butin","cage","primitive key","trolls","où est la clé","zeppelin","zimmix sputterspark","zul'kunda"},sec={{t="Un zeppelin abattu",b="Zimmix Sputterspark vous interpelle depuis sa cage, au milieu des trolls. Il avait organisé l’utilisation de la tour à zeppelins de la Baie-du-Butin pour accélérer les livraisons, mais son appareil a été abattu à l’est dès le premier trajet. Il a survécu au crash, puis s’est réveillé pour découvrir qu’on l’avait emmené de force et enfermé parmi les trolls. À présent, il vous demande de lui apporter la Primitive Key détenue par les trolls des Ruines de Zul’Kunda, dans la Vallée de Strangleronce."},{t="La clé",b="À la cage, Zimmix se jette vers la clé quand vous la lui rapportez. Il tente à plusieurs reprises de vous l’arracher et insiste pour que vous la lui remettiez."}},faq={{q="Qui est prisonnier dans la cage ?",a="Zimmix Sputterspark est enfermé dans une cage par des trolls. Son zeppelin au départ de la Baie-du-Butin a été abattu lors de son premier trajet.",al={"qui est zimmix","gnome en cage","zimix"}},{q="Qu’est-il arrivé au zeppelin de Zimmix ?",a="Zimmix raconte que son zeppelin a été abattu à l’est lors de sa première livraison.",al={"pourquoi s’est-il écrasé","crash du zeppelin","qu’est-il arrivé à zimmix"}},{q="Pourquoi Zimmix est-il dans une cage ?",a="Après avoir survécu au crash, Zimmix s’est réveillé alors qu’on le traînait par les oreilles et s’est retrouvé enfermé dans une cage parmi les trolls.",al={"pourquoi est-il en cage","cage des trolls","comment s’est-il fait capturer"}},{q="Quelle clé Zimmix veut-il ?",a="Zimmix vous demande de lui apporter la Primitive Key détenue par des trolls aux Ruines de Zul'Kunda, dans la Vallée de Strangleronce.",al={"quelle clé","primitive key","clé pour zimmix"}},{q="Où se trouve la Primitive Key ?",a="La Primitive Key est détenue par des trolls aux Ruines de Zul'Kunda, dans la Vallée de Strangleronce.",al={"où est la clé","clé de zul'kunda","emplacement de la clé"}},{q="Que fait Zimmix quand vous lui rapportez la clé ?",a="Zimmix se jette vers la clé et tente à plusieurs reprises de vous l’arracher.",al={"remise de la clé","zimmix attrape la clé","que se passe-t-il avec la clé"}}},fp="16,155,17.410.0,7.142.0,27.101.0,35.79.0,24.126.0,26.110.0,27.84.0,43.71.0"}
P.entries["quest:97331"] = {n="Zimmix's Great Escape",s="Zimmix Sputterspark vous demande de l'escorter depuis les Ruines de Zul'Kunda. Il craint que les trolls ne le capturent à nouveau, et Maître Lozgil, à Baie-du-Butin, doit être informé du sauvetage.",h="Zimmix Sputterspark vous demande de l'escorter depuis les Ruines de Zul'Kunda.",kw={"baie-du-butin","grande évasion","clé","ruines de zul'kunda","trolls","maître lozgil","zimmix","zimmix sputterspark"},sec={{t="La requête d'un gobelin",b="Aux Ruines de Zul'Kunda, Zimmix Sputterspark vous demande de monter la garde pendant son départ. Il dit que les trolls l'ont déjà capturé et craint qu'ils ne recommencent. Vous avez déjà suffisamment affaibli leurs rangs pour obtenir la clé dont il avait besoin. À présent, Zimmix veut que vous l'aidiez à rejoindre un lieu sûr, tandis que Maître Lozgil, à Baie-du-Butin, attend des nouvelles du sauvetage."}},faq={{q="Qui est Zimmix ?",a="Zimmix Sputterspark est un gobelin qui vous demande de l'escorter depuis les Ruines de Zul'Kunda.",al={"zimmix","qui est zimmix","zimmix sputterspark"}},{q="Pourquoi Zimmix veut-il une escorte ?",a="Zimmix craint que les trolls ne le capturent à nouveau, après l'avoir déjà fait une fois.",al={"pourquoi escorter zimmix","zimmix a peur","les trolls l'ont capturé"}},{q="Depuis où escortez-vous Zimmix ?",a="Vous escortez Zimmix loin des Ruines de Zul'Kunda.",al={"où est zimmix","zul'kunda","emplacement de zimmix"}},{q="Qui doit être informé du sauvetage ?",a="Maître Lozgil, à Baie-du-Butin, doit être informé du sauvetage réussi de Zimmix.",al={"qui informer","lozgil","rapport sur le sauvetage"}},{q="De quelle clé Zimmix avait-il besoin ?",a="Zimmix dit qu'il avait besoin d'une clé et que vous avez suffisamment affaibli les trolls pour l'obtenir.",al={"clé de zimmix","pourquoi obtenir la clé","clé pour zimmix"}}},fp="21,174,15.336.0,14.87.0,31.78.0,36.58.0,33.73.0,25.79.0"}
P.entries["quest:97332"] = {n="Twice Misplaced Trust",s="Un gobelin vous demande de porter un colis urgent au maître de quai Whizzbuzz, au Port de Poudremèche. Il vous fait confiance après que vous avez récupéré une cargaison égarée et sauvé un gobelin capturé.",h="Un gobelin vous demande de porter un colis urgent au maître de quai Whizzbuzz, au Port de Poudremèche.",kw={"coursier gobelin","lozgil","port de poudremèche","rives claires","confiance égarée deux fois","colis réacheminé deux fois","whizzbuzz","zimmix"},sec={{t="Un coursier recherché",b="Le gobelin a une autre livraison à faire, mais il ne fait pas confiance à Zimmix pour s'en charger. Aucun autre coursier ne sera disponible avant Zimmix, alors il vous demande de porter le colis au maître de quai Whizzbuzz, au Port de Poudremèche. Vous avez déjà récupéré une cargaison égarée et sauvé un gobelin capturé, ce qui vous a valu la confiance de l'expéditeur."},{t="Au Port de Poudremèche",b="Whizzbuzz ouvre la caisse et s'étonne que Lozgil ait enfin envoyé ce qui était attendu. Lozgil avait reçu une lettre virulente et subi les menaces d'un coursier payé. Whizzbuzz se demande si le capitaine d'un navire a été capturé ou si un zeppelin s'est écrasé, puis remarque que le port n'a pas de tour à zeppelins."}},faq={{q="Qui me demande de livrer le colis ?",a="Un gobelin vous demande de porter le colis au maître de quai Whizzbuzz, au Port de Poudremèche.",al={"qui demande une livraison","expéditeur gobelin","qui m'a envoyé"}},{q="Pourquoi le gobelin me fait-il confiance ?",a="Vous avez récupéré une cargaison égarée et sauvé un gobelin capturé. L'expéditeur vous juge donc digne de confiance.",al={"pourquoi moi","pourquoi me faire confiance","raison de la confiance"}},{q="Pourquoi ne pas laisser Zimmix le livrer ?",a="L'expéditeur ne fait pas confiance à Zimmix pour cette livraison.",al={"pourquoi pas zimmix","livraison par zimmix","pas zimmix"}},{q="Où doit aller le colis ?",a="Le colis est destiné au maître de quai Whizzbuzz, au Port de Poudremèche, dans les Rives Claires.",al={"destination du colis","où livrer","port de poudremèche"}},{q="Qui est Lozgil ?",a="Whizzbuzz attribue à Lozgil l'envoi enfin arrivé du colis.",al={"colis de lozgil","qui est lozgil","lozgil"}},{q="Pourquoi Whizzbuzz est-il surpris ?",a="Whizzbuzz est surpris en jetant un œil dans la caisse et en voyant que Lozgil a enfin envoyé ce qui était attendu.",al={"réaction de whizzbuzz","surprise dans la caisse","contenu de la caisse"}}},fp="21,155,16.304.0,18.301.1,35.83.0,29.91.0,31.52.0,26.85.0,14.69.0,27.110.0"}
P.entries["quest:97386"] = {n="The Offense of Grom'gol",s="Le commandant Aggro'gosh vous demande d'aider le Campement Grom'gol après qu'un éclaireur a repéré des ogres dans une grotte à l'est. La colonie a déjà subi leurs attaques, et le danger persiste.",h="Le commandant Aggro'gosh vous demande d'aider le Campement Grom'gol après qu'un éclaireur a repéré des ogres...",kw={"aggro'gosh","campement","grom'gol","mosh'ogg","ogres","éclaireur"},sec={{t="Rapport d'un éclaireur",b="Après que vous avez aidé à défendre le Campement Grom'gol et repoussé les ogres des environs, le commandant Aggro'gosh envoie un éclaireur en chercher d'autres. Celui-ci découvre des ogres installés dans une grotte, très loin à l'est. Aggro'gosh vous demande de frapper le Mosh'Ogg Ogre Mount, afin que la colonie ne soit plus menacée par eux."}},faq={{q="Qui demande de l'aide contre les ogres ?",a="Le commandant Aggro'gosh du Campement Grom'gol vous demande de vous occuper des ogres.",al={"qui donne cette quête","requête d'aggro'gosh"}},{q="Où l'éclaireur a-t-il trouvé les ogres ?",a="L'éclaireur les trouve dans une grotte très à l'est, au Mosh'Ogg Ogre Mount.",al={"où se trouve la grotte des ogres","où sont-ils"}},{q="Pourquoi Aggro'gosh s'inquiète-t-il des ogres ?",a="Grom'gol a déjà subi les attaques d'ogres des environs, et l'éclaireur en découvre d'autres installés dans une grotte à l'est.",al={"pourquoi combattre les ogres","menace des ogres"}},{q="Que s'est-il passé avant ?",a="Vous avez aidé à défendre Grom'gol et repoussé les ogres des environs avant que l'éclaireur parte en chercher d'autres.",al={"étape précédente","défense de grom'gol"}}},fp="23,177,16.292.0,36.75.0,35.75.0,44.97.0,26.94.0"}
P.entries["quest:97453"] = {n="Weed Whacked",s="Gemmil vous demande de vous occuper des Carnivorous Weeds au sud de Grom'gol. Ces plantes ont effrayé Gemmil pendant sa cueillette, et la sécurité du camp est en jeu.",h="Gemmil vous demande de vous occuper des Carnivorous Weeds au sud de Grom'gol.",kw={"alchimiste","carnivorous weeds","gemmil","grom'gol","herboristerie","jungle","weed whacked"},ang={["profession:Herbalism"]="En tant qu'élève en herboristerie, vous pouvez comprendre le souhait de Gemmil d'étudier les plantes et de devenir alchimiste."},sec={{t="Un jeune élève effrayé",b="Gemmil cueillait des plantes devant les portes du camp de la jungle lorsque d'énormes mauvaises herbes ont surgi et craché sur ce jeune élève. Gemmil a pu s'enfuir sans blessure, mais ne peut désormais plus jouer hors du camp. On vous demande de sécuriser la zone au sud de Grom'gol, puis de parler à la mère de Gemmil."}},faq={{q="Qui est Gemmil ?",a="Gemmil est un jeune élève en herboristerie qui espère devenir alchimiste.",al={"gemmil qui","qui est gemmil"}},{q="Qu'est-il arrivé à Gemmil ?",a="Pendant sa cueillette devant les portes, Gemmil a eu peur d'énormes mauvaises herbes qui lui ont craché dessus. Gemmil a pu s'enfuir sans blessure.",al={"gemmil attaqué","mauvaises herbes qui crachent"}},{q="Où sont les Carnivorous Weeds ?",a="Les Carnivorous Weeds se trouvent au sud de Grom'gol.",al={"emplacement mauvaises herbes","où sont les mauvaises herbes"}},{q="Pourquoi Gemmil ne peut plus jouer hors du camp ?",a="Les parents de Gemmil ne laissent plus leur enfant jouer hors du camp depuis que les mauvaises herbes lui ont fait peur.",al={"gemmil ne peut plus jouer","pourquoi plus sortir"}},{q="À qui devez-vous parler après avoir sécurisé la zone ?",a="Après avoir sécurisé la zone au sud de Grom'gol, on vous demande d'en informer la mère de Gemmil.",al={"prévenir la mère de gemmil","mère de gemmil"}}},fp="12,173,20.274.0,14.72.0,24.121.0,32.44.0,35.90.0,53.86.0"}
P.entries["quest:97485"] = {n="Traditions of the Bluff",s="Une tradition tauren vous invite à disperser de l’encens depuis Chasseur’s Rise. L’offrande peut honorer Earthmother, une chasse, une occasion ou une quête de conseils.",h="Une tradition tauren vous invite à disperser de l’encens depuis Chasseur’s Rise.",kw={"ancêtres","brindilles de cèdre","silex cérémoniel","earthmother","chasseur’s rise","encens","tradition tauren","traditions du promontoire"},ang={["race:Tauren"]="En tant que Tauren, vous honorez une tradition qui peut invoquer Earthmother ou solliciter les conseils de vos ancêtres."},sec={{t="L’encens aux vents",b="Un Tauren à Chasseur’s Rise vous demande d’honorer une tradition en dispersant de l’encens aux vents. Vous rassemblez des herbes, des brindilles de cèdre, du fil de tendon ainsi qu’un silex et de l’amadou cérémoniels auprès des fournisseurs indiqués. Sur le site cérémoniel, vous les combinez et dispersez l’encens depuis la falaise orientée au sud."},{t="De multiples occasions",b="L’encens peut être dispersé pour demander à Earthmother de veiller sur quelqu’un, bénir une chasse, marquer une occasion ou solliciter les conseils des ancêtres. Ce geste est empreint de respect, sans pour autant devoir suivre une cérémonie unique. Les différentes tribus observent des étapes traditionnelles différentes."}},faq={{q="Quelle est la tradition à Chasseur’s Rise ?",a="La tradition consiste à disperser de l’encens aux vents depuis la falaise de Chasseur’s Rise orientée au sud.",al={"tradition de l’encens","disperser l’encens","encens du promontoire"}},{q="À quoi peut servir l’offrande d’encens ?",a="Elle peut demander à Earthmother de veiller sur quelqu’un, de bénir une chasse, de célébrer une occasion ou d’apporter les conseils des ancêtres.",al={"pourquoi l’encens","à quoi sert l’encens","bénir la chasse"}},{q="De quoi ai-je besoin pour préparer l’encens ?",a="Les composants sont des herbes, des brindilles de cèdre, du fil de tendon ainsi qu’un silex et de l’amadou cérémoniels.",al={"ingrédients de l’encens","quels composants","herbes cèdre fil silex"}},{q="Où se trouve le site cérémoniel ?",a="Le site cérémoniel se trouve sur la falaise de Chasseur’s Rise orientée au sud.",al={"où disperser l’encens","emplacement du site cérémoniel","falaise sud"}},{q="Toutes les tribus pratiquent-elles cette tradition de la même manière ?",a="Non. Les différentes tribus peuvent observer des étapes traditionnelles différentes, et le geste n’est pas strictement cérémoniel.",al={"coutumes des différentes tribus","même cérémonie","étapes de l’encens"}}},fp="23,155,20.290.0,14.259.0,41.96.0,37.124.0,35.85.0,29.68.0,49.101.0"}
P.entries["quest:97530"] = {n="Dunemaul Dues",s="Le chef de la sécurité Bilgewhizzle du Port Gentepression veut récupérer un bracelet étincelant près du campement des ogres Dunemaul. Une caravane marchande l’a perdu en jetant sa cargaison pour distraire les ogres.",h="Le chef de la sécurité Bilgewhizzle du Port Gentepression veut récupérer un bracelet étincelant près du...",kw={"bracelet","bilgewhizzle","caravane","dunemaul dues","ogres dunemaul","cargaison perdue","port gentepression"},sec={{t="Cargaison perdue",b="Une caravane a perdu sa cargaison près du campement des ogres Dunemaul après leur attaque. Le chef de la sécurité Bilgewhizzle du Port Gentepression vous demande de récupérer un bracelet particulièrement étincelant. Les marchands lui réclament les bénéfices qu’ils ont perdus, et il vous promet une récompense à la hauteur de vos efforts."}},faq={{q="Qui veut récupérer le bracelet ?",a="Le chef de la sécurité Bilgewhizzle du Port Gentepression veut que vous récupériez le bracelet étincelant.",al={"qui m’a envoyé","bracelet de bilgewhizzle","qui le veut"}},{q="Où le bracelet a-t-il été perdu ?",a="Le bracelet a été perdu près du campement des ogres Dunemaul.",al={"où est le bracelet","emplacement du bracelet","où perdu"}},{q="Comment la caravane a-t-elle perdu sa cargaison ?",a="La caravane a pris un mauvais chemin dans le désert et a été attaquée par les ogres Dunemaul. Ses membres ont jeté de la cargaison par-dessus bord pour les distraire.",al={"qu’est-il arrivé à la caravane","caravane dunemaul","pourquoi la cargaison est perdue"}},{q="Pourquoi Bilgewhizzle veut-il le récupérer ?",a="Les marchands réclament à Bilgewhizzle les bénéfices perdus avec leur cargaison.",al={"pourquoi retrouver le bracelet","bénéfices perdus","ennuis du marchand"}},{q="Quel genre de bracelet Bilgewhizzle recherche-t-il ?",a="Bilgewhizzle demande un bracelet particulièrement étincelant.",al={"bracelet étincelant","quel bracelet","quête du bracelet"}}},fp="13,183,10.277.0,26.87.0,26.52.0,35.135.0,40.79.0,48.59.0"}
P.entries["quest:97534"] = {n="Gritty Business",s="À Gadgetzan, Quinn vous offre une part du butin récupéré sur les machines du désert. Elle compte vendre les pièces aux récupérateurs.",h="À Gadgetzan, Quinn vous offre une part du butin récupéré sur les machines du désert.",kw={"débris du désert","pile à combustible","gadgetzan","gritty business","récupérateurs","machines","quinn","butin récupéré"},sec={{t="Une part du butin récupéré",b="Quinn a de l’argent pour vous à Gadgetzan, où elle compte trier et vendre ce que vous rapporterez. Les machines du désert perdent des pièces que les passionnés de technologie pourraient utiliser pour fabriquer des piles à combustible. Quinn veut que vous lui rapportiez sept pièces de Desert Debris et vous promet une part du produit de la vente."}},faq={{q="Qui demande les débris ?",a="Quinn, à Gadgetzan, vous demande de récupérer du Desert Debris sur les machines du désert.",al={"qui veut les débris","récupération de quinn","donneur de gritty business"}},{q="Que veut Quinn que je rapporte ?",a="Quinn veut sept pièces de Desert Debris.",al={"quelles pièces","pièces de débris","objets de gritty business"}},{q="Pourquoi Quinn veut-elle les pièces des machines ?",a="Quinn compte vendre les pièces récupérées à des récupérateurs qui pourraient les utiliser pour fabriquer des piles à combustible.",al={"pourquoi les débris","à quoi ça sert","raison de récupérer les pièces"}},{q="Que me propose Quinn en échange ?",a="Quinn vous promet une part de l’argent obtenu en vendant les pièces récupérées.",al={"qu’est-ce que j’y gagne","marché de quinn","récompense de gritty business"}},{q="Où puis-je trouver Quinn ?",a="Quinn se trouve à Gadgetzan.",al={"emplacement de quinn","où est quinn","donneur à gadgetzan"}}},fp="15,126,22.280.0,29.86.0,38.42.0,38.87.0,32.64.0,22.22.0"}
P.entries["quest:97538"] = {n="Pigments for Paints",s="Tah Winterhoof a besoin de pigment rouge pour ses peintures, et vous pouvez l'aider à refaire ses réserves. Cette couleur vient des cosses de bourbielle récoltées dans le lac Mirkfallon, dans Les Serres-Rocheuses.",h="Tah Winterhoof a besoin de pigment rouge pour ses peintures, et vous pouvez l'aider à refaire ses réserves.",kw={"lac mirkfallon","bourbielle","cosses de bourbielle","pigments for paints","pigment rouge","les serres-rocheuses","tah winterhoof","pitons-du-tonnerre"},ang={["faction:Horde"]="En tant que membre de la Horde, vous connaissez les liens entre Pitons-du-Tonnerre et les cols escarpés des Serres-Rocheuses.",["profession:Herbalism"]="En tant qu'herboriste, vous savez que les plantes aquatiques comme la bourbielle peuvent fournir des pigments utiles, en plus des plantes médicinales. Les eaux du lac Mirkfallon sont dangereuses.",["race:Tauren"]="En tant que tauren, vous voyez comment les artisans de Pitons-du-Tonnerre utilisent des plantes naturelles pour créer des pigments et des teintures traditionnels."},sec={{t="Le besoin d'un artisan",b="Tah Winterhoof n'a plus de pigment rouge et ne peut pas poursuivre son travail. Il vit à Pitons-du-Tonnerre, et ses voyages sont derrière lui. Il vous demande donc de faire le long trajet vers le nord, dans Les Serres-Rocheuses, pour récolter de quoi colorer ses peintures."},{t="Les eaux de Mirkfallon",b="Le lac Mirkfallon se trouve dans un col des Serres-Rocheuses. La bourbielle pousse sous ses eaux, et ses cosses deviennent rouges une fois récoltées et séchées. Rapportez-en trente, et Tah aura la matière première nécessaire pour reprendre son travail."}},faq={{q="Qui donne la quête Pigments for Paints ?",a="Tah Winterhoof demande de l'aide à Pitons-du-Tonnerre. Ses voyages sont derrière lui, et il a besoin d'une personne plus jeune pour récolter les matériaux nécessaires à son artisanat.",al={"qui donne pigments for paints","donneur de quête pigments for paints","emplacement de tah winterhoof"}},{q="Où trouver les cosses de bourbielle ?",a="La bourbielle pousse dans les eaux du lac Mirkfallon, un grand lac rond situé dans un col des Serres-Rocheuses.",al={"où trouver les cosses de bourbielle","emplacement de la bourbielle","où se trouve le lac mirkfallon"}},{q="Pourquoi Tah Winterhoof a-t-il besoin de bourbielle ?",a="Tah Winterhoof n'a plus de pigment rouge pour ses œuvres. Les cosses de bourbielle séchées deviennent rouges et servent de teinture pour ses peintures.",al={"pourquoi récolter la bourbielle","à quoi sert la bourbielle","pourquoi du pigment rouge"}},{q="Combien de cosses de bourbielle faut-il ?",a="Tah Winterhoof a besoin de trente cosses de bourbielle du lac Mirkfallon pour refaire ses réserves de pigment rouge.",al={"combien de cosses faut-il","nombre de cosses de bourbielle"}},{q="Qu'est-ce que la bourbielle ?",a="La bourbielle est une plante aquatique qui pousse dans le lac Mirkfallon, dans Les Serres-Rocheuses. Ses cosses séchées donnent un pigment rouge.",al={"quel type de plante est la bourbielle","détails sur la bourbielle"}},{q="Où se trouve Tah Winterhoof ?",a="Tah Winterhoof vit au sommet de la cité bâtie sur une mesa de Pitons-du-Tonnerre, en Mulgore, où il exerce son artisanat et prépare des peintures traditionnelles.",al={"où se trouve tah winterhoof","tah winterhoof à pitons-du-tonnerre"}}},fp="19,175,17.239.0,24.243.0,40.144.0,30.116.0,38.119.0,34.92.0,17.118.0,32.130.0"}
P.entries["quest:97539"] = {n="Silky Sutures",s="À Trépas-d'Orgrim, le Docteur Gregory Victor se tourne vers la soie d’araignée à mesure que les réserves de l’infirmerie s’épuisent. Les dégâts du siège restent sans réparation, et les gardes comme les ouvriers de l’avant-poste ont toujours besoin de soins.",h="À Trépas-d'Orgrim, le Docteur Gregory Victor se tourne vers la soie d’araignée à mesure que les réserves de...",kw={"hautes-terres arathies","docteur gregory victor","sutures de campagne","trépas-d'orgrim","infirmerie","silky sutures","soie d'araignée","soie d'araignée chirurgicale"},ang={["faction:Horde"]="Trépas-d'Orgrim est une place forte vitale de la Horde dans les Hautes-terres Arathies. Le travail du Docteur Victor maintient ses défenseurs en bonne santé et prêts à protéger la position de leur faction sur place.",["race:Undead"]="En tant que mort-vivant, vous apportez à Trépas-d'Orgrim les connaissances médicales pragmatiques et sans sentimentalisme des Réprouvés, utilisant les ressources des hautes-terres pour maintenir la clinique en activité."},sec={{t="L'avant-poste en ruine",b="Trépas-d'Orgrim tient bon dans les Hautes-terres Arathies, malgré les dégâts du siège qui marquent encore ses défenses. Le Docteur Gregory Victor, médecin de l’avant-poste, voit dans cet abandon une politique officielle. Avec peu de soutien et des fortifications qui s’effritent autour de lui, il maintient l’infirmerie en activité. Les soins qui y sont prodigués aident les ouvriers et les sentinelles à rester debout et prêts au combat."},{t="Fournitures médicales de fortune",b="Les fournitures médicales viennent à manquer à Trépas-d'Orgrim, et le Docteur Victor cherche donc un autre moyen de suturer les plaies. La solide soie des araignées des hautes-terres peut être torsadée en fils de suture résistants lorsque les bandages et le fil ordinaire se font rares. Victor plaisante en disant que l’infection est le cadet des soucis d’un soldat blessé. Cette soie fournit à l’infirmerie de quoi recoudre les défenseurs en territoire hostile."},{t="Humour noir à Trépas-d'Orgrim",b="Le Docteur Gregory Victor accueille les voyageurs avec des plaisanteries pince-sans-rire sur les pronostics funestes et les sutures en soie d’araignée. Son humour masque la dure réalité d’une clinique qu’il faut faire fonctionner sur le front, alors que Trépas-d'Orgrim reste isolé. L’aide régulière est rare dans les hautes-terres, et les voyageurs peuvent contribuer au ravitaillement de la clinique. Victor compte sur des remèdes improvisés et sur sa détermination pour soigner les blessés tandis que l’avant-poste se délabre autour de lui."}},faq={{q="Qui est le Docteur Gregory Victor ?",a="Le Docteur Gregory Victor dirige l’infirmerie de Trépas-d'Orgrim en tant que médecin militaire et chirurgien traumatologue. Il soigne les gardes et les ouvriers blessés avec un franc-parler et un humour mordant. Malgré les pénuries et les dégâts du siège laissés sans réparation, il maintient le service en activité.",al={"qui est victor","histoire de gregory victor","docteur de trépas-d'orgrim"}},{q="Pourquoi le Docteur Victor a-t-il besoin de soie d'araignée ?",a="Le Docteur Victor a besoin de soie d’araignée, car les réserves ordinaires de l’infirmerie de Trépas-d'Orgrim sont presque épuisées. Il torsade la solide soie des araignées des hautes-terres pour suturer les plaies lorsque le fil adapté fait défaut.",al={"pourquoi de la soie d'araignée","utilisation de soie d'araignée chirurgicale","sutures en soie d'araignée"}},{q="Dans quel état se trouve Trépas-d'Orgrim pendant cette quête ?",a="Trépas-d'Orgrim porte des signes évidents d’abandon et d’épuisement. Les dégâts du siège restent sans réparation, et le Docteur Victor voit dans cet abandon une politique officielle. Avec peu d’aide et de fournitures, les gardes, les ouvriers et le personnel médical doivent se débrouiller.",al={"statut de trépas-d'orgrim","pourquoi trépas-d'orgrim est endommagé","état de trépas-d'orgrim"}},{q="D'où viennent les araignées de cette quête ?",a="Les araignées rôdent dans les étendues sauvages des Hautes-terres Arathies, autour de Trépas-d'Orgrim. Il faut les chasser à travers les plaines des hautes-terres pour recueillir la soie destinée aux sutures du Docteur Victor, puis les rapporter à la clinique.",al={"araignées d'arathi","où trouver de la soie d'araignée","emplacement de la soie d'araignée chirurgicale"}},{q="Pourquoi le Docteur Victor se montre-t-il sarcastique au sujet des infections ?",a="Le Docteur Victor plaisante en disant que l’infection est le cadet des soucis d’un soldat blessé lorsqu’il le recoud avec de la soie d’araignée. Son humour noir reflète les exigences des soins sur le front, où arrêter les hémorragies et traiter les blessures graves passe avant la stérilité.",al={"humour du docteur","infection par la soie d'araignée","plaisanteries de victor"}},{q="Pourquoi le ravitaillement est-il si rare à Trépas-d'Orgrim ?",a="Trépas-d'Orgrim est isolé dans une région disputée des Hautes-terres Arathies et fait face à des menaces ennemies. Les renforts et le ravitaillement arrivent rarement, laissant la garnison et l’infirmerie à court de matériaux, d’outils et de fournitures médicales.",al={"pourquoi pas de fournitures","pénurie de ravitaillement à trépas-d'orgrim","manque d'aide à trépas-d'orgrim"}},{q="Qui l'infirmerie de Trépas-d'Orgrim soigne-t-elle ?",a="L’infirmerie du Docteur Gregory Victor soigne les ouvriers et les gardes en poste à Trépas-d'Orgrim. Les maintenir en bonne santé aide l’avant-poste à rester fortifié et opérationnel malgré le danger et les dégâts subis par ses structures.",al={"qui victor soigne-t-il","patients de trépas-d'orgrim","patients de la clinique"}}},fp="13,181,21.353.0,26.364.0,27.407.0,29.245.0,40.200.0,50.227.0,46.198.0,47.257.0,41.226.0,43.198.0"}
P.entries["quest:97558"] = {n="Hides for the Forsaken",s="Dans les Clairières de Tirisfal, les Réprouvés récupèrent des peaux pour préserver leur corps. Shelene Rhobart vous demande des peaux de chiens de l’ombre, des membranes d’ailes de chauve-souris du crépuscule et de la peau de murloc.",h="Dans les Clairières de Tirisfal, les Réprouvés récupèrent des peaux pour préserver leur corps.",kw={"peau de chien de l’ombre","aile de chauve-souris du crépuscule","hides for the forsaken","shelene rhobart","clairières de tirisfal","greffe de mort-vivant","murloc de la gueule vile"},ang={["profession:Tailoring"]="En tant que couturier, vous pouvez coudre des membranes de bête sur des corps en décomposition pour confectionner des vêtements.",["race:Undead"]="En tant que mort-vivant, vous subissez les contraintes de la condition des Réprouvés. Garder votre corps intact demande un effort constant et des greffes récupérées, car il ne guérit pas naturellement."},sec={{t="Le prix de la non-mort",b="La chair des Réprouvés ne peut pas se réparer. Quand ils sont blessés, la plaie pourrit et reste ouverte. Ils cousent donc des tissus vivants sur leurs blessures pour maintenir leur corps et garder leurs cadavres fonctionnels."},{t="Des matériaux spécialisés",b="Chaque matériau sert à réparer une partie différente du corps. La peau épaisse des chiens de l’ombre tient bien sur les blessures étendues. Les membranes d’ailes de chauve-souris du crépuscule sont fines et souples ; elles couvrent le visage et les doigts sans les raidir. La peau des murlocs de la Gueule vile tapisse les membranes internes et les zones sensibles, comme les joues et la bouche."}},faq={{q="Pourquoi les Réprouvés ont-ils besoin de peaux d’animaux ?",a="La peau des Réprouvés ne peut ni guérir ni repousser après une blessure. Ils prélèvent des peaux et des membranes sur des créatures vivantes pour couvrir leurs blessures et ralentir la décomposition.",al={"pourquoi les réprouvés ont besoin de peaux","légendes sur la guérison des morts-vivants","les morts-vivants guérissent-ils"}},{q="Qui est Shelene Rhobart ?",a="Shelene Rhobart est une travailleuse du cuir réprouvée dans les Clairières de Tirisfal. Elle récupère des peaux et d’autres matériaux pour aider les blessés à réparer leur corps en décomposition.",al={"shelene rhobart","qui est shelene"}},{q="Pourquoi faut-il précisément des membranes d’ailes de chauve-souris du crépuscule ?",a="Les membranes d’ailes de chauve-souris du crépuscule sont fines et souples. Elles couvrent les zones délicates comme le visage et les doigts sans rendre la peau trop épaisse ni trop rigide.",al={"utilisation des ailes de chauve-souris du crépuscule","pourquoi des membranes de chauve-souris du crépuscule"}},{q="À quoi sert la peau de murloc ?",a="La peau des murlocs de la Gueule vile tapisse les membranes internes et les surfaces délicates, notamment l’intérieur des joues et de la bouche.",al={"pourquoi la peau de murloc","peau de murloc pour les morts-vivants"}},{q="Où trouve-t-on ces matériaux ?",a="Les chiens de l’ombre, les chauves-souris du crépuscule et les murlocs de la Gueule vile parcourent les Clairières de Tirisfal. Les chiens de l’ombre et les chauves-souris du crépuscule hantent les bois et les bords des routes, tandis que les murlocs de la Gueule vile se rassemblent le long de la côte nord et des cours d’eau intérieurs.",al={"où trouver des peaux","bêtes des clairières de tirisfal"}},{q="Les Réprouvés utilisent-ils souvent des peaux d’animaux ?",a="Oui. Les Réprouvés comptent sur les tissus animaux et les restes récupérés pour continuer à vivre. Sans chair ni peaux de remplacement, les blessures peuvent exposer les os, les organes et les muscles.",al={"tous les réprouvés utilisent-ils des peaux","fabrication de chair chez les réprouvés"}}},fx={["84f1a52c"]={q="À quoi sert la Peau de limier noir ?",a="La chair des morts-vivants ne guérit pas naturellement des blessures, forçant les Réprouvés à rapiécer leurs corps avec des peaux de bêtes récoltées. Alors que les tissus délicats nécessitent de fines membranes, des peaux plus épaisses et plus résistantes comme la peau de limier servent de greffes durables pour les surfaces larges et très sollicitées du corps qui nécessitent une peau de remplacement solide et résiliente.",al={"utilisation de la peau de limier","pourquoi la peau de limier","peau de limier réprouvés"}}},fp="22,159,20.196.0,21.301.0,38.139.0,23.147.0,51.140.0,29.108.0,32.196.0,46.166.0"}
P.entries["quest:97583"] = {n="WRIGGLE.",s="À Fossoyeuse, WRIGGLE. danse avec les voyageurs, puis se fatigue et a besoin d'une gelée spéciale. Une fois nourri, il suit un nouvel ami.",h="À Fossoyeuse, WRIGGLE.",kw={"canals","limon plein d'entrain","gelée nutritive","limon","gelée","fossoyeuse","wriggle"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez acheter cette gelée spéciale auprès des marchands des canaux de Fossoyeuse, la capitale des Réprouvés.",["race:Undead"]="En tant que Réprouvé, vous connaissez bien les eaux usées toxiques et les limons animés des canaux de Fossoyeuse. Un limon compagnon se sent chez lui à vos côtés."},sec={{t="Un limon danseur",b="À Fossoyeuse, WRIGGLE. se joint aux danses des voyageurs amicaux. Ce petit limon déborde d'énergie, mais se fatigue vite et a besoin de nourriture pour reprendre des forces."},{t="De quoi se nourrir dans les canaux",b="Vous pouvez acheter de la Gelée nutritive dans les canaux rances de Fossoyeuse. WRIGGLE. absorbe cette friandise fétide et retrouve son énergie. Il s'attache alors à la personne qui l'a nourri et est prêt à suivre son nouvel ami."}},faq={{q="Qu'est-ce que WRIGGLE. ?",a="Vous vous liez d'amitié avec WRIGGLE. en dansant avec ce petit limon plein d'entrain. Il a besoin d'une nourriture spéciale pour garder son énergie.",al={"quête wriggle","qu'est-ce que wriggle","quête de danse avec un limon"}},{q="Où trouver de la Gelée nutritive ?",a="Un marchand vend de la Gelée nutritive dans les canaux de Fossoyeuse, où les déchets alchimiques et les eaux usées sont courants.",al={"où trouver de la gelée","marchand de gelée nutritive","nourrir un limon à fossoyeuse"}},{q="Comment attirer l'attention du limon s'il semble fatigué ?",a="Dansez avec le limon fatigué ou distrait, et il imite vos mouvements enjoués.",al={"comment attirer un limon","limon fatigué","réveiller wriggle le limon"}},{q="Pourquoi le limon se nourrit-il de gelée ?",a="Les limons absorbent les boues et les écumes alchimiques qui les entourent pour rester forts et retrouver leur vitalité après l'effort.",al={"pourquoi les limons mangent de la gelée","que mangent les limons"}},{q="Que se passe-t-il une fois le limon nourri ?",a="Une fois nourri de sa gelée préférée, le limon revigoré se lie d'amitié avec vous et cherche à vous suivre.",al={"le limon vous suit-il","compagnon limon","récompense wriggle"}},{q="Les joueurs de l'Alliance peuvent-ils facilement obtenir la gelée ?",a="Les voyageurs de l'Alliance courent de grands dangers en entrant dans Fossoyeuse. Les marchands des canaux vendent la gelée dans la capitale des Réprouvés.",al={"l'alliance peut-elle faire wriggle","gelée pour limon de l'alliance"}}},fp="8,133,15.156.0,26.198.0,17.107.0,42.107.0,57.80.0,34.103.0,35.92.0,46.118.0"}
P.entries["quest:976"] = {n="De l’approvisionnement pour Auberdine",s="Feero Main-de-fer transporte des provisions et des messages du Poste de Maestra à Auberdine, et la route vers le nord a besoin de gardes. Les dangers près de la Tour d'Althalaxx et les infiltrateurs hostiles rendent le voyage périlleux.",h="Feero Main-de-fer transporte des provisions et des messages du Poste de Maestra à Auberdine, et la route vers...",kw={"orneval","auberdine","balizar the umbrage","sombrivage","delgren le purificateur","feero main-de-fer","poste de maestra","sentinelle starbreeze","tour d'althalaxx"},ang={["faction:Alliance"]="En gardant cette route, vous aidez à maintenir les avant-postes d'Orneval reliés à Auberdine et à préserver la fragile emprise de l'Alliance sur le nord de Kalimdor.",["race:Human"]="En tant qu'humain, vous voyez Feero Main-de-fer montrer la volonté de votre peuple à soutenir ses alliés kaldorei dans d'anciennes forêts inconnues et dangereuses.",["race:NightElf"]="Les provisions et les messages que vous escortez vers le nord aident les sentinelles d'Auberdine, confrontées aux ténèbres grandissantes de Sombrivage et de la frontière d'Orneval."},sec={{t="Une route périlleuse vers le nord",b="Le Poste de Maestra se trouve sur la frontière occidentale d'Orneval, entre la forêt et Sombrivage. Après des enquêtes sur des activités sinistres près de la Tour d'Althalaxx, Delgren le Purificateur envoie des provisions et des renseignements à la sentinelle Starbreeze, à Auberdine. L'avant-poste préfère les escortes armées aux coursiers solitaires. Feero Main-de-fer parcourt donc la route forestière avec des gardes."},{t="Des ombres sur le sentier",b="Le voyage de Feero Main-de-fer vers le nord le conduit dans des bois où les embuscades menacent sa livraison. Les sectateurs du Dark Strand veulent faire taire les rapports sur leurs rituels démoniaques. Des éclaireurs réprouvés rôdent dans les sous-bois, et Balizar the Umbrage, Aligar the Tormentor et Caedakar the Vicious tentent chacun d'abattre la caravane avant qu'elle n'atteigne la frontière."}},faq={{q="Qui est Feero Main-de-fer ?",a="Feero Main-de-fer est un coursier humain au Poste de Maestra, dans l'ouest d'Orneval. Delgren le Purificateur lui confie des messages et des provisions pour Auberdine. Feero refuse de voyager sans de solides gardes du corps.",al={"feero","histoire de feero main-de-fer","qui est le nain escorteur"}},{q="Pourquoi Auberdine a-t-elle besoin de ces provisions ?",a="Sombrivage et le nord d'Orneval sont confrontés à une corruption grandissante et aux menaces des sectateurs démoniaques près de la Tour d'Althalaxx. Les sentinelles elfes de la nuit d'Auberdine, dirigées sur place par la sentinelle Starbreeze, ont besoin de provisions et de renseignements récents pour défendre la côte.",al={"pourquoi envoyer des provisions à auberdine","provisions pour auberdine","sentinelle starbreeze"}},{q="Qui attaque Feero sur la route ?",a="Feero avertit que des ennemis dangereux rôdent dans la forêt et demande des gardes. Leurs identités se révèlent au cours de l'escorte.",al={"qui tend une embuscade à feero","assaillants de feero","qui attaque sur la route"}},{q="Quel est le lien avec la Tour d'Althalaxx ?",a="Delgren le Purificateur dirige les efforts visant à découvrir et à perturber les sombres rituels des sectateurs à la Tour d'Althalaxx. Cette escorte découle de cette enquête et apporte renseignements et soutien aux dirigeants elfes de la nuit d'Auberdine.",al={"lien avec althalaxx","tour d'althalaxx","lien avec delgren"}},{q="À qui dois-je faire mon rapport après avoir protégé Feero ?",a="Après avoir escorté Feero sain et sauf à travers les embuscades d'Orneval, faites votre rapport à Delgren le Purificateur, au Poste de Maestra, et confirmez que la livraison a réussi.",al={"rendre la quête de l’approvisionnement pour auberdine","où aller après avoir escorté feero","rendre la quête"}}},fx={["1813fb85"]={q="Pourquoi Feero Main-de-fer veut-il livrer ces fournitures ?",a="Delgren le Purificateur a chargé Feero de livrer des fournitures cruciales et des messages vitaux vers le nord à la sentinelle Starbreeze à Auberdine. Des forces obscures et des cultistes infestés de desseins sinistres opèrent dans tout l'ouest d'Orneval, et Feero sait que laisser ces communications ou provisions sensibles tomber entre les mains de l'ennemi pourrait s'avérer désastreux pour la défense de l'Alliance.",al={"mobile de feero main-de-fer","pourquoi feero a-t-il besoin d'aide","pourquoi des fournitures pour auberdine"}},affb8fb0={q="Pourquoi Feero Main-de-fer vous demande-t-il une protection plutôt que celle des gardes du poste ?",a="Feero n'aime pas voyager seul alors qu'il transporte des fournitures et des messages importants à travers l'Orneval dangereux. Il demande des gardes du corps pour aider à ce que la livraison atteigne Auberdine en toute sécurité.",al={"pourquoi moi feero","pourquoi feero a-t-il besoin d'une escorte","pourquoi feero ne part-il pas seul"}}},fp="21,199,21.359.0,23.343.1,22.201.0,39.255.0,33.117.0,49.232.0,41.145.0"}
P.entries["quest:97663"] = {n="Supplies and Studies",s="À Kargath, Mus'hale vous demande de récupérer des provisions volées et de faire des estampages de pierres gravées dans la Vallée de la poussière. Ces gravures sont les documents d'étude que Mus'hale a perdus lors de l'attaque des ogres des environs.",h="À Kargath, Mus'hale vous demande de récupérer des provisions volées et de faire des estampages de pierres...",kw={"vallée de la poussière","kargath","mushale","ogres","estampages","provisions volées","gravures sur pierre"},sec={{t="Documents perdus",b="Mus'hale se remet à l'auberge de Kargath après avoir été pris pour cible par des ogres des environs dans la Vallée de la poussière. Avant l'attaque, Mus'hale avait découvert des pierres inhabituelles portant des gravures et en avait fait des estampages pour les étudier. À présent, le sac et ces documents ont disparu. On vous demande donc de chercher à l'est et de faire de nouveaux estampages des gravures."}},faq={{q="Qui est Mus'hale ?",a="Mus'hale est un érudit qui a découvert des pierres gravées dans la Vallée de la poussière et en a fait des estampages pour les étudier.",al={"mushale","qui est mushale","histoire de mushale"}},{q="Qu'est-il arrivé aux provisions de Mus'hale ?",a="Des ogres des environs ont attaqué Mus'hale dans la Vallée de la poussière. Mus'hale s'est réveillé sous la garde de l'aubergiste, sans son sac.",al={"provisions volées","où est le sac de mushale","les ogres ont pris le sac"}},{q="Que Mus'hale veut-il que je trouve ?",a="Mus'hale vous demande de chercher le sac volé à l'est et de faire des estampages des gravures sur les pierres voisines.",al={"quête provisions et études","que dois-je chercher","trouver des estampages"}},{q="Où se trouvent les pierres gravées ?",a="Les pierres inhabituelles gravées se trouvent dans la Vallée de la poussière.",al={"gravures de la vallée de la poussière","où sont les pierres","gravures sur pierre"}},{q="Où dois-je retrouver Mus'hale ?",a="Mus'hale se trouve à Kargath, où il se remet sous la garde de l'aubergiste.",al={"retourner auprès de mushale","où est mushale","auberge de kargath"}}},fp="20,186,14.307.0,16.88.0,37.110.0,35.100.0,28.45.0,30.62.0"}
P.entries["quest:97884"] = {n="Armory of Sunnyglade",s="Quelqu’un vous demande de récupérer à Clairsoleil, dans les Rives Claires, un grimoire de forge dont le titre le lie à la famille Tremayne.",h="Quelqu’un vous demande de récupérer à Clairsoleil, dans les Rives Claires, un grimoire de forge dont le titre...",kw={"armurerie de clairsoleil","techniques de forge","rives claires","clairsoleil","tome","famille tremayne"},sec={{t="Un tome familial",b="À Clairsoleil, dans les Rives Claires, on vous demande de récupérer un ouvrage sur les techniques de forge de la famille Tremayne. La demande porte sur le tome lui-même ; son emplacement à Clairsoleil reste à déterminer."}},faq={{q="Que cherchez-vous ?",a="Vous cherchez le tome intitulé Tremayne Family Blacksmithing Techniques.",al={"quel tome","livre de forge","tome tremayne"}},{q="Où se trouve le tome ?",a="Le tome est recherché à Clairsoleil, dans les Rives Claires.",al={"où le trouver","tome de clairsoleil","emplacement de l’armurerie"}},{q="Qui est la famille Tremayne ?",a="Le titre associe les techniques de forge à la famille Tremayne.",al={"famille tremayne","qui sont les tremayne"}}},fp="20,126,13.218.0,22.73.0,18.53.0,27.75.0"}
P.entries["quest:97891"] = {n="Prompt Potion Runner",s="À Fossoyeuse, un coursier transporte le breuvage d'Alessandro au-delà du canal de limon avant qu'il ne se gâte. Il doit atteindre L'Apothicarium à temps.",h="À Fossoyeuse, un coursier transporte le breuvage d'Alessandro au-delà du canal de limon avant qu'il ne se...",kw={"alessandro","l'apothicarium","docteur martin felben","prompt potion runner","société royale des apothicaires","canal de limon","fossoyeuse","potion instable"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez aider les Réprouvés dans leurs dangereux travaux alchimiques à Fossoyeuse, où les voyageurs doivent traverser des canaux de limon toxique.",["race:Undead"]="En tant que Mort-vivant, vous savez que des articulations fragiles et des genoux en décomposition peuvent entraver les travaux essentiels dans les laboratoires de la Société royale des apothicaires."},sec={{t="Une course contre la décomposition",b="Alessandro a besoin d'un coursier rapide dans les couloirs souterrains de Fossoyeuse. Cet alchimiste réprouvé a préparé un breuvage volatil qui va bientôt se gâter. Ses articulations de mort-vivant sont trop fragiles pour lui permettre de traverser le canal de limon toxique. Vous devez transporter le breuvage intact avant qu'il ne devienne une boue inutile."},{t="Les exigences de L'Apothicarium",b="Le docteur Martin Felben attend le breuvage à L'Apothicarium, où il en a besoin pour ses recherches en cours. Il affirme que les six potions envoyées par Alessandro avant celle-ci se sont déstabilisées en chemin. Une livraison à temps permet au docteur de poursuivre ses sombres expériences sans interruption. Le breuvage instable et les articulations fragiles d'Alessandro illustrent les dangers de l'alchimie des Réprouvés et de la non-mort."}},faq={{q="Qui donne cette quête ?",a="Alessandro, à Fossoyeuse, a besoin que vous transportiez sa livraison. Ses genoux de mort-vivant se déboîtent et claquent quand il essaie de courir. Il ne peut donc pas traverser lui-même le canal de limon à toute vitesse.",al={"qui donne prompt potion runner","qui lance prompt potion runner","qui est alessandro"}},{q="Où faut-il apporter la potion ?",a="Apportez la potion au docteur Martin Felben, à L'Apothicarium de Fossoyeuse, où il mène des expériences alchimiques.",al={"où apporter la potion","qui est le docteur martin felben","où rendre prompt potion runner"}},{q="Pourquoi la livraison doit-elle arriver à temps ?",a="La concoction est instable et se conserve très peu de temps. Traversez rapidement le canal avec elle, ou elle se déstabilisera et deviendra inutile.",al={"pourquoi la livraison est chronométrée","durée de conservation d'une potion instable","pourquoi se dépêcher"}},{q="D'autres tentatives de livraison ont-elles échoué ?",a="Le docteur Martin Felben affirme que les six potions qu'Alessandro a tenté d'envoyer avant celle-ci se sont déstabilisées avant d'atteindre L'Apothicarium.",al={"d'autres coursiers ont-ils échoué","tentatives précédentes d'alessandro","combien de potions ont échoué"}},{q="Pourquoi Alessandro ne peut-il pas livrer la potion lui-même ?",a="Alessandro dit que ses genoux claquent et se déboîtent dès qu'il essaie de courir. Ces effets de la non-mort l'empêchent de se dépêcher pour livrer la potion lui-même.",al={"pourquoi alessandro ne peut-il pas livrer la potion","genoux d'alessandro"}},{q="En quoi consistent les expériences du docteur Felben ?",a="Le docteur Martin Felben est un apothicaire qui mène des expériences à L'Apothicarium. La formule exacte reste obscure, et il reprend ses recherches dès que le mélange stable arrive.",al={"que fait le docteur felben","à quoi sert la potion"}}},fp="20,141,20.272.0,26.371.0,21.164.0,33.115.0,26.136.0,36.129.0,48.139.0,37.179.0"}
P.entries["quest:97894"] = {n="Business in Auberdine",s="À Hurlevent, Borgus Steelhand attend des nouvelles de son frère Gorbold, à Auberdine. Vous pouvez rejoindre Gorbold en naviguant vers l’ouest depuis le Port de Hurlevent jusqu’au nord de Kalimdor.",h="À Hurlevent, Borgus Steelhand attend des nouvelles de son frère Gorbold, à Auberdine.",kw={"auberdine","borgus steelhand","business in auberdine","sombrivage","gorbold main-d'acier","marchand","steelhand","port de hurlevent"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez naviguer directement entre le Port de Hurlevent et Auberdine, reliant le royaume humain aux terres kaldorei du nord de Kalimdor.",["race:Dwarf"]="En tant que nain, vous pouvez trouver des marchands nains comme les Steelhand qui commercent bien au-delà des montagnes de Khaz Modan, jusque dans les villages paisibles et ombragés des Elfes de la nuit."},sec={{t="Un Nain loin de chez lui",b="Gorbold a traversé La Grande mer pour tenir un étal marchand à Auberdine. Il espérait faire des bénéfices en ravitaillant les navires faisant escale à Sombrivage. Des semaines ont passé sans nouvelles, et Borgus s’inquiète pour son frère, si loin de Forgefer et de Hurlevent."},{t="La traversée depuis le port",b="La route vers Kalimdor passait autrefois par le Port de Menethil ou par des ports gobelins neutres comme la Baie-du-Butin. Borgus vous envoie vers le navire amarré au quai le plus au sud du Port de Hurlevent. Sa traversée directe s’achève aux longues jetées de bois d’Auberdine."}},faq={{q="Qui est Borgus Steelhand ?",a="Borgus Steelhand est un marchand nain de Hurlevent. Sa famille est réputée pour ses échanges équitables, et il cherche des voyageurs pour porter des nouvelles à son frère Gorbold, de l’autre côté de la mer.",al={"borgus steelhand","qui confie la mission business in auberdine","borgus"}},{q="Où se trouve Gorbold Main-d'acier ?",a="Gorbold Main-d'acier se trouve à Auberdine, le principal port de Sombrivage, sur la côte nord-ouest de Kalimdor. Il travaille à un étal marchand qui sert les navires à leur arrivée.",al={"où se trouve gorbold","trouver gorbold main-d'acier","emplacement de gorbold"}},{q="Comment rejoindre Auberdine depuis Hurlevent ?",a="Un navire part du quai le plus au sud du Port de Hurlevent et traverse La Grande mer jusqu’aux docks d’Auberdine, à Sombrivage.",al={"bateau pour auberdine","comment rejoindre sombrivage depuis hurlevent","bateau de hurlevent à auberdine"}},{q="Pourquoi Borgus s’inquiète-t-il pour son frère ?",a="Gorbold est parti il y a des semaines pour travailler à un étal marchand d’Auberdine, espérant faire des bénéfices en ravitaillant les navires. Il n’a donné aucune nouvelle, alors Borgus demande aux voyageurs de se renseigner sur son sort.",al={"pourquoi prendre des nouvelles de gorbold","qu'est-il arrivé à gorbold"}},{q="Quel genre de village est Auberdine ?",a="Auberdine est un village côtier de Sombrivage, construit et principalement habité par des Elfes de la nuit. C’est le principal centre maritime de l’Alliance et le point de traversée entre le nord de Kalimdor et Teldrassil.",al={"qu'est-ce qu'auberdine","village d'auberdine"}},{q="Pour quoi la famille Steelhand est-elle réputée ?",a="La famille Steelhand est réputée pour le commerce et affirme proposer des accords équitables aux voyageurs et aux dockers.",al={"famille steelhand","les steelhand"}}},fp="21,164,21.234.0,18.230.0,24.166.0,35.156.0,42.116.0,40.175.0,37.190.0,39.100.0"}
P.entries["quest:97899"] = {n="Camping 101: Alchemy",s="Un alchimiste à Orgrimmar peut apprendre à fabriquer un Puits de mana pour un campement. Il offre aux soigneurs et aux lanceurs de sorts une boisson rafraîchissante, tandis que son installation nécessite un feu de camp.",h="Un alchimiste à Orgrimmar peut apprendre à fabriquer un Puits de mana pour un campement.",kw={"alchimiste","alchimie","feu de camp","camping","soigneurs","puits de mana","orgrimmar","lanceurs de sorts","whuut"},sec={{t="Un puits pour le campement",b="Quelqu’un à Orgrimmar vous demande de parler à Whuut une fois que vous aurez fait vos preuves en alchimie. Whuut peut vous apprendre à fabriquer un Puits de mana, un objet de camping qui attire les soigneurs et les lanceurs de sorts en quête de rafraîchissement. Pour établir un campement en pleine nature, il vous faut aussi un feu de camp. Un maître des cuisiniers peut vous apprendre à en faire un."}},faq={{q="Qui peut m’apprendre à fabriquer un Puits de mana ?",a="Whuut, à Orgrimmar, peut vous apprendre à fabriquer un Puits de mana une fois que vous aurez fait vos preuves en alchimie.",al={"maître puits de mana","whuut alchimie","qui est whuut"}},{q="À quoi sert un Puits de mana ?",a="Un Puits de mana est un objet de camping qui offre aux soigneurs et aux lanceurs de sorts une gorgée rafraîchissante.",al={"utilisation puits de mana","qu’est-ce qu’un puits de mana","campement mana"}},{q="Puis-je établir un campement en ville ?",a="La plupart des gens n’apprécient guère les campements en plein centre-ville, alors le texte de fin vous invite à essayer votre Puits de mana en pleine nature.",al={"campement à orgrimmar","puits de mana en ville","camping en ville"}},{q="De quoi d’autre ai-je besoin pour un campement ?",a="Un feu de camp est nécessaire pour établir un campement. Un maître des cuisiniers peut vous apprendre à en faire un.",al={"feu de camp nécessaire","installation du campement","feu pour campement"}}},fp="20,165,15.310.0,37.97.0,25.89.0,26.146.0,31.89.0"}
P.entries["quest:97900"] = {n="Camping 101: Blacksmithing",s="À Tranchecolline, Dwukk vous enseigne un artisanat de camp adapté à votre compétence en forge. Une Meule à aiguiser permet aux combattants proches d’aiguiser leurs armes.",h="À Tranchecolline, Dwukk vous enseigne un artisanat de camp adapté à votre compétence en forge.",kw={"forge","feu de camp","campement","dwukk","tranchecolline","voleurs","meule à aiguiser","armes"},ang={["class:Rogue"]="En tant que Voleur, vous pouvez aiguiser vos armes avec une Meule à aiguiser installée dans un campement proche.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez apprendre auprès de Dwukk à fabriquer une Meule à aiguiser pour un campement sauvage."},sec={{t="Un artisanat de camp",b="Dwukk vous apprend à fabriquer une Meule à aiguiser dès que vous démontrez vos compétences en forge. Installez-la dans un campement sauvage, où les combattants et les Voleurs proches peuvent aiguiser leurs armes.\n\nVous avez besoin d’un feu de camp pour établir votre campement. Les cuisiniers peuvent vous apprendre à en faire un."}},faq={{q="Qui m’apprend à fabriquer une Meule à aiguiser ?",a="Dwukk, à Tranchecolline, vous apprend à fabriquer une Meule à aiguiser dès que vous démontrez vos compétences en forge.",al={"maître de la meule à aiguiser","dwukk forge","qui enseigne le camping et la forge"}},{q="À quoi sert la Meule à aiguiser ?",a="Les combattants et les Voleurs proches peuvent aiguiser leurs armes avec une Meule à aiguiser installée dans votre campement.",al={"utilisation de la meule à aiguiser","à quoi sert la meule","aiguiser les armes au campement"}},{q="Où puis-je essayer mon campement ?",a="Essayez votre campement en pleine nature. Les campements ne doivent pas être installés au centre d’une ville.",al={"où installer un campement","lieu de campement","campement en ville"}},{q="Ai-je besoin d’un feu de camp ?",a="Oui. Vous avez besoin d’un feu de camp pour établir votre campement, et les cuisiniers peuvent vous apprendre à en faire un.",al={"feu de camp nécessaire","comment établir un campement","feu pour camper"}}},fp="26,153,12.250.0,42.97.0,34.89.0,28.86.0,21.85.0"}
P.entries["quest:97901"] = {n="Camping 101: Enchanting",s="Vous pouvez fabriquer un Luth enchanté, mais les habitants n’aiment pas les camps au cœur des villes. Pour camper en pleine nature, il vous faut un feu.",h="Vous pouvez fabriquer un Luth enchanté, mais les habitants n’aiment pas les camps au cœur des villes.",kw={"feu de camp","camping","cuisine","luth enchanté","feu","pleine nature"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre aux autres à allumer un feu, point de départ d’un camp."},sec={{t="Un feu de camp d’abord",b="Un feu de camp est le point de départ de votre camp. La plupart des cuisiniers peuvent vous apprendre à en allumer un. Si vous n’en connaissez pas encore les bases, adressez-vous à un maître cuisinier."}},faq={{q="Que puis-je fabriquer ?",a="Vous pouvez fabriquer un Luth enchanté.",al={"luth enchanté","fabriquer un luth","luth de camping"}},{q="Où puis-je l’essayer ?",a="Vous devez partir en pleine nature pour l’essayer. La plupart des gens n’aiment pas les camps au cœur des villes.",al={"où camper","lieu de camping","essayer le luth"}},{q="Pourquoi me faut-il un feu de camp ?",a="Votre camp commence par un feu de camp.",al={"besoin d’un feu de camp","feu de camp","feu pour camper"}},{q="Qui peut m’apprendre à allumer un feu ?",a="La plupart des cuisiniers peuvent vous apprendre à allumer un feu. Adressez-vous à un maître cuisinier si vous n’en connaissez pas encore les bases.",al={"apprendre à allumer un feu","maître cuisinier","faire un feu de camp"}}},fp="23,127,16.148.0,17.32.0,23.93.0,25.33.0,32.98.0"}
P.entries["quest:97902"] = {n="Camping 101: Engineering",s="Un maître vous oriente vers Mukdrak, à Tranchecolline, qui peut vous apprendre à fabriquer un Robot vendeur de composants après avoir constaté votre maîtrise de l’ingénierie. Ce robot aide à approvisionner un camp en composants de sorts.",h="Un maître vous oriente vers Mukdrak, à Tranchecolline, qui peut vous apprendre à fabriquer un Robot vendeur...",kw={"camp","feu de camp","initiation au camping","ingénierie","mukdrak","tranchecolline","robot vendeur de composants"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous pouvez apprendre à fabriquer un Robot vendeur de composants pour votre camp après avoir démontré votre maîtrise du métier."},sec={{t="Un robot pour le camp",b="Un ingénieur peut apprendre à fabriquer un Robot vendeur de composants auprès de Mukdrak, à Tranchecolline, après avoir démontré sa maîtrise du métier. Cet automate vous aide, vous et vos alliés, à rester approvisionnés en composants de sorts. Pour l’essayer au camp, rendez-vous dans la nature ; les habitants n’apprécient pas les camps installés en plein centre-ville."},{t="Préparer le feu",b="Un feu de camp est également nécessaire avant de pouvoir installer un camp. La plupart des cuisiniers peuvent vous apprendre à en allumer un, alors cherchez un maître des cuisiniers si vous avez besoin des bases."}},faq={{q="Qui peut m’apprendre à fabriquer un Robot vendeur de composants ?",a="Mukdrak, à Tranchecolline, peut vous apprendre à fabriquer un Robot vendeur de composants après avoir constaté votre maîtrise de l’ingénierie.",al={"mukdrak robot","qui enseigne le robot vendeur de composants","maître robot vendeur de composants"}},{q="À quoi sert le Robot vendeur de composants ?",a="Le Robot vendeur de composants vous aide, vous et vos alliés, à rester approvisionnés en composants de sorts.",al={"à quoi sert le robot","utilité du robot vendeur de composants","robot pour le camp"}},{q="Où installer mon camp ?",a="Le texte de fin conseille de se rendre dans la nature pour essayer le robot, car la plupart des gens n’apprécient pas les camps installés en plein centre-ville.",al={"où camper","lieu de campement","où essayer le robot"}},{q="De quoi d’autre ai-je besoin avant d’installer un camp ?",a="Vous avez besoin d’un feu de camp avant d’installer votre camp. La plupart des cuisiniers peuvent vous apprendre à en allumer un.",al={"feu de camp nécessaire","installation du camp","feu pour le camp"}},{q="Qui peut m’apprendre les bases pour allumer un feu de camp ?",a="Un maître des cuisiniers peut vous apprendre les bases pour allumer un feu de camp.",al={"maître feu de camp","apprendre à allumer un feu","feu de cuisine"}}},fp="24,189,14.300.0,14.164.0,37.101.0,29.91.0,30.131.0,43.84.0,49.71.0"}
P.entries["quest:97903"] = {n="Camping 101: First Aid",s="Au camp de Rawrk, à Tranchecolline, les voyageurs expérimentés apprennent à fabriquer une Trousse de premiers soins pour les régions sauvages. La leçon explique où camper et pourquoi un feu est important.",h="Au camp de Rawrk, à Tranchecolline, les voyageurs expérimentés apprennent à fabriquer une Trousse de premiers...",kw={"feu de camp","camping 101","durotar","trousse de premiers soins","rawrk","tranchecolline","survie","camp en pleine nature"},ang={["faction:Horde"]="En tant que voyageur de la Horde, vous pouvez suivre cette formation à Tranchecolline, en Durotar, pour subvenir à vos besoins dans les régions frontalières accidentées de Kalimdor.",["profession:Cooking"]="Avec vos connaissances en Cooking, vous savez que les techniques de campement nécessitent un feu. Rawrk dit qu’un bon camp exige de savoir allumer un feu, une compétence enseignée par les maîtres de cuisine."},sec={{t="Survie à la frontière",b="À Tranchecolline, Rawrk apprend aux voyageurs expérimentés à fabriquer une Trousse de premiers soins. Elle vous permet de soigner les blessures loin d’un apothicaire ou d’une infirmerie, là où l’aide peut être difficile à trouver."},{t="L'art du feu de camp",b="Rawrk vous déconseille de planter une tente au milieu de Tranchecolline ou d’une autre localité. Trouvez plutôt un endroit dégagé dans la nature. Un camp a aussi besoin d’un feu pour vous permettre de passer la nuit. Apprenez les rudiments de l’allumage d’un feu auprès d’un maître de cuisine avant de partir."}},faq={{q="Qui est Rawrk et où se trouve-t-il ?",a="Rawrk enseigne les techniques de campement et de survie à Tranchecolline, en Durotar. Il montre aux voyageurs expérimentés comment fabriquer des Trousses de premiers soins pour les régions sauvages.",al={"qui enseigne les premiers soins de camping","où se trouve rawrk","maître de camping 101"}},{q="Que faut-il avant d'établir un camp dans la nature ?",a="Choisissez un endroit dégagé dans la nature et allumez un bon feu de camp. Rawrk déconseille de camper dans les limites d’une ville et vous recommande d’apprendre d’abord à allumer un feu auprès d’un maître de cuisine.",al={"de quoi ai-je besoin pour camper","comment établir un camp","feu de camp requis pour camper"}},{q="Les camps peuvent-ils être installés dans des villes ou des colonies ?",a="Non. Les habitants s’opposent aux tentes au milieu des localités, alors trouvez un endroit dégagé dans la nature pour établir votre camp.",al={"puis-je camper à tranchecolline","camper dans les villes","où puis-je installer mon camp"}},{q="Qu'est-ce que cet entraînement enseigne aux aventuriers à fabriquer ?",a="Cette formation vous apprend à fabriquer une Trousse de premiers soins personnelle pour soigner les blessures lors de vos voyages dans les régions sauvages.",al={"récompense de camping 101: first aid","quel objet cela apprend-il à fabriquer","fabrication de trousse de premiers soins"}},{q="Pourquoi Rawrk recommande-t-il d'apprendre la cuisine ?",a="Un bon camp a besoin d’un feu. Les maîtres de cuisine enseignent les rudiments de l’allumage d’un feu, aussi Rawrk recommande-t-il d’apprendre auprès de l’un d’eux avant de partir.",al={"pourquoi apprendre la cuisine pour camper","cuisine feu de camp camping"}},{q="Quels prérequis sont nécessaires avant d'apprendre cet artisanat ?",a="Vous devez montrer des compétences élémentaires en soins et en survie avant que Rawrk vous apprenne à fabriquer une Trousse de premiers soins de terrain.",al={"prérequis pour camping 101: first aid","compétence requise pour premiers soins de camping"}}},fp="22,154,24.169.0,23.254.0,35.130.0,53.177.0,49.108.0,51.100.0,42.129.0,57.121.0"}
P.entries["quest:97904"] = {n="Camping 101: Fishing",s="Dans votre camp, la pêche peut vous réconforter, vous et vos compagnons. Près du Village de Sen'jin, Lau'Tiki peut vous apprendre à fabriquer un Bocal à poisson.",h="Dans votre camp, la pêche peut vous réconforter, vous et vos compagnons.",kw={"équipement de camp","campement","bocal à poisson","pêcheur","pêche","lau'tiki","village de sen'jin"},ang={["profession:Cooking"]="En tant que pêcheur, vous pouvez apprendre à fabriquer un Bocal à poisson pour votre camp quand vous aurez fait vos preuves en pêche."},sec={{t="Un réconfort au camp",b="Quand vous aurez fait vos preuves en pêche, parlez à Lau'Tiki près du Village de Sen'jin. Lau'Tiki peut vous apprendre à fabriquer un Bocal à poisson, un équipement de camp destiné à vous réjouir, vous et vos compagnons d'aventure. Selon la personne qui l'offre, un camp plus heureux donne des combattants plus forts."}},faq={{q="À quoi la pêche peut-elle servir à mon camp ?",a="Votre compétence en pêche peut vous aider à apprendre à fabriquer un Bocal à poisson pour votre camp.",al={"objet de camp de pêche","pêche au camp"}},{q="Qui peut m'apprendre à fabriquer un Bocal à poisson ?",a="Lau'Tiki, près du Village de Sen'jin, peut vous apprendre à fabriquer un Bocal à poisson quand vous aurez fait vos preuves en pêche.",al={"maître du bocal à poisson","lau'tiki pêche"}},{q="À quoi sert le Bocal à poisson ?",a="Le Bocal à poisson est un équipement de camp destiné à réjouir vos compagnons d'aventure et vous-même.",al={"utilité du bocal à poisson","équipement de camp pour poissons"}},{q="Où puis-je trouver Lau'Tiki ?",a="Lau'Tiki se trouve près du Village de Sen'jin.",al={"emplacement de lau'tiki","pêche à sen'jin"}}},fp="20,133,14.259.0,32.72.0,35.101.0,26.89.0,26.33.0"}
P.entries["quest:97905"] = {n="Camping 101: Herbalism",s="Dans Camping 101: Herbalism, vous apprenez à fabriquer des bougies d’encens à partir de plantes sauvages. Mais un vrai campement a d’abord besoin d’un feu, et le vôtre doit se trouver dans la nature, loin des villes.",h="Dans Camping 101: Herbalism, vous apprenez à fabriquer des bougies d’encens à partir de plantes sauvages.",kw={"campement","feu de camp","camping","cuisine","herboristerie","bougie d’encens","nature"},ang={["profession:Cooking"]="En tant que cuisinier, vous apprenez à allumer le feu de camp qui se trouve au cœur de chaque campement.",["profession:Herbalism"]="En tant qu’herboriste, vous apprenez à fabriquer des bougies d’encens à partir de plantes récoltées, pour les utiliser dans les campements en pleine nature."},sec={{t="L’art des parfums sauvages",b="L’herboristerie vous permet de transformer les plantes récoltées en bougies d’encens qui apportent du réconfort sur les sentiers. Les citadins voient d’un mauvais œil les tentes dans les rues, alors ces bougies sont destinées aux campements hors des colonies gardées."},{t="Au cœur du campement",b="Un feu de camp est au cœur de tout campement. Allumez-en un avant d’utiliser une bougie d’encens. Les herboristes fournissent les parfums, tandis que les maîtres cuisiniers du monde entier enseignent aux voyageurs les bases de l’allumage d’un feu."}},faq={{q="Qu’est-ce qu’une bougie d’encens ?",a="Les herboristes fabriquent des bougies d’encens à partir de plantes sauvages. Faites-en brûler une dans un campement en pleine nature, près d’un feu de camp.",al={"qu’est-ce qu’une bougie d’encens","utilisation d’une bougie d’encens","objet de camping en herboristerie"}},{q="Où pouvez-vous installer un campement ?",a="Vous pouvez installer un campement dans la nature. Les citadins s’opposent aux tentes qui encombrent les rues de la ville.",al={"où installer un campement","peut-on camper en ville","camping en ville"}},{q="Pourquoi faut-il un feu de camp pour installer un campement ?",a="Un campement a besoin d’un feu de camp en son cœur. Les maîtres cuisiniers d’Azeroth enseignent les techniques de base pour allumer un feu.",al={"comment allumer un feu de camp","feu de camp nécessaire pour camper","feu de camp et cuisine"}},{q="Qui apprend à allumer un feu de camp ?",a="Les maîtres cuisiniers vous apprennent à allumer un simple feu de camp. Apprenez les bases de la cuisine avant de partir dans la nature.",al={"qui apprend à allumer un feu de camp","apprendre à allumer un feu","feu et maître cuisinier"}},{q="Quel est le lien entre l’herboristerie et le camping ?",a="L’herboristerie fournit les plantes et les résines nécessaires aux bougies d’encens. Récoltées dans la nature, elles diffusent des parfums apaisants dans votre campement.",al={"lien entre herboristerie et camping","herboristerie et camping","apport de l’herboristerie aux campements"}},{q="Faut-il un feu de camp pour utiliser une bougie d’encens ?",a="Un campement a besoin d’un vrai feu de camp. Allumez-en un avant de vous installer pour utiliser une bougie d’encens.",al={"peut-on allumer une bougie d’encens sans feu","feu de camp requis pour une bougie d’encens"}}},fp="22,177,26.201.0,25.216.0,26.103.0,28.103.0,44.107.0,35.114.0,36.131.0,48.86.0"}
P.entries["quest:97906"] = {n="Camping 101: Leatherworking",s="À Orgrimmar, Karolek peut vous apprendre à fabriquer une tente de travailleur du cuir une fois votre savoir-faire démontré. Une tente vous abrite lors de vos voyages, mais établir un camp demande aussi un feu de camp.",h="À Orgrimmar, Karolek peut vous apprendre à fabriquer une tente de travailleur du cuir une fois votre...",kw={"feu de camp","bases du camping","objet de camping","cuisine","karolek","travail du cuir","orgrimmar","tente"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre à faire le feu de camp nécessaire pour compléter un campement."},sec={{t="Un endroit où camper",b="Un travailleur du cuir d’Orgrimmar vous oriente vers Karolek, qui peut vous apprendre à fabriquer une tente pour vos voyages. Elle vous offre de l’ombre par temps chaud et vous abrite de la pluie, vous donnant un endroit où vous reposer en chemin. Une fois votre maîtrise du travail du cuir démontrée, Karolek peut vous apprendre à fabriquer cet objet de camping."},{t="D’abord, un feu de camp",b="Votre tente est prête, mais un feu de camp complète le campement. Les cuisiniers peuvent vous apprendre à en faire un, et un maître des cuisiniers peut vous enseigner les bases. Pour essayer votre tente, quittez le centre-ville et installez-la en pleine nature."}},faq={{q="Qui peut m’apprendre à fabriquer une tente de travailleur du cuir ?",a="Karolek, à Orgrimmar, peut vous apprendre à fabriquer une tente une fois votre maîtrise du travail du cuir démontrée.",al={"maître de fabrication de tentes","qui enseigne la fabrication de tentes en travail du cuir","tente de karolek"}},{q="À quoi sert la tente ?",a="La tente vous abrite de la pluie, vous offre de l’ombre par temps chaud et un endroit où vous reposer lors de vos voyages.",al={"à quoi sert la tente","objet de camping en travail du cuir","utilisation de la tente"}},{q="Puis-je installer ma tente en ville ?",a="Le texte de fin indique que la plupart des gens n’apprécient pas les tentes installées en centre-ville, il faut donc l’essayer en pleine nature.",al={"tente en ville","où camper","lieu de campement"}},{q="De quoi d’autre ai-je besoin pour établir un camp ?",a="Il vous faut un feu de camp en plus d’une tente. Les cuisiniers peuvent vous apprendre à faire du feu.",al={"besoin d’un feu de camp","comment faire un feu de camp","ce qui complète un campement"}},{q="Qui peut m’enseigner les bases de la cuisine ?",a="Une personne qui forme les cuisiniers peut vous enseigner les bases des arts culinaires.",al={"maître des cuisiniers","apprendre les arts culinaires","maître du feu de camp"}}},fp="27,201,15.299.0,14.210.0,50.96.0,22.103.0,29.141.0,36.74.0,39.71.0"}
P.entries["quest:97907"] = {n="Camping 101: Mining",s="En Durotar, les mineurs chevronnés peuvent apprendre à forger une magnétite pour les camps en pleine nature. Krunn enseigne cet art à Tranchecolline.",h="En Durotar, les mineurs chevronnés peuvent apprendre à forger une magnétite pour les camps en pleine nature.",kw={"campement","feu de camp","camping 101: mining","cuisine","durotar","krunn","magnétite","minage","tranchecolline"},ang={["faction:Horde"]="En tant que mineur de la Horde qui voyage en Durotar, vous pouvez rendre visite à Krunn à Tranchecolline pour apprendre à fabriquer des magnétites pour vos expéditions.",["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre auprès d'instructeurs de cuisine à allumer le feu de camp basique qui se trouve au cœur d'un campement en pleine nature.",["profession:Mining"]="En tant que mineur, vous pouvez extraire des minerais bruts et fabriquer de l'équipement de terrain comme une magnétite pour soutenir vos alliés au campement."},sec={{t="Le camp du mineur",b="Le minage fournit des matériaux utiles aux voyages et à la survie en pleine nature. En maîtrisant la pioche et le minerai, vous pouvez apprendre à fabriquer de l'équipement de campement. En Durotar, Krunn, à Tranchecolline, apprend aux mineurs chevronnés à forger une magnétite pour leurs voyages."},{t="La camaraderie autour du feu",b="Dans un camp en pleine nature, une magnétite donne plus de force au combat aux combattants rassemblés. Placez-la près du feu de camp pour que les combattants martiaux autour des flammes prennent l'avantage. Les citadins voient d'un mauvais œil les tentes dressées sur les places, alors il vous faut partir en pleine nature pour mettre votre savoir-faire à profit."},{t="Feu et savoir-faire en pleine nature",b="Une magnétite solide a besoin d'un feu au cœur du camp. Vous devez allumer un feu de camp basique avant d'aménager un lieu de repos. Si vous ne savez pas en faire, cherchez un instructeur de cuisine. La cuisine enseigne les bases pour se réchauffer et se nourrir lors d'expéditions loin des murs de la ville."}},faq={{q="Qu'est-ce que Camping 101: Mining ?",a="Les mineurs chevronnés peuvent aller voir Krunn à Tranchecolline pour apprendre à fabriquer une magnétite pour un campement.",al={"qu'est-ce que camping 101: mining","quête de minage et de campement","quête de magnétite en minage"}},{q="Qui est Krunn ?",a="Krunn forme les mineurs chevronnés à Tranchecolline, en Durotar. Quand ils ont acquis suffisamment de savoir-faire, il leur apprend à fabriquer des objets de campement comme la magnétite.",al={"qui est krunn","où se trouve krunn","instructeur à tranchecolline"}},{q="À quoi sert une magnétite ?",a="Les mineurs fabriquent des magnétites à placer près d'un feu de camp en pleine nature. Les combattants au corps à corps rassemblés autour gagnent en force martiale.",al={"à quoi sert une magnétite","avantage de la magnétite","pourquoi fabriquer une magnétite"}},{q="Peut-on installer son camp à Tranchecolline ?",a="Non. Les citadins et les autorités des colonies voient d'un mauvais œil les campements dans les rues peuplées. Partez dans la nature environnante pour dresser votre camp et placer votre magnétite.",al={"peut-on camper en ville","pourquoi ne puis-je pas camper à tranchecolline","campement dans les villes"}},{q="Pourquoi faut-il un feu de camp avant d'installer son campement ?",a="Un feu de camp est au cœur d'un campement fonctionnel. Les instructeurs de cuisine vous apprennent à allumer un feu basique, et la cuisine vous prépare aux campements en pleine nature.",al={"faut-il un feu de camp","comment installer son campement","feu requis pour camper"}},{q="Qui peut apprendre à fabriquer une magnétite ?",a="Les mineurs qui ont acquis suffisamment de savoir-faire peuvent apprendre à fabriquer une magnétite auprès de Krunn, à Tranchecolline.",al={"qui peut fabriquer des magnétites","tout le monde peut-il fabriquer une magnétite"}}},fp="19,119,16.226.0,20.272.0,19.265.0,28.90.0,13.141.0,29.129.0,38.154.0,50.156.0,35.85.0"}
P.entries["quest:97908"] = {n="Camping 101: Skinning",s="À Orgrimmar, les nouveaux dépeceurs sont envoyés auprès de Thuwd pour apprendre l'art du camping. Vous fabriquez une Chaise du camp avec des peaux et des fourrures, puis l'emportez loin de la ville, en pleine nature.",h="À Orgrimmar, les nouveaux dépeceurs sont envoyés auprès de Thuwd pour apprendre l'art du camping.",kw={"chaise du camp","feu de camp","camping","camping 101: skinning","orgrimmar","dépeçage","thuwd"},ang={["faction:Horde"]="Thuwd forme les dépeceurs à Orgrimmar. Les aventuriers de la Horde venus de Durotar peuvent donc y apprendre cet art de la vie sauvage.",["profession:Cooking"]="Un vrai campement a besoin d'un siège et de chaleur. Si vous débutez en dépeçage, vous êtes encouragé à étudier les bases de la cuisine et à apprendre à allumer un feu de camp."},sec={{t="Confort en pleine nature",b="À Orgrimmar, Thuwd apprend aux dépeceurs compétents à fabriquer une Chaise du camp avec des peaux tannées. Les fourrures et les peaux des bêtes abattues peuvent servir à autre chose qu'à confectionner des armures. Un dépeceur peut les utiliser en pleine nature."},{t="Règles de la piste",b="Thuwd prévient que les gardes et les citadins désapprouvent les campements le long des rues animées. Une chaise a sa place en pleine nature, loin des murs des colonies. Un vrai campement a aussi besoin d'un feu de camp chaleureux. Les cuisiniers de Kalimdor en enseignent les bases."}},faq={{q="Qui apprend aux dépeceurs à fabriquer des objets de campement ?",a="À Orgrimmar, Thuwd apprend aux dépeceurs à fabriquer des objets de campement. Ils lui parlent après avoir démontré une maîtrise élémentaire de leur métier.",al={"qui donne camping 101 dépeçage","à qui parler à orgrimmar","qui est thuwd"}},{q="Quel objet de campement les dépeceurs peuvent-ils fabriquer ?",a="Les dépeceurs peuvent fabriquer une Chaise du camp avec les peaux et les fourrures des bêtes abattues. Elle leur offre un siège confortable pour se reposer en pleine nature.",al={"que fabriquent les dépeceurs pour camper","artisanat de camping en dépeçage","chaise de camp en dépeçage"}},{q="Peut-on installer une chaise de camp dans une ville ?",a="Les citadins et les gardes désapprouvent le matériel de campement en ville. Franchissez les portes de la colonie et gagnez la nature pour établir votre camp et installer votre chaise.",al={"peut-on camper à orgrimmar","campements en ville","où établir son camp"}},{q="Que faut-il d'autre pour compléter un campement ?",a="Un vrai campement a besoin d'un feu pour se réchauffer, y voir clair et cuisiner. Avant d'établir votre camp, demandez à un maître cuisinier comment allumer un simple feu de camp.",al={"pourquoi faut-il un feu de camp","conditions pour camper","comment établir un camp"}},{q="Pourquoi un aventurier devrait-il fabriquer une chaise de camp ?",a="Une chaise confortable vous permet de vous reposer entre deux chasses et de récupérer après la route avant votre prochaine escarmouche.",al={"avantage du dépeçage pour camper","pourquoi se reposer sur une chaise de camp","avantages de la chaise de camp"}},{q="Quand Thuwd enseigne-t-il le patron de la Chaise du camp ?",a="Thuwd transmet le patron de la Chaise du camp aux dépeceurs qui ont démontré leur maîtrise élémentaire du prélèvement des peaux sur les bêtes abattues.",al={"quand apprendre à fabriquer une chaise de camp","conditions de camping 101","niveau de dépeçage requis"}}},fp="21,166,19.192.0,18.238.0,44.126.0,37.131.0,42.151.0,41.144.0,44.112.0,45.118.0"}
P.entries["quest:97914"] = {n="Expanding Horizons",s="Thundris Windweaver écrit depuis Auberdine à Hurlevent. Il veut faire connaître le travail de la colonie au-delà de Sombrivage.",h="Thundris Windweaver écrit depuis Auberdine à Hurlevent.",kw={"ameth'aran","auberdine","baros alexston","bashal'aran","sombrivage","darnassus","expanding horizons","port","hurlevent","thundris windweaver"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous voyez le travail nécessaire pour unir des peuples de deux continents au sein d’une même faction.",["race:Human"]="En tant qu’humain, vous voyez le royaume reconstruit étendre son influence lorsque vous rentrez à Hurlevent avec le sceau d’une colonie kaldorei.",["race:NightElf"]="Pour les kaldorei, ouvrir des routes maritimes vers les Royaumes de l'est met fin à dix mille ans d’isolement et lie votre peuple à la civilisation humaine."},sec={{t="Relier deux hémisphères",b="La traversée maritime d’Auberdine relie désormais directement Sombrivage à Hurlevent. Ses dirigeants veulent sécuriser cette route commerciale et rattacher la colonie côtière au reste de l’Alliance. Tout près, les villes en ruine d’Ameth'Aran et de Bashal'Aran attirent depuis longtemps plus l’attention qu’Auberdine et ses habitants."},{t="Un message pour l’architecte de la ville",b="Baros Alexston supervise la construction et les infrastructures de Hurlevent. Ses fonctions couvrent les travaux publics et la logistique. La lettre de Thundris Windweaver traverse La Grande mer jusqu’au responsable des besoins en construction de la capitale humaine."}},faq={{q="Qui vous confie cette quête ?",a="Thundris Windweaver, un Elfe de la nuit influent d’Auberdine, vous demande de porter sa lettre. Il estime que Darnassus et les alliés d’outre-mer négligent la colonie, et cherche à établir un lien officiel avec le royaume humain.",al={"donneur de quête expanding horizons","qui donne expanding horizons","quête de thundris"}},{q="Qui est Baros Alexston ?",a="Baros Alexston est l’architecte de la ville de Hurlevent. Urbaniste respecté, il a connu Edwin VanCleef dans sa jeunesse. Il supervise la construction et l’administration des bâtiments dans toute la capitale.",al={"histoire de baros alexston","qui est baros","architecte de la ville de hurlevent"}},{q="Pourquoi Auberdine se tourne-t-elle vers Hurlevent ?",a="Auberdine veut faire connaître son port comme une porte d’entrée pour le ravitaillement, le commerce et les voyages de l’Alliance. Ses dirigeants espèrent que les nouvelles routes maritimes entre Sombrivage et les Royaumes de l'est renforceront les liens économiques et logistiques avec le royaume humain.",al={"pourquoi envoyer une lettre à hurlevent","liaison entre auberdine et hurlevent","pourquoi contacter les humains"}},{q="Comment se rendre d’Auberdine à Hurlevent ?",a="Un navire relie désormais Auberdine à Port de Hurlevent en traversant La Grande mer. Il apporte du ravitaillement et de l’animation aux rivages d’Auberdine.",al={"bateau pour hurlevent","comment aller à hurlevent depuis auberdine"}},{q="Que sont Ameth'Aran et Bashal'Aran ?",a="Ameth'Aran et Bashal'Aran étaient de prospères cités des Bien-nés dans l’ancien Sombrivage. Le Grand Fracassement a brisé le continent il y a dix mille ans. Aujourd’hui, ces cités sont des ruines hantées, plus marquantes dans l’histoire kaldorei que des villages vivants comme Auberdine.",al={"histoire d’ameth'aran","bashal'aran","anciennes cités de sombrivage"}},{q="Pourquoi remettre cette lettre à un architecte plutôt qu’au roi Anduin ou à Bolvar ?",a="Thundris Windweaver n’explique pas son choix. Il vous demande de remettre la lettre à Baros Alexston, l’architecte de la ville de Hurlevent, pour que le travail d’Auberdine soit reconnu.",al={"pourquoi baros alexston","pourquoi pas bolvar","pourquoi pas le grand seigneur bolvar"}}},fp="18,127,24.291.0,31.231.0,28.209.0,22.198.0,43.238.0,53.126.0,36.258.0,66.168.0"}
P.entries["quest:97915"] = {n="Camping 101: Alchemy",s="Un alchimiste peut apprendre à fabriquer un Puits de mana auprès d’Alchemist Mallory, près de Hurlevent. Il offre aux soigneurs et aux lanceurs de sorts une gorgée rafraîchissante au camp.",h="Un alchimiste peut apprendre à fabriquer un Puits de mana auprès d’Alchemist Mallory, près de Hurlevent.",kw={"alchimiste","alchemist mallory","alchimie","camp","feu de camp","camping","forêt d’elwynn","soigneurs","puits de mana","lanceurs de sorts","hurlevent"},sec={{t="Un camp pour les potions",b="Un alchimiste peut demander à Alchemist Mallory, près de Hurlevent, dans la Forêt d’Elwynn, de lui enseigner une technique de camping. Vous devez faire preuve de maîtrise dans votre métier avant d’apprendre à fabriquer un Puits de mana. Les soigneurs et les lanceurs de sorts peuvent venir au camp pour boire une gorgée rafraîchissante."},{t="Installer le camp",b="Une fois cette technique apprise, vous pouvez fabriquer votre propre Puits de mana. Les camps ont leur place en pleine nature, et un feu de camp est nécessaire avant d’en installer un. Une personne qui forme les cuisiniers peut vous enseigner les bases pour faire du feu."}},faq={{q="Qui apprend aux alchimistes à fabriquer un Puits de mana ?",a="Alchemist Mallory enseigne cette technique près de Hurlevent, dans la Forêt d’Elwynn, une fois que vous avez fait preuve de maîtrise dans votre métier.",al={"maître puits de mana","technique de camping alchimie","mallory alchimie"}},{q="À quoi sert un Puits de mana ?",a="Un Puits de mana offre aux soigneurs et aux lanceurs de sorts une gorgée rafraîchissante au camp.",al={"utilisation puits de mana","à quoi sert un puits de mana","objet de camp alchimie"}},{q="Où trouver Alchemist Mallory ?",a="Alchemist Mallory se trouve près de Hurlevent, dans la Forêt d’Elwynn.",al={"emplacement mallory","où est mallory","maître alchimie elwynn"}},{q="De quoi ai-je besoin avant d’installer un camp ?",a="Vous avez besoin d’un feu de camp avant d’installer votre camp. Une personne qui forme les cuisiniers peut vous apprendre à faire du feu.",al={"feu de camp nécessaire","comment installer un camp","bases du camping"}},{q="Où essayer mon Puits de mana ?",a="Essayez-le en pleine nature, car la plupart des gens n’apprécient pas les camps en plein centre-ville.",al={"puits de mana camping","camp en ville","où essayer un puits de mana"}}},fp="20,144,16.246.0,15.204.0,43.115.0,24.70.0,35.53.0,38.105.0,36.86.0"}
P.entries["quest:97916"] = {n="Camping 101: Blacksmithing",s="À Comté-de-l’Or, Argus le forgeron apprend aux artisans du métal chevronnés à se préparer au travail en pleine nature. Ils apprennent à forger une Meule à aiguiser portative et à installer un campement en pleine campagne avec un bon feu.",h="À Comté-de-l’Or, Argus le forgeron apprend aux artisans du métal chevronnés à se préparer au travail en...",kw={"forge","feu de camp","camping","camping 101","forêt d’elwynn","comté-de-l’or","meule à aiguiser","argus le forgeron"},ang={["faction:Alliance"]="Les artisans de l’Alliance qui débutent à Comté-de-l’Or peuvent demander à Argus le forgeron comment se préparer aux longs voyages au-delà de la ville.",["profession:Blacksmithing"]="Les forgerons qui apprennent leur métier dans la Forêt d’Elwynn peuvent forger une Meule à aiguiser pour entretenir leur équipement et aiguiser leurs lames sur le terrain.",["profession:Cooking"]="Un bon campement a besoin d’un feu fiable. Une formation de base en cuisine complète donc bien l’apprentissage du travail du métal en pleine nature."},sec={{t="Forger pour la route",b="Argus le forgeron de Comté-de-l’Or montre aux artisans du métal chevronnés comment exercer leur métier au-delà des enclumes de la ville. Ceux qui ont le niveau requis peuvent apprendre à forger une Meule à aiguiser pour garder leurs lames bien tranchantes lors de longs voyages."},{t="La vie en pleine nature",b="Du matériel de terrain ne suffit pas à faire un bon campement. Les habitants de Comté-de-l’Or voient d’un mauvais œil les campements dans les localités, alors les artisans doivent rejoindre les grands espaces pour utiliser leur équipement. Un campement en pleine nature a aussi besoin d’un feu bien chaud. Rendez visite à un cuisinier local pour apprendre les bases nécessaires à l’allumer."}},faq={{q="Qu’est-ce que Camping 101: Blacksmithing ?",a="Argus le forgeron apprend aux forgerons expérimentés à forger une Meule à aiguiser portative pour l’utiliser en pleine nature.",al={"à quoi sert cette quête","objectif de camping 101: blacksmithing","qu’apprend-on"}},{q="Qui est Argus le forgeron ?",a="Argus le forgeron est le forgeron et l’instructeur de Comté-de-l’Or, dans la Forêt d’Elwynn. Il enseigne les bases du travail du métal et du camping aux forgerons prometteurs.",al={"qui est argus le forgeron","maître forgeron de comté-de-l’or","argus à comté-de-l’or"}},{q="Qu’est-ce qu’une Meule à aiguiser ?",a="Une Meule à aiguiser est un équipement de camping que les forgerons peuvent fabriquer pour aiguiser outils et armes loin des forges de la ville.",al={"qu’est-ce qu’une meule à aiguiser","meule à aiguiser de camping","équipement de camp de forgeron"}},{q="Peut-on installer son campement en ville ?",a="Les habitants voient d’un mauvais œil les campements dans les lieux habités comme Comté-de-l’Or. Les forgerons doivent rejoindre la pleine nature pour installer leur équipement.",al={"peut-on camper à comté-de-l’or","planter une tente en ville","où peut-on camper"}},{q="Pourquoi faut-il un feu de camp pour camper ?",a="Un feu de camp complète un campement en pleine nature. Les forgerons peuvent rendre visite à un maître cuisinier pour apprendre les bases nécessaires à l’allumage d’un feu avant de partir.",al={"faut-il savoir cuisiner pour camper","feu de camp pour camper","comment installer un campement"}},{q="Quand peut-on apprendre cet art du camping ?",a="Argus le forgeron enseigne cet art du camping aux forgerons suffisamment habiles.",al={"conditions de camping 101","niveau requis en forge"}}},fp="26,188,21.201.0,17.265.0,35.103.0,19.143.0,27.115.0,32.120.0,40.126.0,38.76.0"}
P.entries["quest:97917"] = {n="Camping 101: Enchanting",s="À Hurlevent, Betty Quin apprend aux enchanteurs à apporter un peu de magie au feu de camp. Grâce à un Luth enchanté, ils peuvent remonter le moral et aider les voyageurs à se reposer en chemin.",h="À Hurlevent, Betty Quin apprend aux enchanteurs à apporter un peu de magie au feu de camp.",kw={"betty quin","campement","camping 101","camping 101: enchanting","luth enchanté","enchantement","hurlevent"},ang={["faction:Alliance"]="Les enchanteurs de l’Alliance qui traversent ses terres peuvent retrouver Betty Quin à Hurlevent pour apprendre l’artisanat de campement."},sec={{t="La magie en chemin",b="Les longues routes d’Azeroth réclament plus que de l’acier et des provisions. Le confort et le moral comptent aussi dans les contrées sauvages. Les enchanteurs mettent leur savoir-faire au service du campement, transformant les heures tranquilles en musique et en repos avant la prochaine étape."},{t="À la recherche de Betty Quin",b="Betty Quin, à Hurlevent, apprend aux enchanteurs à fabriquer des objets spéciaux pour le campement. Une fois qu’ils ont fait leurs preuves en enchantement, elle peut leur apprendre à créer un Luth enchanté. Ses charmes remontent le moral autour du feu de camp."}},faq={{q="Qu’est-ce que Camping 101: Enchanting ?",a="Les enchanteurs peuvent apprendre auprès de Betty Quin, à Hurlevent, à fabriquer des fournitures magiques pour le campement. Elle enseigne à ceux qui ont perfectionné leur art.",al={"qu’est-ce que camping 101: enchanting","enchanteurs de camping 101","quête d’enchantement de campement"}},{q="Qui est Betty Quin ?",a="Betty Quin apprend aux enchanteurs chevronnés d’Hurlevent à fabriquer des objets magiques pour la route et les loisirs.",al={"qui est betty quin","betty, maître des enchanteurs à hurlevent","où se trouve betty quin"}},{q="Qu’est-ce qu’un Luth enchanté ?",a="Un Luth enchanté est un instrument magique qui fait de la musique et remonte le moral pendant les campements. Il aide les voyageurs à affronter les épreuves du chemin.",al={"à quoi sert le luth enchanté","pourquoi fabriquer un luth enchanté","utilité du luth enchanté"}},{q="Pourquoi les enchanteurs sont-ils précieux au campement ?",a="Les enchanteurs apportent la magie au campement, faisant du temps libre une occasion de se reposer, de se préparer et de profiter d’un peu de musique avant un périple difficile.",al={"pourquoi des enchanteurs au campement","utilité d’un enchanteur au campement"}},{q="Où dois-je me rendre pour accomplir cette tâche ?",a="Retrouvez Betty Quin à Hurlevent, la capitale du royaume de Hurlevent.",al={"où rendre la quête camping 101: enchanting","emplacement de betty quin"}},{q="Quelle compétence faut-il pour apprendre les recettes d’enchantement de campement ?",a="Betty Quin enseigne l’artisanat de campement aux enchanteurs qui ont fait leurs preuves, notamment la fabrication d’un Luth enchanté.",al={"conditions de camping 101: enchanting","quand apprendre à fabriquer un luth enchanté"}}},fp="23,171,18.231.0,18.216.0,32.130.0,18.106.0,26.142.0,40.118.0,36.70.0,57.125.0"}
P.entries["quest:97919"] = {n="Camping 101: First Aid",s="À l’Auberge de la Fierté du Lion, Michelle Belle vous apprend à préparer des trousses de premiers soins pour le camping. Vous devez avoir assez de compétence en premiers soins pour apprendre à préparer ces fournitures pour la route.",h="À l’Auberge de la Fierté du Lion, Michelle Belle vous apprend à préparer des trousses de premiers soins pour...",kw={"bandages","trousse de campement","introduction au camping","forêt d’elwynn","premiers soins","comté-de-l’or","michelle belle","survie"},ang={["class:Rogue"]="En tant que voleur opérant dans l’ombre, loin de toute aide, vous comptez sur la médecine de terrain pour bander vos plaies saignantes avant de passer à votre prochaine cible.",["class:Warrior"]="En tant que guerrier, vous ne disposez d’aucun sort de soins. Vous comptez donc sur les bandages et les trousses de terrain pour tenir pendant les longues campagnes dans la nature.",["faction:Alliance"]="Le Comté-de-l’Or est un carrefour pour les voyageurs de l’Alliance qui vont du Comté-du-Nord vers la Forêt d’Elwynn."},sec={{t="Médecine de terrain sur la route",b="Traverser la Forêt d’Elwynn peut vous laisser blessé, loin d’un soigneur de ville ou d’une auberge. Les premiers soins vous permettent de soigner vos blessures sans dépendre de personne. Les bandages aident à traiter les saignements et les traumatismes, sans rites arcaniques ni prières sacrées."},{t="Fournitures pour le campement",b="À l’Auberge de la Fierté du Lion, au Comté-de-l’Or, Michelle Belle apprend aux praticiens expérimentés à assembler des trousses de premiers soins. Gardez des fournitures médicales au camp pour qu’un groupe épuisé puisse soigner ses blessures et reprendre des forces avant d’affronter les dangers à venir."}},faq={{q="À quoi sert cette quête ?",a="Les aventuriers qui maîtrisent les bases des premiers soins vont trouver Michelle Belle au Comté-de-l’Or. Elle leur apprend à fabriquer une trousse de premiers soins et à approvisionner un campement sauvage en fournitures médicales.",al={"utilité des premiers soins en camping","à quoi sert cette quête","pourquoi apprendre les premiers soins en camping"}},{q="À qui dois-je parler au Comté-de-l’Or ?",a="Parlez à Michelle Belle, une formatrice en premiers soins au Comté-de-l’Or. Dès que vous aurez montré votre compétence, elle vous apprendra à préparer des fournitures pour soigner les blessés sur le terrain.",al={"qui est michelle belle","formatrice en camping au comté-de-l’or","formatrice en premiers soins au camp"}},{q="Pourquoi les premiers soins sont-ils importants pour les voyageurs ?",a="Les premiers soins aident les voyageurs à soigner les blessures causées par les bêtes, les bandits et les intempéries. Tout le monde peut bander une plaie et se remettre entre deux escarmouches, avec ou sans magie divine ou arcanique.",al={"pourquoi apprendre les premiers soins","les premiers soins sont-ils utiles","histoire des premiers soins"}},{q="Où se trouve le Comté-de-l’Or ?",a="Le Comté-de-l’Or est le principal hameau de la Forêt d’Elwynn, juste au sud de Hurlevent, le long de la route commerciale principale. C’est un centre névralgique pour les fournitures et les instructeurs locaux, où l’on peut se reposer à l’Auberge de la Fierté du Lion.",al={"où se trouve le comté-de-l’or","emplacement du comté-de-l’or","comment trouver michelle belle"}},{q="Dois-je avoir suivi une formation pour accomplir cette tâche ?",a="Oui. Michelle Belle vous demande de démontrer votre compétence en premiers soins avant de vous apprendre à fabriquer des trousses de campement.",al={"conditions pour introduction au camping","compétence en premiers soins requise","conditions préalables"}},{q="À quoi sert une trousse de premiers soins en camping ?",a="Un campement sauvage offre un lieu sûr où reprendre des forces. Une trousse de premiers soins garde bandages et remèdes à portée de main, prêts à sauver des vies loin des soigneurs de ville.",al={"utilisation d’une trousse de premiers soins au camp","objet de premiers soins pour le camping","pourquoi fabriquer une trousse de premiers soins"}}},fp="22,181,26.227.0,25.224.0,34.158.0,41.153.0,41.178.0,27.185.0,47.99.0,42.155.0"}
P.entries["quest:97920"] = {n="Camping 101: Fishing",s="Lee Brown apprend aux pêcheurs novices près de Comté-de-l’Or à utiliser leur compétence de pêche au camp. Avec des prises simples et des matériaux de base, ils peuvent fabriquer des accessoires utiles pour leur campement.",h="Lee Brown apprend aux pêcheurs novices près de Comté-de-l’Or à utiliser leur compétence de pêche au camp.",kw={"art du campement","camping 101: fishing","lac de cristal","forêt d’elwynn","bocal à poisson","comté-de-l’or","lee brown"},ang={["faction:Alliance"]="En tant que voyageur humain qui débute dans la Forêt d’Elwynn, vous pouvez apprendre à vous débrouiller dans la nature près des eaux familières de Comté-de-l’Or."},sec={{t="Le campement des pêcheurs",b="La pêche peut vous nourrir sur la route et rendre le camp plus confortable. Un Bocal à poisson égaye les voyageurs épuisés entre deux expéditions. Un esprit sain et un moral élevé aident à forger de redoutables combattants."},{t="Le savoir-faire de Lee Brown",b="Lee Brown attend près des eaux aux abords de Comté-de-l’Or les pêcheurs prêts à perfectionner leur art. Montrez-lui votre maîtrise de la canne et de la ligne, et il vous apprendra à fabriquer des accessoires utiles pour le camp."}},faq={{q="À quoi sert cette quête ?",a="Lee Brown guide les pêcheurs en herbe près de Comté-de-l’Or. Après lui avoir montré vos bases en pêche, il vous apprend à fabriquer des objets de campement, comme un Bocal à poisson pour les campements au bord de la route.",al={"pourquoi pêcher en campant","à quoi sert introduction au camping","but de la quête"}},{q="Qui est Lee Brown ?",a="Lee Brown est un maître pêcheur près du Lac de Cristal, juste à l’extérieur de Comté-de-l’Or, dans la Forêt d’Elwynn. Il enseigne la pêche et explique comment fabriquer des objets de campement.",al={"où se trouve lee brown","qui enseigne la pêche au campement","lee brown"}},{q="À quoi sert un Bocal à poisson dans un campement ?",a="Un Bocal à poisson apporte confort et joie au campement. Un cadre agréable remonte le moral et aide les aventuriers à se sentir prêts et capables d’affronter les étendues sauvages.",al={"effet du bocal à poisson","à quoi sert le bocal à poisson","pourquoi fabriquer un bocal à poisson"}},{q="Où cette formation a-t-elle lieu ?",a="La formation a lieu dans la Forêt d’Elwynn, près des eaux autour de Comté-de-l’Or, où se retrouvent les pêcheurs locaux.",al={"lieu de la quête","où aller","maître de camping en forêt d’elwynn"}},{q="Faut-il déjà savoir pêcher pour accomplir cette quête ?",a="Oui. Lee Brown enseigne aux voyageurs qui se sont exercés à lancer leur ligne et ont acquis les bases de la pêche.",al={"prérequis de compétence en pêche","faut-il savoir pêcher","prérequis de compétence"}},{q="Le camping est-il utile au combat ?",a="Oui. Un camp bien entretenu apporte du confort qui améliore la préparation physique et mentale, la résistance et l’efficacité au combat des aventuriers sur le terrain.",al={"le camping aide-t-il au combat","bonus du camping","pourquoi camper"}}},fp="20,179,21.187.0,21.190.0,34.169.0,17.154.0,40.155.0,36.105.0,50.93.0,29.154.0"}
P.entries["quest:97921"] = {n="Camping 101: Herbalism",s="Dans la Forêt d’Elwynn, Herbalist Pomeroy enseigne aux cueilleurs expérimentés un nouveau confort pour le camp. Ils apprennent à fabriquer des Bougies d’encens, dont le parfum remonte le moral des lanceurs de sorts qui se reposent en pleine nature.",h="Dans la Forêt d’Elwynn, Herbalist Pomeroy enseigne aux cueilleurs expérimentés un nouveau confort pour le...",kw={"camp","camping 101","campement","forêt d’elwynn","soigneurs","herboristerie","herbalist pomeroy","bougie d’encens","lanceurs de sorts"},ang={["class:Mage"]="En tant que mage, vous pouvez bénéficier de l’aide d’un compagnon herboriste qui fabrique des Bougies d’encens pour le camp.",["class:Priest"]="En tant que prêtre, vous pouvez vous reposer près d’une Bougie d’encens et retrouver courage grâce à son parfum lors de vos voyages en pleine nature.",["faction:Alliance"]="En tant qu’aventurier de l’Alliance, vous pouvez solliciter les enseignements d’Herbalist Pomeroy dans la Forêt d’Elwynn.",["profession:Herbalism"]="En tant qu’herboriste, vous pouvez utiliser votre connaissance des plantes pour fabriquer des Bougies d’encens qui réconfortent vos compagnons de voyage au camp."},sec={{t="Utilitaires botaniques pour la route",b="Le savoir-faire d’un herboriste peut aider un groupe de voyageurs autrement qu’en préparant des breuvages revigorants ou en vendant des fleurs. Grâce à votre maîtrise de la cueillette, vous pouvez aider vos compagnons à affronter la vie sauvage. Un camp a besoin de plus qu’un feu et d’un couchage sec. Les voyageurs fatigués ont aussi besoin de réconfort pour garder l’esprit vif. Certaines plantes dégagent des arômes qui ravivent les esprits las, permettant aux herboristes de soutenir un groupe loin de la civilisation."},{t="Les conseils d'Herbalist Pomeroy",b="Dans la Forêt d’Elwynn, Herbalist Pomeroy apprend aux cueilleurs expérimentés à fabriquer des fournitures de campement à partir de plantes locales. Elle leur montre comment confectionner une Bougie d’encens, donnant aux herbes un usage qui dépasse les flacons d’alchimie. Allumée au camp, elle dégage un parfum qui apaise les voyageurs fatigués et remonte le moral des compagnons qui dépendent du mana. Grâce aux enseignements de Pomeroy, les herboristes peuvent apporter du réconfort aux groupes qui voyagent en pleine nature."}},faq={{q="Qu'est-ce que Camping 101: Herbalism ?",a="Les herboristes expérimentés peuvent apprendre à fabriquer des Bougies d’encens pour les campements. Herbalist Pomeroy enseigne ce savoir-faire dans la Forêt d’Elwynn.",al={"quête camping 101 herbalism","quête de camping d'herboristerie","qu'est-ce que camping 101 herbalism"}},{q="Qui enseigne la recette de camping pour les herboristes ?",a="Dans la Forêt d’Elwynn, Herbalist Pomeroy apprend aux cueilleurs expérimentés à fabriquer des Bougies d’encens à partir de plantes locales.",al={"qui enseigne le camping pour herboristes","maître de camping 101","où se trouve herbalist pomeroy","emplacement d'herbalist pomeroy"}},{q="Quel objet les herboristes apprennent-ils à fabriquer grâce à cette quête ?",a="Les herboristes apprennent à fabriquer une Bougie d’encens. Son parfum apaise les voyageurs et remonte le moral des compagnons qui dépendent du mana lorsqu’ils se reposent en pleine nature.",al={"que fabriquent les herboristes pour le camping","objet de camp d'herboristerie","bougie d'encens herboristerie","qu'enseigne camping 101"}},{q="Quelles sont les conditions requises pour commencer Camping 101: Herbalism ?",a="Vous devez maîtriser l’herboristerie et la cueillette avant qu’Herbalist Pomeroy vous enseigne ce savoir-faire de campement.",al={"conditions requises pour camping 101 herbalism","quand puis-je obtenir camping 101 herbalism","compétence d'herboristerie requise pour camping 101"}},{q="Pourquoi les Bougies d’encens sont-elles utiles pour les groupes d'aventuriers ?",a="Les Bougies d’encens apaisent les voyageurs et remontent le moral des compagnons qui dépendent du mana lorsqu’ils se reposent en pleine nature.",al={"que fait la bougie d'encens","pourquoi fabriquer une bougie d'encens","avantages de la bougie d'encens","utilisation de la bougie d'encens d'herboristerie"}},{q="Où se déroule cette quête ?",a="Vous vous rendez dans la Forêt d’Elwynn pour rencontrer Herbalist Pomeroy et apprendre à fabriquer des fournitures de campement.",al={"zone de camping 101 herbalism","où rendre camping 101 herbalism","quête d'herboristerie de la forêt d’elwynn"}},{q="Les non-herboristes peuvent-ils fabriquer la Bougie d’encens ?",a="Non. Fabriquer une Bougie d’encens exige de maîtriser l’herboristerie et de connaître les plantes sauvages et les matières aromatiques, comme l’enseigne Herbalist Pomeroy.",al={"tout le monde peut-il fabriquer une bougie d'encens","la bougie d'encens est-elle réservée aux herboristes","faut-il l'herboristerie pour la bougie d'encens"}}},fp="22,192,32.406.0,33.393.0,31.122.0,46.103.0,55.155.0,58.93.0,55.111.0,33.90.0,44.133.0"}
P.entries["quest:97922"] = {n="Camping 101: Leatherworking",s="À Comté-de-l’Or, Adele Fielder apprend aux travailleurs du cuir à fabriquer une tente pour leurs voyages.",h="À Comté-de-l’Or, Adele Fielder apprend aux travailleurs du cuir à fabriquer une tente pour leurs voyages.",kw={"adele fielder","feu de camp","camping","forêt d’elwynn","comté-de-l’or","travail du cuir","tente","survie dans la nature"},ang={["faction:Alliance"]="À Comté-de-l’Or, cette formation initie les travailleurs du cuir de l’Alliance aux techniques de survie utiles pour voyager à travers Azeroth.",["profession:Cooking"]="Adele Fielder explique qu’un campement dans la nature a besoin d’un feu de camp et vous recommande d’apprendre la cuisine pour pouvoir en allumer un."},sec={{t="Un abri sur la route",b="Au-delà des portes de Comté-de-l’Or, un abri compte autant qu’une armure. Dans la Forêt d’Elwynn, les travailleurs du cuir peuvent rendre visite à Adele Fielder pour apprendre à confectionner plus que de simples ceintures et tuniques. Après avoir montré leur habileté avec le cuir et l’aiguille, Adele leur apprend à fabriquer une tente solide pour les longs voyages terrestres. Elle est conçue pour résister aux intempéries."},{t="Les bases du campement",b="Une tente terminée couvre un campement et protège des éléments. Elle garde les voyageurs au frais sous un soleil de plomb, au sec sous les pluies battantes et leur permet de se reposer entre deux rencontres dangereuses.\n\nLes habitants de Comté-de-l’Or et les gardes de la ville n’autorisent pas les campements dans les rues. Vous devez donc partir dans la nature pour camper. Adele rappelle aussi aux vagabonds qu’un camp convenable a besoin d’un feu de camp. Un maître des cuisiniers peut vous apprendre à en allumer un."}},faq={{q="Qui apprend aux travailleurs du cuir à fabriquer des tentes ?",a="Adele Fielder apprend aux travailleurs du cuir de Comté-de-l’Or, dans la Forêt d’Elwynn, à fabriquer des tentes solides après qu’ils ont montré leur habileté dans leur métier.",al={"qui apprend à fabriquer des tentes","où se trouve adele fielder","maître des tentes en travail du cuir"}},{q="À quoi sert une tente fabriquée ?",a="Une tente fabriquée protège les voyageurs des intempéries, les gardant au frais lors des journées étouffantes et au sec sous les pluies battantes. Elle permet aussi aux aventuriers de se reposer dans la nature.",al={"pourquoi fabriquer une tente","à quoi sert une tente","avantages d’une tente"}},{q="Peut-on planter une tente en ville ?",a="Vous ne pouvez pas planter de tente dans les rues ni au centre d’une ville. Emportez votre équipement dans la nature pour installer votre camp.",al={"peut-on planter une tente en ville","où utiliser une tente","tente à hurlevent ou à comté-de-l’or"}},{q="De quoi a-t-on besoin en plus d’une tente pour compléter un campement ?",a="Adele Fielder explique qu’un camp a besoin d’un feu de camp en plus d’une tente, pour se réchauffer et pour les usages pratiques dans la nature.",al={"de quoi d’autre ai-je besoin pour camper","tente et feu de camp requis","comment compléter un campement"}},{q="Où peut-on apprendre à allumer un feu de camp ?",a="Les maîtres des cuisiniers et les cuisiniers locaux enseignent les bases pour allumer un feu de camp. Apprenez auprès d’eux afin de pouvoir en allumer un fiable partout où vous irez.",al={"qui apprend à allumer un feu de camp","comment apprendre à allumer un feu de camp","feu pour le campement"}},{q="Quand un travailleur du cuir peut-il apprendre à fabriquer une tente de camping ?",a="Un travailleur du cuir doit d’abord montrer son habileté dans le métier avant qu’Adele Fielder lui apprenne à fabriquer des tentes.",al={"conditions pour fabriquer une tente","comment obtenir la recette de tente","quand puis-je fabriquer une tente"}}},fp="27,196,25.319.0,27.420.0,46.127.0,39.163.0,35.107.0,56.103.0,47.142.0,55.91.0"}
P.entries["quest:97923"] = {n="Camping 101: Mining",s="À Hurlevent, Gelman Stonehand apprend aux mineurs à façonner une pierre d’aimant pour les campements sauvages. Posée près d’un feu de camp, elle renforce les combattants réunis là.",h="À Hurlevent, Gelman Stonehand apprend aux mineurs à façonner une pierre d’aimant pour les campements sauvages.",kw={"feu de camp","camping 101: mining","campement","gelman stonehand","pierre d’aimant","minage","hurlevent","nature sauvage"},ang={["faction:Alliance"]="En tant qu’artisan de l’Alliance, vous pouvez apprendre auprès de Gelman Stonehand à Hurlevent à transformer les arts de la terre en outils pratiques pour le terrain.",["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre à entretenir un feu de camp, la base de tout équipement de camp spécialisé.",["profession:Mining"]="En tant que mineur, vous pouvez façonner une pierre d’aimant pour renforcer votre campement sauvage et aider vos alliés qui se reposent à vos côtés."},sec={{t="La puissance résonnante de la terre",b="À Hurlevent, les mineurs peuvent façonner le magnétisme naturel de la terre pour en faire une pierre d’aimant. Sur le campement d’une expédition, elle renforce la puissance au combat des personnes rassemblées. Gelman Stonehand, le maître mineur de Hurlevent, enseigne cet artisanat aux prospecteurs qui font leurs preuves à la pioche."},{t="Campements sauvages et feux de camp",b="Une pierre d’aimant a sa place dans la nature, loin de la Place de la Cathédrale et du Quartier commerçant. Les citadins désapprouvent les voyageurs qui campent dans les limites de la ville. Les pionniers doivent donc s’aventurer dans la nature pour établir leur camp. La pierre a aussi besoin d’un feu de camp. Les cuisiniers du royaume enseignent cette compétence de base pour la vie sauvage."}},faq={{q="Qu’est-ce que Camping 101: Mining ?",a="À Hurlevent, Gelman Stonehand apprend aux mineurs à fabriquer une pierre d’aimant pour un campement sauvage. Vous devez prouver votre maîtrise du minage pour apprendre cet artisanat.",al={"qu’est-ce que camping 101 minage","objectif de la quête","que faire"}},{q="Qui enseigne le schéma de la pierre d’aimant ?",a="Gelman Stonehand est un maître mineur à Hurlevent. Il apprend aux mineurs qualifiés à fabriquer une pierre d’aimant pour les expéditions dans la nature.",al={"qui enseigne la pierre d’aimant","où se trouve gelman stonehand","emplacement de stonehand"}},{q="À quoi sert une pierre d’aimant ?",a="Une pierre d’aimant placée sur un campement sauvage renforce les guerriers et autres combattants réunis autour de son feu de camp.",al={"à quoi sert la pierre d’aimant","bonus de la pierre d’aimant","pourquoi fabriquer une pierre d’aimant"}},{q="Puis-je installer un camp à Hurlevent ?",a="Les citadins de Hurlevent désapprouvent les campements sur les places et dans les rues. Sortez des portes de la ville pour établir votre camp et placer votre pierre d’aimant dans la nature.",al={"puis-je camper en ville","où installer un camp","restrictions de campement"}},{q="Pourquoi ai-je besoin d’un feu de camp pour installer un camp ?",a="Un feu de camp est la base d’un campement, et un équipement spécialisé comme une pierre d’aimant ne sert à rien sans lui. Les cuisiniers apprennent aux voyageurs à allumer un feu avec du bois et du silex.",al={"faut-il connaître la cuisine pour camper","comment installer un camp","nécessité d’un feu de camp"}},{q="Qui tire le plus profit d’une pierre d’aimant ?",a="Toute personne qui se bat à l’épée, à la hache ou au marteau peut profiter d’une pierre d’aimant. Les combattants recherchent sa force accrue lorsqu’ils se reposent près des flammes avant une bataille dangereuse.",al={"qui profite de la pierre d’aimant","la pierre d’aimant est-elle utile au corps à corps","classes concernées par la pierre d’aimant"}}},fp="19,152,26.291.0,30.285.0,28.145.0,36.132.0,25.110.0,35.156.0,40.163.0,52.164.0"}
P.entries["quest:97924"] = {n="Camping 101: Skinning",s="Dans la Forêt d’Elwynn, les dépeceurs apprennent Camping 101: Skinning auprès d’Helene Peltskinner, à Comté-de-l’Or. Elle leur enseigne à façonner les peaux récoltées pour en faire une Chaise du camp où se reposer loin des villes.",h="Dans la Forêt d’Elwynn, les dépeceurs apprennent Camping 101: Skinning auprès d’Helene Peltskinner, à...",kw={"chaise du camp","feu de camp","camping 101: skinning","comté-de-l’or","helene peltskinner","dépeçage","camping en pleine nature"},ang={["faction:Alliance"]="Si vous êtes un dépeceur de l’Alliance de passage dans la Forêt d’Elwynn, trouvez Helene Peltskinner à Comté-de-l’Or pour apprendre cet art de la nature.",["profession:Cooking"]="Si vous apprenez à installer un camp en pleine nature, consultez un cuisinier. Un campement a besoin d’un feu de camp simple pour se réchauffer et préparer les repas."},sec={{t="Le confort en pleine nature",b="Vous pouvez façonner les peaux prélevées sur les bêtes pour en faire une Chaise du camp où vous reposer en pleine nature. À Comté-de-l’Or, Helene Peltskinner apprend aux dépeceurs compétents à fabriquer ce siège pour les voyageurs qui parcourent de longues distances en terres dangereuses."},{t="Règles du campement",b="Emportez votre équipement dans la nature avant d’installer votre campement, car les habitants des villes s’opposent souvent aux camps sur la place. Un camp en pleine nature a aussi besoin d’un feu de camp. Beaucoup de dépeceurs apprennent les bases de la cuisine pour maîtriser l’allumage d’un feu."}},faq={{q="Qu’est-ce que Camping 101: Skinning ?",a="À Comté-de-l’Or, Helene Peltskinner apprend aux dépeceurs compétents à fabriquer une Chaise du camp avec des peaux récoltées.",al={"qu’est-ce que camping 101 skinning","que fait cette quête","quête de chaise du camp en dépeçage"}},{q="Qui apprend aux dépeceurs à fabriquer une Chaise du camp ?",a="À Comté-de-l’Or, Helene Peltskinner apprend aux dépeceurs compétents à fabriquer une Chaise du camp.",al={"qui enseigne la chaise du camp","emplacement d’helene peltskinner","où rendre camping 101 skinning"}},{q="À quoi sert la fabrication d’une Chaise du camp ?",a="Une Chaise du camp offre aux voyageurs un siège où se reposer pendant leurs périples en pleine nature.",al={"à quoi sert une chaise du camp","pourquoi fabriquer une chaise du camp","utilité de la chaise du camp"}},{q="Où les aventuriers peuvent-ils installer leur campement ?",a="Les habitants des villes n’apprécient généralement pas les campements au milieu des agglomérations. Installez donc le vôtre dans la nature.",al={"peut-on camper en ville","où placer une chaise du camp","camping à comté-de-l’or"}},{q="De quoi d’autre avez-vous besoin pour installer un campement complet ?",a="Un campement a besoin d’un feu de camp simple. Si vous ne savez pas en allumer un, apprenez les bases de la cuisine auprès d’un cuisinier local.",al={"de quoi ai-je besoin pour camper","faut-il un feu pour camper","nécessité d’un feu de camp"}},{q="Qui peut apprendre cet art du campement ?",a="Les dépeceurs capables de prélever des peaux sur les bêtes peuvent apprendre cet art et utiliser ces peaux dans la nature.",al={"qui peut apprendre à fabriquer une chaise du camp","les non-dépeceurs peuvent-ils le faire","condition de dépeçage pour camper"}}},fp="21,184,29.212.0,21.213.0,30.103.0,47.81.0,45.83.0,34.107.0,51.110.0,44.122.0"}
P.entries["quest:97925"] = {n="Camping 101: Tailoring",s="Dans la Forêt d’Elwynn, les artisans du tissu qualifiés sont envoyés auprès d’Eldrin, au Camp de bûcherons du Val d'est. Il leur apprend à tisser une Bannière de faction qui inspire les voyageurs et remonte le moral dans les campements sauvages.",h="Dans la Forêt d’Elwynn, les artisans du tissu qualifiés sont envoyés auprès d’Eldrin, au Camp de bûcherons du...",kw={"bannière","campement","camping 101","camp de bûcherons du val d'est","eldrin","forêt d’elwynn","bannière de faction","couture"},ang={["faction:Alliance"]="Les aventuriers de l’Alliance sont envoyés auprès d’Eldrin, au Camp de bûcherons du Val d'est dans la Forêt d’Elwynn, pour apprendre à coudre une Bannière de faction.",["profession:Tailoring"]="Les couturiers peuvent tisser une Bannière de faction pour inspirer les voyageurs et remonter le moral au campement pendant les longues expéditions."},sec={{t="La vocation du tisserand dans la nature",b="Eldrin, artisan au Camp de bûcherons du Val d'est, dans l'est de la Forêt d’Elwynn, guide les couturiers expérimentés. La couture permet de confectionner des vêtements et des sacs, mais aussi de soutenir les voyageurs. Ceux qui ont fait leurs preuves avec le fil et le métier à tisser peuvent apprendre à fabriquer des accessoires de camp pour les expéditions en pleine nature."},{t="Des bannières qui remontent le moral",b="La Bannière de faction est la principale création qu’enseigne Eldrin. Elle se dresse près du feu d’un voyageur, où son emblème peut réconforter ceux qui affrontent des périls ou combattent. Dans un campement, elle offre aux voyageurs épuisés un signe familier de détermination et les aide à poursuivre leur route en terres hostiles."}},faq={{q="À quoi sert Camping 101: Tailoring ?",a="Eldrin, au Camp de bûcherons du Val d'est, dans la Forêt d’Elwynn, apprend aux couturiers expérimentés à fabriquer une Bannière de faction. Celle-ci inspire les voyageurs et remonte le moral au campement.",al={"en quoi consiste camping 101: tailoring","quête d’objet de camp en couture","comment obtenir une bannière de camp"}},{q="Qui est Eldrin et où peut-on le trouver ?",a="Eldrin est un artisan au Camp de bûcherons du Val d'est, dans l'est de la Forêt d’Elwynn. Il apprend aux couturiers expérimentés à fabriquer des bannières de faction pour les campements.",al={"qui est eldrin","où trouver eldrin","emplacement d’eldrin"}},{q="À quoi sert la Bannière de faction dans un campement ?",a="Une Bannière de faction inspire les voyageurs et remonte le moral au campement. Son emblème donne du courage aux voyageurs épuisés qui traversent des terres hostiles.",al={"à quoi sert la bannière de couture","bannière de faction au campement","pourquoi fabriquer une bannière de faction"}},{q="Quelles conditions faut-il remplir pour apprendre cet art auprès d’Eldrin ?",a="Les couturiers doivent d’abord faire leurs preuves avant qu’Eldrin leur enseigne cet art. Ils doivent maîtriser la couture pour tisser et assembler la bannière.",al={"quelle compétence faut-il","conditions pour la bannière de camp","tous les couturiers peuvent-ils fabriquer une bannière"}},{q="Où se trouve le Camp de bûcherons du Val d'est ?",a="Le Camp de bûcherons du Val d'est se trouve dans les bois à l’est de la Forêt d’Elwynn, sur la route des Carmines. Les artisans et les ouvriers du coin se rassemblent dans ce centre forestier.",al={"où se trouve le camp de bûcherons du val d'est","camp de bûcherons du val d'est dans la forêt d’elwynn"}},{q="Cette tâche est-elle réservée aux couturiers de l’Alliance ?",a="Eldrin se trouve au cœur de la Forêt d’Elwynn, en territoire de l’Alliance. Il y enseigne aux artisans liés à l’Alliance des colonies de l’est.",al={"la horde peut-elle faire cette quête","réservé à l’alliance"}}},fp="22,192,30.298.0,17.274.0,46.159.0,40.138.0,43.143.0,60.135.0,43.170.0,43.153.0"}
P.entries["quest:97926"] = {n="Making Do",s="Auberdine attend des nouvelles de Hurlevent, mais aucune aide ne viendra. Making Do transporte la Réponse d’Alexston par-delà la mer jusqu’à Thundris Windweaver, l’Ancien.",h="Auberdine attend des nouvelles de Hurlevent, mais aucune aide ne viendra.",kw={"alexston","réponse d’alexston","auberdine","coffres","sombrivage","making do","hurlevent","thundris windweaver"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous constatez que la distance et les finances tendues de Hurlevent privent Auberdine de soutien financier.",["race:Human"]="En tant qu’humain, vous constatez que les coffres presque vides de Hurlevent et les difficultés de ses terres empêchent le royaume de financer une aide outre-mer.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous constatez que ni vos alliés humains par-delà la mer ni Darnassus, toute proche, n’aident Auberdine face à ses difficultés locales."},sec={{t="Un courrier par-delà la mer",b="Vous transportez la Réponse d’Alexston par-delà la mer jusqu’à Thundris Windweaver, l’Ancien, à Auberdine. La lettre n’apporte ni troupes ni secours. Le représentant de Hurlevent explique que le trésor du royaume est presque vide. Les richesses restantes doivent suffire à ses propres territoires en difficulté."},{t="Livrés à leur sort",b="Thundris Windweaver reçoit la réponse avec regret et vous remercie pour ce long voyage. Hurlevent ne peut pas aider, et Darnassus n’a pas non plus offert son aide. Auberdine et ses habitants doivent compter sur eux-mêmes. Leur sort repose entre leurs mains."}},faq={{q="Qu’est-ce que la quête Making Do ?",a="Vous transportez la réponse de Baros Alexston depuis Hurlevent, par-delà la mer, jusqu’à Thundris Windweaver, l’Ancien, à Auberdine. Hurlevent n’a pas les moyens d’envoyer de l’aide à Sombrivage.",al={"qu’est-ce que making do","quête making do","quête auberdine hurlevent"}},{q="Pourquoi Hurlevent refuse-t-elle d’aider Auberdine ?",a="Les coffres de Hurlevent sont presque vides, et les ressources restantes sont déjà réparties sur ses propres terres. Le royaume n’a pas les moyens d’aider Auberdine.",al={"pourquoi hurlevent a dit non","coffres de hurlevent presque vides","pourquoi hurlevent n’aide pas auberdine"}},{q="Comment Thundris Windweaver réagit-il à la nouvelle ?",a="Thundris Windweaver reçoit la lettre avec tristesse et accepte qu’Auberdine doive compter sur elle-même. Ni Hurlevent ni Darnassus ne lui apporte de soutien.",al={"réaction de thundris à hurlevent","comment thundris réagit"}},{q="Qui a envoyé la Réponse d’Alexston ?",a="Baros Alexston a envoyé la réponse depuis Hurlevent. Il exprime sa sympathie pour Auberdine tout en expliquant que le royaume n’a pas les moyens de l’aider.",al={"qui est alexston","expéditeur de la réponse d’alexston"}},{q="Darnassus aide-t-elle Auberdine ?",a="Thundris Windweaver affirme que ni Hurlevent ni Darnassus n’ont aidé Auberdine. La colonie doit compter sur elle-même.",al={"aide de darnassus à auberdine","pourquoi darnassus n’a pas aidé"}},{q="Où la Réponse d’Alexston est-elle remise ?",a="La Réponse d’Alexston est remise à Thundris Windweaver à Auberdine, la ville portuaire sur la côte de Sombrivage.",al={"où cette quête se termine","lieu de remise de making do"}}},fp="9,142,24.276.0,22.238.1,28.155.0,43.153.0,47.154.0,26.138.0,31.114.0,36.102.0"}
P.entries["quest:97927"] = {n="Camping 101: Alchemy",s="Kray, aux Pitons-du-Tonnerre, peut vous apprendre à fabriquer un Puits de mana pour votre camp d’alchimiste. Le puits attire les soigneurs et les lanceurs de sorts en quête de rafraîchissement.",h="Kray, aux Pitons-du-Tonnerre, peut vous apprendre à fabriquer un Puits de mana pour votre camp d’alchimiste.",kw={"alchimiste","alchimie","feu de camp","campement","soigneurs","kray","puits de mana","lanceurs de sorts","pitons-du-tonnerre"},sec={{t="Un puits pour le camp",b="Un alchimiste peut apprendre à fabriquer un Puits de mana auprès de Kray, aux Pitons-du-Tonnerre. Vous avez fait preuve de votre maîtrise, et Kray peut vous enseigner cette fabrication de campement. Les soigneurs et les lanceurs de sorts viendront y boire pour se rafraîchir. Pour établir votre camp dans la nature, il vous faut aussi un feu de camp, qu’un cuisinier peut vous apprendre à allumer."}},faq={{q="Qui peut m’apprendre à fabriquer un Puits de mana ?",a="Kray, aux Pitons-du-Tonnerre, peut vous apprendre à fabriquer un Puits de mana une fois que vous avez fait preuve de votre maîtrise de l’alchimie.",al={"maître puits de mana","qui est kray","kray alchimie"}},{q="À quoi sert un Puits de mana ?",a="Un Puits de mana est un objet de campement que les alchimistes peuvent fabriquer. Les soigneurs et les lanceurs de sorts viennent s’y rafraîchir.",al={"utilité du puits de mana","à quoi sert le puits","objet de campement d’alchimie"}},{q="Où apprendre à fabriquer cet objet de campement ?",a="Adressez-vous à Kray, aux Pitons-du-Tonnerre, pour apprendre à fabriquer un Puits de mana.",al={"où est kray","alchimie aux pitons-du-tonnerre","emplacement du puits de mana"}},{q="De quoi d’autre ai-je besoin pour établir un camp ?",a="Un camp nécessite un feu de camp avant de pouvoir être établi. Un cuisinier peut vous apprendre à en allumer un.",al={"feu de camp nécessaire","comment établir un camp","feu pour le camp"}},{q="Puis-je essayer le Puits de mana en ville ?",a="Les instructions pour terminer indiquent que la plupart des gens n’apprécient pas les campements en plein centre-ville, vous devez donc partir dans la nature pour l’essayer.",al={"campement en ville","où essayer le puits de mana","essai du puits de mana"}}},fp="20,144,15.311.0,36.100.0,24.99.0,36.66.0,35.82.0,33.138.0"}
P.entries["quest:97928"] = {n="Camping 101: Blacksmithing",s="Vous êtes prêt à fabriquer une Meule à aiguiser et à l’essayer dans la nature. D’abord, il vous faut un feu de camp pour installer votre campement.",h="Vous êtes prêt à fabriquer une Meule à aiguiser et à l’essayer dans la nature.",kw={"forge","feu de camp","camping","cuisinier","meule à aiguiser","nature"},ang={["profession:Blacksmithing"]="Vous pouvez maintenant fabriquer une Meule à aiguiser pour l’utiliser dans la nature.",["profession:Cooking"]="Un cuisinier peut vous apprendre à fabriquer un feu de camp."},sec={{t="Prêt à camper",b="Vous pouvez maintenant fabriquer une Meule à aiguiser. Emportez-la dans la nature pour l’essayer, où vous pourrez installer votre campement loin du centre-ville. Emportez aussi un feu de camp. Un cuisinier peut vous apprendre à en fabriquer un."}},faq={{q="Que puis-je fabriquer maintenant ?",a="Vous pouvez maintenant fabriquer votre propre Meule à aiguiser.",al={"meule à aiguiser","fabrication en forge","que fabriquer"}},{q="Où puis-je essayer la Meule à aiguiser ?",a="Vous pouvez l’essayer dans la nature, où vous pouvez installer votre campement loin du centre-ville.",al={"où l’essayer","emplacement de la meule à aiguiser","où camper"}},{q="De quoi ai-je besoin avant d’installer mon campement ?",a="Vous avez besoin d’un feu de camp pour installer votre campement.",al={"feu de camp nécessaire","comment installer un campement","bases du camping"}},{q="Qui peut m’apprendre à fabriquer un feu de camp ?",a="Un cuisinier peut vous apprendre à fabriquer un feu de camp.",al={"apprendre à faire un feu de camp","qui apprend à faire du feu","feu de cuisine"}}},fp="26,119,13.198.0,21.44.0,37.89.0,38.47.0,36.40.0"}
P.entries["quest:97931"] = {n="Camping 101: First Aid",s="Vous êtes prêt à fabriquer une Trousse de premiers soins, et il vous faut maintenant un endroit pour l’essayer.",h="Vous êtes prêt à fabriquer une Trousse de premiers soins, et il vous faut maintenant un endroit pour...",kw={"feu de camp","camping","cuisine","premiers soins","trousse de premiers soins","nature"},sec={{t="Un endroit où camper",b="Vous pouvez fabriquer la trousse, mais la plupart des gens préfèrent éviter de camper en pleine ville. Emportez-la donc dans la nature. Avant d’installer votre camp, vous avez besoin d’un feu de camp. La plupart des cuisiniers peuvent vous apprendre à en allumer un."}},faq={{q="Où puis-je essayer la Trousse de premiers soins ?",a="Essayez la Trousse de premiers soins dans la nature, où les gens risquent moins de s’opposer à un campement.",al={"où essayer la trousse","endroit pour la trousse de premiers soins"}},{q="De quoi ai-je besoin avant d’installer mon camp ?",a="Vous avez besoin d’un feu de camp avant de pouvoir installer votre camp.",al={"feu de camp nécessaire","de quoi camper"}},{q="Qui peut m’apprendre à allumer un feu de camp ?",a="La plupart des cuisiniers peuvent vous apprendre à allumer un feu de camp.",al={"allumer un feu de camp","qui apprend à allumer un feu"}}},fp="22,74,15.205.0,34.90.0,38.47.0,36.48.0"}
P.entries["quest:97932"] = {n="Camping 101: Fishing",s="À Mulgore, les pêcheurs peuvent apporter un peu de confort aux campements sauvages. Montrez votre adresse à la canne et au moulinet à Uthan Stillwater, au village de Sabot-de-Sang, et il vous apprendra à fabriquer un Bocal à poisson pour les voyageurs qui se reposent en plein air.",h="À Mulgore, les pêcheurs peuvent apporter un peu de confort aux campements sauvages.",kw={"sabot-de-sang","feu de camp","camping","camping 101: fishing","bocal à poisson","pêche","mulgore","uthan stillwater"},ang={["faction:Horde"]="En tant que pêcheur de la Horde de passage à Mulgore, vous pouvez apprendre à fabriquer des accessoires de campement auprès d'Uthan Stillwater, au village de Sabot-de-Sang.",["profession:Cooking"]="Un campement digne de ce nom a besoin d'un feu de camp. Des notions de cuisine s'accordent naturellement avec un campement de pêcheur en pleine nature."},sec={{t="La pêche en pleine nature",b="Les pêcheurs de passage à Mulgore peuvent mettre leur paisible passe-temps à profit au campement. Si vous avez prouvé votre adresse à la canne et au moulinet, cherchez Uthan Stillwater au village de Sabot-de-Sang. Il apprend aux pêcheurs chevronnés à fabriquer un Bocal à poisson, une touche de chaleur pour un campement."},{t="Le confort du campement",b="Un Bocal à poisson apporte un peu de gaieté à un voyage éprouvant. Sa présence apaisante rend un lieu de repos en pleine nature plus agréable et remonte le moral des voyageurs qui s'y rassemblent. Un meilleur moral aiguise les instincts et renforce la résistance au combat."},{t="Feu de camp et grands espaces",b="Un campement doit être installé dans les grands espaces, et non dans un village comme Sabot-de-Sang. Le Bocal à poisson ne peut être utilisé qu'en pleine nature. Un campement a aussi besoin d'un feu adéquat : cherchez donc un maître cuisinier pour apprendre les bases de l'allumage avant de vous installer."}},faq={{q="À quoi sert le Bocal à poisson dans un campement ?",a="Le Bocal à poisson est un accessoire de campement fabriqué par les pêcheurs chevronnés. Il apporte confort et gaieté aux voyageurs qui se reposent en pleine nature, leur remonte le moral et les aide à garder l'esprit vif au combat.",al={"bocal à poisson au campement","utilité du bocal à poisson","avantage du bocal à poisson"}},{q="Qui enseigne la recette du Bocal à poisson ?",a="Uthan Stillwater enseigne cet artisanat au village de Sabot-de-Sang, à Mulgore. Il apprend aux pêcheurs qui ont déjà fait leurs preuves.",al={"où apprendre à fabriquer le bocal à poisson","qui enseigne le bocal à poisson","emplacement d'uthan stillwater"}},{q="Pourquoi ne peut-on pas installer son campement dans un village ?",a="Les villages comme Sabot-de-Sang n'autorisent pas les voyageurs à installer leur campement en ville. Installez plutôt votre campement en pleine nature.",al={"campement en ville","pourquoi je ne peux pas camper à sabot-de-sang","campement dans les villes"}},{q="De quoi d'autre a-t-on besoin pour installer un campement ?",a="Un campement digne de ce nom a besoin d'un feu de camp. Si vous ne savez pas en allumer un, cherchez un maître cuisinier pour apprendre les bases.",al={"feu de camp nécessaire au campement","besoin d'un feu pour camper","bases du camping et feu"}},{q="Quelles sont les conditions à remplir pour apprendre à fabriquer le Bocal à poisson ?",a="Vous devez prouver votre savoir-faire en pêche avant qu'Uthan Stillwater vous apprenne à fabriquer des accessoires de campement. Si vous débutez, prenez d'abord le temps de vous exercer au bord de l'eau.",al={"niveau de pêche requis pour camper","quand obtenir le bocal à poisson","conditions pour le guide du camping : pêche"}},{q="Pourquoi un aventurier voudrait-il emporter un Bocal à poisson en camping ?",a="Un Bocal à poisson apporte un peu de chez soi à une vie éprouvante et fatigante sur les routes. Observer un poisson près du feu peut réjouir un aventurier et lui remonter le moral.",al={"pourquoi emporter un bocal à poisson en camping","histoire du bocal à poisson de campement"}}},fp="20,218,19.257.0,16.237.0,25.248.0,42.185.0,33.128.0,45.124.0,39.128.0,59.169.0,55.146.0"}
P.entries["quest:97933"] = {n="Camping 101: Herbalism",s="Komin Winterhoof, aux Pitons-du-Tonnerre, peut vous apprendre à fabriquer une Bougie d’encens pour votre campement. Votre compétence en herboristerie vous donne accès à une aide utile aux soigneurs et aux lanceurs de sorts.",h="Komin Winterhoof, aux Pitons-du-Tonnerre, peut vous apprendre à fabriquer une Bougie d’encens pour votre...",kw={"feu de camp","camping","initiation au camping","herboristerie","bougie d’encens","komin winterhoof","pitons-du-tonnerre"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez enseigner les bases pour allumer un feu de camp, indispensable à un campement.",["profession:Herbalism"]="En tant qu’herboriste, votre compétence vous permet d’apprendre à fabriquer une Bougie d’encens pour le campement."},sec={{t="Une bougie pour le campement",b="Un maître aux Pitons-du-Tonnerre vous demande de mettre votre compétence en herboristerie à profit pour apprendre une technique de camping. La Bougie d’encens peut renforcer l’esprit des soigneurs et des lanceurs de sorts. Vous repartez en sachant en fabriquer une, mais pour l’essayer, il vous faut un campement hors de la ville et un feu de camp."}},faq={{q="Qui enseigne cette technique de camping ?",a="Komin Winterhoof, aux Pitons-du-Tonnerre, vous apprend à fabriquer une Bougie d’encens.",al={"maître herboristerie camping","qui enseigne la bougie d’encens"}},{q="Quel rapport entre l’herboristerie et le camping ?",a="Faire preuve de compétence en herboristerie vous permet d’apprendre à fabriquer une Bougie d’encens pour votre campement.",al={"objet de campement herboristerie","herboristerie camping"}},{q="À quoi sert une Bougie d’encens ?",a="Une Bougie d’encens peut renforcer l’esprit des soigneurs et des lanceurs de sorts.",al={"utilité de la bougie d’encens","bougie de campement"}},{q="Où puis-je essayer la bougie ?",a="Vous devez vous rendre en pleine nature pour l’essayer, car la plupart des gens n’apprécient guère les campements en plein centre-ville.",al={"où essayer la bougie d’encens","campement en ville"}},{q="Me faut-il autre chose pour le campement ?",a="Un feu de camp est nécessaire avant d’installer votre campement. La plupart des cuisiniers peuvent vous apprendre à en allumer un.",al={"feu de camp nécessaire","quoi d’autre pour le campement"}}},fp="22,165,17.285.0,27.73.0,44.89.0,30.68.0,27.109.0,33.86.0"}
P.entries["quest:97934"] = {n="Camping 101: Leatherworking",s="À Sabot-de-Sang, les travailleurs du cuir apprennent à fabriquer une tente pour s’abriter en voyage. Chaw Stronghide enseigne cet art aux artisans prêts à travailler des peaux plus épaisses et à faire des coutures solides.",h="À Sabot-de-Sang, les travailleurs du cuir apprennent à fabriquer une tente pour s’abriter en voyage.",kw={"sabot-de-sang","feu de camp","camping 101","chaw stronghide","travail du cuir","mulgore","abri","tente"},ang={["faction:Horde"]="Les voyageurs de la Horde qui traversent les terres vastes et arides de Kalimdor comptent sur un équipement de campement robuste, loin des forteresses.",["profession:Cooking"]="Les maîtres cuisiniers apprennent aux voyageurs à faire un vrai feu de camp, qui complète le campement chaleureux autour d’une tente en cuir.",["race:Tauren"]="La fabrication d’abris portatifs en cuir s’accorde avec les traditions nomades des tribus taurènes et leur savoir-faire de survie dans les étendues sauvages de Mulgore."},sec={{t="Des abris dans les plaines",b="À travers Kalimdor, les travailleurs du cuir qui savent coudre une tente solide peuvent se protéger du soleil de midi et des pluies des prairies. Une tente offre aussi aux voyageurs épuisés un lieu où se reposer et reprendre des forces avant de traverser à nouveau les plaines."},{t="L’art de Chaw Stronghide",b="À Sabot-de-Sang, en Mulgore, Chaw Stronghide enseigne aux travailleurs du cuir capables de manier des peaux plus épaisses et de faire des coutures solides. Quand ils ont prouvé leur savoir-faire, il leur montre comment fabriquer une tente résistante pour voyager loin de la civilisation."},{t="Des campements sauvages",b="Choisissez votre campement avec soin et respectez les communautés locales. Les habitants des villages voient d’un mauvais œil les voyageurs qui s’installent sur les chemins centraux et les grands axes. Emportez donc votre tente dans les terres sauvages. Un vrai campement nécessite aussi un feu. Demandez à un cuisinier expérimenté comment en allumer un."}},faq={{q="Qu’apprend cette quête aux travailleurs du cuir ?",a="Les travailleurs du cuir apprennent à fabriquer une tente pour leurs voyages. Elle les protège des intempéries et leur offre un lieu où se reposer dans la nature.",al={"quête de tente en travail du cuir","que enseigne camping 101","objet de campement en travail du cuir"}},{q="Qui apprend aux travailleurs du cuir à fabriquer des tentes de campement ?",a="Chaw Stronghide enseigne la fabrication de tentes à Sabot-de-Sang, en Mulgore. Il transmet son savoir aux travailleurs du cuir qui prouvent qu’ils savent manier des peaux plus épaisses et faire des coutures solides.",al={"qui enseigne la fabrication de tentes","tente de chaw stronghide","maître des tentes en travail du cuir"}},{q="Où les voyageurs peuvent-ils installer leurs tentes de campement ?",a="Installez votre campement dans la nature, loin des zones habitées. Les citadins et les anciens des villages ne veulent pas de campements privés sur les places ou le long des routes.",al={"où installer ma tente","peut-on camper en ville","emplacement d’une tente"}},{q="Pourquoi faut-il un feu de camp en plus d’une tente ?",a="Un feu de camp apporte chaleur et protection à un campement en pleine nature. Avant de partir dans les terres sauvages, consultez un cuisinier expérimenté pour apprendre à en allumer un.",al={"pourquoi faut-il un feu de camp","cuisine feu de camp tente","tente et feu"}},{q="Où se trouve Sabot-de-Sang ?",a="Sabot-de-Sang se trouve au centre de Mulgore, au sud des Pitons-du-Tonnerre, sur les rives du Lac Taureau-de-pierre. Cette colonie taurène accueille chasseurs, cueilleurs et artisans, et offre aux voyageurs qui explorent les plaines de quoi se former, faire du commerce et obtenir des conseils.",al={"où se trouve sabot-de-sang","emplacement de sabot-de-sang","comment trouver chaw stronghide"}},{q="Faut-il savoir cuisiner pour tenir un bon campement ?",a="Il n’est pas nécessaire de savoir cuisiner pour coudre une tente en cuir, mais les cuisiniers apprennent aux voyageurs à allumer des feux de camp. Un feu complète un campement en plein air, réchauffe l’air de la nuit et permet de préparer des repas au cours des longs voyages.",al={"faut-il savoir cuisiner pour camper","faut-il savoir cuisiner","bases du feu de camp et de la cuisine"}},{q="Quels avantages une tente de campement offre-t-elle aux voyageurs ?",a="Une tente protège les voyageurs de la chaleur intense et des fortes pluies. S’y reposer les aide à rester en forme et vigilants pendant qu’ils explorent des contrées lointaines.",al={"avantages d’une tente de campement","pourquoi fabriquer une tente","à quoi sert une tente"}}},fp="27,181,28.219.0,28.228.0,17.253.0,42.140.0,51.167.0,44.162.0,42.141.0,35.247.0,56.202.0,53.147.0"}
P.entries["quest:97935"] = {n="Camping 101: Mining",s="Aux Pitons-du-Tonnerre, les mineurs apprennent à exercer leur métier en pleine nature. Brek Stonehoof leur enseigne à façonner une pierre d’aimant qui fortifie ceux qui se reposent près d’un feu de camp.",h="Aux Pitons-du-Tonnerre, les mineurs apprennent à exercer leur métier en pleine nature.",kw={"brek stonehoof","campement","feu de camp","camping 101: mining","pierre d’aimant","minage","pitons-du-tonnerre"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez donner aux personnes qui se reposent près de votre feu de camp la force d’une pierre d’aimant pour les batailles à venir.",["profession:Mining"]="En tant que mineur, vous pouvez mettre votre métier de récolte au service de la nature en préparant une pierre d’aimant pour un campement d’expédition.",["race:Tauren"]="En tant que tauren, vous pouvez apprendre auprès de Brek Stonehoof, au sommet des mesas des Pitons-du-Tonnerre, et tirer parti des connaissances taurens de la pierre et du travail de la terre."},sec={{t="Un labeur honnête sous terre",b="Le minage n’a peut-être pas l’éclat des arcanes supérieures, mais c’est un métier honnête que l’on exerce partout en Azeroth. Les mineurs extraient des minéraux utiles et de la pierre dense des parois rocheuses profondes. Ces matériaux servent à fabriquer des armes et des armures, et ont désormais aussi une utilité sur le terrain. Un mineur peut façonner la pierre pour créer des outils robustes destinés au campement en pleine nature."},{t="La pierre d’aimant des Pitons-du-Tonnerre",b="Brek Stonehoof, aux Pitons-du-Tonnerre, enseigne aux mineurs à exercer leur métier en pleine nature. Après avoir démontré leur maîtrise de la pioche, ils apprennent à façonner une pierre d’aimant de camp. Placée près d’un feu à ciel ouvert, elle donne vigueur et force au combat à ceux qui se préparent à manier une lame."}},faq={{q="Quel est l’effet de la pierre d’aimant sur un campement ?",a="Placée près d’un feu de camp, la pierre d’aimant donne vigueur et force au combat à ceux qui se rassemblent autour.",al={"avantage de la pierre d’aimant au campement","bonus de la pierre d’aimant","effet de la pierre d’aimant"}},{q="Qui est Brek Stonehoof ?",a="Brek Stonehoof vit aux Pitons-du-Tonnerre, la capitale des taurens. Il apprend aux mineurs expérimentés à fabriquer des outils de camping à partir de pierre et de minerai.",al={"emplacement de brek stonehoof","où se trouve brek stonehoof","qui enseigne l’objet de campement en minage"}},{q="Quand un mineur peut-il apprendre à fabriquer une pierre d’aimant ?",a="Le mineur doit d’abord démontrer sa maîtrise du métier avant que Brek Stonehoof lui enseigne à façonner une pierre d’aimant.",al={"quand apprendre à fabriquer une pierre d’aimant","niveau de minage requis pour la pierre d’aimant"}},{q="Qui profite le plus de la pierre d’aimant d’un mineur ?",a="Toute personne qui se prépare à manier une arme peut profiter de la force de la pierre d’aimant en se reposant près d’elle.",al={"qui profite de la pierre d’aimant","la pierre d’aimant est-elle pour le corps à corps"}},{q="Quel est le lien entre le minage et l’installation d’un campement ?",a="Le minage fournit du métal aux fondeurs et aux forgerons, et permet aux voyageurs de façonner des outils de pierre comme les pierres d’aimant, qui renforcent un campement en pleine nature.",al={"pourquoi miner pour le camping","comment le minage aide au campement"}},{q="Quel est le but de Camping 101: Mining ?",a="Aux Pitons-du-Tonnerre, les mineurs en herbe peuvent apprendre auprès de Brek Stonehoof à fabriquer des outils utiles à leur survie en pleine nature.",al={"aperçu de camping 101: mining","qu’est-ce que camping 101: mining"}}},fp="19,171,25.301.0,30.269.0,42.90.0,22.126.0,48.106.0,43.101.0,49.137.0,43.109.0"}
P.entries["quest:97936"] = {n="Camping 101: Skinning",s="À Mulgore, les dépeceurs apprennent à confectionner une Chaise du camp pour se reposer dans la nature. Yonn Deepcut enseigne cet art à Sabot-de-Sang, où les récolteurs de peaux expérimentés se préparent aux campements loin des villages.",h="À Mulgore, les dépeceurs apprennent à confectionner une Chaise du camp pour se reposer dans la nature.",kw={"sabot-de-sang","chaise du camp","feu de camp","camping 101","camping 101: skinning","mulgore","dépeçage","yonn deepcut"},ang={["faction:Horde"]="En tant que dépeceur de la Horde en Mulgore, vous pouvez vous rendre à Sabot-de-Sang et apprendre à fabriquer du matériel de campement avec les peaux que vous récoltez.",["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre auprès des maîtres des arts culinaires à faire un feu de camp pour votre campement.",["race:Tauren"]="En tant que dépeceur tauren, vous pouvez apprendre auprès de Yonn Deepcut, au cœur de Mulgore, à fabriquer des chaises avec les peaux des bêtes pour vous reposer dans la nature."},sec={{t="Les peaux de la nature sauvage",b="Les bêtes abattues fournissent des peaux et des fourrures que les dépeceurs peuvent transformer en équipement utile. Le cuir devient une armure, et les peaux d’animaux peuvent aussi servir à fabriquer des objets confortables pour la nature sauvage. Après de longues semaines à traverser des terres indomptées, les voyageurs peuvent se reposer sur un équipement fait de ces peaux et rester prêts au combat."},{t="Leçons à Sabot-de-Sang",b="À Mulgore, les dépeceurs se rendent à Sabot-de-Sang pour parler avec Yonn Deepcut. Après avoir prouvé qu’ils savent récolter les peaux des bêtes, Yonn leur apprend à assembler une Chaise du camp. Les habitants des villes et des villages n’apprécient pas que les voyageurs plantent leur tente dans leurs rues, alors ces chaises sont destinées aux séjours dans la nature. Un feu de camp complète le campement, et les cuisiniers locaux apprennent à en faire un."}},faq={{q="Qu’est-ce que Camping 101: Skinning ?",a="À Mulgore, Yonn Deepcut apprend aux dépeceurs à fabriquer une Chaise du camp à Sabot-de-Sang. D’abord, ils prouvent qu’ils savent récolter les peaux des bêtes.",al={"qu’est-ce que camping 101: skinning","quête de dépeçage pour camper","à quoi sert cette quête"}},{q="Qui enseigne la recette de la Chaise du camp ?",a="Yonn Deepcut apprend aux dépeceurs à fabriquer une Chaise du camp à Sabot-de-Sang, en Mulgore, après qu’ils ont prouvé leur savoir-faire dans la récolte des peaux des bêtes.",al={"qui enseigne la chaise du camp","à qui parler pour camper avec le dépeçage","où se trouve yonn deepcut"}},{q="À quoi sert une Chaise du camp ?",a="Une Chaise du camp vous offre un endroit confortable où vous reposer quand vous campez dans la nature. Vous asseoir vous aide à reprendre des forces et à rester prêt au combat.",al={"à quoi sert une chaise du camp","utilité de la chaise du camp","pourquoi fabriquer une chaise du camp"}},{q="Où peut-on installer un campement ?",a="Installez votre campement dans la nature. Les habitants des villes n’apprécient pas que les voyageurs plantent leur tente dans les villages.",al={"où puis-je installer un campement","puis-je camper en ville","chaise du camp en ville"}},{q="De quoi d’autre a-t-on besoin pour installer un campement ?",a="Un campement a aussi besoin d’un feu de camp. Les cuisiniers locaux et les maîtres des arts culinaires vous apprennent à en faire un.",al={"de quoi d’autre ai-je besoin pour camper","feu de camp nécessaire","faut-il un feu pour camper"}},{q="Où se trouve Sabot-de-Sang ?",a="Sabot-de-Sang se trouve en Mulgore. Ce village tauren abrite des artisans, notamment des maîtres dépeceurs.",al={"où se trouve sabot-de-sang","emplacement de sabot-de-sang"}}},fp="21,192,17.269.0,28.353.0,30.131.0,34.137.0,30.139.0,28.98.0,39.90.0,35.110.0"}
P.entries["quest:97938"] = {n="Camping 101: Alchemy",s="À Dolanaar, Cyndra Kindwhisper apprend aux alchimistes à aménager un campement. Sa leçon allie potions et survie en pleine nature, et leur montre à créer un Puits de mana pour les soigneurs et lanceurs de sorts itinérants.",h="À Dolanaar, Cyndra Kindwhisper apprend aux alchimistes à aménager un campement.",kw={"alchimie","campement","camping 101","camping 101: alchemy","cyndra kindwhisper","dolanaar","puits de mana","teldrassil"},ang={["faction:Alliance"]="Les alchimistes de l’Alliance qui parcourent Teldrassil sont envoyés à Dolanaar pour apprendre à créer des équipements magiques de campement et survivre en pleine nature.",["race:NightElf"]="En tant qu’herboriste ou alchimiste elfe de la nuit à Dolanaar, vous pouvez allier botanique naturelle et savoir-faire de campement pour soutenir les lanceurs de sorts en pleine nature."},sec={{t="L’alchimie sur le terrain",b="Les alchimistes apprennent à exercer leur art au-delà de l’établi. Cyndra Kindwhisper leur montre comment fabriquer des équipements de campement utiles pour soutenir un groupe en voyage dans la nature."},{t="Le Puits de mana de Dolanaar",b="À Dolanaar, les alchimistes qui maîtrisent les bases peuvent aller voir Cyndra Kindwhisper. Elle leur apprend à installer un Puits de mana au camp. Sa magie revigorante aide les soigneurs et les lanceurs de sorts à récupérer leur mana loin des tavernes et des villages."}},faq={{q="Qu’est-ce que Camping 101: Alchemy ?",a="Camping 101: Alchemy apprend aux alchimistes novices de Dolanaar à mettre leur savoir-faire au service du campement. Ils découvrent comment fabriquer des équipements utiles en pleine nature grâce à leurs talents de préparateurs de potions.",al={"qu’est-ce que camping 101 alchemy","quête camping 101 alchemy","quête d’alchimie et de campement"}},{q="Qui enseigne cette compétence de campement ?",a="Cyndra Kindwhisper enseigne aux alchimistes de Dolanaar, le village des Elfes de la nuit sur Teldrassil. Elle forme ceux qui ont fait leurs preuves dans la préparation de potions et la fabrication d’objets de campement spécialisés.",al={"qui est cyndra kindwhisper","lieu où se trouve cyndra kindwhisper","où se trouve cyndra kindwhisper"}},{q="Qu’est-ce qu’un Puits de mana ?",a="Un Puits de mana est une installation de campement fabriquée par un alchimiste. Il procure un regain d’énergie arcanique aux lanceurs de sorts et aux soigneurs qui doivent reconstituer leurs réserves en chemin.",al={"à quoi sert un puits de mana","objet de campement puits de mana","histoire du puits de mana"}},{q="Où cette quête vous mène-t-elle ?",a="Vous vous rendez à Dolanaar, un village des Elfes de la nuit au centre de Teldrassil. C’est un lieu de passage pour les jeunes aventuriers et les artisans qui quittent Sombrevallon.",al={"où se trouve dolanaar","comment aller à dolanaar","emplacement de dolanaar"}},{q="Qui bénéficie des installations de campement des alchimistes ?",a="Les soigneurs et les lanceurs de sorts itinérants tirent le plus grand bénéfice des Puits de mana. Ces sources revigorantes les aident à récupérer au cours de longs voyages loin des villes.",al={"qui bénéficie des puits de mana","qui utilise les puits de mana","puits de mana pour lanceurs de sorts"}},{q="Que faut-il maîtriser avant d’apprendre à fabriquer un Puits de mana ?",a="Les alchimistes doivent d’abord faire leurs preuves dans la préparation de potions et les bases de l’alchimie. Cyndra Kindwhisper leur apprend ensuite à assembler des équipements de campement, comme un Puits de mana.",al={"quand apprendre à fabriquer le puits de mana","conditions requises pour camping 101","niveau de compétence requis"}}},fp="20,198,26.192.0,25.227.0,29.165.0,31.182.0,20.155.0,31.144.0,51.140.0,54.154.0"}
P.entries["quest:97940"] = {n="Camping 101: Enchanting",s="Un guide de la Clairière de l'Oracle vous oriente vers l’apprentissage d’un savoir-faire d’enchanteur pour le campement. Un Luth enchanté peut vous divertir lors d’un séjour en pleine nature.",h="Un guide de la Clairière de l'Oracle vous oriente vers l’apprentissage d’un savoir-faire d’enchanteur pour le...",kw={"alanna raveneye","objet de campement","camping","luth enchanté","enchantement","la clairière de l'oracle","teldrassil"},ang={["profession:Tailoring"]="En tant qu’enchanteur, vous pouvez apprendre à fabriquer un Luth enchanté pour votre campement après avoir démontré votre maîtrise du métier."},sec={{t="Un objet de campement",b="Un enchanteur peut fabriquer un objet utile pour votre campement, et l’on vous envoie auprès d’Alanna Raveneye à la Clairière de l'Oracle. Elle peut vous apprendre à fabriquer un Luth enchanté une fois que vous avez démontré votre maîtrise du métier. Il est destiné à vous divertir pendant vos moments de repos avant de reprendre la route."}},faq={{q="Qui peut m’apprendre à fabriquer un Luth enchanté ?",a="Alanna Raveneye, à la Clairière de l'Oracle, peut vous apprendre à fabriquer un Luth enchanté une fois que vous avez démontré votre maîtrise du métier.",al={"alanna raveneye","qui enseigne le luth","maître du luth"}},{q="À quoi sert le Luth enchanté ?",a="Le Luth enchanté est un objet de campement destiné à vous divertir pendant vos moments de repos en pleine nature.",al={"utilité du luth","luth de campement","pourquoi un luth enchanté"}},{q="Pourquoi les enchanteurs sont-ils les bienvenus dans les campements ?",a="Les enchanteurs peuvent améliorer les choses, ils sont donc les bienvenus dans les campements en pleine nature.",al={"enchanteurs et camping","enchantement au campement","camping et enchantement"}},{q="Où puis-je apprendre à fabriquer cet objet de campement ?",a="Vous pouvez apprendre auprès d’Alanna Raveneye à la Clairière de l'Oracle, en Teldrassil.",al={"maître de la clairière de l'oracle","où est alanna","lieu d’enchantement"}}},fp="23,152,12.295.0,36.123.0,31.97.0,36.76.0,36.69.0"}
P.entries["quest:97942"] = {n="Camping 101: First Aid",s="À Dolanaar, les voyageurs apprennent à préparer une Trousse de premiers soins pour camper. Byancie leur montre comment soigner les blessures loin des guérisseurs et trouver un lieu de campement.",h="À Dolanaar, les voyageurs apprennent à préparer une Trousse de premiers soins pour camper.",kw={"byancie","feu de camp","camping","dolanaar","médecin de terrain","premiers soins","trousse de premiers soins","chasseur"},ang={["class:Hunter"]="En tant que chasseur, vous pouvez associer la survie en pleine nature aux premiers soins pour soigner vos blessures loin de la civilisation et des guérisseurs des villes.",["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre à allumer les feux nécessaires au campement et à sa chaleur, ainsi qu’à préparer les aliments qui vous nourrissent."},sec={{t="Médecine de terrain en pleine nature",b="Dans les contrées sauvages, les bêtes mordent et les terrains rocailleux blessent. Les rôdeurs et autres voyageurs peuvent se trouver loin des villes et de leurs fournitures médicales. Une Trousse de premiers soins leur permet de soigner les blessures légères dans un campement au bord de la route, avant qu’elles ne s’aggravent sous le ciel ouvert."},{t="Leçons à Dolanaar",b="À Dolanaar, Byancie apprend aux voyageurs formés au triage à préparer des fournitures médicales pour les sentiers difficiles. Les habitants n’autorisent ni tentes ni matériel éparpillé au centre d’une colonie. Les campeurs doivent s’enfoncer dans la forêt avant d’établir leur camp."},{t="Le foyer du camp",b="Un feu à ciel ouvert est le point de départ d’un camp fonctionnel. Allumez un feu de camp avant de sortir vos trousses médicales ou votre literie ; il apporte chaleur et protection. Savoir allumer et entretenir un feu est essentiel pour survivre dans la nature. Les maîtres recommandent de demander à un cuisinier de vous apprendre à en allumer un avant de vous occuper d’un campement sauvage."}},faq={{q="Qui est Byancie ?",a="Byancie enseigne à Dolanaar, une colonie de Teldrassil. Elle montre aux voyageurs formés à la médecine comment préparer des Trousses de premiers soins pour camper en pleine nature.",al={"qui est byancie","emplacement de byancie","où se trouve byancie"}},{q="Qu’est-ce qu’une Trousse de premiers soins de camping ?",a="Une Trousse de premiers soins de camping est un ensemble de fournitures médicales préparé par des aventuriers formés aux premiers soins. Dans un campement établi, elle leur permet de soigner les blessures et de prodiguer des soins sur le terrain.",al={"qu’est-ce qu’une trousse de premiers soins de camping","comment fonctionne une trousse de premiers soins","trousse de premiers soins de camping"}},{q="Où peut-on établir un camp ?",a="Établissez votre camp en pleine nature, loin des limites des villes. Les habitants et les gardes n’apprécient pas les campements temporaires au centre des colonies ou sur les places des villes.",al={"peut-on camper en ville","pourquoi camper hors de la ville","règles de campement"}},{q="Pourquoi faut-il un feu de camp ?",a="Un feu de camp apporte chaleur, lumière et sécurité à un campement sauvage. Les cuisiniers et les maîtres cuisiniers peuvent vous apprendre à en allumer un.",al={"pourquoi faut-il un feu de camp","feu de camp et cuisine","obligation d’avoir un feu de camp"}},{q="Pourquoi les premiers soins sont-ils pratiques pour les chasseurs ?",a="Les chasseurs voyagent souvent seuls dans des contrées reculées, loin des guérisseurs et des templiers. Les premiers soins leur permettent de soigner leurs blessures pendant qu’ils suivent le gibier ou survivent à une embuscade.",al={"pourquoi les premiers soins pour les chasseurs","soins des chasseurs"}},{q="Comment apprendre à fabriquer une Trousse de premiers soins de camping ?",a="Montrez que vous maîtrisez les bases des premiers soins, puis demandez à Byancie, à Dolanaar, de vous apprendre à préparer une Trousse de premiers soins de camping.",al={"comment obtenir une trousse de premiers soins","apprendre à fabriquer une trousse de premiers soins"}}},fp="22,148,27.249.0,19.239.0,22.284.0,15.151.0,32.180.0,28.150.0,38.116.0,50.152.0,50.113.0"}
P.entries["quest:97943"] = {n="Camping 101: Fishing",s="À Darnassus, Astaia apprend aux pêcheurs à fabriquer un Bocal à poisson pour égayer leur campement sauvage.",h="À Darnassus, Astaia apprend aux pêcheurs à fabriquer un Bocal à poisson pour égayer leur campement sauvage.",kw={"astaia","feu de camp","camping","camping 101: fishing","campement","darnassus","bocal à poisson","pêche"},ang={["faction:Alliance"]="En tant que pêcheur de l’Alliance, vous pouvez rendre visite à Astaia à Darnassus pour apprendre à fabriquer des objets de campement.",["profession:Cooking"]="Votre formation de base en cuisine vous apprend à préparer le feu de camp dont chaque campement a besoin."},sec={{t="Confort au campement",b="En parcourant Kalimdor, les pêcheurs peuvent mettre à profit leurs heures paisibles au bord de l’eau. À Darnassus, Astaia apprend aux pêcheurs expérimentés à transformer leurs prises et leur savoir-faire en objets pratiques pour le campement. Le Bocal à poisson, exposé au camp, apporte de la gaieté aux voyageurs fatigués."},{t="Le nécessaire en pleine nature",b="Un campement sauvage exige plus que du matériel de pêche. Vous ne pouvez pas en installer un dans un centre-ville bondé ou un quartier urbain : il vous faut trouver un terrain dégagé. Chaque campement a aussi besoin d’un feu chaleureux. Rendez-vous auprès d’un maître cuisinier pour apprendre à allumer un feu avant de vous installer pour la nuit."}},faq={{q="Qui vous apprend à fabriquer des objets de camping liés à la pêche ?",a="À Darnassus, Astaia apprend aux pêcheurs expérimentés à fabriquer un Bocal à poisson décoratif pour le campement, après qu’ils ont prouvé leur maîtrise de la pêche.",al={"qui enseigne la pêche de camping","où se trouve astaia","maître du bocal à poisson"}},{q="À quoi sert un Bocal à poisson au campement ?",a="Un Bocal à poisson apporte réconfort et joie aux aventuriers au repos. Un campeur heureux et bien reposé combat avec une vigueur renouvelée lors de ses voyages en pleine nature.",al={"à quoi sert le bocal à poisson","utilité du bocal à poisson au camp","aménagement de camp bocal à poisson"}},{q="Pouvez-vous installer un campement à Darnassus ou dans d’autres villes ?",a="Vous ne pouvez pas installer un campement au cœur d’une agglomération ni sur une place centrale. Partez en pleine nature pour camper et placer des aménagements comme un Bocal à poisson.",al={"peut-on camper à darnassus","où installer son campement","campement en ville"}},{q="Que faut-il avant d’installer un campement ?",a="Un feu de camp rudimentaire est indispensable. Rendez-vous auprès d’un maître cuisinier pour apprendre à en allumer un avant d’établir un campement sauvage.",al={"nécessaire pour un campement","comment établir un campement","feu de camp indispensable"}},{q="Faut-il savoir pêcher pour apprendre à fabriquer un Bocal à poisson ?",a="Oui. Un aventurier doit d’abord prouver sa maîtrise de la pêche pour apprendre cet artisanat auprès d’Astaia.",al={"maîtrise de la pêche et camping","quand apprendre le bocal à poisson"}},{q="Pourquoi les aventuriers installent-ils des campements dans la nature ?",a="Un campement offre aux voyageurs en pleine nature un lieu de repos et des commodités qui remontent le moral, comme un Bocal à poisson. Ils peuvent ainsi rester reposés et en état d’affronter les dangers de la nature.",al={"pourquoi camper dans wow forever","avantages du camping"}}},fp="20,180,23.262.0,22.270.0,55.129.0,44.133.0,55.148.0,42.134.0,60.96.0,44.157.0"}
P.entries["quest:97944"] = {n="Camping 101: Herbalism",s="À Dolanaar, les herboristes apprennent à fabriquer du matériel de camp avec les plantes qu’ils récoltent. Malorne Bladeleaf enseigne aux récolteurs expérimentés à fabriquer des Bougies d’encens, qui soutiennent soigneurs et lanceurs de sorts près du feu de camp.",h="À Dolanaar, les herboristes apprennent à fabriquer du matériel de camp avec les plantes qu’ils récoltent.",kw={"camping","camping 101: herbalism","dolanaar","herboristerie","bougie d’encens","malorne bladeleaf","teldrassil"},ang={["faction:Alliance"]="En tant qu’herboriste de l’Alliance près de Teldrassil, vous pouvez apprendre les techniques de survie en milieu naturel auprès des adeptes elfes de la nuit de Dolanaar.",["profession:Herbalism"]="En tant qu’herboriste, vous pouvez utiliser les plantes récoltées pour survivre dans la nature comme pour l’alchimie, et fabriquer du matériel de camp tel que des Bougies d’encens.",["race:NightElf"]="En tant qu’elfe de la nuit, vous partagez une tradition de connaissance des propriétés réparatrices des plantes de la nature, enseignée dans des colonies comme Dolanaar."},sec={{t="Plus que cueillir des fleurs",b="L’herboristerie peut être utile aux voyageurs autrement qu’en récoltant des fleurs à vendre ou pour les alchimistes. Dans la nature, les plantes récoltées peuvent devenir du matériel de camp pratique. Les préparer pour survivre permet à votre récolte de vous accompagner lors de longs voyages sur le terrain."},{t="La flamme apaisante de Dolanaar",b="À Dolanaar, Malorne Bladeleaf apprend aux herboristes expérimentés à fabriquer une Bougie d’encens. Sa flamme apaisante crée un refuge concentré et réconfortant autour du feu de camp. Les soigneurs et les lanceurs de sorts apprécient sa présence revitalisante lorsqu’ils restaurent leurs énergies magiques entre deux périls."}},faq={{q="Quel est le but de cette quête ?",a="Les herboristes expérimentés se rendent auprès de Malorne Bladeleaf à Dolanaar pour apprendre à fabriquer du matériel de camp avec les plantes récoltées.",al={"qu’est-ce que camping 101 herboristerie","quête d’herboristerie et de camping"}},{q="Quel effet une Bougie d’encens a-t-elle sur un camp ?",a="Une Bougie d’encens remonte le moral et crée une atmosphère apaisante et propice à la concentration autour d’un feu de camp.",al={"effet bougie d’encens","avantage bougie d’encens"}},{q="Qui est Malorne Bladeleaf ?",a="Malorne Bladeleaf apprend aux herboristes expérimentés de Dolanaar à fabriquer du matériel de camp, notamment des Bougies d’encens.",al={"qui enseigne à fabriquer une bougie d’encens","qui est malorne bladeleaf","bladeleaf dolanaar"}},{q="Où cette quête vous mène-t-elle ?",a="Vous vous rendez à Dolanaar, une colonie d’elfes de la nuit sur Teldrassil et un centre pour les voyageurs, les instructeurs et les artisans des bois.",al={"où se trouve dolanaar","emplacement de dolanaar"}},{q="Pourquoi les Bougies d’encens sont-elles utiles aux utilisateurs de magie ?",a="Une Bougie d’encens crée un lieu serein et propice à la concentration, où soigneurs et lanceurs de sorts peuvent restaurer leur moral et leurs forces magiques pendant leurs voyages dans la nature.",al={"qui bénéficie de la bougie d’encens","bougie d’encens pour lanceurs de sorts"}},{q="Que faut-il avant que Malorne Bladeleaf vous enseigne ?",a="Vous devez avoir suffisamment de pratique en herboristerie pour que Malorne Bladeleaf vous apprenne à fabriquer du matériel de camp.",al={"quand apprendre à fabriquer une bougie d’encens","compétence requise en herboristerie pour le camping"}}},fp="22,203,25.245.0,30.276.0,34.112.0,42.93.0,25.106.0,31.118.0,46.155.0,57.107.0"}
P.entries["quest:97946"] = {n="Camping 101: Leatherworking",s="Sur Teldrassil, les travailleurs du cuir peuvent apprendre à fabriquer un abri pour la route. Trouvez Nadyia Maneweaver sur le chemin entre Dolanaar et Darnassus, où elle enseigne l’art des tentes qui gardent les voyageurs au sec et au frais.",h="Sur Teldrassil, les travailleurs du cuir peuvent apprendre à fabriquer un abri pour la route.",kw={"feu de camp","camping","darnassus","dolanaar","travail du cuir","nadyia maneweaver","tente","nature sauvage"},ang={["class:Rogue"]="En tant que Voleur, vous comptez sur le repos et un abri en pleine nature pour rester affûté. Une tente en cuir peut vous procurer les deux.",["profession:Cooking"]="Pour établir un véritable campement, il vous faut un feu de camp bien chaud. Les maîtres des cuisiniers de tout le pays vous apprennent à en allumer un."},sec={{t="Un abri dans la nature sauvage",b="À travers Kalimdor, le ciel ouvert peut réserver un temps rude. Les travailleurs du cuir expérimentés apprennent à façonner des peaux en abris solides, offrant aux voyageurs un lieu sûr pour se reposer où que mène la route. Une tente permet aux vagabonds de trouver le repos dont ils ont besoin, loin des auberges."},{t="La route depuis Dolanaar",b="Nadyia Maneweaver enseigne aux travailleurs du cuir confirmés sur le chemin forestier entre Dolanaar et Darnassus. Elle leur montre comment coudre une tente solide pour la route. Une tente a besoin d’un feu de camp pour former un véritable campement, et les cuisiniers enseignent cette technique. Installez l’abri en pleine nature, à l’écart des rues des villes."}},faq={{q="Qui enseigne cette compétence de camping ?",a="Nadyia Maneweaver enseigne la compétence de camping sur la route qui mène de Dolanaar vers Darnassus, sur Teldrassil.",al={"qui donne camping 101 leatherworking","qui enseigne camping 101","nadyia maneweaver"}},{q="Qu'apprennent les travailleurs du cuir grâce à cette quête ?",a="Les travailleurs du cuir apprennent à fabriquer une tente qui garde les voyageurs au frais par temps chaud et au sec sous la pluie.",al={"qu'enseigne camping 101","recette de tente","qu'apprend-on avec camping 101"}},{q="Où pouvez-vous planter une tente de campement ?",a="Dressez les tentes en pleine nature, hors des villages et des centres-villes.",al={"où puis-je planter ma tente","peut-on monter une tente en ville","camper dans les villes"}},{q="Que faut-il d'autre pour installer un campement ?",a="Un campement nécessite un feu de camp allumé ainsi qu’une tente. Les maîtres des cuisiniers enseignent l’art d’en allumer un.",al={"que faut-il pour un campement","prérequis feu de camp","faut-il un feu de camp pour une tente"}},{q="Pourquoi posséder une tente est-il utile aux voyageurs ?",a="Une tente abrite les voyageurs des intempéries et leur permet de se reposer, les aidant à rester vigilants loin des auberges.",al={"pourquoi fabriquer une tente","avantage du repos sous une tente","pourquoi camper"}},{q="Où se trouve Nadyia Maneweaver ?",a="Nadyia Maneweaver se trouve sur la route principale qui mène de Dolanaar vers Darnassus, la capitale des Elfes de la nuit.",al={"où se trouve nadyia maneweaver","emplacement de nadyia","maître sur la route de darnassus"}}},fp="27,210,25.256.0,22.297.0,31.104.0,45.97.0,32.73.0,39.94.0,42.102.0,35.95.0"}
P.entries["quest:97948"] = {n="Camping 101: Mining",s="Vous êtes envoyé à Auberdine pour découvrir un nouvel usage du minage. Là, Kurdram Stonehammer apprend aux mineurs expérimentés à façonner une pierre de magnétite qui renforce les alliés réunis autour d’un feu de camp.",h="Vous êtes envoyé à Auberdine pour découvrir un nouvel usage du minage.",kw={"auberdine","art du campement","feu de camp","camping 101: mining","sombrivage","kurdram stonehammer","pierre de magnétite","minage"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez trouver Kurdram Stonehammer à Auberdine, sur les côtes de Sombrivage. Il enseigne l’art du campement aux voyageurs de passage dans le nord de Kalimdor.",["profession:Mining"]="En tant que mineur, vous pouvez façonner la pierre brute en une pierre de magnétite de campement qui aide les voyageurs sur la route et renforce les combattants de première ligne."},sec={{t="L’art pratique de la terre et de la pierre",b="Le minage ne sert pas qu’à fondre des lingots et à marteler des armures. Les prospecteurs expérimentés façonnent la terre brute et le minerai magnétique pour en faire du matériel de campement, afin que les voyageurs puissent établir des foyers bien fortifiés en pleine nature. Cette introduction présente aux mineurs un usage pratique de leur métier."},{t="Un mentor à Auberdine",b="À Auberdine, ville côtière de Sombrivage, les mineurs prometteurs vont trouver Kurdram Stonehammer. Dès qu’un mineur a prouvé son dévouement et son savoir-faire, Kurdram lui enseigne à fabriquer une pierre de magnétite de campement. Placée près d’un feu, elle renforce les compagnons d’armes rassemblés à proximité."}},faq={{q="Qu’est-ce que Camping 101: Mining ?",a="Vous êtes envoyé à Auberdine pour trouver Kurdram Stonehammer. Dès que vous démontrez votre savoir-faire en minage, il vous apprend à fabriquer une pierre de magnétite qui renforce un campement.",al={"qu’est-ce que cette quête","objectif de camping 101: mining","que faire pour camping 101: mining"}},{q="Qui est Kurdram Stonehammer ?",a="Kurdram Stonehammer est un artisan d’Auberdine, sur la côte de Sombrivage. Il apprend aux mineurs qualifiés à fabriquer du matériel de campement, notamment des pierres de magnétite.",al={"qui est kurdram stonehammer","entraîneur de minage à auberdine","emplacement de kurdram stonehammer"}},{q="Qu’est-ce qu’une pierre de magnétite de campement ?",a="Les mineurs fabriquent une pierre de magnétite de campement à placer près d’un feu de camp. Elle renforce les combattants au corps à corps rassemblés à proximité.",al={"à quoi sert une pierre de magnétite","effet de la pierre de magnétite de campement","amélioration de vigueur au campement"}},{q="Où se déroule cette quête ?",a="Auberdine est un port côtier de Sombrivage, un port et un carrefour de l’Alliance dans le nord de Kalimdor. Kurdram Stonehammer y vit et y enseigne l’art du campement aux mineurs.",al={"où se trouve auberdine","emplacement d’auberdine","comment aller à auberdine"}},{q="Qui bénéficie d’une pierre de magnétite de campement ?",a="Les combattants au corps à corps apprécient particulièrement une pierre de magnétite de campement. Son pouvoir donne plus de vigueur au combat aux voyageurs réunis autour du feu.",al={"qui bénéficie de la pierre de magnétite","la pierre de magnétite est-elle utile aux guerriers","cible de l’amélioration de la pierre de magnétite"}},{q="Quand pouvez-vous apprendre à fabriquer la pierre de magnétite ?",a="Kurdram Stonehammer enseigne la fabrication des pierres de magnétite dès que vous démontrez un niveau suffisant en minage.",al={"quand apprendre à fabriquer une pierre de magnétite","niveau de minage requis pour une pierre de magnétite de campement","condition de compétence"}}},fp="19,180,36.263.0,21.270.0,28.148.0,27.146.0,25.105.0,33.159.0,35.134.0,42.88.0"}
P.entries["quest:97949"] = {n="Camping 101: Skinning",s="Dans la nature, apprenez à fabriquer une Chaise du camp et à préparer un campement. Il vous faut des peaux, un terrain dégagé loin des villes et un feu de camp.",h="Dans la nature, apprenez à fabriquer une Chaise du camp et à préparer un campement.",kw={"chaise du camp","feu de camp","camping 101","camping 101: skinning","cuisine","dépeçage","nature"},ang={["profession:Cooking"]="Apprenez les bases de la cuisine auprès d'un maître des cuisiniers. Savoir allumer un feu de camp est essentiel pour installer un campement dans la nature."},sec={{t="Le confort sur la route",b="Les peaux récoltées en chemin peuvent servir. Avec les matériaux à votre disposition, apprenez à fabriquer une Chaise du camp portable pour vos voyages à travers Azeroth. Les habitants n'apprécient guère que les voyageurs campent au cœur des villes : pratiquez donc cet artisanat dans la nature."},{t="Le feu de camp indispensable",b="Dans la nature, le feu de camp est la première chose nécessaire à un campement. Ses flammes apportent chaleur et protection contre les éléments. Si vous n'avez pas appris les bases de la cuisine, rendez-vous auprès d'un maître des cuisiniers pour apprendre à allumer un feu en pleine nature."}},faq={{q="Qu'apprend-on dans Camping 101: Skinning ?",a="Vous apprenez à fabriquer une Chaise du camp portable pour vous reposer dans la nature.",al={"qu'est-ce que j'obtiens","que donne camping 101","fabriquer une chaise du camp"}},{q="Peut-on installer un campement en ville ?",a="Les habitants s'opposent généralement aux campements sur les places et dans les rues des villes. Partez dans la nature pour installer le vôtre.",al={"peut-on camper en ville","camper à hurlevent","camping dans les villes"}},{q="Faut-il un feu de camp pour camper ?",a="Oui. Un campement nécessite un feu de camp allumé. Les maîtres des cuisiniers d'Azeroth peuvent vous apprendre à en allumer un.",al={"faut-il un feu pour camper","comment allumer un feu de camp","feu pour chaise du camp"}},{q="Où apprendre à allumer un feu de camp ?",a="Les maîtres des cuisiniers peuvent vous apprendre à préparer des repas et à allumer un simple feu de camp avec du silex et du bois.",al={"qui apprend à allumer un feu","maître des cuisiniers et feu","où apprendre à allumer un feu"}},{q="Pourquoi faut-il partir dans la nature pour camper ?",a="Les espaces dégagés dans la nature vous permettent d'installer un campement sans déranger les habitants ni bloquer les routes et les hameaux des environs.",al={"pourquoi aller dans la nature","où utiliser une chaise du camp","où installer un campement"}},{q="Quel est le lien entre le dépeçage et la fabrication d'une chaise de camp ?",a="Les dépeceurs travaillent les peaux et le cuir prélevés sur les bêtes. Ces matériaux conviennent à des sièges portables pour l'extérieur, comme une Chaise du camp.",al={"lien entre dépeçage et camping","pourquoi le dépeçage pour une chaise","dépeçage et chaise du camp"}}},fp="21,132,21.243.0,22.217.0,45.70.0,30.105.0,36.98.0,43.95.0,53.124.0,48.118.0"}
P.entries["quest:97950"] = {n="Camping 101: Tailoring",s="Un couturier peut apprendre à fabriquer une Rallying Banner pour un camp. Trianna, à Darnassus, enseigne le patron une fois votre savoir-faire en couture démontré.",h="Un couturier peut apprendre à fabriquer une Rallying Banner pour un camp.",kw={"feu de camp","campement","darnassus","bannière de faction","rallying banner","couture","trianna"},ang={["profession:Tailoring"]="En tant que couturier, vous pouvez apprendre à confectionner une Rallying Banner pour votre camp après avoir démontré votre savoir-faire."},sec={{t="Une bannière pour le camp",b="Quelqu’un qui apprécie la couture vous oriente vers Trianna, à Darnassus. Elle peut vous apprendre à confectionner une Bannière de faction pour votre camp une fois votre maîtrise de la couture démontrée. Une bannière peut renforcer l’inspiration et le moral sur un champ de bataille, et sa confection est à la portée d’un couturier habile."},{t="Installer un camp",b="Grâce à l’enseignement de Trianna, vous pouvez confectionner une Rallying Banner. Pour l’essayer, trouvez un endroit en pleine nature, car la plupart des gens n’aiment pas les camps au milieu de la ville. Prévoyez aussi un feu de camp ; un cuisinier peut vous apprendre à en faire un."}},faq={{q="Qui enseigne la confection d’une bannière de camp ?",a="Trianna, à Darnassus, peut vous apprendre à confectionner une Bannière de faction pour votre camp une fois votre maîtrise de la couture démontrée.",al={"couturier bannière maître","trianna couture","bannière de camp maître"}},{q="Que peut confectionner un couturier pour un camp ?",a="Un couturier habile peut apprendre à confectionner une Rallying Banner pour un camp.",al={"couturier objet de camp","couture confection de camp","quelle bannière couture"}},{q="Pourquoi fabriquer une Rallying Banner ?",a="Une bannière inspirante peut vous aider à garder votre énergie, et l’inspiration comme le moral comptent sur un champ de bataille.",al={"utilité de la bannière","rallying banner pourquoi","bannière moral"}},{q="Où puis-je tester mon installation de camp ?",a="Le conseil donné à la fin est d’essayer la bannière en pleine nature, car la plupart des gens n’aiment pas les camps en centre-ville.",al={"où tester la bannière","endroit où camper","lieu pour tester la bannière"}},{q="Ai-je besoin d’un feu de camp ?",a="Un camp a besoin d’un feu de camp, et la plupart des cuisiniers peuvent vous apprendre à en faire un.",al={"feu de camp pour camper","feu nécessaire","comment faire un feu de camp"}}},fp="22,137,17.279.0,15.217.0,36.115.0,34.65.0,27.104.0,31.114.0,21.66.0"}
P.entries["quest:97951"] = {n="Camping 101: Alchemy",s="Dans votre campement, les alchimistes peuvent apprendre à fabriquer un Puits de mana. Carolai Anise, à Brill, enseigne cet art lorsque vous avez fait vos preuves en alchimie.",h="Dans votre campement, les alchimistes peuvent apprendre à fabriquer un Puits de mana.",kw={"alchimiste","alchimie","brill","campement","feu de camp","bases du camping","carolai anise","puits de mana"},sec={{t="Un camp pour les breuvages",b="Carolai Anise, à Brill, apprend aux alchimistes à fabriquer un Puits de mana pour leur campement. Une fois cet art appris, vous pouvez camper dans la nature. Il vous faut d’abord un feu de camp, que les cuisiniers peuvent vous apprendre à fabriquer."}},faq={{q="Qui m’apprend à fabriquer un Puits de mana ?",a="Carolai Anise, à Brill, peut vous apprendre à fabriquer un Puits de mana lorsque vous avez fait vos preuves en alchimie.",al={"maître du puits de mana","qui enseigne le puits de mana","carolai anise alchimie"}},{q="À quoi sert un Puits de mana ?",a="Un Puits de mana est un objet de campement que vous pouvez fabriquer en tant qu’alchimiste. Son goût revigorant attire les soigneurs et les lanceurs de sorts.",al={"utilité du puits de mana","effet du puits de mana","objet de campement de mana"}},{q="Où puis-je apprendre à fabriquer un Puits de mana ?",a="Carolai Anise, à Brill, peut vous apprendre à fabriquer un Puits de mana.",al={"emplacement du puits de mana","maître d’alchimie à brill","où se trouve carolai"}},{q="De quoi ai-je besoin avant d’installer un campement ?",a="Vous avez besoin d’un feu de camp avant d’installer votre campement. La plupart des cuisiniers peuvent vous apprendre à en fabriquer un.",al={"feu de camp nécessaire","comment installer un campement","bases du campement"}}},fp="20,135,16.203.0,36.95.0,24.120.0,38.57.0,38.85.0"}
P.entries["quest:97952"] = {n="Camping 101: Blacksmithing",s="Un forgeron peut apprendre à fabriquer une Meule à aiguiser à utiliser au camp. Basil Frye, à Fossoyeuse, peut vous l’enseigner une fois que vous avez démontré votre maîtrise du métier.",h="Un forgeron peut apprendre à fabriquer une Meule à aiguiser à utiliser au camp.",kw={"basil frye","forge","camp","voleur","meule à aiguiser","fossoyeuse","guerrier"},ang={["class:Rogue"]="Une Meule à aiguiser au camp vous permet d’aiguiser votre arme.",["class:Warrior"]="Une Meule à aiguiser au camp vous permet d’aiguiser votre arme.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez apprendre à fabriquer une Meule à aiguiser à utiliser au camp."},sec={{t="Le camp d’un forgeron",b="On vous demande de parler à Basil Frye, à Fossoyeuse, d’un objet de camp lié à la forge. Vous devez démontrer votre maîtrise du métier avant qu’il vous apprenne à fabriquer une Meule à aiguiser. Au camp, la meule permet aux guerriers et aux voleurs à proximité d’aiguiser leurs armes."}},faq={{q="Que peut m’apprendre Basil Frye ?",a="Basil Frye peut vous apprendre à fabriquer une Meule à aiguiser à utiliser au camp, une fois que vous avez démontré votre maîtrise de la forge.",al={"basil frye forge","meule à aiguiser","objet de camp forgeron"}},{q="À quoi sert une Meule à aiguiser ?",a="Une Meule à aiguiser dans votre camp permet aux guerriers et aux voleurs à proximité d’aiguiser leurs armes.",al={"à quoi sert la meule","aiguiser les armes","utilisation de la meule à aiguiser"}},{q="Où trouver Basil Frye ?",a="Basil Frye se trouve à Fossoyeuse.",al={"emplacement de basil","où est basil","basil frye fossoyeuse"}}},fp="26,152,14.264.0,29.119.0,32.83.0,27.27.0"}
P.entries["quest:97953"] = {n="Camping 101: Enchanting",s="À Brill, Vance Undergloom apprend aux enchanteurs à fabriquer un Luth enchanté pour le camp. Montrez d’abord votre maîtrise de votre compétence.",h="À Brill, Vance Undergloom apprend aux enchanteurs à fabriquer un Luth enchanté pour le camp.",kw={"brill","camp","bases du camping","luth enchanté","enchanteur","enchantement","vance undergloom"},ang={["profession:Tailoring"]="En tant qu’enchanteur, vous pouvez apprendre à fabriquer un Luth enchanté pour le camp après avoir montré votre maîtrise de votre compétence."},sec={{t="Un compagnon de camp",b="Dans un camp en pleine nature, les enchanteurs peuvent apprendre à fabriquer un Luth enchanté. Emportez-le pour agrémenter vos séjours loin des sentiers."}},faq={{q="Que puis-je apprendre à fabriquer ?",a="Vous pouvez apprendre à fabriquer un Luth enchanté pour votre camp.",al={"luth enchanté","objet d’enchantement de camping","ce que vance enseigne"}},{q="Qui m’enseigne à fabriquer le luth ?",a="Vance Undergloom, à Brill, peut vous apprendre à fabriquer un Luth enchanté.",al={"qui est vance","vance undergloom","maître du luth"}},{q="Où trouver Vance Undergloom ?",a="Vance Undergloom se trouve à Brill.",al={"où est vance","emplacement de vance","enchanteur à brill"}},{q="Que dois-je faire avant de parler à Vance ?",a="Montrez votre maîtrise de votre compétence avant d’apprendre à fabriquer cet objet de camping.",al={"condition de compétence","montrer sa maîtrise","condition d’enchantement"}},{q="Pourquoi emporter un Luth enchanté au camp ?",a="Le Luth enchanté vous divertira pendant votre séjour au camp.",al={"utilité du luth","divertissement au camp","pourquoi le luth enchanté"}}},fp="23,120,16.147.0,26.55.0,30.67.0,33.29.0,42.74.0,36.61.0"}
P.entries["quest:97955"] = {n="Camping 101: First Aid",s="Dans les camps en pleine nature, Camping 101: First Aid aide les soigneurs à se préparer aux blessures. À Brill, Nurse Neela apprend aux praticiens expérimentés à fabriquer une Trousse de premiers soins pour soigner les blessures loin des terres habitées.",h="Dans les camps en pleine nature, Camping 101: First Aid aide les soigneurs à se préparer aux blessures.",kw={"brill","feu de camp","campement","camping 101","premiers soins","trousse de premiers soins","nurse neela","clairières de tirisfal"},ang={["faction:Horde"]="Nurse Neela enseigne à Brill, la ville des Réprouvés dans les Clairières de Tirisfal, offrant aux voyageurs de la Horde une source locale de formation.",["profession:Cooking"]="Les instructeurs de cuisine vous apprennent à construire un feu de camp rudimentaire. Il vous en faut un avant d’installer un campement en pleine nature ou d’y ajouter des équipements médicaux.",["race:Undead"]="En tant que Mort-vivant, vous pouvez vous tourner vers Nurse Neela, à Brill, pour adapter vos compétences en médecine à la survie dans les terres dévastées de Lordaeron."},sec={{t="Les soins sur le terrain",b="Loin des colonies protégées, les bêtes et les factions rivales mettent les voyageurs en danger. Un soigneur formé à First Aid peut apprendre à assembler une Trousse de premiers soins pour un camp en pleine nature. Elle permet aux voyageurs de soigner les blessures loin des terres habitées."},{t="Une formation à Brill",b="À Brill, Nurse Neela apprend aux voyageurs à mettre leurs compétences médicales au service du camp. Ceux qui maîtrisent les bandages et les soins peuvent apprendre à fabriquer une Trousse de premiers soins transportable. Il faut d’abord trouver un emplacement en pleine nature et préparer un feu de camp rudimentaire. Les instructeurs de cuisine peuvent leur apprendre à en construire un."}},faq={{q="Qui est Nurse Neela ?",a="Nurse Neela exerce la médecine à Brill, la ville des Réprouvés dans les Clairières de Tirisfal. Elle apprend aux praticiens expérimentés de First Aid à fabriquer des trousses pour les camps en pleine nature.",al={"qui est nurse neela","où se trouve nurse neela","emplacement de nurse neela"}},{q="À quoi sert une Trousse de premiers soins dans un camp ?",a="Une Trousse de premiers soins est un accessoire de camp fabriqué par les praticiens de First Aid. Dans un campement en pleine nature, elle fournit aux voyageurs de quoi soigner les blessures.",al={"qu’est-ce qu’une trousse de premiers soins","utilité d’une trousse de premiers soins","trousse de premiers soins de camp"}},{q="Pourquoi faut-il un feu de camp pour installer son camp ?",a="Un feu de camp doit être installé avant de pouvoir ajouter d’autres équipements au camp, notamment des trousses médicales. Les instructeurs de cuisine et les cuisiniers vous apprennent à construire un feu de camp rudimentaire.",al={"pourquoi faut-il un feu de camp","comment construire un feu de camp","feu de camp et cuisine"}},{q="Peut-on installer un camp en ville ?",a="Vous devez camper en pleine nature. Les habitants et les autorités locales s’opposent généralement aux tentes et aux feux au milieu des rues de la ville.",al={"peut-on camper en ville","campement à brill","pourquoi camper en pleine nature"}},{q="Qui apprend à fabriquer la Trousse de premiers soins ?",a="Nurse Neela, à Brill, apprend aux voyageurs qui remplissent les conditions à fabriquer une Trousse de premiers soins lorsqu’ils ont suffisamment de compétence en First Aid.",al={"qui enseigne les soins en campement","instructeur de soins en campement","instructeur de trousse de premiers soins"}},{q="Quel est le but de Camping 101: First Aid ?",a="Nurse Neela, à Brill, vous apprend à mettre vos compétences en médecine de terrain à profit pour préparer des fournitures médicales destinées aux camps en plein air.",al={"qu’est-ce que camping 101: first aid","quête camping 101"}}},fp="22,199,21.228.0,20.283.0,19.157.0,39.145.0,42.162.0,36.144.0,42.110.0,43.113.0"}
P.entries["quest:97956"] = {n="Camping 101: Fishing",s="À Brill, quelqu’un espère que votre talent pour la pêche égayera le camp. Clyde Kellen peut vous apprendre à fabriquer un bocal à poisson.",h="À Brill, quelqu’un espère que votre talent pour la pêche égayera le camp.",kw={"brill","camp","bases du camping","clyde kellen","bocal à poisson","pêche"},ang={["profession:Cooking"]="En tant que pêcheur, vous pouvez utiliser votre talent pour fabriquer un bocal à poisson pour votre camp."},sec={{t="Un souvenir du camp",b="Votre talent pour la pêche pourrait égayer le camp. Après avoir prouvé votre savoir-faire, parlez à Clyde Kellen, à Brill. Il peut vous apprendre à fabriquer un bocal à poisson pour le camp.\n\nLa personne qui vous confie cette tâche pense que les aventuriers joyeux se battent avec plus d’ardeur. Elle espère que le bocal à poisson apportera de la joie à vous et aux autres."}},faq={{q="Que dois-je faire ?",a="Prouvez votre savoir-faire en pêche, puis parlez à Clyde Kellen, à Brill. Il peut vous apprendre à fabriquer un bocal à poisson pour votre camp.",al={"que faire","tâche de pêche au camp"}},{q="Qui est Clyde Kellen ?",a="Clyde Kellen se trouve à Brill et peut vous apprendre à fabriquer un bocal à poisson pour votre camp.",al={"qui est clyde","clyde kellen"}},{q="À quoi sert le bocal à poisson ?",a="Le bocal à poisson est censé apporter de la joie aux autres aventuriers du camp et à vous-même.",al={"utilité du bocal à poisson","bocal à poisson du camp"}},{q="Pourquoi la pêche aiderait-elle le camp ?",a="Votre talent pour la pêche peut vous aider à fabriquer un bocal à poisson. La personne qui vous confie cette tâche espère qu’il égayera les aventuriers.",al={"à quoi sert la pêche","pourquoi pêcher au camp"}}},fp="20,122,15.273.0,28.115.0,20.76.0,25.76.0,32.95.0"}
P.entries["quest:97957"] = {n="Camping 101: Herbalism",s="Dans les Clairières de Tirisfal, Eleanor Shackleton envoie les nouveaux herboristes auprès de Faruza, à Brill, pour apprendre un métier utile. Les Bougies d’encens aident les lanceurs de sorts à se reposer dans les campements sauvages.",h="Dans les Clairières de Tirisfal, Eleanor Shackleton envoie les nouveaux herboristes auprès de Faruza, à...",kw={"brill","camping","eleanor shackleton","faruza","herboristerie","bougie d’encens","tirisfal"},ang={["class:Mage"]="En tant que mage, vous appréciez les herboristes qui fabriquent des Bougies d’encens. Leur fumée apaisante aide à retrouver concentration et moral loin des tavernes.",["profession:Herbalism"]="Les herboristes peuvent aider les groupes en voyage en fabriquant des Bougies d’encens parfumées pour leurs campements. Ils préparent aussi des potions et récoltent des tiges.",["race:Undead"]="En tant que voyageurs réprouvés venus du Glas et de Brill, vous pouvez apprendre auprès de Faruza à tirer parti des plantes flétries de Tirisfal."},sec={{t="La flore du camp",b="L’herboristerie fournit leurs premières matières premières aux alchimistes. Les voyageurs comptent aussi sur les racines et les fleurs qu’ils récoltent. Dans toutes les régions, les maîtres herboristes apprennent aux cueilleurs à préparer des Bougies d’encens. Dans les Clairières de Tirisfal, Eleanor Shackleton envoie les cueilleurs prometteurs auprès de Faruza, à Brill, dès qu’ils montrent une compétence de base."},{t="Nourrir l’esprit",b="Les longs voyages épuisent les lanceurs de sorts et les spiritualistes. Les Bougies d’encens libèrent des fragrances réparatrices qui remontent le moral et apaisent les esprits fatigués. Les cueilleurs infusent des plantes séchées dans les bougies, aidant les soigneurs et les mages dont les réserves magiques faiblissent en chemin."}},faq={{q="À quoi sert cette quête ?",a="Les herboristes développent leur compétence pour qu’un maître puisse leur apprendre à fabriquer des Bougies d’encens. Ces bougies aident les lanceurs de sorts pendant leur repos dans les campements sauvages.",al={"pourquoi faire du camping en herboriste","que permet camping 101","objectif de camping 101 : herboristerie"}},{q="Qui propose cette quête dans les Clairières de Tirisfal ?",a="Eleanor Shackleton guide les herboristes des Clairières de Tirisfal et les dirige vers Faruza, à Brill.",al={"qui donne camping 101 : herboristerie à tirisfal","quête d’eleanor shackleton"}},{q="À quoi sert une Bougie d’encens ?",a="Les Bougies d’encens remontent le moral et aident les soigneurs et les utilisateurs de magie à retrouver leur concentration pendant leur repos sur le terrain.",al={"effet de la bougie d’encens","à quoi servent les bougies d’encens"}},{q="Qui enseigne la recette de la Bougie d’encens ?",a="Les maîtres herboristes locaux enseignent la recette aux herboristes qualifiés. Dans les Clairières de Tirisfal, Faruza enseigne à Brill. Jandi enseigne à Orgrimmar, Reyna Stonebranch à Forgefer et Malorne Bladeleaf à Dolanaar.",al={"qui enseigne l’herboristerie du camping","où rendre camping 101 : herboristerie"}},{q="Les membres d’autres factions et races peuvent-ils entreprendre cette quête ?",a="Oui. Dans tout Kalimdor et les Royaumes de l'est, les guides et les maîtres enseignent aux herboristes les mêmes choses qu’Eleanor Shackleton et Faruza aux voyageurs des Clairières de Tirisfal.",al={"camping 101 est-elle réservée à la horde","camping 101 : herboristerie pour l’alliance"}},{q="Quelle compétence faut-il pour terminer l’entraînement ?",a="Les herboristes doivent avoir une compétence de vingt avant qu’un maître leur enseigne la recette de la bougie.",al={"quel niveau d’herboristerie faut-il","niveau de compétence requis pour camping 101"}}},fp="22,157,18.293.0,23.259.0,34.148.0,41.95.0,31.116.0,38.206.0,56.168.0,58.85.0"}
P.entries["quest:97958"] = {n="Camping 101: Leatherworking",s="Shelene Rhobart peut vous apprendre à fabriquer une tente si vous lui montrez votre maîtrise du travail du cuir. Elle vous abrite de la chaleur et de la pluie pendant vos voyages.",h="Shelene Rhobart peut vous apprendre à fabriquer une tente si vous lui montrez votre maîtrise du travail du...",kw={"brill","tente de campement","feu de camp","camping","cuisine","travail du cuir","shelene rhobart","tente","fossoyeuse"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre aux voyageurs à faire le feu de camp qui complète un campement."},sec={{t="Une tente de travailleur du cuir",b="Un maître des travailleurs du cuir vous oriente vers Shelene Rhobart, qui se trouve sur la route de Brill à Fossoyeuse. Elle peut vous apprendre à fabriquer un objet de camping une fois que vous avez démontré votre maîtrise du métier. Une tente peut vous garder au frais par temps chaud et au sec sous la pluie, vous permettant de vous reposer en voyage."},{t="Un lieu où camper",b="Votre tente est destinée aux étendues sauvages, car la plupart des gens n'apprécient pas les tentes dressées en plein centre-ville. Un feu de camp complète un campement, et les cuisiniers peuvent vous apprendre à en faire un. Si vous avez besoin des bases de la cuisine, cherchez quelqu'un qui puisse vous les enseigner."}},faq={{q="Qui peut m'apprendre à fabriquer une tente ?",a="Shelene Rhobart peut vous apprendre à fabriquer un objet de camping grâce au travail du cuir.",al={"maître des tentes","qui enseigne la fabrication de tentes","tente shelene"}},{q="Où se trouve Shelene Rhobart ?",a="Shelene Rhobart se trouve sur la route de Brill à Fossoyeuse.",al={"emplacement de shelene","où est shelene","route de fossoyeuse"}},{q="À quoi sert la tente ?",a="La tente peut vous garder au frais par temps chaud et au sec sous la pluie, pour vous permettre de vous reposer en voyage.",al={"utilisation de la tente","à quoi sert la tente","tente de camping"}},{q="Où dois-je dresser la tente ?",a="La tente est destinée aux étendues sauvages ; la plupart des gens n'apprécient pas les tentes dressées en plein centre-ville.",al={"où camper","tente en ville","emplacement de camping"}},{q="Ai-je besoin d'un feu de camp ?",a="Oui. Un feu de camp complète un campement, et les cuisiniers peuvent vous apprendre à en faire un.",al={"feu de camp","besoin d'un feu au camp","feu de camping"}},{q="Comment apprendre à faire un feu de camp ?",a="La plupart des cuisiniers peuvent vous apprendre à faire un feu. Si vous avez besoin des bases de la cuisine, cherchez quelqu'un qui puisse vous les enseigner.",al={"apprendre à faire un feu","maître des cuisiniers","faire un feu de camp"}}},fp="27,140,22.273.0,15.243.0,32.73.0,25.55.0,22.96.0,31.99.0,21.74.0,34.107.0"}
P.entries["quest:97959"] = {n="Camping 101: Mining",s="Vous pouvez maintenant fabriquer une lodestone et vous préparer à camper dans la nature.",h="Vous pouvez maintenant fabriquer une lodestone et vous préparer à camper dans la nature.",kw={"feu de camp","campement","cuisinier","lodestone","minage","nature"},sec={{t="Un endroit où camper",b="Vous pouvez désormais fabriquer votre propre lodestone. Essayez-la dans la nature, où les gens sont moins susceptibles de s’offusquer d’un campement. Avant de commencer, il vous faudra aussi un feu de camp. Un cuisinier peut vous apprendre à en fabriquer un."}},faq={{q="Que puis-je fabriquer maintenant ?",a="Désormais, vous pouvez fabriquer vous-même une lodestone.",al={"recette de lodestone","fabriquer une lodestone"}},{q="Où devrais-je essayer la lodestone ?",a="Partez dans la nature pour l’essayer ; la plupart des gens ne veulent pas de campement au centre-ville.",al={"où camper","essayer la lodestone"}},{q="De quoi ai-je besoin avant d’installer un campement ?",a="Il vous faut un feu de camp avant d’installer votre campement.",al={"feu de camp nécessaire","installation d’un campement"}},{q="Qui peut m’apprendre à faire un feu de camp ?",a="Un cuisinier peut vous apprendre à faire un feu de camp.",al={"apprendre à faire un feu de camp","qui apprend à faire du feu"}}},fp="19,67,15.193.0,20.47.0,33.86.0,38.46.0,36.40.0"}
P.entries["quest:97960"] = {n="Camping 101: Skinning",s="Dans les Clairières de Tirisfal, Camping 101: Skinning enseigne un métier utile aux nouveaux dépeceurs. Ils apprennent à fabriquer une chaise du camp avec des peaux récoltées et découvrent où trouver des maîtres dans tout Azeroth.",h="Dans les Clairières de Tirisfal, Camping 101: Skinning enseigne un métier utile aux nouveaux dépeceurs.",kw={"brill","chaise du camp","camping","eleanor shackleton","rand rhobart","dépeçage","clairières de tirisfal","fossoyeuse"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez utiliser chaque partie d’une bête abattue et ne rien gaspiller sur cette route difficile.",["race:Undead"]="En tant que mort-vivant, vous êtes peut-être libéré de l’épuisement des mortels, mais un camp bien aménagé reste utile lorsque vous chassez les bêtes pestiférées de Tirisfal."},sec={{t="Le confort en pleine nature",b="Une lame bien affûtée ne suffit pas pour survivre en pleine nature. Il vous faut aussi de quoi vous reposer entre les épreuves. Sur le terrain, les dépeceurs peuvent apprendre les bases et utiliser des peaux traitées pour fabriquer une chaise du camp. Elle permet aux voyageurs épuisés de reprendre des forces avant que le danger ne les rappelle."},{t="Maîtriser le métier",b="Dans les Clairières de Tirisfal, les jeunes dépeceurs réprouvés sont envoyés auprès de Rand Rhobart dès qu’ils ont acquis un peu d’expérience. Il travaille le long de la route entre Brill et les ruines de la capitale, Fossoyeuse. Rhobart leur enseigne des méthodes pratiques pour transformer le cuir brut en siège de campement. Les maîtres dépeceurs des territoires de la Horde et de l’Alliance enseignent le même métier."}},faq={{q="À quoi sert cette quête ?",a="Cette leçon envoie les nouveaux dépeceurs auprès d’un maître de métier, qui leur apprend à fabriquer une chaise du camp avec des peaux d’animaux récoltées.",al={"à quoi sert camping 101 skinning","pourquoi faire camping 101 skinning","récompense de camping 101"}},{q="Qui propose cette formation dans les Clairières de Tirisfal ?",a="Eleanor Shackleton donne cette leçon dans les Clairières de Tirisfal et dirige les nouveaux dépeceurs vers Rand Rhobart, qui se trouve sur la route entre Brill et Fossoyeuse.",al={"qui donne la quête à tirisfal","quête d’eleanor shackleton"}},{q="Quel niveau de compétence faut-il pour accomplir cette tâche ?",a="Vous devez avoir une compétence en dépeçage d’au moins vingt pour qu’un maître vous apprenne à fabriquer du matériel de campement.",al={"quel niveau de dépeçage faut-il","conditions de camping 101 skinning","compétence de dépeçage requise"}},{q="Où trouver Rand Rhobart ?",a="Rand Rhobart travaille le long de la route principale qui part au sud de Brill et mène à l’entrée de Fossoyeuse, dans les Clairières de Tirisfal.",al={"emplacement de rand rhobart","où se trouve rand rhobart","rand rhobart à tirisfal"}},{q="Les membres d’autres factions peuvent-ils apprendre cette technique ?",a="Oui. Les Réprouvés apprennent auprès de Rand Rhobart, tandis que d’autres maîtres enseignent le dépeçage au Comté-de-l’Or, à Forgefer, à Dolanaar, à Orgrimmar, à Sabot-de-Sang et à Shen’dar.",al={"quête réservée à la horde","l’alliance peut-elle faire camping 101 skinning","chaise du camp pour dépeceur de l’alliance"}},{q="À quoi sert la fabrication d’une chaise du camp ?",a="Une chaise du camp vous offre un endroit confortable où vous asseoir et reprendre des forces en pleine nature. Reposez-vous-y pour rester vigilant face aux batailles à venir.",al={"à quoi sert une chaise du camp","pourquoi fabriquer une chaise du camp"}}},fp="21,181,20.264.0,19.348.0,34.115.0,44.143.0,51.100.0,32.112.0,51.164.0,36.146.0"}
P.entries["quest:97961"] = {n="Camping 101: Tailoring",s="Un maître de couture peut vous apprendre à fabriquer une Bannière de faction pour votre camp. Bowen Brisboise vous enseigne ce savoir-faire une fois votre talent démontré.",h="Un maître de couture peut vous apprendre à fabriquer une Bannière de faction pour votre camp.",kw={"bowen brisboise","brill","feu de camp","campement","le glas","bannière de faction","rallying banner","couture"},sec={{t="Une bannière pour le camp",b="Un maître de couture vous oriente vers Bowen Brisboise, sur la route du Glas à Brill. Prouvez-lui votre talent, et il pourra vous apprendre à fabriquer une Bannière de faction pour votre camp. Une bannière peut vous aider à garder le moral sur le terrain."},{t="Établir un camp",b="Bowen Brisboise vous apprend à fabriquer une Rallying Banner. Pour l'essayer, vous devez établir votre camp en pleine nature, car la plupart des gens n'aiment pas les campements en ville. Il vous faut aussi un feu de camp, qu'un cuisinier peut vous apprendre à allumer."}},faq={{q="Qui enseigne les techniques de couture pour le campement ?",a="Bowen Brisboise peut vous apprendre à fabriquer une Bannière de faction une fois votre talent en couture démontré.",al={"qui est bowen","bowen brisboise","maître de couture"}},{q="Où trouver Bowen Brisboise ?",a="Bowen Brisboise se trouve sur la route du Glas à Brill.",al={"où est bowen","emplacement de bowen","route vers brill"}},{q="Que peut-on fabriquer pour un camp grâce à la couture ?",a="La couture permet d'apprendre à fabriquer une Bannière de faction pour votre camp.",al={"objet de couture pour le camp","fabrication de bannière","bannière de camp"}},{q="Comment s'appelle la bannière ?",a="La bannière que vous apprenez à fabriquer s'appelle Rallying Banner.",al={"rallying banner","nom de la bannière","quelle bannière"}},{q="Ai-je besoin d'un feu de camp ?",a="Oui. Il vous faut un feu de camp avant d'établir votre campement, et un cuisinier peut vous apprendre à en allumer un.",al={"feu de camp nécessaire","feu pour le camp","établir un camp"}}},fp="22,137,17.225.0,15.211.1,34.92.0,33.56.0,35.63.0,26.58.0,21.86.0"}
P.entries["quest:97963"] = {n="Camping 101: Alchemy",s="Nyassa Swiftdraught, à Shen’dar, peut vous apprendre à fabriquer un Puits de mana une fois votre savoir-faire en alchimie démontré. Le puits attire les soigneurs et les lanceurs de sorts dans un camp pour se désaltérer.",h="Nyassa Swiftdraught, à Shen’dar, peut vous apprendre à fabriquer un Puits de mana une fois votre savoir-faire...",kw={"alchimie","feu de camp","campement","soigneurs","puits de mana","nyassa swiftdraught","shen’dar","lanceurs de sorts"},ang={["profession:Cooking"]="Un cuisinier peut vous apprendre à faire le feu de camp nécessaire pour établir votre camp."},sec={{t="Un camp pour alchimistes",b="Un alchimiste peut apprendre à fabriquer un Puits de mana auprès de Nyassa Swiftdraught, à Shen’dar, une fois votre savoir-faire démontré. Les soigneurs et les lanceurs de sorts sont attirés par sa boisson rafraîchissante. Pour l’essayer au camp, il vous faut d’abord un feu de camp ; un cuisinier peut vous apprendre à en faire un."}},faq={{q="Que peut m’apprendre Nyassa ?",a="Nyassa Swiftdraught, à Shen’dar, peut vous apprendre à fabriquer un Puits de mana une fois votre savoir-faire en alchimie démontré.",al={"nyassa alchimie","puits de mana maître","campement alchimie"}},{q="À quoi sert un Puits de mana ?",a="Un Puits de mana attire les soigneurs et les lanceurs de sorts dans votre camp pour y boire une boisson rafraîchissante.",al={"puits de mana utilisation","à quoi sert le puits de mana","puits de mana"}},{q="Où apprendre à fabriquer un Puits de mana ?",a="Nyassa Swiftdraught enseigne la recette à Shen’dar.",al={"où est nyassa","shen’dar alchimie","puits de mana emplacement"}},{q="De quoi ai-je besoin avant d’installer un camp ?",a="Il vous faut un feu de camp pour établir votre camp. Un cuisinier peut vous apprendre à en faire un.",al={"feu de camp nécessaire","comment établir un camp","campement alchimie prérequis"}}},fp="20,173,21.279.0,25.118.0,25.79.0,37.59.0,38.73.0"}
P.entries["quest:97964"] = {n="Camping 101: Blacksmithing",s="En tant que forgeron, vous pouvez apprendre à fabriquer une Meule à aiguiser pour votre camp. Aedi Thriceforged, à Shen’dar, peut vous l’enseigner une fois que vous avez fait vos preuves.",h="En tant que forgeron, vous pouvez apprendre à fabriquer une Meule à aiguiser pour votre camp.",kw={"aedi thriceforged","forge","initiation au camping","voleur","meule à aiguiser","shen’dar","guerrier"},ang={["class:Rogue"]="En tant que voleur à proximité, vous pouvez affûter votre arme sur une Meule à aiguiser installée dans un camp.",["class:Warrior"]="En tant que guerrier à proximité, vous pouvez affûter votre arme sur une Meule à aiguiser installée dans un camp.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez apprendre à fabriquer une Meule à aiguiser pour votre camp."},sec={{t="La leçon d’Aedi",b="Une Meule à aiguiser permet aux guerriers et aux voleurs à proximité d’affûter leurs armes à votre camp. À Shen’dar, Aedi Thriceforged peut vous apprendre à la fabriquer une fois que vous avez fait vos preuves en forge."}},faq={{q="Qui peut m’apprendre à fabriquer une Meule à aiguiser ?",a="Aedi Thriceforged, à Shen’dar, peut vous apprendre à fabriquer une Meule à aiguiser une fois que vous avez fait vos preuves en forge.",al={"maître meule à aiguiser","qui est aedi","aedi forge"}},{q="À quoi sert une Meule à aiguiser ?",a="À votre camp, une Meule à aiguiser permet aux guerriers et aux voleurs à proximité d’affûter leurs armes.",al={"utilisation meule à aiguiser","affûter les armes","objet pour aiguiser au camp"}},{q="Où trouver Aedi Thriceforged ?",a="Aedi Thriceforged se trouve à Shen’dar.",al={"emplacement aedi","où est aedi","aedi shen’dar"}}},fp="26,165,13.196.0,42.129.0,32.84.0,34.41.0"}
P.entries["quest:97965"] = {n="Camping 101: First Aid",s="À Shen’dar, vous faites soigner vos blessures loin de la civilisation. Naleeia Tattermend apprend aux praticiens qualifiés à préparer des trousses médicales pour un camp en pleine nature.",h="À Shen’dar, vous faites soigner vos blessures loin de la civilisation.",kw={"bandages","campement","camping 101: first aid","premiers soins","trousse de premiers soins","naleeia tattermend","shen’dar","survie en pleine nature"},sec={{t="Soigner en pleine nature",b="Un voyage à travers Azeroth peut vous exposer à la violence, aux bêtes sauvages et aux dangers du terrain. Les premiers soins vous permettent de bander coupures et fractures sans dépendre uniquement de la magie. Une trousse de premiers soins dans un camp en pleine nature vous offre un endroit où soigner vos blessures et aider vos compagnons à se rétablir. Vous pouvez ensuite reprendre la route."},{t="La mentor de Shen’dar",b="À Shen’dar, Naleeia Tattermend apprend aux praticiens à confectionner du matériel médical résistant pour un campement. Elle partage ses techniques après que vous avez prouvé vos connaissances des soins de base."}},faq={{q="À qui dois-je parler pour cette quête ?",a="Parlez à Naleeia Tattermend à Shen’dar. Elle sait confectionner du matériel médical pour les camps en pleine nature.",al={"à qui parler pour les premiers soins au camp","où se trouve naleeia tattermend","rendre la quête camping 101 premiers soins"}},{q="Où se trouve Shen’dar ?",a="Shen’dar se trouve sur l’Île de Zéphras, où vit Naleeia Tattermend. Les praticiens s’y rendent pour approfondir leur formation aux premiers soins en pleine nature après avoir perfectionné leurs compétences.",al={"où se trouve shen’dar","emplacement de shen’dar","premiers soins à shen’dar"}},{q="À quoi sert la confection d’une trousse de premiers soins pour le camp ?",a="Vous apprenez à confectionner une trousse de premiers soins pour le campement d’un aventurier. Avoir des fournitures à portée de main au camp permet de soigner les blessures entre deux voyages. Elles peuvent faire la différence entre la vie et la mort.",al={"à quoi servent les premiers soins au camp","trousse de premiers soins pour le camp","pourquoi confectionner une trousse de premiers soins"}},{q="Quand Naleeia Tattermend m’apprendra-t-elle à confectionner la trousse ?",a="Naleeia Tattermend vous enseigne ces techniques après que vous avez prouvé votre maîtrise des premiers soins. Entraînez-vous à poser des bandages et à soigner les blessures avant de confectionner des trousses de campagne.",al={"quand apprendre à confectionner la trousse de premiers soins","conditions requises par naleeia tattermend","conditions requises pour camping 101 premiers soins"}},{q="Pourquoi les premiers soins sont-ils considérés comme honorables et pragmatiques ?",a="Les blessures et les traumatismes physiques menacent les voyageurs partout en Azeroth. Les bandages et les soins médicaux permettent aux voyageurs de toutes les disciplines de soigner leurs blessures et de stabiliser leurs compagnons sans dépendre uniquement de la magie.",al={"pourquoi les premiers soins sont-ils importants","histoire des premiers soins","les premiers soins sont-ils utiles"}},{q="N’importe quel aventurier peut-il confectionner une trousse de premiers soins pour le camp ?",a="Tout aventurier qui étudie les premiers soins et prouve ses compétences peut apprendre auprès de Naleeia Tattermend, à Shen’dar, à confectionner une trousse de premiers soins pour le camp.",al={"qui peut apprendre à confectionner cette trousse","qui peut confectionner une trousse de premiers soins pour le camp"}}},fp="22,166,25.300.0,30.185.0,43.112.0,34.164.0,57.180.0,55.131.0,57.199.0,49.147.0"}
P.entries["quest:97967"] = {n="Camping 101: Fishing",s="Vous découvrez comment la pêche rend les camps sauvages plus accueillants. À Shen’dar, les pêcheurs chevronnés peuvent demander à Fenn Fairweather de leur apprendre à fabriquer un Bocal à poisson.",h="Vous découvrez comment la pêche rend les camps sauvages plus accueillants.",kw={"camping","camping 101: fishing","fenn fairweather","bocal à poisson","pêche","shen’dar"},sec={{t="Le confort du foyer",b="Un campement en pleine nature a besoin de confort, en plus de lames affûtées et d’une armure robuste. Le moral aide les compagnons à supporter les épreuves de la vie sur le terrain. La pêche fournit des provisions, et les pêcheurs chevronnés peuvent mettre leur savoir-faire au service du campement. Avec des poissons vivants et une installation adaptée, un voyageur peut rendre le camp plus accueillant."},{t="L’artisan de Shen’dar",b="À Shen’dar, Fenn Fairweather partage ses secrets de pêche avec les pêcheurs chevronnés qui connaissent la patience de la canne et du moulinet. Les pêcheurs assez habiles peuvent apprendre à fabriquer un Bocal à poisson, une installation simple qui apporte joie et repos aux compagnons épuisés. Un bon moral en pleine nature aide le groupe à rester concentré et déterminé quand le danger approche."}},faq={{q="Qui enseigne à fabriquer le Bocal à poisson pour le campement ?",a="Fenn Fairweather enseigne à fabriquer le Bocal à poisson à Shen’dar. Montrez suffisamment de talent en pêche pour qu’il vous apprenne à en fabriquer un pour le camp.",al={"qui enseigne le bocal à poisson","où se trouve fenn fairweather","instructeur du bocal à poisson"}},{q="À quoi sert le Bocal à poisson au camp ?",a="Le Bocal à poisson est une installation décorative qui apporte confort et joie à vous et à vos compagnons au camp. Un camp bien entretenu et un bon moral vous aident à rester vigilants et prêts à affronter les dangers du terrain.",al={"à quoi sert le bocal à poisson","bonus du bocal à poisson","effet du bocal à poisson au camp"}},{q="Où se trouve Shen’dar ?",a="Shen’dar est un lieu de rassemblement pour les artisans et les instructeurs, dont Fenn Fairweather. Les pêcheurs s’y rendent pour apprendre des techniques pratiques de camping adaptées à leurs talents.",al={"où se trouve shen’dar","emplacement de shen’dar"}},{q="Quelle compétence faut-il pour apprendre cette technique de camping ?",a="Vous devez montrer que vous maîtrisez les bases de la pêche avant d’apprendre cette technique. Une fois votre savoir-faire bien aiguisé, les instructeurs de Shen’dar peuvent vous apprendre à fabriquer des installations de camp, comme le Bocal à poisson.",al={"conditions pour la pêche en camping","quand apprendre le bocal à poisson","comment commencer la pêche en camping"}},{q="Pourquoi la pêche est-elle utile pour camper en pleine nature ?",a="La pêche fournit de la nourriture, et la patience ainsi que l’œil aiguisé d’un pêcheur peuvent aussi améliorer la vie au camp. Une prise fraîche exposée dans un bocal fabriqué à cet effet apaise et remonte le moral au cours des longues expéditions en pleine nature.",al={"pourquoi pêcher en camping","utilité de la pêche au camp"}},{q="Qui est Fenn Fairweather ?",a="Fenn Fairweather est un artisan et un instructeur de Shen’dar. Il connaît les petits conforts de la vie en pleine nature et enseigne aux pêcheurs chevronnés à fabriquer des installations de camp.",al={"qui est fenn fairweather","histoire de fenn fairweather"}}},fp="20,167,22.316.0,23.331.0,40.140.0,44.190.0,26.172.0,51.193.0,47.194.0,24.171.0"}
P.entries["quest:97968"] = {n="Camping 101: Herbalism",s="Dans les campements le long du sentier, Camping 101: Herbalism oriente les cueilleurs vers des instructeurs qui leur apprennent à fabriquer des Bougies d’encens. Les herboristes utilisent les plantes récoltées pour réconforter les lanceurs de sorts et les soigneurs au cours de longs périples.",h="Dans les campements le long du sentier, Camping 101: Herbalism oriente les cueilleurs vers des instructeurs...",kw={"camp","camping","camping 101: herbalism","soigneurs","herboristerie","herbes","bougie d’encens","lanceurs de sorts"},ang={["class:Mage"]="Les lanceurs de sorts qui dépensent leur concentration au combat apprécient l’encens de camp, dont le parfum apaisant aide à restaurer leur esprit et favorise la récupération des arcanes.",["class:Priest"]="Les Bougies d’encens allumées au camp remontent le moral et reconstituent les réserves mentales des soigneurs du Sacré entre les escarmouches.",["profession:Herbalism"]="La cueillette de plantes dans la nature fournit les herbes aromatiques nécessaires à l’encens de camp. Ce travail est donc utile à la survie comme à l’alchimie."},sec={{t="La flore sauvage du sentier",b="Les voyageurs peuvent tirer parti des racines et des pétales autrement qu’en vendant des tiges fraîches ou en préparant des décoctions. Les cueilleurs rencontrent des instructeurs qui leur apprennent à fabriquer des Bougies d’encens à partir de plantes sauvages aromatiques. Ces bougies soutiennent leurs compagnons sur le sentier."},{t="Apaiser l’esprit",b="Les longs périples en territoire hostile épuisent les soigneurs et les lanceurs de sorts. Dans un campement actif, une Bougie d’encens diffuse un parfum apaisant et revitalisant qui leur remonte le moral et les aide à retrouver lucidité et vigueur avant que le danger ne les rappelle. Ceux qui manient la magie ou soignent les blessés apprécient tout particulièrement ce réconfort."}},faq={{q="Qu’est-ce que Camping 101: Herbalism ?",a="Camping 101: Herbalism met les cueilleurs chevronnés en contact avec des instructeurs qui leur apprennent à fabriquer des Bougies d’encens pour les campements en pleine nature.",al={"qu’est-ce que camping 101 herbalism","quête camping 101 herbalism","quête d’herboristerie au camp"}},{q="À quoi sert une Bougie d’encens ?",a="Une Bougie d’encens est fabriquée à partir de plantes récoltées et brûlée dans un campement. Son parfum apaisant et revitalisant remonte le moral des compagnons qui se reposent et procure un bienfait aux soigneurs et aux lanceurs de sorts.",al={"à quoi sert une bougie d’encens","effet d’une bougie d’encens au camp","pourquoi fabriquer une bougie d’encens"}},{q="Qui apprend à fabriquer une Bougie d’encens ?",a="Votre instructeur dépend de votre lieu de départ : Reyna Stonebranch à Forgefer, Malorne Bladeleaf à Dolanaar, Herbalist Pomeroy dans la Forêt d’Elwynn, Jandi à Orgrimmar, Faruza à Brill, Komin Winterhoof aux Pitons-du-Tonnerre, ou à Shen’dar, sur l’Île de Zéphras.",al={"qui apprend à fabriquer une bougie d’encens","instructeur de bougie d’encens","où apprendre à fabriquer une bougie d’encens"}},{q="Pourquoi les Bougies d’encens sont-elles particulièrement utiles aux utilisateurs de magie ?",a="Lancer des sorts et soigner les blessures épuisent l’énergie physique et la concentration mentale. La fumée apaisante d’une Bougie d’encens aide à reconstituer les deux, en maintenant le moral et en préparant les lanceurs de sorts au combat.",al={"pourquoi les lanceurs de sorts ont-ils besoin d’encens","bougie d’encens pour les soigneurs","bougie d’encens pour les utilisateurs de magie"}},{q="Faut-il être herboriste pour entreprendre cette quête ?",a="Cet enseignement s’adresse à ceux qui savent récolter des plantes et des herbes. Il apprend à trouver et à utiliser les plantes sauvages aromatiques.",al={"tout le monde peut-il apprendre à fabriquer une bougie d’encens","faut-il connaître l’herboristerie pour camping 101 herbalism","condition d’herboristerie pour la bougie de camp"}},{q="Quel est le lien entre l’Herboristerie et le camping ?",a="Les plantes récoltées ont d’autres usages au camp que la préparation de concoctions et d’onguents. Elles peuvent être transformées en encens qui revigore les compagnons épuisés.",al={"l’herboristerie sert-elle uniquement aux potions","usages des herbes au camp","objets d’herboristerie pour le camp"}}},fp="22,218,23.229.0,17.318.0,31.132.0,35.196.0,42.254.0,58.186.0,50.121.0,36.139.0"}
P.entries["quest:97969"] = {n="Camping 101: Leatherworking",s="Les voyages d’un travailleur du cuir lui apprennent à fabriquer un abri pour la nature. À Shen’dar, Indari Sunseam enseigne aux artisans chevronnés à coudre des tentes qui protègent les voyageurs et leur offrent du repos pendant les longs trajets.",h="Les voyages d’un travailleur du cuir lui apprennent à fabriquer un abri pour la nature.",kw={"tente de camping","feu de camp","camping","cuisine","indari sunseam","travail du cuir","shen’dar","tente","nature"},ang={["profession:Cooking"]="Une tente ne suffit pas à faire un campement complet. Vous devez aussi apprendre les bases du feu de camp, généralement auprès d’un maître cuisinier."},sec={{t="Un abri sur la route",b="Les travailleurs du cuir itinérants ont besoin d’un équipement solide, fait de cuir et de peaux. Une fois leur métier appris, ils sont envoyés auprès d’Indari Sunseam, à Shen’dar. Elle leur apprend à fabriquer une véritable tente de camping. Celle-ci protège les voyageurs des fortes pluies et de la chaleur d’un soleil ardent, et les aide à se reposer pendant les longs trajets."},{t="Campements sauvages",b="Les habitants n’apprécient pas que des campements rudimentaires encombrent leurs rues. Vous devez donc planter votre tente dans la nature. Un campement a besoin de plus qu’un abri : il lui faut aussi un feu de camp réconfortant. Rendez visite à un cuisinier local pour apprendre les bases de l’allumage d’un feu avant de partir."}},faq={{q="Qui apprend aux travailleurs du cuir à fabriquer une tente ?",a="Indari Sunseam, à Shen’dar, apprend aux travailleurs du cuir chevronnés à fabriquer des tentes de camping.",al={"qui enseigne à fabriquer des tentes en travail du cuir","maître des tentes de camping","où se trouve indari sunseam"}},{q="À quoi sert la fabrication d’une tente ?",a="Une tente bien conçue protège les voyageurs des fortes pluies et de la chaleur accablante, les aidant à se reposer et à rester vigilants sur la route.",al={"à quoi sert une tente","utilité d’une tente","avantages d’une tente"}},{q="Où peut-on planter une tente de camping ?",a="Vous plantez votre tente dans la nature, loin des centres-villes où les habitants n’apprécient pas les campements.",al={"peut-on planter une tente en ville","où utiliser une tente","règles de campement"}},{q="De quoi d’autre a-t-on besoin pour établir un vrai campement ?",a="Un vrai campement a aussi besoin d’un feu de camp. Un maître cuisinier peut vous apprendre à allumer un feu simple.",al={"faut-il un feu","conditions pour camper","que faut-il d’autre pour camper"}},{q="Quand Indari Sunseam vous apprend-elle le patron de la tente ?",a="Indari Sunseam vous apprend le patron de la tente après que vous avez pratiqué le travail du cuir et fait preuve de compétence dans ce métier.",al={"quand apprendre à fabriquer une tente","conditions pour fabriquer une tente","conditions pour la tente en travail du cuir"}},{q="Qu’est-ce que Shen’dar ?",a="Shen’dar est le lieu où vit et travaille Indari Sunseam. Elle y apprend aux voyageurs à fabriquer du matériel de camping.",al={"où se trouve shen’dar","emplacement de shen’dar","ville d’indari sunseam"}}},fp="27,216,19.306.0,20.227.0,47.88.0,39.114.0,36.88.0,43.91.0,52.115.0,25.103.0"}
P.entries["quest:97970"] = {n="Camping 101: Mining",s="Un maître des mineurs à Shen’dar peut vous apprendre à fabriquer un Lodestone pour votre camp. Il renforce au combat ceux qui se rassemblent autour du feu.",h="Un maître des mineurs à Shen’dar peut vous apprendre à fabriquer un Lodestone pour votre camp.",kw={"camp","feu de camp","camping 101","lodestone","messana crestwind","minage","shen’dar"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez apprendre aux autres à faire le feu de camp nécessaire pour installer leur camp.",["profession:Mining"]="En tant que mineur, vous pouvez démontrer votre maîtrise à Messana Crestwind et apprendre à fabriquer un Lodestone pour votre camp."},sec={{t="Le savoir-faire du mineur",b="Le minage est un travail honnête, et Messana Crestwind peut vous enseigner une technique de campement à Shen’dar. Une fois que vous aurez démontré votre maîtrise du minage, elle pourra vous apprendre à fabriquer un Lodestone. Ceux qui se rassemblent autour de votre feu peuvent y puiser une force supplémentaire : ce savoir-faire pourrait donc attirer des combattants armés d’épées dans votre camp."},{t="Un endroit où camper",b="Une fois cette technique apprise, vous pourrez fabriquer votre propre Lodestone. Les camps sont malvenus au centre-ville : emportez-le donc en pleine nature pour le mettre à l’essai. Un feu de camp est nécessaire avant d’installer votre camp, et un cuisinier peut vous apprendre à en faire un."}},faq={{q="Qui peut m’apprendre à fabriquer un Lodestone ?",a="Messana Crestwind, à Shen’dar, peut vous apprendre à fabriquer un Lodestone une fois que vous aurez démontré votre maîtrise du minage.",al={"maître lodestone","qui enseigne la technique de campement du minage"}},{q="À quoi sert un Lodestone ?",a="Il renforce au combat ceux qui se rassemblent autour de votre feu de camp.",al={"utilisation du lodestone","à quoi sert le lodestone"}},{q="Où puis-je mettre mon Lodestone à l’essai ?",a="Vous pouvez le mettre à l’essai en pleine nature ; les camps sont malvenus au centre-ville.",al={"où essayer le lodestone","lodestone de camp"}},{q="Ai-je besoin d’un feu de camp ?",a="Oui. Vous avez besoin d’un feu de camp avant d’installer votre camp, et un cuisinier peut vous apprendre à en faire un.",al={"feu de camp nécessaire","comment installer un camp"}},{q="Que me faut-il avant que Messana puisse m’enseigner cette technique ?",a="Vous devez démontrer votre maîtrise du minage avant que Messana Crestwind puisse vous apprendre à fabriquer un Lodestone.",al={"maîtrise du minage","comment apprendre à fabriquer un lodestone"}}},fp="19,155,15.305.0,15.229.0,35.110.0,25.70.0,30.77.0,21.86.0,41.99.0"}
P.entries["quest:97971"] = {n="Camping 101: Skinning",s="À Shen’dar, Mendalass Tattermend apprend aux dépeceurs à se préparer au repos en pleine nature. Cette leçon associe le dépeçage à la survie et à un siège pour le campement.",h="À Shen’dar, Mendalass Tattermend apprend aux dépeceurs à se préparer au repos en pleine nature.",kw={"chaise du camp","feu de camp","camping 101","peaux","mendalass tattermend","shen’dar","dépeçage","terres sauvages"},ang={["profession:Cooking"]="La cuisine et la survie en pleine nature vont de pair. Un campement a besoin d’un feu de camp, une compétence traditionnellement enseignée par les maîtres cuisiniers."},sec={{t="Le confort en pleine nature",b="Vous pouvez façonner les peaux des bêtes tombées au combat pour en faire bien plus que des armures. Mendalass Tattermend vous montre comment fabriquer une Chaise du camp transportable, pour vous reposer en pleine nature et reprendre des forces avant la bataille."},{t="Les enseignements de Shen’dar",b="À Shen’dar, Mendalass Tattermend apprend aux dépeceurs chevronnés à fabriquer des sièges solides avec les peaux récoltées. Les villes interdisent les campements dans leurs limites. Un campement a aussi besoin d’un feu de camp, une compétence traditionnellement enseignée par les maîtres cuisiniers locaux."}},faq={{q="De quoi parle Camping 101: Skinning ?",a="À Shen’dar, Mendalass Tattermend apprend aux dépeceurs à fabriquer une Chaise du camp à partir des peaux prélevées. Elle vous offre un endroit où vous reposer en campant en pleine nature.",al={"de quoi parle cette quête","but de camping 101","pourquoi faire cette quête"}},{q="Qui est Mendalass Tattermend ?",a="Mendalass Tattermend est un maître du dépeçage à Shen’dar. Il apprend aux dépeceurs expérimentés à fabriquer un siège de terrain avec les peaux récoltées.",al={"qui est mendalass","qui apprend à fabriquer la chaise du camp","mendalass tattermend"}},{q="Où trouver Mendalass Tattermend ?",a="Mendalass Tattermend se trouve à Shen’dar, où les dépeceurs peuvent démontrer leur savoir-faire et apprendre à fabriquer du matériel de campement.",al={"où se trouve mendalass","où se trouve shen’dar","où rendre cette quête"}},{q="Quel objet cette quête vous apprend-elle à fabriquer ?",a="Les dépeceurs apprennent à fabriquer une Chaise du camp avec les peaux prélevées sur les bêtes tombées au combat. Elle vous offre un endroit où vous reposer en pleine nature.",al={"que fabriquent les dépeceurs","patron de la chaise du camp","quel objet reçoit-on"}},{q="Peut-on camper dans une ville ?",a="Non. Les villes interdisent les campements dans leurs limites : les campements et les chaises sont donc réservés aux terres sauvages.",al={"peut-on camper en ville","où installer son campement","où utiliser la chaise du camp"}},{q="De quoi d’autre a-t-on besoin pour établir un vrai campement ?",a="Un vrai campement a besoin d’un feu de camp. Les maîtres cuisiniers enseignent traditionnellement les rudiments nécessaires pour en allumer un.",al={"de quoi d’autre ai-je besoin pour camper","feu de camp nécessaire","conditions pour camper"}}},fp="21,162,20.195.0,33.244.0,36.158.0,28.147.0,40.109.0,44.118.0,34.89.0,44.101.0"}
P.entries["quest:97972"] = {n="Camping 101: Tailoring",s="Un couturier peut apprendre à fabriquer une Bannière de faction pour votre camp. Vous devez prouver votre maîtrise de la couture avant que Taleen Shimmerthread puisse vous l’enseigner.",h="Un couturier peut apprendre à fabriquer une Bannière de faction pour votre camp.",kw={"camping","bannière de faction","métier","shen’dar","couture","taleen shimmerthread"},ang={["profession:Tailoring"]="En tant que couturier, vous pouvez apprendre à confectionner une Bannière de faction pour votre camp après avoir prouvé votre maîtrise du métier."},sec={{t="Une bannière pour le camp",b="Quelqu’un à Shen’dar peut vous apprendre à fabriquer une Bannière de faction. Taleen Shimmerthread peut vous montrer comment confectionner cet objet de camping une fois que vous aurez prouvé votre maîtrise de la couture. Une bannière inspirante peut vous aider à garder votre énergie sur le champ de bataille."}},faq={{q="Qui peut m’apprendre à fabriquer une Bannière de faction ?",a="Taleen Shimmerthread, à Shen’dar, peut vous apprendre à confectionner une Bannière de faction pour votre camp une fois que vous aurez prouvé votre maîtrise de la couture.",al={"maître des bannières","qui enseigne la confection de bannières","bannière de taleen"}},{q="À quoi sert la Bannière de faction ?",a="La Bannière de faction est un objet de camping. Une bannière inspirante peut vous aider à garder votre énergie sur le champ de bataille.",al={"utilité de la bannière","pourquoi fabriquer une bannière","bannière de camp"}},{q="Que me faut-il avant que Taleen puisse m’enseigner ?",a="Vous devez prouver votre maîtrise de la couture avant que Taleen Shimmerthread puisse vous apprendre à confectionner la Bannière de faction.",al={"prérequis en couture","niveau requis pour la bannière","compétence pour la bannière"}}},fp="22,143,17.250.0,42.134.0,31.109.0,42.112.0"}
P.entries["quest:97973"] = {n="Camping 101: Tailoring",s="À Shen’dar, les couturiers peuvent apprendre à fabriquer une Bannière de faction pour les campements en pleine nature. Elle remonte le moral et aide à le maintenir.",h="À Shen’dar, les couturiers peuvent apprendre à fabriquer une Bannière de faction pour les campements en...",kw={"bannière de camp","campement","camping 101: tailoring","bannière de faction","shen’dar","couture","taleen shimmerthread","métier"},ang={["profession:Tailoring"]="En tant que couturier, vous pouvez fabriquer des Bannières de faction qui remontent le moral au camp et donnent de l’énergie aux alliés sur le terrain."},sec={{t="La contribution de The Weaver au camp",b="Un campement en pleine nature exige plus que des vêtements chauds. Une bannière bien confectionnée peut donner un but commun au camp. Les artisans du tissu sont donc encouragés à exercer leur métier au-delà des vêtements et des sacs. Avec une formation plus poussée, les étoffes tissées deviennent un symbole d’unité et de force d’âme."},{t="Formation à Shen’dar",b="À Shen’dar, Taleen Shimmerthread enseigne les techniques de campement aux couturiers assez habiles. Elle leur montre comment confectionner une Bannière de faction. Cousue avec soin et plantée au camp, elle rassemble les alliés et leur remonte le moral face aux épreuves à venir."}},faq={{q="Qu’est-ce que Camping 101: Tailoring ?",a="À Shen’dar, les couturiers prometteurs peuvent se former aux techniques de terrain. Montrez suffisamment d’habileté en couture pour apprendre à fabriquer une Bannière de faction destinée à un campement en pleine nature.",al={"quelle est cette quête","quête camping 101 couture","bannière de camp en couture"}},{q="Qui est Taleen Shimmerthread ?",a="Taleen Shimmerthread est une couturière chevronnée de Shen’dar. Elle apprend aux artisans qualifiés à fabriquer des objets de campement, notamment des bannières qui remontent le moral.",al={"taleen shimmerthread","qui enseigne à fabriquer une bannière en couture","où se trouve taleen shimmerthread"}},{q="Où se trouve Shen’dar ?",a="Taleen Shimmerthread vit à Shen’dar. Les couturiers s’y rendent pour apprendre à mettre leur savoir-faire au service de l’équipement de campement.",al={"où se trouve shen’dar","emplacement de shen’dar"}},{q="Quel objet de campement les couturiers peuvent-ils apprendre à fabriquer ?",a="Les couturiers peuvent apprendre à fabriquer une Bannière de faction pour le camp. Plantée sur place, elle inspire ceux qui s’y reposent.",al={"bannière de faction pour le campement","que fabrique-t-on pour le camp en couture","objet de campement en couture"}},{q="Quelles sont les conditions pour apprendre à fabriquer la bannière de campement ?",a="Vous devez démontrer vos talents de couturier à Taleen Shimmerthread, à Shen’dar, avant qu’elle vous apprenne à fabriquer une Bannière de faction pour le camp.",al={"comment apprendre à fabriquer une bannière de faction","conditions pour apprendre la bannière de campement en couture"}},{q="Pourquoi les bannières de faction sont-elles précieuses au camp ?",a="Les bannières de faction remontent le moral et le maintiennent pendant une campagne. Les couturiers les confectionnent pour offrir un point de ralliement stimulant aux aventuriers lors de longs périples éprouvants.",al={"pourquoi fabriquer une bannière de faction","moral et bannière de campement"}}},fp="22,136,33.268.0,31.258.0,31.176.0,28.160.0,26.138.0,45.114.0,54.133.0,41.149.0"}
P.entries["quest:97977"] = {n="Nature's Call",s="À Sombrevallon, Tarindrella cherche la cause de l’hostilité soudaine des Gnarlpine. Leurs totems sculptés pourraient révéler pourquoi ils se sont retournés contre leurs alliés elfes de la nuit de longue date.",h="À Sombrevallon, Tarindrella cherche la cause de l’hostilité soudaine des Gnarlpine.",kw={"furbolg","gnarlpine","grell","grellkin","nature's call","cauchemars","sombrevallon","tarindrella","teldrassil","totem"},ang={["class:Druid"]="En tant que druide, vous êtes en harmonie avec l’équilibre de la nature et la corruption spirituelle qui affecte les créatures de Kalimdor. Les totems des furbolgs touchés par les cauchemars sont alarmants.",["faction:Alliance"]="En tant que membre de l’Alliance, vous contribuez à protéger les frondaisons de Teldrassil et à maintenir vos nouveaux alliés elfes de la nuit sur Kalimdor.",["race:NightElf"]="En tant qu’elfe de la nuit, voir les Gnarlpine, autrefois des compagnons de longue date, sombrer dans l’hostilité et la folie est une tragédie personnelle pour les défenseurs de Teldrassil."},sec={{t="Enquête dans le vallon",b="La dryade Tarindrella vous demande de fouiller les camps le long de la frontière occidentale de Sombrevallon. Les furbolgs Gnarlpine les ont quittés à la hâte, et elle ne peut croire qu’ils aient renoncé sans raison à des siècles d’amitié avec les elfes de la nuit. Rapportez des totems gravés intacts. Leurs motifs pourraient révéler ce qui a changé."},{t="L’ombre et le cauchemar",b="Les totems des Gnarlpine racontent des cauchemars où une ombre envahissante menaçait d’anéantir leur tribu. La peur s’est muée en rage aveugle et a déformé leur esprit. Ils ont fini par voir en leurs voisins elfes de longue date l’ombre même qu’ils redoutaient. Tarindrella espère que leur histoire éclairera le mal plus profond qui s’insinue dans Teldrassil."}},faq={{q="Qui donne la quête Nature's Call ?",a="Tarindrella, une dryade, veille sur Sombrevallon, en Teldrassil. Alarmée par l’hostilité soudaine des furbolgs Gnarlpine, elle vous demande de récupérer des reliques dans leurs camps et de découvrir la cause de leur folie.",al={"qui donne nature's call","qui est tarindrella","emplacement de tarindrella"}},{q="Pourquoi les furbolgs Gnarlpine sont-ils devenus hostiles ?",a="Les furbolgs Gnarlpine faisaient des cauchemars où une ombre menaçante cherchait à les détruire. L’effroi s’est mué en paranoïa et en fureur, jusqu’à ce qu’ils voient leurs alliés elfes de la nuit de longue date comme des ennemis.",al={"pourquoi les gnarlpine attaquent","pourquoi les gnarlpine sont fous","qu’est-il arrivé aux furbolgs gnarlpine"}},{q="Où se trouvent les totems des Gnarlpine ?",a="De petits totems des Gnarlpine se trouvent dans des camps de furbolgs abandonnés, le long de la bordure ouest du vallon. Des Grell et des grellkin qui fouillent les ruines en ont dispersé certains dans les environs.",al={"où sont les totems des gnarlpine","trouver les totems des gnarlpine","emplacement du camp des gnarlpine"}},{q="Pourquoi les joueurs ne peuvent-ils pas récupérer les grands totems des camps ?",a="Tarindrella vous conseille de laisser les grands totems dans les camps. Elle dit qu’en tant que dryade, elle ne saurait quoi faire de ces sculptures encombrantes et qu’elle préfère les petits totems gravés, faciles à transporter.",al={"pourquoi ignorer les grands totems","peut-on récupérer les grands totems","grand totem des gnarlpine"}},{q="Qui sont les furbolgs Gnarlpine ?",a="Les Gnarlpine sont une tribu de furbolgs originaire de Teldrassil. Ils vivaient en paix aux côtés des elfes de la nuit, mais des cauchemars insidieux les ont récemment changés en adversaires agressifs.",al={"qui sont les gnarlpine","histoire des gnarlpine","les gnarlpine sont-ils mauvais"}},{q="Quelle est la grande ombre mentionnée dans les totems ?",a="Les totems évoquent une Grande Ombre invisible qui hante les rêves des furbolgs. Son origine reste inconnue, et Tarindrella espère que leur destin aidera à découvrir la corruption plus vaste qui afflige Teldrassil.",al={"quelle ombre chez les gnarlpine","quelle est l’ombre de teldrassil","cauchemars en teldrassil"}}},fp="13,165,22.302.0,28.327.1,34.198.0,44.192.0,39.181.0,57.209.0,30.176.0,49.198.0"}
P.entries["quest:97979"] = {n="The Goddess Provides",s="Sous Teldrassil, les jeunes elfes de la nuit apprennent à reconnaître les dons d’Élune.",h="Sous Teldrassil, les jeunes elfes de la nuit apprennent à reconnaître les dons d’Élune.",kw={"élune","the goddess provides","hyjal","kaldorei","longue veille","mère-lune","camouflage dans l’ombre","teldrassil"},ang={["class:Priest"]="En tant que prêtre kaldorei, vous vous consacrez à la Mère-Lune et canalisez la grâce d’Élune sous forme d’éclat qui vous guide et de protection divine.",["faction:Alliance"]="Après la bataille du Mont Hyjal, les elfes de la nuit mirent fin à leur long isolement et rejoignirent l’Alliance. Vous mettez les pouvoirs lunaires de votre peuple au service de la défense mutuelle.",["race:NightElf"]="En tant qu’elfe de la nuit, vous héritez des bénédictions d’Élune : la lumière lunaire révèle les chemins cachés et les ombres dissimulent votre présence."},sec={{t="Une veille achevée",b="Pendant des millénaires après la Fracture, les kaldorei vécurent à l’écart des autres peuples. Durant la Longue Veille, ils veillèrent sur Kalimdor et gardèrent les sommets sacrés du Mont Hyjal. La Troisième guerre apporta la dévastation, et la défense de l’Arbre-monde mit fin à leur ancien isolement.\n\nÀ présent, les elfes de la nuit vivent sous les branches de Teldrassil et font face à un monde inconnu. Ils tendent la main par-delà l’océan pour nouer des alliances et prendre leur place parmi les peuples d’Azeroth."},{t="Bénédictions de la Mère-Lune",b="Élune, la Mère-Lune, reste au cœur de la foi kaldorei, même si les elfes de la nuit vivent désormais dans un nouveau foyer et nouent de nouveaux liens. Dès leurs premiers jours, ils apprennent à invoquer ses dons. Son éclat guide leurs frappes et éclaire leur dessein. Son ombre les dissimule aux yeux de leurs ennemis.\n\nCes bénédictions héritées lient les kaldorei à leur déesse et les préparent aux dangers qui les attendent au-delà du Grand Arbre."}},faq={{q="Qu’est-ce que The Goddess Provides ?",a="Les jeunes elfes de la nuit apprennent à reconnaître et à manifester les bénédictions d’Élune lors d’un rite sous les branches de Teldrassil.",al={"qu’est-ce que the goddess provides","quête the goddess provides"}},{q="Quelle est la déesse mentionnée dans cette quête ?",a="Il s’agit d’Élune, que les kaldorei appellent la Mère-Lune. Elle est au cœur de la culture et de la vie spirituelle des elfes de la nuit, qui croient qu’elle accorde à ses enfants protection, clarté et discrétion.",al={"qui est la déesse","qui est la mère-lune","déesse des elfes de la nuit"}},{q="Quels dons Élune accorde-t-elle aux kaldorei ?",a="Élune accorde un éclat qui guide les frappes des guerriers, ainsi que le pouvoir de se fondre dans les ombres environnantes.",al={"quels dons élune accorde-t-elle","capacités raciales d’élune","pouvoirs d’élune"}},{q="Qu’était la Longue Veille ?",a="La Longue Veille désigne les milliers d’années durant lesquelles les elfes de la nuit gardèrent Kalimdor dans l’isolement. Elle prit fin après qu’ils eurent défendu le Mont Hyjal contre la Légion ardente, puis les kaldorei ouvrirent leurs frontières.",al={"qu’était la longue veille","pourquoi la longue veille a-t-elle pris fin"}},{q="Pourquoi les elfes de la nuit ont-ils rejoint l’Alliance ?",a="Après avoir défendu le Mont Hyjal, les elfes de la nuit mirent fin à leur long isolement et choisirent de nouer des liens avec les races mortelles de l’autre côté de la mer. Ils rejoignirent Grand Alliance pour assurer leur survie mutuelle et nouer des liens d’amitié.",al={"pourquoi les elfes de la nuit ont-ils rejoint l’alliance","kaldorei et alliance"}},{q="Où se déroule cet enseignement ?",a="Teldrassil est un Grand Arbre au large de la côte nord de Kalimdor. Après la Troisième guerre, ses branches abritées devinrent le nouveau foyer et le sanctuaire des elfes de la nuit.",al={"où se trouve teldrassil","qu’est-ce que teldrassil"}}},fp="20,177,17.451.0,24.405.0,29.113.0,44.188.0,46.104.0,24.206.0,45.197.0,39.151.0"}
P.entries["quest:97985"] = {n="Thundering Hearts",s="Dans les Mille pointes, le chercheur veut le cœur immense de Stormheart pour créer une abomination.",h="Dans les Mille pointes, le chercheur veut le cœur immense de Stormheart pour créer une abomination.",kw={"abomination","création","cœur","stormheart","mille pointes","lézard-tonnerre","thundering hearts"},sec={{t="Un cœur immense",b="Un chercheur qui étudie la création des abominations pense que ses travaux nécessitent un cœur immense. Stormheart, un lézard-tonnerre qui patrouillerait au bord du canyon des Mille pointes, semble assez grand. Mais Stormheart n’est pas docile."},{t="Le cœur",b="Le cœur de Stormheart est encore parcouru d’impulsions électriques. Le chercheur dit qu’il semble avoir la taille indiquée dans ses notes et qu’il sera ajouté à l’abomination."}},faq={{q="Qui veut le cœur de Stormheart ?",a="Un chercheur qui étudie la création des abominations veut le cœur de Stormheart pour créer une abomination.",al={"qui a besoin du cœur","chercheur en abominations","qui m’a envoyé"}},{q="Où se trouve Stormheart ?",a="Stormheart patrouille au bord du canyon des Mille pointes.",al={"emplacement de stormheart","où est le lézard-tonnerre","où se trouve stormheart"}},{q="Qu’est-ce que Stormheart ?",a="Stormheart est un lézard-tonnerre d’une taille impressionnante.",al={"créature stormheart","grand lézard","lézard-tonnerre"}},{q="Pourquoi faut-il un cœur ?",a="D’après les notes du chercheur, la création d’une abomination nécessite un cœur immense.",al={"pourquoi un cœur","cœur d’abomination","à quoi sert le cœur"}},{q="Que sait le chercheur sur le cœur ?",a="Le chercheur dit que le cœur est encore parcouru d’impulsions électriques et semble avoir la taille indiquée dans ses notes.",al={"détails sur le cœur","cœur électrique","qu’a-t-il de spécial"}}},fp="17,98,13.218.0,9.163.1,31.89.0,20.61.0,19.50.0,22.75.0,46.115.0"}
P.entries["quest:98"] = {n="The Legend of Stalvan",s="Le pressentiment de Madame Eva annonce une menace contre Sombre-Comté : Stalvan Mantebrume, un tueur porteur d’une bague de famille. Vous devez l’affronter et lui rapporter la bague.",h="Le pressentiment de Madame Eva annonce une menace contre Sombre-Comté : Stalvan Mantebrume, un tueur porteur...",kw={"cottage","sombre-comté","bois de la pénombre","bague de famille","madame eva","stalvan","stalvan mantebrume"},sec={{t="Une menace contre Sombre-Comté",b="Le pressentiment de Madame Eva vous a mené à Stalvan Mantebrume, dont les crimes terrorisent Sombre-Comté. On dit qu’il menace la ville depuis son cottage, juste au nord. Vous devez mettre fin à ce danger et rapporter sa bague de famille à Madame Eva."}},faq={{q="Qui est Stalvan Mantebrume ?",a="Stalvan Mantebrume est décrit comme un tueur responsable de nombreux crimes, qui menace Sombre-Comté.",al={"stalvan","qui est stalvan","histoire de stalvan"}},{q="Pourquoi Madame Eva m’envoie-t-elle traquer Stalvan ?",a="Le pressentiment de Madame Eva a révélé la menace que Stalvan fait peser sur Sombre-Comté.",al={"pourquoi stalvan","eva et stalvan","pourquoi tuer stalvan"}},{q="Où se trouve le cottage de Stalvan ?",a="Le cottage de Stalvan se trouve juste au nord de Sombre-Comté.",al={"cottage de stalvan","où est stalvan","emplacement du cottage"}},{q="Que me demande Madame Eva de rapporter ?",a="Elle vous demande de lui montrer la bague de famille de Stalvan.",al={"bague de famille","bague de stalvan","quoi rapporter à eva"}},{q="Que s’est-il passé après la mort de Stalvan ?",a="Madame Eva affirme que Stalvan est mort et que le Bois de la Pénombre est libéré de sa soif de sang.",al={"fin de stalvan","stalvan est-il mort","qu’est-il arrivé à stalvan"}},{q="Pourquoi Madame Eva est-elle heureuse ?",a="Elle a senti l’espoir se répandre dans la forêt corrompue après la mort de Stalvan, même si elle pleure ses victimes.",al={"eva heureuse","pourquoi eva est-elle heureuse","réaction de madame eva"}}},fp="21,167,21.254.0,26.100.0,42.84.0,27.45.0,42.47.0,39.80.0,23.108.0"}
